local P = LoreForeverPacks.Begin("LoreForever_Lang_roRO")
P.entries["quest:1046"] = {n="Raene's Cleansing",s="Aceasta misiune marcheaza ultimul capitol al cautarii menite sa descopere ce i s-a intamplat lui Teronis si sa opreasca amenintarea furbolg care planeaza asupra Ashenvale. Purtand craniul lui Ran Bloodtooth, luat de la Krolg, un aventurier se intoarce la Sentinel Raene Wolfrunner, in Astranaar, pentru a relata deznodamantul calatoriei sale primejdioase.",h="Aceasta misiune marcheaza ultimul capitol al cautarii menite sa descopere ce i s-a intamplat lui Teronis si...",kw={"Ashenvale","Astranaar","toiagul lui Dartol","furbolg","Krolg","Raene Wolfrunner","Raene's Cleansing","Ran Bloodtooth","Teronis"},ang={["faction:Alliance"]="Predarea craniului lui Bloodtooth intareste angajamentul Alliance de a apara Astranaar si de a lupta umar la umar cu Sentinels night elven.",["race:NightElf"]="Pentru kaldorei, curmarea furiei lui Ran Bloodtooth ii onoreaza pe aliatii cazuti precum Teronis si ajuta la redobandirea sfinteniei dumbravilor sacre din Ashenvale."},sec={{t="Un trofeu amar",b="Dupa infrangerea temutei capetenii furbolg corupte Ran Bloodtooth, Krolg il trimite pe campion inapoi la Astranaar. Cu craniul retezat al lui Bloodtooth in mana, te intorci ca dovada ca amenintarea salbatica ce bantuia adancurile padurii a fost zdrobita definitiv."},{t="In amintirea lui Teronis",b="Dupa ce primeste craniul, Raene Wolfrunner il asaza alaturi de Toiagul lui Dartol, intr-un loc de cinste. Acest simbol sumbru cinsteste amintirea lui Teronis, a carui investigatie tragica privind purificarea furbolgilor corupti a pus in miscare intreaga actiune disperata."}},faq={{q="Cine este Ran Bloodtooth?",a="Ran Bloodtooth era considerat cea mai apriga amenintare dintre furbolgii corupti care terorizau padurile din Ashenvale. Infrangerea lui inlatura un conducator periculos, care vana in mod activ locuitorii padurii.",al={"Ran Bloodtooth","craniul lui Bloodtooth","cine a fost Ran Bloodtooth"}},{q="De ce vrea Raene Wolfrunner craniul?",a="Raene Wolfrunner pastreaza craniul alaturi de Dartol's Rod, ca simbol al victoriei si al amintirii. Este o dovada de netagaduit ca fortele santinelelor si aliatii lor au doborat o primejdie mortala pentru Ashenvale.",al={"de ce craniul","craniul Wolfrunner","ce face Raene cu craniul"}},{q="Cine a fost Teronis?",a="Teronis era un cercetator Night Elf a carui moarte, la inceputul seriei de misiuni, a declansat cautarea pietrelor pretioase purificatoare si a toiagului lui Dartol. Incheierea sarcinii ii implineste misiunea neterminata.",al={"teronis","cine este teronis","mandrul teronis"}},{q="Unde se incheie aceasta misiune?",a="Se incheie in Astranaar, principalul centru al rasei Night Elf din Ashenvale, vorbind cu Sentinel Raene Wolfrunner.",al={"locatia predarii misiunii","unde se afla raene","locatia lui Raene Wolfrunner"}},{q="Cine este Krolg?",a="Krolg este un aliat care te indruma sa duci craniul taiat al lui Ran Bloodtooth inapoi la Astranaar, ca sa-ti castigi recunoasterea si sa-ti savurezi victoria alaturi de ai tai.",al={"krolg","cine da misiunea","npc krolg"}},{q="Ce este toiagul lui Dartol?",a="Toiagul lui Dartol este o relicva fermecata puternica, faurita in timpul seriei de misiuni si strans legata de natura furbolgilor si de purificare.",al={"toiagul lui dartol","toiagul transformarii","toiagul furbolg"}}},fx={d3b35236={q="De ce te trimite Krolg la Astranaar?",a="Dupa ce Ran Bloodtooth, cea mai feroce amenintare furbolg din Ashenvale, a fost ucis, Krolg iti recunoaste izbanda. Furbolg necorupt, care te ia drept unul de-ai lui datorita toiagului lui Dartol, iti da craniul lui Ran si iti spune sa te intorci la tribul tau, sa le arati trofeul si sa te bucuri de gloria victoriei.",al={"de ce vrea krolg sa se faca acest lucru","motivul lui krolg","de ce vrea krolg craniul din astranaar"}}},fp="17,291,15.266.0,20.255.1,22.182.0,41.209.0,16.188.1,26.113.0,13.164.0,21.144.0"}
P.entries["quest:1050"] = {n="Mitologia titanilor",s="Bibliotecarul Mae Paledust din Ironforge cauta o carte despre care se spune ca ar fi fost pastrata in vechea Manastire din Tirisfal. Studiul sau poate ajuta la dezvaluirea a ceea ce trecutul poate invata despre necunoscutul din viitor.",h="Bibliotecarul Mae Paledust din Ironforge cauta o carte despre care se spune ca ar fi fost pastrata in vechea...",kw={"carte","ironforge","bibliotecar mae paledust","mae paledust","mitologia titanilor","manastire veche","poiana tirisfal","titani"},sec={{t="Un volum pierdut",b="Inainte ca necazurile sa vina in Lordaeron, vechea Manastire din Poiana Tirisfal detinea o biblioteca de cunostinte. Mae va cere sa preluati o carte numita Mythology of the Titans de acolo si sa i-o aduceti in Ironforge. Ea spera ca studierea acesteia va ajuta la descoperirea secretelor trecutului."}},faq={{q="Cine cere cartea?",a="Bibliotecara Mae Paledust din Ironforge va cere sa-i aduceti Mythology of the Titans.",al={"cine vrea","Cartea Mae Paledust","bibliotecar Mae"}},{q="Unde se spune ca este Mitologia Titanilor?",a="Se zvoneste ca cartea se afla in biblioteca vechii Manastiri din Poiana Tirisfal.",al={"unde carte","cartea manastirii","locatia cartii titan"}},{q="Ce este Mitologia Titanilor?",a="Este o carte despre care se spune ca ar fi fost gazduita in biblioteca vechei Manastiri din Poiana Tirisfal.",al={"care este cartea","mitologia titanului","carte de mitologie"}},{q="De ce vrea Mae cartea?",a="Mae spera ca studierea cartii poate ajuta la dezvaluirea secretelor trecutului si la pregatirea pentru necunoscut.",al={"de ce sa-l ia","de ce Mae are nevoie de el","pentru ce este"}}},fp="23,180,13.274.0,27.82.0,44.81.0,32.88.0,27.92.0"}
P.entries["quest:1052"] = {n="Down the Scarlet Path",s="Brother Anton spune ca faptele tale impotriva celor undead din Desolace sunt doar un inceput, fiindca adevaratul pericol al ciumei se afla in Lordaeron. Iti da o scrisoare de recomandare cu sigiliul sau, pentru Raleigh the Devout din Southshore.",h="Brother Anton spune ca faptele tale impotriva celor undead din Desolace sunt doar un inceput, fiindca...",kw={"brother anton","down the scarlet path","hearthglen","letter of commendation","lordaeron","raleigh the devout","scarlet monastery","southshore","tirisfal glades"},sec={{t="Fortaretele Cruciadei",b="Anton vorbeste cu mandrie despre bastioanele de purificare ale Scarlet Crusade din Lordaeron. Crusade detine fortarete de-a lungul intregului tinut, intre Hearthglen si Tirisfal Glades. Anton spune ca ti-ai dovedit valoarea luptand impotriva Undead din Desolace, dar adevaratul pericol al plagii se afla in Lordaeron."},{t="O scrisoare pentru Southshore",b="Anton te trimite la Southshore, un oras din Eastern Kingdoms, sa-l cauti pe un cruciat pe nume Raleigh the Devout. Scrisoarea poarta sigiliul lui Anton, iar el spune ca aceasta iti va asigura o escorta din partea lui Raleigh pana la un loc de cinste in Scarlet Monastery."},{t="Reactia lui Raleigh",b="Raleigh rupe pecetea si citeste scrisoarea. Vestea ca Anton inca raspandeste informatii despre Scarlet Crusade il tulbura pe Raleigh, care iti spune ca aici se petrece ceva ce nu poti intelege."}},faq={{q="Cine te trimite in aceasta calatorie?",a="Brother Anton iti da o scrisoare de recomandare sigilata, pe care sa i-o duci lui Raleigh the Devout.",al={"cine da Down the Scarlet Path","cel care ofera misiunea Down the Scarlet Path"}},{q="Unde esti trimis?",a="Mergi in Southshore, in Eastern Kingdoms, pentru a-l gasi pe cruciatul Raleigh the Devout.",al={"unde sa mergi","unde se afla raleigh","locatia Down the Scarlet Path"}},{q="Ce spune Brother Anton ca va face scrisoarea?",a="Anton spune ca, dupa ce Raleigh va vedea scrisoarea sa sigilata, te va duce intr-un loc de onoare din Scarlet Monastery.",al={"la ce foloseste scrisoarea","scopul scrisorii de recomandare"}},{q="Ce teritoriu revendica Scarlet Crusade in Lordaeron?",a="Brother Anton spune ca Scarlet Crusade detine fortarete intinse intre Hearthglen si Tirisfal Glades si este mandru de aceste bastioane ale purificarii.",al={"teritoriile Scarlet Crusade","unde se afla fortaretele Scarlet Crusade"}}},fp="21,221,26.278.0,23.249.0,18.184.1,30.87.0,25.87.0,47.124.0,59.158.0"}
P.entries["quest:1054"] = {n="Culling the Threat",s="Culling the Threat este o operatiune defensiva a Alliance, initiata de Raene Wolfrunner in Astranaar. Confruntati cu inmultirea rapida a furbolgilor Thistlefur chiar la nord, elfii noptii cauta sa previna un atac asupra asezarii, ucigandu-l pe conducatorul lor de razboi, Dal Bloodclaw. Misiunea reflecta cruda realitate in care fostii aliati ai padurii trebuie acum eliminati pentru a proteja locuintele kaldorei.",h="Culling the Threat este o operatiune defensiva a Alliance, initiata de Raene Wolfrunner in Astranaar.",kw={"ashenvale","astranaar","culling the threat","dal bloodclaw","furbolg","raene wolfrunner","thistlefur"},ang={["class:Druid"]="Druizii privesc cu profunda tristete nebunia tribului Thistlefur, vazand cum intinarea persistenta din Ashenvale ii transforma pe nobilii furbolg in bestii insetate de sange.",["faction:Alliance"]="Pastrarea controlului asupra Astranaar este esentiala pentru liniile de aprovizionare si comunicatiile Alliance din centrul Kalimdor, astfel ca orice amenintare la nord de oras devine o prioritate tactica urgenta.",["race:NightElf"]="Pentru kaldorei, doborarea furbolgilor este o necesitate tragica: deplang coruperea unor aliati stravechi, dar recurg la masuri brutale pentru a salva Astranaar de la distrugere."},sec={{t="O primejdie iminenta la nord",b="Astranaar se afla in inima Ashenvale si este mereu inconjurat de primejdii. La nordul asezarii locuiesc furbolgii Thistlefur. Odinioara pasnici locuitori ai padurii stravechi, au innebunit si au devenit agresivi, asemenea multora dintre semenii lor. Cercetasii Sentinel au urmarit cum populatia lor creste in ultimele luni, starnind temeri ca un atac coordonat asupra Astranaarului este doar o chestiune de timp."},{t="Lovirea capeteniei",b="In loc sa astepte ca hoarda Thistlefur sa napadeasca palisadele modeste din Astranaar, Raene Wolfrunner le cere calatorilor sa treaca la atac. Tinta este Dal Bloodclaw, capetenia a carei conducere organizeaza si incurajeaza vizuina. Decapitand tribul si aducand craniul lui Dal inapoi la Astranaar, Sentinels spera sa destrame coordonarea furbolgilor si sa castige timp pretios pentru orasul asediat."}},faq={{q="Cine ofera misiunea Culling the Threat?",a="Raene Wolfrunner, o comandanta Sentinel stationata in orasul Night Elf Astranaar din Ashenvale, ofera aceasta misiune.",al={"cel care ofera misiunea","cine incepe culling the threat","de unde iau misiunea culling the threat"}},{q="De ce vrea Astranaar ca Dal Bloodclaw sa fie ucis?",a="Dal Bloodclaw conduce tribul Thistlefur, aflat chiar la nord de Astranaar. Cum numarul lor creste rapid, Wolfrunner se teme ca Bloodclaw va porni un raid direct asupra orasului daca nu i se inlatura conducerea.",al={"de ce sa-l ucizi pe Dal Bloodclaw","povestea lui Dal Bloodclaw","de ce sa ataci Thistlefur"}},{q="De ce sunt furbolgii Thistlefur ostili elfilor noptii?",a="Desi furbolgii si elfii noptii au fost in trecut aliati, influentele demonice si corupatoare din Ashenvale au impins multe triburi, inclusiv pe cele din Thistlefur, intr-o furie violenta si o paranoia teritoriala.",al={"de ce ataca Furbolgii","Furbolgii corupti din Ashenvale","povestea Thistlefur"}},{q="Unde poate fi gasit Dal Bloodclaw?",a="Dal Bloodclaw locuieste in Thistlefur Village si in criptele din apropiere, chiar la nord de Astranaar, in Ashenvale.",al={"locatia lui dal bloodclaw","unde se afla dal bloodclaw"}},{q="Rezolva definitiv uciderea lui Dal Bloodclaw amenintarea furbolgilor?",a="Nu. Raene Wolfrunner observa ca uciderea lui Dal Bloodclaw doar le potoleste agresivitatea pentru o vreme. Atata timp cat coruptia stapaneste Ashenvale, populatia de furbolgi ramane un pericol persistent.",al={"thistlefur a fost invins","am salvat Astranaar"}},{q="Ce dovada a mortii lui Dal Bloodclaw este necesara?",a="Trebuie sa iei Dal Bloodclaw's Skull si sa-l duci direct la Raene Wolfrunner, in Astranaar.",al={"ce sa-i aduc lui Raene","obiectul de predat pentru Culling the Threat"}}},fx={d8b26d15={q="Cine este Dal Bloodclaw?",a="Dal Bloodclaw este capetenia furbolgilor Thistlefur care traiesc in satul lor, chiar la nord de Astranaar. Sub conducerea sa, furbolgii corupti s-au inmultit rapid in ultimele luni, amenintand sa copleseasca padurile din jur si sa lanseze un atac in toata regula asupra asezarii elfilor noptii.",al={"cine este Dal Bloodclaw","cine este capetenia furbolgilor","povestea lui Dal Bloodclaw"}},["05594dd8"]={q="De ce are nevoie Raene Wolfrunner de un aventurier in locul sentinelilor din Astranaar?",a="Sentinels stationate in Astranaar sunt intinse la maximum, aparand orasul de amenintarile care se apropie din toate directiile. Raene Wolfrunner trebuie sa ramana in urma pentru a coordona apararea locala, asa ca niste calatori capabili sunt alegerea ideala pentru a se strecura pe teritoriul Thistlefur si a-i rapune conducatorul inainte ca atacul sa aiba loc.",al={"de ce sa ma trimita pe mine","de ce nu trimite Raene garzi","de ce nu ataca santinelele din Astranaar"}}},fp="18,375,28.409.0,22.422.0,39.115.0,43.206.0,59.203.0,33.112.0,64.185.0,48.93.0"}
P.entries["quest:1055"] = {n="Raene's Cleansing",s="Aceasta sarcina marcheaza incheierea Toiagului Transformarii, la sanctuarul ascuns din Ashenvale. Odata asamblat artefactul sacru, trebuie dus imediat inapoi la dryada Shael'dryn, in sanctuarul ei de la putul lunii.",h="Aceasta sarcina marcheaza incheierea Toiagului Transformarii, la sanctuarul ascuns din Ashenvale.",kw={"Ashenvale","Astranaar","Elune","altar ascuns","fintana lunii","Raene's Cleansing","toiag al transformarii","Shael'dryn"},ang={["class:Priest"]="Ajutarea lui Shael'dryn restaureaza o relicva magica de care Raene are nevoie pentru cercetarea sa in Ashenvale.",["faction:Alliance"]="Asigurarea controlului asupra Ashenvale este esentiala pentru pozitia Alliance in nordul Kalimdor, protejand Astranaar de atacurile neincetate ale coruptiei locale si ale fortelor ostile.",["race:NightElf"]="Refacerea toiagului o ajuta pe Raene sa cerceteze atacurile furbolg care ameninta Astranaar si padurile din jur."},sec={{t="O relicva restaurata",b="Munca istovitoare de asamblare a Rod of Transformation ajunge la un moment de cotitura linistit la altarul izolat, ascuns adanc in salbaticia din Ashenvale. Imbinarea tijei, a butonului si a nestematei stralucitoare, precum si vrajirea din nou a toiagului reconstruit la altarul ascuns i-au redat magia. Artefactul este pregatit sa fie inapoiat lui Shael'dryn, pentru cercetarea lui Raene asupra atacurilor furbolgilor."},{t="Intoarcerea la Shael'dryn",b="Dupa ce asamblarea este incheiata, vestea si relicva trebuie duse degraba inapoi la Shael'dryn. Driada, aflata langa apele linistite ale fantanii lunare din padure, a calauzit fiecare pas al acestei restaurari. Sa-i prezinti toiagul asamblat nu doar confirma ca magia lui a fost refacuta, ci le permite si aparatorilor Sentinels sa faca urmatorii pasi decisivi pentru apararea patriei asediate."}},faq={{q="Care este scopul acestei etape a misiunii?",a="Dupa ce ai asamblat cu succes Toiagul Transformarii la sanctuarul ascuns, nu trebuie decat sa duci toiagul terminat inapoi la dryada Shael'dryn, care te asteapta la fantana lunii din nordul Ashenvale.",al={"ce sa faci in Raene's Cleansing 7","ce este aceasta misiune","scopul misiunii"}},{q="Cine este Shael'dryn?",a="Shael'dryn este o dryada care ingrijeste o fantana lunara sacra din Ashenvale. Lucrand la curatarea stravechii paduri de coruptia care se raspandeste, ea le cere aliatilor de incredere sa adune relicve, sa purifice componente si sa restaureze artefacte sacre.",al={"Shael'dryn","cine este Shael'dryn","preoteasa de la moonwell"}},{q="Unde se afla Shael'dryn?",a="Shael'dryn locuieste langa un izvor lunar linistit, ascuns in nordul Ashenvale, la est de drumul principal dintre Astranaar si Felwood, inconjurat de apele tihnite pe care le vegheaza.",al={"locatia lui Shael'dryn","unde este Shaeldryn","unde este izvorul lunii"}},{q="Ce este Rod of Transformation?",a="Toiagul este o creatie magica a lui Dartol. Puterea sa restaurata urmeaza sa o ajute pe Raene sa investigheze furbolgii; forma pe care o capata va fi dezvaluita mai tarziu.",al={"ce este rod of transformation","povestea lui rod of transformation","toiagul"}},{q="De ce este atat de importanta asamblarea toiagului pentru Astranaar?",a="Raene Wolfrunner spera ca toiagul ii va permite unui investigator sa se apropie de furbolgi si sa afle mai multe despre atacurile care ameninta Astranaar.",al={"de ce purifica Raene","de ce ii pasa Astranaar","importanta lui Raene"}},{q="Asamblarea toiagului incheie lantul de purificare?",a="Nu. Shael'dryn iti va cere apoi sa te intorci la Raene Wolfrunner in Astranaar si sa-i spui ca toiagul este gata.",al={"aceasta este ultima misiune","purificarea lui Raene se termina aici","sfarsitul seriei"}}},fp="17,213,16.386.0,20.408.0,47.197.0,18.218.0,28.182.0,34.149.0,52.133.0,48.107.0"}
P.entries["quest:1057"] = {n="Reclaiming the Charred Vale",s="Reclaiming the Charred Vale este o misiune Alliance oferita de Keeper Albagorm, pe varful Stonetalon Peak. Aventurierii trebuie sa rareasca harpiile Bloodfury agresive care ocupa valea ruinata Charred Vale, eliberand calea pentru ca druizii si ingrijitorii sa inceapa vindecarea tinutului parjolit.",h="Reclaiming the Charred Vale este o misiune Alliance oferita de Keeper Albagorm, pe varful Stonetalon Peak.",kw={"Bloodfury","Charred Vale","harpii","Keeper Albagorm","Reclaiming the Charred Vale","Stonetalon","varful Stonetalon"},ang={["class:Druid"]="Ca pazitori ai cercului Cenarion si aparatori ai armoniei naturale, druizii ii ajuta direct pe Keepers sa curete cuiburile contaminate, facand loc reimpaduririi magice.",["faction:Alliance"]="Securizarea trecatorilor inalte si a vailor sudice protejeaza asezarile si sanctuarele vulnerabile ale elfilor noptii din Stonetalon Peak de amenintarile pradatoare.",["race:NightElf"]="Elfii noptii venereaza padurile salbatice din Stonetalon; alungarea harpiilor ticaloase din dumbravile sacre pangarite de motoare straine este o chemare urgenta."},sec={{t="Valea ranita",b="La sud de Stonetalon Peak se afla Charred Vale, un refugiu alpin odinioara luxuriant, acum redus la cenusa si ruine fumegande. Dezastrul a inceput cand o armata mecanizata de taietori de lemne si mineri a strabatut stancile sacre, doborand copacii si alimentand incendii scapate de sub control. Pentru pazitorii din Stonetalon, sa priveasca padurea straveche cum cedeaza in fata lacomiei industriale este o rana de nesuportat adusa salbaticiei."},{t="Amenintarea Harpy",b="Desi focurile mecanice au declansat ruina, in cenusa s-a inradacinat si o infestare oportunista. Harpiile Bloodfury, feroce, au navalit in tinuturile joase inca fumegande, facandu-si cuiburi si atacand cu inversunare pe oricine se apropie de vale. Keeper Albagorm si aliatii sai nici macar nu pot strabate pamantul ca sa semene semintele renasterii, caci Bloodfury refuza cu violenta trecerea tuturor strainilor."},{t="Eliberarea caii catre reinnoire",b="Inainte de a putea incepe o restaurare adevarata, cuiburile tribului Bloodfury trebuie distruse. Albagorm le cere luptatorilor Alliance incercati sa patrunda adanc printre randurile lor, ucigand vanatori, ambuscadori si roguefeathers deopotriva. Rarirea stolurilor lor de pradatori este primul pas esential pentru a recupera ceea ce apartine naturii si a le reda spiritelor padurii ragazul de a respira."}},faq={{q="Ce este Charred Vale?",a="Charred Vale este o vale ascunsa in inaltimile sud-vestice din Stonetalon Mountains. Odinioara o padure verde si bogata, a fost mistuita de foc si parjolita pana la roca de baza, in timpul exploatarii necontrolate a tinutului de catre industria exploatarii lemnului.",al={"povestea lui charred vale","ce s-a intamplat cu charred vale","de ce a fost parjolita"}},{q="Cine este Keeper Albagorm?",a="Keeper Albagorm este un paznic al padurii si ingrijitor care locuieste in asezarea Alliance de pe Stonetalon Peak. Ca aparator al naturii si al spiritelor padurii, isi dedica viata opririi pustiirii muntilor si respingerii fiarelor care le invadeaza.",al={"Keeper Albagorm","cine ofera Reclaiming the Charred Vale","povestea lui Albagorm"}},{q="De ce traiesc harpiile in Charred Vale?",a="Harpile Bloodfury sunt necrofage agresive si oportuniste, care prospera in teritorii devastate si corupte. Cand focul a ras de pe fata pamantului valea, stolul s-a instalat acolo pentru a stapani bazinul pustiu, atacand pe oricine incerca sa patrunda.",al={"harpiile Bloodfury","de ce sunt harpii aici","Bloodfuries in Stonetalon"}},{q="Cine a incendiat Charred Vale de la bun inceput?",a="Keeper Albagorm ii identifica pe vinovati: o armata mecanizata si lacoma de industriasi, care a sfasiat dealurile. Utilajele de exploatare forestiera lasate nesupravegheate si extinderea exploziva au provocat incendii devastatoare, care au mistuit padurea.",al={"cine a ars Charred Vale","armata mecanizata a industriaselor","Venture Company in Charred Vale"}},{q="Ce trebuie facut dupa rarirea harpiilor?",a="Starpirea harpiilor nu face decat sa securizeze perimetrul. Dupa ce efectivele Bloodfury sunt reduse, Keeper Albagorm isi indreapta atentia spre plantarea semintelor si canalizarea magiei vindecatoare, pentru a readuce viata in solul parjolit.",al={"urmatoarea misiune din Charred Vale","Reclaiming the Charred Vale, partea 2","ce se intampla in continuare"}},{q="Este aceasta misiune disponibila aventurierilor din Horde?",a="Nu. Keeper Albagorm isi desfasoara activitatea din reduta Alliance-aligned de pe culmea Stonetalon Peak, asa ca aceasta misiune anume, de a-i nimici pe harpiile Bloodfury, este rezervata eroilor din Alliance.",al={"poate Horde sa faca aceasta misiune","Horde recucereste Charred Vale"}}},fx={d7987d6f={q="De ce vrea Keeper Albagorm sa starpeasca Bloodfuries?",a="In calitate de pazitor al dumbravii si protector al spiritelor padurii, Albagorm incearca sa vindece si sa redea Charred Vale, brazdat si ars, infatisarea luxurianta de sanctuar pe care o avea odinioara. Totusi, harpiile Bloodfury agresive, care au napadit ruinele, impiedica cu indarjire orice acces, impiedicand Cenarion Circle sa inceapa ritualurile sacre de reinnoire si renastere.",al={"de ce sa cureti Charred Vale","motivul lui Keeper Albagorm","de ce sa omori harpiile din Charred Vale"}}},fp="27,299,18.407.0,16.383.0,28.387.0,25.246.0,23.248.0,43.229.0,52.216.0,45.222.1,45.178.0"}
P.entries["quest:1058"] = {n="Jin'Zil's Forest Magic",s="La avanpostul marunt din Malaka'jin, Witch Doctor Jin'Zil a capturat trei cercetasi night elf in custi grosolane din fier. In loc sa-i execute pe loc sau sa-i tina pentru rascumparare, trollul excentric le cere aventurierilor Hordei sa adune reactivi din salbaticie de la Stonetalon Peak pentru a pregati o doza oribila de 'magie a padurii'.",h="La avanpostul marunt din Malaka'jin, Witch Doctor Jin'Zil a capturat trei cercetasi night elf in custi...",kw={"ochi de alergator","dragon zana","magia padurii","Jin'Zil","Malaka'jin","prizonieri","Stonetalon","alergator crepuscular","doctor vrajitor"},ang={["class:Druid"]="Sa vezi cum seva straveche a padurii, drakele feerice sacre si bidiviii maiestuosi sunt recoltati pentru a prepara o otrava mortala este o pervertire sinistra a echilibrului naturii.",["faction:Horde"]="Securizarea Malaka'jin presupune infrangerea rezistentei night elf din intreaga regiune, chiar si prin metodele neobisnuite ale unui doctor vrajitor retras.",["race:NightElf"]="Executarea chinuitoare a prizonierilor elfi ai noptii cu ajutorul materialelor padurii pervertite este una dintre cele mai crude fapte ale Horde din Stonetalon.",["race:Troll"]="Umorul macabru al lui Jin'Zil si folosirea practica a alchimiei voodoo sunt trasaturi definitorii ale mestesugului medicilor voodoo Darkspear."},sec={{t="O bautura amara",b="In defileul cu stanci rosii din Malaka'jin, Witch Doctor Jin'Zil isi practica arta sub privirile vigilente ale Horde. Cand trei captive night elf ajung in mainile lui, Jin'Zil hotaraste sa renunte la macelul obisnuit si nascoceste in schimb un ritual batjocoritor, croit anume pentru dusmancele sale captive din padure. El le cere calatorilor sa mearga spre nord, in piscurile neimblanzite, pentru a aduna o multime de ingrediente locale: seva groasa de copac, mustati de feline de la alergatorii crepusculari rapitori, o solz stralucitor de dragon-fey si zeci de ochi smulsi din alergatorii padurii din partea locului."},{t="Gust de acasa",b="In spatele firii jucause a lui Jin'Zil se ascunde un simt al umorului crud, de troll. Sub pretextul ca vrea sa-i faca pe elves intemnitati sa se 'simta ca acasa' fara o padure in care sa zburde, amestecul de fauna magica si seva concentrata formeaza un venin letal si instabil. Odata eliberat in pestera, amestecul toxic le curma pe loc viata captivilor din custi. Pe masura ce trupurile lor pier, spiritele ancestrale ale elves se destrama in lumini plutitoare care se inalta spre munti, lasand in urma custile goale."}},faq={{q="Cine este Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil este un troll Darkspear stationat la Malaka'jin, in sudul Stonetalon Mountains. El sprijina efortul de razboi al Horde impotriva night elves, practicand alchimia traditionala a trollilor, voodoo si interogatoriul.",al={"cine este jin'zil","doctorul vrajitor jin'zil","povestea lui jinzil"}},{q="De ce vrea Jin'Zil atat de multi ochi de courser?",a="Jin'Zil sustine ca nu poti prepara magie navalnica a padurii fara o multime de ochi. Desi vracii troll folosesc adesea ingrediente organice ciudate in potiunile lor, cantitatea absurda reflecta si firea lui excentrica si razbunatoare.",al={"de ce ochi de courser","30 de ochi de courser","de ce atatia ochi"}},{q="Ce se intampla cu elfii noptii inchisi in custi la incheierea misiunii?",a="Dupa ce primeste reactivii, Jin'Zil raspandeste bautura toxica prin pestera. Licoarea ii otraveste mortal pe cei trei captivi, omorandu-i si eliberandu-le spiritele sub forma unor suflete de foc ratacitoare, care se pierd in salbaticie.",al={"ce se intampla cu elfii","soarta elfilor captivi","prizonierii lui Jin'Zil"}},{q="Unde se gasesc toti acesti reactivi?",a="Ochii de courser si seva din Stonetalon pot fi adunate in jurul Mirkfallon Lake si in podisurile nordice. Mustatile twilight si rarul solz de fey dragon se gasesc mai la nord, langa Stonetalon Peak, unde cutreiera fiarele magice ale muntelui.",al={"unde gasesc reactivi pentru magia padurii","locatia sevei din stonetalon","locul solzilor de dragon zanelor"}},{q="De ce se lupta Horde cu Night Elves in Stonetalon?",a="Defrisarile Horde in Ashenvale, tinutul invecinat, au starnit o rezistenta apriga din partea Sentinels, iar elfii noptii stapanesc in continuare Stonetalon Peak si crangurile sale sacre, deasupra avanposturilor Horde precum Malaka'jin.",al={"de ce lupti impotriva elfilor noptii in Stonetalon","conflictul dintre Hoarda si elfii noptii in Stonetalon","razboiul din Stonetalon"}},{q="De ce elfii muribunzi se transforma in spirite?",a="Wispii sunt spiritele elfilor noptii decedati, care raman strans legate de natura. Dupa moarte, sufletele lor capata aceasta forma luminoasa, arboricola, in loc sa dainuie ca fantome sau umbre obisnuite.",al={"de ce devin elfii wisps","wisps elfice in pestera","lore despre wisp"}}},fx={["58b555cd"]={q="De ce vrea Witch Doctor Jin'Zil ca acest lucru sa fie facut?",a="Witch Doctor Jin'Zil a capturat trei sentinele night elf si le-a inchis in custi, in pestera sa din Malaka'jin. In loc sa le execute pur si simplu, vrea sa prepare o potiune razbunatoare, botezata in batjocura \"magie a padurii\". Combinand esente brute si puternice din salbaticia lor indragita, intentioneaza sa creeze o otrava letala care sa intoarca darurile naturii padurii impotriva prizonierilor sai.",al={"de ce foloseste Jin'Zil magia padurii","de ce creeaza magie a padurii","motivul lui Jin'Zil"}},["840e6ff0"]={q="La ce foloseste Stonetalon Sap?",a="Adunata din arborii vii si fiarele de seva ale regiunii, rasina groasa serveste drept baza vascoasa si lipicioasa pentru amestecul lui Jin'Zil. Ea capteaza si imbina celelalte ingrediente forestiere, ancorandu-i bautura toxica in esenta bruta a muntilor.",al={"utilizarea sevei din Stonetalon","de ce se colecteaza seva","la ce foloseste seva"}},["70cbdf3f"]={q="La ce foloseste Fey Dragon Scale?",a="Dragonii feerici sunt creaturi mistice, strans legate de puterea de smarald a Stonetalon Peak si de Kaldorei. Jin'Zil are nevoie de un solz pentru a-si impregna potiunea cu protectia magica si energiile salbatice innascute ale acestora, transformand-o intr-un agent letal creat special pentru a le face rau celor din night elf.",al={"la ce foloseste solzul de dragon feeric","de ce este necesar solzul de dragon feeric"}},a0fa7c69={q="La ce foloseste Twilight Whisker?",a="Recoltate de la alergatorii amurgului care pandesc prin paduri, aceste mustati adauga amestecului instinctul salbatic si pradator al rapitorilor bastinasi din Stonetalon, transformand fiertura intr-o otrava agresiva.",al={"la ce foloseste twilight whisker","de ce twilight whiskers","la ce folosesc mustatile twilight"}}},fp="22,325,13.547.0,15.519.1,28.226.0,43.253.0,62.215.1,35.242.0,52.203.0,39.196.0"}
P.entries["quest:1059"] = {n="Reclaiming the Charred Vale",s="Reclaiming the Charred Vale este o misiune de mesager primita de la Keeper Albagorm in Stonetalon Peak. Dupa ce a tinut temporar sub control harpiile locale, Albagorm trimite un calator din Alliance mult spre sud, in Feralas, pentru a cere ajutorul druidului Falfindel Waywarder.",h="Reclaiming the Charred Vale este o misiune de mesager primita de la Keeper Albagorm in Stonetalon Peak.",kw={"bloodfuries","Charred Vale","Falfindel Waywarder","Feralas","Thalanaar","Keeper Albagorm","varful Stonetalon","Thousand Needles"},ang={["class:Druid"]="Aceasta misiune evidentiaza datoria Cenarion de a merge dincolo de garnizoanele locale si de a chema spiritele primordiale ale naturii pentru a vindeca tinuturile marcate de distrugeri nenaturale.",["faction:Alliance"]="Pozitia Alliance de la Stonetalon Peak depinde de legatura dintre avanposturile de frontiera, aflate la distante mari unele de altele, in zonele disputate din Kalimdor."},sec={{t="Cicatricele vaii",b="Charred Vale, din sudul Stonetalon Mountains, ramane o amintire sufocata de cenusa a unei pustiiri catastrofale. Desi fortele Alliance aflate sub comanda lui Keeper Albagorm au ripostat impotriva harpiilor Bloodfury care isi fac cuib in ruine, alungarea lor este doar o masura temporara. Albagorm intelege ca forta fizica singura nu poate vindeca pamantul devastat inainte ca harpiile sa se regrupeze si sa-si recapete suprematia."},{t="Un apel catre sud",b="Pentru a reda viata pamanturilor parjolite in mod definitiv, ingrijitorii dumbravii au nevoie de o interventie mistica ce le depaseste puterile actuale. Albagorm trimite un curier departe spre sud, ocolind salinele si canioanele din Thousand Needles, pana la Thalanaar, la granita cu Feralas. Acolo il asteapta Falfindel Waywarder, un druid elf al noptii despre care se spune ca stapaneste puterea rara de a chema spirite primordiale ale padurii, capabile sa revitalizeze solul mort."}},faq={{q="Cine este Keeper Albagorm?",a="Keeper Albagorm este un pazitor al crangului stationat la Stonetalon Peak, care supravegheaza eforturile Alliance de a curata si restaura Charred Vale, zona pustiita.",al={"cine este albagorm","keeper albagorm"}},{q="Unde se afla Falfindel Waywarder?",a="Falfindel Waywarder se afla la Thalanaar, la granita vestica, unde Thousand Needles se preschimba in salbaticia luxurianta din Feralas.",al={"unde este Falfindel","locatia lui Falfindel Waywarder","gaseste-l pe Waywarder"}},{q="De ce sa fie chemat un druid tocmai din Feralas?",a="Keeper Albagorm il considera pe Falfindel deosebit de capabil sa invoce spirite stravechi puternice ale padurii, care pot inversa devastarea ecologica profunda din Charred Vale.",al={"de ce sa mergi in feralas","de ce falfindel"}},{q="Ce amenintare salasluieste in Charred Vale?",a="Valea este napadita de harpiile ostile Bloodfury, alaturi de elementali ai focului si fiare salbatice care au prosperat dupa ce tinutul a fost mistuit de flacari.",al={"dusmani din Charred Vale","ce ataca valea"}},{q="Necesita aceasta misiune lupta?",a="Nu. A doua parte din Reclaiming the Charred Vale este doar o misiune de calatorie terestra, in care trebuie sa duci mesajul lui Albagorm prin centrul si sudul Kalimdorului.",al={"e grea misiunea asta","lupta in misiunea Charred Vale"}},{q="Cum ajungi la Thousand Needles din Stonetalon?",a="Calatorii trebuie sa mearga spre est, iesind din Stonetalon Mountains in Barrens, apoi sa se indrepte spre sud de-a lungul Gold Road, sa coboare pe Great Lift in Thousand Needles si sa continue spre vest, catre Feralas.",al={"cum ajungi la Thousand Needles","ruta de calatorie spre Feralas"}}},fx={edca7440={q="De ce vrea Keeper Albagorm ca acest lucru sa fie facut?",a="Desi ai doborat multe dintre harpiile Bloodfury, Keeper Albagorm stie ca se vor regrupa repede si isi vor recastiga stapanirea asupra Charred Vale daca nu se iau masuri de durata. Tinutul ramane ruinat si vulnerabil, iar simpla rarire a fiarelor nu poate vindeca pamantul parjolit. Are nevoie urgenta de puternicele spirite ale padurii pe care doar un druid precum Falfindel Waywarder le poate chema, pentru a reda viata vaii inainte ca harpiile sa se adune din nou si sa-ti anuleze progresele.",al={"motivul lui Keeper Albagorm","de ce sa-l chemi pe Falfindel","de ce sa recuceresti Charred Vale"}}},fp="27,253,21.405.0,19.427.0,23.149.0,37.151.0,44.167.0,40.140.0,31.167.0,50.185.0"}
P.entries["quest:106"] = {n="Young Lovers",s="Young Lovers este o misiune din Elwynn Forest, axata pe povestea de dragoste interzisa dintre Maybell Maclure si Tommy Joe Stonefield. Cum familiile lor rivale sunt prinse intr-o dusmanie amara, Maybell roaga un aventurier sa-i duca in taina lui Tommy Joe o scrisoare de dragoste plina de emotie, pana la malul raului.",h="Young Lovers este o misiune din Elwynn Forest, axata pe povestea de dragoste interzisa dintre Maybell Maclure...",kw={"elwynn forest","vrajba","scrisoare de dragoste","maclure vineyards","maybell maclure","stonefield farm","tommy joe stonefield","tineri indragostiti"},ang={["faction:Alliance"]="Aventurierii Aliantei care traverseaza padurea Elwynn Forest ajung deseori sa duca mesaje intre familiile rivale Stonefield si Maclure, descoperind ca suferintele oamenilor de rand dainuie chiar si in mijlocul primejdiilor care ameninta intregul regat.",["race:Human"]="Pentru oamenii care cunosc Elwynn Forest, vechea vrajba dintre Stonefields si Maclures este o cearta locala bine cunoscuta, ceea ce face din povestea de dragoste dintre Maybell si Tommy Joe un scandal delicat de cartier."},sec={{t="O iubire interzisa",b="Pe campurile pastorale din Elwynn Forest, o cearta amara desparte doua familii de fermieri vecine: Stonefields si Maclures. In ciuda dusmaniei dintre familiile lor, tanara Maybell Maclure s-a indragostit profund de Tommy Joe Stonefield. Neputand sa-l viziteze pe fata, fara a starni furia familiei, Maybell se bazeaza pe calatorii aflati in trecere pentru a purta scrisori tainice peste hotarele care despart proprietatile rivale."},{t="Intalnirea de pe malul raului",b="Pentru a-si ascunde afectiunea de rudele vigilente, Tommy Joe Stonefield isi petrece orele pe malul linistit al raului, chiar la vest de Stonefield Farm. Sa-i duca scrisoarea lui Maybell ii aduce o usurare imensa si ii reaprinde dorul, facand despartirea de nesuportat si declansand noi incercari clandestine de a-i aduce impreuna pe tinerii indragostiti, in ciuda vrajbei dintre familii."}},faq={{q="Cine ofera misiunea Young Lovers?",a="Misiunea este oferita de Maybell Maclure la Maclure Vineyards, in Elwynn Forest. Este indragostita nebuneste de Tommy Joe Stonefield, dar familiile lor sunt rivale inversunate si nu-i lasa sa se intalneasca pe fata.",al={"cine da Young Lovers","cine incepe Young Lovers","cel care ofera misiunea Young Lovers"}},{q="Unde poate fi gasit Tommy Joe Stonefield?",a="Tommy Joe Stonefield poate fi gasit stand pe malul raului, chiar la vest de Stonefield Farm, aflata la vest de Maclure Vineyards, in Elwynn Forest. Asteapta acolo, departe de ochii vigilenti ai familiei.",al={"unde este Tommy Joe Stonefield","gaseste-l pe Tommy Joe","locatia lui Tommy Joe"}},{q="De ce sunt tinuti Maybell si Tommy Joe departe unul de celalalt?",a="Stonefields si Maclures sunt familii dusmane de moarte, care nutresc o ranchiuna de lunga durata una fata de cealalta. Din cauza acestei ostilitati adanc inradacinate, niciuna dintre familii nu le permite copiilor sa interactioneze, obligand tanarul cuplu sa comunice prin scrisori secrete.",al={"de ce se cearta familiile","cearta dintre Stonefield si Maclure","de ce nu se pot vedea Maybell si Tommy Joe"}},{q="Ce obiect livrezi in timpul acestei misiuni?",a="Ti se cere sa-i duci lui Tommy Joe Stonefield, direct la rau, scrisoarea de dragoste a lui Maybell. Scrisoarea ii transmite dragostea patimasa si il asigura pe Tommy Joe de devotamentul ei, in ciuda dusmaniei dintre familiile lor.",al={"ce este scrisoarea lui Maybell","ce livrezi in Young Lovers","scrisoare de dragoste din Elwynn"}},{q="Cum reactioneaza Tommy Joe la scrisoare?",a="Dupa ce primeste scrisoarea lui Maybell, Tommy Joe este in culmea fericirii si declara ca Maybell este lumina vietii sale monotone. Citindu-i cuvintele, nu mai poate suporta despartirea si incepe sa caute o cale prin care sa se intalneasca.",al={"cum reactioneaza tommy joe","reactia lui tommy joe","ce se intampla cand predai scrisoarea"}},{q="Unde are loc aceasta misiune?",a="Misiunea se desfasoara in sudul regiunii Elwynn Forest, intre Maclure Vineyards si raul care margineste Stonefield Farm. Este un colt rural linistit al regatului oamenilor, tulburat de certuri marunte intre localnici.",al={"unde se desfasoara young lovers","zona din young lovers","locatia fermei stonefield"}}},fp="12,278,19.433.0,24.368.0,33.209.0,40.217.0,41.264.0,43.227.0,39.209.0,33.217.0"}
P.entries["quest:1060"] = {n="Letter to Jin'Zil",s="Letter to Jin'Zil este o misiune de livrare a Horde, incredintata aventurierilor care au ucis-o pe Serena Bloodfeather in nordul regiunii Barrens. Darsok Swiftdagger, un rogue orc, te trimite peste granita, in tinutul stancos din Stonetalon Mountains, pentru a-i da de veste vechiului sau prieten, Witch Doctor Jin'Zil, despre moartea matriarhei harpiilor.",h="Letter to Jin'Zil este o misiune de livrare a Horde, incredintata aventurierilor care au ucis-o pe Serena...",kw={"bloodfury","darsok swiftdagger","harpii","scrisoare pentru jin'zil","malaka'jin","serena bloodfeather","stonetalon mountains","witch doctor jin'zil"},ang={["faction:Horde"]="Predarea acestei scrisori ii ajuta pe razboinicii Horde sa treaca de la pacificarea rutelor comerciale interne din Barrens la stabilirea unor capete de pod in disputatii Stonetalon Mountains.",["race:Troll"]="Pestera lui Jin'Zil din Malaka'jin serveste drept avanpost spiritual si tactic esential pentru troll din Darkspear care cauta sa asigure trecatorile montane."},sec={{t="Un mesaj in munti",b="Dupa ce amenintarea harpiilor din partea nordica a tinutului Barrens este inlaturata sistematic, Darsok Swiftdagger dezvaluie ca jefuitorii inaripati nu erau bastinasi ai tinuturilor cu tufisuri. Cetele Witchwing si Bloodfeather au coborat din crestele accidentate ale Stonetalon Mountains, din nord-vest. Impresionat de iscusinta ta in uciderea Serenei Bloodfeather, Darsok te trimite in acele piscuri primejdioase sa-i duci vestea mortii ei unei vechi cunostinte, Witch Doctor Jin'Zil, care locuieste in asezarea troll din Malaka'jin."},{t="Ecourile ghearelor Bloodfury",b="A ajunge la Jin'Zil, in pestera sa umbrita, dezvaluie un capitol mai vechi din istoria Horde. Auzind ca Serena Bloodfeather a cazut, doctorul vrajitor troll isi aminteste campania de odinioara, cand vanatorul umbrelor Rokhan si maestrul fiarelor ratacitor Rexxar au ucis-o pe sora mai mare a Serenei, Bloodfeather. Starpirea Serenei pune un fel de punct final dusmaniei indelungate dintre avanposturile de frontiera ale Horde si harpiile insetate de sange din Kalimdor."}},faq={{q="Cine ofera misiunea Letter to Jin'Zil?",a="Darsok Swiftdagger ofera misiunea la Crossroads, in Barrens. Ti-o da doar dupa ce inchei vanatoarea lui Serena Bloodfeather.",al={"datatorul misiunii","unde iei misiunea","cine incepe misiunea Scrisoare catre Jin'Zil"}},{q="Unde il pot gasi pe Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil locuieste intr-o pestera din Malaka'jin, o tabara de trolli Darkspear aflata chiar langa drumul principal care intra in Stonetalon Mountains din Barrens.",al={"unde se afla Jin'Zil","locatia lui Jin'Zil","locatia Malaka'jin"}},{q="De ce te trimite Darsok in Stonetalon Mountains?",a="Darsok vrea sa-i dea de veste vechiului sau prieten Jin'Zil ca amenintarea harpiilor a fost inlaturata odata cu moartea Serenei Bloodfeather si, totodata, sa indrume un aventurier capabil spre provocarile mai mari care asteapta Horde in muntii Stonetalon.",al={"de ce mergem la Stonetalon","de ce trimite Darsok o scrisoare"}},{q="La care sora mai mare a Serenei se refera Jin'Zil?",a="Jin'Zil o mentioneaza pe Bloodfeather, o harpie batrana care a terorizat Kalimdor cu ani in urma. A fost ucisa de Vanatorul umbrelor Rokhan si de razboinicul pe jumatate capcaun Rexxar, in timpul calatoriilor lor alaturi de Horde aflat la inceputuri.",al={"sora mai mare a Serenei","Rokhan si Rexxar si harpia","Bloodfury"}},{q="Face aceasta misiune parte dintr-o serie mai ampla?",a="Da. Este ultima misiune din lantul de vanatoare a harpiilor din nordul regiunii Barrens, dupa Harpy Raiders, Harpy Lieutenants si Serena Bloodfeather, si totodata o misiune de introducere in Stonetalon Mountains.",al={"lant de misiuni","cerinte preliminare","ce duce la asta"}},{q="Ce factiune poate indeplini aceasta sarcina?",a="Aceasta este o misiune exclusiv pentru Horde, deoarece atat Darsok Swiftdagger, cat si Witch Doctor Jin'Zil slujesc interesele Horde la granita.",al={"este doar pentru horde","poate alianta sa faca aceasta misiune"}}},fx={a93c7265={q="De ce are nevoie Darsok sa-i duci scrisoarea lui Jin'Zil?",a="Darsok Swiftdagger ramane stationat la Crossroads, unde vegheaza asupra nordului Barrens. Dupa ce te-a vazut curatand cu succes tinutul de harpiile witchwing si ucigand-o pe conducatoarea lor, Serena Bloodfeather, te considera un mesager incercat si capabil, care poate face fata drumului primejdios spre Stonetalon Mountains. Vestea caderii Serenei iti ofera si un pretext potrivit pentru a explora tinuturile de dincolo de campiile aride.",al={"de ce sa-i duc scrisoarea lui Jin'Zil","de ce nu poate Darsok sa livreze scrisoarea","de ce eu sa duc scrisoarea lui Jin'Zil"}}},fp="17,320,28.512.0,29.447.1,38.139.0,38.169.0,49.230.0,55.210.0,37.206.0,37.126.0"}
P.entries["quest:1061"] = {n="The Spirits of Stonetalon"}
P.entries["quest:1062"] = {n="Goblin Invaders",s="Goblin Invaders este o misiune Horde incredintata de Seereth Stonebreak, la granita dintre Barrens si Stonetalon Mountains. Ea ii trimite pe razboinicii Horde in Windshear Crag pentru a lovi direct taietorii de lemne ai Venture Company, care devasteaza vechile paduri ale regiunii.",h="Goblin Invaders este o misiune Horde incredintata de Seereth Stonebreak, la granita dintre Barrens si...",kw={"goblin","Greatwood Vale","taietor de lemne","Seereth Stonebreak","spirite","Stonetalon Mountains","Venture Company","Windshear Crag"},ang={["class:Druid"]="Distrugerea fara discernamant a crangurilor vii si macelarirea copacilor stravechi din Windshear Crag incalca in mod direct ordinea naturala pe care druizii au jurat sa o apere.",["class:Shaman"]="Shaman simt cu acuitate strigatele elementalilor locali si ale spiritelor naturii, orbite de furie din cauza fumului si a devastarii provocate de utilajele goblinilor.",["faction:Horde"]="Oprirea Venture Company asigura tinuturile de granita dintre Barrens si trecatorile inalte, impiedicand sindicatele comerciale ostile sa-si intareasca pozitiile in centrul Kalimdorului.",["race:Tauren"]="Pangarirea padurilor din Stonetalon si agonia spiritelor pamantului fac din infruntarea Venture Company o datorie urgenta pentru orice Tauren care o cinsteste pe Earth Mother."},sec={{t="O padure in agonie",b="Venture Company a patruns adanc in Stonetalon Mountains, croind fasii intinse de distrugere printre stanci si vai. Operatiunile lor de exploatare forestiera despaduresc versantii si dau foc tufarisului, lasand in urma cicatrice mocnite. Pentru tauren si aliatii lor, nu este vorba doar de o exploatare miniera si forestiera inestetica; spiritele primordiale legate de Stonetalon urla de durere. Seereth Stonebreak, stationata de-a lungul granitei muntilor, observa ca aceste spirite au orbit de agonie si furie in urma asaltului neincetat al goblinilor."},{t="Limbajul fortei",b="Apelurile la ratiune sau diplomatie nu inseamna nimic pentru directorii si angajatii fara scrupule ai Venture Company, a caror singura preocupare este profitul brut. Intelegand acest lucru, Seereth le porunceste calatorilor sa treaca de Greatwood Vale si sa ajunga direct in Windshear Crag pentru a ucide cincisprezece taietori de lemne. Raspunzand lacomiei corporatiste cu forta armelor, Horde urmareste sa opreasca defrisarea si sa le castige batranilor tauren timp pentru a linisti spiritele agitate ale tinutului."}},faq={{q="Cine este Seereth Stonebreak?",a="Seereth Stonebreak este o saman orc aflata langa granita sudica dintre Barrens si Stonetalon Mountains. Ea supravegheaza inaintarea factiunilor ostile si lucreaza pentru a proteja echilibrul spiritual al regiunii.",al={"Seereth Stonebreak","personajul care ofera misiuni","cine da misiunea Goblin Invaders"}},{q="De ce defriseaza goblinii Stonetalon Mountains?",a="Venture Company este o intreprindere lipsita de scrupule, manata de profit. Padurile stravechi si dese din Stonetalon, precum si dealurile bogate in minereuri, nu sunt pentru ei decat materii prime de recoltat, prelucrat si vandut celui care ofera mai mult, fara sa le pese catusi de putin de distrugerile naturale si spirituale lasate in urma.",al={"de ce taie copaci Venture Co","motivul exploatarii forestiere a Venture Company in Stonetalon","de ce taie copaci"}},{q="Unde se afla Windshear Crag?",a="Windshear Crag se afla in partea centrala a Stonetalon Mountains. Pentru a ajunge acolo de la granita cu Barrens, mergi spre nord-vest pe drumul montan prin Greatwood Vale, pana cand padurea verde si vibranta lasa locul taberelor mecanizate de exploatare forestiera si dealurilor defrisate ale Venture Company.",al={"locatia Windshear Crag","unde sunt taietorii de lemne","unde gasesc taietorii de lemne ai Venture Co"}},{q="Cum reactioneaza spiritele la prezenta Venture Company?",a="Potrivit lui Seereth Stonebreak, spiritele pamantului sunt impinse aproape de nebunie, de furia si durerea provocate de defrisarile si incendierile necontenite ale padurilor. Suferinta lor tulbura echilibrul natural, devenind o amenintare spirituala pentru intreaga regiune.",al={"spiritele din Stonetalon sunt furioase","reactia spiritelor din Stonetalon"}},{q="Ce se intampla dupa ce sunt starpiti taietorii de lemne ai Venture Company?",a="Eliminarea taietorilor de lemne este doar prima lovitura data operatiunii. Seereth indreapta apoi atentia Horde catre demontarea infrastructurii mecanizate a companiei si recomanda totodata ca eroul sa ceara indrumarea batranilor tauren, care il pot ajuta sa linisteasca spiritele ranite.",al={"dupa invadatorii goblini","urmatoarea misiune dupa taietori de lemne"}},{q="De ce ii pasa Horde de exploatarea forestiera in Stonetalon?",a="Stonetalon Mountains au o profunda insemnatate culturala si spirituala pentru tauren, in vreme ce Horde, in ansamblu, considera ca agresivitatea nestavilita a Venture Company si furtul resurselor reprezinta o amenintare la adresa influentei lor teritoriale si a armoniei spirituale.",al={"interesul horde in stonetalon","de ce se lupta horde cu venture co"}}},fx={c7723727={q="De ce vrea Seereth Stonebreak sa fie ucisi taietorii de lemne ai Venture Company?",a="Venture Company taie cu cruzime paduri si incendiaza intinse zone din Stonetalon Mountains. Distrugerea lor nesabuita i-a innebunit de durere cumplita si furie pe spiritele naturii din tinut. Seereth vrea ca taietorii de lemne sa fie doborati, pentru a opri jaful neintrerupt si a dovedi ca Horde nu va tolera pangarirea acestor pamanturi sacre.",al={"motivul lui Seereth Stonebreak","de ce sa omoram taietorii de lemne","de ce ii pasa lui Seereth de goblini"}},["4d329e4c"]={q="Cine sunt taietorii de lemne ai Venture Co.?",a="Taietorii de lemne din Venture Co. sunt muncitori si tehnicieni angajati de notoriul sindicat goblin. Manati doar de profit, au trecut dincolo de Greatwood Vale si au ajuns in Windshear Crag, unde taie copaci stravechi si folosesc utilaje grele fara sa tina seama de pamant sau de mania spiritelor sale bastinase.",al={"cine sunt taietorii de lemne","taietorii de lemne de la Venture Co","lucratorii Venture Company"}}},fp="15,271,17.565.0,21.450.0,26.230.0,53.293.0,32.286.0,59.241.0,55.285.1,52.252.0"}
P.entries["quest:1065"] = {n="Calatorie la Tarren Mill"}
P.entries["quest:1066"] = {n="Sangele Inocentilor"}
P.entries["quest:1067"] = {n="Intoarce-te la Thunder Bluff",s="Toxina apothecary Lydon este destinata pentru Thunder Bluff, unde Zamah o asteapta. Are nevoie de formula pentru a face un dispozitiv care sa-l raspandeasca impotriva companiei Venture.",h="Toxina apothecary Lydon este destinata pentru Thunder Bluff, unde Zamah o asteapta.",kw={"apothecary lydon","apothecary zamah","toxina lui Lydon","bazine de viziune","reveni la cacealma de tunet","societate regala de farmacie","moara tarren","aburitor toxic","companie de risc"},ang={["faction:Horde"]="Ca membru al Hoardei, ii vezi pe alchimistii Renuntati lucrand impreuna impotriva operatiunilor distructive ale Companiei Venture.",["race:Tauren"]="Ca Tauren, stii ca Magatha Grimtotem si batranii i-au intampinat pe Forsaken in Thunder Bluff, in speranta ca vor gasi mantuirea sau vindecarea. Apoticarii de sub Spirit Rise fac in schimb arme contagioase.",["race:Undead"]="In calitate de strigoi, puteti vedea cum Societatea Regala Apothecary leaga cercetarea din Lordaeron cu avanposturile de pe Kalimdor."},sec={{t="O livrare transcontinentala",b="Apothecary Lydon a facut toxina din ingredientele adunate la poalele Hillsbrad. Vrea sa-l vada testat pe subiecti vii, dar lichidul are nevoie de o modalitate de a-l raspandi. Porti fiola peste Marea Mare pana la Mulgore, unde o asteapta Apothecary Zamah."},{t="Aparatul lui Zamah",b="Apothecary Zamah lucreaza sub Spirit Rise in Thunder Bluff ca ambasador si cercetator pentru Royal Apothecary Society. Cu formula lui Lydon, ea face un dispozitiv de aerosoli numit Toxic Fogger. Ea intentioneaza sa-l foloseasca impotriva spiridusilor companiei Venture."}},faq={{q="Care este scopul aducerii toxinei in Thunder Bluff?",a="Lydon a facut toxina lichida, dar are nevoie de o modalitate de a se raspandi intr-o zona larga. Zamah poate transforma formula intr-un dispozitiv de aerosoli numit Toxic Fogger.",al={"de ce thunder bluff","ce face zamah cu toxina","utilizarea toxinei Lydons"}},{q="Cine este tinta acestui amestec?",a="Toxina este destinata Companiei Venture, un sindicat minier de goblin ale carui operatiuni ajung in Muntii Stonetalon si nu numai.",al={"cine se otraveste","tinta toxinei Lydon","cu cine ne luptam"}},{q="Unde se afla Apothecary Zamah?",a="Apothecary Zamah se afla in Pools of Vision, sub Spirit Rise, in Thunder Bluff.",al={"gasi zamah","unde este apoticarul zamah","locatie zamah"}},{q="De ce lucreaza farmacii Undercity intr-un oras Tauren?",a="Taureni le-au dat azil celor Parasiti si i-au ajutat sa se alature Hoardei, in speranta ca ar putea gasi un remediu pentru suferinta lor. Zamah reprezinta Societatea Regala Apothecary, a carei munca aici se indreapta spre ciuma si arme, mai degraba decat spre vindecare.",al={"parasit in thunder bluff","de ce sunt strigoii in thunder bluff","apoticarii in mulgore"}},{q="Ce se intampla dupa introducerea toxinei?",a="Dupa ce Zamah primeste flaconul, ea face Toxic Fogger. Apoi te trimite sa-l folosesti la o unitate Venture Company din Muntii Stonetalon.",al={"urmatoarea cautare","ce dupa intoarcerea la cacealma de tunet","quest fogger"}},{q="Cine a creat formula originala?",a="Apothecary Lydon, un cercetator al Royal Apothecary Society din Tarren Mill, a facut otrava.",al={"cine a facut otrava","cine este lydon","apothecary lydon lore"}}},fx={["4bd277bc"]={q="De ce vrea Apothecary Lydon ca acest lucru sa fie facut?",a="Apothecary Lydon abia asteapta sa-si vada amestecurile folosite in mod practic pe teren. Toxina sa ar trebui sa stinga violenta celor din Venture Company, lasandu-i slabiti si docili, insa nu poate fi folosita eficient de una singura. Trimiterea ei inapoi la Apothecary Zamah din Thunder Bluff ii va permite acesteia sa creeze o metoda de administrare adecvata, care sa-i maximizeze efectul si sa dea rezultate favorabile, poate chiar contagioase.",al={"de ce vrea Lydon asta","motivul lui Lydon","motivul Apothecary Lydon"}}},fp="23,164,27.269.0,17.259.1,59.153.0,37.129.0,34.81.0,56.239.0,40.146.1,33.88.0"}
P.entries["quest:1068"] = {n="Shredding Machines",s="Shredding Machines este o misiune a Horde care le cere aventurierilor sa vaneze doua utilaje forestiere specializate ale Venture Company in Windshear Crag. Indrumati de samanul Seereth Stonebreak, jucatorii lovesc in defrisarile mecanizate care chinuie spiritele bastinase din Stonetalon.",h="Shredding Machines este o misiune a Horde care le cere aventurierilor sa vaneze doua utilaje forestiere...",kw={"exploatarea forestiera","seereth stonebreak","masina de tocat","masini de tocat","stonetalon mountains","venture company","windshear crag","xt:4","xt:9"},ang={["class:Shaman"]="Seereth scoate in evidenta rezonanta profunda dintre magia spirituala si natura, amintindu-le shamanilor ca echilibrul elemental depinde de apararea spiritelor care locuiesc pe aceste meleaguri.",["faction:Horde"]="Pe masura ce Horde isi stabileste puncte de sprijin in Kalimdor, este esential sa fie tinuta in frau lacomia nestavilita a Venture Company, pentru a pastra tinutul si a asigura trecerea in siguranta prin Stonetalon.",["profession:Engineering"]="Mecanismele forestiere din seria XT demonstreaza designul avansat al tocatoarelor Goblin, imbinand fierastraiele hidraulice mecanice cu propulsia bruta cu abur.",["race:Tauren"]="Pangarirea padurilor stravechi din Stonetalon de catre utilajele gobline lipsite de suflet incalca in mod direct devotamentul taurenilor fata de Earth Mother."},sec={{t="Viziunea defrisarii",b="Aflat la granita prafuita dintre Barrens si Stonetalon Mountains, samanul orc Seereth Stonebreak asculta cu atentie taramul nevazut. In timp ce mare parte din glasul spiritual al tinutului Stonetalon este acoperit de haos, o viziune i s-a aratat cu o claritate infioratoare: masinarii in forma de om, care spinteca padurile stravechi cu o iuteala nefireasca. Marcate cu codurile mecanice XT:4 si XT:9, aceste tocatoare construite de goblini macelaresc padurile din Windshear Crag, starnind valuri de neliniste printre spiritele naturii din imprejurimi."},{t="Reducerea la tacere a fierastraielor",b="Pentru a opri prapadul, campionii Horde patrund adanc in Windshear Crag, la nord-vest de Greatwood Vale, unde opereaza Venture Company. Gasirea si distrugerea acestor utilaje forestiere da o lovitura puternica defrisarilor comerciale din munti. Desi doborarea lui XT:4 si XT:9 potoleste strigatele imediate ale spiritelor copacilor raniti, Seereth avertizeaza ca, daca Venture Company nu abandoneaza cu totul Stonetalon, pamantul va avea parte de atrocitati mult mai cumplite."}},faq={{q="Cine este Seereth Stonebreak?",a="Seereth Stonebreak este o samana orca, stationata la granita sudica a Stonetalon Mountains, langa Barrens. In rezonanta cu fortele elementale si spirituale ale tinutului, ea actioneaza ca un canal pentru spiritele chinuite ale padurii, care protesteaza impotriva expansiunii rapide a Venture Company.",al={"cine este seereth","seereth, cel care da misiunea","povestea lui seereth stonebreak"}},{q="Ce sunt XT:4 si XT:9?",a="XT:4 si XT:9 sunt utilaje specializate de taiat busteni, desemnate pentru acest scop, operate de Venture Company in Windshear Crag. Propulsate de motoare cu abur si pilotate de operatori goblini, aceste masini bipede doboara copaci stravechi mult mai repede decat ar putea vreodata muncitorii manuali.",al={"ce sunt shredder-ele","XT4 si XT9","tinte pentru shredder"}},{q="Unde se afla Windshear Crag?",a="Windshear Crag se afla in nordul Stonetalon Mountains, la nord-vest de Greatwood Vale. Venture Company l-a transformat intr-un vast bazin industrial pentru exploatarea lemnului.",al={"locatia Windshear Crag","unde gasesc tocatoarele","unde sunt masinile"}},{q="De ce ii pasa unui shaman de copaci si de magia druidica?",a="Dupa cum explica Seereth, comuniunea samanica cu spiritele este strans legata de magia naturii a druidilor. Trauma provocata padurilor vii isi face ecoul in taramul spiritual, permitandu-le samanilor perspicace sa auda vaietele spiritelor copacilor macelarite, alaturi de tulburarile elementale.",al={"de ce le pasa samanilor de copaci","legatura dintre samani si druizi","spiritele naturii si samanii"}},{q="Cine detine si opereaza aceste utilaje de tocat?",a="Tocatoarele apartin Venture Company, un conglomerat comercial lipsit de scrupule, condus de goblini si cunoscut in tot Azerothul pentru exploatarea nemiloasa a resurselor naturale pretioase, fara nicio grija pentru ecosistemul local sau pentru locuitorii stravechi.",al={"cine a creat XT:4","cine conduce tocatorii","tocatorii Venture Company"}},{q="Alungam Venture Company distrugand XT:4 si XT:9?",a="Nu. Desi distrugerea acestor utilaje emblematice linisteste spiritele plangatoare ale copacilor si da inapoi eforturile locale de exploatare forestiera, Venture Company isi mentine o vasta prezenta industriala in Windshear Crag, iar aparatorii salbaticiei trebuie sa continue sa-i reziste.",al={"pleaca Venture Company","dupa distrugerea masinilor","rezultatul misiunii"}}},fx={["0171bd6f"]={q="De ce vrea Seereth Stonebreak ca XT:4 si XT:9 sa fie distruse?",a="Ca saman acordat la lumea spiritelor, Seereth aude strigatele de agonie ale tinutului ranit din Stonetalon. Legatura fireasca dintre spiritualitatea samanica si echilibrul naturii ii ingaduie sa perceapa spiritele copacilor jelind in timp ce Venture Company distruge muntii. Intr-o viziune spirituala limpede, le-a vazut pe aceste doua masinarii ingrozitoare doborand copacii stravechi cu o viteza nefireasca. Pentru ea, distrugerea lor este o indatorire spirituala esentiala; daca masinariile isi continua masacrul neingradit al padurii, ranile tinutului s-ar putea sa nu se vindece niciodata.",al={"de ce sa distrugi taietoarele","motivul lui Seereth Stonebreak","de ce sa distrugi XT4 si XT9"}}},fp="18,276,25.542.0,18.473.0,26.280.0,23.261.0,24.198.0,53.275.0,38.236.0,61.255.0"}
P.entries["quest:1069"] = {n="Deepmoss Spider Eggs"}
P.entries["quest:107"] = {n="Note to William",s="\"Note to William\" este o insarcinare indeplinita pentru Gramma Stonefield, in sudul Elwynn Forest, pentru a ajuta doi indragostiti tinuti in secret, din familii aflate in conflict. Ducand mesajul lui Mildred la William Pestle, spiterul din Goldshire, aventurierii cauta o solutie alchimica pentru a-i uni pe tinerii Maybell si Tommy Joe.",h="\"Note to William\" este o insarcinare indeplinita pentru Gramma Stonefield, in sudul Elwynn Forest, pentru a...",kw={"elwynn forest","goldshire","gramma stonefield","lion's pride inn","maybell maclure","mildred stonefield","nota pentru william","tommy joe stonefield","william pestle"},ang={["faction:Alliance"]="Aventurierii Alliance care strabat Elwynn Forest ajuta adesea familiile de fermieri locale in momente de cumpana, in timp ce garzile oficiale se concentreaza doar asupra amenintarilor militare.",["race:Human"]="Dusmania neintrerupta dintre Stonefields si Maclures dezbina vecinii din Elwynn, facandu-i pe batranii intelegatori sa se bazeze pe curieri discreti."},sec={{t="Indragostiti sortiti pieirii in Elwynn",b="Familiile Stonefield si Maclure traiesc de ani intregi ca vecine in sudul Elwynn Forest, dar vrajba lor amara a facut imposibila orice relatie normala. Prinsi chiar la mijloc se afla tinerii Tommy Joe Stonefield si Maybell Maclure, a caror poveste de dragoste trebuie tinuta in cel mai adanc secret. In timp ce parintii lor nutresc resentimente neostoite, Gramma Mildred Stonefield se induioseaza de tinerii indragostiti si cauta o solutie neobisnuita pentru a-i uni."},{t="Un apel catre Goldshire",b="Crezand ca persuasiunea obisnuita nu va reusi niciodata sa impace familiile certate, Gramma Stonefield trimite un curier spre nord, la Lion's Pride Inn din Goldshire. Mesajul ei il cauta pe William Pestle, un alchimist si farmacist cu experienta, pe care Mildred il cunoaste de multi ani. Luand scrisoarea, William este miscat de necazurile lui Maybell si Tommy Joe si hotaraste sa-si foloseasca stiinta alchimica in sprijinul lor."}},faq={{q="Cine este William Pestle?",a="William Pestle este un alchimist si spiter care locuieste la Lion's Pride Inn din Goldshire. Este un vechi cunoscut al lui Gramma Mildred Stonefield si este renumit pentru leacurile din plante si potiunile speciale pe care le prepara.",al={"cine este william pestle","william pestle din goldshire","alchimist din goldshire"}},{q="Cine i-a trimis biletul lui William?",a="Gramma Mildred Stonefield, matriarha fermei Stonefield, a scris biletul. Intelegatoare fata de iubirea interzisa dintre Maybell Maclure si Tommy Joe Stonefield, ea spera ca William Pestle va putea gasi o solutie pentru a-i ajuta.",al={"cine a trimis biletul","biletul lui Gramma Stonefield","Mildred Stonefield"}},{q="De ce nu pot Maybell si Tommy Joe sa fie impreuna pe fata?",a="Maybell Maclure si Tommy Joe Stonefield sunt profund indragostiti, dar familiile lor sunt prinse intr-o rivalitate indarjita, care dureaza de multa vreme. Gramma Stonefield crede ca William Pestle ar putea cunoaste o potiune sau un plan care sa le permita celor doi indragostiti sa fie impreuna, in ciuda ostilitatii dintre familii.",al={"de ce sa le ajuti pe Maybell si Tommy Joe","misiunea indragostitilor din Elwynn","cearta dintre Stonefield si Maclure"}},{q="Unde poate fi gasit William Pestle?",a="William Pestle poate fi gasit in Lion's Pride Inn, taverna centrala si locul de intalnire din Goldshire, in Elwynn Forest.",al={"unde este william pestle","locatia lui pestle","alchimistul de la lion's pride inn"}},{q="Care este numele adevarat al lui Gramma Stonefield?",a="Prenumele ei este Mildred, dupa cum dezvaluie William Pestle, cand spune ca nu a mai vazut-o de ani de zile dupa ce primeste scrisoarea ei.",al={"care este prenumele lui Gramma Stonefield","numele lui Gramma Stonefield"}},{q="Cum reactioneaza William Pestle la bilet?",a="Dupa ce citeste scrisoarea lui Mildred, William remarca faptul ca n-a mai vazut-o de ani buni si se intreaba ce scrie in bilet, intrucat ea spera ca mestesugul lui alchimic i-ar putea ajuta pe indragostitii sortiti nenorocirii.",al={"ce face William cu biletul","reactia lui William Pestle"}}},fp="15,295,22.448.0,22.423.0,22.217.0,29.228.0,59.270.0,34.148.0,38.138.0,42.195.0"}
P.entries["quest:1070"] = {n="On Guard in Stonetalon",s="On Guard in Stonetalon este o misiune de indrumare a Alliance, care ii trimite pe aventurieri spre sud, din Ashenvale in muntii accidentati din Stonetalon Mountains. Sentinel Thenysil trimite calatorii sa verifice ce face prietena ei cercetasa, Kaela Shadowspear, trimisa printre stanci alaturi de un mag gnom pentru a supraveghea incursiunile industriale ale celor din Venture Company.",h="On Guard in Stonetalon este o misiune de indrumare a Alliance, care ii trimite pe aventurieri spre sud, din...",kw={"ashenvale","kaela shadowspear","on guard in stonetalon","sentinel thenysil","stonetalon mountains","venture co","windshear crag"},ang={["faction:Alliance"]="Aceasta sarcina marcheaza extinderea spre sud a securitatii de frontiera a Alliance, legand avanposturile de aparare din Ashenvale de punctele izolate de observatie din Stonetalon Mountains.",["race:Gnome"]="Sentinels privesc cu profund scepticism magia si masinariile gnomilor, considerand ca includerea unui mage gnome este o variabila ciudata si imprevizibila in salbaticia din Kalimdor.",["race:NightElf"]="Misiunea ilustreaza tensiunile dintre Sentinels traditionali ai elfilor noptii si practicile arcane, mecanice, ale aliatilor lor din Eastern Kingdoms, indeosebi ale gnomilor."},sec={{t="Un cercetas trimis spre sud",b="Aflata la post in Astranaar, Sentinel Thenysil vegheaza indeaproape asupra amenintarilor care se apropie de padurea straveche. Foarte ingrijorata pentru prietena ei Kaela Shadowspear, Thenysil le cere campionilor Alliance care trec prin zona sa o gaseasca. Sentinel Wolfrunner a trimis-o pe Kaela in Stonetalon Mountains sa cerceteze tulburarile tot mai mari din inaltimi, dar legatura s-a intrerupt, iar Thenysil se teme pentru siguranta ei."},{t="Aliante nesigure in creste",b="Ingrijorarea lui Thenysil este amplificata de insotitoarea desemnata Kaelei: o vrajitoare gnom, trimisa alaturi de ea de conducerea Alliance. Desi elfii noptii s-au alaturat Marii Aliante din necesitate strategica, multi dintre Sentinels raman profund neincrezatori in practicantii arcani si gnomii inventatori care umbla prin salbaticia neatinsa. Gasirea Kaelei pe stancile de deasupra Windshear Crag dezvaluie un avanpost care supravegheaza distrugerile ecologice pe scara larga provocate de Venture Company."}},faq={{q="Cine ofera aceasta misiune?",a="Misiunea este oferita de Sentinel Thenysil, o sentinel elf de noapte stationata in Astranaar, in Ashenvale.",al={"cel care ofera misiunea","de unde sa incep","cine incepe On Guard in Stonetalon"}},{q="Unde o pot gasi pe Kaela Shadowspear?",a="Kaela Shadowspear si-a stabilit tabara sus, pe o creasta stancoasa, de unde priveste intrarea in valea din Windshear Crag, in Stonetalon Mountains.",al={"locatia lui kaela","gaseste-o pe kaela","locul lui kaela shadowspear"}},{q="De ce este Sentinel Thenysil ingrijorata pentru Kaela?",a="Kaela a fost trimisa sa cerceteze incursiunile ostile si periculoase din Stonetalon, dar nu a mai trimis nicio veste. In plus, Thenysil este ingrijorata fiindca Alliance a asociat-o pe Kaela cu un mage gnome, combinatie pe care o considera un semn de necaz.",al={"de ce sa-ti faci griji","ingrijorarea lui Thenysil"}},{q="Ce amenintari sunt active in Stonetalon Mountains?",a="Muntii sufera mult din cauza Venture Company, un cartel goblin lipsit de scrupule, dedicat mineritului si exploatarii forestiere, care distruge salbaticia, dar si din cauza fiarelor native agresive si a fortelor rivale Horde care inainteaza dinspre sud.",al={"dusmanii din stonetalon","cine se afla in stonetalon"}},{q="Cine este Tara?",a="Tara este prenumele lui Sentinel Thenysil. Cand o intalnesti pe Kaela, ea se refera cu drag la vechea ei prietena drept Tara si isi exprima mandria ca aceasta coordoneaza iscoadele si aventurierii.",al={"cine este tara","tara mentionata"}},{q="Ce se intampla dupa ce o gasesti pe Kaela Shadowspear?",a="Ajungerea la Kaela incheie calatoria si deschide calea catre alte sarcini prin care o ajuti pe ea si pe partenerul ei gnom sa supravegheze amenintarile care se apropie in Windshear Crag.",al={"urmatoarea misiune","ce urmeaza"}}},fx={["96da069b"]={q="De ce are Sentinel Thenysil nevoie de un aventurier care sa o gaseasca pe Kaela?",a="Sentinel Thenysil isi indeplineste datoria in Ashenvale si nu-si poate parasi pur si simplu postul pentru a porni spre tinuturile invecinate. Cand vede un calator capabil, dornic sa cutreiere lumea, profita de ocazie pentru a recruta un cercetas independent, care poate trece granita in Stonetalon fara sa perturbe apararea locala a Sentinels.",al={"de ce ma trimit","de ce nu merge thenysil","de ce un aventurier"}}},fp="22,331,18.412.0,32.490.0,21.100.0,35.136.0,45.227.0,52.216.0,12.173.0,45.168.0"}
P.entries["quest:1071"] = {n="A Gnome's Respite",s="A Gnome's Respite este o misiune a Alliance oferita de inventatorul excentric Gaxim Rustfizzle in Stonetalon Mountains. Coplesit de expansiunea industriala rapida a Venture Company in Windshear Crag, Gaxim angajeaza aventurieri sa-i rareasca taietorii de lemne si defrisatorii, ca sa castige timp pentru a inventa noi mijloace de descurajare.",h="A Gnome's Respite este o misiune a Alliance oferita de inventatorul excentric Gaxim Rustfizzle in Stonetalon...",kw={"taietor de paduri","explozibili","gaxim rustfizzle","gnome","taietor de lemne","stonetalon","venture co","windshear crag"},ang={["profession:Engineering"]="Inginerii vor aprecia filosofia lui Gaxim, potrivit careia mecanismele si chimia pot rezolva crizele de mediu, precum si pasiunea lui pentru explozibili puternici.",["race:Gnome"]="Misiunea lui Gaxim intruchipeaza ambitia gnomica clasica: rezolvarea conflictelor filozofice stravechi dintre natura si civilizatie prin ingeniozitate superioara si putin explozibil puternic.",["race:NightElf"]="Desi sentinelele Kaldorei privesc de obicei cu profunda neincredere masinariile gnomilor, inaintarea neincetata a Venture Company face ca orice mijloc eficient de descurajare sa fie binevenit in Stonetalon."},sec={{t="O Alliance aflata in conflict",b="Gaxim Rustfizzle reprezinta Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. Aflat printre crangurile stravechi din Stonetalon, el sustine ca datoria sa este sa le demonstreze night elves care venereaza natura ca inventiile moderne ale gnomilor - imbinand magia, potiuni chimice si mecanica - le pot apara in mod activ tinuturile amenintate. Totusi, ritmul neobosit al Venture Company abia daca ii mai lasa timp sa-si creeze prototipurile dispozitivelor defensive."},{t="Castigand timp in Windshear Crag",b="Pentru a opri valul, Gaxim ii trimite pe aventurieri direct in mijlocul operatiunilor fumegande de la Windshear Crag. Atacand lucratorii forestieri si defrisatorii Venture Co. din prima linie, calatorii ii ofera lui Gaxim ragazul necesar pentru a-si organiza atelierul si a concepe urmatoarea linie de aparare: explozibili puternici, controlati si folositi strategic."}},faq={{q="Cine este Gaxim Rustfizzle?",a="Gaxim Rustfizzle este un mag si inventator gnome din Alliance, aflat in Stonetalon Mountains. El slujeste ca agent al Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, incercand sa-i ajute pe night elf impotriva cotropitorilor industriali.",al={"gaxim","cine este Gaxim Rustfizzle","cel care da misiunea gaxim"}},{q="De ce incearca un gnom sa protejeze padurile elfilor noptii?",a="Gaxim crede ca este de datoria lui sa le dovedeasca elfilor noptii sceptici ca stiinta avansata a gnomilor, mai exact arcanologia, alchimia si ingineria, poate coexista cu natura si poate contribui activ la apararea tinuturilor lor salbatice de exploatarea industriala necontrolata.",al={"de ce este un gnom in stonetalon","de ce sa-i ajuti pe Night Elves","ecologia gnomilor"}},{q="Cine este Venture Company din Windshear Crag?",a="Venture Company este un cartel comercial nemilos, condus de goblini, care extrage resursele si taie padurile din Windshear Crag. Manat doar de profit, a napadit valea cu taietori de lemne, defrisatori si utilaje grele de exploatare forestiera.",al={"Venture Co din Stonetalon","cine este Venture Co","spiridusii din Windshear Crag"}},{q="Unde pot fi gasiti taietorii de lemne si defrisatorii?",a="Acestia activeaza in tot Windshear Crag, bazinul puternic industrializat aflat chiar la est de pozitia lui Gaxim, de-a lungul drumului principal din Stonetalon Mountains.",al={"unde sunt taietorii de lemne","unde gasesti defrisatorii","locatia Windshear Crag"}},{q="Ce planuieste Gaxim sa faca dupa ce are timp sa se gandeasca?",a="Dupa ce muncitorii goblini au fost alungati, Gaxim intentioneaza sa-si refaca stocul de explozibili puternici, folosind detonari tintite in munti pentru a indeparta si a speria Venture Company din cranguri.",al={"planul lui Gaxim","continuarea misiunii Gnome Respite","planul explozibililor"}},{q="Ce este Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences?",a="Este o societate academica gnomica ce cerceteaza imbinarea vrajilor arcane, a amestecurilor chimice si a ingineriei mecanice pentru a rezolva probleme practice in tot Azerothul.",al={"adunarea gnomilor","adunarea arcaneologiei","ce este Enlightened Assembly"}}},fx={["8136de5d"]={q="De ce vrea Gaxim Rustfizzle sa reduca numarul membrilor din Venture Company?",a="Gaxim Rustfizzle considera ca este datoria sa, ca membru al Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, sa dovedeasca faptul ca ingeniozitatea gnomilor poate ocroti padurile sacre ale elfilor noptii. Defrisarile neincetate si rapide ale Venture Company il coplesesc intruna, nelasandu-i ragaz sa conceapa, organizeze si asambleze dispozitivele si explozibilii ingeniosi de care are nevoie pentru a schimba cursul luptei.",al={"de ce sa omori taietorii de lemne","motivul lui Gaxim","de ce sa reduci numarul celor din Venture Co"}},["7aed6e2a"]={q="De ce are Gaxim Rustfizzle nevoie de tine ca sa lupti impotriva goblinilor?",a="Gaxim este un inventator si cercetator, nu o armata intreaga de unul singur, iar in Stonetalon lucreaza fara sprijin militar important din partea Alliance. Intre paza taberei si incercarea de a concepe noi schite mecanice, pur si simplu nu poate tine piept singur taietorilor de lemne ai Venture Company, care navalesc fara incetare. Se bazeaza pe aventurieri priceputi ca tine pentru a le rari randurile, astfel incat sa se poata concentra asupra construirii mijloacelor de contracarare.",al={"de ce eu, Gaxim","de ce are Gaxim nevoie de ajutor","de ce sa trimita un aventurier"}}},fp="17,322,19.463.0,29.304.0,24.258.0,51.258.0,46.220.0,47.163.0,54.192.0,81.174.0"}
P.entries["quest:1072"] = {n="An Old Colleague",s="An Old Colleague este o misiune a Alliance oferita de inginerul gnome Gaxim Rustfizzle in Stonetalon Mountains. Dorind sa construiasca un dispozitiv de o putere extraordinara, Gaxim trimite un aventurier tocmai peste mare, la Ironforge, pentru a gasi o veche cunostinta capabila sa sintetizeze un amestec exploziv periculos. Indeplinirea acestei sarcini deschide calea spre obtinerea compusului chimic volatil cunoscut sub numele de Nitromirglyceronium.",h="An Old Colleague este o misiune a Alliance oferita de inginerul gnome Gaxim Rustfizzle in Stonetalon...",kw={"explozibili","gaxim rustfizzle","ironforge","lomac gearstrip","ng-5","nitromirglyceronium","stonetalon","tinker town"},ang={["faction:Alliance"]="Aceasta sarcina ii trimite pe aventurierii din Alliance intr-o calatorie de-a lungul continentului, din stancile primejduite ale Kalimdorului inapoi, la adapostul din Ironforge.",["profession:Engineering"]="Inginerii vor aprecia urmarirea neobosita a lui Gaxim si Lomac pentru putere de foc maxima, indiferent de dificultatile logistice primejdioase implicate.",["race:Gnome"]="O intreprindere gnomish emblematica, care implica legaturi academice la mare distanta, rivalitati excentrice si compusi explozivi periculos de instabili."},sec={{t="O reteta instabila",b="In timp ce se afla in muntii Stonetalon, Gaxim Rustfizzle concepe cel mai ambitios proiect ingineresc al sau de pana acum. Crearea unui mecanism de asemenea proportii necesita un combustibil specializat, cu mult peste praful de pusca obisnuit sau titeiul brut. Mai precis, Gaxim are nevoie de Nitromirglyceronium, cunoscut si sub numele de NG-5, un amestec exploziv suficient de puternic pentru a garanta rezultate devastatoare, daca totul decurge conform planului."},{t="Legatura cu Tinker Town",b="Prepararea NG-5 nu este deloc simpla, iar Gaxim cunoaste o singura minte capabila sa-l rafineze: un vechi cunoscut pe nume Lomac Gearstrip. Lomac locuieste departe, spre est, in cartierul gnomilor din Tinker Town, aflat adanc in fortareata montana Ironforge. Incredintat cu lunga calatorie, curierul ajunge acolo doar pentru a fi intampinat de suspiciunea imediata si intrebarile paranoice ale lui Lomac."}},faq={{q="Cine ofera misiunea An Old Colleague?",a="Misiunea este oferita de Gaxim Rustfizzle, un inginer gnom aflat in Stonetalon Mountains.",al={"cel care ofera misiunea","cine incepe An Old Colleague","misiunea lui Gaxim"}},{q="Unde il pot gasi pe Lomac Gearstrip?",a="Lomac Gearstrip poate fi gasit in Tinker Town, cartierul gnomilor din partea estica a orasului piticilor, Ironforge.",al={"unde este lomac","locatia lui Lomac Gearstrip","Lomac din Ironforge"}},{q="Ce este Nitromirglyceronium?",a="Nitromirglyceronium, cunoscut si ca NG-5, este un exploziv chimic extrem de volatil, conceput de Lomac Gearstrip si ravnit de Gaxim Rustfizzle pentru dispozitivele sale de mare putere.",al={"ce este ng-5","nitromirglyceronium","ng 5"}},{q="De ce ma trimite Gaxim tocmai la Ironforge?",a="Gaxim sustine ca Lomac Gearstrip este singura persoana capabila sa sintetizeze compusul specializat NG-5 necesar pentru alimentarea dispozitivului sau experimental.",al={"de ce sa calatoresti la Ironforge","de ce Lomac","de ce sa mergi in Tinker Town"}},{q="Ce se intampla dupa ce-l gasesti pe Lomac Gearstrip?",a="Dupa ce confirmi solicitarea lui Gaxim cu suspiciosul Lomac, acesta iti da misiunea Ineptitude + Chemicals = Fun, ca sa aduni reactivii periculosi necesari prepararii amestecului.",al={"misiunea urmatoare","ce urmeaza dupa An Old Colleague"}},{q="Ce factiune poate indeplini aceasta sarcina?",a="Aceasta este strict o misiune a Alliance, deoarece porneste de la un gnome Alliance-aligned din Stonetalon si se incheie in capitala Alliance, Ironforge.",al={"aceasta este doar pentru Alianta","varianta hoardei","poate Hoarda face asta"}}},fx={bce9e2b8={q="De ce are nevoie Gaxim Rustfizzle de tine, in loc sa mearga el insusi la Ironforge?",a="Gaxim Rustfizzle este ocupat sa cerceteze Stonetalon Mountains si sa pregateasca amplasarea tactica a dispozitivelor sale experimentale. Fabricarea explozivului de inalta calitate Nitromirglyceronium presupune o lunga calatorie inapoi, peste mare, pana la Tinker Town din Ironforge, asa ca se bazeaza pe un calator capabil sa se ocupe de treaba, in timp ce el ramane pe loc pentru a pregati operatiunea.",al={"de ce are nevoie Gaxim de mine","de ce sa trimita un aventurier la Ironforge","de ce nu poate Gaxim sa mearga la Lomac"}}},fp="16,436,17.404.0,22.393.0,37.98.0,33.133.0,28.176.0,48.150.0,43.179.0,38.153.0"}
P.entries["quest:1073"] = {n="Ineptitude + Chemicals = Fun",s="In cautarea unei contramasuri explozive impotriva Venture Company din Stonetalon Mountains, aventurierii din Alliance sunt trimisi peste mare, la Ironforge. Acolo, excentricul gnom Lomac Gearstrip se invoieste sa-si prepare inventia volatila, Nitromirglyceronium, cu conditia sa-i aduci reactivii alchimici necesari.",h="In cautarea unei contramasuri explozive impotriva Venture Company din Stonetalon Mountains, aventurierii din...",kw={"elixir de rezistenta minora","gaxim rustfizzle","ironforge","lomac gearstrip","potiune de mana","nitromirglyceronium","stonetalon","venture company"},ang={["faction:Alliance"]="Drumul lung de la Stonetalon la Ironforge scoate in evidenta dificultatile logistice ale sustinerii avanposturilor Alliance indepartate, raspandite prin Kalimdor ostil.",["profession:Engineering"]="Cand pulberea obisnuita de explozie nu poate strapunge otelul Venture Company, combinarea alchimiei ezoterice cu principiile ingineriei produce rezultate mult mai catastrofale.",["race:Gnome"]="Lomac intruchipeaza latura nestapanita si trasnita a ingeniozitatii gnomilor, punand mai presus randamentul chimic pur si aplicatiile teoretice decat siguranta sau prudenta diplomatica."},sec={{t="O solutie instabila",b="Gaxim Rustfizzle, aflat in trecatorile stancoase din Stonetalon Mountains, avea nevoie de explozibili puternici pentru cel mai avansat dispozitiv conceput de el pana atunci impotriva Venture Company. Pentru asta, a apelat la un fost coleg excentric, care locuia in Ironforge: Lomac Gearstrip. Lomac este creatorul Nitromirglyceronium, o substanta atat de instabila si distrugatoare prin natura ei, incat i se pare hilar ca cineva ar putea s-o foloseasca, indiferent cine ajunge sa fie aruncat in aer."},{t="Potiuni pentru artificii",b="Desi Lomac e nerabdator sa vada cum masinaria Goblin - si poate chiar aventurierul - este facuta bucati, atelierul sau din Ironforge a ramas fara substanta preparata. Inainte sa prepare un nou lot de Nitromirglyceronium, Lomac cere potiuni alchimice obisnuite: Minor Mana Potions si Elixirs of Minor Fortitude. In ochii lui, obligarea unui aventurier sa adune aceste ingrediente are un scop dublu: se asigura ca are reactantii necesari pentru reactie si dovedeste ca acesta are macar un strop de respect fata de mestesugul alchimiei."}},faq={{q="Cine este Lomac Gearstrip?",a="Lomac Gearstrip este un alchimist si inventator gnom excentric, aflat in capitala piticilor, Ironforge. Este un vechi coleg al lui Gaxim Rustfizzle si inventatorul Nitromirglyceronium, un compus exploziv extrem de instabil.",al={"lomac gearstrip","cine este lomac","gnom din Ironforge"}},{q="De ce vrea Lomac potiuni in locul pieselor standard de inginerie?",a="Lomac foloseste alchimia alaturi de cunostintele sale mecanice pentru a produce reactii volatile de inalta calitate. Energia magica a potiilor Minor Mana si umorile corporale stabilizatoare, potentate de elixirele Elixirs of Minor Fortitude, servesc drept reactivi de baza pentru amestecul sau specializat de Nitromirglyceronium.",al={"de ce potiuni","ingrediente alchimice","de ce potiuni de mana"}},{q="De ce sa trimiti un aventurier tocmai pana la Ironforge pentru asta?",a="Gaxim Rustfizzle este izolat in salbaticia din Stonetalon, fara acces la ateliere industriale sau chimice dotate cu utilaje grele. Lomac Gearstrip din Ironforge este singurul asociat in care are incredere - sau de care se teme indeajuns - ca sa detina un explozibil suficient de puternic pentru cel mai avansat dispozitiv al sau.",al={"de ce ironforge","de ce sa calatoresti atat de departe","gaxim spre ironforge"}},{q="Ce este Nitromirglyceronium?",a="Nitromirglyceronium este amestecul chimic exploziv patentat de Lomac Gearstrip. Este renumit pentru instabilitatea sa, iar Lomac il numeste cea mai mare creatie a sa.",al={"nitromirglyceronium","ce este explozibilul","suc exploziv de gnomi"}},{q="Este Lomac ingrijorat de Venture Company sau de padure?",a="Nicidecum. Lomac rade pe fata de ideea folosirii explozibililor puternici pentru a salva copacii. Singurul motiv pentru care vrea sa predea amestecul este perspectiva haotica de a-i vedea fie pe goblini, fie pe curier facuti bucati de o explozie.",al={"ii pasa lui lomac de natura","motivele lui lomac"}},{q="Trebuie sa fii alchimist pentru a indeplini aceasta sarcina?",a="Nu. Desi Lomac vorbeste despre punerea la incercare a priceperii tale in alchimie, accepta la fel de bine reactivi obtinuti prin comert, de la negustori sau de la alti mestesugari, atat timp cat primeste potiunile cerute de reteta sa.",al={"necesita alchimie","alchimie necesara"}}},fx={["04ca68af"]={q="De ce vrea Lomac Gearstrip ca acest lucru sa fie facut?",a="Lomac nu da doi bani pe Venture Company, soarta padurilor din Stonetalon sau vechiul sau cunoscut Gaxim Rustfizzle. Ceea ce-l incanta este haosul pur si potentialul exploziv. Accepta sa prepare volatilul Nitromirglyceronium doar pentru placerea perversa de a privi cum te faci bucati - pe tine sau pe goblini -, cu conditia sa-i aduci reactivii necesari pentru a-si reface proviziile.",al={"motivul lui lomac gearstrip","de ce sa-l ajuti pe lomac","de ce sa faci nitromirglyceronium"}},["23e9865b"]={q="La ce foloseste Minor Mana Potion?",a="Potiunile Minor Mana sunt reactivi lichizi esentiali in potiunea instabila a lui Lomac. Impreuna cu elixirurile de fortitudine, energia lor magica serveste drept catalizator vital, necesar pentru a sintetiza un nou lot de Nitromirglyceronium, inventia sa alchimica volatila si orgolioasa.",al={"la ce foloseste potiunea minora de mana","de ce sa folosesc o potiune minora de mana","potiunea de mana nitromirglyceronium"}},["2bdc95b5"]={q="La ce foloseste Elixir of Minor Fortitude?",a="Lomac are nevoie de Elixirs of Minor Fortitude ca ingrediente esentiale pentru prepararea Nitromirglyceronium. In reteta sa chimica excentrica, amestecul fortifiant alcatuieste o parte din baza reactiva necesara crearii compusului exploziv.",al={"utilizarea elixirului de tarie minora","de ce elixir de tarie minora","elixirul de tarie si Nitromirglyceronium"}},ba2add0a={q="De ce iti cere Lomac sa aduci potiuni in loc sa le ia singur?",a="Lomac a ramas complet fara provizii si nu simte nicio graba sa te ajute pe tine sau pe Gaxim pe cheltuiala lui. Punandu-te sa aduni sau sa prepari singur ingredientele, te obliga sa-ti dovedesti ingeniozitatea si priceperea in alchimie inainte sa-ti incredinteze creatia sa de pret si periculoasa.",al={"de ce are lomac nevoie de mine","de ce trebuie sa iau potiuni","de ce nu-si poate lua lomac singur potiuni"}}},fp="28,308,19.479.0,24.543.0,23.239.0,66.284.0,57.262.0,28.147.0,57.233.0,53.204.0"}
P.entries["quest:1074"] = {n="Ineptitude + Chemicals = Fun",s="Aceasta sarcina presupune livrarea unui recipient cu NG-5 instabil, de la inventatorul Lomac Gearstrip la Gaxim Rustfizzle, in Stonetalon Mountains. Gaxim are nevoie de acest produs chimic instabil pentru a crea un aprinzator puternic pentru mai multe carute pline cu dinamita. Explozia rezultata creeaza o diversiune esentiala pentru operatiunile Alliance din tinuturile stancoase disputate.",h="Aceasta sarcina presupune livrarea unui recipient cu NG-5 instabil, de la inventatorul Lomac Gearstrip la...",kw={"dinamita","inginerie","Gaxim Rustfizzle","Gnome","Lomac Gearstrip","NG-5","Nitromirglyceronium","Stonetalon"},ang={["faction:Alliance"]="Stonetalon este o frontiera disputata; o explozie uriasa le ofera agentilor Alliance ragazul de care au atata nevoie.",["profession:Engineering"]="Manevrarea lui NG-5 necesita intelegerea chimiei volatile si o mana sigura pentru a evita detonarea prematura.",["race:Gnome"]="Numai ambitia gnomilor ar putea considera o diversiune rezonabila aprinderea unor vagoane pline cu explozibili prin Nitromirglyceronium."},sec={{t="O livrare instabila",b="Ingineria gnomilor tine adesea geniul in echilibru pe muchia catastrofei, iar Nitromirglyceronium - sau NG-5 - nu face exceptie. Lomac Gearstrip iti inmaneaza compusul instabil cu un avertisment sever: manevreaza-l cu cea mai mare grija sau risti sa te faci bucati pe drumul inapoi spre Gaxim Rustfizzle."},{t="O reteta pentru diversiune",b="Dupa ce primeste intact canistrul, Gaxim Rustfizzle dezvaluie adevarata amploare a lucrarii sale. NG-5 este catalizatorul esential necesar pentru a detona vagoane intregi pline cu dinamita. Punand la cale o explozie colosala, Gaxim spera sa semene haos si sa induca in eroare inamicii din Stonetalon, in timp ce Alliance isi urmareste obiectivele regionale."}},faq={{q="Ce este NG-5?",a="NG-5, prescurtare de la Nitromirglyceronium, este un compus chimic extrem de volatil, creat de Lomac Gearstrip. Serveste drept catalizator de aprindere incontestabil pentru armamentul greu.",al={"ce este Nitromirglyceronium","NG-5","ce mi-a dat Lomac"}},{q="Cine este Gaxim Rustfizzle?",a="Gaxim Rustfizzle este un magician gnome postat in Stonetalon Mountains, unde coordoneaza eforturile de demolare ale Alliance si diversiuni tactice impotriva amenintarilor regionale.",al={"gaxim","cine este Gaxim Rustfizzle"}},{q="Cine este Lomac Gearstrip?",a="Lomac Gearstrip este un inginer si un asociat al lui Gaxim Rustfizzle, care pregateste periculosul compus NG-5 si il incredinteaza unor curieri de incredere.",al={"lomac","cine este lomac gearstrip"}},{q="De ce are Gaxim nevoie de atata putere exploziva?",a="Gaxim a pregatit mai multe carute incarcate cu dinamita. NG-5 furnizeaza scanteia puternica si de nadejde necesara pentru a le detona pe toate deodata, creand o diversiune coplesitoare.",al={"de ce carute pline cu dinamita","planul lui Gaxim","de ce explozia"}},{q="Este periculoasa transportarea substantei chimice?",a="Lomac avertizeaza explicit ca NG-5 este instabil si poate detona accidental, cu urmari catastrofale, daca este manevrat gresit; totusi, un curier sigur pe el il poate duce fara probleme la Gaxim.",al={"ng5 explodeaza","este NG-5 sigur"}},{q="Unde are loc aceasta livrare?",a="Livrarea se incheie la avanpostul lui Gaxim Rustfizzle, in trecatorile accidentate din Stonetalon Mountains.",al={"unde se afla Gaxim","locatia Stonetalon"}}},fx={cbbf8960={q="De ce iti da Lomac Gearstrip NG-5?",a="Lomac indeplineste o cerere a asociatului sau Gaxim Rustfizzle, furnizandu-i Nitromirglyceronium-ul volatil, asa cum i s-a cerut. Nu pune intrebari despre detalii: daca esti intr-adevar aliatul lui Gaxim, iti transmite salutari, iar daca esti un impostor, se multumeste sa te lase sa fii facut bucati de compusul exploziv.",al={"de ce ajuta Lomac","motivul lui Lomac Gearstrip","de ce da NG-5"}}},fp="28,331,19.305.0,24.316.1,13.171.0,24.165.0,23.143.0,44.177.0,39.163.0,36.103.0"}
P.entries["quest:1075"] = {n="A Scroll from Mauren",s="Gaxim Rustfizzle are nevoie de ajutor arcane pentru a-si declansa de la distanta explozibilii NG-5. Te trimite la Collin Mauren, in Stormwind, unde ingeniozitatea gnomilor se intalneste cu arta arcana a oamenilor.",h="Gaxim Rustfizzle are nevoie de ajutor arcane pentru a-si declansa de la distanta explozibilii NG-5.",kw={"collin mauren","devils in westfall","explozibili","gaxim rustfizzle","mage quarter","ng-5","remote detonator","stormwind"},ang={["class:Mage"]="Ca Mage, stii ca Kirin Tor si practicantii arcani din Stormwind colaboreaza cu inginerii. Ei aplica evocarea si transmutarea pentru a rezolva probleme mecanice.",["faction:Alliance"]="Ca membru Alliance, vezi mestesugari Gnome lucrand alaturi de vrajitorii Human care studiaza in Mage Quarter din Stormwind.",["profession:Engineering"]="Ca inginer, stii ca praful de pusca negru, instabil, si catalizatorii arcani pot rezolva probleme precum aprinderea de la distanta.",["race:Gnome"]="Ca Gnome, nu te sfiesti niciodata sa imbini tehnologia cu vrajitoria, daca astfel poti provoca o explozie mai catastrofala de la o distanta confortabila."},sec={{t="O scanteie peste mari distante",b="Gaxim Rustfizzle cauta o metoda mai sigura de a detona explozibilii NG-5. Fitilele mecanice nu-i pot oferi declansatorul de la distanta pe care-l doreste: un singur buton ar trebui sa aprinda incarcaturile in timp ce el ramane la o distanta sigura. Apeleaza la magia arcana pentru a rezolva problema."},{t="Legatura cu Mage Quarter",b="Gaxim te trimite la Collin Mauren, in Mage Quarter din Stormwind, pentru vrajile necesare. Mauren este un human vrajitor, iar cunostintele sale practice despre arcane ar putea ajuta la legarea unei aprinderi explozive de o comanda transmisa de la distanta. Munca sa da startul incantatiei de care are nevoie Gaxim pentru proiectul sau periculos."}},faq={{q="Cine ma trimite la Collin Mauren?",a="Gaxim Rustfizzle te trimite la Collin Mauren. Are nevoie de o formula arcana de la cunostinta sa Human pentru a termina un detonator cu temporizator.",al={"cel care da misiunea","cine da un pergament de la Mauren","misiunea lui Gaxim"}},{q="Unde poate fi gasit Collin Mauren?",a="Collin Mauren se afla in Mage Quarter din Stormwind City. Cauta-l printre instructorii, ucenicii si cercetatorii arcani din jurul turnurilor si magazinelor cartierului.",al={"locatia lui Collin Mauren","unde este Collin Mauren","gaseste-l pe Mauren"}},{q="De ce are Gaxim nevoie de o vraja pentru un dispozitiv exploziv?",a="Gaxim vrea sa-si detoneze explozibilii NG-5 cu un singur buton, de la o distanta sigura. El cauta cunostintele arcane ale lui Mauren pentru a declansa instantaneu explozia de la distanta, deoarece metodele mecanice pot fi greoaie sau nesigure la distante mari.",al={"de ce magie pentru bombe","poveste despre detonarea de la distanta","de ce sa vezi un Mage"}},{q="Ce este NG-5?",a="NG-5, sau Nitromirglyceronium, este un explozibil instabil preparat de Lomac Gearstrip din Ironforge, fost coleg al lui Gaxim. Gaxim are nevoie de un sistem de detonare de la distanta, astfel incat persoana care il declanseaza sa poata ramane mult in afara razei exploziei.",al={"ng-5","ce este ng5","explozibilul lui gaxim"}},{q="Ce urmeaza dupa ce vorbesti cu Collin Mauren?",a="Dupa ce Collin Mauren cugeta la cererea pentru o vraja de detonare la distanta, iti cere sa-l ajuti in Westfall, in Devils in Westfall.",al={"misiunea urmatoare","ce urmeaza dupa un sul de la Mauren","continuarea pentru Collin Mauren"}},{q="Este Collin Mauren un Gnome sau un Human?",a="Collin Mauren este un Mage Human. Gaxim observa ca Mauren ar trebui sa iasa usor in evidenta printre multimile din Stormwind pentru ca este Human.",al={"rasa lui Collin Mauren","ce rasa este Mauren","este Mauren Human"}}},fp="20,170,24.245.0,27.285.0,30.129.0,33.162.0,52.220.0,17.222.0,50.132.0,36.128.0"}
P.entries["quest:1076"] = {n="Devils in Westfall",s="Vartejuri de praf cutreiera Westfall, iar Collin Mauren are nevoie de ramasitele lor pentru o vraja. Vrajitorul din Mage Quarter il ajuta pe Gaxim Rustfizzle cu un experiment neobisnuit. Munca lor necesita un pergament de mesagerie, iar praful contine ceea ce ii trebuie lui Mauren pentru a-l vraji.",h="Vartejuri de praf cutreiera Westfall, iar Collin Mauren are nevoie de ramasitele lor pentru o vraja.",kw={"collin mauren","vartej de praf","resturi de vartej de praf","gaxim rustfizzle","mage quarter","vraja de comunicare","sul","stormwind","westfall"},ang={["class:Mage"]="Ca mage, vezi cum vrajitoria poate folosi rezonanta elementala salbatica pentru a lega o vraja de comunicare complexa intr-un pergament.",["faction:Alliance"]="Ca un calator din Alliance, treci de la turnurile din Stormwind la campurile neglijate din Westfall, unde tinutul de margine al regatului zace in ruine.",["profession:Engineering"]="Ca inginer, vezi cum munca lui Gaxim Rustfizzle se bazeaza pe arta pergamentelor arcane pentru a rezolva o problema de comunicare."},sec={{t="Componentele unui mesager",b="Collin Mauren pregateste un pergament de mesagerie pentru Gaxim Rustfizzle. Vrajitorul il ajuta pe mesterul inventator intr-o initiativa neobisnuita, dar vraja are nevoie de mai mult decat cerneala si pergament. Vartejuri de praf cutreiera Westfall, cu magie elementala invartindu-se in jurul lor. Ramasitele lor ofera mediul volatil de care Mauren are nevoie pentru a lega vraja lui Gaxim de pergament."},{t="Pustietatile elementale",b="Westfall a fost candva hambarul roditor al Stormwind. Seceta, banditismul si neglijarea au lasat campurile aride si salbatice. Vartejurile de praf ratacesc pe acolo si ameninta calatorii si colonistii izolati. Reziduurile lor contin esenta elementala concentrata de care are nevoie Mauren pentru a incheia vraja."}},faq={{q="Cine este Collin Mauren?",a="Collin Mauren este un mage Human din Mage Quarter al Stormwind. Lucreaza cu vrajitorii din oras si uneori ii ajuta pe cercetatori din afara, precum Gaxim Rustfizzle, sa pregateasca pergamente fermecate si componente arcane.",al={"Collin Mauren","cine da misiunea","mag din Stormwind"}},{q="De ce are nevoie Collin Mauren de resturi de diavol al prafului?",a="Collin Mauren are nevoie de resturi de diavol al prafului pentru a vraji un sul de mesaje pentru Gaxim Rustfizzle. Ramasitele contin energie elementala care ajuta la legarea vrajii de pergament.",al={"la ce folosesc resturile de la dust devil","pentru ce sunt resturile de la dust devil","de ce sa mergi in Westfall"}},{q="Unde pot fi gasiti diavolii de praf?",a="Vartejurile de praf bantuie campiile uscate si ogoarele sterpe din Westfall, mai ales pe intinderile prafuite dintre fermele neglijate de la sud de drumul spre Sentinel Hill.",al={"locatia dust devil","unde sunt dust devils","dust devils din Westfall"}},{q="Cine este Gaxim Rustfizzle?",a="Gaxim Rustfizzle este un inventator gnome ambitios, care lucreaza la proiecte de inginerie ezoterica. Collin Mauren il ajuta sa pregateasca suluri fermecate pentru experimentele sale.",al={"gaxim","gaxim rustfizzle","cine este gaxim"}},{q="Ce se intampla dupa ce duci ramasitele la Mauren?",a="Folosind ramasitele, Collin Mauren termina pergamentul cu mesajul si iti cere sa-l duci la Gaxim Rustfizzle, ca inventatorul sa-si poata continua experimentele.",al={"recompensa misiunii","ce urmeaza","dupa Devils in Westfall"}},{q="Sunt diavolii de praf creaturi magice sau naturale?",a="Vartejurile de praf sunt elementali minori ai aerului, care se arata sub forma unor tornade vii de nisip si pietris. Se dezvolta in peisajul uscat si instabil din Westfall.",al={"sunt diavolii de praf elementali","povestea diavolilor de praf"}}},fx={b0d4cd5a={q="La ce foloseste Dust Devil Debris?",a="Collin Mauren are nevoie de ramasitele unui vartej de praf, un reactiv esential pentru incantarea unui pergament special. Gaxim Rustfizzle are nevoie de o vraja de transmitere a mesajelor pentru experimentele sale neobisnuite, iar materialul elemental adunat de la creatura vartej ii permite lui Mauren sa imprime vraja pe pergament.",al={"la ce folosesc ramasitele dust devil","pentru ce sunt ramasitele","de ce sunt ramasitele dust devil"}},["9b2ec5a3"]={q="Ce sunt vartejurile de praf pe care le vanezi?",a="Vartejurile de praf sunt elementali ai aerului haotici, care cutreiera campiile aride si tinuturile agricole din Westfall. Starnite de vanturile turbulente si de magia salbatica din regiune, aceste vartejuri in miniatura se napustesc asupra oricaror calatori care le ies in cale, devenind un pericol letal atat pentru fermierii locali, cat si pentru drumeti.",al={"ce sunt diavolii de praf","tinte ale diavolilor de praf","cine sunt diavolii de praf"}}},fp="18,250,24.333.0,20.278.0,21.211.0,46.163.0,28.150.0,24.160.0,49.152.0,45.139.0"}
P.entries["quest:1077"] = {n="Special Delivery for Gaxim",s="Special Delivery for Gaxim reprezinta etapa de intoarcere a unei misiuni de curierat Alliance, intre Stormwind City si salbaticia din Kalimdor. Collin Mauren ii da un Scroll of Messaging special, care trebuie dus inapoi gnomului inventator Gaxim Rustfizzle din Stonetalon Mountains. Pergamentul contine componenta arcana necesara pentru a construi un exploziv cu actionare de la distanta, menit sa saboteze eforturile locale de defrisare.",h="Special Delivery for Gaxim reprezinta etapa de intoarcere a unei misiuni de curierat Alliance, intre...",kw={"collin mauren","gaxim rustfizzle","ng-5","exploziv cu detonare la distanta","scroll of messaging","stonetalon","venture co"},ang={["class:Mage"]="Mestesugul lui Collin Mauren arata cum incantatii simple aplicate pergamentului pot fi transformate in relee arcane functionale de catre inventatori iscusiti.",["faction:Alliance"]="Aceasta sarcina scoate in evidenta legaturile logistice dintre capitala umana Stormwind si avanposturile indepartate ale Alliance, care se lupta cu exploatarea industriala din Kalimdor.",["profession:Engineering"]="Planul lui Gaxim scoate in evidenta straniul punct de intalnire dintre ingineria gnomilor si vrajitorie, combinand explozibili NG-5 instabili cu declansatoare arcanice."},sec={{t="Livrari arcane",b="Eforturile lui Gaxim Rustfizzle de a sabota operatiunile distructive ale Venture Company cer solutii neobisnuite. Dupa ce a preparat un compus exploziv numit NG-5, inventatorul si-a dat seama ca nu avea o metoda sigura de detonare de la distanta. In loc sa recurga la fitiluri rudimentare, Gaxim a cerut ajutor dincolo de Great Sea, luand legatura cu Collin Mauren, din Mage Quarter of Stormwind, pentru a obtine un Scroll of Messaging vrajit."},{t="O diversiune indepartata",b="Dupa ce primeste sulul, Gaxim dezvaluie intregul plan al proiectului sau excentric de inginerie. Pergamentul fermecat nu serveste doar la transmiterea cuvintelor pe distante mari; magia lui comunicativa poate fi legata direct de amestecul instabil NG-5. Declansand de la distanta explozia prin magie, Gaxim vrea sa provoace o diversiune devastatoare, care sa le permita agentilor sa se strecoare neobservati in incinta Venture Company."}},faq={{q="La ce se foloseste Scroll of Messaging?",a="Desi a fost conceput initial ca instrument arcane pentru transmiterea mesajelor, Gaxim Rustfizzle combina pergamentul cu compusul sau volatil NG-5. Magia mesajelor actioneaza ca un declansator de la distanta, permitandu-i sa detoneze explozibilii in siguranta, de la departare.",al={"la ce foloseste scroll of messaging","ce face pergamentul","scopul lui scroll of messaging"}},{q="Cine este Collin Mauren?",a="Collin Mauren este un vrajitor din Alliance, cu sediul in Mage Quarter of Stormwind City. Ii ajuta pe aventurieri cu chestiuni arcane si faureste pergamentul fermecat necesar planului lui Gaxim din Stonetalon.",al={"povestea lui collin mauren","cine este collin"}},{q="De ce saboteaza Gaxim Rustfizzle Venture Company?",a="Venture Company taie fara mila padurile virgine din Stonetalon Mountains. Gaxim incearca sa le incetineasca defrisarile provocand haos, distrugandu-le operatiunile si furandu-le planurile tehnice proprietare si corespondenta.",al={"de ce sa ataci Venture Co","motivatia lui Gaxim","Venture Co in Stonetalon"}},{q="Unde il duce aceasta livrare pe aventurier?",a="Livrarea il duce pe curier din Stormwind City, peste mare, inapoi in tabara Alliance din stancariile muntilor Stonetalon Mountains, pe Kalimdor.",al={"destinatia livrarii","unde este Gaxim","locatia din Stonetalon"}},{q="Ce se intampla dupa ce pergamentul este livrat?",a="Cu pergamentul si NG-5 la indemana, Gaxim pregateste o diversiune exploziva controlata de la distanta, deschizandu-i calea unui agent sa se infiltreze in operatiunile din Windshear Crag si sa recupereze scrisori si scheme despre exploatarea lemnului.",al={"misiunea urmatoare","ce urmeaza dupa livrare","distragerea atentiei Venture Co"}}},fx={["89640f85"]={q="De ce vrea Collin Mauren ca acest lucru sa fie facut?",a="Collin Mauren ii este un coleg arcan si prieten de ajutor lui Gaxim Rustfizzle. In timp ce Collin ramane in siguranta in Stormwind, ocupandu-se de studiile sale magice, il intriga planul indraznet al lui Gaxim impotriva Venture Company in Kalimdor si ii ofera bucuros vraja necesara, asteptand cu nerabdare sa afle toate detaliile aventurii dupa ce aceasta se va incheia.",al={"motivul lui Collin Mauren","de ce il ajuta Collin pe Gaxim","de ce trimite Collin Mauren pergamentul"}}},fp="26,388,17.434.0,20.439.1,41.243.0,21.194.0,55.257.0,45.145.0,43.206.1"}
P.entries["quest:1078"] = {n="Retrieval for Mauren",s="Retrieval for Mauren este o misiune oferita de Collin Mauren in Mage Quarter of Stormwind. Dupa ce aude povesti despre calatorii care patrund adanc in Kalimdor, vrajitorul angajeaza aventurieri Alliance sa adune solzi cristalizati de la basilicii care salasluiesc in Charred Vale din Stonetalon. Mauren vrea sa macine aceste exemplare rare si sa le foloseasca drept reactivi pentru vrajile sale.",h="Retrieval for Mauren este o misiune oferita de Collin Mauren in Mage Quarter of Stormwind.",kw={"solzi de basilisc","Charred Vale","Collin Mauren","solzi cristalizati","Mage Quarter","Retrieval for Mauren","Stonetalon Mountains","Stormwind"},ang={["class:Mage"]="Sa procuri reactivi exotici pentru vrajitorii tai este un semn distinctiv al cercetarii arcane, aratand cum vietatile magice neobisnuite contribuie la dezvoltarea unor incantatii noi.",["faction:Alliance"]="Aceasta sarcina demonstreaza cum prezenta factiunii Alliance in Stormwind mentine active interesele si liniile de aprovizionare care se intind adanc in teritoriile salbatice din Kalimdor."},sec={{t="Reactivi neobisnuiti pentru un Mage",b="Collin Mauren, un vrajitor care locuieste in Mage Quarter of Stormwind City, trage cu urechea la zvonurile aventurierilor ratacitori. A aflat ca indepartatii Stonetalon Mountains din Kalimdor au devenit un punct de atractie tot mai popular pentru calatorii aflati in cautare de wyverni salbatici, elementali nestapaniti sau afaceri profitabile si confruntari cu Venture Company. Mauren nu cauta bogatii sau glorie; il intereseaza minunile naturale rare despre care se spune ca se gasesc in cele mai necrutatoare cotloane ale regiunii."},{t="Bestiile cristaline din vale",b="In adancul Stonetalon se afla Charred Vale, o intindere sufocata de cenusa si brazdata de devastarile Venture Company. Potrivit cercetarilor lui Mauren, bazinul era cunoscut odinioara ca salas al unei rase aparte de basilisc. Recoltati si macinati pana se transforma intr-o pulbere fina, solzii lor sunt un catalizator puternic pentru vrajile arcane specializate pe care le-a dezvoltat. Neavand certitudinea ca aceste creaturi au supravietuit transformarii brutale a Vaii, Mauren se bazeaza pe exploratori neinfricati, care sa adune un nou lot de solzi cristalizati si sa confirme daca rasa a dainuit."}},faq={{q="Cine este Collin Mauren?",a="Collin Mauren este un practicant al magiei arcane care se gaseste in Mage Quarter of Stormwind. Studiaza vrajitoria ezoterica si se bazeaza adesea pe calatori aventurosi pentru a-i procura reactivi magici rari din tinuturi indepartate.",al={"Collin Mauren","cine da misiunea Retrieval for Mauren","mauren in stormwind"}},{q="De ce are Collin Mauren nevoie de solzi de basilisc?",a="Mauren macina solzii cristalizati pana ii transforma intr-o pulbere fina, folosindu-le compozitia minerala unica drept catalizator pentru vrajile originale pe care le-a conceput.",al={"de ce solzi","la ce folosesc solzii","la ce se folosesc solzii cristalizati"}},{q="Unde se afla Charred Vale?",a="Charred Vale este un bazin ruinat, acoperit de funingine, aflat in regiunile sud-vestice ale Stonetalon Mountains, pe continentul Kalimdor.",al={"unde este charred vale","gaseste charred vale","locatia charred vale"}},{q="De ce este Charred Vale carbonizata?",a="Charred Vale a fost devastata de goblinii Venture Company, ale caror distrugeri au infuriat spiritele vaii si au dezlantuit elementalii, lasand pamantul innegrit, mocnind si populat de bestii rezistente si deformate.",al={"ce s-a intamplat cu Charred Vale","incendiul din Charred Vale","distrugerea din Charred Vale"}},{q="Ce creaturi lasa solzii necesari pentru aceasta sarcina?",a="Solzii sunt adunati de la basilicii care bantuie tinuturile parjolite din Charred Vale, in Stonetalon Mountains.",al={"care basiliskuri","cine lasa solzi cristalizati","inamici care lasa solzi"}},{q="De ce sa trimiti un aventurier tocmai peste mare pentru asta?",a="Proprietatile cristaline specifice de care are nevoie Mauren se gasesc doar la basilicii nativi din Charred Vale. Fiindca traversarea Great Sea este primejdioasa, Mauren recruteaza calatori experimentati care se indreapta deja spre Kalimdor.",al={"de ce Kalimdor","de ce Stonetalon pentru solzi"}}},fx={ae0c8dc0={q="De ce vrea Collin Mauren solzii de bazilisc?",a="Collin Mauren este un mag inventiv care locuieste in Stormwind si isi creeaza propriile vraji originale. A descoperit ca solzii cristalizati ai basiliscilor din Charred Vale, in Stonetalon, devin un reactiv magic ideal dupa ce sunt macinati fin. Pentru ca ramane in oras sa-si continue studiile arcane, se bazeaza pe calatorii care sa-i reaprovizioneze rezervele rare.",al={"motivul lui Collin Mauren","de ce vrea Mauren solzi","de ce sa adun solzi pentru Mauren"}},c10c105c={q="Ce creaturi vanezi in Charred Vale?",a="Esti trimis in adancurile parjolite din Charred Vale pentru a da de urma basiliscilor locali, care traiesc printre cenusa si ruinele elementale. Mauren isi aminteste din rapoartele vechi pieile lor unice, acoperite cu cristale, desi nu stie daca bestiile rezistente au supravietuit incendiului catastrofal care a mistuit valea.",al={"ce basilisc se gaseste in charred vale","pentru cine lupt pentru mauren","tinte basilisc stonetalon"}}},fp="20,365,25.480.0,29.553.0,21.210.0,44.154.0,34.142.0,32.215.0,52.126.0,59.227.0"}
P.entries["quest:1079"] = {n="Covert Ops - Alpha"}
P.entries["quest:1080"] = {n="Covert Ops - Beta",s="Covert Ops - Beta este o misiune a Alliance organizata de inginerul gnome Gaxim Rustfizzle in Stonetalon Mountains. Continuand actiunile anterioare de sabotaj impotriva Venture Company, aflata in expansiune, operatiunea trimite un agent adanc in Windshear Mine pentru a declansa diversiuni explozive si a extrage scrisori operationale esentiale. Informatiile recuperate servesc atat curiozitatii gnome, cat si apararii teritoriale a factiunii Sentinels din regiune, formata din night elf.",h="Covert Ops - Beta este o misiune a Alliance organizata de inginerul gnome Gaxim Rustfizzle in Stonetalon...",kw={"covert ops - beta","gaxim rustfizzle","santinele","stonetalon mountains","venture co.","venture co. letters","windshear crag","windshear mine"},ang={["faction:Alliance"]="Coordonarea tehnologiei gnomilor cu apararea teritoriului night elf consolideaza prezenta fragila a Alliance in centrul Kalimdorului.",["profession:Engineering"]="Misiunea se concentreaza pe echipamentul specializat Covert Ops Pack al lui Gaxim, aratand cum diversiuni pirotehnice ingenioase pot indeplini obiective pe care forta bruta nu le poate atinge singura.",["race:Gnome"]="Imbinarea explozibililor de mare randament, a planificarii minutioase si a infiltrarii clandestine de catre Gaxim Rustfizzle intruchipeaza ingeniozitatea tipic gnomica pusa in slujba scopurilor militare.",["race:NightElf"]="Venture Company rade padurile stravechi; sprijinirea operatiunilor secrete ale lui Gaxim le asigura comandantilor Sentinels informatiile necesare pentru a proteja muntele."},sec={{t="Sabotaj in adancuri",b="In urma primelor atacuri asupra operatiunilor de defrisare ale Venture Company din Windshear Crag, Gaxim Rustfizzle concepe o noua operatiune, indreptata chiar spre centrul logistic al companiei. Planul Beta urmeaza acelasi principiu ca planul precedent: crearea unei diversiuni explozive si haotice, care sa-i imprastie pe goblinii si mercenarii companiei, in timp ce un agent se strecoara printre ei si cauta corespondenta scrisa in mine."},{t="Cu ochii pe Windshear Mine",b="Windshear Mine se afla in extremitatea estica a crestei, servind drept baza subterana regionala a companiei. Sapand prin stanca si recoltand lemn, goblins tin registre stricte si pastreaza comunicatii detaliate despre rutele de aprovizionare si directivele conducerii. Strecurandu-se inauntru, amplasand pachetele speciale cu explozibili ale lui Gaxim si insusindu-si Venture Co. Letters, agentii dezmembreaza sistemul de securitate al companiei si ii descopera ambitiile mai largi din Kalimdor."},{t="Un parteneriat pragmatic",b="Desi Gaxim abordeaza misiunea cu bucuria tipic gnomilor pentru pirotehnie si gadgeturi ingenioase, aceasta are implicatii strategice serioase pentru night elves. Sentinels din Stonetalon, conduse de comandanti precum Kaela Shadowspear, se lupta cu greu atat impotriva Horde, cat si a exploatatorilor industriali lipsiti de scrupule. Informatiile recuperate din mina ii ajuta direct pe Sentinels sa prevada si sa impiedice pangarirea padurilor lor sacre."}},faq={{q="Care este obiectivul misiunii Covert Ops - Beta?",a="Obiectivul este sa te infiltrezi in Windshear Mine, in estul Windshear Crag, sa declansezi diversiuni explozive folosind pachetul lui Gaxim Rustfizzle si sa furi Venture Co. Letters, care descriu operatiunile lor din regiune.",al={"obiectivul operatiunii secrete beta","ce trebuie sa fac in Covert Ops Beta","scopul planului beta"}},{q="Cine este Gaxim Rustfizzle?",a="Gaxim Rustfizzle este un inginer gnom stationat in Stonetalon Mountains. Isi foloseste priceperea mecanica si inventiile explozive pentru a-i ajuta pe Sentinels night elf in lupta impotriva exploatarilor forestiere si miniere care pun stapanire pe munte.",al={"gaxim rustfizzle","cine ofera covert ops beta"}},{q="Unde se afla Windshear Mine?",a="Windshear Mine este sapata in munti, la capatul estic al Windshear Crag, ascunsa in adancul vastei zone defrisate de Venture Company.",al={"locatia Windshear Mine","unde se afla mina"}},{q="De ce isi doreste Gaxim Venture Co. Letters?",a="Scrisorile contin informatii esentiale despre rutele de aprovizionare ale Venture Company, directivele conducerii si planurile operationale. Recuperarea lor ii ajuta pe cei din Alliance si pe Sentinels sa anticipeze urmatoarele miscari ale companiei si sa-i zadarniceasca exploatarea padurii.",al={"de ce sa furi scrisori","ce sunt scrisorile celor din Venture Co"}},{q="Cum le este de folos aceasta misiune Night Elves?",a="Sentinels, elfii noptii, nu sunt destui pentru a pazi fiecare colt din Stonetalon de pustiirea industriala. Sabotajul exploziv al lui Gaxim intarzie lucrarile de taiere a copacilor, iar corespondenta recuperata le ofera comandantilor Sentinels, precum Kaela, informatii utile despre inamici.",al={"de ce le pasa Night Elves","operatiuni secrete ale santinelelor"}},{q="Ce a fost Plan Alpha?",a="Plan Alpha a fost operatiunea clandestina anterioara a lui Gaxim: o diversiune exploziva la gaterul Venture Company de la sud de Cragpool Lake, in timp ce un agent fura planurile tehnice ale companiei. Plan Beta repeta aceeasi tactica la Windshear Mine.",al={"planul alfa","operatiunea secreta alfa","misiunea anterioara"}}},fx={c7fb3974={q="La ce folosesc Venture Co. Letters?",a="Aceste documente contin comunicari si planuri esentiale ale conducerii Venture Company din Windshear Mine. Punandu-le mana, Gaxim Rustfizzle si Sentinels locali, elfi ai noptii, spera sa descopere operatiunile profanatorilor, sa le zadarniceasca exploatarile forestiere si miniere agresive din Stonetalon si sa le redea aparatorilor Kaelei un avantaj tactic esential.",al={"la ce folosesc scrisorile venture co","de ce sunt scrisori de la venture co","ce sunt scrisorile"}},["2e3cb5f9"]={q="Pe cine te infiltrezi la Windshear Mine?",a="Ataci Venture Company, un cartel comercial fara scrupule, condus de goblini si vestit pentru exploatarea nemiloasa a resurselor. S-au inradacinat in Windshear Crag, sfasiind pamantul, exploatand padurile sacre si ignorand drepturile elfilor noptii asupra acestor tinuturi sfinte, pana cand au transformat intreaga regiune intr-un pustiu industrial.",al={"dusmanii din Windshear Mine","cine se afla la Windshear Crag","Venture Co din Stonetalon"}}},fp="17,437,22.441.0,22.464.0,23.459.0,38.204.0,24.241.0,32.163.0,44.259.0,46.278.0,20.244.0"}
P.entries["quest:1081"] = {n="Reception from Tyrande",s="Reception from Tyrande este o misiune Alliance care ii trimite pe aventurieri de pe versantii greu incercati ai Stonetalon Mountains direct in capitala elfilor noptii, Darnassus. Dupa ce ii ajuta pe Sentinels sa-si asigure capul de pod precar din Stonetalon impotriva Venture Company, aventurierii sunt trimisi de Sentinel Thenysil, din Astranaar, sa primeasca recunoasterea oficiala chiar de la Mare Preoteasa Tyrande Whisperwind, in Temple of the Moon.",h="Reception from Tyrande este o misiune Alliance care ii trimite pe aventurieri de pe versantii greu incercati...",kw={"darnassus","kaldorei","reception from tyrande","sentinel thenysil","stonetalon mountains","teldrassil","temple of the moon","tyrande whisperwind"},ang={["faction:Alliance"]="O audienta cu Tyrande Whisperwind creeaza o legatura semnificativa intre night elves din Kalimdor si Alliance in ansamblu, transformand incaierarile din salbaticie intr-o slujire recunoscuta pentru Darnassus.",["race:NightElf"]="Sa te prezinti in fata lui High Priestess Tyrande Whisperwind, in Temple of the Moon, inseamna o intoarcere triumfala acasa, care-ti dovedeste devotamentul fata de apararea tinuturilor stramosesti stravechi."},sec={{t="Un punct de sprijin in Stonetalon",b="Avanposturile elfilor noptii raspandite prin Stonetalon Mountains se confrunta cu o presiune intensa, mai ales din partea Venture Company, care devasteaza tinutul. Sentinel Thenysil coordoneaza eforturile din Astranaar, insa mentinerea acestor baze indepartate necesita o rezistenta extraordinara. Asigurarea liniilor de aprovizionare si obtinerea de informatii sunt vitale pentru mentinerea prezentei Alliance in interiorul Kalimdor, astfel ca ajutorul din afara are un impact deosebit de mare asupra Santinelelor stationate acolo."},{t="Audienta cu Marea Preoteasa",b="Recunoscand ca ajutorul tau a intarit in mod concret controlul Sentinels asupra regiunii, Sentinel Thenysil iti cere sa te intorci in Teldrassil. La Temple of the Moon din Darnassus, High Priestess Tyrande Whisperwind iti acorda o audienta privata. Tyrande iti recunoaste faptele tot mai numeroase din Kalimdor si te primeste nu doar ca pe un mercenar ratacitor, ci ca pe un campion aliat care lupta alaturi de kaldorei."}},faq={{q="Unde incepe aceasta misiune?",a="Misiunea incepe cu Sentinel Thenysil in Astranaar, in Ashenvale, imediat dupa incheierea misiunii 'Update for Sentinel Thenysil'.",al={"de unde obtin Reception from Tyrande","cel care ofera misiunea","locatia lui Sentinel Thenysil"}},{q="Unde o pot gasi pe Tyrande Whisperwind?",a="Tyrande Whisperwind locuieste in Temple of the Moon, aflat in districtul central al capitalei night elves, Darnassus, pe Teldrassil.",al={"unde este Tyrande","gaseste-o pe Tyrande","locatia Temple of the Moon"}},{q="De ce vrea Tyrande sa ma vada?",a="Eforturile tale din Stonetalon au contribuit la pastrarea avanpostului Kaldorei pe teritoriul disputat din munti. Sentinel Thenysil considera ca aportul tau in slujba night elves merita un simbol personal de recunostinta din partea conducatorului lor spiritual si militar.",al={"de ce vrea tyrande sa vorbeasca","scopul audientei"}},{q="Ce valoare strategica au Stonetalon Mountains?",a="Stonetalon formeaza o zona-tampon accidentata intre Ashenvale si campiile sudice din Kalimdor. Cu fortele Horde inaintand din Barrens, mentinerea avanposturilor de aici este esentiala pentru ca elfii noptii sa supravegheze miscarile inamicului si sa apere tinuturile sacre.",al={"de ce sa-ti pese de Stonetalon","povestea Stonetalon"}},{q="Sunt recunoscute aici si alte rase ale Alliance?",a="Da. Orice aventurier Alliance care o ajuta pe Sentinel Thenysil poate intreprinde aceasta calatorie spre Darnassus, simbolizand apararea reciproca tot mai stransa dintre elfii noptii si restul Alliance.",al={"pot face asta si cei care nu sunt Night Elves","este pentru oameni"}},{q="Exista o misiune de continuare dupa intalnirea cu Tyrande?",a="Aceasta audienta incheie misiunile de curierat si sprijin din Stonetalon pentru Sentinel Thenysil, oferind o incheiere oficiala si prilejul de a cere ordine suplimentare in Darnassus.",al={"ce urmeaza","urmatoarea misiune din lant"}}},fx={e0e9e6b4={q="De ce te trimite Sentinel Thenysil in Darnassus?",a="Sentinel Thenysil crede ca eforturile tale au pus bazele consolidarii pozitiei Night Elves in Stonetalon Mountains, macinati de lupte. Recunoscandu-ti devotamentul in lupta impotriva atrocitatilor care au loc in munti, doreste sa primesti recunoastere oficiala si multumiri direct de la conducatoarea Night Elf, High Priestess Tyrande Whisperwind.",al={"de ce ma trimite Thenysil","motivul lui Thenysil pentru Tyrande","de ce sa merg la Tyrande"}}},fp="22,428,24.449.0,32.423.0,28.138.0,37.148.0,32.247.0,56.243.0,44.188.0,49.198.0"}
P.entries["quest:1082"] = {n="Update for Sentinel Thenysil",s="Aceasta misiune poarta vesti de alinare din stancariile Stonetalon inapoi la avanpostul elfilor noptii din Astranaar. Dupa ce ai ajutat-o pe Kaela Shadowspear si pe Gaxim Rustfizzle impotriva companiei Venture Company care se apropia, ti se cere sa o asiguri pe Sentinel Tara Thenysil ca avanpostul lor rezista.",h="Aceasta misiune poarta vesti de alinare din stancariile Stonetalon inapoi la avanpostul elfilor noptii din...",kw={"Ashenvale","Astranaar","Gaxim Rustfizzle","Kaela Shadowspear","Sentinel Thenysil","Stonetalon","Update for Sentinel Thenysil","Venture Co"},ang={["faction:Alliance"]="Mentinerea comunicarii intre avanposturile de frontiera din Stonetalon si fortaretele din Ashenvale ajuta la consolidarea prezentei Alliance in centrul Kalimdorului.",["race:Gnome"]="Chiar si Sentinel Thenysil recunoaste cu reticenta ca se bucura ca Gaxim Rustfizzle este in siguranta, demonstrand ca ingeniozitatea gnomilor poate castiga respect chiar si in randul elfilor traditionalisti.",["race:NightElf"]="Vestea ca Kaela a supravietuit ii linisteste pe Sentinels, caci stapanirea lor asupra tinuturilor de frontiera din Kalimdor nu a cedat in fata expansiunii industriale."},sec={{t="O depesa din piscuri",b="Trecatorile zimtate din Stonetalon constituie o frontiera izolata si vulnerabila pentru night elf. Operatiunile de defrisare ale goblinilor devoreaza stancile si polueaza cursurile de apa, iar avanpostul aparat de Kaela Shadowspear si mesterul gnom Gaxim Rustfizzle este amenintat fara incetare. Dupa ce se diminueaza primejdiile imediate reprezentate de Venture Company, e esential sa fie tinuta la curent lantul de comanda. Kaela te trimite spre nord-est, peste granita, inapoi in Ashenvale, ca sa confirmi ca au supravietuit."},{t="Ajutor in Astranaar",b="In sanctuarul impadurit din Astranaar, Sentinel Tara Thenysil vegheaza asupra drumurilor din interiorul Ashenvale si isi face griji pentru cercetasii trimisi in tinuturi mai aspre. Confirmarea ca atat Kaela, cat si excentricul ei partener inginer sunt in viata si lucreaza activ la vindecarea pamantului este o veste buna, rara. Dovedeste ca, in ciuda fortelor tot mai putine si a mai multor fronturi ostile, cooperarea cu aliatii din Alliance poate opri valul de distrugere ecologica."}},faq={{q="Cine este Sentinel Thenysil?",a="Tara Thenysil este o ofiter al Sentinels-ilor Night Elf stationati in Astranaar, principalul centru al Alliance-ului din Ashenvale. Ea supravegheaza starea cercetasilor si a patrulelor trimise in tinuturile salbatice din imprejurimi si in regiunile invecinate.",al={"Sentinel Thenysil","Tara Thenysil","Thenysil din Astranaar"}},{q="De ce se afla Kaela Shadowspear in Stonetalon Mountains?",a="Kaela Shadowspear a fost trimisa in Stonetalon pentru a supraveghea si combate exploatarea distructiva a mediului desfasurata de Venture Company. Lucreaza alaturi de gnomul Gaxim Rustfizzle pentru a sabota utilajele goblinilor si a reda viata tinutului.",al={"kaela shadowspear","misiunea lui kaela","de ce este kaela in stonetalon"}},{q="Cine este Gaxim?",a="Gaxim Rustfizzle este un inginer gnome din Alliance, aflat in Stonetalon alaturi de Kaela Shadowspear. Desi meseria sa zgomotoasa contrasteaza cu firea traditionala a elfilor, priceperea lui tehnica este esentiala pentru sabotarea utilajelor goblinilor care exploateaza lemnul.",al={"gaxim","gaxim rustfizzle","gnomul cu kaela"}},{q="Unde o gasesc pe Sentinel Thenysil?",a="Sentinel Thenysil este postata in Astranaar, asezata de-a lungul drumului central din Ashenvale, la nord-est de poteca ce coboara din Stonetalon Mountains.",al={"unde se afla Thenysil","locatia Thenysil","unde se afla Astranaar"}},{q="Ce se intampla dupa ce raportezi inapoi la Sentinel Thenysil?",a="Raportarea succesului din Stonetalon catre Sentinel Thenysil deschide noi oportunitati in cadrul armatei elfilor noptii si conduce la comunicari de rang inalt cu conducerea din Darnassus.",al={"urmatoarea misiune dupa Thenysil","incotro merg mai departe","Reception from Tyrande"}},{q="De ce reprezinta Venture Company o amenintare in Stonetalon?",a="Venture Company defriseaza fara mila crangurile sacre, foloseste utilaje masive de exploatare forestiera si otraveste cursurile de apa din Stonetalon, reprezentand o amenintare directa la adresa echilibrului natural pe care il apara elfii noptii.",al={"venture co stonetalon","de ce sa lupti cu venture co"}}},fx={be49c188={q="De ce vrea Kaela Shadowspear sa fie livrata aceasta actualizare?",a="Aflati departe, in Stonetalon Mountains disputati, Kaela si Gaxim au ramas izolati in timp ce incercau sa opreasca distrugerile aduse mediului de Venture Company. Kaela are nevoie ca cineva sa duca vestea inapoi la Astranaar, pentru ca liderii Sentinel sa stie ca misiunea lor continua si da roade, nu ca s-au pierdut in salbaticie sau au cazut prada masinariilor goblinilor.",al={"de ce sa trimiteti o actualizare lui Thenysil","motivul Kaelei Shadowspear","de ce se raporteaza la Astranaar"}},["9e9209a2"]={q="De ce te trimite Kaela in loc sa mearga ea insasi?",a="Kaela si Gaxim nu-si pot abandona postul. Defrisarile si mineritul celor din Venture Company reprezinta o amenintare directa si imediata pentru Crag si piscurile din jur. Daca ar pleca acum, ar ceda terenul greu castigat pe care tocmai i-ai ajutat sa-l asigure, asa ca se bazeaza pe un calator priceput ca tine sa duca mesajul spre nord.",al={"de ce nu trimitem o sentinel","de ce nu poate Kaela sa raporteze","de ce are Kaela nevoie de mine"}}},fp="28,285,25.503.0,19.471.0,25.217.0,49.241.0,13.246.0,34.156.0,55.186.0,50.211.0"}
P.entries["quest:1083"] = {n="Enraged Spirits",s="Enraged Spirits este o misiune Alliance oferita de Kaela Shadowspear in Stonetalon Mountains. Dupa ce Venture Company a pustiit Charred Vale cu foc si utilaje grele, elementari de foc furiosi s-au eliberat si au napadit bazinul devastat. Campionilor Alliance li se cere sa potoleasca aceste spirite ratacitoare de flacara si piatra, pentru ca pamantul ranit sa se poata vindeca intr-o buna zi sub harul lui Elune.",h="Enraged Spirits este o misiune Alliance oferita de Kaela Shadowspear in Stonetalon Mountains.",kw={"charred vale","elune","spirite infuriate","elementali de foc","kaela shadowspear","smoldering embers","stonetalon mountains","venture co"},ang={["class:Druid"]="Druizii considera elementalii dezlantuiti ai focului o perturbare catastrofala a echilibrului naturii, ce necesita interventie activa inainte ca viata sa poata reveni in sol.",["class:Shaman"]="Shamanii inteleg ca furia elementalilor este o reactie directa si chinuitoare la exploatarea nechibzuita a pamantului de catre mineri si taietori de lemne muritori.",["faction:Alliance"]="Alliance lucreaza prin intermediul santinelelor night elf din Stonetalon pentru a tine sub control haosul provocat de cartelurile goblinilor si a reda siguranta trecatorilor montane.",["race:NightElf"]="Pentru elfii de noapte, devastarea din Charred Vale este o rana sfasietoare, provocata tinuturilor salbatice sacre din Kalimdor de lacomia industriala scapata de sub control."},sec={{t="O tragedie mistuita de flacari",b="Charred Vale a fost candva un refugiu luxuriant in Stonetalon, dar lacomia nesabuita a Venture Company l-a transformat intr-un pustiu cenusiu. In goana lor dupa lemn si resurse, goblinii au folosit dispozitive incendiare si utilaje grele, care au mistuit intreaga bolta de frunzis. Amestecul lor distructiv nu a nimicit doar copacii, ci a zdruncinat si fragilul echilibru elemental de sub pamant."},{t="Furie dezlantuita",b="Planul goblinilor a esuat. Incendiul si excavatiile adanci au trezit din strafunduri spirite stravechi si adormite ale focului, pietrei si furiei. Elementalii furiosi s-au intors numaidecat impotriva intrusilor, alungand Venture Company si revendicand craterul mocnit. Kaela Shadowspear deplange faptul ca natura nu-si va putea reveni pana cand acesti elementali haotici nu vor fi nimiciti."}},faq={{q="Cine ofera misiunea Enraged Spirits?",a="Kaela Shadowspear, o santinela Night Elf stationata in Stonetalon Mountains, le ofera aceasta misiune aventurierilor Alliance care cauta sa ajute tinutul.",al={"cel care da misiunea","unde poti obtine Enraged Spirits","cine incepe Enraged Spirits"}},{q="De ce sunt in toiul dezlantuirii elementalii focului in Charred Vale?",a="Venture Company a ras padurea si i-a dat foc folosind utilaje distructive. Metodele lor industriale invazive au tulburat pamantul si au dezlantuit spirite latente ale focului, pietrei si furiei, care au coplesit rapid zona.",al={"de ce sunt elementali aici","ce a cauzat aparitia elementalilor de foc","spirite de foc din Charred Vale"}},{q="Ce s-a intamplat cu Venture Company in Charred Vale?",a="Gobolinii au incendiat padurea, insa neglijenta lor a dezlantuit elementali mult mai periculosi decat se asteptau. Fiintele de foc furioase le-au coplesit operatiunile, lasand in urma tabere distruse si ruine in flacari.",al={"soarta Venture Co","au murit goblinii din Charred Vale","Venture Co si Charred Vale"}},{q="Ce sunt Smoldering Embers?",a="Smoldering Embers sunt ramasitele aprinse adunate de la elementalii de foc distrusi in Charred Vale si aduse inapoi la Kaela Shadowspear drept dovada concreta ca numarul lor haotic a fost redus.",al={"smoldering embers poveste","la ce folosesc taciunii","taciunii spiritelor furioase"}},{q="Isi poate reveni vreodata Charred Vale?",a="Kaela Shadowspear crede ca pamantul nu are nicio sansa sa simta binecuvantarea lui Elune sau sa-si revina cat timp elementalii ostili bantuie printre cenusa. Inlaturarea acestor spirite dezlantuite este primul pas spre orice vindecare viitoare.",al={"se va vindeca Charred Vale","vindecarea Charred Vale","poate fi salvata valea"}},{q="Unde se afla Charred Vale?",a="Charred Vale se afla in regiunea sud-vestica a Stonetalon Mountains, fiind presarata cu pamant innegrit, lemn ars si spirite elementale ratacitoare.",al={"locatia Charred Vale","cum sa gasesti Charred Vale","unde sunt elementalii"}}},fx={db30736e={q="De ce vrea Kaela Shadowspear sa fie starpite spiritele infuriate?",a="Pustiirea din Charred Vale o indurereaza profund pe Kaela Shadowspear. Pangarirea nechibzuita a dezlantuit in tinut spirite violente de foc, piatra si furie. Ca Night Elf, ea crede ca pamantul cicatrizat nu poate primi harul lui Elune si nici incepe sa se vindece cat timp aceste forte elementale haotice umbla libere. Starpirea lor este primul pas spre restabilirea pacii in valea ranita.",al={"de ce sa eliminam spiritele","motivul lui kaela shadowspear","de ce vrea kaela sa faci asta"}},["3905caa9"]={q="Cu ce creaturi te lupti in Charred Vale?",a="Vanezi spiritele arzande - elementali nascuti din foc, piatra topita si furie nestapanita - care bantuie acum tinuturile parjolite din Charred Vale. Trezite si intaritate de Venture Company, care a incendiat padurile si a sfasiat pamantul cu utilajele sale, aceste entitati ostile napadesc ruinele cu violenta si ataca pe oricine indrazneste sa se apropie.",al={"elementalii din Charred Vale","ce sunt spiritele arzande","cu cine ma lupt, spiritele furioase"}}},fp="15,386,18.412.0,14.414.0,36.144.0,58.222.0,57.217.0,27.201.0,34.214.0,34.150.0"}
P.entries["quest:1084"] = {n="Wounded Ancients",s="Wounded Ancients este o misiune Alliance oferita de Kaela Shadowspear in Stonetalon Mountains. Banuiind ca munitia goblinilor i-a innebunit pe paznicii padurii din zona, Kaela trimite aventurieri sa recupereze schije infipte in copacii stravechi corupti, pentru ca inginerul gnom Gaxim Rustfizzle sa poata analiza intinarea.",h="Wounded Ancients este o misiune Alliance oferita de Kaela Shadowspear in Stonetalon Mountains.",kw={"srapnel corodat","coruptie","Gaxim Rustfizzle","Kaela Shadowspear","Stonetalon","treanti","Venture Co","stravechi raniti"},ang={["class:Druid"]="Treantii reprezinta pulsul viu al naturii; extragerea metalului strain care le otraveste trupurile este o necesitate sumbra in lupta impotriva distrugerilor provocate de Venture Company.",["profession:Engineering"]="Metalul corodat recuperat de la copacii vii subliniaza caracterul distructiv si facut in graba al munitiei Venture Company, in comparatie cu maiestria rafinata a gnomilor.",["race:Gnome"]="Privirea analitica a lui Gaxim Rustfizzle arata ca mestesugul mecanic poate fi folosit pentru a intelege si diagnostica infractiunile impotriva mediului comise de ingineri iresponsabili.",["race:NightElf"]="Sa privesti cum aparatorii stravechi ai padurii putrezesc si se stramba din cauza industriei goblinilor este revoltator pentru orice Kaldorei devotat protejarii salbaticiei din Kalimdor."},sec={{t="Pazitori napastuiti",b="Crangurile impadurite din Stonetalon au fost multa vreme vegheate de treanti impunatori, paznici blanzi, dar feroce, legati de sanatatea pamantului. Cand Venture Company a sosit cu fierastraie circulare, explozibili si operatiuni de exploatare la zi, natura a ripostat. Treantii au respins cu succes invadatorii din unele parti ale vaii, insa victoria a avut un pret perfid. Aparatorii nu s-au intors la paza pasnica; in schimb, au degenerat in ramasite ostile si innebunite."},{t="Investigatie gnoma",b="Kaela Shadowspear, o cercetasa Alliance aflata in munti, crede ca declinul treantilor nu este cauzat de vreo boala naturala. Inginerul gnome Gaxim Rustfizzle banuieste ca vinovate sunt armele chimice si mecanice folosite de goblini in timpul retragerii lor haotice. Scoatand schije corodate din creaturile lemnoase ranite, Gaxim spera sa afle daca munitia Venture Company ii otraveste in mod activ pe stravechii aparatori ai Stonetalon."}},faq={{q="Cine ofera misiunea Wounded Ancients?",a="Kaela Shadowspear ofera misiunea. Este o operativa Alliance care supravegheaza conflictele tot mai intense si daunele ecologice din Stonetalon Mountains.",al={"cine ofera misiunea Wounded Ancients","cine ofera Wounded Ancients","misiunea lui kaela shadowspear"}},{q="De ce sunt corupti treantii?",a="Gaxim Rustfizzle banuieste ca munitia si armele toxice folosite de Venture Company in timpul retragerii haotice s-au infipt in treanti, otravind si infuriind treptat paznicii padurii.",al={"de ce sunt treantii furiosi","treantii din Stonetalon sunt corupti","sursa coruperii treantilor"}},{q="Ce obiect trebuie recuperat pentru aceasta sarcina?",a="Trebuie sa recuperezi o bucata de Corroded Shrapnel, infipta in scoarta si carnea treantilor raniti care cutreiera zona.",al={"stravechi raniti, obiect","misiunea schijelor corodate"}},{q="Cine este Gaxim Rustfizzle?",a="Gaxim este un inginer gnome Alliance-aligned care o ajuta pe Kaela Shadowspear. El isi foloseste priceperea mecanica pentru a cerceta tehnologia Venture Company si a afla cum corup armele lor viata naturala.",al={"gaxim","gnom din stonetalon","rolul lui Gaxim Rustfizzle"}},{q="Ce prezenta are Venture Company in Stonetalon?",a="Venture Company este un sindicat goblin nemilos, specializat in exploatarea forestiera si miniera, care a invadat Stonetalon pentru a rade de pe fata pamantului padurile sacre si a jefui zacamintele minerale, fara sa tina cont de echilibrul local.",al={"Venture Co in Stonetalon","de ce sunt goblini in Stonetalon"}},{q="Vindeca strangerea schijelor arborii treant?",a="Nu. Schija recuperata este doar o mostra pentru analiza, menita sa-i permita lui Gaxim sa cerceteze natura si originea toxinei, nu sa ofere un leac imediat pentru paznicii corupti.",al={"pot fi vindecati treantii","isi revin treantii"}}},fx={["6c6333aa"]={q="De ce vrea Kaela Shadowspear schijele corodate?",a="Kaela este profund tulburata de coruptia care-i deformeaza pe protectorii din Charred Vale. Dupa ce Venture Company a fost respinsa, stravechii treanti au fost lasati violenti si cu mintea ratacita. Ea i-a promis lui Gaxim Rustfizzle ca va obtine o mostra de munitie goblina infipta in trupurile stramosilor raniti, sperand ca gnomul o va putea studia si va confirma daca armele crude ale invadatorilor sunt intr-adevar raspunzatoare pentru otravirea aparatorilor tinutului.",al={"motivul Kaelei Shadowspear","de ce sa-i ajuti pe treants din Stonetalon","de ce vrea Kaela schije"}},["4feb3a85"]={q="Ce este Corroded Shrapnel?",a="Corroded Shrapnel este alcatuit din fragmente de metal zimtate, aruncate in copaciants de Venture Company in retragere. Gaxim Rustfizzle banuieste ca reziduurile toxice sau explozive ramase pe fier au dus la nebunia tragica a stravechilor. Kaela are nevoie de mostra, pentru ca Gaxim sa-i poata cerceta compozitia chimica si sa gaseasca o cale de urmat.",al={"ce sunt Corroded Shrapnel","Corroded Shrapnel din Stonetalon","povestea schijelor"}},["2aa0bc4f"]={q="De ce esti trimis impotriva treantilor raniti?",a="Treantii raniti au fost candva paznici pasnici ai Charred Vale, inainte ca exploatarile forestiere si razboiul Venture Company sa devasteze valea. In timpul retragerii lor, goblinii i-au atacat pe aparatori cu munitii josnice, lasandu-i plini de cicatrici, turbati si ostili fata de oricine se apropie. Pentru a recupera srapnelul infipt in scoarta lor, trebuie sa infrunti aceste creaturi chinuitor de corupte.",al={"de ce sa ucizi treantii raniti","cine sunt stravechii raniti","treantii din Charred Vale"}}},fp="16,301,19.469.0,21.440.0,38.151.0,30.195.0,42.128.0,24.197.0,53.185.0,46.181.0"}
P.entries["quest:1085"] = {n="On Guard in Stonetalon",s="On Guard in Stonetalon ii indruma pe calatorii Alliance de la Kaela Shadowspear la Gaxim Rustfizzle, in tabara lor de langa Windshear Crag. In fata distrugerilor necontrolate provocate de Venture Company, o pereche neasteptata - o santinela night elf precauta si un inventator gnome excentric - isi uneste fortele pentru a apara trecatoarea montana.",h="On Guard in Stonetalon ii indruma pe calatorii Alliance de la Kaela Shadowspear la Gaxim Rustfizzle, in...",kw={"inginerie","gaxim rustfizzle","gnom","kaela shadowspear","night elf","stonetalon","stonetalon peak","venture co"},ang={["faction:Alliance"]="Aceasta colaborare ilustreaza spiritul mai larg al Alliance, reunind experienta din Eastern Kingdoms si Sentinels din Kalimdor pentru a opri amenintarile comune de la granita.",["profession:Engineering"]="Misiunea lui Gaxim subliniaza utilitatea practica a ingineriei in cercetarea de pe linia frontului si in apararea ecosistemelor, dovedind ca rotitele pot ajuta la protejarea naturii atunci cand sunt folosite impotriva exploatarii necontrolate.",["race:Gnome"]="Gaxim Rustfizzle reprezinta cu mandrie ingeniozitatea gnomilor din Kalimdor, demonstrand prin prezenta sa ca stiinta, ingineria si magia pot depasi obstacolele in fata carora traditiile stravechi se dovedesc neputincioase.",["race:NightElf"]="Pentru santinelele Kaldorei, sa aiba incredere intr-un mester gnom care sustine imbinarea ingineriei cu magia cere sa-si inghita mandria, dovada a amplorii distrugerilor provocate de operatiunile forestiere ale Venture Company."},sec={{t="O Alliance improbabila",b="Night elves si gnomes au rareori ceva in comun, mai ales cand vine vorba de tehnologie si de lumea naturala. Insa, in vaile abrupte din Stonetalon Mountains, necesitatea creeaza o punte peste prapastia culturala. In timp ce lacoma Venture Company defriseaza tinuturile salbatice si doboara copaci stravechi, santinela Kaela Shadowspear a inteles ca doar iscusinta martiala nu poate opri jafurile industrializate. Primirea ingeniozitatii gnomilor pe teritoriul sacru al Kaldorei arata cat de precara a devenit situatia."},{t="Filosofia gnomilor",b="Gaxim Rustfizzle intruchipeaza pragmatismul excentric al aliatilor mai mici ai Alliance. Desi societatea Night Elf a intors renumit spatele exceselor arcane cu milenii in urma, Gaxim crede ca renuntarea la magie si inovatie tehnica ii lasa vulnerabili. Imbinand alchimia si ingineria cu o nota de disciplina arcana, Gaxim spera sa-si convinga gazdele Kaldorei ca stiinta practica poate apara natura la fel de eficient ca arcul si glaiva."}},faq={{q="De ce lucreaza impreuna aici un Night Elf si un Gnome?",a="Defrisarea distructiva si exploatarea resurselor de catre Venture Company in Stonetalon sunt atat de grave, incat Kaela Shadowspear a acceptat ajutor din afara. Gaxim aduce cunostinte de inginerie si alchimie care le lipsesc de obicei elfilor noptii, oferind sprijin tehnic impotriva utilajelor industriale moderne.",al={"de ce este gaxim cu kaela","kaela si gaxim","alianta dintre gnomi si elfii noptii"}},{q="Cine este Gaxim Rustfizzle?",a="Gaxim este un gnom inginer si inventator aventuros, instalat intr-o tabara de langa Windshear Crag. El crede cu tarie ca stricta aversiune a elfilor noptii fata de magia arcana ii dezavantajeaza, cautand sa demonstreze ca imbinarea ingineriei, alchimiei si magiei controlate poate rezolva chiar si cele mai cumplite amenintari.",al={"povestea lui Gaxim Rustfizzle","cine este Gaxim","Gnome de la Stonetalon Peak"}},{q="Cine este Kaela Shadowspear?",a="Kaela Shadowspear este o santinela elf de noapte insarcinata cu supravegherea si apararea Stonetalon Mountains. Este comandanta regionala care coordoneaza rezistenta impotriva Venture Company.",al={"kaela shadowspear","cine este kaela"}},{q="Ce amenintare reprezinta Venture Company in Stonetalon?",a="Venture Company este un sindicat comercial lipsit de scrupule, care taie paduri sacre, foloseste instalatii de foraj distructive si polueaza tinuturi neatinse din Stonetalon pentru profit comercial rapid.",al={"venture co stonetalon","de ce sa lupti cu venture co"}},{q="Cine este Tara, cea mentionata de Kaela?",a="Tara este Sentinel Tara Thenysil, prietena Kaelei din Astranaar, care te-a trimis sa vezi ce mai face. Kaela se bucura ca Tara se descurca suficient de bine printre Sentinels, incat sa trimita aventurieri cu treburi.",al={"tara stonetalon","te trimite inapoi la tara"}},{q="Unde duce aceasta sarcina mai departe?",a="Dupa ce vorbeste cu Gaxim Rustfizzle, acesta iti ofera misiunea 'A Gnome's Respite', cerandu-ti ajutorul pentru a tine la distanta taietorii de lemne ai Venture Company din Windshear Crag, ca sa aiba timp sa-si planifice urmatoarele inventii.",al={"misiunea de dupa On Guard in Stonetalon","urmatoarea misiune dupa Gaxim"}}},fx={["6de32c22"]={q="De ce vrea Kaela Shadowspear sa vorbesti cu Gaxim?",a="Venture Company a devastat grav Stonetalon, acaparandu-i aproape tot timpul si atentia Kaelei, care incearca sa-i stavileasca distrugerile. Disperata sa gaseasca ajutor, ea a renuntat la reticenta traditionala a elfilor noptii fata de alianta cu inginerul gnom Gaxim Rustfizzle. Pentru a organiza o rezistenta eficienta si a proteja muntii, trebuie sa colaborezi direct cu Gaxim si sa-ti aduci forta in sprijinul eforturilor lor comune.",al={"de ce sa vorbesc cu gaxim","motivul lui kaela shadowspear","de ce te trimite kaela la gaxim"}}},fp="22,315,20.521.0,18.450.0,54.299.0,24.304.0,25.202.0,56.201.0,32.192.0,31.192.0"}
P.entries["quest:1086"] = {n="The Flying Machine Airport",s="Trimisi de Apothecary Zamah din Thunder Bluff, aventurierii Horde cauta o platforma de aterizare ascunsa a Venture Company, cocotata deasupra Stonetalon Mountains. Purtand un Toxic Fogger alchimic, agentii trebuie sa se strecoare in inima exploatarilor forestiere goblin pentru a umple de gaz nodul lor de transport aerian. Misiunea loveste direct in comunicatiile cartelului si scoate in evidenta metodele nemiloase ale Royal Apothecary Society.",h="Trimisi de Apothecary Zamah din Thunder Bluff, aventurierii Horde cauta o platforma de aterizare ascunsa a...",kw={"aeroport","Apothecary Zamah","platforma pentru elicopter","Cragpool Lake","masina zburatoare","Stonetalon","Thunder Bluff","aparat de pulverizare a gazului toxic","Venture Co"},ang={["faction:Horde"]="Pentru a asigura Stonetalon, trebuie taiat accesul Venture Company la ajutor din exterior, iar atacarea transportului lor aerian este o lovitura logistica esentiala.",["profession:Engineering"]="Platforma pentru elicoptere a goblinilor etaleaza ingineria rudimentara si pragmatica ce asigura transportul rapid al Venture Company peste lanturile muntoase accidentate.",["race:Tauren"]="Desi poporul tau detesta distrugerea pe care Venture Company o provoaca in Stonetalon, folosirea toxinelor chimice la sfatul unui apotecar Forsaken pune la incercare echilibrul dintre venerarea Mamei-Pamant si pragmatismul dur al campului de lupta.",["race:Undead"]="Pentru Forsaken, folosirea Toxic Fogger in Stonetalon este o treaba ca oricare alta, demonstrand Kalimdorului ca geniul alchimic al Undercity poate rezolva probleme pe care forta bruta nu le poate invinge."},sec={{t="O livrare tacuta",b="In timp ce taurenii cauta sa protejeze Stonetalon de defrisari si utilaje devastatoare, Forsaken aduc in prim-plan o filosofie cu totul diferita. Apothecary Zamah pregateste toxina lui Apothecary Lydon pentru a perturba logistica Venture Company. In loc sa-i atace direct pe soldatii de infanterie sau pe taietorii de lemne, ea vizeaza legatura cartelului cu lumea exterioara: un heliport despre care se zvoneste ca ar fi folosit pentru a transporta marfuri usoare si mesaje intre Stonetalon si sediile companiei indepartate."},{t="Portul aerian al Cragpool",b="Ascunsa in zona Cragpool Lake, la sud de marea roata de apa, se afla platforma pentru elicoptere a Venture Company, cocotata deasupra funinginii si a lemnului taiat. Este mica, destinata aparatelor de zbor usoare, nu dirijabilelor uriase. Declansarea Toxic Fogger chiar pe platforma asigura ca orice pilot, curier sau mecanic care lucreaza la utilaje sa fie sufocat de vaporii toxici inainte sa-si poata alerta comandantii."},{t="Pragmatismul Forsaken",b="Dupa ce primeste vestea despre bombardament, Apothecary Zamah nu-si cere scuze pentru folosirea razboiului chimic impotriva goblinilor. In ochii ei, Venture Company merita un tratament mult mai rau pentru ceea ce face pamantului. Mai important, ea ii ofera Horde o lectie fundamentala din doctrina Undercity: sa nu se fereasca niciodata de caile intunecate, daca acestea duc spre victoria suprema."}},faq={{q="Unde se afla aeroportul pentru masini zburatoare?",a="Platforma pentru elicoptere a Venture Company se afla in regiunea Cragpool Lake din Stonetalon Mountains. Structura inalta din lemn se afla la sud de imensa roata de apa industriala, cu vedere spre cotul sudic al lacului.",al={"unde este aeroportul","locatia platformei pentru elicoptere","unde este portul aerian","platforma de aterizare Venture Co"}},{q="De ce vrea Apothecary Zamah ca acest loc sa fie otravit?",a="Zamah vrea sa intrerupa comunicatiile si liniile de aprovizionare cu lumina ale Venture Company dintre Stonetalon si sediul sau indepartat. Contaminand platforma pentru elicoptere, spera ca toxina va paraliza echipajele goblinilor si poate va ajunge, la bordul unei aeronave, pana la conducatorii companiei.",al={"de ce sa bombardezi aeroportul","de ce sa folosesti pulverizatorul toxic","motivul lui zamah"}},{q="Cine este Apothecary Zamah?",a="Apothecary Zamah este un emisar al Royal Apothecary Society, aflat in Pools of Vision, sub Thunder Bluff. Studiaza flora si fauna din Kalimdor, dezvoltand totodata arme alchimice pentru Forsaken si Horde.",al={"identitatea lui Zamah","cine este Zamah","strigoi in Thunder Bluff"}},{q="De ce foloseste Horde arme chimice aici?",a="Forsaken lupta cu un pragmatism nemilos. Desi aliatii lor tauren prefera vindecarea spirituala si apararea directa a pamantului, Zamah crede ca lacomia distructiva a Venture Company justifica metode fara mila, invatand ca victoria conteaza mai mult decat retinerea sentimentala.",al={"horde foloseste ciuma","de ce otravesc goblinii","este aceasta ciuma"}},{q="Ce fel de aeronave foloseste aici Venture Company?",a="Platforma este dimensionata pentru aparate de zbor si girocoptere goblin mici, nu pentru zeppeline de mari dimensiuni. Aceste vehicule agile ii permit cartelului sa ocoleasca rapid trecatorile accidentate din Stonetalon pentru a transporta mesaje si marfuri de maxima importanta.",al={"elicopterele Venture Co","ce masina zburatoare","aeronava goblinilor din Stonetalon"}},{q="Ce se intampla dupa ce este amplasat pulverizatorul de ceata?",a="Dupa ce declansezi dispozitivul de dispersare a cetii in varful platformei, fugi inainte ca vaporii sa te ajunga din urma. Zamah considera desfasurarea un succes si se asteapta ca otrava sa perturbe grav logistica goblin.",al={"rezultatul aparatului de ceata","dupa ce amplasezi aparatul de ceata"}}},fx={ee15b44c={q="Pe cine tintesti la aeroport si de ce se afla aici?",a="Tintezi Venture Company, un cartel goblin nemilos, care exploateaza Stonetalon Mountains prin minerit in cariera si defrisari, de dragul profitului. Ei opereaza un port aerian clandestin pentru a transporta mesaje si marfuri usoare inapoi la sediul lor indepartat. Lovind platforma de aterizare cu aparatul de pulverizat ceata toxica al lui Apothecary Zamah, Horde urmareste sa le intrerupa linia vitala de aprovizionare si sa raspandeasca otrava direct printre conducatorii lor.",al={"tinta aeroportului Venture Company","pe cine atacam in stonetalon","de ce se afla aici venture co"}}},fp="26,416,17.465.0,19.419.0,19.352.1,44.224.0,50.278.0,24.235.0,45.276.0,56.236.0,42.204.1"}
P.entries["quest:1087"] = {n="Cenarius' Legacy",s="Cenarius' Legacy este o sarcina a Horde, incredintata de Braelyn Firehand langa Sun Rock Retreat, in Stonetalon Mountains. Frustrat de protectiile naturale intretinute de elfii noptii si de copiii lui Cenarius, magul elf de sange vrea sa le reduca numarul la Stonetalon Peak, pentru a restabili fluxul neingradit al magiei. Pentru Horde, atacarea aparatorilor Cenarion slabeste si prezenta Alliance din regiune.",h="Cenarius' Legacy este o sarcina a Horde, incredintata de Braelyn Firehand langa Sun Rock Retreat, in...",kw={"braelyn firehand","botanist cenarion","cenarius' legacy","fiica lui cenarius","jaedenar","ordanus","fiul lui cenarius","stonetalon peak","sun rock retreat"},ang={["class:Druid"]="Pentru druidii Tauren, macelarirea odraslelor lui Cenarius si a botanistilor din Cenarion Circle este un act stanjenitor si profund dezbinator, care subliniaza conflictul tragic dintre loialitatea fata de factiune si caile sacre ale naturii.",["class:Mage"]="Plangerile lui Braelyn ating o coarda sensibila in randul practicantilor artelor arcane, care inteleg tensiunea dintre protectiile stravechi kaldorei si energiile ley libere, chiar daca zelul ei nechibzuit se apropie de obsesie.",["faction:Horde"]="Stonetalon Peak este cea mai mare fortareata a puterii Alliance si kaldorei din lantul muntos; inlaturarea aparatorilor sai este esentiala pentru protejarea Sun Rock Retreat si Greatwood Vale."},sec={{t="Curente inabusite",b="Braelyn Firehand locuieste pe dealurile de langa Sun Rock Retreat si este macinata de frustrarea fata de mediul natural din Stonetalon. Potrivit ei, druizii din Cenarion Circle si urmasii semizeului Cenarius suprima si inabusa in mod activ curentii arcani ai tinutului. Descriind canalizarea puterii de aici drept incercarea de a scoate apa cu o galeata gaurita, ea tanjeste sa le inlature apararile naturale, pentru ca energia magica bruta sa poata curge din nou nestingherita."},{t="O lovitura la Stonetalon Peak",b="Pentru a slabi aceasta strangulare vegetala, Braelyn ii mobilizeaza pe campionii Horde sa se indrepte spre nord, la Stonetalon Peak. Acolo, in jurul vechilor cranguri kaldorei si al templelor, patruleaza botanistii Cenarion alaturi de mandrii Fii si Fiice ai lui Cenarius. Doborarea acestor paznici are un dublu scop: distruge protectiile care inabusa vrajitoria lui Braelyn si da o lovitura sangeroasa enclavei night elf care ameninta capul de pod al Horde din munti."},{t="Legaturi cu Shadow Council",b="Desi Braelyn isi prezinta nemultumirea ca pe o simpla chestiune de comoditate magica, adevarata ei loialitate se afla in locuri mult mai intunecate. Tanjeste sa se intoarca la Jaedenar, fortareata corupta a Shadow Council, ascunsa in Felwood, la nord, dar spune ca stapanul ei nevazut ii interzice sa se intoarca pana cand nu-si incheie treaba in Stonetalon. Hordea o ajuta din ratiuni teritoriale, fara sa-si dea seama, de cele mai multe ori, ca un cult sinistru trage sforile."}},faq={{q="Cine este Braelyn Firehand?",a="Braelyn Firehand este o vrajitoare elfa de sange, campata printre stancile de langa Sun Rock Retreat. Desi accepta ajutorul Horde pentru a alunga elfii noptii din Stonetalon, ea slujeste unui stapan ascuns, aflat in Jaedenar, in Felwood.",al={"povestea lui Braelyn Firehand","cine ofera misiunea","Braelyn"}},{q="De ce vrea Braelyn sa-i omoare pe copiii lui Cenarius?",a="Sustine ca magia druidica practicata de botanistii kaldorei si de odraslele lui Cenarius inabusa in mod activ curgerea puterii arcane brute peste munti. Eliminandu-i, se slabesc protectiile dumbravii, iar magia poate curge nestingherita in mainile ei.",al={"de ce sa-i ucizi pe fiii lui Cenarius","de ce uraste botanistii Cenarion","de ce ii uraste Braelyn"}},{q="Unde se afla tintele?",a="Fiii lui Cenarius, Fiicele lui Cenarius si Botanistii Cenarion sunt concentrati mult spre nord, la Stonetalon Peak, pazind ruinele ancestrale, crangurile si fantanile lunii intretinute de night elves.",al={"unde se afla fiii lui Cenarius","locatiile inamicilor de la Stonetalon Peak","unde gasesti botanisti Cenarion"}},{q="Ce este Jaedenar, despre care vorbeste Braelyn?",a="Jaedenar este un complex intins de canioane si pesteri din Felwood, puternic corupt de Burning Legion si folosit in prezent drept baza centrala de operatiuni a Shadow Council din Kalimdor.",al={"ce este Jaedenar","stapanul lui Braelyn din Jaedenar","legatura cu Jaedenar"}},{q="De ce este Horde dispusa sa o ajute pe Braelyn sa atace aparatorii Cenarion?",a="Elfii noptii de la Stonetalon Peak sunt aliati directi ai lui Alliance si se opun expansiunii lui Horde in intreaga regiune Stonetalon Mountains. Slabirea crangului lor asigura regiunea pentru Horde, indiferent de motivele personale ale lui Braelyn.",al={"de ce ucide hoarda Cenarion Circle","conflictul hoardei din stonetalon peak"}},{q="Ce se intampla dupa finalizarea misiunii Cenarius' Legacy?",a="Urmatoarea misiune a lui Braelyn il vizeaza pe Ordanus, un paznic al dumbravii din Raynewood Retreat, in Ashenvale. Poate fi gasit in varful marelui copac de acolo.",al={"misiunea de dupa Cenarius' Legacy","ce urmeaza in lantul de misiuni","lantul de misiuni Ordanus"}}},fx={["9bca5a54"]={q="Pe cine esti trimis sa omori in Cenarius' Legacy?",a="Braelyn te trimite impotriva Fiilor si Fiicelor lui Cenarius, precum si a botanistilor Cenarion aflati in varful Stonetalon Peak. Acesti pazitori, driade si ingrijitori Night Elf se ocupa de dumbrava sacra si muncesc neincetat pentru a cultiva pamantul, ferind regiunea de magia arcana haotica si arzatoare pe care Braelyn incearca sa o stapaneasca.",al={"tinte pentru cenarius legacy","pe cine ucizi in cenarius legacy","cine sunt fiii si fiicele lui cenarius"}}},fp="16,401,16.468.0,27.454.0,26.429.1,24.243.1,52.256.0,30.204.0,41.194.0,67.242.0,47.142.1"}
P.entries["quest:1088"] = {n="Ordanus",s="Braelyn Firehand de la Sunrock Retreat isi foloseste vederea arcana pentru a-l urmari pe Keeper Ordanus, un fiu mai varstnic al lui Cenarius, care a fugit din Stonetalon Peak. Crezand ca ai ei au pangarit vechile ruine Highborne, ii trimite pe campionii Horde peste granita, in Ashenvale, ca sa-i aduca capul.",h="Braelyn Firehand de la Sunrock Retreat isi foloseste vederea arcana pentru a-l urmari pe Keeper Ordanus, un...",kw={"ashenvale","braelyn firehand","cenarius","highborne","ordanus","raynewood retreat","stonetalon","refugiul sunrock"},ang={["class:Druid"]="Druizii Horde se confrunta cu o dilema sumbra in aceasta sarcina: trebuie sa ucida fiul direct al lui Cenarius pentru a implini vechea razbunare a unui elf de sange.",["class:Mage"]="Braelyn Firehand intruchipeaza mandria arcana neclintita a Highborne, afirmand suprematia magiei arcane asupra filosofiei naturiste Cenarion.",["faction:Horde"]="Doborarea unui fiu mai mare al lui Cenarius slabeste autoritatea Night Elves de-a lungul granitei dintre Ashenvale si Stonetalon, ajutand expansiunea Horde in padurile disputate."},sec={{t="O vanatoare manata de vechi resentimente",b="Braelyn Firehand a sosit in Stonetalon Mountains la porunca maestrului sau, pentru a recupera ruinele sacre ale templelor stravechi din Azshara. A gasit deja elfii night elf ocupand culmea si tratand relicvele stramosilor ei Highborne ca pe o salbaticie ce trebuie tinuta sub control. Tinta ei principala, Keeper Ordanus, a fugit inainte ca ea sa-l poata prinde, trecand granita in Ashenvale. Folosindu-si vederea arcana, Braelyn i-a descoperit ascunzatoarea, sus, intr-un refugiu de lemn din Raynewood Retreat, si a chemat Horde sa duca vanatoarea la bun sfarsit."},{t="Urmasul zeului padurii",b="Ordanus se numara printre cei mai varstnici fii ai lui Cenarius si are legaturi stranse cu magia salbatica a Kalimdorului. Paznicii elfi ai noptii l-au mutat de la Stonetalon Peak la Raynewood Retreat, incercand sa-l fereasca de fortele arcane care se apropiau de crangurile sacre. Aparat de aparatori Cenarion loiali si de treanti ai padurii invocati, paznicul intruchipeaza atat vechea autoritate a semizeului padurii, cat si un obstacol viu in calea razbunarii lui Braelyn."},{t="Razbunarea Highborne",b="Pentru Braelyn Firehand, revendicarea capului lui Ordanus este o chestiune personala, nu doar una tactica. Ea isi aminteste deschis ca l-a cunoscut cu secole in urma si isi aminteste aroganta cu care odraslele lui Cenarius ii priveau de sus pe Highborne si maiestria lor in artele arcane. Taindu-i capul, se razbuna pentru vechile insulte si deschide calea planurilor mai marete ale stapanului ei in salbaticia din Kalimdor."}},faq={{q="Cine este Keeper Ordanus?",a="Ordanus este un pazitor al crangului si unul dintre cei mai varstnici fii ai semizeului Cenarius. Initial era stationat langa Stonetalon Peak, inainte sa fuga in Ashenvale pentru a scapa de razbunarea Highborne.",al={"povestea lui Ordanus","cine este Ordanus","cine este paznicul Ordanus"}},{q="Unde poate fi gasit Keeper Ordanus?",a="Ordanus locuieste in varful unei structuri masive, scobite in trunchiul unui copac, in Raynewood Retreat, de-a lungul drumului care strabate centrul Ashenvale.",al={"locatia lui ordanus","unde este ordanus","copacul din raynewood retreat"}},{q="De ce il vrea Braelyn Firehand mort pe Ordanus?",a="Braelyn considera ca prezenta Night Elves in Stonetalon este o profanare a ruinelor vechilor temple Highborne. De asemenea, nutreste de mult timp o ura personala fata de Ordanus, pe care si-l aminteste ca fiind arogant si dispretuitor fata de poporul ei in vremuri stravechi.",al={"de ce sa-l omoare pe Ordanus","dusmania lui Braelyn","de ce il vrea Braelyn pe Ordanus"}},{q="Cine este maestrul lui Braelyn Firehand?",a="Braelyn povesteste ca a slujit un stapan care a trimis-o pe varful din Stonetalon sa recucereasca ruinele templului antic din Azshara, dar pastreaza ascunsa identitatea exacta a stapanului.",al={"stapanul lui braelyn","cine l-a trimis pe braelyn"}},{q="Cum se inscrie acest conflict in prezenta Horde in Stonetalon?",a="Fortele Horde stationate la Sunrock Retreat se ciocnesc frecvent cu santinelele elfilor noptii si protectorii Cenarion pentru teritoriu si resurse in Stonetalon si Ashenvale, ceea ce face ca atacul lui Braelyn asupra unui conducator Cenarion sa fie in avantajul ambelor parti.",al={"de ce o ajuta horde pe braelyn","motivele horde in stonetalon"}},{q="Ce se intampla dupa ce Ordanus este ucis?",a="Dupa ce Ordanus este ucis, Braelyn il rasplateste pe campion si il indruma spre The Den, unde acesta cerceteaza mai indeaproape amenintarile din muntii Stonetalon.",al={"ce urmeaza dupa Ordanus","misiunea de dupa Ordanus","urmatoarea misiune din vizuina"}}},fx={ec9312c1={q="La ce foloseste Ordanus' Head?",a="Braelyn Firehand cere capul lui Keeper Ordanus drept dovada absoluta a mortii sale si pentru a-si satisface o veche ranchiuna. Cunoscandu-l pe Ordanus cu mult timp in urma, Braelyn dispretuieste aroganta pazitorului si credinta lui ca neamul sau era mai presus chiar si de Highborne. Aducerea capului retezat nu doar confirma ca apararea elfilor noptii din Ashenvale a suferit o lovitura critica, ci il si umileste pe fiul lui Cenarius exact asa cum isi inchipuise Braelyn.",al={"de ce Ordanus","capul lui Ordanus","ce face Braelyn cu capul lui Ordanus"}}},fp="7,272,32.520.0,27.444.0,19.389.1,22.193.0,34.133.0,44.232.0,33.179.0,67.239.0,36.157.1"}
P.entries["quest:1089"] = {n="The Den",s="The Den este punctul culminant al unei campanii de infiltrare a Horde impotriva druidilor elfi de noapte intariti pe Stonetalon Peak. Sub indrumarea agentului blood elf Braelyn Firehand, campionii patrund in camerele subterane ale tumulului din Talon Den pentru a sparge un sistem de securitate complex si a jefui relicvele ascunse ale druidilor.",h="The Den este punctul culminant al unei campanii de infiltrare a Horde impotriva druidilor elfi de noapte...",kw={"barrow key","braelyn firehand","cenarius' legacy","claw key","gatekeeper's key","ordanus","sleepers' key","stonetalon peak","talon den","talon den hoard"},ang={["class:Druid"]="Druizii Tauren din Horde se confrunta aici cu o ironie amara: folosesc chei concepute dupa arhitectura traditionala a tumulilor - numite pentru Dormitori, Gheare si Tumuluri - impotriva semenilor lor, paznicii Cenarion.",["class:Rogue"]="Strabaterea salilor intunecate ale tumulului pentru a fura cheile din felinarele ascunse si din suporturile de torte necesita infiltrare si viclenie.",["faction:Horde"]="Atacul asupra Talon Den frange coloana vertebrala a apararii Night Elf de pe Stonetalon Peak, asigurand caile de acces montane si capturand relicve magice puternice pentru Horde.",["race:NightElf"]="Pang arirea Talon Den incalca in mod sumbru sanctuarele sacre ale mormintelor, tulburand somnul stravechi al paznicilor Cenarion si ducand la jefuirea relicvelor lor protejate de vraji."},sec={{t="Secrete subterane",b="Asezat in cele mai inalte tinuturi din Stonetalon Mountains, Talon Den serveste drept bastion subteran pentru druizii elfilor noptii. Sapate adanc in piatra vie, aceste sali funerare sunt menite sa-i ocroteasca pe gardienii aflati in meditatie si sa adaposteasca comori sacre departe de privirile indiscrete. Cunoscand valoarea strategica si arcane a celor ascunse acolo, Braelyn Firehand il interogheaza pe un druid capturat pentru a-i smulge secretele apararii."},{t="Incuietorile stratificate",b="Pentru a-si proteja relicvele cele mai puternice, druidii au creat un mecanism complicat, in loc sa se increada intr-o singura usa. La intrarea in camerele barrow, ascunsa intr-un felinar modest, se afla Gatekeeper's Key. Aceasta cheie initiala deschide trei ascunzatori raspandite in complex: Sleepers' Key, Claw Key si Barrow Key. Numai dupa ce toate cele trei pietre sculptate sunt intoarse in vistieria centrala se destrama sigiliile druidice, lasand vechile obiecte sa ajunga in mainile Horde."}},faq={{q="Ce este Talon Den?",a="Talon Den este un complex subteran de cripte ale elfilor de noapte, sapat in inaltimile din Stonetalon Peak. Serveste atat ca sanctuar de meditatie pentru druizii veniti sa se odihneasca, cat si ca depozit sigur pentru relicvele lor sacre.",al={"unde este Talon Den","ce este vizuina","vizuina din Stonetalon Barrow"}},{q="Cine ordona infiltrarea in Talon Den?",a="Braelyn Firehand, o operativa Sin'dorei care lucreaza alaturi de Horde in Stonetalon Mountains, organizeaza raidul. Dupa ce a obtinut informatii esentiale de la un druid captiv nefericit, ea le da agentilor Hordei instructiuni sa treaca de barierele sanctuarului si sa-i jefuiasca tezaurul.",al={"cine ofera misiunea din barlog","scopul lui Braelyn Firehand","cine m-a trimis la barlog"}},{q="Cum functioneaza cheile din vizuina?",a="O cheie principala Gatekeeper's Key este ascunsa intr-un felinar de langa intrare. Aceasta deschide trei ascunzatori raspandite prin tumul, in care se gasesc Sleepers' Key, Claw Key si Barrow Key. Cand sunt introduse impreuna in lada de piatra sculptata, sigiliile magice se risipesc.",al={"cum se deschide Talon Den Hoard","la ce foloseste cheia portarului","trei chei in Stonetalon"}},{q="De ce sunt luati in vizor druizii de la Stonetalon Peak?",a="Braelyn Firehand vrea sa restabileasca fluxul magiei din zona si ii invinuieste pe druizii din Stonetalon Peak si pe fiii lui Cenarius ca il blocheaza. Ii ucide, impreuna cu conducatorul lor, Keeper Ordanus, despre care pretinde ca l-ar fi cunoscut candva, apoi iti cere sa jefuiesti Barlogul de obiectele sale puternice.",al={"de ce sa atacam druizii din Stonetalon","motivul Hoardei pentru uciderea lui Ordanus","de ce sa jefuim barlogul"}},{q="Ce se afla in Talon Den Hoard?",a="Tezaurul contine relicve puternice si comori adunate de druizii elfi ai noptii. Sigilate sub straturi de protectii, aceste obiecte au fost pastrate in siguranta de intrusi, pana cand Braelyn a reusit sa forteze secventa de securitate.",al={"prada din Talon Den Hoard si lore","ce se afla in comoara","ce au ascuns druizii"}},{q="Ce s-a intamplat chiar inainte de aceasta misiune?",a="Inainte de a patrunde in vizuina, aventurierilor Horde li se cere sa cerceteze prezenta night elf in Cenarius' Legacy si sa-l asasineze pe pazitorul Ordanus, pentru a destrama comanda aparatorilor.",al={"seria de misiuni Den","ce duce la Den","cerinte preliminare pentru Den"}}},fx={["48aeb852"]={q="De ce vrea Braelyn Firehand sa fie pradata comoara?",a="Braelyn Firehand vrea ca fluxul magiei din jurul Stonetalon Peak sa fie restabilit si da vina pe druizi si pe fiii lui Cenarius pentru ca il blocheaza. Dupa ce a vazut cum Keeper Ordanus a fost ucis si a aflat de la unul dintre druizi secretele protectiilor din Den, ea te trimite sa iei obiectele puternice pe care le ascund acolo, in Talon Den.",al={"motivul lui Braelyn","de ce sa jefuiesti vizuina","de ce sa furi din Talon Den"}},["6c65008b"]={q="La ce foloseste Sleepers' Key?",a="Sleepers' Key este una dintre cele trei chei ascunse de druizii elfi ai noptii pentru a-si proteja cele mai de pret relicve. Ascunsa intr-un depozit aflat in adancurile Talon Den, trebuie asezata, alaturi de cheile sale surori, in mecanismul stravechi de incuiere din piatra pentru a deschide Talon Den Hoard.",al={"utilizarea cheii sleepers","scopul cheii sleepers","ce deschide cheia sleepers"}},["1086853e"]={q="La ce foloseste Claw Key?",a="Claw Key este una dintre cele trei chei ascunse de druizii din Stonetalon in jurul vizuinii. Este pastrata intr-un depozit in forma de torta, pe care numai Gatekeeper's Key il poate deschide. Reprezinta a doua componenta a incuietorii cu trei parti care protejeaza Talon Den Hoard din centru.",al={"utilizare claw key","scopul claw key","ce deschide claw key"}},["6ca48c55"]={q="La ce foloseste Barrow Key?",a="Barrow Key este a treia piesa din elaboratul sistem de securitate conceput de druizii din Stonetalon. Ascunsa intr-un depozit de torte, printre radacinile adanci si movilele funerare, aceasta functioneaza impreuna cu cheile Claw si Sleepers pentru a risipi vrajile protectoare din jurul cufarului cu tezaur.",al={"folosirea lui barrow key","scopul lui barrow key","ce deschide barrow key"}}},fp="7,309,20.428.0,17.496.1,22.209.0,45.262.0,36.254.0,53.304.0,35.216.0,38.193.0"}
P.entries["quest:109"] = {n="Report to Gryan Stoutmantle",s="Westfall are nevoie de luptatori, iar Report to Gryan Stoutmantle te trimite sa raspunzi chemarii. Coroana ii lasa pe oamenii din tinuturile agricole de la margine sa se descurce singuri, asa ca aparatorii locali se strang in jurul lui Gryan Stoutmantle la Sentinel Hill.",h="Westfall are nevoie de luptatori, iar Report to Gryan Stoutmantle te trimite sa raspunzi chemarii.",kw={"defias","elwynn","gryan stoutmantle","marshal dughan","people's militia","sentinel hill","stormwind","westfall"},ang={["class:Warrior"]="Ca Warrior, aduci disciplina calita de experienta pe care o pretuieste Gryan Stoutmantle, devenind un luptator important pentru People's Militia, aflata in inferioritate numerica.",["faction:Alliance"]="Ca membru al Alliance, vezi cetateni obisnuiti alcatuind militii pentru a supravietui, in timp ce curtea regala dezbate politica in Stormwind.",["race:Human"]="Ca Human al regatului, vezi prapastia dintre strazile de marmura sigure din Stormwind City si ogoarele aspre si neglijate de dincolo."},sec={{t="Un apel de dincolo de rau",b="Westfall cere luptatori priceputi de peste rau. Talharii, gnoll-ii si golemi ostili ai recoltelor arunca tinuturile agricole in haos. Cum niciun batalion regal nu raspunde chemarii, voluntarii locali trebuie sa apere regatul."},{t="Sentinel Hill si militia",b="Drumul te duce la Gryan Stoutmantle, in turnul de piatra de pe culmea Sentinel Hill. El conduce People's Militia, o forta alcatuita din fermieri, veterani retrasi si mercenari, formata ca raspuns la lipsa de reactie a coroanei. Tinuturile agricole sunt cuprinse de un razboi de gherila crancen impotriva faradelegilor."}},faq={{q="Cine este Gryan Stoutmantle?",a="Gryan Stoutmantle este un luptator veteran care comanda People's Militia. El organizeaza apararea Westfall din turnul aflat pe Sentinel Hill si aduna luptatori pentru a-i proteja pe fermieri de banditi si bestii.",al={"Gryan Stoutmantle","cine este Stoutmantle","liderul din Sentinel Hill"}},{q="De ce este necesara People's Militia?",a="People's Militia este necesara deoarece armata din Stormwind si-a indreptat atentia spre capitala, lasand Westfall cu putin sprijin regal. Locuitorii au format militia pentru a se apara de banditi, automati de recolta scapati de sub control si gnolli Riverpaw pradalnici.",al={"de ce militia","de ce nu exista o armata Stormwind","de ce este Westfall abandonat"}},{q="Unde se afla Sentinel Hill?",a="Sentinel Hill se afla aproape de centrul Westfall, de-a lungul drumului principal. Turnul sau de veghe solid, din piatra, si tabara fortificata sunt locuri de adunare pentru People's Militia.",al={"gaseste Sentinel Hill","locatia Sentinel Hill","unde il gasesti pe Stoutmantle"}},{q="Cine ii trimite pe aventurieri in aceasta misiune?",a="Marshal Dughan din Goldshire, garzi de frontiera precum Guard Thomas si Deputy Rainer, precum si fermieri stramutati precum Farmer Furlbrow si Farmer Saldean ii trimit luptatori capabili lui Gryan.",al={"cine ofera misiunea","personaje care ofera misiuni","personajul care te trimite la Gryan"}},{q="Ce se intampla dupa ce ii raportezi lui Gryan?",a="Cand te prezinti lui Stoutmantle, el iti pune abilitatile de lupta in slujba People's Militia. Primele tale misiuni ii vizeaza pe proscrisii Defias si pe gnoll care ameninta Westfall.",al={"ce urmeaza","continuarea pentru Stoutmantle","lantul de misiuni al militiei"}},{q="Mai face Westfall, din punct de vedere tehnic, parte din Alliance?",a="Da. Westfall ramane teritoriu Alliance, sub autoritatea nominala a Kingdom of Stormwind. Garnizoana coroanei neglijeaza provincia, lasand cetatenii inarmati sa o apere.",al={"Westfall este alianta","Stormwind detine Westfall"}}},fx={a1beb42d={q="De ce ti se cere sa te prezinti la Gryan Stoutmantle?",a="In timp ce Stormwind isi concentreaza fortele militare in interior si lasa Westfall aproape cu totul in voia banditilor si a jefuitorilor, cei care tin linia acolo sunt suprasolicitati. Gryan Stoutmantle si People's Militia au nevoie disperata de luptatori cu experienta pentru a apara ce a mai ramas din terenurile agricole. Cei care te trimit din Elwynn inteleg ca priceperea ta in lupta se iroseste patruland prin livezi pasnice, cand Westfallul vecin se scufunda cu totul in haos.",al={"de ce sa te raportezi la Stoutmantle","de ce Westfall","Dughan Westfall Stoutmantle de ce"}},e97846b7={q="De ce are Gryan Stoutmantle nevoie de aventurieri independenti in locul garzilor din Stormwind?",a="Monarhia din Stormwind a refuzat sa trimita intariri regulate ale armatei in Westfall, lasand provincia practic abandonata de coroana. Garzile locale si militia nu pot face fata numarului urias de banditi, gnolli si proscrisi care napadesc fermele. Gryan Stoutmantle trebuie sa se bazeze pe mercenari si aventurieri capabili, precum tine, care au dovedit ca au experienta reala de lupta si sunt dispusi sa puna mana pe arme pentru cauza lor.",al={"de ce eu in westfall","de ce sa trimita aventurieri in locul armatei","de ce are militia oamenilor nevoie de ajutor"}}},fp="27,215,23.217.0,29.264.0,25.209.0,35.263.0,31.162.0,41.180.0,38.176.0,51.175.0"}
P.entries["quest:1090"] = {n="Gerenzo's Orders",s="La situl de excavare al Venture Company din Stonetalon Mountains, un goblin alungat pe nume Piznik pune la cale demascarea noului sau sef, Gerenzo. Aparandu-l pe Piznik de patrulele taberei in timp ce extrage un minereu ciudat, auriu-verzui, aventurierii ajuta la dezvaluirea secretelor profitabile din spatele excavatiilor agresive ale companiei.",h="La situl de excavare al Venture Company din Stonetalon Mountains, un goblin alungat pe nume Piznik pune la...",kw={"gerenzo","minereu aur-verde","minereu misterios","piznik","stonetalon mountains","venture company","windshear crag","ziz fizziks"},ang={["faction:Horde"]="Exploatarile miniere nechibzuite si distructive ale Venture Company devasteaza peisajul natural din Stonetalon, astfel ca orice efort de a le supraveghea, sabota sau exploata operatiunile le este de folos fortelor Horde din apropiere.",["profession:Mining"]="Minereul ciudat, auriu-verzui, descoperit de minerii Venture Company in Stonetalon nu seamana cu filoanele obisnuite de fier sau cositor, starnind curiozitatea oricarui prospector interesat de minerale rare."},sec={{t="Tradarea corporativa in stancarie",b="Operatiunile masive ale Venture Company din Stonetalon se bazeaza pe o competitie nemiloasa, in care avansarile se castiga prin cruzime, nu prin loialitate. Candva, Piznik se bucura de statutul de mana dreapta a sefului sapaturilor, pana cand Gerenzo a preluat puterea, l-a indepartat pe supraveghetorul Ziz Fizziks si l-a retrogradat pe Piznik, punandu-l sa dea cu tarnacopul in pamant. In loc sa plece, Piznik a ramas ca informator, la ordinul lui Ziz, urmarind fiecare miscare a lui Gerenzo si asteptand clipa potrivita pentru a se razbuna pe noul sau supraveghetor tradator."},{t="Dezgroparea filoanei aurii-verzi",b="Preluarea brusca a puterii de catre Gerenzo este motivata de obsesia sa pentru un minereu misterios, verzui-auriu, care strabate rocile din Stonetalon. Convins ca mineralul are o valoare comerciala extraordinara, Gerenzo le-a poruncit minerilor sa scoata din pamant cantitati uriase. Banuid ca misteriosul nou angajator al lui Ziz Fizziks va plati generos pentru informatii despre proiect, Piznik risca sa fie descoperit ca sa dezgroape o mostra intacta, bazandu-se pe un aliat care sa tina la distanta sapatorii agresivi, daunatorii si supraveghetorii ce patruleaza prin zona."}},faq={{q="Cine este Piznik?",a="Piznik este un muncitor goblin de la exploatarea din Windshear Crag, in Stonetalon Mountains. Odinioara era al doilea cel mai important administrator al sitului minier, sub conducerea lui Ziz Fizziks, dar dupa ce Gerenzo a preluat controlul, Piznik a fost retrogradat si trimis sa munceasca in mine ca simplu salahor.",al={"piznik","cine este minerul goblin","piznik stonetalon"}},{q="De ce exploateaza Piznik acest minereu pe ascuns?",a="Piznik strange pe ascuns o mostra dintr-un mineral neobisnuit, de culoare verde-aurie, a carui extragere in cantitati uriase a fost comandata de Gerenzo. Fostul sau sef, Ziz Fizziks, i-a promis ca noul angajator va plati bine pentru informatii despre orice operatiune valoroasa desfasurata de Gerenzo.",al={"de ce sa extragi minereu","minereu misterios","minereu auriu-verzui"}},{q="Cine este Gerenzo?",a="Gerenzo este supraveghetorul nemilos al Venture Company, care a preluat controlul asupra sapaturilor din Stonetalon dupa ce l-a concediat pe Ziz Fizziks. A redirectionat imediat resursele companiei spre excavarea agresiva a unui minereu aur-verzui, necunoscut si valoros, gasit pretutindeni in stancarii.",al={"Gerenzo","cine este Gerenzo","Gerenzo de la Venture Co"}},{q="Pentru cine lucreaza acum Ziz Fizziks?",a="Dupa ce a fost concediat de Gerenzo, Ziz Fizziks s-a aliat cu noi sustinatori interesati sa supravegheze activitatile Venture Company din regiune. El ii plateste pe agenti si informatori precum Piznik sa-l saboteze pe Gerenzo si sa afle ce dezgroapa Venture Company.",al={"noul sef al lui ziz","cine l-a angajat pe ziz","angajatorul lui ziz"}},{q="Ce il ataca pe Piznik in timp ce sapa?",a="Lucratorii Venture Company ataca in timpul sapaturilor, printre ei numarandu-se Windshear Tunnel Rats, Windshear Vermin, sapatori, geomantii, cioplitori in piatra si supraveghetori.",al={"ambuscada lui piznik","cine il ataca pe piznik","patrulele windshear"}},{q="Ce se intampla dupa ce este extras esantionul?",a="Dupa ce Piznik extrage cu succes mostra de minereu, i-o da protectorului sau, ca acesta s-o duca direct la Ziz Fizziks, in speranta ca ii va oferi parghia necesara pentru a zadarnici planurile ambitioase ale lui Gerenzo.",al={"unde sa duci minereul","ce sa faci cu mostra"}}},fx={["0d43f256"]={q="De ce are nevoie Piznik de ajutorul tau in loc sa extraga singur minereul?",a="Muncitorii Venture Company il supravegheaza pe Piznik la situl de excavare. Are nevoie de un aliat care sa tina patrulele la distanta in timp ce extrage o mostra de minereu pentru Ziz Fizziks.",al={"de ce are Piznik nevoie de mine","de ce sa-l ajut pe Piznik","de ce nu poate Piznik sa sape singur"}}},fp="16,300,30.527.0,30.511.0,14.259.0,39.273.0,15.260.0,34.252.0,34.154.0,38.190.0"}
P.entries["quest:1091"] = {n="Kaela's Update"}
P.entries["quest:1092"] = {n="Gerenzo's Orders",s="Dupa ce a respins patrulele sitului de excavare si a obtinut o mostra din minereul neobisnuit pe care Gerenzo a poruncit sa-l extraga, Piznik trimite aventurieri sa duca mostra la contactul sau, Ziz Fizziks. Livrarea incheie o misiune riscanta de spionaj corporatist, in adancurile operatiunilor Venture Company din Windshear Crag.",h="Dupa ce a respins patrulele sitului de excavare si a obtinut o mostra din minereul neobisnuit pe care Gerenzo...",kw={"ordinele lui Gerenzo","Piznik","Stonetalon","Undermine","Unidentified Ore","Venture Company","Windshear Crag","Ziz Fizziks"},ang={["profession:Engineering"]="Inginerii Goblin din Undermine platesc generos pentru minereuri exotice, neprelucrate, capabile sa alimenteze mecanisme si prototipuri noi si instabile.",["profession:Mining"]="Unidentified Ore extras la porunca lui Gerenzo arata ca operatiunile de defrisare ale Venture Company din Windshear Crag urmaresc la fel de mult sa scotoceasca muntii dupa bogatii subterane necunoscute."},sec={{t="Un bilet spre iesire",b="Dupa ce i-a fost demascata identitatea in urma luptei de la situl de excavare, Piznik stie ca timpul petrecut printre membrii echipajului Venture Company de la Windshear Crag s-a incheiat. Conducerea corporatiei din Undermine nu priveste cu ochi buni sabotajul intern, asa ca goblinul nelinistit isi pune la cale evadarea. Inainte de a se strecura departe, in cautarea unui nou angajator, incredinteaza Unidentified Ore, extras la ordinele lui Gerenzo, unui strain, asigurandu-se ca pretiosul specimen va fi livrat in siguranta fara sa atraga suspiciuni asupra sa."},{t="Curiozitati corporatiste",b="Minereul este destinat lui Ziz Fizziks, care si-a infiintat un avanpost secret pe marginea vestica a Windshear Crag. Ziz intelege valoarea strategica a mineralului si intentioneaza sa-l trimita spre sud, inginerilor din Undermine, pastrand pe ascuns o parte valoroasa pentru profitul propriu. Un asemenea pragmatism egoist scoate in evidenta caracterul nemilos al disputelor comerciale si ingineresti care mocnesc sub piscurile din Stonetalon Mountains."}},faq={{q="De ce trebuie sa fuga Piznik din Windshear Crag?",a="Supraveghetorii sitului l-au prins pe Piznik in timp ce extragea pe ascuns o mostra de minereu pentru Ziz, dandu-i de gol acoperirea de informator. Stie ca, de indata ce sefii Venture Company vor afla ce s-a intamplat, razbunarea va fi rapida, asa ca trebuie sa se strecoare de acolo si sa-si gaseasca un nou loc de munca.",al={"de ce pleaca Piznik","Piznik fugar","de ce e speriat Piznik"}},{q="Cine este Ziz Fizziks?",a="Ziz Fizziks este un agent Goblin instalat pe creasta vestica din Windshear Crag. L-a infiltrat pe Piznik in Venture Company pentru a fura informatii confidentiale despre companie si mostre de minerale rare.",al={"cine este ziz","rolul lui ziz fizziks","unde se afla ziz"}},{q="Ce este Unidentified Ore?",a="Este un esantion din minereul misterios auriu-verzui, pe care Chief Engineer Gerenzo a ordonat sa fie extras in cantitati mari. Ziz Fizziks intentioneaza sa-l trimita cercetatorilor si inginerilor din Undermine pentru a-i analiza utilizarile industriale.",al={"unidentified ore poveste","ce este minereul","gerenzo minereu"}},{q="Unde poate fi gasit Ziz Fizziks?",a="Ziz Fizziks se ascunde intr-o tabara mica, cocotata pe marginea vestica, cu vedere spre Windshear Crag, in Stonetalon Mountains.",al={"locatia lui ziz fizziks","gaseste-l pe ziz","unde predau ordinele lui gerenzo"}},{q="Ce se intampla cu minereul dupa ce il primeste Ziz?",a="Ziz planuieste sa trimita cea mai mare parte a mostrei de minereu inginerilor din Undermine pentru profit si reputatie, pastrand pentru sine o mica aschie fara stirea angajatorilor sai.",al={"ce face ziz cu minereul","ziz pastreaza minereul"}},{q="Ii este loial Piznik organizatiei Venture Company?",a="Piznik a lucrat pentru Venture Company doar atat cat sa serveasca interesele lui Ziz. Nu este deloc loial sindicatului si se teme de represaliile conducerii acestuia.",al={"factiunea lui piznik","piznik face parte din venture co","pentru cine lucreaza piznik"}}},fx={["692a35ea"]={q="De ce te pune Piznik sa livrezi minereul in loc sa-l duca el insusi?",a="Piznik nu poate pleca imediat, fiindca are nevoie de timp sa-si stearga urmele si sa curete harababura ramasa in urma, inainte de a se strecura departe de Venture Company. Vestea incidentului va ajunge repede la superiorii sai, asa ca iti incredinteaza Unidentified Ore, pentru ca aceasta sa ajunga fara intarziere si in siguranta la Ziz Fizziks.",al={"de ce ma trimite piznik","de ce nu poate piznik sa livreze minereul","de ce eu, piznik"}}},fp="16,298,12.479.0,21.444.1,44.277.0,19.182.0,29.220.0,31.126.0,45.173.0,39.171.0"}
P.entries["quest:1093"] = {n="Super Reaper 6000"}
P.entries["quest:1094"] = {n="Further Instructions",s="Further Instructions este o misiune de livrare care leaga operatiunile haotice de exploatare forestiera din Stonetalon Mountains de centrul comercial Ratchet. Inventatorul nemultumit Ziz Fizziks trimite un curier cu planuri furate si documente interne catre omologul sau, Sputtervalve, incercand sa transforme spionajul corporatist intr-un avantaj personal.",h="Further Instructions este o misiune de livrare care leaga operatiunile haotice de exploatare forestiera din...",kw={"Barrens","instructiuni suplimentare","Ratchet","Sputtervalve","Stonetalon","Super Reaper 6000","Venture Company","Ziz Fizziks"},ang={["faction:Horde"]="Transportarea planurilor furate ale Venture Company la Ratchet contribuie la razboaiele comerciale mocnite, care submineaza teritoriile Horde din calea unei expansiuni industriale periculoase.",["profession:Engineering"]="Plicul intruchipeaza industria goblina clasica in actiune: spionaj corporatist nemilos, furt de patente si inginerie inversa aplicata unor utilaje complexe de recoltat lemn."},sec={{t="Spionaj corporatist",b="Cand Ziz Fizziks a fost dat afara din operatiunile de exploatare forestiera ale Venture Company din Windshear Crag, nu a plecat cu mana goala. Amarat din cauza concedierii, Fizziks a sustras mai multe documente sensibile, manuale interne si scheme tehnice, iar captura sa cea mai de pret au fost planurile experimentului Super Reaper 6000. Disperat sa gaseasca un cumparator sau un aliat dornic sa foloseasca informatiile, a pecetluit secretele adunate intr-un plic adresat catre Ratchet."},{t="Legatura cu Ratchet",b="Cel care primeste documentele furate este Sputtervalve, un inginer aflat in portul neutru Ratchet din Barrens. Desi Sputtervalve nu are mare afectiune sau incredere in Fizziks, rivalitatea cu Venture Company face oferta imposibil de refuzat. Goblinii afiliati Steamwheedle cauta neincetat modalitati de a reduce influenta necrutatorului lor concurent si, in acelasi timp, nu ezita sa reproduca prin inginerie inversa orice inovatii mecanice superioare descopera."}},faq={{q="Ce se afla in Sealed Envelope?",a="Plicul contine documente interne ale Venture Company, manuale tehnice si schite pentru Super Reaper 6000, furate de Ziz Fizziks dupa ce a fost alungat din operatiunea lor de exploatare forestiera.",al={"continutul plicului","ce trimite fizziks","documente furate"}},{q="Cine este Sputtervalve?",a="Sputtervalve este un inginer goblin care locuieste in Ratchet, in Barrens. Desi nu are deplina incredere in Ziz Fizziks, abia asteapta sa slabeasca Venture Company si sa-i cerceteze progresele mecanice.",al={"identitatea lui Sputtervalve","cine este destinatarul","inginerul din Ratchet"}},{q="De ce lucreaza Ziz Fizziks impotriva Venture Company?",a="Fizziks a fost dat afara fara ceremonie din randurile Venture Company din Stonetalon. Plin de ranchiuna si dornic de razbunare, a inceput sa le dezvaluie secretele comerciale rivalilor.",al={"de ce a tradat fizziks venture co","motivul lui fizziks"}},{q="Unde poate fi gasit Sputtervalve?",a="Sputtervalve se afla in orasul-port neutru Ratchet, situat pe coasta estica a regiunii Barrens.",al={"unde se afla sputtervalve","locatia lui sputtervalve","gaseste-l pe sputtervalve"}},{q="Are incredere Sputtervalve in Ziz Fizziks?",a="Nu. Sputtervalve recunoaste deschis ca nu are incredere in Fizziks, dar valoarea manualelor tehnice si a schitelor depaseste neincrederea pe care i-o inspira mesagerul.",al={"are incredere Sputtervalve in Fizziks","relatia dintre Fizziks si Sputtervalve"}},{q="Ce este Super Reaper 6000?",a="Este un tocator industrial avansat, creat de Venture Company pentru a curata padurile si a prelucra lemnul cu mare viteza, ceea ce face ca planurile sale sa fie foarte ravnite.",al={"Super Reaper 6000","ce este masina","secera Venture Co"}}},fx={["98641ea6"]={q="De ce are nevoie Ziz Fizziks de un aventurier care sa livreze plicul?",a="Ziz Fizziks se ascunde in Stonetalon Mountains, dupa ce a fost alungat de Venture Company. Lipsit de functie si inconjurat de fostii colegi ostili, precum si de primejdiile din Crag, nu poate strabate in siguranta Kalimdor pana la Ratchet. Incredintarea planurilor sensibile si a documentelor furate unui calator capabil ii garanteaza ca informatiile vor ajunge la Sputtervalve fara sa-si puna singur gatul in primejdie.",al={"de ce eu instructiuni suplimentare","de ce are Ziz nevoie de mine","de ce nu poate Ziz sa livreze plicul"}}},fp="20,331,19.466.0,22.486.0,35.189.0,20.198.0,55.162.0,32.110.0,36.152.0,30.159.0"}
P.entries["quest:1095"] = {n="Further Instructions",s="Further Instructions marcheaza o escaladare a politicii corporatiste a goblinilor, ordonand asasinarea unui inginer gnom renegat, angajat de Mogul Razdunk. Sputtervalve transmite directive sosite din inima Undermine, poruncindu-i lui Ziz Fizziks sa-l elimine pe Gerenzo Wrenchwhistle in Stonetalon Mountains.",h="Further Instructions marcheaza o escaladare a politicii corporatiste a goblinilor, ordonand asasinarea unui...",kw={"instructiuni suplimentare","gerenzo wrenchwhistle","gnomeregan","razdunk","riddlevox","sputtervalve","stonetalon","undermine","venture company","ziz fizziks"},ang={["profession:Engineering"]="Rivalitatea acerba dintre ingineria gnomilor si cea a goblinilor capata aici o turnura literala, trecand de la dezbateri despre brevete de design la asasinate corporatiste in toata regula.",["race:Gnome"]="Agentii goblini mentioneaza trecutul lui Gerenzo ca inginer-sef in Gnomeregan, unde un experiment secret a detonat catastrofal chiar in fata inginerilor."},sec={{t="Dezaprobarea corporatiei",b="Venture Company actioneaza dintr-o dorinta nemiloasa de profit, dar angajarea unor specialisti din afara poate starni conflicte interne aprige. Cand Mogul Razdunk l-a primit in randurile sale pe inginerul gnome Gerenzo, vestea a ajuns pana la Undermine si i-a nemultumit pe Trade Princes aflati la conducere. Directorul Riddlevox i-a poruncit lui Sputtervalve sa intervina si sa rezolve situatia fara zarva. Dandu-si seama ca ordinul venea de la cele mai inalte autoritati comerciale, Sputtervalve paseaza treaba murdara agentului cel mai apropiat de locul faptei: Ziz Fizziks."},{t="Secretele din Dun Morogh",b="Dupa ce primeste ordinul de asasinare, Ziz Fizziks se avanta cu entuziasm in misiune. Inginerii goblini ii dispretuiesc din fire pe rivalii gnomi, dar trecutul personal al lui Gerenzo il face o tinta deosebit de imprevizibila. Inainte sa se alature companiei Venture Company, Gerenzo fusese inginer-sef in Gnomeregan si participase la un proiect strict secret, pe care spionii din Undermine nu au reusit sa-l descopere pe deplin. Se spune ca proiectul s-a incheiat cu un dezastru, explodandu-le literalmente in fata inginerilor, iar Gerenzo isi vinde acum priceperea periculoasa companiei Venture Company din Kalimdor."}},faq={{q="Cine este Sputtervalve?",a="Sputtervalve este un agent goblin care lucreaza sub conducerea directorului Riddlevox. Actionand la ordinele venite din Undermine, el coordoneaza operatiunile de teren si transmite contracte agentilor locali precum Ziz Fizziks.",al={"sputtervalve","cine da misiunea","cel care da misiunea sputtervalve"}},{q="De ce le pasa Printilor Negustori de Gerenzo?",a="Printii Comertului din Undermine dezaproba cu tarie faptul ca Mogul Razdunk se insoteste cu ingineri gnomi din afara. Angajarea unor ne-goblin cu reputatie ameninta dominatia industriala a goblinilor si atrage o atentie nedorita.",al={"de ce le pasa printilor negustori","furia Undermine","Gerenzo si printii negustori"}},{q="La ce proiect secret a lucrat Gerenzo?",a="Gerenzo era inginer-sef in Gnomeregan si lucra la un proiect secret in care spionii goblini nu au reusit niciodata sa se infiltreze. Se spune ca orice ar fi construit s-a incheiat cu un dezastru catastrofal, explodandu-le literalmente in fata inginerilor implicati.",al={"proiectul secret al lui Gerenzo","explozia din Gnomeregan","trecutul lui Gerenzo"}},{q="Unde se afla Ziz Fizziks?",a="Ziz Fizziks este stationat in Stonetalon Mountains, unde supravegheaza activitatile locale de exploatare forestiera si miniera ale Venture Company, indeplinind totodata contracte corporatiste.",al={"locatia lui Ziz Fizziks","unde este Ziz","unde trebuie livrate ordinele"}},{q="De ce abia asteapta Ziz Fizziks sa-l omoare pe Gerenzo?",a="Dincolo de ura profesionala a goblinilor fata de gnomi, Fizziks il considera pe Gerenzo un rival periculos, ale carui experimente esuate din Dun Morogh il fac primejdios pentru toti cei din jur.",al={"de ce il uraste Ziz pe Gerenzo","reactia lui Fizziks","de ce sa-l omori pe Gerenzo"}},{q="Cine este Mogul Razdunk?",a="Mogul Razdunk este directorul general al Venture Company. Decizia sa de a-l angaja pe Gerenzo a sfidat direct eticheta comerciala traditionala din Undermine, determinandu-i pe Trade Princes sa insiste pentru eliminarea lui Gerenzo.",al={"Mogul Razdunk","cine este Razdunk","seful Venture Company"}}},fx={["36e39e8c"]={q="De ce vrea Sputtervalve ca aceasta sarcina sa fie indeplinita?",a="Sputtervalve a primit ordine direct de la directorul Riddlevox, care raspunde presiunilor exercitate de Printii Negustori din Undermine. Decizia lui Mogul Razdunk de a-l angaja pe gnomul Gerenzo Wrenchwhistle a scandalizat conducerea goblinilor. Pentru a-si proteja propria pozitie si a indeplini cerintele superiorilor, Sputtervalve trebuie sa se asigure ca Gerenzo este eliminat. El considera ca transmiterea ordinelor catre Ziz Fizziks este modul ideal de a implini vointa celor din Undermine si de a pune la incercare capacitatile lui Fizziks.",al={"de ce sa trimiti ordine","motivul lui sputtervalve","de ce sa-l omori pe gerenzo"}}},fp="20,307,21.516.0,21.542.1,20.198.0,44.219.0,40.235.0,29.161.0,41.176.0,21.212.0"}
P.entries["quest:1096"] = {n="Gerenzo Wrenchwhistle",s="Aceasta recompensa le cere aventurierilor sa-l elimine pe Gerenzo Wrenchwhistle, un supraveghetor gnome renegat, catarat sus, deasupra Cragpool Lake, in Stonetalon Mountains. Gerenzo si-a augmentat considerabil carnea in descompunere cu roti dintate, mecanisme de ceasornic si membre artificiale. Inginerul goblin Ziz Fizziks vrea bratul sau mecanic drept dovada incontestabila a mortii sale, pentru a obtine o promovare ravnita din partea superiorilor.",h="Aceasta recompensa le cere aventurierilor sa-l elimine pe Gerenzo Wrenchwhistle, un supraveghetor gnome...",kw={"cragpool lake","cyborg","gerenzo","brat mecanic","sputtervalve","stonetalon","wrenchwhistle","ziz fizziks"},ang={["faction:Horde"]="Ajutorul dat contractantilor goblini din Stonetalon contribuie la asigurarea unor resurse si teritorii valoroase, perturbarea inginerilor rebeli periculosi din munti.",["profession:Engineering"]="Constructia macabra a bratului mecanic al lui Gerenzo reprezinta o culme tulburatoare a ingineriei bionice gnomice, in contrast puternic cu designul practic al goblinilor.",["race:Gnome"]="Gerenzo reprezinta o abatere excentrica si macabra de la ingeniozitatea gnomica obisnuita, apeland la augmentari radicale ale propriului corp pentru a-si pastra trupul tot mai slabit."},sec={{t="Un hibrid monstruos",b="Gerenzo Wrenchwhistle este renumit chiar si printre mestesugarii cu experienta pentru transformarile fizice ingrozitoare prin care a trecut. Potrivit celor care l-au vazut, carnea sa naturala pare sa putrezeasca, acoperita pe alocuri de roti dintate grefate, placi de fier si proteze mecanice zumzaind. Asezat langa uriasa roata de apa de deasupra Cragpool Lake, gnomul supravegheaza operatiunile cu precizie mecanica si o nepasare tulburatoare fata de propria conditie de muritor."},{t="Ambitiile Goblin",b="Ziz Fizziks, un goblin care lucreaza in numele lui Sputtervalve, considera prabusirea lui Gerenzo biletul sau de iesire din tinuturile izolate ale Stonetalon. Neavand forta fizica sa urce stancile sau sa-l invinga singur pe supraveghetorul imbunatatit, Ziz angajeaza un aventurier sa-l doboare pe Gerenzo si sa-i recupereze bratul mecanic. Inarmat cu acest trofeu, Ziz spera sa-si dovedeasca valoarea si sa obtina un transfer la atelierele prestigioase ale Tinkers' Union din Gadgetzan sau Undermine."},{t="Filozofii contradictorii",b="Recuperarea bratului mecanic al lui Gerenzo scoate in evidenta profunda prapastie ideologica dintre traditiile ingineresti ale goblinilor si gnomilor. Gerenzo a recurs la masura extrema, proprie gnomilor, de a-si amputa carnea care ceda pentru a integra proteze complexe, gest pe care goblinii il considera de neinteles. Dupa cum remarca Ziz, adevarata ingeniozitate goblin nu arunca un membru biologic - i-ar monta pur si simplu un al treilea brat exploziv alaturi de celelalte doua."}},faq={{q="Cine este Gerenzo Wrenchwhistle?",a="Gerenzo Wrenchwhistle este un supraveghetor Gnome renegat din Stonetalon Mountains. Este cunoscut pentru ca inlocuieste parti din carnea si membrele sale in putrefactie cu proteze mecanice si rotite, supraveghind operatiunile industriale aflate sus, deasupra lacului Cragpool Lake.",al={"gerenzo","cine este gerenzo","povestea lui gerenzo"}},{q="Unde poate fi gasit Gerenzo Wrenchwhistle?",a="Gerenzo se afla la nord-est de pozitia lui Ziz Fizziks, sus, mult deasupra apelor lacului Cragpool Lake, langa o mare roata hidraulica industriala.",al={"locatia lui gerenzo","gaseste-l pe gerenzo","unde este gerenzo"}},{q="De ce vrea Ziz Fizziks sa-l ucida pe Gerenzo?",a="Ziz Fizziks actioneaza la ordinele lui Sputtervalve. Eliminarea lui Gerenzo ii dovedeste competenta lui Ziz, iar el spera ca astfel va obtine transferul la un atelier important al Tinkers' Union din Gadgetzan sau Undermine.",al={"de ce sa-l ucizi pe Gerenzo","motivul lui Ziz","scopul lui Ziz Fizziks"}},{q="Ce dovada ii trebuie lui Ziz?",a="Ziz are nevoie de bratul mecanic grefat al lui Gerenzo ca dovada palpabila si incontestabila ca supraveghetorul cyborg a fost scos definitiv din functiune.",al={"ce dovada","dovada Gerenzo","obiectivul misiunii"}},{q="De ce este Gerenzo partial mecanic?",a="Carnea vie a lui Gerenzo parea sa putrezeasca, ceea ce l-a indemnat sa-si prinda direct de trup angrenaje, placi de fier si membre mecanice, pentru a se mentine in viata si a-si spori capacitatile.",al={"de ce este gerenzo cyborg","gerenzo robot","corpul lui gerenzo"}},{q="Cine este Sputtervalve?",a="Sputtervalve este un supraveghetor goblin important, care conduce operatiunile si le da ordine subalternilor precum Ziz Fizziks din alte locuri din Kalimdor.",al={"sputtervalve","cine este sputtervalve"}}},fx={["94dcbf90"]={q="De ce are Ziz Fizziks nevoie ca tu sa te ocupi de Gerenzo?",a="Ziz Fizziks este inginer, nu luptator de prima linie. Gerenzo Wrenchwhistle s-a baricadat sus, deasupra lacului Cragpool Lake, inconjurat de operatiunile de exploatare forestiera si de utilajele Venture Company. Ziz recunoaste ca nu are nicio sansa sa razbata singur prin exploatarea forestiera ostila, cu atat mai putin sa-l invinga pe gnomul puternic augmentat din varful santierului. Are nevoie de un aventurier capabil sa strapunga apararea si sa duca treaba la bun sfarsit.",al={"de ce eu, Gerenzo","de ce nu-l ucide Ziz pe Gerenzo","de ce sa angajezi un aventurier"}}},fp="21,399,18.462.0,16.460.0,21.423.0,29.259.0,41.139.0,39.200.0,28.137.0,33.171.0,20.137.0"}
P.entries["quest:1097"] = {n="Elmore's Task"}
P.entries["quest:1098"] = {n="Deathstalkers in Shadowfang",s="High Executor Hadrec trimite aventurieri din Horde in Shadowfang Keep, sa-i gaseasca pe cei doi agenti de recunoastere disparuti, Deathstalker Adamant si Deathstalker Vincent. Armata Forsaken se bazeaza pe informatiile adunate de ei pentru a coordona un atac impotriva lui Archmage Arugal si a haitelor sale de worgen. Patrunderea in fortareata dezvaluie cruda realitate a spionajului din spatele liniilor inamice.",h="High Executor Hadrec trimite aventurieri din Horde in Shadowfang Keep, sa-i gaseasca pe cei doi agenti de...",kw={"adamant","arugal","deathstalkers in shadowfang","hadrec","sepulcher","shadowfang keep","silverpine","vincent"},ang={["class:Rogue"]="Disparitia Deathstalkers demonstreaza riscurile misiunilor de recunoastere din spatele liniilor fortificate ale inamicului.",["faction:Horde"]="High Executor Hadrec se bazeaza pe campionii Horde pentru a sprijini operatiunile Forsaken atunci cand trupele conventionale nu pot patrunde in fortareata blestemata a lui Arugal.",["race:Undead"]="Pentru Forsaken, recucerirea Silverpine de la bestiile lui Arugal este esentiala pentru asigurarea Lordaeronului. Cercetasii disparuti arata cat de periculoasa este aceasta lupta."},sec={{t="In vizuina Worgen",b="Silverpine Forest ramane un teritoriu disputat, iar worgenii salbatici ai lui Archmage Arugal stapanesc reduta impunatoare a fortaretei Shadowfang Keep. Pentru a rupe acest asediu de la granitele lor sudice, comandamentul Forsaken din Sepulcher a organizat o operatiune de spionaj. High Executor Hadrec i-a trimis pe doi Deathstalkers cu experienta - Adamant si Vincent - sa se infiltreze in fortareata si sa-i cartografieze apararea. Cand au trecut zile intregi fara vesti, Hadrec a inceput sa se teama pentru soarta lor si a insarcinat campionii capabili ai Horde sa patrunda in fortareata, sa-i recupereze pe agenti si sa salveze misiunea."},{t="O descoperire amara",b="Dupa ce-si croiesc drum prin bastioanele de jos, aventurierii descopera pretul greu al infiltrarii. Deathstalker Adamant supravietuieste captivitatii si ajuta la deschiderea portilor curtii, insa Vincent a avut un sfarsit brutal. Trupul sau zdrobit zace nemiscat in cetate, iar informatiile pe care le detinea s-au pierdut in salile intunecate. Nu-i mai ramane decat un mic obiect de podoaba, strans in degetele sale reci, marturie tacuta a unui spion care si-a dat viata pentru cucerirea Dark Lady."}},faq={{q="De ce au fost trimisi Deathstalkers la Shadowfang Keep?",a="High Executor Hadrec a ordonat infiltrarea pentru a strange informatii tactice esentiale despre fortele si fortificatiile lui Archmage Arugal, inainte de a trimite trupele Forsaken intr-un asalt de proportii asupra Shadowfang Keep.",al={"de ce sa trimiti spioni la Shadowfang","scopul misiunii lui Hadrec","scopul Deathstalker la Shadowfang"}},{q="Cine sunt Deathstalkers Adamant si Vincent?",a="Sunt agenti de elita Forsaken, membri ai Deathstalkers, ramura de spionaj si asasinat a celor din Undercity. Trimisi in avangarda ca cercetasi, au primit misiunea de a cartografia Shadowfang Keep si de a observa apararea worgen.",al={"cine sunt adamant si vincent","povestea lui adamant si vincent"}},{q="Ce s-a intamplat cu Deathstalker Vincent?",a="Vincent nu s-a intors de la Shadowfang Keep. Hadrec are nevoie de cineva care sa patrunda in fortareata si sa afle ce i s-a intamplat.",al={"a murit Vincent","unde este Vincent","soarta lui Vincent"}},{q="Ce rol are Deathstalker Adamant in interiorul fortaretei?",a="Adamant este unul dintre Deathstalkers disparuti, trimisi sa adune informatii in Shadowfang Keep. Soarta lui este aflata in timpul cautarilor.",al={"ce face adamant","rolul lui deathstalker adamant"}},{q="Unde incepe aceasta misiune?",a="Misiunea este data de High Executor Hadrec, comandantul militar Forsaken aflat in Sepulcher, in Silverpine Forest.",al={"unde gasesti Deathstalkers in Shadowfang","cel care ofera misiunea Deathstalkers in Shadowfang"}},{q="De ce vrea conducerea Forsaken ca Shadowfang Keep sa fie eliberat?",a="Archmage Arugal dezlantuie haite violente de worgen in Silverpine Forest, de la adapostul sau din Shadowfang Keep, amenintand fara incetare teritoriile Forsaken, liniile de aprovizionare si securitatea intregului Lordaeron.",al={"de ce sa ataci Shadowfang","de ce au Forsaken un conflict cu Arugal"}}},fx={["7d643f75"]={q="De ce are High Executor Hadrec nevoie sa gasesti Deathstalkers?",a="High Executor Hadrec pregateste un atac major al celor din Forsaken asupra Shadowfang Keep, dar intreaga strategie depinde de informatii esentiale. I-a trimis inainte pe Deathstalkers Adamant si Vincent sa cerceteze fortareata, dar au trecut zile fara nicio veste. Fara informatii despre puterea si apararea inamicului, orice ofensiva directa ar insemna sa marsaluiasca orbeste spre macel.",al={"de ce vrea hadrec ca acest lucru sa fie facut","motivul lui hadrec in shadowfang","de ce sa-i cauti pe deathstalkers"}},cc510862={q="De ce te trimite High Executor Hadrec pe tine, in locul propriilor trupe?",a="Fortele de paza din Sepulcher sunt raspandite subtire, ocupand linia de aparare din Silverpine, iar trimiterea unei armate sa se infiltreze in Shadowfang fara informatii ar insemna un dezastru. Hadrec are nevoie de un aventurier ingenios si capabil, care sa se strecoare dincolo de perimetrul exterior al fortaretei, sa-si gaseasca cercetasii de elita disparuti si sa le ofere tot ajutorul necesar pentru a salva misiunea.",al={"de ce ma trimit la Shadowfang","de ce sa nu trimita Deathstalkers sau garzile","de ce eu, Hadrec"}}},fp="27,374,19.582.0,18.476.1,47.208.0,42.234.0,38.129.1,57.139.1,30.126.0,62.201.0"}
P.entries["quest:1099"] = {n="Goblins Win!",s="In Thousand Needles, un bilet la cursa goblinilor aduce castiguri cand goblinii ies invingatori. Cutia cu premiul ajunge la cel care avea biletul castigator.",h="In Thousand Needles, un bilet la cursa goblinilor aduce castiguri cand goblinii ies invingatori.",kw={"goblin","cutie cu premii pentru goblin","bilet pentru rasa","thousand needles"},sec={{t="Biletul Goblin",b="Biletul de cursa al goblinilor este talonul care conteaza cand goblinii castiga. Pastreaza-l, iar dupa aflarea rezultatului vei primi o cutie cu premiu goblin. Biletul gnomilor are propriul rezultat, pentru cealalta tabara din cursa."}},faq={{q="Ce este Goblin Race Ticket?",a="Este biletul pentru cursa goblinilor din Thousand Needles. Devine important cand castiga goblinii.",al={"tichet de cursa","ce este tichetul de cursa goblin"}},{q="Ce primesti cand castiga goblinii?",a="Cutia cu premiul pentru goblin ii revine celui care detine biletul cursei goblin atunci cand goblins ies invingatori.",al={"cutia cu premii goblin","goblins castiga premiul"}},{q="Ce se intampla daca gnomes castiga in schimb?",a="Atunci conteaza tichetul gnomului. Rezultatul sau se numeste Gnomes Win!, contrapartea acestuia.",al={"gnomes castiga","bilet pentru cursa gnome"}}},fp="12,140,17.212.0,31.102.0,37.97.0,39.109.0"}
P.entries["quest:11"] = {n="Riverpaw Gnoll Bounty",s="Riverpaw Gnoll Bounty este un contract oficial emis de Deputy Rainer la Westbrook Garrison pentru a rari gnolls care inainteaza si ameninta granitele vestice ale Elwynn Forest. Stormwind Army ofera o recompensa pentru banderolele pictate luate de la Riverpaw packs care infesteaza padurile si apele.",h="Riverpaw Gnoll Bounty este un contract oficial emis de Deputy Rainer la Westbrook Garrison pentru a rari...",kw={"recompensa","deputy rainer","elwynn","gnoll","bratara pictata de gnoll","riverpaw","stone cairn lake","westbrook garrison"},ang={["faction:Alliance"]="Acceptarea recompenselor pentru capete de infractori de la granita iti creste reputatia in cadrul Stormwind Army si ajuta la securizarea rutelor comerciale vitale prin inima regatului.",["race:Human"]="Pentru oamenii regatului, vanarea Riverpaws este un efort direct de a proteja granitele Elwynn si de a sprijini garzile regale suprasolicitate."},sec={{t="O amenintare la granita",b="Westbrook Garrison pazeste tinuturile de granita esentiale dintre Elwynn Forest si Westfall. Cu toate acestea, garnizoana si-a pierdut o mare parte din efective, iar avanpostul se lupta sa tina piept afluxului agresiv de gnoli Riverpaw. Aceste creaturi salbatice si-au ridicat tabere chiar la sud de turnul de straja si mai departe spre est, pe tarmurile Stone Cairn Lake, apropiindu-se indeajuns pentru a-i ameninta pe calatorii pasnici si pe locuitorii din zona."},{t="Pretul ordinii",b="Neputand sa detaseze infanteristi in mod regulat pentru a scotoci padurile, Deputy Rainer pune o recompensa pe capul jefuitorilor. Pentru a confirma uciderile, Rainer cere dovada victoriei in lupta: bratarile de brate pictate ale gnollilor, luate de la fiarele ucise. Angajand aventurieri ratacitori si recruti pentru a rari ceata, garnizoana spera sa opreasca inaintarea Riverpaws inainte ca acestia sa cotropeasca tinuturile vestice de frontiera."}},faq={{q="Unde pot fi gasiti gnollii Riverpaw in Elwynn Forest?",a="Gnollii Riverpaw se aduna mai ales in doua locuri din Elwynn: in padurile dese, chiar la sud de Westbrook Garrison, langa malurile raului, si mai la est, de-a lungul marginii Stone Cairn Lake.",al={"locatiile gnollilor","unde sunt gnollii","locatiile Riverpaw"}},{q="De ce cere garnizoana ajutorul aventurierilor impotriva gnollilor?",a="Westbrook Garrison duce lipsa de personal si este supusa presiunii de-a lungul granitelor din Elwynn. Neavand destui garzi pentru a patrula perimetrul si a lansa in acelasi timp incursiuni ofensive, Deputy Rainer apeleaza la campioni independenti pentru a vana gnolii.",al={"de ce are Deputy Rainer nevoie de ajutor","de ce angajeaza garnizoana mercenari"}},{q="Ce dovezi ii sunt necesare lui Deputy Rainer?",a="Deputy Rainer are nevoie de opt Painted Gnoll Armbands drept dovada concreta ca fiarele invadatoare au fost doborate.",al={"dovada recompensei","ce sa adun pentru rainer"}},{q="Cine sunt gnolii Riverpaw?",a="Riverpaws sunt un trib de umanoizi asemanatori hienelor, cunoscut pentru ferocitatea sa si pentru ca infesteaza vaile raurilor si granitele tinuturilor umane. Ataca frecvent asezarile, calatorii si terenurile agricole, in cautare de hrana si prada.",al={"ce sunt gnollii Riverpaw","povestea tribului Riverpaw"}},{q="Are aceasta misiune legatura cu alte amenintari din Elwynn?",a="Riverpaw Gnoll Bounty incheie scurta serie de alerte din Westbrook Garrison, desi Deputy Rainer si Westbrook Garrison supravegheaza si alte elemente fara de lege din zona, precum vestitul proscris Hogger.",al={"continuarea misiunii","ce urmeaza dupa recompensa Riverpaw"}},{q="Cine plateste recompensa pentru acesti gnoll-i?",a="Recompensa este autorizata oficial si sustinuta de Stormwind Army, care le da garnizoanelor locale dreptul sa-i rasplateasca si sa-i recompenseze pe cei care ajuta la pacificarea teritoriilor regale.",al={"cine finanteaza recompensa","sursa recompensei"}}},fx={["139c22ee"]={q="De ce vrea Deputy Rainer sa rareasca gnollii?",a="Deputy Rainer ii considera pe gnolii Riverpaw niste intrusi brutali, care nu au ce cauta la granitele Elwynn. Cu haite mari intarite la sud de turnul de paza si la est, langa Stone Cairn Lake, ei ameninta direct perimetrul Westbrook Garrison si colonistii din imprejurimi. Rainer vrea sa-i starpeasca pentru a opri infestarea care se extinde, inainte ca avanpostul sa fie coplesit cu totul.",al={"de ce sa rarefiem gnollii","motivul lui Deputy Rainer","de ce vrea Rainer morti Riverpaws"}}},fp="21,288,22.425.0,18.382.0,52.192.0,60.236.0,38.117.0,28.216.0,55.214.0,37.177.0"}
P.entries["quest:110"] = {n="Insect Part Analysis",s="Dupa disparitia lui Scrimshank, Senior Surveyor Fizzledowser incepe sa verifice echipamentul de masuratori si sa puna in ordine lucrurile personale ale lui Scrimshank. Iti cere sa-l cauti pe Alchemist Pestlezugg in Gadgetzan in legatura cu partile de insecte.",h="Dupa disparitia lui Scrimshank, Senior Surveyor Fizzledowser incepe sa verifice echipamentul de masuratori si...",kw={"fizzledowser","gadgetzan","insect part analysis","pestlezugg","scrimshank","tanaris"},sec={{t="O verificare la Gadgetzan",b="Fizzledowser intentioneaza sa petreaca ceva timp cu echipamentul de masuratori si efectele personale ale lui Scrimshank si are presimtirea ca insectele acestea vor provoca si mai multe pierderi. Ti se cere sa-l vizitezi pe Alchemist Pestlezugg in Gadgetzan si sa afli daca au fost prelucrate partile de insecte trimise de topografi. Daca sunt gata, Fizzledowser vrea sa le aduci inapoi."},{t="Ce a gasit Pestlezugg",b="Pestlezugg are rezultatele, iar acestea sunt tulburatoare. Prima banuiala, ca o forta din afara controleaza insectele, pare sa se fi adeverit. Asta inseamna ca exista o forta necunoscuta, foarte puternica si malefica. Insectele au fost transformate in pradatori puri, iar Pestlezugg n-a mai vazut niciodata ceva asemanator."}},faq={{q="Cine te trimite sa-l consulti pe Alchemist Pestlezugg?",a="Senior Surveyor Fizzledowser, care verifica echipamentul lui Scrimshank si ii pune lucrurile in ordine.",al={"cel care ofera misiunea","cine incepe Insect Part Analysis","locatia lui Fizzledowser"}},{q="Unde se afla Alchemist Pestlezugg?",a="In Gadgetzan, unde trebuie sa te prezinti pentru a discuta despre partile de insecte.",al={"unde este pestlezugg","locatia lui pestlezugg","orasul lui pestlezugg"}},{q="Ce a urmat imediat inaintea acestui pas?",a="Urmeaza dupa The Scrimshank Redemption.",al={"misiune prealabila","ce misiune trebuie facuta mai intai","pasul anterior"}},{q="Ce trebuie sa afli?",a="Daca Pestlezugg a terminat de cercetat partile de insecte trimise de topografi. Daca sunt gata, trebuie duse la Fizzledowser.",al={"ce are pestlezugg"}}},fp="20,225,23.354.0,21.311.1,46.111.0,38.63.0,36.37.0,30.141.0"}
P.entries["quest:1100"] = {n="Lonebrow's Journal",s="Lonebrow's Journal este o misiune Alliance declansata de gasirea unei carti uzate, tinute in mana unui pitic mort de la baza Great Lift din Thousand Needles. Insemnarile descriu ultima sa calatorie si ii cer celui care le gaseste sa duca volumul spre vest, la un druid elf al noptii stationat la granita cu Feralas.",h="Lonebrow's Journal este o misiune Alliance declansata de gasirea unei carti uzate, tinute in mana unui pitic...",kw={"Falfindel","Feralas","marele lift","henrig","jurnal","Lonebrow","Razorfen Kraul","Thalanaar","Thousand Needles","waywarder"},ang={["class:Druid"]="Falfindel Waywarder, din Thalanaar, supravegheaza schimbarile nefiresti din ecosistemul local, ceea ce face ca insemnarile lui Lonebrow despre quilboarii din Razorfen sa fie de mare interes pentru Cenarion Circle.",["faction:Alliance"]="Cu putine avanposturi intre Theramore si Thalanaar, recuperarea jurnalului lui Lonebrow asigura transmiterea unor informatii vitale catre aliatii Alliance inainte ca acestea sa se piarda in canion.",["race:Dwarf"]="Moartea lui Henrig Lonebrow aminteste cu tristete de pericolele cu care se confrunta exploratorii pitici departe de Ironforge, in colturile salbatice ale Kalimdor."},sec={{t="Un explorator cazut",b="Langa baza Great Lift, uriasul ascensor mecanic care leaga Barrens de fundul canionului din Thousand Needles, se afla trupul lui Henrig Lonebrow. In mana strange un jurnal personal, care ii descrie calatoriile prin acest tinut salbatic. Lasat in urma intr-un desert ostil, stapanit de centauri si tauren, cadavrul sau este un avertisment sumbru despre cat de neiertator poate fi canionul cu calatorii izolati."},{t="O rugaminte de pe patul de moarte",b="Jurnalul lui Henrig iti dezvaluie drumul pe care intentiona sa-l urmeze si ultima lui dorinta. In loc sa-si lase descoperirile sa se piarda in canion, exploratorul spera ca insemnarile lui vor ajunge pe maini prietene. Urmand drumul drept spre vest, peste Thousand Needles, iesi din ravenele uscate si ajungi spre Thalanaar, avanpostul elfilor noptii care pazeste granita cu Feralas, unde druidul Falfindel Waywarder asteapta vesti despre calator."},{t="Descoperirea Kraulului",b="Cand Falfindel Waywarder cerceteaza notitele lui Lonebrow, soarta exploratorului se impleteste cu o amenintare mai mare din sudul Kalimdorului. Observatiile lui Henrig indica vizuinile pline de maracini din Razorfen Kraul, la nord, dezvaluind ca o baba primejdioasa ii conduce pe quilboarii de acolo."}},faq={{q="Unde gasesc trupul lui Henrig Lonebrow?",a="Trupul lui zace la baza Great Lift din Thousand Needles. De la baza rampei ascensorului vestic, inainteaza cam douazeci si cinci de picioare spre o platforma joasa de stanca, unde cadavrul lui se afla cu jurnalul in mana.",al={"locatia lui Henrig Lonebrow","unde este jurnalul lui Lonebrow","trupul lui Lonebrow","gaseste-l pe Lonebrow"}},{q="Cui trebuie sa-i predau jurnalul?",a="Du jurnalul la Falfindel Waywarder, un druid night elf stationat la Thalanaar. Thalanaar se afla de-a lungul drumului principal spre vest, chiar la granita dintre Thousand Needles si Feralas.",al={"cine primeste jurnalul lui Lonebrow","unde predau obiectele lui Lonebrow","predarea obiectelor lui Lonebrow","locatia lui Falfindel"}},{q="Cine a fost Henrig Lonebrow?",a="Henrig Lonebrow era un calator pitic care strabatea centrul Kalimdorului. A pierit langa baza Great Lift, lasand in urma un jurnal uzat, in care isi descria observatiile despre tinuturile din jur si deplasarile primejdioase ale quilboarilor.",al={"cine este Henrig Lonebrow","povestea lui Lonebrow","cine este Lonebrow"}},{q="La ce duce aceasta misiune?",a="Predarea jurnalului catre Falfindel Waywarder deblocheaza misiunea 'The Crone of the Kraul', care le cere aventurierilor Alliance sa patrunda in temnita Razorfen Kraul.",al={"continuarea lui Lonebrow","misiunea de dupa jurnalul lui Lonebrow","lantul de misiuni Lonebrow"}},{q="Pot jucatorii Horde sa ridice jurnalul?",a="Nu. Jurnalul si seria de misiuni care urmeaza sunt rezervate strict jucatorilor din Alliance si duc direct la avanpostul de granita al Alliance din Thalanaar.",al={"jurnalul lui Lonebrow este doar pentru Alianta","poate Hoarda sa faca misiunea jurnalului lui Lonebrow","Lonebrow pentru Hoarda"}},{q="De ce se indrepta Lonebrow spre Thalanaar?",a="Thalanaar este cel mai apropiat avanpost al Alliance din regiune, un adapost intre Thousand Needles si tinuturile salbatice din Feralas. Lonebrow intentiona sa le impartaseasca observatiile sale despre regiune elfilor noptii stationati acolo.",al={"de ce Thalanaar","de ce sa trimiti cartea unui druid","scopul lui Lonebrow"}}},fx={["0173d93a"]={q="De ce cere jurnalul sa fie dus la Thalanaar?",a="Henrig Lonebrow stia ca drumul sau avea sa se incheie tragic sub Great Lift. Ultima sa dorinta, consemnata in paginile roase ale jurnalului, era ca descoperirile lui sa ajunga la Falfindel Waywarder, la postul de granita din Thalanaar. Ducand jurnalul la destinatie, te asiguri ca informatiile sau descoperirile esentiale pentru care piticul si-a dat viata nu se pierd in nisipurile din Thousand Needles.",al={"de ce sa predai jurnalul","scopul jurnalului","motivul jurnalului lui henrig lonebrow"}}},fp="18,299,17.419.0,15.417.0,20.301.1,39.222.0,32.194.0,24.240.0,29.168.1,38.140.0,42.221.0"}
P.entries["quest:1101"] = {n="The Crone of the Kraul",s="Crone of the Kraul este o misiune a Alliance oferita de Falfindel Waywarder la Thalanaar, la granita dintre Feralas si Thousand Needles. Dupa ce citeste jurnalul recuperat al dwarf-ului cazut Henrig Lonebrow, Falfindel le cere aventurierilor sa se infiltreze in Razorfen Kraul si sa o ucida pe vrajitoarea quilboar, Charlga Razorflank.",h="Crone of the Kraul este o misiune a Alliance oferita de Falfindel Waywarder la Thalanaar, la granita dintre...",kw={"agamaggan","charlga razorflank","baba","falfindel waywarder","lonebrow","medalion","razorfen kraul","thalanaar"},ang={["class:Druid"]="Druizii il pretuiesc mult pe Agamaggan, considerandu-l un stravechi venerat al naturii, si cauta sa curete pata intunecata care-i deformeaza mostenirea acoperita de spini.",["faction:Alliance"]="Aceasta misiune reprezinta principala initiativa a Alliance-ului impotriva amenintarii quilboarilor din sudul Barrens, lansata de la avanpostul Thalanaar.",["race:Dwarf"]="Razbunarea exploratorului Henrig Lonebrow le ofera piticilor un motiv personal sa ia cu asalt fortareata quilboar.",["race:NightElf"]="Elfii noptii privesc cu mahnire profanarea locului de odihna al lui Agamaggan, recunoscand in mistretul stravechi un aliat cazut in War of the Ancients."},sec={{t="O cerere de ajutor la granita",b="La avanpostul night elf izolat din Thalanaar, Falfindel Waywarder ii jeleste pe druidul Heralath si pe Dwarf-ul Henrig Lonebrow. Lonebrow, un calator al Explorers' League capturat de quilboar, a evadat din Razorfen Kraul, dar a murit pe drum, lasand in urma un jurnal zdrentuit care descria amenintarea tot mai mare din Razorfen Kraul. Dandu-si seama ca nu mai este timp sa trimita un mesager la Darnassus pentru intariri militare, Falfindel apeleaza la aventurierii aflati in trecere pentru a lovi direct in inima vizuinilor pline de spini."},{t="Lovirea capeteniei",b="Tinta expeditiei este Charlga Razorflank, o geomanta straveche si matroana nemiloasa care a unit triburile razlete de quilboar Razorfen sub stapanirea ei de fier. Din adancurile Kraulului, ea mobilizeaza o armata fioroasa care ameninta tinuturile invecinate. Aventurierii trebuie sa-si croiasca drum prin labirinturi dese de spini, ziduri de aparare si roiuri de razboinici quilboar fanatici, ca sa o incercuiasca pe Charlga si sa-i ia medalionul de pe trupul neinsufletit, drept dovada a infrangerii sale."},{t="O corupere mai profunda",b="Desi moartea lui Charlga domoleste amenintarea imediata a quilboar, infrangerea ei starneste temeri mai adanci in randul elfilor noptii. Kraul-ul este alcatuit din maracinii vii care au rasarit acolo unde a cazut mistretul Ancient Agamaggan in timpul War of the Ancients. Dupa intoarcerea medalionului, Falfindel remarca faptul ca neutralizarea lui Charlga le permite invatatilor night elf sa studieze mai indeaproape coruptia zonei, desi simte ca o tradare perfida s-ar putea afla la originea molimei care cuprinde brusc ramasitele sacre ale lui Agamaggan."}},faq={{q="Cine ofera misiunea The Crone of the Kraul?",a="Misiunea este oferita de Falfindel Waywarder, un Night Elf stationat la Thalanaar. Thalanaar este un avanpost al Alliance aflat pe trecatoarea montana inalta dintre Feralas si Thousand Needles.",al={"cine ofera misiunea pentru crone of the kraul","unde gasesc misiunea crone of the kraul","misiunea lui falfindel waywarder"}},{q="Ce cerinta preliminara trebuie indeplinita inainte de a incepe aceasta misiune?",a="Mai intai trebuie sa termini misiunea Lonebrow's Journal. Aceasta presupune sa recuperezi jurnalul lui Henrig Lonebrow de la ramasitele sale cazute, langa Great Lift din Thousand Needles, si sa-l duci la Falfindel, in Thalanaar.",al={"cerinta pentru crone of the kraul","cum deblochezi crone of the kraul","cerinta prealabila pentru jurnalul lui lonebrow"}},{q="Cine este Charlga Razorflank?",a="Charlga Razorflank este hagul suprem si matriarha quilboarilor din Razorfen. Este o geomantita puternica, ce a unit triburile aflate in razboi din Razorfen Kraul, indreptandu-le agresivitatea impotriva teritoriilor invecinate.",al={"cine este baba","povestea lui charlga","charlga razorflank"}},{q="Unde poate fi gasita Charlga Razorflank?",a="Ea se afla chiar in capatul indepartat al Razorfen Kraul, in coltul din sudul indepartat al Barrens, langa Great Lift. Te asteapta pe un altar, in adancul temnitei.",al={"unde este Charlga","locatia lui Charlga","unde este batrana din RFK"}},{q="De ce are Falfindel nevoie de aventurieri in loc sa cheme armata din Darnassus?",a="Thalanaar este un avanpost indepartat de la frontiera, departe de nordul Kalimdorului. Intrucat Charlga isi aduna activ fortele, ar dura prea mult sa trimita vesti la Darnassus si sa astepte sosirea unei armate, iar pericolul in crestere nu poate astepta.",al={"de ce sa nu-i cheme pe cei din darnassus","de ce sa angajeze aventurieri"}},{q="Ce dovada a mortii vrajitoarei cere Falfindel?",a="Falfindel are nevoie de Razorflank's Medallion, amuleta purtata chiar de Charlga, care dovedeste fara putinta de tagada ca batrana a fost ucisa.",al={"ce obiect dropeaza","obiectul dovada disparitiei","medalionul Razorflank"}}},fx={["8858b532"]={q="De ce vrea Falfindel Waywarder sa fie ucisa Charlga Razorflank?",a="Falfindel Waywarder refuza sa lase ca sacrificiile lui Heralath si Henrig Lonebrow sa fi fost in zadar. Charlga Razorflank strange in mod activ o forta periculoasa in adancurile Razorfen Kraul, amenintand toate tinuturile din jur. Eliminarea ei opreste aceasta amenintare tot mai mare din partea quilboarilor si le permite elfilor noptii de la Thalanaar sa studieze in siguranta cum au fost corupte locurile sacre de odihna ale stravechiului Agamaggan.",al={"de ce sa o ucizi pe Charlga Razorflank","motivul lui Falfindel","de ce Crone of the Kraul"}}},fp="22,325,20.507.0,22.456.0,19.508.1,43.187.0,63.223.0,26.224.0,38.167.0,74.217.0,54.144.0"}
P.entries["quest:1103"] = {n="Chemarea apei"}
P.entries["quest:1104"] = {n="Salt Flat Venom",s="Pe intinderea de sare orbitoare din Shimmering Flats, inginerul gnom Fizzle Brassbolts cauta ingrediente neobisnuite pentru a-si supraincarca automobilul cu rachete. Convins ca veninul extrem de sarat al scorpidilor locali va da nastere unui combustibil de propulsie cu ardere ultra-fierbinte, el le cere aventurierilor aflati in trecere sa infrunte bestiile intepatoare.",h="Pe intinderea de sare orbitoare din Shimmering Flats, inginerul gnom Fizzle Brassbolts cauta ingrediente...",kw={"fizzle brassbolts","combustibil","mirage raceway","masina-racheta","salty scorpid venom","shimmering flats","thousand needles"},ang={["profession:Engineering"]="Folosirea toxinelor organice tratate cu catalizatori precum skipper-otomers scoate in evidenta experimentele creative si volatile, frecvente in ingineria vehiculelor de competitie.",["race:Gnome"]="Fizzle intruchipeaza ambitia clasica a gnomilor: experimente fara incetare, masuri de siguranta chimica indoielnice, notite ratacite si dorinta permanenta de a-i intrece pe mecanicii goblini."},sec={{t="O reteta instabila",b="Mirage Raceway este un duel nesfarsit pentru suprematia tehnica in viteza, intre precizia gnomilor si indrazneala goblinilor. Pentru Fizzle Brassbolts, hidrocarburile obisnuite si piesele de mecanism nu sunt de ajuns ca sa intreaca rivalii. El isi imagineaza un amestec special de combustibil, conceput sa arda mult mai fierbinte decat carburantii obisnuiti, propulsandu-le masinile-racheta peste lacul sarat secat, cu viteze ametitoare."},{t="Venin salin din Salt Flats",b="Marea descoperire a lui Fizzle se bazeaza pe fauna primejdioasa din Shimmering Flats. Scorpidii locali au evoluat pentru a supravietui intr-un tinut arid, acoperit cu sare, ceea ce le-a dat un venin neobisnuit de sarat. In loc sa se teama de toxicitatea lui mortala, Fizzle il priveste ca pe o incarcatura chimica bruta. Odata fiert, rafinat si tratat cu agenti catalitici exotici, veninul sarat ar urma, crede el, sa produca arderea exploziva necesara pentru a-i lasa in urma pe echipele de excavatori goblini."}},faq={{q="De ce vrea Fizzle Brassbolts venin de scorpid?",a="Fizzle inventeaza un combustibil pentru o noua masina cu racheta, care arde la temperaturi extrem de inalte. El crede ca salinitatea neobisnuit de mare a veninului scorpizilor din Shimmering Flats este componenta chimica esentiala pentru desavarsirea amestecului sau exploziv.",al={"de ce venin de scorpid","la ce foloseste veninul","reteta combustibilului Fizzle"}},{q="Unde pot fi gasiti scorpizii necesari?",a="Scorpizii ratacesc prin toate intinderile deschise din Shimmering Flats, mai ales in campiile din vest si prin nisipurile desertului, departe de pista centrala.",al={"locatia scorpids","unde sunt scorpids","creaturi salt flat venom"}},{q="Ce va face Fizzle cu veninul dupa ce il colecteaza?",a="Fizzle intentioneaza sa concentreze veninul prin fierbere, sa-l trateze cu un skipper-otomer si sa-l amestece cu un nega-catalizator pentru a obtine combustibilul sau de racheta de mare performanta - presupunand ca isi poate aminti unde si-a ratacit notitele.",al={"cum se transforma otrava in combustibil","procesul de fabricare a combustibilului"}},{q="Pot membrii Alliance si Horde sa-l ajute pe Fizzle?",a="Da. Mirage Raceway este administrat in baza unui armistitiu neutru intre gnomi si goblini, astfel incat aventurierii din ambele factiuni pot ajuta echipele din boxe fara amestec politic.",al={"aceasta misiune este neutra","horde sau alliance"}},{q="De ce se intrec gnomii si goblinii in Thousand Needles?",a="Shimmering Flats ofera o suprafata vasta, perfect plata si lipsita de obstacole, acoperita cu sare bine tasata, ceea ce o transforma in terenul ideal de incercare pentru masinile experimentale cu racheta, de mare viteza, si pentru masinile de curse.",al={"de ce e aici pista","de ce Mirage Raceway"}},{q="Face combustibilul masina sa zboare cu adevarat?",a="Desi Fizzle sustine cu entuziasm ca masina va 'zbura', vehiculele cu racheta ale gnomilor de pe saline sunt concepute sa alunece pe sol cu viteze ametitoare, chiar daca decolarile catastrofale si prabusirile nu sunt niciodata excluse.",al={"zboara masina","rezultatul masinii-racheta a lui fizzle"}}},fp="15,323,17.404.0,30.473.0,46.240.0,42.163.0,50.202.0,55.183.0,54.185.0,40.223.0"}
P.entries["quest:1105"] = {n="Hardened Shells",s="La Mirage Raceway, in Shimmering Flats, inventatorul gnom Wizzle Brassbolts se teme ca noul combustibil puternic pentru rachete al fratelui sau le va dizolva masina de curse din interior. Pentru a preveni o catastrofa pe intinderea sarata, Wizzle le cere trecatorilor sa adune carapace intarite de la testoasele din zona, ca sa confectioneze un rezervor de combustibil impenetrabil.",h="La Mirage Raceway, in Shimmering Flats, inventatorul gnom Wizzle Brassbolts se teme ca noul combustibil...",kw={"carapace intarite","mirage raceway","masina-racheta","shimmering flats","thousand needles","broasca testoasa","wizzle brassbolts"},ang={["profession:Engineering"]="Folosirea unor placi organice de armura pentru a adaposti compusi volatili este o practica neconventionala, care scoate in evidenta abordarea excentrica, bazata pe incercari si erori, la care recurg mestesugarii gnomi sub presiune.",["race:Gnome"]="Ingeniozitatea frateasca si ambitia stiintifica nesabuita se ciocnesc aici, intruchipand impulsul gnomilor de a-si depasi rivalii goblini in orice privinta, indiferent de obstacolele logistice."},sec={{t="Inovatii instabile",b="In arsita orbitoare din Shimmering Flats, rivalitatea dintre inginerii gnomi si goblini impinge ambitiile mecanice spre extreme nesabuite. Wizzle Brassbolts si fratele sau sunt hotarati sa domine Mirage Raceway cu masina lor personalizata cu rachete. Insa amestecul experimental de combustibil al fratelui sau pare mult prea puternic. Temandu-se ca substanta coroziva va topi sasiul si rezervoarele standard ale vehiculului, Wizzle se grabeste sa gaseasca un recipient suficient de rezistent pentru a supravietui cursei."},{t="Solutii blindate pentru desert",b="In loc sa se bazeze pe metale rafinate, care s-ar putea dizolva sub presiunea substantelor chimice, Wizzle recurge la adaptarile naturale ale salinelor. Testoasele native care cutreiera Thousand Needles au carapace remarcabil de rezistente la stihii necrutatoare si la uzura mecanica. Strangand aceste carapace intarite, Wizzle spera sa faureasca rezervoare de combustibil speciale, suficient de rezistente pentru a pastra amestecul volatil fara sa arunce in aer masina-racheta."}},faq={{q="De ce are Wizzle nevoie de carapace de testoasa in loc de metal?",a="Fratele lui prepara un combustibil experimental pentru rachete, suficient de coroziv incat sa dizolve metalul. Wizzle crede ca invelisurile naturale, ultra-rezistente, ale testoaselor din zona vor rezista mai bine la actiunea substantei decat rezervoarele obisnuite.",al={"de ce carapace de testoasa","de ce carapace de broasca testoasa","carapace pentru rezervorul de combustibil"}},{q="Cine este Wizzle Brassbolts?",a="Wizzle este un inginer gnom aflat la Mirage Raceway, in Shimmering Flats. Lucreaza alaturi de fratele sau la construirea si reglarea masinii lor cu racheta de mare viteza, ca sa-si intreaca rivalii goblini.",al={"wizzle","cine este wizzle"}},{q="Unde pot fi gasite testoasele?",a="Testoasele umbla nestingherite de-a lungul vastei saline din Shimmering Flats, adunandu-se in numar deosebit de mare la soare, langa vechea epava din partea de nord-est.",al={"locatia testoaselor","unde se afla testoasele","unde gasesc carapace intarite"}},{q="Este o misiune Alliance sau Horde?",a="Este complet neutru. Mirage Raceway functioneaza in afara razboiului dintre factiuni si se concentreaza pe competitii de inginerie, astfel ca aventurierii Alliance si Horde il pot ajuta pe Wizzle.",al={"Hardened Shells este neutra","Alianta sau Hoarda"}},{q="Ce se intampla dupa ce sunt livrate scoicile?",a="Wizzle incepe cu entuziasm sa le transforme in rezervoare de combustibil ranforsate, dar isi da repede seama ca invelisurile sunt atat de rezistente, incat probabil va distruge o intreaga trusa de scule incercand sa le dea forma.",al={"rezultatul cochiliilor lui Wizzle","ce face Wizzle cu cochiliile"}},{q="De ce este defectarea rezervorului de combustibil o problema atat de mare in campie?",a="Masinile-racheta strabat sarea cu viteze inspaimantatoare. Wizzle se teme ca noul combustibil al fratelui sau este atat de puternic, incat va roade sasiul masinii, asa ca vrea sa consolideze rezervoarele inainte sa se intample asta.",al={"pericolul masinii-racheta","de ce exista ingrijorari legate de combustibil"}}},fx={["201b3417"]={q="De ce vrea Wizzle Brassbolts sa se faca acest lucru?",a="Fratele lui Wizzle proiecteaza un nou combustibil extrem de instabil pentru masina lor cu racheta de pe Mirage Raceway. Desi Wizzle admira geniul fratelui sau, este ingrozit la gandul ca amestecul este atat de coroziv, incat ar putea topi pe loc sasiul existent al masinii in timpul testelor. Pentru a preveni un dezastru catastrofal pe intinderile sarate, Wizzle trebuie sa confectioneze rezervoare de combustibil de schimb, mai rezistente, inainte ca fratele sau sa termine amestecul.",al={"motivul lui Wizzle","de ce sa-l ajuti pe Wizzle","de ce vrea Wizzle scoici"}},["5a3ddfa8"]={q="Ce sunt testoasele din Shimmering Flats?",a="Testoasele sparkleshell ratacesc prin intinderile dogorite de soare din Shimmering Flats. De-a lungul generatiilor petrecute in bazinul arid si aspru, carapacele lor s-au intarit pana au devenit remarcabil de rezistente. In general, isi vad de treaba printre crustele de sare, devenind o materie prima naturala si trainica, ideala pentru mestesugarii gnomi care au mare nevoie de placi nereactive si rezistente la caldura.",al={"broaste testoase de pe campiile sarate","testoasele din Shimmering Flats","de ce sunt testoase aici"}}},fp="15,330,20.523.0,24.429.0,54.225.0,25.202.0,33.172.0,35.179.0,43.182.1,53.208.0"}
P.entries["quest:1106"] = {n="Martek the Exiled",s="Fizzle Brassbolts construieste un motor nou pentru masina sa, dar nu poate face pistoane suficient de rezistente pentru a suporta solicitarea. Te trimite cu o scrisoare la un mare fierar pe nume Martek the Exiled, departe, intr-o tabara din Badlands.",h="Fizzle Brassbolts construieste un motor nou pentru masina sa, dar nu poate face pistoane suficient de...",kw={"badlands","fizzle brassbolts","gath'ilzogg","martek the exiled","mirage raceway","pistoane","thousand needles"},sec={{t="O scrisoare pentru fierar",b="Dupa Salt Flat Venom, Fizzle de la Mirage Raceway explica faptul ca noul sau motor ar trebui sa faca masina atat de rapida, incat sa poata zbura. Toate incercarile lui au esuat fiindca nu reuseste sa faca pistoane suficient de rezistente pentru solicitarea intensa. Cunoaste o persoana care s-ar putea pricepe: Martek the Exiled, un fierar grozav care stie mai multe despre metal decat oricine. Martek se afla departe, in Badlands, unde campeaza alaturi de un goblin, iar tu duci scrisoarea lui Fizzle la el."},{t="La tabara",b="Martek nu este prietenos cand gasesti tabara. Martek te intreaba daca ai venit pentru un topor facut pentru Gath'Ilzogg sau ca sa revendici onoarea ducesei Pamay si spune ca, daca vrei o lupta, la fel de bine poate incepe chiar acum."},{t="Raspunsul lui Martek",b="A afla ca Fizzle te-a trimis schimba totul. Martek spune ca Fizzle si fratele lui sunt printre putinii care nu-l vor mort si accepta sa-l ajute cu pistoane suficient de rezistente pentru orice solicitare a planului lui Fizzle, fiindca noua masina i se pare lui Martek un vulcan pe roti."}},faq={{q="De ce are Fizzle Brassbolts nevoie de ajutorul lui Martek?",a="Noul motor al lui Fizzle ar trebui sa faca masina suficient de rapida pentru a zbura, dar toate incercarile au esuat, fiindca nu poate face pistoane destul de rezistente pentru solicitari. Martek este un fierar iscusit, care stie mai multe despre metal decat oricine.",al={"de ce sa-l vizitezi pe martek","problema pistonului lui fizzle brassbolts","de ce martek exilatul"}},{q="Unde se afla Martek the Exiled?",a="In Badlands, intr-o tabara unde sta si un goblin.",al={"unde se afla martek","martek locatia exilatului","cum il gasesc pe martek"}},{q="Ce a precedat aceasta calatorie?",a="Salt Flat Venom vine inaintea acesteia in lantul de misiuni. Indurium ii urmeaza.",al={"cerinte preliminare pentru Martek the Exiled","ce misiune preceda Martek the Exiled"}}},fp="17,218,22.435.0,11.220.1,14.277.1,46.209.0,35.58.0,30.73.0"}
P.entries["quest:1107"] = {n="Encrusted Tail Fins",s="Wizzle Brassbolts de la Mirage Raceway se teme ca masina-racheta este atat de rapida, incat frecarea o va dezmembra. Pentru a o proteja, are nevoie de aripioare de coada de la murlocii Saltscale din Vile Reef, in largul coastei Stranglethorn Vale.",h="Wizzle Brassbolts de la Mirage Raceway se teme ca masina-racheta este atat de rapida, incat frecarea o va...",kw={"inotatoare incrustate cu depuneri","mirage raceway","masina-racheta","murloci saltscale","shimmering flats","stranglethorn vale","vile reef","wizzle brassbolts"},sec={{t="Un strat protector pentru masina",b="Wizzle spune ca masina-racheta este cel mai rapid lucru din Shimmering Flats si se teme ca frecarea o va face bucati. Partile mobile au nevoie de un strat dintr-un material compozit, dur, dar nu casant, care sa reziste coroziunii provocate de sare, altfel campia va roade masina pana o distruge. Ingredientul-cheie sunt inotatoarele codale ale murlocilor Saltscale, care traiesc la Vile Reef, in largul coastei din Stranglethorn Vale. Ti se cere sa-i aduci lui Wizzle zece."},{t="Compozitul finalizat",b="Wizzle iti va macina aripioarele pana le va face pulbere si le va amesteca cu alte cateva ingrediente; compozitul obtinut ar trebui sa protejeze masina de propria-i viteza. Wizzle adauga ca va functiona doar atata timp cat masina nu se izbeste de nimic."}},faq={{q="De ce are nevoie Wizzle Brassbolts de inotatoare de coada incrustate?",a="Masina cu racheta este atat de rapida, incat Wizzle se teme ca frecarea o va dezmembra. Aripioarele sunt un ingredient esential al unui material compozit cu care vor fi acoperite piesele mobile; acesta trebuie sa fie dur, dar sa nu fie casant si sa reziste la coroziunea provocata de sare.",al={"de ce aripioare de coada","la ce folosesc aripioarele lui Wizzle","de ce aripioare de murloc"}},{q="Unde pot fi gasiti murlocii Saltscale?",a="La Vile Reef, in largul coastei din Stranglethorn Vale, aproape exact la vest de Grom'gol Base Camp.",al={"locatia Vile Reef","unde sunt murlocii Saltscale","unde gasesc inotatoarele incrustate"}},{q="Ce a facut Wizzle inainte de asta?",a="Hardened Shells precede aceasta misiune in lant.",al={"ce misiune vine prima","misiunea precedenta din lantul lui Wizzle","conditie prealabila pentru Encrusted Tail Fins"}},{q="Cine este Wizzle Brassbolts?",a="Wizzle Brassbolts se afla la Mirage Raceway, ingrijorat pentru masina-racheta, si este cel care iti cere aripioarele.",al={"cine este wizzle","cine da inotatoarele de coada incrustate"}}},fp="19,221,21.428.0,22.227.1,52.206.0,41.99.0,33.45.0,25.113.0"}
P.entries["quest:1108"] = {n="Indurium",s="Martek the Exiled spune ca Badlands sunt pline de metale pentru oricine are curajul sa le ia. Se spune ca Indurium rezista la caldura si presiune, iar Martek vrea mostre ca sa afle daca poate fi folosit pentru masina de curse a lui Fizzle. Troggii Stonevault din Badlands au in posesie astfel de aschii.",h="Martek the Exiled spune ca Badlands sunt pline de metale pentru oricine are curajul sa le ia.",kw={"agmond's end","badlands","fizzle brassbolts","indurium","fragmente de indurium","martek the exiled","mirage raceway","troggii stonevault","uldaman"},sec={{t="Un metal care merita testat",b="Martek the Exiled iti spune ca nu se afla in Badlands doar ca sa evite compania altora. Regiunea contine indurium, un metal despre care se spune ca rezista la caldura si presiune, si care s-ar putea potrivi pentru masina lui Fizzle. Martek vrea mostre pentru teste, iar forja este incinsa si pregatita."},{t="Aschii de la Troggs",b="Minereul adevarat se gaseste in adancurile Uldaman, dar troggii Stonevault din Badlands poarta uneori fulgi din el. Martek cere zece. Troggii care ii au cutreiera versantul sud-estic al unei coline stancoase din Agmond's End, chiar la sud de Valley of Fangs."},{t="Proba forjei",b="Martek duce aschiile la forja si ridica treptat temperatura. Rezista, iar Martek jura pe Orgrim ca induriumul acesta poate suporta o caldura uriasa. Proba este un succes, iar Martek numeste metalul o minune."}},faq={{q="Cine te trimite dupa indurium?",a="Martek the Exiled, aflat in centrul regiunii Badlands, iti cere mostrele. Lantul de misiuni care duce la el incepe cu Fizzle Brassbolts la Mirage Raceway, in Thousand Needles.",al={"cine ofera misiunea indurium","unde se obtine indurium"}},{q="De ce are Martek nevoie de indurium?",a="Martek crede ca acest metal, despre care se spune ca rezista la caldura si presiune, ar putea fi potrivit pentru masina lui Fizzle si vrea mostre pe care sa le testeze in forja.",al={"la ce se foloseste indurium","de ce indurium"}},{q="Unde pot fi gasite aschiile de indurium?",a="Stonevault troggs poarta aceste lucruri din cand in cand, pe panta sud-estica a unei movile stancoase de la Agmond's End, chiar la sud de Valley of Fangs.",al={"unde se gasesc indurium flakes","cum obtii flakes","cine lasa indurium flakes"}},{q="De unde provine minereul de indurium autentic?",a="Martek spune ca minereul adevarat se afla adanc in Uldaman.",al={"unde se afla minereul de indurium","unde se extrage indurium"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Martek the Exiled, primul pas al acestui sir de misiuni, care incepe cu Fizzle Brassbolts la Mirage Raceway.",al={"misiunea anterioara pentru indurium","cum incepe misiunea indurium"}},{q="Ce urmeaza dupa ce sunt livrate fulgii?",a="Lantul continua cu News for Fizzle.",al={"misiunea urmatoare dupa indurium","ce se intampla apoi"}}},fp="8,292,21.251.0,22.245.0,14.220.1,33.170.0,30.135.0,39.151.0,39.44.0,23.118.0,42.41.0"}
P.entries["quest:111"] = {n="Speak with Gramma",s="Tommy Joe Stonefield cauta ajutorul lui Gramma Stonefield pentru a o intalni pe Maybell Maclure. Dusmania amara dintre familiile lor ii tine despartiti pe tinerii indragostiti, iar Tommy Joe spera ca bunica lui va gasi o cale sa se vada.",h="Tommy Joe Stonefield cauta ajutorul lui Gramma Stonefield pentru a o intalni pe Maybell Maclure.",kw={"Elwynn Forest","Gramma Stonefield","podgoriile Maclure","Maybell Maclure","Speak with Gramma","ferma Stonefield","Tommy Joe Stonefield","indragostiti tineri"},ang={["faction:Alliance"]="In timp ce Stormwind se confrunta cu tulburarile provocate de Defias si cu atacurile fiarelor, s-ar putea sa ajungi sa aplanezi certuri intre fermieri vecini.",["race:Human"]="Ca Human in Elwynn, vezi cat de adanc inradacinate sunt vechile dusmanii in tinuturile centrale ale Stormwind, chiar si in mijlocul tulburarilor mai ample din regat."},sec={{t="O dusmanie si o iubire interzisa",b="Tommy Joe Stonefield si Maybell Maclure isi tin povestea de dragoste secreta fata de familiile lor aflate in vrajba. Stonefields si Maclures se lupta de ani intregi pentru fermele lor, transformandu-si gospodariile invecinate in teritorii ostile. Tommy Joe vrea sa se intalneasca cu Maybell fara sa starneasca violenta intre rudele lor, asa ca apeleaza la bunica lui."},{t="Viclenia lui Gramma",b="Gramma Stonefield sta in casa, dar cunoaste bine dusmania. Intelege ca familiile nu se pot impaca cu adevarat cat timp resentimentele persista. Totusi, nu va lasa ca ranchiuna lor sa zdrobeasca iubirea tinerilor. In loc sa-i indemne la prudenta, Gramma incepe sa caute prilejuri marunte de a-i aduce impreuna pe Tommy Joe si Maybell."}},faq={{q="De ce vrea Tommy Joe sa vorbesc cu bunica lui?",a="Tommy Joe o iubeste pe Maybell Maclure, dar vrajba dintre familiile lor ii impiedica sa se intalneasca. Speranta lui este ca bunica sa il poate ajuta sa puna la cale intalniri secrete fara sa starneasca zarva.",al={"de ce Gramma","Gramma a lui Tommy Joe","scopul misiunii Speak with Gramma"}},{q="Unde poate fi gasita Gramma Stonefield?",a="Gramma Stonefield sta in casa principala a fermei Stonefield, la sud de Goldshire si la est de malul raului unde se ascunde Tommy Joe.",al={"locatia lui Gramma Stonefield","unde se afla bunica","gaseste-o pe Gramma Stonefield"}},{q="Care este disputa dintre Stonefields si Maclures?",a="Familiile de fermieri vecine au o veche ranchiuna personala si teritoriala. Se acuza reciproc de furt si isi disputa recoltele, in timp ce neincrederea le tine pe amandoua la un pas de violenta. Copiii lor trebuie sa-si pastreze orice legatura in secret.",al={"cearta dintre stonefield si maclure","de ce se lupta","cearta dintre familii din elwynn"}},{q="Dezaproba Gramma Stonefield relatia lui Tommy Joe?",a="Nu. Gramma stie ca vrajba le face dificil un viitor impreuna, dar tine la tinerii indragostiti si e dispusa sa gaseasca modalitati prin care sa se intalneasca.",al={"este bunica impotriva lui maybell","bunica sustine indragostitii"}},{q="Ce se intampla dupa ce vorbesti cu Gramma?",a="Gramma incepe sa puna la cale un plan pentru a-i aduce pe Tommy Joe si Maybell impreuna in taina. Te trimite sa strangi cele necesare pentru un lichior al invizibilitatii, care sa-i ajute sa treaca neobservati pe langa familiile vigilente.",al={"ce urmeaza, Speak with Gramma","continuarea misiunii gramma"}},{q="Cine este Maybell Maclure?",a="Maybell Maclure este fiica familiei rivale si locuieste peste drum de Stonefields. Se intalneste pe ascuns cu Tommy Joe Stonefield.",al={"cine este maybell","maybell maclure"}}},fx={ba5df8a9={q="De ce are nevoie Tommy Joe de un strain care sa vorbeasca cu bunica lui?",a="Tommy Joe se ascunde pe malul raului, langa Stonefield Farm, pentru a se intalni pe ascuns cu Maybell Maclure. Daca s-ar intoarce el insusi la casa familiei, ar risca sa atraga atentia asupra iubirii lor interzise, mai ales acum, cand tensiunile dintre cele doua familii aflate in vrajba sunt mari. In calitate de calator aflat in trecere, te poti apropia in liniste de Gramma Stonefield fara sa alertezi restul gospodariei.",al={"de ce eu, Tommy Joe","de ce sa trimiti jucatorul la bunica","de ce nu poate Tommy sa vorbeasca cu bunica"}}},fp="17,213,25.335.0,16.307.0,52.168.0,37.129.0,58.230.0,55.142.0,38.181.1,23.144.0"}
P.entries["quest:1110"] = {n="Rocket Car Parts",s="Rocket Car Parts este o comanda primita de la negustorul pitic oportunist Kravel Koalbeard, in salinarul orbitor din Shimmering Flats. In loc sa lase sa se piarda resturile imprastiate violent in urma accidentelor pilotilor de curse de mare viteza, Koalbeard ii plateste pe calatori sa scotoceasca prin desert si sa recupereze mecanismele distruse, pe care sa le revanda direct echipelor rivale de gnomi si goblini.",h="Rocket Car Parts este o comanda primita de la negustorul pitic oportunist Kravel Koalbeard, in salinarul...",kw={"accidente","Gnome","Goblin","Kravel Koalbeard","Mirage Raceway","piese pentru masina-racheta","recuperare","fier vechi","Shimmering Flats","Thousand Needles"},ang={["profession:Engineering"]="Cercetarea campurilor sarate dezvaluie inventivitatea nesabuita a proiectelor goblinilor si gnomilor rivali, ale caror propulsoare instabile de racheta si sasiuri improvizate se termina adesea prin cedari structurale spectaculoase.",["race:Dwarf"]="In timp ce multi pitici din Ironforge privesc circuitul de curse ca pe o sursa de inovatie mecanica sau de excavare, Kravel Koalbeard intruchipeaza o atitudine pur mercenara, interesandu-se strict de monedele aduse de operatiunile de recuperare.",["race:Gnome"]="Recuperarea acestor piese scoate in evidenta elanul neobosit, chiar daca uneori dezastruos, al inginerilor gnome care incearca sa-i intreaca si sa-i depaseasca prin inovatie pe concurentii lor goblini, pe pista deschisa."},sec={{t="Epave pe campurile de sare",b="Shimmering Flats este terenul de incercare pentru apriga rivalitate tehnologica dintre inginerii Goblin si cei gnomici. Masinile experimentale de curse cu rachete de mare viteza se defecteaza adesea catastrofal, lasand in urma, pe suprafata intinsa a desertului alb, roti dintate rasucite, cilindri si foi zimtate de metal. In timp ce echipele de asistenta se concentreaza doar asupra construirii si reglarii urmatoarei masini, podeaua desertului a devenit pe nesimtite un depozit de fier vechi provenit din ingineria experimentala."},{t="Intreprinderea de recuperare a lui Koalbeard",b="In loc sa concureze direct pe pista, antreprenorul Dwarf Kravel Koalbeard a recunoscut la Mirage Raceway o oportunitate profitabila de intermediere. Mecanicii Gnome si Goblin consuma piese intr-un ritm nebunesc si cauta mereu mecanisme de schimb pe care sa le monteze pe vehicule. Koalbeard ii angajeaza pe calatori sa adune treizeci de legaturi de resturi sfaramate, transformand accidentele devastatoare in marfa proaspata si profitand frumos de pe urma necazurilor pilotilor."}},faq={{q="Cine este Kravel Koalbeard?",a="Kravel Koalbeard este un negustor pitic iscusit, stationat la Mirage Raceway, in Shimmering Flats. Pune la cale diverse afaceri in jurul pistei, axate in principal pe cautarea de fier vechi, treburi marunte si transformarea rivalitatii dintre gnomi si goblini intr-un profit personal.",al={"Kravel Koalbeard","cine ofera piese pentru masina-racheta","pitic de la circuit"}},{q="De ce sunt atat de multe piese de masina-racheta imprastiate pe jos?",a="Mirage Raceway este o pista operationala pentru teste si curse, unde ingineri goblini si gnomi imping vehicule experimentale cu rachete pana la limite periculoase. Accidentele violente si exploziile neasteptate au loc frecvent pe intinderile sarate, imprastiind in toate directiile fragmente de structura, roti dintate si cilindri.",al={"de ce sunt piese de masina in desert","resturi din Shimmering Flats","masini-racheta distruse"}},{q="Ce face Kravel cu piesele recuperate din epava?",a="Koalbeard curata resturile adunate si le vinde inapoi echipelor gnomilor si goblinilor. Echipele consuma materiale intruna si sunt dornice sa cumpere orice dispozitive si resturi de metal pe care le pot atasa la urmatoarele prototipuri.",al={"ce vrea Kravel cu piesele","de ce sa aduni piese de masina"}},{q="Unde se afla aceste piese?",a="Piesele sunt imprastiate pe intregul desert deschis din Shimmering Flats, in jurul taberei centrale de curse. Se vad sub forma unor mormane de fier vechi, roti dintate rasucite, cilindri si placi metalice turtite.",al={"unde gasesc piese pentru masina cu rachete","locatiile pieselor","piese auto in Shimmering Flats"}},{q="Are aceasta misiune legata de alte sarcini din jurul pistei de curse?",a="Da. Cautarea prin campii se imbina firesc cu vanarea faunei locale pentru alti clienti ai pistei de curse, de pilda adunarea veninului din acele scorpionilor, recoltarea carapacelor de broasca testoasa si imputinarea numarului vulturilor si basiliscilor din tinut, in timp ce strabati intinsele saline.",al={"misiuni de pe circuit","misiuni de vanatoare in Shimmering Flats","misiuni legate de piesele masinii-racheta"}},{q="Ce se intampla cu soferii implicati in aceste accidente?",a="Cursele de masini-racheta sunt renumite pentru numarul mare de victime. In timp ce sorteaza fierul vechi recuperat, Koalbeard observa nepasator o ureche taiata, strivita intre placi de metal, subliniind cruda realitate: multi piloti nu supravietuiesc testelor de viteza.",al={"supravietuiesc pilotii accidentelor","ureche zdrobita","decesele pilotilor de pe circuit"}}},fx={["16d6be49"]={q="La ce folosesc piesele masinii-racheta?",a="Sunt resturi contorsionate - roti dintate, cilindri si fier vechi aruncate de coliziunile la viteza mare de pe intinderile sarate. In loc sa le lase sa rugineasca in saramura, Kravel Koalbeard le aduna pentru a le revinde echipajelor de pit crew gnomice si gobline, care se zbat sa-si revina. Dornice sa-si reconstruiasca masinile de curse sfaramate si sa-si intreaca rivalii in inventii, ambele tabere cumpara cu placere metalul recuperat, ca sa-l sudeze pe urmatoarea lor masinarie nesabuita.",al={"la ce folosesc piesele masinii-racheta","pentru ce sunt piesele masinii-racheta","de ce se aduna piese pentru masina-racheta"}}},fp="16,378,24.464.0,30.467.0,24.272.0,63.294.0,43.255.0,30.225.0,56.256.0,53.243.0"}
P.entries["quest:1111"] = {n="Wharfmaster Dizzywig",s="Kravel Koalbeard, un dwarf de la Mirage Raceway, se ocupa sa le faca rost oamenilor de ce au nevoie. Gnomii de acolo asteapta piese care au ajuns la Ratchet acum o saptamana, iar Kravel nu poate merge personal. Te trimite la Ratchet cu comanda lui de piese pentru Wharfmaster Dizzywig.",h="Kravel Koalbeard, un dwarf de la Mirage Raceway, se ocupa sa le faca rost oamenilor de ce au nevoie.",kw={"kravel koalbeard","mirage raceway","comanda de piese","ratchet","thousand needles","wharfmaster dizzywig"},sec={{t="Munca de teren pentru Kravel",b="Kravel Koalbeard se asigura ca oamenii primesc lucrurile de care au nevoie. Gnomii de la Mirage Raceway asteapta un transport de piese care a ajuns la Ratchet acum o saptamana, iar Kravel nu poate face singur drumul. Iti cere sa te ocupi de treaba si promite mai multe slujbe cu un potential serios de castig, daca o faci."},{t="Docurile din Ratchet",b="Ratchet se afla in Barrens. Trebuie sa-l cauti pe Wharfmaster Dizzywig, un goblin, iar Kravel spune ca Dizzywig va fi probabil la docuri. Ii duci acolo comanda de piese a lui Kravel."}},faq={{q="Cine te trimite la Wharfmaster Dizzywig?",a="Kravel Koalbeard, un Dwarf de la Mirage Raceway din Thousand Needles, iti da comanda de piese si te trimite la Ratchet.",al={"cine ofera Wharfmaster Dizzywig","misiunea lui Kravel Koalbeard"}},{q="Unde poate fi gasit Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig este un goblin, iar Kravel se asteapta sa-l gaseasca pe Dizzywig la docurile din Ratchet, in Barrens.",al={"locatia lui dizzywig","unde este dizzywig","unde il gasesti pe dizzywig"}},{q="La ce foloseste ordinul lui Kravel?",a="Gnomele de la Mirage Raceway asteapta piese care au ajuns in Ratchet acum o saptamana. Kravel nu poate merge personal, asa ca te roaga sa-i duci comanda la docurile de acolo.",al={"la ce folosesc piesele","de ce sa mergi la ratchet"}},{q="Ce urmeaza dupa Wharfmaster Dizzywig?",a="Urmatoarea etapa din lant este Parts for Kravel.",al={"urmatoarea misiune dupa Dizzywig","ce urmeaza"}}},fp="20,272,18.302.0,20.173.0,38.120.0,40.109.0,38.166.0,38.47.0"}
P.entries["quest:1112"] = {n="Parts for Kravel",s="Dupa ce ai dus comanda de piese a lui Kravel Koalbeard la Wharfmaster Dizzywig, duci acum inapoi pachetul lui Kravel la Mirage Raceway, in Shimmering Flats. Dizzywig trimite si un mesaj: daca Kravel mai vrea comenzi speciale, va trebui sa-si plateasca datoria.",h="Dupa ce ai dus comanda de piese a lui Kravel Koalbeard la Wharfmaster Dizzywig, duci acum inapoi pachetul lui...",kw={"kravel koalbeard","mirage raceway","parts for kravel","shimmering flats","thousand needles","wharfmaster dizzywig"},sec={{t="Un pachet si o nota de plata",b="Wharfmaster Dizzywig iti da un pachet destinat lui Kravel Koalbeard, care asteapta la Mirage Raceway, in Shimmering Flats din Thousand Needles. Dizzywig iti cere sa-i transmiti si un avertisment: daca Kravel spera sa primeasca mai multe comenzi speciale, trebuie mai intai sa-si achite datoria."},{t="Bun venit din partea lui Kravel",b="Kravel se bucura ca a sosit pachetul si spune ca tot trebuie sa ajunga la gnome. Mai intai, insa, pune lada jos, scoate un obiect mic si si-l strecoara in buzunar."}},faq={{q="Cine iti da pachetul destinat lui Kravel?",a="Wharfmaster Dizzywig din Ratchet iti da pachetul si iti cere sa-l duci inapoi lui Kravel Koalbeard.",al={"cine incepe Parts for Kravel","de unde provin piesele","cel care ofera misiunea Parts for Kravel"}},{q="Unde asteapta Kravel Koalbeard livrarea?",a="Kravel se afla la Mirage Raceway, pe Shimmering Flats din Thousand Needles.",al={"locatia lui Kravel Koalbeard","unde este Kravel","unde predau Parts for Kravel"}},{q="Ce mesaj vrea Dizzywig sa fie transmis odata cu piesele?",a="Dizzywig iti spune sa-i zici ca, daca Kravel vrea alte comenzi speciale, trebuie sa-si achite socoteala.",al={"ce spune Dizzywig","mesajul lui Dizzywig pentru Kravel","jetonul lui Kravel"}},{q="Ce a precedat aceasta livrare?",a="Urmeaza dupa etapa in care ai dus comanda de piese a lui Kravel la Wharfmaster Dizzywig din Ratchet.",al={"piese pentru kravel cerinte","misiunea anterioara parts for kravel"}}},fp="16,266,19.266.0,16.173.1,37.104.0,47.76.0,62.96.0,31.99.0"}
P.entries["quest:1114"] = {n="Delivery to the Gnomes",s="Kravel Koalbeard are acum tot ce-i trebuie si vrea ca Delicate Car Parts sa fie duse la Fizzle Brassbolts, in Shimmering Flats, care le asteapta de multa vreme. Kravel recunoaste ca a luat o piesa mica din comanda lui Fizzle si sugereaza sa nu pomenesti nimic despre asta.",h="Kravel Koalbeard are acum tot ce-i trebuie si vrea ca Delicate Car Parts sa fie duse la Fizzle Brassbolts, in...",kw={"piese auto delicate","Delivery to the Gnomes","Fizzle Brassbolts","clichet hidraulic","Kravel Koalbeard","Mirage Raceway","suruburi pentru repetor","Shimmering Flats","Thousand Needles"},sec={{t="O piesa lipsa",b="Kravel Koalbeard iti spune ca piesele sunt pentru Fizzle Brassbolts, care asteapta de multa vreme. Kravel marturiseste ca a luat o bucatica din comanda lui Fizzle, dar e sigur ca lipsa ei nu va fi observata. Spune ca piesa e mica si fara valoare, te sfatuieste sa nu aduci vorba despre ea si iti cere sa ai incredere in el."},{t="Verdictul lui Fizzle",b="Fizzle Brassbolts intampina cu bucurie coletul: hidro-clichetii si suruburile repetitoare au sosit, in sfarsit, si isi vor face treaba."}},faq={{q="Cine ii trimite piesele lui Fizzle Brassbolts?",a="Kravel Koalbeard, la Mirage Raceway. Iti cere sa duci piesele mai departe, la Fizzle Brassbolts.",al={"cine da Delivery to the Gnomes","cine ofera misiunea Delivery to the Gnomes","cine trimite piesele"}},{q="Ce a luat Kravel Koalbeard din colet?",a="Kravel spune ca a scos o piesa mica din comanda lui Fizzle, pe care o considera neinsemnata si fara valoare, si ar prefera sa nu-i spui lui Fizzle.",al={"ce a luat kravel","ce lipseste dintre piese","kravel a furat piese"}},{q="Unde trebuie dusa aceasta livrare?",a="La Fizzle Brassbolts, in Shimmering Flats, pe aceeasi campie cu Mirage Raceway, unde se afla Kravel Koalbeard.",al={"locatia Delivery to the Gnomes","unde se afla Fizzle Brassbolts","livrarea din Shimmering Flats"}},{q="Ce a precedat aceasta livrare?",a="Urmeaza dupa Parts for Kravel, in care ai adus pachetul lui Kravel din Ratchet inapoi la el.",al={"misiunea precedenta Delivery to the Gnomes","ce duce la Delivery to the Gnomes"}}},fp="22,263,16.299.0,16.130.1,41.96.0,48.150.0,28.119.0,31.94.0"}
P.entries["quest:1115"] = {n="The Rumormonger",s="Dupa ce i-a ajutat pe gnomi, Kravel Koalbeard vrea acum sa le faca un bine goblinilor. A auzit ca Nazz Steamboil, pilotul goblin al masinii de curse, avea candva alt nume si se intreaba daca secretul valoreaza bani. Te trimite la Krazek din Booty Bay, care ar trebui sa stie.",h="Dupa ce i-a ajutat pe gnomi, Kravel Koalbeard vrea acum sa le faca un bine goblinilor.",kw={"booty bay","kravel koalbeard","krazek","mirage raceway","nazz steamboil","salty sailor tavern","shimmering flats","stranglethorn vale","thousand needles"},sec={{t="Un nume despre care merita sa intrebi",b="Kravel Koalbeard spune ca urmatorii care vor primi o favoare sunt goblinii. Aude ca Nazz Steamboil, pilotul goblin de curse, purta candva alt nume, iar Kravel se intreaba de ce s-a schimbat, daca ascunde vreun secret si daca Nazz vrea sa-l pastreze ascuns. Kravel spune ca Krazek, aflat la capatul sudic al Stranglethorn, in Booty Bay, ar sti adevarul. Informatiile utile ar putea aduce profit. Cauta-l pe Krazek la Salty Sailor Tavern."},{t="Raspunsul lui Krazek",b="Krazek il stie pe Nazz Steamboil drept pilot de curse de pe Shimmering Flats. Krazek spune ca s-ar putea afla ceva, dar te avertizeaza ca nu va fi nici usor, nici rapid, nici ieftin."}},faq={{q="Cine te trimite la Krazek?",a="Kravel Koalbeard, un dwarf de la Mirage Raceway, din Shimmering Flats, te trimite.",al={"cine ofera the rumormonger","cel care da misiunea rumormonger","cine incepe misiunea"}},{q="De ce este Kravel interesat de Nazz Steamboil?",a="Kravel a auzit ca pilotul goblin al vehiculului de curse nu a purtat dintotdeauna acel nume. Se intreaba daca e un secret si daca Nazz il pretuieste indeajuns incat sa fie profitabil.",al={"de ce nazz steamboil","motivul lui kravel nazz","care este zvonul"}},{q="Unde poate fi gasit Krazek?",a="Krazek se afla la Salty Sailor Tavern, in Booty Bay, la extremitatea sudica a Stranglethorn.",al={"locatia lui Krazek","unde este Krazek","cum il gasesc pe Krazek"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Delivery to the Gnomes, serviciul facut pentru gnomi.",al={"cerinte pentru Rumormonger","misiunea anterioara Rumormonger","ce misiune se face mai intai"}}},fp="15,277,25.442.0,15.174.1,24.88.0,43.162.0,26.88.0,23.67.0"}
P.entries["quest:1116"] = {n="Dream Dust in the Swamp",s="Krazek din Booty Bay spune ca a afla lucruri despre Nazz este o mare favoare. In timp ce Krazek ia legatura cu sursele sale, ti se cere sa aduci 10 particule de praf de vis, luate de la dragonii pui din Swamp of Sorrows, pentru tabachera lui Krazek. Adu-le inapoi si Krazek iti va da informatiile cautate.",h="Krazek din Booty Bay spune ca a afla lucruri despre Nazz este o mare favoare.",kw={"booty bay","praf de vis","kravel koalbeard","krazek","mirage raceway","nazz","swamp of sorrows","pui de dragon"},sec={{t="Un serviciu pentru un serviciu",b="Krazek iti spune ca aflarea unor informatii despre Nazz este o favoare insemnata si ca ai venit de departe, tocmai din Shimmering Flats. In timp ce Krazek ia legatura cu sursele sale, ti se cere sa aduni ceva. Alegerea cade asupra a zece firimituri de praf de vis, luate de la pui de dragon din Swamp of Sorrows, pe care Krazek le-ar vrea pentru o punga de tutun de prizat. Cand te intorci cu ele, informatiile iti apartin."},{t="Unde se gaseste praful",b="Dragonii verzi din Swamp of Sorrows poarta praf de vis. Atat puii adolescenti, cat si puii adormiti il au, iar ambele tipuri traiesc in coltul de sud-vest al mlastinii."}},faq={{q="Cine cere praful de vis?",a="Krazek din Booty Bay o cere in schimbul informatiilor despre Nazz.",al={"cine ofera misiunea dream dust","cine ma trimite in swamp of sorrows","cel care da misiunea dream dust"}},{q="De ce vrea Krazek praf de vis?",a="Krazek spune ca praful este necesar pentru o tabachera si ti-l cere in timp ce ia legatura cu surse pentru a afla informatii despre Nazz.",al={"la ce foloseste praful de vis","de ce vrea krazek praf","priza de praf de vis"}},{q="Unde se gaseste praful de vis?",a="Este luat de la puii de dragon din Swamp of Sorrows, precum cei adolescenti si cei adormiti, in coltul de sud-vest al mlastinii.",al={"unde gasesti dream dust","unde se afla dream dust in swamp of sorrows","locatia lui dream dust"}},{q="Cum se leaga acest lucru de Kravel Koalbeard?",a="Kravel Koalbeard din Mirage Raceway te-a trimis la Krazek sa intrebi despre pilotul goblin Nazz Steamboil, iar tu ai venit din Shimmering Flats pentru raspuns.",al={"de ce sunt in booty bay","cum are legatura cu kravel","legatura cu shimmering flats"}},{q="Ce urmeaza?",a="Urmatorul pas este Rumors for Kravel.",al={"ce urmeaza dupa Dream Dust in the Swamp","urmatoarea misiune dupa Dream Dust","ce urmeaza dupa Rumors for Kravel"}}},fp="23,287,19.398.0,23.162.0,33.76.0,32.102.0,30.132.0,47.164.0,16.35.0"}
P.entries["quest:1117"] = {n="Rumors for Kravel",s="Krazek a gasit ceea ce cautai. Dupa ce a apelat la favoruri, a facut numeroase deductii si a renuntat la o sticla rara de vin elfic, Krazek a scris o scrisoare despre Nazz Steamboil. Este prea periculos ca Krazek sa o foloseasca, asa ca o duci la Kravel Koalbeard, in Shimmering Flats, si ti se cere sa nu spui de unde provine.",h="Krazek a gasit ceea ce cautai.",kw={"booty bay","zvonuri despre goblin","kravel koalbeard","krazek","mirage raceway","nazz steamboil","rumors for kravel","shimmering flats","thousand needles"},sec={{t="O scrisoare de la Krazek",b="Krazek iti spune cat a costat cautarea: s-au consumat cateva favoruri, s-a dat o sticla rara de vin elfic si s-au facut o multime de deductii. Rezultatul este o scrisoare cu cateva informatii foarte interesante despre Nazz Steamboil. Krazek o considera prea periculoasa ca s-o foloseasca si ti-o lasa tie, sa faci ce doresti cu ea, atata timp cat nimeni nu afla de unde provine. Trebuie dusa inapoi la Kravel Koalbeard, in Shimmering Flats."},{t="Verdictul lui Kravel",b="Kravel considera scrisoarea foarte interesanta. Se gandeste ca poate ar trebui sa se incline in fata pilotului goblin data viitoare cand se intalnesc si se asteapta ca Nazz sa dea o mica avere ca secretul sa ramana ingropat."}},faq={{q="Unde incepe asta?",a="Krazek iti da scrisoarea in Booty Bay, dupa ce aduci praful de vis.",al={"cine ofera Rumors for Kravel","cel care incepe Rumors for Kravel","de unde iau zvonurile"}},{q="Cui trebuie sa-i fie adusa scrisoarea?",a="Lui Kravel Koalbeard, la Mirage Raceway, in Shimmering Flats din Thousand Needles.",al={"unde predau Rumors for Kravel","cine primeste zvonurile despre goblin","unde este Kravel Koalbeard"}},{q="Cine face obiectul descoperirilor lui Krazek?",a="Nazz Steamboil, pilotul goblin al vehiculului de curse. Krazek a notat in scrisoare cateva lucruri foarte interesante despre Nazz.",al={"cine este Nazz Steamboil","despre ce este zvonul","despre cine sunt zvonurile"}},{q="Cum a descoperit Krazek informatia?",a="Krazek si-a folosit cateva favoruri, a facut multe deductii si a renuntat la o sticla rara de vin elfic.",al={"cum a obtinut Krazek informatiile","favorurile lui Krazek"}},{q="Ce urmeaza?",a="Urmatoarea etapa din lant este Back to Booty Bay.",al={"urmatoarea misiune dupa Rumors for Kravel","continuarea misiunii Rumors for Kravel"}}},fp="17,326,20.418.0,16.192.1,22.73.0,37.91.0,40.110.0,39.97.0,16.48.0"}
P.entries["quest:1118"] = {n="Back to Booty Bay",s="Kravel Koalbeard are incredere in tine sa duci o treaba la bun sfarsit si sa pastrezi tacerea. Are un nou plan, riscant, dar care promite un castig frumos pentru amandoi. Ii duci scrisoarea lui Crank Fizzlebub in Booty Bay. Aceasta urmeaza dupa Rumors for Kravel.",h="Kravel Koalbeard are incredere in tine sa duci o treaba la bun sfarsit si sa pastrezi tacerea.",kw={"booty bay","crank fizzlebub","kravel koalbeard","planul lui kravel","mirage raceway","salty sailor tavern","shimmering flats","thousand needles"},sec={{t="O scrisoare pentru Booty Bay",b="Kravel Koalbeard, Dwarf de la Mirage Raceway, spune ca esti o persoana in care poate avea incredere, atat sa duci treaba la bun sfarsit, cat si sa-ti tii gura. Noul lui plan este riscant, dar daca reuseste, amandoi veti face o gramada de bani. Isi cere scuze ca te trimite inapoi la Booty Bay, unde te-a dus si ultima lui treaba, si iti cere sa-l gasesti acolo pe Crank Fizzlebub si sa-i inmanezi o scrisoare. Daca Crank are nevoie de ajutor, Kravel vrea sa faci tot ce poti si spune ca efortul va merita."},{t="Crank citeste planul",b="Crank Fizzlebub citeste scrisoarea si isi da seama ca Kravel pune la cale un plan grandios. Crank apreciaza mintea sa sinistra. Planul va avea nevoie de ceva puternic care sa zapaceasca mintile, iar Crank se intreaba daca amestecul pe care Zanzil il da zombie-lor sai ar putea fi folosit."}},faq={{q="Unde incepe si unde se termina aceasta calatorie?",a="Totul incepe cu Kravel Koalbeard la Mirage Raceway din Thousand Needles. Ii duci scrisoarea lui Crank Fizzlebub, care se gaseste la Salty Sailor Tavern, in Booty Bay, in Stranglethorn Vale.",al={"unde merg","cine da Back to Booty Bay","unde este Crank Fizzlebub"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa Rumors for Kravel, pasul anterior care te-a dus la Booty Bay.",al={"conditii prealabile","misiunea precedenta","ce misiune trebuie facuta mai intai"}},{q="Ce este planul lui Kravel?",a="Este scrisoarea pe care o duci la Crank Fizzlebub. Kravel numeste planul riscant si spune ca, daca da roade, voi doi ati putea castiga o avere.",al={"care este planul lui kravel","scrisoare despre planul lui kravel"}},{q="Ce ar trebui sa faci daca Crank Fizzlebub are nevoie de ajutor?",a="Kravel iti cere sa faci tot ce poti pentru a-l ajuta si spune ca efortul va merita.",al={"ajuta-l pe crank","are crank nevoie de ajutor"}},{q="Ce urmeaza dupa asta?",a="Lantul continua cu Zanzil's Mixture and a Fool's Stout.",al={"urmatoarea misiune","ce urmeaza dupa intoarcerea la Booty Bay"}}},fp="17,233,22.462.0,22.254.1,38.193.0,22.74.0,24.142.0,49.80.0,22.61.0"}
P.entries["quest:1119"] = {n="Zanzil's Mixture and a Fool's Stout",s="Crank Fizzlebub a descoperit ca Zanzil's Mixture amestecat in bere tare da o bautura puternica, numita Fool's Stout. Crede ca va fi exact ce-i trebuie lui Kravel. Du-o la Kravel Koalbeard, la Mirage Raceway din Shimmering Flats, si grabeste-te, fiindca nu se va mentine proaspata.",h="Crank Fizzlebub a descoperit ca Zanzil's Mixture amestecat in bere tare da o bautura puternica, numita Fool's...",kw={"booty bay","fizzlebub","kravel","amestec","pista de curse","campiile sclipitoare","bere tare","zanzil"},sec={{t="O libatie pentru Kravel",b="Crank Fizzlebub a descoperit ca Zanzil's Mixture, amestecat in bere tare, da o bautura puternica: Fool's Stout. Crank crede ca va fi exact ce-i trebuie lui Kravel si vrea sa afle cum functioneaza. Du bautura inapoi la Kravel Koalbeard, la Mirage Raceway din Shimmering Flats."},{t="Nu-l lasa sa zaca",b="Crank te avertizeaza sa nu pastrezi berea tare prea mult timp. Amestecul are un efect ciudat asupra drojdiei din bere, facand-o sa fermenteze accelerat, asa ca bautura nu va ramane proaspata la nesfarsit."}},faq={{q="Cine te trimite sa faci aceasta livrare?",a="Crank Fizzlebub din Booty Bay iti da Fool's Stout sa-l transporti.",al={"cine incepe Zanzil's Mixture and a Fool's Stout","cel care da misiunea"}},{q="Cine primeste Fool's Stout?",a="Kravel Koalbeard, la Mirage Raceway din Shimmering Flats, in Thousand Needles.",al={"cine primeste berea","unde o predau","locatia lui kravel"}},{q="De ce trebuie livrata bautura rapid?",a="Fiindca amestecul grabeste fermentarea drojdiei, iar berea tare lasata prea mult se strica.",al={"expira fool's stout","de ce are limita de timp","efectul fermentarii"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa Back to Booty Bay si Zanzil's Secret.",al={"misiuni prealabile","etapa precedenta"}},{q="Ce urmeaza dupa livrarea berii tari?",a="Lantul continua cu Fool's Stout, Get the Gnomes Drunk si Get the Goblins Drunk.",al={"urmatoarea misiune","ce urmeaza"}}},fp="35,279,21.273.0,17.178.0,31.65.0,30.84.0,48.77.0,22.49.0,38.86.0"}
P.entries["quest:112"] = {n="Collecting Kelp",s="In Goldshire, Maybell Maclure cauta o cale de a-l vizita pe Tommy Joe Stonefield fara sa fie vazuta. William Pestle are nevoie de alge cristaline rare pentru a prepara o licoare de invizibilitate pentru ea.",h="In Goldshire, Maybell Maclure cauta o cale de a-l vizita pe Tommy Joe Stonefield fara sa fie vazuta.",kw={"collecting kelp","alga cristalina","crystal lake","goldshire","licoare de invizibilitate","maybell maclure","murloc","tommy joe stonefield","william pestle"},ang={["faction:Alliance"]="Pentru Alliance, curatarea taberelor de murloci din jurul Crystal Lake pentru Pestle ajuta la potolirea amenintarii agresive de langa drumul estic din Goldshire.",["profession:Herbalism"]="Pentru tine, ca culegator, algele cristaline sunt o descoperire ciudata: o planta oceanica scoasa din pungile murlocilor de apa dulce, nu din sol sau de pe fundul marii."},sec={{t="Un leac pentru iubirea interzisa",b="Vrajba dintre familiile Stonefield si Maclure o impiedica pe Maybell Maclure sa se intalneasca pe fata cu Tommy Joe Stonefield. Maybell vrea sa-si vada iubitul fara sa provoace o ciocnire armata intre familiile lor, asa ca incearca sa gaseasca o cale de a traversa valea fara sa fie vazuta. William Pestle, un herbalist si apotecar de la Lion's Pride Inn din Goldshire, planuieste sa prepare o potiune a invizibilitatii. Ingredientele rare de care are nevoie nu se gasesc in camara hanului."},{t="Hoardarii de la Crystal Lake",b="Algele cristaline sunt catalizatorul de care are nevoie William Pestle pentru preparatul sau. De obicei, aceste frunze cresc departe, in oceanele cu apa sarata, dar murlocii tribali au adus provizii in interiorul uscatului, in taberele lor rudimentare de-a lungul Crystal Lake, chiar la est de Goldshire. Instinctele lor neobisnuite i-au facut sa care plantele marine pana la malul cu apa dulce. Trebuie sa recuperezi suficiente frunze de la murloci inainte sa te intorci cu ele la Goldshire."}},faq={{q="De ce are nevoie William Pestle de alge cristaline?",a="William Pestle are nevoie de alge cristaline pentru a prepara o licoare a invizibilitatii pentru Maybell Maclure. Bautura ar trebui sa o ajute sa plece nevazuta din podgoria familiei si sa-l viziteze pe Tommy Joe Stonefield.",al={"de ce algele cristaline","la ce folosesc algele","ingredientele lui William Pestle"}},{q="De ce se gaseste varec marin in apropiere de Crystal Lake, un lac cu apa dulce?",a="Algele cristaline cresc in ocean, dar triburile de murlocs din jurul Crystal Lake scormonesc printre frunze si le duc in interiorul uscatului. Le depoziteaza in taberele de pe malul lacului, singura sursa locala din apropiere de Goldshire.",al={"de ce e varec la crystal lake","varec in apa dulce","povestea varecului murlocilor"}},{q="Cine sunt Maybell Maclure si Tommy Joe Stonefield?",a="Maybell Maclure si Tommy Joe Stonefield sunt doi tineri indragostiti din familii rivale de fermieri din sudul Elwynn Forest. Familiile lor se urasc, asa ca cei doi trebuie sa se bazeze pe discretie si trucuri alchimice pentru a se intalni.",al={"cine este Maybell","cine este Tommy Joe","cearta dintre familiile Maclure si Stonefield"}},{q="Unde se afla Crystal Lake?",a="Crystal Lake se afla chiar la est de Goldshire, in centrul Elwynn Forest. Murloc ostili i-au infestat apele si tarmurile.",al={"unde se afla Crystal Lake","locatia lui Crystal Lake","gaseste Crystal Lake"}},{q="Ce se intampla dupa ce aduni varecul?",a="Dupa ce ii aduci patru frunze de varec de cristal, William Pestle le distileaza intr-un Invisibility Liquor. Apoi iti cere sa-l duci la Maybell Maclure, ca ea sa se poata strecura fara sa fie vazuta.",al={"urmatoarea misiune dupa kelp","ce prepara pistilul"}},{q="Cine este William Pestle?",a="William Pestle este farmacist si cocheteaza cu alchimia la Lion's Pride Inn din Goldshire. El ii ajuta pe localnici cu leacuri populare, potiuni ciudate si favoruri confidentiale.",al={"cine este William Pestle","Pestle din Goldshire"}}},fx={ff0f7883={q="De ce vrea William Pestle sa le dea o mana de ajutor lui Maybell si Tommy Joe?",a="William Pestle este farmacistul si alchimistul local din Goldshire si este dispus sa-si puna mestesugul in slujba tinerilor indragostiti. Maybell Maclure si Tommy Joe Stonefield se afla de parti opuse in conflictul amar si indelungat dintre familiile lor. O potiune secreta a invizibilitatii ii ofera lui Maybell o modalitate ingenioasa de a se strecura departe de privirile vigilente ale familiei, la Maclure Vineyards, fara sa starneasca si mai multe neintelegeri intre clanuri.",al={"de ce sa o ajuti pe Maybell","motivul lui William Pestle","de ce ii pasa lui William"}},cc419076={q="De ce s-au adunat murlocii la Crystal Lake?",a="Murlocii s-au strecurat spre interior de pe tarmuri si si-au stabilit tabere de-a lungul apelor dulci din Elwynn Forest, precum Crystal Lake si Stonecairn Lake. Fortele militare din Stormwind sunt deja suprasolicitate, aparand alte granite, iar acesti amfibieni agresivi au prins curaj, apropiindu-se de asezarile locale si strangand materiale, inclusiv varec oceanic pe care il aduc cu ei dinspre coasta.",al={"de ce sunt murloci in Crystal Lake","murlocii din Crystal Lake","murloci in Elwynn"}}},fp="15,158,27.434.0,30.410.0,42.183.0,53.210.0,49.211.0,30.112.0,39.178.0,22.170.0"}
P.entries["quest:1120"] = {n="Get the Gnomes Drunk",s="Kravel Koalbeard vrea ca Fool's Stout sa fie testata pe echipa de la boxe de pe Mirage Raceway. Daca alegi gnomii, duci bautura la Gnome Pit Boss. Mai devreme sau mai tarziu, bautura se va strica, asa ca Kravel spune sa nu astepti prea mult.",h="Kravel Koalbeard vrea ca Fool's Stout sa fie testata pe echipa de la boxe de pe Mirage Raceway.",kw={"fool's stout","maistru gnome de arena","kravel koalbeard","mirage raceway","thousand needles","zanzil"},sec={{t="O incercare pentru echipele din arena",b="Kravel Koalbeard trebuie sa testeze Fool's Stout pe una dintre echipele de la pista. O poti incerca pe gnomes: iti da bautura tare si te trimite cu ea la Gnome Pit Boss, aflat in apropiere, la Mirage Raceway. Daca alegi gnomes, cursele vor inclina in favoarea goblins. Kravel te avertizeaza sa nu zabovesti, fiindca bautura se va strica pana la urma."},{t="O mica bautura inaintea cursei",b="Gnome Pit Boss este incantat de dar si spune ca a fost un gest atent. Recunoaste ca nu e intelept sa bei inaintea unei curse, dar echipa ar putea probabil sa bea putin. Pana la urma, n-are cum sa fie atat de tare."}},faq={{q="Cine iti cere sa livrezi berea tare?",a="Kravel Koalbeard, dwarf-ul de la Mirage Raceway din Thousand Needles, iti da berea stout.",al={"cine da misiunea Get the Gnomes Drunk","cine ofera misiunea Get the Gnomes Drunk","misiunea lui Kravel Koalbeard"}},{q="Cui trebuie sa-i fie livrata berea Fool's Stout?",a="Pentru Gnome Pit Boss, care se afla in apropiere, la Mirage Raceway.",al={"unde duc berea tare","cine primeste berea tare a nebunilor","locatia sefului gnom din arena"}},{q="Ce se intampla daca intarzii prea mult cu livrarea berii tari?",a="Bere neagra se va strica pana la urma, asa ca Kravel iti spune sa nu astepti prea mult.",al={"se strica fools stout","cronometru pentru stout","fools stout se strica"}},{q="Poti alege sa-i ataci pe goblins in schimb?",a="Da. Kravel te lasa sa alegi cu care echipa de mecanici sa incerci berea tare, iar cealalta optiune este Get the Goblins Drunk.",al={"alegerea de a imbata goblins","pot sa imbat goblins in schimb","cursa gnomes sau goblins"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Zanzil's Mixture and a Fool's Stout.",al={"misiunea anterioara","cerinta pentru Get the Gnomes Drunk"}},{q="Ce urmeaza dupa livrarea berii brune?",a="Lantul continua cu Report Back to Fizzlebub.",al={"misiunea urmatoare","ce urmeaza dupa ce-i imbati pe gnomes"}}},fp="20,222,23.338.0,30.214.1,34.91.0,45.59.0,55.75.0,45.108.0,23.47.0,40.50.0"}
P.entries["quest:1121"] = {n="Get the Goblins Drunk",s="Kravel Koalbeard vrea ca Fool's Stout sa fie testata pe echipa de la boxe de pe Mirage Raceway. Daca alegi goblinii, duci bautura la Goblin Pit Boss. Mai devreme sau mai tarziu, bautura se va strica, asa ca Kravel spune sa nu astepti prea mult.",h="Kravel Koalbeard vrea ca Fool's Stout sa fie testata pe echipa de la boxe de pe Mirage Raceway.",kw={"berari stout","gnome","goblin","maistru de groapa goblin","kravel koalbeard","mirage raceway","thousand needles"},sec={{t="O incercare pentru echipele din arena",b="Kravel Koalbeard trebuie sa testeze Fool's Stout pe una dintre echipele de la pista. O poti incerca pe goblins: iti da bautura tare si te trimite cu ea la Goblin Pit Boss, aflat in apropiere, la Mirage Raceway. Daca alegi goblins, cursele vor inclina in favoarea gnomes. Kravel te avertizeaza sa nu zabovesti, fiindca bautura se va strica pana la urma."},{t="Putin nu strica",b="Seful arenei Goblin vede ca i se ofera bautura si nu refuza putin."}},faq={{q="Cine ofera asta?",a="Kravel Koalbeard, dwarf-ul de la Mirage Raceway din Thousand Needles.",al={"cel care ofera misiunea","cine da get the goblins drunk","kravel koalbeard"}},{q="Unde trebuie dusa berea neagra?",a="Pentru Goblin Pit Boss, care se afla in apropiere, la Mirage Raceway.",al={"unde sa duci berea tare","locatia sefului de groapa goblin"}},{q="Ce se intampla daca astepti prea mult?",a="Bere neagra se va strica pana la urma, asa ca Kravel iti spune sa nu astepti prea mult.",al={"se strica berea","cat rezista Fool's Stout","berea se invecheste"}},{q="Care este alternativa la asta?",a="Kravel te lasa sa alegi ce echipa de boxe va incerca bautura tare. Cealalta optiune este Imbata-i pe Gnomes, cu echipa de gnome.",al={"imbata-i pe Gnome","cursa Gnome sau Goblin"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Zanzil's Mixture and a Fool's Stout.",al={"misiunea anterioara","conditie prealabila pentru a-i imbata pe goblins"}},{q="Ce urmeaza dupa livrarea berii brune?",a="Lantul continua cu Report Back to Fizzlebub.",al={"misiunea urmatoare","ce urmeaza dupa ce-i imbata pe goblini"}}},fp="21,224,23.340.0,19.74.1,16.70.0,30.60.0,34.75.0,32.119.0,23.47.0,40.50.0"}
P.entries["quest:1122"] = {n="Report Back to Fizzlebub"}
P.entries["quest:1127"] = {n="Fool's Stout",s="Crank Fizzlebub din Booty Bay prepara loturi de Fool's Stout pentru calatorii care vor sa se intoarca la circuitul din Shimmering Flats. Pentru a pregati inca o portie, are nevoie de douasprezece flacoane cu amestecul lui Zanzil.",h="Crank Fizzlebub din Booty Bay prepara loturi de Fool's Stout pentru calatorii care vor sa se intoarca la...",kw={"booty bay","crank fizzlebub","fools stout","pista de curse","stranglethorn vale","amestecul lui zanzils"},sec={{t="Un al doilea lot",b="Pentru calatorii care au ramas fara rezervele initiale de Fool's Stout inainte sa ajunga la gnomii de pe circuitul de curse, Crank Fizzlebub se ofera sa prepare un inlocuitor. Goblinul Crank Fizzlebub din Booty Bay are nevoie de douasprezece flacoane din amestecul lui Zanzil pentru a prepara din nou bautura puternica si ii va rasplati pe cei care aduc ingredientele, oferind ceva in plus pentru a pastra tranzactia discreta."}},faq={{q="Cine se ofera sa prepare Fool's Stout?",a="Crank Fizzlebub, care se gaseste in Booty Bay, in sudul Stranglethorn Vale, prepara berea stout.",al={"cine ofera fools stout","cel care da misiunea fools stout","crank fizzlebub"}},{q="De ce ingrediente are nevoie Crank Fizzlebub?",a="Are nevoie de douasprezece flacoane din amestecul lui Zanzil pentru a prepara inca un lot de stout.",al={"ce obiecte sunt necesare pentru fools stout","ingredientele pentru fools stout","cantitatea necesara din zanzils mixture"}},{q="De ce ar avea cineva nevoie de inca o serie de Fool's Stout?",a="Amestecul se evapora dupa doua ore, asa ca cei care calatoresc si pierd acest ragaz trebuie sa adune ingrediente proaspete pentru a-l inlocui.",al={"de ce sa bei iar Fool's Stout","Fool's Stout expirat","cat dureaza Fool's Stout"}},{q="Unde ar trebui sa ajunga bautura?",a="Bautura este destinata gnomes de la pista de curse.",al={"unde ajunge berea tare a nebunilor","cine bea berea tare a nebunilor","destinatia berii tari a nebunilor"}}},fp="12,198,14.393.0,32.91.0,43.81.0,53.125.0,33.48.0"}
P.entries["quest:113"] = {n="Insect Part Analysis",s="Alchemist Pestlezugg a terminat raportul despre partile insectelor si spune ca Senior Surveyor Fizzledowser trebuie sa-l vada imediat. Amenintarea planeaza asupra Tanaris si Gadgetzan si, daca nu este oprita, asupra intregului sud al Kalimdor.",h="Alchemist Pestlezugg a terminat raportul despre partile insectelor si spune ca Senior Surveyor Fizzledowser...",kw={"fizzledowser","gadgetzan","gadgetzan water company","analiza insectelor","pestlezugg","raport","tanaris"},sec={{t="Un avertisment grav",b="Pestlezugg insista ca Senior Surveyor Fizzledowser trebuie sa vada raportul imediat si ca toti cei care pot citi trebuie sa-l vada si ei. Amenintarea este grava si serioasa pentru Tanaris si Gadgetzan si, daca nu este tinuta sub control, pentru intreg sudul Kalimdor. Ar putea ajunge chiar in tot Azeroth, caci nimic nu arata ca se va domoli. Ti se cere sa duci raportul la Fizzledowser, in Gadgetzan, si sa faci o copie, pentru a o impartasi tuturor celor de aceeasi parte cu tine. Toti trebuie sa afle despre aceasta amenintare."},{t="O chestiune de bani",b="Fizzledowser iti multumeste pentru livrare si pentru munca depusa pentru Gadgetzan Water Company. Nu-i place sa imparta cu toata lumea informatiile pretioase ale companiei, fiindca, in mod normal, oamenii ar plati bine pentru ele. Dar Fizzledowser il cunoaste de multa vreme pe Pestlezugg si, daca Pestlezugg recomanda sa le spuna tuturor, asa sa fie. Ti se face o copie."}},faq={{q="Cine trimite raportul si cine il primeste?",a="Alchemist Pestlezugg iti da raportul si te trimite cu el la Senior Surveyor Fizzledowser din Gadgetzan.",al={"cine ofera insect part analysis","cui predau insect part analysis","unde predau raportul"}},{q="De ce este Alchemist Pestlezugg atat de alarmat?",a="Pestlezugg o considera o amenintare grava si serioasa pentru Tanaris si Gadgetzan, iar daca nu este oprita, si pentru tot sudul Kalimdorului si poate chiar pentru intregul Azeroth, fara vreun semn ca s-ar domoli.",al={"avertismentul lui pestlezugg","ce contine raportul despre insecte","de ce este serioasa amenintarea insectelor"}},{q="De ce ai nevoie de o copie a raportului?",a="Pestlezugg vrea ca toata lumea sa afle despre amenintare, asa ca Fizzledowser trebuie sa faca o copie pe care s-o poti impartasi nestingherit cu ai tai.",al={"de ce sa copiezi raportul","copie raport Fizzledowser","de ce sa impartasesti raportul"}},{q="Ce se intampla chiar inaintea acestei livrari?",a="Urmeaza dupa o etapa anterioara numita tot Insect Part Analysis.",al={"misiunea anterioara","ce misiune preceda aceasta"}}},fp="20,212,15.495.0,16.367.1,41.109.0,39.185.0,37.145.0,41.59.0"}
P.entries["quest:1131"] = {n="Steelsnap"}
P.entries["quest:1132"] = {n="Fiora Longears",s="Aceasta misiune ii introduce pe aventurierii Alliance din Eastern Kingdoms pe continentul neimblanzit Kalimdor. Indrumati de entuziastul recrutor Red Jack Flint din Menethil Harbor, calatorii traverseaza Great Sea cu corabia pentru a se prezenta contactului sau elf inalt, Fiora Longears, la hanul din Theramore.",h="Aceasta misiune ii introduce pe aventurierii Alliance din Eastern Kingdoms pe continentul neimblanzit...",kw={"Theramore","barca","Dustwallow Marsh","Fiora Longears","Kalimdor","Menethil Harbor","Red Jack Flint","Wetlands"},ang={["faction:Alliance"]="Aceasta calatorie reprezinta puntea dintre Eastern Kingdoms si teritoriile elfilor noptii din Kalimdor, unind granitele estice si vestice ale Alliance.",["race:NightElf"]="Fiora Longears este oficiala care ii intampina pe aliatii sositi din est la Theramore, pregatindu-i pentru tinuturile salbatice stravechi din nordul Kalimdor."},sec={{t="Un apel catre vest",b="Pentru multi oameni, dwarves si gnomi, Eastern Kingdoms sunt marcate de conflicte vechi si pamanturi ranite. In portul aglomerat din Menethil Harbor, marinarul Red Jack Flint isi petrece zilele indemnand calatorii dornici de aventura sa se imbarce pe o corabie cu destinatia de peste Great Sea. Prezentand Kalimdor drept un tinut necartografiat, plin de bogatii si oportunitati, Flint ii indruma pe ratacitorii indrazneti spre Theramore, ca sa-l intalneasca pe asociatul sau, un elf pe nume Fiora Longears."},{t="Sosirea in Theramore",b="Traversarea oceanului ii aduce pe calatori la Theramore, un port al Alliance pe coasta din Dustwallow Marsh. Fiora Longears ii intampina la hanul orasului pe cei sositi la recomandarea lui Flint. Avand incredere in judecata lui Flint, Fiora ii primeste pe eroii Alliance proaspat sositi si se pregateste sa-i indrume spre interiorul tinutului, catre padurile stravechi din Ashenvale."}},faq={{q="Cine este Fiora Longears?",a="Fiora Longears este un high elf aflat in hanul din Theramore, in Dustwallow Marsh. Este un partener primitor si un punct de contact pentru Red Jack Flint, intampinand calatorii Alliance care sosesc din Eastern Kingdoms.",al={"Fiora Longears","cine este Fiora"}},{q="Cine incepe aceasta misiune?",a="Misiunea este oferita de Red Jack Flint, un marinar human plin de energie, aflat in Menethil Harbor, pe coasta din Wetlands.",al={"cel care da misiunea","unde iau misiunea de la Fiora Longears","cine da misiunea"}},{q="Cum ajung la Fiora Longears din Menethil Harbor?",a="Urca la bordul navei de pasageri acostate in Menethil Harbor, care navigheaza spre vest peste Great Sea, direct catre Theramore, in Dustwallow Marsh.",al={"cum ajungi la Theramore","corabia spre Theramore","barca din Menethil"}},{q="Ce se intampla dupa intalnirea cu Fiora Longears?",a="Cand o intalnesti in Theramore, Fiora lauda recomandarea lui Flint si iti ofera urmatoarea etapa a calatoriei, trimitandu-te spre interiorul continentului, la Astranaar, in Ashenvale.",al={"ce urmeaza","misiunea urmatoare","misiunea Journey to Astranaar"}},{q="Ce relatie exista intre Red Jack Flint si Fiora Longears?",a="Flint o numeste pe Fiora partenera lui de peste mare. In timp ce Flint cerceteaza tinuturile Eastern Kingdoms in cautare de aventurieri dornici sa se implice, Fiora ii primeste in Kalimdor pentru a facilita operatiunile Alliance si calatoriile spre interiorul continentului.",al={"sunt Flint si Fiora parteneri","legatura dintre Red Jack Flint si Fiora"}},{q="De ce recruteaza Alliance calatori pentru Kalimdor?",a="Kalimdor reprezinta un teritoriu vast si resurse noi pentru Alliance, precum si un front in care aliatii Night Elf au nevoie de ajutor pentru a-si apara pamanturile ancestrale de amenintari precum Horde si ramasitele demonice.",al={"de ce sa merg in kalimdor","de ce theramore"}}},fx={["869cd7aa"]={q="De ce vrea Red Jack Flint sa te trimita in Kalimdor?",a="Red Jack Flint se considera un agent al oportunitatii, insarcinat sa-i inspire pe aventurierii promitatori din Menethil Harbor sa traverseze Great Sea. Legat chiar el de docuri si tanjind dupa calatorii oceanice, rolul sau este sa gaseasca suflete calite si sa le indrume spre partenera lui high elf, Fiora Longears, care ii ajuta pe noii veniti sa-si gaseasca locul si sa contribuie la eforturile Alliance, aflate in plina crestere, in Kalimdor.",al={"motivul lui red jack flint","de ce sa ma trimita la fiora","de ce vrea jack flint sa se faca asta"}}},fp="14,298,18.431.0,20.337.0,22.211.0,22.125.0,51.136.0,42.156.0,67.199.0,53.213.0"}
P.entries["quest:1133"] = {n="Journey to Astranaar",s="Journey to Astranaar este o misiune introductiva Alliance care ii indruma pe noii veniti de pe coasta Kalimdor catre inima continentului, in Ashenvale. Indrumati de Fiora Longears din Theramore, calatorii pornesc spre nord, in Ashenvale, pentru a-i raporta lui Shindrell Swiftfire, in Astranaar. Misiunea marcheaza intrarea aventurierilor in conflictele tot mai intense din jurul padurii ancestrale a Night Elves.",h="Journey to Astranaar este o misiune introductiva Alliance care ii indruma pe noii veniti de pe coasta...",kw={"ashenvale","astranaar","theramore","dustwallow marsh","fiora longears","journey to astranaar","menethil harbor","shindrell swiftfire"},ang={["faction:Alliance"]="Aceasta calatorie reprezinta trimiterea directa a unei recrute Alliance din porturile relativ sigure din Dustwallow Marsh in salbaticia disputata din Ashenvale.",["race:Human"]="Abia sositi cu corabia din Menethil Harbor, calatorii human pasesc pentru prima oara adanc in tinuturile Kalimdorului, cinstind promisiunea Alliance de a-i ajuta pe night elves.",["race:NightElf"]="Pentru Night Elves, aceasta calatorie inseamna intoarcerea in tinutul lor natal, aflat sub asediu, unde apara ramurile sfinte din Ashenvale alaturi de aliati straini."},sec={{t="De pe coasta in paduri",b="Calatorii din Alliance care sosesc in Dustwallow Marsh cu feribotul din Menethil Harbor cauta adesea un rost in nordul Kalimdor. In Theramore, Fiora Longears le incredinteaza celor priceputi misiunea de a inainta spre interiorul continentului, catre Astranaar, principala asezare a elfilor noptii din Ashenvale. Drumul urmeaza carari serpuite, pe sub bolti stravechi si umbrite, si duce drept intr-o padure greu incercata de razboi si tulburari."},{t="O recomandare nerostita",b="In mod curios, Fiora le spune calatorilor sa nu-i pomeneasca numele cand ajung in Astranaar, precizand raspicat ca Shindrell Swiftfire nu o cunoaste. Rolul ei este doar sa indrume noii recruti ai Alliance acolo unde este cea mai mare nevoie de ei. La sosirea lor, Shindrell primeste cu bratele deschise orice aparator apt, recunoscand ca, desi Ashenvale ramane uluitoare, nu mai este sanctuarul linistit de odinioara."}},faq={{q="Unde incepe misiunea Journey to Astranaar?",a="Misiunea este data de Fiora Longears in Theramore, pe coasta din Dustwallow Marsh. Ea le-o propune calatorilor Alliance care sosesc din Eastern Kingdoms si vor sa ajute in Kalimdor.",al={"cine ofera Journey to Astranaar","incepe Journey to Astranaar","de unde iei Journey to Astranaar"}},{q="Cu cine trebuie sa vorbesc in Astranaar?",a="Trebuie sa vorbesti cu Shindrell Swiftfire, o night elf stationata in Astranaar, orasul central al Alliance din Ashenvale.",al={"unde predai journey to astranaar","npc-ul de la finalul journey to astranaar","cine este shindrell swiftfire"}},{q="De ce spune Fiora sa nu-i mentioneze numele?",a="Fiora Longears le spune in mod expres aventurierilor sa nu dezvaluie cine i-a trimis, pur si simplu pentru ca Shindrell nu o cunoaste personal. Ea doar ii indruma pe nou-venitii dornici sa ajute catre un avanpost care are nevoie disperata de sprijin.",al={"de ce nu este mentionata Fiora","legatura dintre Fiora Longears si Shindrell"}},{q="Care este scopul acestei misiuni?",a="Serveste drept indiciu care ii indruma pe personajele Alliance din Dustwallow Marsh spre Ashenvale, prezentandu-le Astranaar, principala lor baza de operatiuni din padure.",al={"de ce sa faci Journey to Astranaar","scopul povestii Journey to Astranaar"}},{q="Ce fel de probleme au loc in Ashenvale?",a="Dupa cum observa Shindrell Swiftfire la sosirea ta, Ashenvale nu mai este crangul linistit care a fost candva. Padurea se confrunta cu incursiuni din partea Horde, cu coruptia demonica ramasa din Third War si cu fauna locala agitata de conflictele recente.",al={"de ce are nevoie astranaar de ajutor","povestea problemelor din ashenvale"}},{q="Ce misiune duce la Journey to Astranaar?",a="Este precedata direct de o scurta misiune introductiva de indrumare, numita 'Fiora Longears', care le cere calatorilor sositi in Dustwallow Marsh sa vorbeasca cu ea in Theramore.",al={"conditii preliminare pentru Journey to Astranaar","lantul de misiuni al Fiorei Longears"}}},fx={["5f2da217"]={q="De ce te trimite Fiora Longears la Astranaar?",a="Fiora ii intampina pe noii calatori ai Alliance care sosesc in Theramore si ii indruma pe aventurierii capabili acolo unde este cea mai mare nevoie de ei. Astranaar este asezarea centrala a night elves din Ashenvale, o regiune cuprinsa acum de pericole tot mai mari si incursiuni ostile. Ea te trimite la Shindrell Swiftfire, pentru ca priceperea ta sa poata ajuta de indata la apararea, tot mai solicitata, a stravechii paduri de catre Alliance.",al={"de ce te trimite la Astranaar","motivul Fiora Longears","de ce te trimite Fiora"}},["432055d5"]={q="De ce iti cere Fiora sa mergi tu in loc sa mearga ea insasi?",a="Fiora ramane la Theramore Inn, in Dustwallow Marsh, si ii indruma pe calatorii dornici sa o caute pe Shindrell Swiftfire in Astranaar, unde e nevoie de ajutorul lor.",al={"de ce eu pentru Journey to Astranaar","de ce nu merge Fiora la Astranaar","de ce nu Fiora"}}},fp="20,378,29.398.0,26.407.0,48.198.0,38.116.0,43.220.0,34.172.0,47.251.0,43.173.0"}
P.entries["quest:1134"] = {n="Pridewings of Stonetalon",s="Shindrell transmite o informatie neconfirmata: ingrijorati de atacurile secrete ale Horde, Sentinels din Astranaar incearca sa intercepteze o arma mortala inainte ca aceasta sa le loveasca poporul. Informatiile din Theramore arata ca asasinii orci recolteaza venin toxic de la wyvernii din Stonetalon Mountains pentru raiduri clandestine. Pentru a-si apara fragila granita, cercetasi ai Alliance sunt trimisi spre sud sa adune primii sacii cu venin si sa-si priveze dusmanul de otrava letala.",h="Shindrell transmite o informatie neconfirmata: ingrijorati de atacurile secrete ale Horde, Sentinels din...",kw={"asasini","astranaar","mirkfallon lake","pridewings","shindrell swiftfire","stonetalon mountains","theramore","venin"},ang={["class:Druid"]="Druizii deplang adesea irosirea vietii naturale, regretand ca trebuie starpite creaturi nevinovate doar pentru ca veninurile lor sa nu ajunga la razboinici.",["class:Rogue"]="Cei din Rogue pot aprecia utilitatea letala a veninului de pridewing, intelegand perfect cat de devastatoare pot fi lamele unse in ambuscadele ascunse din salbaticie.",["faction:Alliance"]="Aceasta misiune demonstreaza existenta retelei discrete de informatii care leaga asezarea Jainei din Theramore de avanposturile Sentinel din Ashenvale, in efortul de a zadarnici agresiunea Horde.",["race:NightElf"]="Night Elf se lupta cu cruda necesitate de a ucide pridewingi salbatici, cautand echilibrul intre grija lor spirituala fata de natura si realitatea dura a razboiului de frontiera."},sec={{t="Un armistitiu fragil",b="Desi nu a fost declarat razboi deschis intre Alliance si Horde in nordul Kalimdor, pacea dintre ele este fragila. Au loc incaierari sub boltile dese ale padurii, iar loviturile discrete si usor de dezmintit au luat locul armatelor in toata regula. Comandantii santinelelor din Astranaar raman in permanenta vigilenti fata de miscarile ascunse ale dusmanului, stiind ca orice neatentie i-ar putea costa sanctuarul."},{t="Otrava din stanci",b="Shindrell relateaza o afirmatie neconfirmata: informatiile transmise de contacte discrete din Theramore au adus vestea unei operatiuni sinistre in desfasurare in crestele din Stonetalon. Urmaritori Orc au strans venin de la pridewings salbatici din jurul Mirkfallon Lake, folosind acest agent biologic puternic pentru a-si unge lamele in vederea unor raiduri prin ambuscada, fatale, impotriva personalului Alliance. Pentru a limita amenintarea, Shindrell Swiftfire le cere campionilor sa starpeasca bestiile si sa puna mana pe sacii cu venin inainte ca agentii Horde sa-i poata recolta."},{t="O datorie dureroasa",b="A le cere sa nimiceasca fiarele bastinase apasa greu asupra elfilor noptii, care venereaza profund salbaticia din Kalimdor. Shindrell deplange insasi faptul ca trebuie sa sufere creaturi nevinovate pentru un razboi in care nu au ales sa ia parte. Totusi, in calculul sumbru al apararii de frontiera, impiedicarea inamicului sa obtina arme letale este mai importanta decat protejarea mediului."}},faq={{q="Ce sunt pridewings?",a="Pridewings sunt fiare zburatoare periculoase si veninoase, inrudite cu wyvernele, care isi fac cuiburile pe stanci inalte, mai ales in jurul Mirkfallon Lake, in Stonetalon Mountains. Veninul lor puternic face din ele niste pradatori letali si o resursa ravnita de otravitori.",al={"ce sunt Pridewings","povestea Pridewing","Pridewings din Stonetalon"}},{q="De ce ii vaneaza Alliance?",a="Shindrell relateaza o acuzatie neconfirmata: informatiile Alliance indica faptul ca asasinii Horde recolteaza activ venin de pridewing pentru a unge armele folosite in raiduri clandestine impotriva pozitiilor Alliance. Macelarind bestiile si luandu-le primii sacii cu venin, Alliance priveaza Horde de aceasta otrava mortala.",al={"de ce sa ucizi pridewings","scopul misiunii","veninul pridewing pentru alianta"}},{q="Cine a furnizat informatiile despre asasinii orci?",a="Avertismentul a venit de la informatori ascunsi ai Alliance aflati in Theramore, care urmaresc indeaproape miscarile Horde si retelele de aprovizionare din tinuturile sudice ale Barrens si din Stonetalon.",al={"cine a avertizat Alianta","informatii despre spionul din theramore","sursa informatiilor lui shindrell"}},{q="Unde se afla Mirkfallon Lake?",a="Mirkfallon Lake se afla in tinuturile nordice din Stonetalon Mountains, chiar la sud de drumul de granita care vine din Ashenvale.",al={"locatia Mirkfallon Lake","unde se gasesc pridewingii","gaseste pridewingii"}},{q="Alliance si Horde sunt in razboi deschis in Ashenvale?",a="Oficial, cele doua factiuni mentin o pace fragila si evita razboiul deschis, declarat. In realitate, asasinatele sub acoperire, ciocnirile pentru resurse si conflictele de granita izbucnesc fara incetare sub bolta padurii.",al={"sunt Horde si Alliance in razboi","situatia razboiului din Ashenvale","tratat de pace in Ashenvale"}},{q="Ce parere are Shindrell Swiftfire despre uciderea bestiilor?",a="Shindrell sufera pentru ca trebuie sa porunceasca uciderea unor fiare care nu s-au alaturat de bunavoie conflictului. Totusi, ca ofiter insarcinat cu apararea Astranaar, considera ca este un sacrificiu tragic, dar necesar, pentru a-si tine poporul in siguranta.",al={"reactia lui Shindrell","vinovatie druidica","elf de noapte care ucide bestii"}}},fx={["9b2e4c3f"]={q="La ce foloseste Pridewing Venom Sac?",a="Shindrell Swiftfire iti cere sa recoltezi sacii cu venin pentru a dovedi ca fiarele au fost rarite si pentru a lipsi Horde de o sursa letala. Informatii neconfirmate din Theramore avertizeaza ca asasinii orc recolteaza venin de la pridewings din jurul Mirkfallon Lake pentru a-si unge armele in raidurile ascunse impotriva Alliance. Adunand tu insuti sacii, te asiguri ca otrava nu ajunge niciodata pe lamele dusmanilor.",al={"Pridewing Venom Sac - folosire","de ce sa colectezi saci cu venin","ce face Shindrell cu sacii cu venin"}}},fp="24,459,15.398.0,21.505.0,14.350.0,20.242.0,33.316.0,54.186.0,33.128.0,52.213.0,59.216.0"}
P.entries["quest:1135"] = {n="Highperch Venom",s="Fiora Longears din Theramore le cere aventurierilor Alliance sa calatoreasca spre vest, in canioanele din Thousand Needles. Acolo, pe culmile inalte din Highperch, isi au cuiburile vivernele periculoase, cautate pentru veninul lor exceptional de puternic.",h="Fiora Longears din Theramore le cere aventurierilor Alliance sa calatoreasca spre vest, in canioanele din...",kw={"dustwallow marsh","fiora","highperch","longears","theramore","thousand needles","venin","wyvern"},ang={["class:Rogue"]="Rogues inteleg in mod firesc atractia intunecata a toxinelor exotice. Procurarea veninului pur, nerafinat, ofera o intelegere profunda a celor mai letali agenti biologici din Kalimdor.",["faction:Alliance"]="Aventurarea in Thousand Needles ii duce pe aventurierii Alliance adanc in spatele liniilor inamice, chiar sub privirile vigilente ale patrulelor Horde formate din tauren si orci.",["race:NightElf"]="Pentru kaldorei, trimiterea vanatorilor in adancul tinuturilor aride din Thousand Needles arata cat de departe se intind interesele comerciale si cautarea reactivilor neobisnuiti, dincolo de Ashenvale si Darkshore."},sec={{t="O expeditie profitabila",b="In timp ce se odihnesc in portul insular Theramore, calatorii se pot intalni cu Fiora Longears. Desi orcii captureaza si domesticesc adesea wyverni ca sa-i foloseasca drept mijloace de transport aerian, Fiora dezvaluie existenta unui comert mult mai clandestin: cel cu veninul lor letal. Unii cumparatori din Kalimdor pretuiesc sacii de venin proaspat mult mai mult decat bestiile in sine, asa ca Fiora recruteaza vanatori dispusi sa infrunte distante lungi si inaltimi primejdioase."},{t="Stancile din Highperch",b="Cuiburile de wyverne se afla la vest de Dustwallow Marsh, printre mesetele inalte de gresie din Thousand Needles. La locul de cuibarit numit Highperch, wyvernele locale au o toxina neobisnuit de concentrata. Pentru a ajunge la cuiburi, trebuie strabatut teritoriul ostil al Horde si escaladat un tinut primejdios. Acolo, vanatorii trebuie sa ucida wyvernele si sa le extraga sacii cu venin fara sa-i deterioreze, inainte de a duce prada inapoi la Theramore."}},faq={{q="Unde gasesc wyvernele pentru aceasta misiune?",a="Wyvernii locuiesc in Highperch, o mesa inalta aflata in tinuturile vestice ale Thousand Needles, la vest de Theramore.",al={"locatia highperch","unde se afla highperch","locatia wyvernului"}},{q="Cine este Fiora Longears?",a="Fiora Longears este o persoana de contact a Alliance stationata in Theramore, in largul coastei din Dustwallow Marsh. Recruteaza aventurieri indrazneti pentru a procura reactivi naturali rari si valorosi din tot Kalimdorul.",al={"fiora longears","cine ofera Highperch Venom"}},{q="De ce este atat de valoros veninul de wyvern?",a="Veninul de wyvern este extrem de puternic si foarte cautat in anumite cercuri subterane, de apotecari si in retele comerciale. Desi Horde apreciaza wyvernele mai ales ca munti aerieni, glandele lor cu venin se vand scump alchimistilor si fabricantilor de otrava.",al={"de ce otrava de wyvern","folosirea otravii de wyvern"}},{q="De ce ma trimite o misiune din Theramore atat de departe spre vest?",a="Fiora este o negustoreasa intreprinzatoare, aflata in cautarea unor exemplare exotice care nu se gasesc in mlastinile din jurul Theramore. Highperch, din Thousand Needles, adaposteste o varietate distincta si concentrata de wyvern, care nu se gaseste in Dustwallow Marsh.",al={"de ce Thousand Needles","de ce sa te trimita in Thousand Needles"}},{q="Ce se intampla cand returnezi sacii cu venin?",a="Fiora examineaza sacii si observa ca sunt plini pana la refuz cu venin. Remarca faptul ca o asemenea calitate se gaseste de obicei doar la wyvern-ii tineri sau la femelele fertile si te felicita pentru vanatoare.",al={"reactia lui fiora","finalizarea misiunii Highperch Venom"}},{q="Este Highperch un loc sigur pentru calatorii din Alliance?",a="Nu. Thousand Needles are o prezenta puternica a Horde, concentrata in asezari din apropiere, precum Freewind Post. Urcarea pe Highperch inseamna sa infrunti atat pradatori salbatici, cat si iscoade ostile ale Horde.",al={"este Highperch periculos","Alliance in Thousand Needles"}}},fx={["9e43b6cb"]={q="De ce vrea Fiora Longears ca acest lucru sa fie facut?",a="Fiora are un ochi format pentru negotul profitabil si reactivii rari. In timp ce majoritatea ii cunosc pe wyvern doar ca animale de povara imblanzite de Horde, ea stie ca anumite cercuri platesc scump pentru veninul puternic. Recoltarea sacilor de la Highperch ii aduce un profit frumos pe aceste piete de nisa.",al={"de ce vrea Fiora venin","motivul Fiorai Longears","de ce sa recoltezi venin de wyvern"}},ef763353={q="La ce foloseste Highperch Venom Sac?",a="Sacii cu venin contin toxina letala si puternica a wyvernilor salbatici care-si fac cuiburile pe inaltimile din Thousand Needles. Pretuiti de anumiti alchimisti, otravitori si negustori de marfuri exotice, acesti saci gata sa plesneasca se vand pe bani grei in pietele care comercializeaza fiare rare si periculoase.",al={"la ce folosesc highperch venom sacs","utilizarea sacului cu venin","de ce sa colectezi saci cu venin"}},f9186ab4={q="Ce creaturi isi fac cuibul la Highperch?",a="Highperch este o mesa impunatoare din Thousand Needles, care serveste drept adapost salbatic pentru wyvernele bastinase. Neimblanziti si extrem de teritoriali, acesti pradatori inaripati planeaza prin canioanele desertului, doborandu-si prada cu acul lor veninos, apoi ducandu-si hrana in cuiburile stancoase de pe piscuri.",al={"ce sunt wyvernele din highperch","pe cine vanezi in highperch","ce traieste in highperch"}}},fp="15,226,22.421.0,22.392.0,43.115.0,22.195.0,32.245.0,48.220.0,44.181.0,41.193.0"}
P.entries["quest:1136"] = {n="Frostmaw",s="Melor Stonehoof te trimite in Muntii Alterac sa vanezi Frostmaw, un yeti rar intalnit. Un pergament explica cum sa-l ademenesti, iar Melor asteapta coama lui Frostmaw in Thunder Bluff.",h="Melor Stonehoof te trimite in Muntii Alterac sa vanezi Frostmaw, un yeti rar intalnit.",kw={"muntii alterac","gheata","coama","melo stonehoof","parcurge","cacealma de tunet","yeti"},sec={{t="O vanatoare indepartata",b="Melor Stonehoof spune ca esti gata sa calatoresti departe de casa si sa vanezi Frostmaw in Muntii Alterac. Haina alba a yetiului se imbina cu zapada de munte, iar el se arata rar. Melor va ofera un pergament care explica cum sa ademeniti Frostmaw. Aduce-i coama inapoi lui Melor in Thunder Bluff; pana atunci, calatoria ta ramane neterminata."}},faq={{q="Cine este Frostmaw?",a="Frostmaw este un yeti din Muntii Alterac. Haina lui alba se amesteca in zapada si apare rar.",al={"frostmaw cine","ce este frostmaw"}},{q="Unde pot gasi Frostmaw?",a="Frostmaw traieste in Muntii Alterac, unde haina lui alba se amesteca in zapada.",al={"locatie gheata","unde este gheata de inghet"}},{q="Cum ademenesc Frostmaw?",a="Melor Stonehoof va ofera un pergament cu instructiuni pentru a atrage Frostmaw.",al={"momeala gheata","sulul de gheata"}},{q="Ce vrea Melor de la Frostmaw?",a="Melor Stonehoof iti cere sa-i aduci coama lui Frostmaw in Thunder Bluff.",al={"melor frostmaw","coama de gheata"}}},fp="8,176,14.336.0,16.104.0,26.83.0,23.73.0,35.76.0"}
P.entries["quest:1137"] = {n="News for Fizzle",s="Martek the Exiled din Badlands are vesti despre indurium pentru Fizzle Brassbolts. Ii duci mesajul lui Martek inapoi la Shimmering Flats, in Thousand Needles.",h="Martek the Exiled din Badlands are vesti despre indurium pentru Fizzle Brassbolts.",kw={"badlands","fizzle brassbolts","indurium","minereu de indurium","martek the exiled","mirage raceway","shimmering flats","thousand needles","uldaman"},sec={{t="Vorbele lui Martek despre Indurium",b="Martek spune ca induriumul rezista remarcabil de bine la caldura si crede ca este potrivit pentru pistoanele lui Fizzle. Totusi, fulgii nu sunt de ajuns: Fizzle are nevoie de minereu de indurium adevarat, extras din adancurile Uldaman, la marginea nordica a Badlands, pe care Martek il indica drept sursa autentica de indurium. Martek te roaga sa-i transmiti salutari lui Fizzle Brassbolts si sa-i repeti toate acestea."},{t="Fizzle afla vestea",b="Fizzle Brassbolts abia asteapta sa afle ce a spus Martek si daca Martek il poate ajuta. Cand ii povestesti despre calatoriile tale prin Badlands, Fizzle declara ca indurium este cheia."}},faq={{q="Unde incepe si unde se termina aceasta calatorie?",a="Martek the Exiled din Badlands iti da un mesaj, pe care il duci lui Fizzle Brassbolts, la Mirage Raceway din Shimmering Flats, in Thousand Needles.",al={"cine ofera News for Fizzle","unde predau News for Fizzle","de la Martek la Fizzle"}},{q="Ce veste ii trimite Martek lui Fizzle?",a="Martek spune ca indurium rezista remarcabil de bine la caldura si ar trebui sa fie potrivit pentru pistoanele lui Fizzle. Fizzle are nevoie de minereu adevarat, nu de bucatele, iar acesta trebuie extras din adancurile lui Uldaman.",al={"ce spune martek","vesti despre indurium","mesajul lui martek"}},{q="De unde provine minereul de indurium?",a="Martek spune ca este scoasa din adancurile lui Uldaman, de la marginea nordica a Badlands, pe care Martek o numeste adevarata sursa de indurium.",al={"unde se gaseste minereul de indurium","sursa minereului de indurium"}},{q="Unde se incadreaza acest pas in firul narativ?",a="Urmeaza dupa Indurium, in lantul inceput cand Fizzle Brassbolts te-a trimis la Martek the Exiled.",al={"lantul News for Fizzle","misiunea anterioara News for Fizzle"}}},fp="15,157,25.365.0,21.173.1,38.159.0,37.184.0,34.137.0,42.98.0"}
P.entries["quest:1138"] = {n="Fruit of the Sea",s="Fruit of the Sea este o misiune Alliance oferita de pescarul Gubber Blump, pe docurile din Auberdine. Pasionat de preparatele culinare cu crustacee, Gubber le cere calatorilor sa cerceteze coasta din Darkshore in cautare de bucati alese de crab, in timp ce el se ocupa de unditele sale.",h="Fruit of the Sea este o misiune Alliance oferita de pescarul Gubber Blump, pe docurile din Auberdine.",kw={"Auberdine","Darkshore","encrusted tide crawlers","bucati fine de crab","fructe de mare","Gubber Blump","reef crawlers"},ang={["faction:Alliance"]="Auberdine este un punct esential de debarcare pentru exploratorii Alliance care sosesc in Kalimdor, oferind mici ajutoare, precum sprijinirea pescarilor locali sa se stabileasca.",["profession:Cooking"]="Explicatiile entuziaste ale lui Gubber despre retetele cu crab sunt o sursa de inspiratie pentru orice bucatar care vrea sa profite la maximum de captura locala de pe coasta.",["race:Dwarf"]="Sa auda un strain din nordul Kalimdorului visand sa gateasca un 'crab surpriza din Ironforge' le aminteste placut de casa calatorilor alpinisti din Khaz Modan."},sec={{t="Pasiune pentru crustacee",b="Gubber Blump, un pescar care isi arunca undita de pe lungile pontoane de lemn din Auberdine, are o pasiune culinara obsesiva pentru carnea de crab. Considerand crabii adevarata bogatie a oceanului, Gubber viseaza la un repertoriu nesfarsit de retete: de la preparate coapte, fripte la gratar si fierte, pana la specialitati locale elaborate, precum crabul cu radacina whipper si crabul-surpriza din Ironforge."},{t="Cercetarea baltilor de maree",b="Gubber nu se poate desprinde de undita sa, asa ca se bazeaza pe aventurierii in trecere pentru a aduna ingrediente de pe plajele invaluite in ceata ale Darkshore. Tarmul e plin de taratoare de recif si taratoare de mare acoperite de crusta, care misuna printre valuri, fiind o sursa la indemana - desi uneori cam ciupitoare - de carne pentru un bucatar de coasta in devenire."}},faq={{q="Cine ofera misiunea Fruit of the Sea?",a="Misiunea este oferita de Gubber Blump, un pescar din Alliance stationat pe docurile din Auberdine, in Darkshore.",al={"cel care da misiunea Fruit of the Sea","cine ofera Fruit of the Sea","misiunea lui Gubber Blump"}},{q="Ce creaturi lasa in urma Fine Crab Chunks?",a="Fine Crab Chunks sunt recoltate de la crabii reef crawler si tide crawler acoperiti de scoici, care se deplaseaza pe tarmurile si prin apele putin adanci de-a lungul coastei Darkshore.",al={"de unde cad bucatile fine de crab","ce creaturi lasa bucati de crab","ce crabi lasa bucati fine de crab"}},{q="De ce nu strange Gubber singur carnea de crab?",a="Gubber este ocupat cu pescuitul de pe pontoanele din Auberdine si nu-si poate lasa undita ca sa vaneze crabi taratori pe plaja.",al={"de ce nu-si ia gubber propriul crab","de ce are gubber nevoie de ajutor"}},{q="Ce feluri de mancare vrea Gubber sa prepare?",a="Gubber se lauda cu o varietate uriasa de moduri de preparare, printre care salata de crab, supa, tocana, crab cu piper, crab cu lamaie, crab cu radacina de whipper si o reteta regionala pe care o numeste crab-surpriza Ironforge.",al={"retete cu crabi ale lui gubber","ce retete mentioneaza gubber","preparate cu crab"}},{q="Face aluzie Gubber Blump la ceva in discursul sau?",a="Da. Monologul sau, care insira toate metodele imaginabile de a gati crab, este un omagiu evident adus lui Benjamin Buford 'Bubba' Blue din filmul Forrest Gump, care a rostit in mod celebru un discurs identic despre creveti.",al={"referinta la cultura pop pentru Gubber Blump","referinta la Forrest Gump si Bubba"}},{q="Unde are loc aceasta misiune?",a="Misiunea incepe si se preda in satul-port Auberdine, iar vanatoarea se desfasoara de-a lungul coastelor din Darkshore, in nordul Kalimdorului.",al={"unde se gaseste fructul marii","in ce zona se gaseste fructul marii"}}},fx={cf4b2535={q="La ce folosesc Fine Crab Chunks?",a="Gubber Blump intentioneaza sa le foloseasca intr-o nesfarsita varietate de preparate culinare. Pentru el, crabii sunt roadele marii, numai buni de copt, pus pe gratar, fiert, fript, prajit sau amestecat in supe, tocanite si salate.",al={"la ce folosesc bucatile fine de crab","de ce bucati fine de crab","ce face Gubber cu bucatile de crab"}},["82492fa1"]={q="Ce sunt taratorii de-a lungul coastei Darkshore?",a="Reef Crawler si Tide Crawler cu crusta sunt crustacee bastinase care cauta hrana de-a lungul tarmurilor lungi si cetoase ale Darkshore si prin bazinele mlastinoase de la reflux. Desi sunt periculoase pentru cei care umbla neatenti pe plaja, carnea lor este apreciata de pescari si bucatari precum Gubber Blump, pentru festinuri bogate cu roadele tarmului.",al={"ce sunt reef crawlers","encrusted tide crawlers darkshore","crabi din Darkshore"}}},fp="16,260,25.370.0,21.355.0,37.107.0,41.150.0,48.128.0,37.196.0,47.202.0,33.145.0"}
P.entries["quest:114"] = {n="The Escape",s="Maybell Maclure asteapta ocazia de a se furisa de langa familia ei si de a se intalni cu Tommy Joe Stonefield. Ii aduci Invisibility Liquor preparata de William Pestle din alge cristaline culese din intreaga regiune.",h="Maybell Maclure asteapta ocazia de a se furisa de langa familia ei si de a se intalni cu Tommy Joe Stonefield.",kw={"elwynn forest","licoare de invizibilitate","podgoriile maclure","maybell maclure","ferma stonefield","evadarea","tommy joe stonefield","william pestle"},ang={["faction:Alliance"]="Ca aventurier Alliance aflat la inceput de drum in Elwynn Forest, ajutorul oferit lui Tommy Joe si Maybell iti da un ragaz amuzant de la luptele cu banditii Defias si gnolii. Ranchiunele de la tara dainuie chiar si in apropiere de Stormwind.",["race:Human"]="Ca human din Elwynn, stii ca vechile ranchiune dintre familii sunt adanci, iar micile gesturi de ajutor secret intre vecini pot contribui la mentinerea pacii."},sec={{t="O licoare pentru iubirea adevarata",b="Familiile Maclures si Stonefields se dusmanesc de generatii, fara sa lase loc pentru idile. Gramma Stonefield apeleaza la William Pestle, un alchimist de la Lion's Pride Inn din Goldshire. Cu alge cristaline din lacurile apropiate, Pestle prepara Invisibility Liquor, suficient de puternica pentru a ascunde fuga lui Maybell din gospodaria Maclure."},{t="Disparitia in padure",b="Maybell Maclure ia plosca si se strecoara printre copaci, spre Tommy Joe. O apasa vina ca si-a inselat rudele, dar devotamentul ei cantareste mai mult decat teama de a fi descoperita. Bea licoarea si dispare sub ochii tai, castigand cateva clipe alaturi de Tommy Joe, departe de privirile vigilente ale batranilor aflati in vrajba."}},faq={{q="Cine ofera misiunea The Escape?",a="William Pestle, farmacistul si asistentul alchimist de la Lion's Pride Inn din Goldshire, iti da Invisibility Liquor dupa ce ii aduci alge cristaline.",al={"cel care da misiunea The Escape","cine incepe The Escape","de unde iei misiunea The Escape"}},{q="La ce foloseste Invisibility Liquor?",a="Invisibility Liquor ii permite lui Maybell Maclure sa devina invizibila suficient de mult timp cat sa plece de la ferma familiei si sa-l viziteze pe Tommy Joe Stonefield fara sa-si provoace rudele.",al={"de ce sa folosesc licoarea invizibilitatii","ce face potiunea","scopul licorii invizibilitatii"}},{q="De ce trebuie Maybell si Tommy Joe sa-si ascunda relatia?",a="Familiile Maclure si Stonefield sunt rivale inversunate, iar ostilitatea lor adanca interzice orice curtare pe fata intre copiii lor.",al={"de ce se ascund","cearta dintre Stonefield si Maclure","de ce nu pot fi impreuna Maybell si Tommy Joe"}},{q="Ce se intampla cand ii duci potiunea lui Maybell?",a="Maybell iti multumeste, sfasiata intre vinovatie si entuziasm, apoi bea licoarea. Dispare sub ochii tai, ca sa se strecoare spre Tommy Joe.",al={"ce se intampla la final","dispare Maybell","finalizarea misiunii The Escape"}},{q="Ce misiune duce direct la The Escape?",a="Misiunea Escape urmeaza dupa Collecting Kelp, in care aduni alge cristaline de la murlocii din Crystal Lake, pentru ca William Pestle sa prepare potiunea de invizibilitate.",al={"conditie prealabila pentru evadare","misiune inainte de evadare","ce duce la evadare"}},{q="Pune aceasta misiune capat dusmaniei dintre familii?",a="Nu. Potiunea le ofera indragostitilor doar o scurta intalnire secreta. Vrajba dintre Gramma Stonefield si Maclures ramane acerba si nerezolvata.",al={"se impaca familiile","s-a incheiat dusmania","se termina dusmania"}}},fx={["245b9158"]={q="De ce ii ajuta William Pestle pe Tommy Joe si Maybell?",a="William Pestle este un farmacist dispus sa dea o mana de ajutor celor tineri indragostiti. Dupa ce Gramma Stonefield i-a trimis un biletel in care ii cerea o cale de a ocoli cearta amara dintre familiile Stonefield si Maclure, William a fost de acord sa prepare o portie de Invisibility Liquor, cu conditia sa primeasca alge de cristal. Nu are nimic personal de castigat, in afara de a-i ajuta pe cei doi indragostiti sortiti sa se intalneasca in taina fara sa starneasca o noua incaierare intre neamurile lor potrivnice.",al={"de ce ajuta William","motivul lui William Pestle","de ce sa o ajuti pe Maybell sa scape"}},["53ceb805"]={q="De ce te trimite William Pestle sa livrezi bautura, in loc sa o faca el insusi?",a="William isi tine dugheana aglomerata in Lion's Pride Inn din Goldshire si nu-si poate abandona cu usurinta negotul ca sa faca drumuri prin padure. Mai important, daca ar umbla prin viile Maclure cu licori alchimice suspecte, rudele protectoare ale lui Maybell l-ar banui imediat. Tu, aventurier ratacitor care ai fost deja curier intre indragostiti si ai strans ingredientele, poti intra pe nesimtite in ferma si ii poti inmana licoarea.",al={"de ce te trimite william","de ce livrez potiunea de invizibilitate","de ce nu poate william sa livreze potiunea"}}},fp="10,196,26.319.0,24.307.1,31.156.0,41.162.0,61.129.0,52.137.1,42.146.0,54.144.1"}
P.entries["quest:1140"] = {n="The Tower of Althalaxx"}
P.entries["quest:1141"] = {n="The Family and the Fishing Pole"}
P.entries["quest:1142"] = {n="Mortality Wanes",s="In adancurile tufarisurilor ostile din Razorfen Kraul, un night elf pe moarte, pe nume Heralath Fallowbrook, ii sopteste ultima rugaminte primului aventurier din Alliance care trece pe acolo. Lipsit de putere si pe moarte, cere doar sa-i fie recuperat pandantivul de logodna furat al sotiei si dus inapoi acasa, la Darnassus, alaturi de vestea mortii sale.",h="In adancurile tufarisurilor ostile din Razorfen Kraul, un night elf pe moarte, pe nume Heralath Fallowbrook...",kw={"darnassus","falfindel","heralath fallowbrook","lonebrow","mortality wanes","pandantivul legaturii","razorfen kraul","treshala fallowbrook"},ang={["faction:Alliance"]="Pentru campionii Alliance care se aventureaza in inima zonei Barrens, dominata de Horde, sa duca acasa la Darnassus ultimul simbol al lui Heralath este o datorie solemna, dictata de onoare.",["race:Dwarf"]="Ultimele cuvinte ale lui Heralath cinstesc curajul piticului Lonebrow, care si-a riscat viata pentru a duce departe un avertisment urgent din fortareata quilboarilor.",["race:NightElf"]="Night Elves simt o durere personala profunda cand isi vad unul dintre semeni pierind singur si uitat printre ciulinii barbari din sudul Barrens."},sec={{t="Ultima suflare printre spini",b="Razorfen Kraul este un refugiu primejdios, invadat de quilboari salbatici si magie neagra, departe de teritoriul Alliance. Printre maracinii inselatori se afla Heralath Fallowbrook, ranit mortal si pe cale sa-si dea ultima suflare. Cu puterile pe sfarsite, reuseste doar sa murmure cuvinte incoerente, dezvaluind ca un pitic curajos pe nume Lonebrow a fost trimis inainte pentru a-i duce un avertisment lui Falfindel. Heralath stie insa ca nu va mai parasi niciodata Kraul-ul in viata."},{t="Pandantivul legaturii",b="Inainte de a-si da ultima suflare, Heralath se agata de o singura dorinta: sa-si recupereze amintirea casatoriei. Un pandantiv care simboliza legatura sa vesnica cu sotia lui, Treshala, i-a fost smuls de unul dintre pradatorii malefici ai barlogului. El implora orice calator care se opreste langa el sa recupereze pandantivul si sa-l duca pana la Darnassus, de cealalta parte a Kalimdorului, pentru ca Treshala sa afle adevarul despre moartea lui solitara, in loc sa astepte in zadar."},{t="Durere in Darnassus",b="Cand Treshala Fallowbrook primeste in Darnassus mostenirea de familie recuperata, vestea mortii sotului ei o zdrobeste. Confruntandu-se cu cruzimea aspra a lumii, jura ca munca lui Heralath nu va pieri odata cu el. Lasata sa jeleasca in singuratate, isi asuma povara mostenirii lui in timp ce se lupta cu durerea care a cuprins-o pe neasteptate."}},faq={{q="Cine este Heralath Fallowbrook?",a="Heralath Fallowbrook este un night elf din Alliance, gasit ranit de moarte in Razorfen Kraul. Pe masura ce-si pierde repede puterile, le incredinteaza aventurierilor care trec pe acolo sarcina de a recupera pandantivul de legamant furat al sotiei sale si de a duce vestea mortii lui la Darnassus.",al={"Heralath Fallowbrook","cine este Heralath","elf muribund din Razorfen"}},{q="Unde se afla Heralath Fallowbrook?",a="Heralath se afla in Razorfen Kraul, bastionul quilboarilor napadit de spini, aflat in tinuturile sudice ale Barrens.",al={"locatia lui heralath","unde este heralath","unde il gasesti pe heralath"}},{q="Cine a fost Lonebrow?",a="Lonebrow este un pitic curajos, pomenit de Heralath in ultimele sale clipe. Se pare ca Lonebrow a fost trimis intr-o misiune urgenta, din desisul de maracini, pentru a-l avertiza pe Falfindel cu privire la primejdiile care se abat asupra Kraulului.",al={"piticul lonebrow","cine este lonebrow","avertismentul lui lonebrow"}},{q="Cine este Treshala Fallowbrook?",a="Treshala este sotia lui Heralath si locuieste in capitala elfilor noptii, Darnassus. Ea primeste pandantivul recuperat si trebuie sa indure vestea tragica a mortii sotului ei.",al={"Treshala Fallowbrook","cine este Treshala","sotia lui Heralath"}},{q="Ce este pandantivul legaturii?",a="Pandantivul de legamant este o amintire draga, care simbolizeaza casatoria dintre Heralath si Treshala Fallowbrook. Quilboarii agresori l-au furat de la Heralath in Razorfen Kraul, inainte sa moara.",al={"pandantivul Treshalei","ce este pandantivul","pandantivul legaturii"}},{q="Cum reactioneaza Treshala la veste?",a="Treshala este indurerata de tragedie si deplange cruzimea lumii. In ciuda durerii sale profunde, hotaraste ca munca lui Heralath trebuie sa continue prin ea si cere sa fie lasata singura sa jeleasca.",al={"reactia Treshalei","ce se intampla cand predai pandantivul"}}},fx={aa8861aa={q="De ce vrea Heralath Fallowbrook ca aceasta treaba sa fie facuta?",a="Heralath stie ca moare, adanc in mijlocul spinilor ostili din Razorfen Kraul. Ultima sa dorinta nu este sa-si salveze propria viata, ci sa se asigure ca iubita sa sotie, Treshala, afla ce i s-a intamplat si primeste pandantivul drag de legamant, furat de la el de quilboar, inainte sa-si dea ultima suflare.",al={"de ce sa-l ajuti pe heralath","motivul lui heralath fallowbrook","de ce sa trimiti pandantivul"}},["170253dc"]={q="De ce nu poate Heralath Fallowbrook sa recupereze pandantivul singur?",a="Heralath este ranit mortal si se stinge repede, neajutorat printre quilboar fiorosi din Kraul. Abia mai are destula putere ca sa-si murmure ultima rugaminte, fiind cu totul incapabil sa-si infrunte atacatorii sau sa supravietuiasca singur calatoriei inapoi la Darnassus.",al={"de ce are Heralath nevoie de mine","de ce nu se poate ocupa Heralath de asta","de ce eu, Mortality Wanes"}}},fp="15,314,28.416.0,22.427.0,18.349.1,28.252.0,38.125.0,17.196.0,28.167.0,31.202.0,36.199.1"}
P.entries["quest:1143"] = {n="The Tower of Althalaxx"}
P.entries["quest:1147"] = {n="The Swarm Grows",s="Moktar Krin din Ironstone Camp spune ca Belgrom vrea ca silithid sa fie impinsi inapoi in adancurile din care s-au tarat. Grupul de razboinici pe jumatate mort al lui Moktar nu poate face asta, asa ca iti cere sa te ocupi de silithid de la situl de excavare din sud.",h="Moktar Krin din Ironstone Camp spune ca Belgrom vrea ca silithid sa fie impinsi inapoi in adancurile din care...",kw={"belgrom","explorers' league","ironstone camp","moktar krin","rustmaul dig site","shimmering flats","silithid","thousand needles"},sec={{t="O banda de razboinici pe jumatate moarta",b="Dupa The Swarm Grows (2), Moktar Krin spune ca Belgrom considera silithid o amenintare si vrea sa-i alunge inapoi in adancurile din care au venit. Dupa ce au ucis deja dwarf-ii trimisi de Explorers' League, oamenii lui Moktar nu mai sunt in stare sa lupte din nou, iar el nu se poate ocupa de asta fara ajutor. Situl de excavare se afla la sud, iar Moktar nu se asteapta sa mai gaseasca acolo dwarf-i. Cautatorii, dronele stupului si invadatorii sunt silithid care trebuie ucisi, iar grupul lui Moktar nu poate pleca pana cand treaba nu este gata."},{t="Multumirile lui Moktar",b="Moktar glumeste ca icorul care te acopera iti imbunatateste de fapt infatisarea, desi pute. Moktar te avertizeaza sa stai departe de kodo si spune ca numai mirosul dovedeste ca ti-ai facut partea impotriva silithizilor."}},faq={{q="Unde se afla infestarea cu silithizi?",a="La Rustmaul Dig Site, la sud de Ironstone Camp.",al={"locatia silithidelor","unde sunt insectele","unde este situl sapaturilor"}},{q="De ce nu se poate ocupa singur grupul lui Moktar Krin de insecte?",a="Grupul de razboinici al lui Moktar este pe jumatate mort dupa ce i-a ucis pe Dwarfii trimisi de Explorers' League si, in starea aceasta, nu poate duce alta batalie.",al={"de ce sa-l ajuti pe moktar","de ce este ranita trupa de razboinici","starea grupului lui moktar"}},{q="Cine vrea sa-i alunge pe silithizi?",a="Belgrom considera silithid o amenintare si vrea sa-i impinga inapoi in adancurile din care s-au tarat.",al={"cine vrea silithizii morti","ordinul lui belgrom privind silithizii"}},{q="Ce feluri de silithid trebuie invinse?",a="Silithid Searchers, Silithid Hive Drones si Silithid Invaders, cate cinci din fiecare.",al={"ce silithid sa omori","tinte silithid"}},{q="Mai sunt dwarves la situl arheologic?",a="Moktar spune ca nu ar mai trebui sa fie Dwarves cu care sa te ocupi acolo.",al={"sunt Dwarves la rustmaul","Explorers' League la situl de excavatii"}}},fp="15,230,21.486.0,15.216.1,42.50.0,60.141.0,35.107.0,40.77.0,40.63.0"}
P.entries["quest:1148"] = {n="Parts of the Swarm",s="Rasucind o carapace de silithid crapata in Thousand Needles, descoperi ca placile sale sunt impletite atat de strans, incat sunt remarcabil de rezistente, iar creatura pare puternica si foarte evoluata. Korran de la Crossroads ar fi probabil interesat sa studieze mai multe.",h="Rasucind o carapace de silithid crapata in Thousand Needles, descoperi ca placile sale sunt impletite atat de...",kw={"carapace","crossroads","field of giants","inima","korran","silithid","gheare","thousand needles"},ang={["faction:Horde"]="Aceasta este o chestiune a Horde: Korran trebuie sa primeasca exemplarele la Crossroads."},sec={{t="O carapace neobisnuita",b="O examinare mai atenta arata ca chitina este impletita atat de strans, incat nu seamana cu nimic din ce ai mai vazut. Restul corpului spune aceeasi poveste despre o forta si o evolutie remarcabile. Iti dai seama ca Korran, de la Crossroads, s-ar bucura sa examineze mai multe asemenea creaturi, ca sa le afle natura si originea. Sunt necesare un cord silithid, cinci gheare silithid si trei carapace silithid intregi."},{t="Mostre pentru Korran",b="Korran este multumit si remarca faptul ca aceste exemplare, impreuna cu ouale gasite in Field of Giants, reprezinta un inceput bun pentru a intelege ce fel de creaturi sunt insectele si ce cauta."}},faq={{q="Cine vrea aceste parti de silithid?",a="Korran de la Crossroads, care ar dori sa studieze mai multe dintre aceste creaturi.",al={"cine este Korran","preda Parts of the Swarm","cine studiaza silithizii"}},{q="Unde incepe asta?",a="Incepe cand examinezi o carapace de silithid crapata in Thousand Needles.",al={"cum incepi parts of the swarm","inceputul cracked silithid carapace","unde gasesti carapacea"}},{q="Ce specimene vrea Korran?",a="O inima de silithid, cinci gheare de silithid si trei carapace intacte de silithid.",al={"ce obiecte sunt necesare","lista pieselor de silithid","ce trebuie sa adun"}},{q="De ce ar vrea Korran sa studieze silithid?",a="Studierea mai multora dintre ele ar putea dezvalui natura si originea creaturilor.",al={"de ce sa studiezi silithid","ce afla korran"}}},fp="18,256,18.418.0,20.200.1,31.74.0,22.75.0,32.77.0,40.66.0"}
P.entries["quest:1149"] = {n="Test of Faith",s="Test of Faith este un ritual spiritual administrat de pustnicul Dorn Plainstalker, sus, deasupra fundului canionului din Thousand Needles. Acesta ii pune la incercare pe aventurierii Horde, care trebuie sa-si dovedeasca hotararea pasind de pe o scandura de lemn instabila in prapastia deschisa de dedesubt.",h="Test of Faith este un ritual spiritual administrat de pustnicul Dorn Plainstalker, sus, deasupra fundului...",kw={"dorn plainstalker","horde","leap of faith","scanduri","test of endurance","test of faith","thousand needles"},ang={["class:Priest"]="Preotii care isi petrec zilele cultivand credinta in puteri superioare sunt pusi la incercare, fiind nevoiti sa-si transforme convingerile teoretice in actiune fizica propriu-zisa.",["faction:Horde"]="Incercarile reflecta valorile fundamentale care unesc tanara Horde in Kalimdor: convingere absoluta, rezistenta in fata mediilor ostile si vointa neclintita.",["race:Tauren"]="Pentru poporul Shu'halo, ritualurile de trecere prin locurile sacre din Kalimdor sunt o traditie straveche, iar incercarea lui Dorn cere o dovada palpabila de incredere in cele nevazute."},sec={{t="Masura spiritului",b="Dorn Plainstalker locuieste intr-un loc retras, cu vedere spre piscurile sculptate de vant din Thousand Needles, meditand la insusirile care alcatuiesc o fiinta vie: mintea, trupul si spiritul. In loc sa se bazeze pe traditii tribale simple, Dorn isi impune propriile incercari pentru a masura ce se afla cu adevarat inlauntrul unui aventurier. El sustine ca, desi convingerea poate lua multe forme, trasatura esentiala este pur si simplu taria de a crede in ceva suficient de puternic incat sa-ti risti viata pentru acel lucru."},{t="Saltul in vid",b="Incercarea pare inselator de simpla. Dus pe varful abrupt al unuia dintre tancurile inalte de piatra, aspirantul sta pe scanduri de lemn batute de vreme, suspendate deasupra haului. Pentru a trece proba, trebuie sa-si invinga instinctul de autoconservare si sa paseasca in gol, fara nicio garantie concreta ca va supravietui. Cei care sar sunt opriti din cadere de forte arcane sau spirituale si purtati inapoi in siguranta, dovedind astfel ca spiritul lor este destul de puternic pentru a infrunta incercarile neprevazute ce-i asteapta."}},faq={{q="Cine este Dorn Plainstalker?",a="Dorn Plainstalker este un pustnic tauren care locuieste intr-o tabara izolata, pe marginea unei stanci, deasupra Thousand Needles. El este supraveghetorul spiritual care cauta aventurieri din Horde si le pune la incercare diferitele insusiri omenesti: credinta, rezistenta si puterea.",al={"istoria lui dorn plainstalker","cine ofera test of faith","cel care da misiunea thousand needles"}},{q="Ma va ucide daca sar de pe scandura?",a="Nu. Desi saltul de pe turla acului pare fatal, incercarea este un act de incredere. Odata ce pasesti de pe scandurile de lemn, o protectie magica te prinde in cadere si te teleporteaza direct inapoi in pestera lui Dorn Plainstalker, nevatamat.",al={"mor daca sar","ma poate ucide dauna de cadere in test of faith","este test of faith periculos"}},{q="Ce se intampla dupa ce treci Test of Faith?",a="Dovedirea credintei este doar ritualul de inceput din seria de incercari a lui Dorn. Odata ce spiritul tau este considerat receptiv, Dorn iti pune imediat la incercare rezistenta fizica in Test of Endurance.",al={"ce urmeaza dupa Test of Faith","lantul misiunii Test of Faith","urmatoarea misiune pentru Dorn Plainstalker"}},{q="De ce spune Dorn ca esecul inseamna sa intelegi imensitatea Netherului?",a="Este trista aducere aminte a lui Dorn despre efemeritatea vietii. In ochii lui, cei lipsiti de focul launtric necesar pentru a se dedica pe deplin incercarii risca sa-si piarda viata - si sufletul - in golul nesfarsit de dincolo de lumea celor vii.",al={"intelesul nemarginirii Infernului","citatul lui Dorn Plainstalker despre Infern"}},{q="Pot aventurierii din Alliance sa sustina acest test?",a="Nu. Dorn Plainstalker isi ofera intelepciunea si indrumarea spirituala doar campionilor de partea Horde, care strabat canioanele periculoase din sudul Kalimdor.",al={"misiunea Test of Faith este doar pentru Hoarda","poate Alianta sa faca Test of Faith"}},{q="Unde are loc Test of Faith?",a="Incercarea incepe in tabara lui Dorn, intre peretii canionului din Thousand Needles, care se leaga in mod magic de prapastia ametitoare a unei turle de piatra izolate, iesind deasupra fundului defileului.",al={"locatia testului credintei","unde este scandura in Thousand Needles"}}},fx={f9bf32d9={q="De ce iti pune Dorn Plainstalker credinta la incercare?",a="Dorn Plainstalker crede ca fiecare fiinta este modelata de spirit, trup si minte. Unele insusiri sunt influentate de traditiile culturale, in timp ce altele pot fi descoperite doar adanc in tine. Prin aceste incercari, Dorn vrea sa-ti masoare puterea interioara si sa-ti pregateasca spiritul pentru greutati. Iti cere sa te arunci fara sa vezi in vanturile canionului, pentru a-ti dovedi credinta si increderea, desi nu ti se garanteaza supravietuirea, si pentru a se asigura ca mintea ta este deschisa provocarilor mai mari care te asteapta.",al={"de ce vrea Dorn sa se faca asta","motivul lui Dorn Plainstalker","de ce este testul Leap of Faith"}}},fp="13,255,23.490.0,22.488.1,25.251.0,35.246.1,45.190.1,69.219.0,40.159.0,40.181.0"}
P.entries["quest:115"] = {n="Shadow Magic",s="Shadow Magic este o misiune disperata data de Marshal Marris pentru a zadarnici artele intunecate care intaresc invazia Blackrock in Redridge. Aruncatorii de umbre Blackrock au adus pe campul de lupta sfere nocturne patate de demoni, folosind energii intunecate impotriva aparatorilor coplesiti din Lakeshire. Recuperarea si distrugerea acestor relicve blestemate este esentiala pentru mentinerea liniei defensive a orasului.",h="Shadow Magic este o misiune disperata data de Marshal Marris pentru a zadarnici artele intunecate care...",kw={"orci blackrock","contaminat de demoni","lakeshire","marshal marris","glob de la miezul noptii","redridge","magie a umbrelor","vrajitor al umbrelor"},ang={["class:Paladin"]="Infruntarea invocatorilor umbrelor si punerea in siguranta a relicvelor patate de demoni indeplinesc in mod direct datoria sfanta de a curata taramul muritor de coruptia demonica.",["class:Warlock"]="Sferele miezonoptice demonstreaza radacinile demonice durabile ale Blackrock clan, oferindu-le warlockilor o privire asupra canalizarii demonice brute practicate de vrajitorii orci.",["faction:Alliance"]="Lakeshire este in pragul caderii, practic fara intariri din Stormwind; lipsirea Blackrock clan de artileria sa intunecata este cruciala pentru supravietuirea regiunii."},sec={{t="Un arsenal sinistru",b="Desi forta bruta a fost dintotdeauna semnul distinctiv al Blackrock clan, incursiunile recente ale acestuia in Redridge Mountains dezvaluie o amenintare mult mai perfida. Invadatorii si-au intarit randurile cu vrajitori ai umbrelor care stapanesc puteri intunecate. Acesti vrajitori nu se bazeaza doar pe vrajitorie; ei isi canalizeaza energiile vilului si ale umbrelor prin artefacte patate de demoni, cunoscute drept sfere ale miezului noptii. Artefactele au provocat pierderi cumplite in randul militiei locale, inclinand si mai mult in favoarea invadatorilor o lupta deja disperata."},{t="Stapanirea coruptiei",b="Marshal Marris, care coordoneaza apararea subrezita a Lakeshire din centrul orasului, intelege ca otelul obisnuit nu poate invinge cu usurinta relicvele intunecate. Daca orcii Blackrock isi pastreaza globurile nocturne, granitele estice din Redridge risca sa se prabuseasca de tot. Poruncindu-le aventurierilor sa-i ucida pe evocatorii umbrelor si sa puna mana pe globuri, Marris nu urmareste sa foloseasca aceasta magie primejdioasa, ci sa vada relicvele demonice distruse."}},faq={{q="Ce sunt globurile miezonoptii?",a="Globurile Midnight sunt conducte pangarite de demoni, purtate de vrajitorii umbrelor Blackrock. Ele concentreaza magia neagra pentru a le da lovituri nimicitoare aparatorilor muritori din Redridge.",al={"globul miezului noptii","ce este un glob al miezului noptii","ce fac globurile miezului noptii"}},{q="De ce vrea Marshal Marris aceste sfere?",a="Marshal Marris vrea ca sferele sa fie indepartate cu totul de pe campul de lupta, pentru a paraliza puterea ofensiva a vrajitorilor umbrelor Blackrock. Intentioneaza ca relicvele demonice sa fie eliminate in siguranta si distruse.",al={"de ce sa aduni globurile miezului noptii","globurile lui marris","planul lui marris pentru globuri"}},{q="Cine sunt vrajitorii umbrelor Blackrock?",a="Sunt vrajitori printre orcii Blackrock care practica magia umbrelor si magia patata de energia malefica, oferind artilerie magica si blesteme in sprijinul razboinicilor brutali ai clanului.",al={"vrajitori Blackrock","cine foloseste magia umbrelor","vrajitorii Blackrock"}},{q="Unde se gasesc conjuratorii umbrelor?",a="Blackrock shadowcasters sunt trimisi in taberele si pozitiile fortificate ale Blackrock clan din nord-estul Redridge Mountains.",al={"unde sunt shadowcasters","locatia shadowcaster","taberele shadowcaster din Blackrock"}},{q="Va studia Lakeshire globurile sau le va folosi?",a="Nu. Marshal Marris ii considera periculosi si patati de demoni, afirmand cu tarie ca lumea ar fi mai buna fara ei. Scopul lui declarat este sa-i nimiceasca pe loc.",al={"va folosi Lakeshire globurile","poate Alianta sa foloseasca globurile","sunt globurile utile"}},{q="De ce apare magie demonica in Redridge?",a="Blackrock clan are o lunga istorie de relatii cu entitati intunecate si demonice, datand din vremea Old Horde. Vrajitorii sai continua sa foloseasca relicve demonice si magie a umbrelor pentru a-si intari cuceririle.",al={"de ce sunt demoni in Redridge","influenta demonica Blackrock","fel in Redridge"}}},fx={["809c126b"]={q="De ce are nevoie Marshal Marris de un aventurier in loc sa-si foloseasca propriii gardieni?",a="Garnizoana locala din Lakeshire este intinsa pana la limita. Stormwind nu trimite intariri, iar Marshal Marris abia reuseste sa adune destui soldati pentru a apara podul orasului si a tine drumurile libere de gnolli si de patrulele de cercetasi orci. Infiltrarea fortaretelor inamice pentru a-i dobori pe evocatorii umbrelor Blackrock cere un aventurier independent, in stare sa loveasca din spatele liniilor ostile, unde nu se pot trimite garzile obisnuite ale orasului.",al={"de ce eu pentru magia umbrelor","de ce are marris nevoie de mine","de ce sa nu-i trimita pe garzile din lakeshire"}}},fp="12,378,18.523.0,20.428.0,23.169.0,40.202.0,36.166.0,34.139.0,37.176.0,43.208.0"}
P.entries["quest:1150"] = {n="Test of Endurance",s="Test of Endurance este a doua proba dintr-o serie de incercari spirituale supravegheate de Dorn Plainstalker in Thousand Needles. Dupa ce si-au dovedit deja curajul, aventurierii Horde trebuie sa-si impinga rezistenta fizica la limita, infiltrandu-se in Roguefeather Den si provocand-o pe necrutatoarea conducatoare harpie, Grenka Bloodscreech.",h="Test of Endurance este a doua proba dintr-o serie de incercari spirituale supravegheate de Dorn Plainstalker...",kw={"Dorn Plainstalker","Freewind Post","Grenka Bloodscreech","Roguefeather Den","canionul tipetelor","proba rezistentei","Thousand Needles","Weathered Nook"},ang={["faction:Horde"]="Dorn le propune aceste incercari tuturor raselor Horde, crezand ca tinerii razboinici din fiecare trib trebuie caliti prin greutati inainte de a infrunta primejdiile din Kalimdor.",["race:Tauren"]="Pentru calatorii tauren, incercarile lui Dorn Plainstalker reflecta riturile traditionale de trecere, punand la incercare daca rezistenta fizica a unui initiat este pe masura indrumarii spirituale a Earth Mother."},sec={{t="Testarea trupului",b="Dorn Plainstalker, care locuieste in Weathered Nook, si-a luat asupra sa sarcina de a-i cali pe tinerii razboinici inainte ca acestia sa porneasca spre lumea mai vasta si mai aspra. Daca proba initiala a demonstrat ca un calator are o credinta neclintita si sange rece, aceasta incercare ii pune la incercare rezistenta fizica. In viziunea lui Dorn, pregatirea adevarata cere armonie intre devotamentul spiritual, disciplina mintii si rezistenta pura necesara pentru a supravietui unei brutalitati indelungate."},{t="Incursiune in Roguefeather Den",b="Arena aleasa pentru aceasta incercare este Roguefeather Den, o pestera primejdioasa ascunsa in Screeching Canyon, la vest de Freewind Post. Plina de harpii ostile, pestera reprezinta un pericol grav pentru calatorii singuratici. Pentru a duce incercarea la bun sfarsit, challengerii trebuie sa-si croiasca drum adanc in cotetul subteran, sa saboteze proviziile stranse de harpii si sa infrunte riposta feroce a stolului pana cand insasi matriarha Grenka Bloodscreech intra in lupta."}},faq={{q="Cine ofera Test of Endurance?",a="Misiunea este oferita de Dorn Plainstalker, un batran tauren stationat la Weathered Nook, pe falezele canionului din Thousand Needles.",al={"cine ofera misiunea test of endurance","cine incepe test of endurance","misiunea lui dorn plainstalker"}},{q="Unde se afla Roguefeather Den?",a="Roguefeather Den se afla sus, de-a lungul peretilor canionului sudic din Thousand Needles, la vest de Freewind Post. Calatorii trebuie sa urce pe o poteca serpuitoare prin Screeching Canyon pentru a ajunge la rampa care duce la intrarea pesterii.",al={"locatia Roguefeather Den","unde se afla pestera harpiilor","rampele din Screeching Canyon"}},{q="Cum il invoci pe Grenka Bloodscreech?",a="Grenka Bloodscreech apare dupa ce iti croiesti drum pana in cele mai adanci incaperi ale Roguefeather Den si vandalizezi proviziile de hrana si echipamente depozitate acolo de harpii, provocand-o sa-si apere cuibul.",al={"invocarea lui grenka","cum sa-l invoci pe grenka bloodscreech","gaseste-l pe grenka"}},{q="Ce urmeaza dupa Test of Endurance?",a="Sa-i inapoiezi gheara retezata a lui Grenka lui Dorn Plainstalker iti dovedeste rezistenta fizica, iar el te trimite la urmatoarea provocare din seria sa: Test of Strength.",al={"urmatoarea misiune dupa rezistenta","ce urmeaza dupa Proba rezistentei","urmatoarea proba pentru Dorn Plainstalker"}},{q="De ce ii testeaza Dorn pe aventurierii care nu sunt tauren?",a="Dorn crede ca menirea sa este sa-i indrume pe toti tinerii din Horde, indiferent de rasa sau trib. El considera ca mandria neincercata este o sentinta la moarte in lumea larga si insista ca fiecare razboinic sa-si dovedeasca pregatirea trupeasca, mintala si spirituala.",al={"de ce ii ajuta Dorn pe cei din Hoarda","filosofia lui Dorn Plainstalker","incercari Tauren pentru alte rase"}},{q="Care a fost incercarea de dinaintea acesteia?",a="Inainte de a pune la incercare rezistenta trupului, Dorn le cere provocatorilor sa treaca Test of Faith, un salt primejdios al devotiunii, menit sa verifice daca spiritul unui aventurier va ceda in fata fricii.",al={"misiunea anterioara","testul dinaintea rezistentei","prima incercare"}}},fx={["8999be4f"]={q="De ce vrea Dorn Plainstalker sa se faca acest lucru?",a="Dorn Plainstalker considera ca este datoria sa sacra sa-i pregateasca pe tinerii aventurieri pentru primejdiile mortale ale lumii largi. Dupa ce se asigura ca spiritul si credinta ta sunt nevatamate, insista sa-ti puna la incercare trupul. Silindu-te sa induri val dupa val de harpii furioase, tocmai in inima teritoriului lor, se asigura ca ai rezistenta si hotararea necesare pentru a supravietui dincolo de siguranta caminului.",al={"de ce imi testeaza dorn rezistenta","motivul lui dorn plainstalker","scopul testului de rezistenta"}},b2efd71b={q="La ce foloseste Grenka's Claw?",a="Gheara este o dovada de netagaduit ca ti-ai tinut pozitia in inima lui Roguefeather Den, ai supravietuit atacului sustinut al harpiilor si ai rapus-o pe fioroasa lor matriarha, Grenka Bloodscreech. Dorn are nevoie de ea pentru a se asigura ca ai rezistat asaltului neincetat, inainte de a-ti incredinta urmatoarea incercare.",al={"utilizarea ghearei lui Grenka","de ce am nevoie de gheara lui Grenka","scopul ghearei lui Grenka"}},["28ecd26a"]={q="Cine este Grenka Bloodscreech?",a="Grenka Bloodscreech este o conducatoare redutabila printre harpiile Roguefeather care infesteaza pesterile canionului de la vest de Freewind Post. Ferma si extrem de teritoriala, ea stapaneste sanctuarul interior al stolului. Cand te napustesti in adancurile Roguefeather Den si le distrugi proviziile stranse, furia ei o face sa coboare din cuib ca sa te ucida cu propriile maini.",al={"cine este Grenka","povestea lui Grenka Bloodscreech","conducatoarea harpiilor Roguefeather"}}},fp="17,345,16.431.0,31.455.0,32.132.0,34.208.0,38.210.0,39.169.0,49.240.0,35.197.0"}
P.entries["quest:1151"] = {n="Test of Strength",s="Test of Strength este a treia proba supravegheata de misticul tauren Dorn Plainstalker in Thousand Needles. Pentru a-si dovedi forta fizica, campionii Hordei trebuie sa-l vaneze pe Rok'Alim the Pounder, un stravechi elementar de piatra care rataceste liber, si sa se intoarca cu ramasitele trupului sau zdrobit.",h="Test of Strength este a treia proba supravegheata de misticul tauren Dorn Plainstalker in Thousand Needles.",kw={"dorn plainstalker","zeii vechi","elemental de piatra","rok'alim","proba fortei","zdrobitorul","thousand needles","weathered nook"},ang={["class:Shaman"]="Shamanii il recunosc pe Rok'Alim nu doar ca pe un obstacol, ci si ca pe o manifestare periculoasa si neimblanzita a pamantului, a carei neclintire tulbura echilibrul local al spiritelor.",["faction:Horde"]="Indeplinirea ritualurilor din Weathered Nook castiga respectul batranilor din Thunder Bluff si consolideaza reputatia unui aventurier in tot Kalimdorul.",["race:Tauren"]="Pentru pelerinii tauren, infruntarea unui spirit neimblanzit al pietrei este o incercare traditionala de armonie si vointa fizica, demonstrand capacitatea vanatorului de a indura si de a invinge cele mai aspre forte ale Earth Mother."},sec={{t="Ramasitele Epocii Old Gods",b="Cu mult timp in urma, in timpul domniei Old Gods, elementalii primordiali acopereau suprafata lumii si le slujeau stapanilor lor intunecati. Cand acele entitati stravechi au fost rasturnate si pecetluite sub pamant, spiritele elementale si-au pierdut legatura cu acest taram si au disparut aproape cu totul din lumea fizica, daca nu erau legate si invocate prin vrajitorie moderna. Totusi, cateva entitati au fost suficient de indaratnice si puternice pentru a ramane pe Azeroth la nesfarsit, fara ancore magice. Rok'Alim the Pounder este o astfel de relicva, ratacind prin canioanele aride din Thousand Needles ca un ecou viu al acelei epoci primordiale."},{t="Strivitorul din Thousand Needles",b="Clanurile locale de centauri i-au dat lui Rok'Alim porecla sa din cauza bubuiturilor asurzitoare, asemenea unor cutremure, produse cand pumnii sai de piatra lovesc fundul canionului. Oricine este destul de nesabuit sau indraznet incat sa-i intre in cale este facut pulbere. Fiindca Rok'Alim intruchipeaza masa fizica pura si nestapanita, Dorn Plainstalker le porunceste initiatilor sa doboare fiara, ca masura directa a spiritului lor razboinic, cerandu-le fragmente din inima de piatra a elementalului drept dovada a victoriei."}},faq={{q="Unde incepe si unde se incheie aceasta misiune?",a="Misiunea este oferita si incheiata de Dorn Plainstalker, un batran tauren stationat la Weathered Nook, o tabara izolata intr-un canion, sus printre piscurile din Thousand Needles.",al={"cel care ofera misiunea","unde predau misiunea","locatia lui dorn"}},{q="Ce este Rok'Alim the Pounder?",a="Rok'Alim este un stravechi elementar de piatra, care a dainuit in Kalimdor inca din era Old Gods. Spre deosebire de elementarii moderni invocati, el are suficienta putere innascuta pentru a ramane manifestat fizic in Azeroth de unul singur.",al={"cine este Rokalim","ce fel de creatura este Rokalim","poveste despre elementali"}},{q="De ce il numesc centaurii 'Zdrobitorul'?",a="Triburile de centauri din canion l-au poreclit Pounder datorita undelor de soc puternice, asemenea unor tunete, pe care le provoaca pumnii sai de piatra cand zdrobeste tot ce-i sta in cale.",al={"porecla Pounder","numele centaurului pentru Rokalim"}},{q="Unde poate fi gasit Rok'Alim in canion?",a="Rok'Alim rataceste prin tinuturile nord-vestice din Thousand Needles, patruland de obicei pe terenul deschis de la sud de drumul principal care strabate fundul canionului.",al={"aparitia lui rokalim","unde este rokalim"}},{q="Ce loc ocupa aceasta misiune in lantul general al incercarilor?",a="Test of Strength este a treia incercare din serie. Urmeaza dupa Test of Faith si Test of Endurance si preceda direct ultima incercare, Test of Lore.",al={"ordinea lantului de misiuni","ce urmeaza","ce vine inainte"}},{q="De ce cere Dorn sa ucizi un elementar si nu o bestie sau un dusman?",a="Dorn il alege pe Rok'Alim fiindca elementalul este o intruchipare pura a pietrei vii si a fortei primordiale, neclintite. Infrangerea unui asemenea adversar dovedeste superioritatea fizica asupra pamantului insusi, brut si neinduplecat.",al={"de ce sa omori un elementar","scopul testului de forta"}}},fx={d3b1c16f={q="De ce vrea Dorn Plainstalker sa se faca acest lucru?",a="Dorn Plainstalker te supune unui ritual tauren stravechi, pentru a-ti pune vitejia la incercare inainte de a trece la incercarile finale. Infruntarea unei simple fiare sau a unui soldat nu ti-ar masura cu adevarat puterea, asa ca iti cere sa provoci o ramasita straveche de piatra primordiala. Uciderea lui Rok'Alim dovedeste ca puterea ta launtrica si cea fizica pot invinge chiar si forte elementale stravechi.",al={"motivul lui dorn plainstalker","de ce vrea dorn sa-l ucida pe rokalim","de ce sa dai proba de forta"}},["67dd1d0a"]={q="La ce folosesc Fragments of Rok'Alim?",a="Fragmentele sunt dovada incontestabila ca l-ai infruntat pe Rok'Alim the Pounder si ai facut bucati stravechiul elementar. Dorn Plainstalker are nevoie de o dovada palpabila a victoriei tale, pentru a recunoaste ca ai trecut Test of Strength si ai castigat dreptul de a trece la urmatoarea proba.",al={"fragmente din rokalim","la ce folosesc fragmentele","de ce sa aduni fragmentele rokalim"}}},fp="16,300,29.589.0,31.471.0,36.178.0,29.226.0,42.161.0,42.156.0,59.162.0,75.211.0"}
P.entries["quest:1152"] = {n="Test of Lore",s="Dupa incercarile de credinta, rezistenta si putere din Thousand Needles, Dorn Plainstalker ii indruma pe campionii Horde spre nord, catre Stonetalon Mountains. Acolo, un shaman intelept pe nume Braug Dimspirit ii asteapta pentru a le da Test of Lore. Incercarea muta accentul de la hotararea fizica la intelegerea istoriei profunde a lumii si a suferintei raspandite pretutindeni.",h="Dupa incercarile de credinta, rezistenta si putere din Thousand Needles, Dorn Plainstalker ii indruma pe...",kw={"Braug Dimspirit","Dorn Plainstalker","Stonetalon Mountains","Talondeep Path","Test of Lore","Thousand Needles","Weathered Nook","Windshear Crag"},ang={["class:Shaman"]="Braug Dimspirit intruchipeaza viziunea samanica asupra lumii, care citeste suferinta pamantului in faptele nechibzuite ale muritorilor, de la exploatarea goblina pana la izolarea elfilor stravechi.",["faction:Horde"]="Proba lui Braug ii obliga pe campionii Horde sa reflecteze sincer asupra reputatiei propriilor aliati, amintindu-le ca nici orcii, nici Forsaken nu sunt singurii vinovati pentru necazurile tinutului.",["race:Tauren"]="Incercarile intruchipeaza filozofiile traditionale tauren, punand armonia spirituala si intelegerea istoriei mai presus de setea nestavilita de sange."},sec={{t="De la credinta la legende",b="In refugiul ferit din Weathered Nook, Dorn Plainstalker isi supune initiatii unor probe dificile, menite sa le testeze convingerile spirituale, rezistenta fizica si iscusinta martiala. Totusi, forta bruta si credinta oarba nu sunt suficiente pentru a deveni un adevarat campion al Hordei. Dorn isi cunoaste limitele de dascal si-i trimite pe cei care si-au dovedit valoarea in Stonetalon Mountains, unde un saman batran le poate pune la incercare mintea si cunoasterea lumii."},{t="Drumul spre Stonetalon",b="Calatoria ii poarta pe drumeti spre nord, traversand tufarisurile uscate din Barrens si ajungand in crestele din Stonetalon. Sus, in munti, langa intrarea in Talondeep Path - caverna care strapunge stanca spre Ashenvale - se afla schitul lui Braug Dimspirit. El vegheaza asupra unei frontiere aflate sub asediu, unde exploatarile forestiere ale goblinilor devasteaza padurile, iar Night Elves ostili isi apara cu inversunare tinuturile stramosesti."},{t="O perspectiva mai larga",b="Dupa intalnirea cu Braug, adevaratul scop al probei devine limpede. In loc sa ceara o mandrie oarba fata de factiune, Braug reflecteaza asupra starii tragice a Azerothului. El observa ca, desi orcii si cei din Forsaken sunt invinuiti fara incetare pentru razboi si coruptie, aproape fiecare civilizatie este raspunzatoare pentru starea pamantului. Goblinii doboara copaci stravechi, iar night elves privesc cu profunda neincredere rasele mai tinere. Test of Lore cere ca un campion sa priveasca dincolo de dusmaniile imediate si sa inteleaga istoria mai ampla a unei lumi ranite."}},faq={{q="Ce este Test of Lore?",a="Este o incercare de instruire din cadrul unui rit de trecere mai amplu, conceput de batranii tauren. Initiatii trebuie sa dovedeasca nu doar ca au forta fizica si credinta, ci si ca sunt constienti de istorie si inteleg trecutul comun al Azerothului.",al={"semnificatia Test of Lore","ce este aceasta misiune"}},{q="Unde il pot gasi pe Braug Dimspirit?",a="Braug Dimspirit locuieste in Stonetalon Mountains, langa Windshear Crag, chiar la intrarea in pestera Talondeep Path, care leaga Stonetalon de Ashenvale.",al={"locatia lui braug dimspirit","unde se afla braug"}},{q="De ce te trimite Dorn Plainstalker departe?",a="Dorn supravegheaza probele de credinta, rezistenta si forta din Thousand Needles, dar recunoaste ca nu se pricepe sa predea intelepciunea lumii. Ii indruma pe initiatii vrednici catre Braug, un saman cu intelepciunea necesara pentru a le pune mintea la incercare.",al={"de ce stonetalon","de ce te trimite dorn"}},{q="De ce pericole ar trebui sa se fereasca calatorii pe drum?",a="Dorn avertizeaza in mod special ca elfii noptii pandesc tinuturile de granita din apropiere de Ashenvale si Stonetalon, considerand prezenta Horde o intruziune. Zona inconjuratoare din Windshear Crag este, de asemenea, plina de exploatari forestiere gobline instabile.",al={"pericole pentru braug","pericol pe Talondeep Path"}},{q="Ce parere are Braug Dimspirit despre conflictele lumii?",a="Braug crede ca toate rasele muritoare sunt vinovate de suferintele lumii. Desi orcii si Forsaken sunt adesea demonizati de rivalii lor, el atrage atentia ca lacomia goblinilor si aroganta elfilor noptii au facut la fel de mult rau in Kalimdor si Lordaeron.",al={"filosofia lui braug dimspirit","in ce crede braug"}},{q="Ce este Talondeep Path?",a="Talondeep Path este un sistem important de tuneluri montane care leaga Windshear Crag din Stonetalon Mountains de vechile hotare impadurite ale sudului Ashenvale.",al={"ce este Talondeep Path","pestera Talondeep"}}},fp="12,353,18.452.0,22.411.0,21.539.1,25.238.0,33.169.0,41.239.0,54.226.0,56.254.0,27.160.0"}
P.entries["quest:1153"] = {n="A New Ore Sample"}
P.entries["quest:1154"] = {n="Test of Lore",s="Test of Lore este o incercare stabilita de Braug Dimspirit la intrarea in Talondeep Path, care pune la incercare mintea unui aventurier Horde, nu rezistenta sa fizica. Pentru a trece, cel care o sustine trebuie sa se aventureze adanc in criptele bantuite din Ashenvale, sa recupereze un tom stravechi despre istoria dragonilor si sa-i studieze continutul inainte de a fi chestionat.",h="Test of Lore este o incercare stabilita de Braug Dimspirit la intrarea in Talondeep Path, care pune la...",kw={"ashenvale","braug dimspirit","camp taurajo","deathwing","barlogul dor'danil","dorn plainstalker","legacy of the aspects","talondeep path","test of lore"},ang={["class:Druid"]="Calatorii Druid care patrund in Dor'Danil Barrow Den sunt pusi fata in fata cu tragedia fratilor Night Elf corupti si ucisi, care odinioara dormeau in comuniune cu Emerald Dream.",["faction:Horde"]="Proba reflecta nevoia Horde de razboinici capabili sa inteleaga istoria straveche a Kalimdor si sa strabata ruinele elfe primejdioase din Ashenvale fara sa cada prada ignorantei."},sec={{t="O schimbare in incercari",b="Dupa ce isi dovedesc rezistenta fizica si credinta de nezdruncinat pe salinele si platourile din Thousand Needles, candidatii supusi seriei de incercari a lui Dorn Plainstalker sunt trimisi spre nord, la Braug Dimspirit, in Stonetalon Mountains. Aflat langa gura de acces a Talondeep Path, Braug respinge incercarile de mai inainte, socotindu-le simple exercitii fizice. Pentru a sluji Horde cu adevarat si a se distinge, un aventurier are nevoie de o minte agera si disciplinata, pregatita sa inteleaga istoriile antice, nu doar sa doboare fiare."},{t="Umbrele din Dor'Danil",b="Braug ii indruma pe solicitanti sa strabata Talondeep Path si sa patrunda in padurile din sudul Ashenvale. Acolo, ascuns sub coronament, la sud de Splintertree Post, se afla Dor'Danil Barrow Den. Sanctuarul subteran este o ruina primejdioasa, bantuita de druizi night elf cazuti si de creaturile feroce care i-au macelarit. Pe un podium de piatra, adanc in incaperile de jos, se afla premiul: 'Legacy of the Aspects', un manuscris rar care descrie crearea si coruperea straveche a marilor Dragon Aspects."},{t="Invata sau sufera",b="Obtinerea tomului este doar jumatate din incercarea lui Braug. Inainte de a inmana volumul, cel care il cauta trebuie sa-i invete pe de rost invataturile. Braug ia imediat cartea dupa ce i-o aduc si ii verifica memoria solicitantului cu privire la aparatorii inzestrati cu puterea Titan si la tradarea cataclismica din care s-a nascut Deathwing. Cei care nu au invatat sau dau raspunsuri gresite sunt alungati pe neasteptate peste Kalimdor, la Camp Taurajo, in sudul Barrens, fiind siliti sa se intoarca la Stonetalon in dizgratie."}},faq={{q="Cine este Braug Dimspirit?",a="Braug Dimspirit este un saman tauren in varsta, aflat in apropierea intrarii in Talondeep Path, in Stonetalon Mountains. El serveste drept examinator dupa incercarile anterioare ale lui Dorn Plainstalker, verificand daca campionii Horde au intelectul si cunostintele necesare pentru a-si completa priceperea martiala bruta.",al={"Braug Dimspirit","cine da misiunea Test of Lore","cel care da misiuni in Stonetalon"}},{q="Unde se afla cartea Legacy of the Aspects?",a="Cartea se afla in Dor'Danil Barrow Den, in sudul Ashenvale, aproape exact la sud de Splintertree Post. Este asezata pe un podium de piatra, pe o platforma centrala, in adancurile subterane ale tumulilor.",al={"locatia Legacy of the Aspects","unde se afla cartea","locatia cartii din Dor'Danil"}},{q="Ce se ascunde in Dor'Danil Barrow Den?",a="Cotlonul din tumul a fost candva un sanctuar pentru druizii elfi ai noptii, dar in adancurile sale s-a petrecut o tragedie. Acum este napadit de spiritele neodihnite ale druidilor morti si de invadatorii letali care i-au macelarit, formand un labirint ucigas pentru orice intrus.",al={"dusmanii din dor danil","cine pazeste cartea","barlogul din ashenvale"}},{q="De ce ma pune Braug sa citesc cartea inainte sa o predau?",a="Braug ia cartea cand i-o returnezi si iti testeaza memoria. Se asteapta sa fi studiat dinainte, fiindca proba iti masoara cunostintele, nu doar capacitatea de a recupera un obiect.",al={"de ce sa citesti Legacy of Aspects","testul Test of Lore","ce se intampla daca raspund gresit la intrebare"}},{q="Cum se incadreaza aceasta misiune in seria mai ampla de incercari?",a="Aceasta incercare urmeaza dupa Test of Faith, initiata de Dorn Plainstalker la Weathered Nook din Thousand Needles. In timp ce Dorn ti-a pus la incercare curajul si capacitatea de a supravietui in fata unor primejdii mortale, Braug iti evalueaza cunostintele si intelegerea istoriei.",al={"lantul de misiuni test of faith","ce misiune preceda test of lore","incercarile lui dorn plainstalker"}},{q="Despre ce este Legacy of the Aspects?",a="Manuscrisul consemneaza istoria mitica a Titanilor, care i-au inzestrat pe cei cinci mari Dragon Aspects pentru a pazi Azeroth. In mod esential, vorbeste despre caderea lui Neltharion the Earth-Warder si transformarea sa in distrugatorul monstruos cunoscut drept Deathwing.",al={"povestea Legacy of the Aspects","istoria cartii","despre ce este cartea"}}},fx={["0efda427"]={q="De ce imi cere Braug Dimspirit sa gasesc Legacy of the Aspects?",a="Braug Dimspirit iti pune la incercare mintea, nu forta. Dupa ce ai indurat deja probele fizice ale lui Dorn Plainstalker, acum esti judecat dupa intelect, ingeniozitate si dorinta de a invata. Trimitandu-te singur pe un teritoriu periculos pentru a recupera si asimila cunostinte stravechi, Braug stabileste daca ai intelepciunea necesara pentru a duce la bun sfarsit seria de probe.",al={"de ce ma testeaza braug","de ce legacy of the aspects","de ce ma testeaza braug dimspirit"}}},fp="12,326,21.528.0,24.518.0,15.477.1,23.306.0,48.223.0,39.236.0,58.180.1,54.232.0,56.260.0"}
P.entries["quest:1159"] = {n="Test of Lore",s="Aceasta etapa din Test of Lore ii trimite pe aventurierii Hordei peste Great Sea, catre ruinele din Lordaeron. Dupa ce ai raspuns la prima ghicitoare a lui Braug Dimspirit in Stonetalon Mountains, esti indrumat sa cauti un fost savant din rasa Human printre Forsaken din Undercity.",h="Aceasta etapa din Test of Lore ii trimite pe aventurierii Hordei peste Great Sea, catre ruinele din Lordaeron.",kw={"Apothecarium","Braug Dimspirit","Dorn Plainstalker","Lordaeron","Parqual Fintallas","Test of Lore","Thousand Needles","Undercity","Weathered Nook"},ang={["faction:Horde"]="Aceasta misiune demonstreaza cooperarea dintre continente care uneste noua Horde, punandu-i laolalta pe cautatorii de intelepciune tauren si pe arhivarii sumbri din Lordaeron.",["race:Tauren"]="Pentru un initiat tauren, sa paraseasca campiile deschise si platourile inalte din Kalimdor pentru a strabate canalele otravitoare si claustrofobice din Undercity face ca aceasta calatorie sa fie deopotriva o incercare culturala si una istorica.",["race:Undead"]="Intalnirea cu Parqual arata ca, in ciuda putreziciunii si a strigoiului, invatati Forsaken precum el au pastrat vastele traditii academice si arhivele regatului cazut Lordaeron."},sec={{t="O Alliance savanta",b="Dupa ce iti dovedesti curajul si dezlegi istoria Dragon Aspects, consemnata in Legacy of the Aspects, Braug Dimspirit recunoaste ca si cunostintele sale au limite. In loc sa limiteze incercarea la Kalimdor, Braug iti dezvaluie cat de departe si de surprinzator se intind legaturile Horde, indreptandu-te spre capitala strigoilor, aflata sub ruinele Lordaeron."},{t="Istoricul sceptic",b="Pe coridoarele umede ale Apothecarium locuieste Parqual Fintallas. Odinioara un cronicar uman de seama al regatelor nordice, Parqual si-a pastrat setea de cunoastere dupa ce a supravietuit lui Scourge si s-a transformat in Forsaken. Cand se confrunta cu un strain care pretinde ca a trecut probele spirituale si fizice din Thousand Needles, Parqual refuza sa creada ca esti altceva decat un mercenar oportunist, pana cand ii dovedesti direct ca esti demn."}},faq={{q="De ce o proba Tauren ma trimite tocmai pana la Undercity?",a="Braug Dimspirit recunoaste ca adevarata stapanire a cunostintelor se extinde dincolo de istoria Kalimdor. El te indruma catre Parqual Fintallas, un savant Human renumit, ale carui cunostinte au supravietuit caderii Lordaeron si transformarii sale in Undead, pentru a-ti pune la incercare intelegerea istoriei mai vaste a lumii.",al={"de ce sa merg la Undercity","de ce Lordaeron","Braug te trimite la Forsaken"}},{q="Unde se afla mai exact Parqual Fintallas?",a="Parqual Fintallas locuieste in Undercity, mai exact langa podul sudic din cartierul Apothecarium.",al={"unde se afla parqual","locatia lui parqual","gaseste-l pe fintallas"}},{q="Cine a fost Parqual Fintallas in viata?",a="In viata, Parqual Fintallas a fost un istoric Human iscusit din regatul Lordaeron. Dupa ce a cazut prada Plague of Undeath si s-a alaturat celor Forsaken ai lui Sylvanas, si-a continuat preocuparile academice, indreptandu-si intelectul spre alte cercetari, mai sumbre.",al={"povestea lui Parqual Fintallas","cine este Parqual","povestea lui Fintallas"}},{q="De ce nu crede Parqual ca m-a trimis Braug?",a="Parqual este foarte neincrezator fata de straini. I se pare de necrezut ca un aventurier obisnuit ar putea sari de pe piscurile din Thousand Needles, invinge elementali primordiali si recupera relicve stravechi, presupunand in schimb ca doar ai auzit zvonuri intr-o carciuma.",al={"de ce e Parqual nepoliticos","reactia lui Parqual","Parqual nu ma crede"}},{q="Din ce incercare mai ampla face parte aceasta misiune?",a="Aceasta misiune este etapa de mijloc a lantului Test of Lore, care a evoluat din proba initiata de Dorn Plainstalker la Weathered Nook. Ea evalueaza daca initiatul are nu doar pricepere in lupta si curaj, ci si inteligenta si cunoasterea istoriei demne de un campion al Horde.",al={"ce lant este acesta","lantul Test of Faith","ce este Test of Lore"}},{q="Ce urmeaza dupa ce ajungi la Parqual?",a="Inainte ca Parqual sa se invredniceasca sa-ti puna propria ghicitoare istorica, iti cere sa indeplinesti o sarcina in numele lui in Eastern Kingdoms, pentru a verifica daca esti cu adevarat eroul capabil pe care il lauda Braug.",al={"ce urmeaza dupa parqual","misiunea urmatoare dupa undercity","dupa ce vorbesti cu fintallas"}}},fx={["670eb265"]={q="De ce te trimite Braug Dimspirit la Undercity?",a="Braug Dimspirit ti-a pus la incercare cunostintele de baza, dar rolul sau este doar sa te indrume in prima etapa a Test of Lore. Pentru a-ti incerca cu adevarat intelegerea lumii, el stie ca urmatoarea intrebare cere o perspectiva diferita de a sa. Te trimite la Parqual Fintallas - un istoric vestit din Lordaeron, devenit Forsaken - pentru ca devotamentul tau fata de istorie si adevar sa fie judecat de un invatat care cauta iluminarea intr-un mod cu totul diferit.",al={"de ce ma trimite Braug","motivul lui Braug Dimspirit","de ce sa merg la Undercity la cererea lui Braug"}}},fp="12,263,20.359.0,23.461.0,57.270.0,43.120.0,34.266.0,42.255.0,40.295.0,39.206.0"}
P.entries["quest:116"] = {n="Dry Times",s="Dry Times este o sarcina data de Barkeep Daniels de la Lakeshire pentru a reaproviziona hanul orasului cu bauturi alcoolice in timpul unui asediu in desfasurare. Cum invazia orcilor Blackrock a intrerupt rutele comerciale, Daniels se bazeaza pe curieri aventurosi care sa aduca bauturi deosebite din tinuturile Stormwind.",h="Dry Times este o sarcina data de Barkeep Daniels de la Lakeshire pentru a reaproviziona hanul orasului cu...",kw={"Barkeep Daniels","vremuri de seceta","Grimbooze Thunderbrew","Lakeshire","merlot","rachiu","Redridge","rom dulce","bere Thunderbrew"},ang={["faction:Alliance"]="Aceasta insarcinare ilustreaza felul in care degradarea securitatii drumurilor din Redridge afecteaza viata de zi cu zi, obligand curierii Alliance sa refaca rutele comerciale intrerupte dintre Stormwind, Elwynn, Westfall, Duskwood si Redridge.",["race:Dwarf"]="Chiar si in timpul unei invazii Orc, tavernele Human se bazeaza pe priceperea piticilor in arta berii, trimitand soli pana in Westfall pentru a procura lagerul renumit al lui Grimbooze Thunderbrew."},sec={{t="Un oras sub asediu",b="Lakeshire se afla pe linia frontului unei ofensive agresive a orcs din Blackrock clan, care coboara din Stonewatch Keep. Cu liniile obisnuite de aprovizionare blocate si drumurile nesigure, hangiul local, Barkeep Daniels, se confrunta cu o criza iminenta a butoaielor goale. Pentru a mentine moralul satenilor speriati si al garzilor greu incercate, el apeleaza la calatori din afara care sa ocoleasca blocadele de pe drumuri si sa-i umple din nou rafturile."},{t="Un mare tur al regatului",b="Aprovizionarea pivnitei lui Daniels nu e o simpla livrare; necesita o calatorie ambitioasa prin tot regatul Stormwind. Un curier trebuie sa faca rost de un butoi de Merlot chiar din capitala, de rom dulce de la Lion's Pride Inn din Goldshire, de rachiu puternic din Darkshire, posomoratul orasel din Duskwood, si de un butoias special de Thunderbrew Lager, produs de Grimbooze Thunderbrew in colinele din Westfall."}},faq={{q="De ce ramane Lakeshire fara alcool?",a="Invazia orcilor Blackrock in Redridge a dat complet peste cap comertul obisnuit si caravanele de aprovizionare. Livrarile obisnuite ale lui Barkeep Daniels intarzie de mult, amenintand sa-i lase taverna complet fara bautura, in timp ce orasul se afla sub o presiune uriasa din cauza razboiului.",al={"de ce e seceta","de ce nu este bautura in Lakeshire","problema lui Barkeep Daniels"}},{q="Unde gasesc toate bauturile de care are nevoie Barkeep Daniels?",a="Trebuie sa aduni patru obiecte din tot regatul: Merlot de la tavernele din Stormwind City, Sweet Rum din Goldshire, in Elwynn Forest, Moonshine din Darkshire, in Duskwood, si un butoi de Thunderbrew Lager de la Grimbooze Thunderbrew, in dealurile din Westfall.",al={"locatii de bauturi pentru Dry Times","de unde cumpar merlot, moonshine si rom","de unde iau bauturi pentru daniels"}},{q="Cine este Grimbooze Thunderbrew?",a="Grimbooze Thunderbrew este un berar pitic care locuieste pe dealurile din Westfall. Barkeep Daniels considera Thunderbrew Lager o rezerva esentiala, insa pentru a o obtine trebuie sa indeplinesti o treaba separata pentru Grimbooze si sa-i faci rost de un butoi proaspat.",al={"locatia lui Grimbooze","unde se afla Grimbooze Thunderbrew","Thunderbrew din Westfall"}},{q="Cine este Barkeep Daniels?",a="Daniels este hangiul din Lakeshire. Disperat sa-si mentina taverna aprovizionata si clientii potoliti in fata amenintarii iminente a orcilor Blackrock, angajeaza calatori sa recupereze personal proviziile.",al={"Barkeep Daniels","hangiul din Lakeshire","cine ofera Dry Times"}},{q="De ce are Daniels nevoie de bauturi din atat de multe regiuni diferite?",a="Daniels are o clientela variata, de la refugiati si membri ai militiei locale pana la aventurieri aflati in trecere; de aceea are nevoie de o gama larga de produse, de la bere blonda piticeasca la vin fin din capitala si bauturi spirtoase tari din Duskwood si Elwynn.",al={"de ce atatea bauturi","de ce sa vizitezi duskwood si westfall"}},{q="Ce recompensa ofera Barkeep Daniels pentru cursa?",a="Pe langa faptul ca iti ramburseaza cheltuielile de calatorie cu o punga de monede, Daniels iti ofera drept multumire o mantie cusuta de mana de sotia sa, pentru ca ai infruntat drumurile disputate ale tinutului.",al={"recompensa pentru Dry Times","ce ofera daniels"}}},fx={["266c2dd6"]={q="De ce are Barkeep Daniels nevoie de ajutorul tau ca sa aduca bauturi?",a="Daniels nu-si poate lasa taverna nesupravegheata, mai ales cu Lakeshire in pragul nelinistii si clientii disperati dupa o bautura care sa-i faca sa-si uite necazurile. Intre timp, garzile locale si militia orasului sunt cu totul ocupate sa respinga invazia orcilor Blackrock care coboara dinspre nord. Numai un aventurier hoinar are libertatea de a strabate in siguranta drumurile primejdioase ale regatului pentru a aduna provizii.",al={"de ce eu in dry times","de ce are daniels nevoie de un aventurier","de ce ma trimite dupa bauturi"}},["8f4cd8c5"]={q="La ce foloseste Butoiul de Thunderbrew?",a="Butoiul contine Thunderbrew Lager, o bere tare produsa de Grimbooze Thunderbrew in tinuturile deluroase din Westfall. Barkeep Daniels are nevoie de ea pentru a reface proviziile pe terminate din pivnitele Lakeshire, oferindu-le localnicilor infricosati si aparatorilor hartuiti o bere bruna zdravana de pitici, care sa le ridice moralul in fata amenintarii Blackrock.",al={"butoi de bere Thunderbrew","de ce butoi de bere Thunderbrew","la ce foloseste lagerul Thunderbrew"}},["0ca5cd6a"]={q="La ce foloseste Skin of Sweet Rum?",a="Burduful acesta cu rom dulce provine chiar de la Lion's Pride Inn din Goldshire. Daniels il include in goana sa dupa bautura pentru urgente, ca sa satisfaca gustul clientilor pentru licori mai dulci, in timp ce orcii au intrerupt liniile obisnuite de aprovizionare ale orasului.",al={"burduf de rom dulce pentru perioadele secetoase","de ce rom dulce","la ce foloseste romul dulce"}},["41f763cb"]={q="La ce foloseste Cask of Merlot?",a="Acest butoi cu vin rosu de calitate, adus din inima Stormwind City, ofera o farama de confort civilizat in mijlocul razboiului sumbru de la frontiera. Daniels are nevoie de el pentru ca pivnita tavernei sale sa nu ramana complet fara vin cat timp drumurile sunt asediate.",al={"butoiul de Merlot seaca","de ce butoi de Merlot","la ce foloseste Merlot"}},["88b6ac2e"]={q="La ce foloseste Bottle of Moonshine?",a="Fabricata in catunul intunecat din Darkshire, aceasta sticla de Moonshine aspra ofera o lovitura puternica si neprelucrata. Barkeep Daniels o aduce pentru clientii care au nevoie de ceva neobisnuit de tare, ca sa-si linisteasca nervii in fata amenintarii constante a invaziei.",al={"sticla de moonshine din dry times","de ce sticla de moonshine","la ce foloseste moonshine"}}},fp="9,277,18.416.0,27.398.0,40.246.0,53.260.0,29.231.0,23.215.0,60.225.0,57.181.0"}
P.entries["quest:1166"] = {n="Overlord Mok'Morokk's Concern",s="Overlord Mok'Morokk din clanul Stonemaul se afla in Brackenwall Village si isi vrea inapoi grogul, tutunul de prizat si caseta de valori. Le-a lasat in urma in graba, la vechea locuinta a clanului, si te trimite spre sud sa le gasesti.",h="Overlord Mok'Morokk din clanul Stonemaul se afla in Brackenwall Village si isi vrea inapoi grogul, tutunul de...",kw={"brackenwall","den of flame","dustwallow","grog","mok'morokk","rexxar","tutun","stonemaul","caseta incuiata"},sec={{t="Povestea suzeranului",b="Mok'Morokk spune ca Rexxar l-a facut puternicul conducator al clanului Stonemaul si ca isi tine oamenii in siguranta. Dupa cum povesteste el, niste dragoni mari au venit in vechea lor asezare si au adus focul, asa ca a gasit clanului o noua casa aici, in Dustwallow."},{t="Lucruri ramase in urma",b="A plecat atat de repede din vechea locuinta, incat si-a uitat lucrurile: grogul, tutunul de prizat si caseta de valori. Iti indica spre sud, catre Den of Flame si Stonemaul Ruins, convins ca se afla acolo. Spune ca este prea ocupat sa-i conduca pe ogri ca sa mearga el insusi."}},faq={{q="Cine este Overlord Mok'Morokk?",a="Overlord Mok'Morokk conduce clanul Stonemaul din Brackenwall Village. Potrivit spuselor lui, Rexxar l-a facut puternicul conducator al clanului.",al={"mok'morokk","conducator ogre","cine este stapanul suprem"}},{q="Ce s-a intamplat cu vechea casa a clanului Stonemaul?",a="Mok'Morokk spune ca niste dragoni uriasi au venit si au dat foc vechii locuinte, asa ca a gasit pentru clan o noua casa la Brackenwall Village.",al={"de ce au plecat ogrii","distrugerea lui stonemaul","dragonii ataca ogrii"}},{q="Ce vrea Mok'Morokk inapoi?",a="Vrea grogul, tabacul de prizat si lada sa de valori, pe care le-a uitat cand a plecat in graba din vechea locuinta.",al={"obiectele lui Mok'Morokk","ce lucruri vrea el","grog tabac lada"}},{q="Unde sunt lucrurile lui Mok'Morokk?",a="Te trimite spre sud si este sigur ca lucrurile se afla in Den of Flame si Stonemaul Ruins.",al={"unde sunt obiectele","locatiile obiectelor","gaseste grog si tutun de prizat"}},{q="De ce nu-si aduce Mok'Morokk singur lucrurile?",a="Spune ca este prea ocupat sa-i conduca pe ogri ca sa mearga sa-i ia.",al={"de ce nu pleaca mok'morokk","de ce ma trimite"}}},fp="29,205,20.226.0,18.248.0,27.132.0,47.122.0,31.101.0,34.94.0,48.60.0"}
P.entries["quest:1167"] = {n="The Tower of Althalaxx"}
P.entries["quest:1168"] = {n="Army of the Black Dragon",s="In Brackenwall Village, ogre-ul Tharg vrea sa se razbune pe armata dragonului negru. Tharg este manios pe Overlord Mok'Morokk fiindca le-a spus ogres sa fuga in loc sa lupte si iti cere sa lovesti in Firemane.",h="In Brackenwall Village, ogre-ul Tharg vrea sa se razbune pe armata dragonului negru.",kw={"Brackenwall","Dustwallow","Firemane","Mok'Morokk","Rexxar","Stonemaul","Tharg"},sec={{t="O nemultumire sangeroasa",b="Black dragons au ucis multi ogres, iar sotia lui Tharg s-a numarat printre cei morti. Mok'Morokk, pe care Rexxar l-a facut Overlord, le-a spus supravietuitorilor sa fuga, asa ca au ajuns in Brackenwall Village. Tharg spune ca ogres nu se pricep la fuga si ar trebui sa lupte, si crede ca lui Mok'Morokk nu-i pasa decat de Mok'Morokk. Tharg mai spune ca Mok'Morokk le porunceste tuturor ogres sa stea pe loc si sa pazeasca locul."},{t="Casa din sud",b="Tharg considera Stonemaul Ruins casa lui si ii place sa stea in sud. Brackenwall Village nu este casa lui. Vrea sa se razbune pe armata dragonilor negri si sa-si recupereze vechea casa, asa ca iti cere sa dobori Firemane Scouts si Firemane Ash Tails din randurile ei."}},faq={{q="Cine este Tharg?",a="Tharg este un ogre care locuieste in Brackenwall Village. Sotia lui a fost ucisa de dragoni negri, iar el vrea sa se razbune si sa se intoarca la Stonemaul Ruins.",al={"povestea lui tharg","cine este tharg","tharg dustwallow"}},{q="De ce nu-l place Tharg pe Overlord Mok'Morokk?",a="Rexxar l-a facut Overlord pe Mok'Morokk, dar Tharg spune ca acestuia ii pasa mai mult de putere decat de ogri. Cand dragonii negri au ucis multi ogri, Mok'Morokk le-a spus celorlalti sa fuga, iar Tharg crede ca ogrii ar trebui sa lupte.",al={"de ce il uraste tharg pe mok morokk","mok'morokk lasul","tharg si mok morokk"}},{q="Ce s-a intamplat cu sotia lui Tharg?",a="Dragonii negri au ucis-o, alaturi de multi alti ogres. De aici izvoraste dorinta lui Tharg de razbunare.",al={"sotia lui tharg","ce s-a intamplat cu sotia lui tharg","sotia lui tharg a murit"}},{q="Unde se afla vechea casa a ogriilor?",a="Tharg considera Stonemaul Ruins casa lui si ii place sa stea in sud. Spune ca Brackenwall Village nu este casa lui si vrea sa se intoarca.",al={"casa ogre din stonemaul","de unde provin ogre","istoria ruinelor stonemaul"}},{q="Ce dusmani alcatuiesc armata dragonului negru?",a="Tharg te indruma spre Firemane, printre care se numara Firemane Scouts si Firemane Ash Tails.",al={"dragonkin Firemane","pe cine sa omori din armata dragonului negru","dusmanii Firemane"}}},fp="24,209,20.382.0,17.261.0,13.143.0,43.199.0,30.98.0,29.129.0,51.84.0"}
P.entries["quest:1169"] = {n="Identifying the Brood",s="In Brackenwall Village, Draz'Zilb il numeste pe Mok'Morokk un nebun las, care se scalda in putere, si spune ca Tharg se zbate intre durere si razbunare, incercand sa ajunga conducatorul clanului. Draz'Zilb crede ca nimeni altcineva nu-si da silinta sa afle cine a atacat vechea locuinta si iti cere cincisprezece limbi dogoritoare si cincisprezece inimi dogoritoare.",h="In Brackenwall Village, Draz'Zilb il numeste pe Mok'Morokk un nebun las, care se scalda in putere, si spune...",kw={"black dragon","brackenwall village","draz'zilb","dustwallow marsh","mok'morokk","inimi arzande","limbi arzande","stonemaul","tharg"},sec={{t="O voce a ratiunii",b="Draz'Zilb spune ca Mok'Morokk se lafaieste in putere, in timp ce Tharg se lupta cu durerea si setea de razbunare, asa ca, dupa cum povesteste Draz'Zilb, nimanui altcuiva nu-i pasa cine se afla in spatele agresiunii impotriva vechii patrii. Draz'Zilb remarca faptul ca poate te asteptai ca un ogre sa vorbeasca precum o bruta."},{t="Inimi si limbi",b="Draz'Zilb vrea sa i se aduca limbi si inimi, cate cincisprezece de la pui si pui abia iesiti din ou, pentru a descoperi originea raului. Analizand puii arsi ai armatei dragonilor negri, Draz'Zilb spera sa afle ce bestie blestemata le-a dat drumul in tinuturile ogrilor. Cunoscandu-si mai bine dusmanul, ogrii ar putea sa-l distruga pentru totdeauna si sa recupereze Stonemaul Village din ruine. Draz'Zilb adauga ca, si asa, va fi o treaba grea sa-l convinga pe Mok'Morokk sa paraseasca mlastina."}},faq={{q="Cine este Draz'Zilb?",a="Draz'Zilb este un ogre din Brackenwall Village care vorbeste intr-un mod formal, nu ca un bataus, si vrea sa afle cine se afla in spatele atacului asupra vechii case a clanului.",al={"drazzilb","mage ogre din Brackenwall","ogru istet"}},{q="Ce vrea Draz'Zilb de la puii abia iesiti din ou si de la cei care inca nu au eclozat?",a="Draz'Zilb vrea cincisprezece limbi incinse si cincisprezece inimi incinse. Acestea ar trebui sa ajute la identificarea bestiei care i-a alungat puii din vechea casa.",al={"folosirea inimilor arzatoare","de ce limbi si inimi","scopul Identifying the Brood"}},{q="Ce parere are Draz'Zilb despre liderii clanului?",a="Draz'Zilb nu are prea mult respect pentru Mok'Morokk, numindu-l pe acel ogre un nebun las, orbit de putere, si vorbeste despre Tharg ca despre cineva coplesit de durere si de dorinta de razbunare.",al={"problema lui mokmorokk","tharg si mokmorokk","conducatorii stonemaul"}}},fp="21,323,17.284.0,18.461.0,17.171.0,56.145.0,48.186.0"}
P.entries["quest:117"] = {n="Thunderbrew",s="In Westfall, Grimbooze Thunderbrew aduna ingredientele necesare pentru urmatoarea sa serie. Hameiul proaspat impiedica berea sa se ingroase ca o tocanita, iar el imparte butoaie cu cei care il ajuta.",h="In Westfall, Grimbooze Thunderbrew aduna ingredientele necesare pentru urmatoarea sa serie.",kw={"bere","fabricarea berii","dwarf","grimbooze","hamei","butoi","lager","thunderbrew","westfall"},ang={["profession:Cooking"]="Ca bucatar, stii ca orzul, maltul si hameiul trebuie sa fie in echilibru, la fel ca ingredientele din berea clasica Dwarf.",["race:Dwarf"]="Ca Dwarf, sa vezi un compatriot pastrand vii traditiile de fabricare a berii din Kharanos pe frontiera aspra din Westfall este o priveliste imbucuratoare, mai ales cand sunt implicate butoaie."},sec={{t="O pasiune piticeasca in Westfall",b="Grimbooze Thunderbrew pastreaza vie traditia familiei sale de berari, departe de Dun Morogh. Chiar si pe campiile framantate din Westfall, insista sa foloseasca ingredientele potrivite: fara hamei de calitate, berea pe care o prepara s-ar putea transforma intr-o tocana groasa in loc de o bere racoritoare."},{t="Arta butoiului",b="Grimbooze lauda hameiul, orzul, drojdia si maltul in rime voioase. Cu hameiul proaspat, incheie pe loc fermentatia. Cei care il aprovizioneaza primesc butoaie intregi de Thunderbrew Lager, o bautura cunoscuta pentru taria gustului sau."}},faq={{q="Cine este Grimbooze Thunderbrew?",a="Grimbooze Thunderbrew este un berar Dwarf care rataceste prin Westfall. Pastreaza traditia beraritului clanului sau oriunde isi aseaza tabara, vorbind si cantand in rime voioase.",al={"Grimbooze","cine este Grimbooze","povestea lui Grimbooze"}},{q="De ce are nevoie Grimbooze de hamei?",a="Fara hamei proaspat, cel mai nou lot al lui Grimbooze ar putea avea un gust gros si greu, ca tocanita, in loc sa fie o bere crocanta. Hameiul da bauturii amareala si echilibru.",al={"de ce hamei","hameiul lui Grimbooze","la ce foloseste hameiul"}},{q="Ce este Thunderbrew Lager?",a="Thunderbrew Lager este o bautura piticeasca tare, facuta de familia Thunderbrew. Grimbooze o imparte la butoi, iar gustul puternic iti izbeste cerul gurii.",al={"bere Thunderbrew","butoi de Thunderbrew","ce este Thunderbrew"}},{q="Poti sa-i aduci hamei lui Grimbooze de mai multe ori?",a="Da. Grimbooze accepta mai multe hameiuri si ofera in schimb butoaie suplimentare din berea sa.",al={"misiune repetabila","se poate repeta thunderbrew","mai multe butoaie"}},{q="Unde se desfasoara aceasta sarcina?",a="Munca are loc in Westfall, unde Grimbooze isi instaleaza tabara si aduna provizii printre terenurile agricole.",al={"locatia thunderbrew","unde este grimbooze","zona misiunii"}},{q="Exista vreo legatura intre Grimbooze si Thunderbrews din Dun Morogh?",a="Da. Grimbooze imparte acelasi nume de familie si aceeasi meserie de berar cu familia Thunderbrew din Kharanos, in Dun Morogh.",al={"distileria Thunderbrew","clanul Grimbooze","familia Thunderbrew"}}},fp="11,173,29.253.0,18.228.0,29.165.0,29.151.0,26.150.0,44.83.0,32.97.0,55.106.0"}
P.entries["quest:1170"] = {n="The Brood of Onyxia",s="Draz'Zilb povesteste despre puietul lui Onyxia care a invadat Stonemaul Village si se intreaba de ce fiica lui Deathwing ar veni pe aceste meleaguri. Esti trimis sa-i duci vestea lui Overlord Mok'Morokk din Brackenwall Village.",h="Draz'Zilb povesteste despre puietul lui Onyxia care a invadat Stonemaul Village si se intreaba de ce fiica...",kw={"brackenwall village","deathwing","draz'zilb","dustwallow marsh","mok'morokk","onyxia","stonemaul"},sec={{t="O prezenta nelinistitoare",b="Satul Stonemaul a fost invadat de odraslele lui Onyxia, iar Draz'Zilb este tulburat de gandul ca fiica lui Deathwing s-ar napusti asupra acestor tinuturi. Draz'Zilb este convins ca Onyxia a venit pentru mai mult decat asedierea catorva ogri si vrea ca Overlord Mok'Morokk sa fie instiintat imediat, in Brackenwall Village, pentru a se putea lua masuri."},{t="Vesti la Brackenwall",b="Mok'Morokk nu primeste vestea cu bucurie. Overlordului nu-i plac dragonii, ii place sa stea in Brackenwall Village si spune ca aici nu sunt dragoni."}},faq={{q="Cine te trimite sa vorbesti cu Overlord Mok'Morokk?",a="Draz'Zilb te trimite dupa ce puii lui Onyxia au invadat Stonemaul Village.",al={"cine incepe Brood of Onyxia","cel care da misiunea Brood of Onyxia"}},{q="Unde poate fi gasit Overlord Mok'Morokk?",a="Il vei gasi pe Overlord Mok'Morokk in Brackenwall Village.",al={"locatia lui mok'morokk","unde este mok'morokk","overlord mok'morokk dustwallow"}},{q="De ce este Draz'Zilb ingrijorat de progenitura lui Onyxia?",a="Draz'Zilb se intreaba de ce fiica lui Deathwing ar veni pe aceste meleaguri si este sigur ca motivul era mai mult decat asedierea unei mici cete de ogri.",al={"de ce ii pasa lui Draz'zilb de dragoni","ingrijorarea lui Draz'zilb cu privire la Onyxia"}}},fp="19,204,20.308.0,19.136.1,48.77.0,39.57.0,48.142.0"}
P.entries["quest:1171"] = {n="The Brood of Onyxia",s="Overlord Mok'Morokk nu vrea sa auda despre dragoni. Spune ca aici nu sunt dragoni negri si te trimite inapoi la Draz'Zilb in Brackenwall Village, cu vestea ca ogrii raman pe loc.",h="Overlord Mok'Morokk nu vrea sa auda despre dragoni.",kw={"brackenwall village","puii lui onyxia","draz'zilb","dustwallow marsh","mok'morokk","rexxar"},sec={{t="Lasa-ma in pace",b="Dupa ce Draz'Zilb a trimis vesti despre puii lui Onyxia, Overlord Mok'Morokk nu vrea decat sa fie lasat in pace. Mok'Morokk spune ca ogrii raman unde sunt, ca aici nu exista niciun dragon negru, apoi iti spune sa mergi sa-i transmiti asta lui Draz'Zilb, in Brackenwall Village."},{t="Ce spune Draz'Zilb",b="Draz'Zilb primeste prost raspunsul si-l numeste pe Overlord un las lenes. Mok'Morokk a dat dovada de putere cat timp Rexxar le-a fost conducator, spune Draz'Zilb, dar, dupa plecarea lui Rexxar, ispitele puterii l-au acaparat. Acum, Mok'Morokk le cere ogrelor sa-l slujeasca, in loc sa le conduca, iar Draz'Zilb spune ca trebuie facut ceva."}},faq={{q="De ce refuza Overlord Mok'Morokk sa actioneze?",a="Mok'Morokk spune ca nu sunt dragoni negri aici si vrea sa fie lasat in pace. Ti se cere sa-i duci vestea lui Draz'Zilb: ogrii raman.",al={"de ce nu ajuta mok'morokk","reactia lui mok'morokk","de ce nu sunt dragoni negri"}},{q="Ce se intampla inaintea acestei parti a povestii?",a="Aceasta urmeaza dupa The Brood of Onyxia, in care Draz'Zilb te-a trimis sa-i dai lui Mok'Morokk vesti despre puiet.",al={"ce urmeaza inaintea acestei misiuni","ordinea lantului de misiuni"}},{q="Unde se petrece?",a="Atat Mok'Morokk, cat si Draz'Zilb se afla in Brackenwall Village.",al={"unde este aceasta misiune","locatie"}}},fp="19,191,14.249.0,19.322.1,43.136.0,40.103.0,27.57.0"}
P.entries["quest:1172"] = {n="The Brood of Onyxia",s="Draz'Zilb din Brackenwall Village nu mai vrea sa eclozeze nici macar un pui de Onyxia. Esti trimis sa gasesti si sa distrugi ouale dragonului negru de langa Wyrmbog, in partea de sud a mlastinii.",h="Draz'Zilb din Brackenwall Village nu mai vrea sa eclozeze nici macar un pui de Onyxia.",kw={"brackenwall","puiul lui onyxia","dragonmurk","draz'zilb","mok'morokk","onyxia","stonemaul","wyrmbog"},sec={{t="Ouale din Wyrmbog",b="Puii lui Onyxia au fost imprastiati prin Dragonmurk. Draz'Zilb indeamna la graba: Wyrmbog se afla in sudul mlastinii, iar Draz'Zilb este sigur ca dragonul si-a facut acolo barlogul, cu ouale raspandite in jurul lui. Cat timp pamantul din jurul satului Stonemaul este loc de cuibarit pentru dragoni, ogrii nu il vor recuceri niciodata, asa ca esti trimis sa gasesti ouale si sa le distrugi."},{t="Un ultim serviciu",b="Dupa ce ouale au fost distruse, Draz'Zilb spune ca va trece ceva timp pana cand Onyxia va putea depune altele si iti multumeste in numele clanului Stonemaul. Apoi Draz'Zilb iti cere inca o favoare. Draz'Zilb il considera pe Mok'Morokk nepotrivit pentru conducere, iar Tharg, care ar fi un conducator excelent, este tinut pe loc de ranile si varsta sa. Ti se cere sa-l alungi cu forta pe Mok'Morokk, ca un nou conducator sa poata readuce clanul la adevarata lui casa, in sud."}},faq={{q="Cine ofera aceasta misiune?",a="Draz'Zilb, din Brackenwall Village, te trimite sa te ocupi de ouale lui Onyxia.",al={"cine ofera misiunea Brood of Onyxia","cine da misiunea Brood of Onyxia","misiunea lui Drazzilb"}},{q="De ce trebuie distruse ouale de dragon?",a="Draz'Zilb nu mai vrea sa eclozeze niciun pui de Onyxia. Desi tinutul din jurul Stonemaul Village este un loc de cuibarit pentru dragoni, ogrii nu il vor recuceri niciodata.",al={"de ce sa distrugi ouale lui Onyxia","de ce sa spargi ouale","oua de dragon in Stonemaul Village"}},{q="Unde se afla ouale?",a="In jurul Wyrmbog, in sudul mlastinii. Draz'Zilb este sigur ca Onyxia si-a facut acolo barlogul.",al={"unde sunt ouale lui onyxia","locatia oului lui onyxia","unde se afla wyrmbog"}},{q="Unde se incadreaza aceasta etapa in lantul mai amplu?",a="Urmeaza dupa ce Mok'Morokk a refuzat sa actioneze la aflarea vestii despre puiet, cand i-ai dus raspunsul inapoi lui Draz'Zilb.",al={"lantul brood of onyxia","misiunea anterioara brood of onyxia","ce vine inainte de brood of onyxia 3"}}},fp="19,188,23.384.0,16.428.1,21.71.0,38.159.0,27.96.0,46.113.0"}
P.entries["quest:1173"] = {n="Challenge Overlord Mok'Morokk",s="Overlord Mok'Morokk iti ia in deradere provocarea, promite sa te zdrobeasca si te invita sa-i spui cand esti gata sa fii facut praf. Draz'Zilb din Brackenwall Village spera sa-l vada pe Mok'Morokk alungat din sat.",h="Overlord Mok'Morokk iti ia in deradere provocarea, promite sa te zdrobeasca si te invita sa-i spui cand esti...",kw={"Brackenwall Village","provoaca-l pe Overlord Mok'Morokk","Draz'zilb","Dustwallow Marsh","Mok'Morokk","Stonemaul"},sec={{t="O provocare pentru Overlord",b="Te apropii de Overlord Mok'Morokk, care rade de indrazneala ta, promite sa te zdrobeasca si iti spune sa vorbesti cand esti gata sa-ti primesti bataia. Aceasta are loc dupa The Brood of Onyxia. Draz'Zilb din Brackenwall Village se asteapta ca Mok'Morokk sa fie alungat din sat si se intreaba de ce te-ai intoarce doar ca sa vorbesti."},{t="Vesti pentru Draz'Zilb",b="Dupa ce lupta este castigata, Draz'Zilb spune ca Mok'Morokk a fugit ca un las si iti multumeste pentru un serviciu important. Cu Mok'Morokk plecat, ogrii pot numi un lider nou, care sa-i ajute sa-si recastige definitiv vechea casa."}},faq={{q="Pe cine provoci?",a="Il provoci pe Overlord Mok'Morokk in Brackenwall Village. Overlordul raspunde razand si laudandu-se ca te va zdrobi.",al={"cu cine ma lupt","tinta provocarii","cine este mok'morokk"}},{q="Ce preceda aceasta provocare?",a="Urmeaza dupa The Brood of Onyxia.",al={"ce misiune vine inainte","misiune premergatoare","misiunea anterioara"}},{q="Cui ii raportezi dupa lupta?",a="Draz'Zilb din Brackenwall Village este cel caruia trebuie sa-i raportezi.",al={"cui predau acest obiect","NPC caruia predau","unde merg dupa ce-l inving pe Mok'Morokk"}},{q="Ce asteapta Draz'Zilb de la tine?",a="Draz'Zilb se asteapta ca Mok'Morokk sa fie alungat din sat si se intreaba de ce te-ai intoarce doar ca sa stai de vorba.",al={"de ce sa te lupti cu Mok'Morokk","de ce sa-l provoci pe stapanul suprem","motivul luptei"}}},fp="29,213,27.314.0,18.219.1,21.120.0,33.31.0,37.57.0,34.110.0"}
P.entries["quest:1174"] = {n="Gnomes Win!",s="In Thousand Needles, un bilet la cursa gnomilor aduce castiguri cand gnomii ies invingatori. Cutia cu premiul ajunge la cel care avea biletul castigator.",h="In Thousand Needles, un bilet la cursa gnomilor aduce castiguri cand gnomii ies invingatori.",kw={"gnome","cutie cu premii gnome","victoria gnomes","curse","thousand needles"},sec={{t="Biletul Gnome",b="Biletul cursei gnome este bonul care conteaza daca gnomes castiga. Pastreaza-l, iar cand se anunta rezultatul, premiul tau va fi o cutie cu premii gnome. Biletul goblin are propriul rezultat, pentru cealalta tabara a cursei."}},faq={{q="Ce este Gnome Race Ticket?",a="Este biletul pentru partea gnomilor a cursei din Thousand Needles. Conteaza atunci cand gnomii castiga.",al={"bilet gnome","ce este biletul cursei gnome","scopul biletului cursei"}},{q="Ce primesti cand castiga gnomii?",a="Cutia cu premiul pentru gnome ii revine celui care detine biletul cursei gnome atunci cand gnomes ies invingatori.",al={"cutie cu premii pentru gnome","gnome castiga un premiu"}},{q="Cine poate participa la acest pariu?",a="Nu apartine niciunei factiuni, asa ca cei care calatoresc pentru Alliance si Horde sunt pe picior de egalitate.",al={"poate Horde sa parieze","poate Alliance sa parieze","bilet neutru"}},{q="Ce se intampla daca goblinii castiga in schimb?",a="Atunci biletul Goblin este cel care conteaza. Rezultatul sau se numeste Goblins Win!, contrapartea acestuia.",al={"goblinii castiga","biletul cursei goblinilor"}}},fp="11,138,16.210.0,30.100.0,36.94.0,32.87.0,40.111.0"}
P.entries["quest:1175"] = {n="A Bump in the Road",s="Trackmaster Zherin are grija de circuitul de la Mirage Raceway, iar animalele de pe Shimmering Flats au crescut suficient de mult incat numarul lor trebuie redus inainte sa ajunga pe el. Ti se cere sa raresti populatiile de Saltstone Basilisks, Crystalhides si Gazers.",h="Trackmaster Zherin are grija de circuitul de la Mirage Raceway, iar animalele de pe Shimmering Flats au...",kw={"crystalhide","privitor","mirage raceway","tunetul rosu","basilisc de piatra sarata","campiile stralucitoare","tahonda ruins","maestrul de pista zherin","weazel's crater"},sec={{t="Mentinem drumul liber",b="Odata, un basilisk s-a ciocnit cu o masina de curse a goblinilor, Red Thunder, iar in urma incidentului Kronkrider l-a angajat pe Zherin sa se ocupe de pista. Zherin nu poate spune ce mananca animalele de prin Shimmering Flats ca sa ajunga atat de mari, ci doar ca trebuie sa li se reduca numarul, altfel unul va ajunge pe traseu in mijlocul unei curse. Sa curete resturile e destul de rau, iar Zherin ar prefera sa nu mai scotoceasca si prin bucati de animale arse."}},faq={{q="Cine este Trackmaster Zherin?",a="Maestrul pistei de la Mirage Raceway, in Shimmering Flats, angajat de Kronkrider sa aiba grija de pista.",al={"cine este zherin","trackmaster zherin","povestea lui zherin"}},{q="De ce sunt vanati basilisc?",a="Fiarele de pe campie au crescut mari, iar una care s-ar rataci pe pista in timpul unei curse ar putea provoca un accident, asa cum s-a intamplat cand un basilisc s-a intalnit cu Red Thunder al goblinilor.",al={"de ce sa ucizi basilisk","de ce trebuie sa moara basilisk","problema cu basilisk"}},{q="Ce este Red Thunder?",a="Un vehicul de curse al Goblin, distrus intr-o coliziune cu un basilisc.",al={"red thunder","prabusirea red thunder","red thunder goblin"}},{q="Unde se gasesc de obicei basilicii pe campii?",a="Se gasesc peste tot in Shimmering Flats, dar se aduna in numar mai mare langa Weazel's Crater si printre Tahonda Ruins.",al={"locatiile basilisk","unde sunt basilisk","unde gasesti Saltstone"}}},fp="18,266,23.435.0,26.109.0,35.167.0,24.73.0,51.114.0"}
P.entries["quest:1176"] = {n="Load Lightening",s="Pozzik, seful inginerilor goblini de la Mirage Raceway, are nevoie de materiale ca sa reduca greutatea cruciala a sasiului masinii sale-racheta. In loc sa se bazeze doar pe placi grele de metal, goblinii recupereaza oase goale de la vulturii desertului din zona, pentru a construi ansambluri de directie si structura rezistente, dar ultrau usoare.",h="Pozzik, seful inginerilor goblini de la Mirage Raceway, are nevoie de materiale ca sa reduca greutatea...",kw={"oase","load lightening","mirage raceway","pozzik","masina-racheta","shimmering flats","thousand needles","vultur"},ang={["profession:Engineering"]="Faptul ca Pozzik se bazeaza pe cadre din oase de pasari demonstreaza ingeniozitatea goblinilor: practica, improvizata si surprinzator de eficienta in reducerea greutatii vehiculului.",["race:Gnome"]="Sa vezi goblini care leaga la propriu carcase de pasari gasite prin gunoaie de mecanisme de directie este garantat sa scandalizeze orice inginer Tinker Town format dupa metodele clasice."},sec={{t="Fiecare gram conteaza",b="Pe intinderea orbitor de alba din Shimmering Flats, rivalitatea dintre inginerii goblini si cei gnomi se decide in fractiuni de secunda. Impingerea bruta a motorului nu foloseste la nimic daca vehiculul e ingreunat de masa excesiva. In timp ce echipele de gnomi se preocupa de angrenaje complicate si garnituri din alama, echipa goblina condusa de Pozzik urmareste o eficienta pragmatica nemiloasa: scoaterea cadrului masiv din fier si inlocuirea lui cu componente structurale mai usoare si goale pe dinauntru, oriunde permite cadrul."},{t="Cautatul prin desert pentru viteza",b="In loc sa expedieze compozite scumpe si specializate pana in Thousand Needles, Pozzik se foloseste de deseurile sarate din jur. Vulturii de pe Salt Flats sunt numerosi, iar oasele lor, slefuite de zbor, au un miez gol si alveolar, care ofera rezistenta mare la intindere fara aproape nicio greutate. Inlocuind piesele lucrate cu oase de vultur in mecanismul de directie si in contrafisele secundare ale masinii de curse, mecanicii lui Pozzik spera sa-si pastreze vehiculele suficient de agile pentru a-i depasi pe gnomi fara sa se dezmembreze la viteza maxima."}},faq={{q="De ce vrea Pozzik oase de vultur pentru o masina de curse?",a="Ingineria Goblin pune pret pe ingeniozitate si pe materiale folosite cu spirit de oportunitate. Oasele de vultur sunt goale pe dinauntru si usoare in mod natural, oferind un raport ideal intre rezistenta si greutate pentru a consolida componente delicate, precum sistemele de directie, fara a ingreuna vehiculul de curse.",al={"scopul oaselor de vultur","de ce oase","oasele lui Pozzik"}},{q="Cine este Pozzik?",a="Pozzik este mecanicul-sef al curselor Goblin si conducatorul echipei stationate la Mirage Raceway, in Shimmering Flats. El coordoneaza echipele Goblin impotriva rivalilor lor inversunati, gnomii.",al={"Pozzik","povestea lui Pozzik","cine este inginerul goblin"}},{q="Unde se gasesc vulturii acestia?",a="Necrofagii si vulturii dau tarcoale intinderii deschise din Shimmering Flats, mai ales in jurul ramasitelor scheletice uriase presarate in zonele de nord-est ale bazinului de sare.",al={"locatia vulturilor","unde se gasesc oasele goale","necrofagii din Shimmering Flats"}},{q="Ce este Mirage Raceway?",a="Mirage Raceway este o pista de curse neutra, amenajata pe vastul lac sarat secat din Thousand Needles. Goblinii si gnomii se intrec acolo in curse periculoase, de mare viteza, cu masini-racheta experimentale.",al={"povestea circuitului","ce este mirage raceway","pista din shimmer flats"}},{q="Fac gnomii acelasi lucru?",a="Desi gnomii cauta si ei modalitati de a-si optimiza masinile de curse, traditia lor inginereasca se bazeaza mai degraba pe mecanisme de precizie si metale complexe decat pe modificarile improvizate, facute din piese recuperate, ale goblinilor.",al={"curse de gnomi","gnomi contra goblini","folosesc gnomii oase"}},{q="Ajuta aceasta munca la efortul mai amplu al lui Pozzik de organizare a curselor?",a="Da. Dovedindu-ti seriozitatea prin usurarea racerului, castigi increderea lui Pozzik, ceea ce duce la alte treburi legate de rivalitatile de pe pista si de sponsorizarea oficiala a goblinilor, in campie.",al={"continuarea misiunii","ce urmeaza","sponsorizarea goblinilor"}}},fx={a8fc0189={q="De ce se concentreaza Pozzik atat de mult pe usurarea vehiculului sau de curse?",a="La Mirage Raceway, viteza este totul, iar cursele se decid adesea la diferente infime. Pozzik concureaza direct cu inginerii gnomi, unde orice greutate in plus il poate costa victoria pe salinuri. Eliminarea fiecarui gram de prisos din sasiu si mecanismul de directie ii permite masinii sale-racheta sa atinga acceleratia maxima fara sa-si sacrifice integritatea structurala.",al={"motivul lui pozzik","de ce sa usurez racer","de ce are pozzik nevoie de piese usoare"}},["8208273d"]={q="De ce sunt atat de multi vulturi in Shimmering Flats?",a="Shimmering Flats sunt o intindere necrutatoare, parjolita de soare si presarata cu ramasitele unor fiare uriase din vechime si ale calatorilor cazuti. Gunoierii salinelor se descurca bine aici, rotindu-se pe cer si hranindu-se cu hoiturile lasate in urma de clima aspra a desertului si de populatiile violente de bazilisci si scorpizi ale intinderii.",al={"de ce sunt vulturi in Shimmering Flats","povestea vulturilor de pe Salt Flats","vulturi din Thousand Needles"}}},fp="15,297,18.473.0,27.492.0,50.239.0,14.182.0,31.185.0,27.198.0,36.206.0,55.175.0"}
P.entries["quest:1177"] = {n="Hungry!",s="Mudcrush Durtfeet, un ogre din nordul Dustwallow Marsh, este flamand. Mud vrea sa mergi sa-i zdrobesti pe pestii Mirefin si sa le aduci capetele, altfel Mud te va manca pe tine.",h="Mudcrush Durtfeet, un ogre din nordul Dustwallow Marsh, este flamand.",kw={"dustwallow marsh","pestisor","Hungry!","capete Mirefin","Mudcrush Durtfeet","ogre"},sec={{t="Un ogre infometat",b="Mudcrush Durtfeet este un ogre mare si o spune fara ocolisuri. Lui Mud ii este foame si are o intelegere simpla: du-te si bate-i pe pestii Mirefin, apoi adu-i capetele lor drept hrana lui Mud. Hraneste-l pe Mud sau Mud te va manca pe tine."}},faq={{q="Cine este Mudcrush Durtfeet?",a="Mudcrush Durtfeet este un ogre masiv din nordul Dustwallow Marsh, cunoscut drept Mud. Lui Mud ii este foame si vrea mancare.",al={"mudcrush durtfeet","cine este mudcrush","ogru din dustwallow"}},{q="Ce vrea sa manance Mudcrush Durtfeet?",a="Mud vrea capete de Mirefin, aduse de la Mirefin cei piscosi pe care ti se spune sa-i cotonogesti.",al={"mancarea lui mudcrush","ce vrea capcaunul","mancarea pentru misiunea foamei"}},{q="Ce se intampla daca refuzi sa-l hranesti?",a="Mud o spune pe sleau: hraneste-l pe Mud sau te va manca.",al={"amenintare mudcrush","ma va manca mudcrush"}}},fp="7,167,13.184.0,25.107.0,40.82.0,39.49.0"}
P.entries["quest:1178"] = {n="Goblin Sponsorship",s="Pozzik, din echipa goblinilor de curse, asteapta un regulator de combustibil prototip pe care Gazlowe l-a promis cu cateva saptamani in urma, dar care nu a sosit. Gazlowe este de obicei foarte prompt, asa ca Pozzik iti cere sa mergi la Ratchet si sa afli ce s-a intamplat, fiindca gnomii recupereaza teren.",h="Pozzik, din echipa goblinilor de curse, asteapta un regulator de combustibil prototip pe care Gazlowe l-a...",kw={"regulator de combustibil","gazlowe","mirage raceway","pozzik","ratchet","campia stralucitoare","tinkers union","undermine"},sec={{t="O piesa promisa",b="Pozzik numeste echipa de curse mandria goblinilor si spune ca multi o ajuta intr-un fel sau altul. Gazlowe cauta piese prin toata lumea pentru echipa si chiar a venit odata sa lucreze la una dintre masini. Cu cateva saptamani in urma, Gazlowe a spus ca va trimite un nou prototip de regulator de combustibil, dar n-a sosit nimic, lucru neobisnuit pentru el. Cum gnomii ii ajung din urma, Pozzik te roaga sa mergi la Ratchet si sa-l intrebi pe Gazlowe ce s-a intamplat."},{t="Vesti despre Pozzik",b="Cand afla ca Pozzik te-a trimis, Gazlowe remarca faptul ca, inainte sa se retraga pentru a lucra la masinile de curse, Pozzik era considerat unul dintre cei mai respectati inventatori din Undermine. Primul lucru pe care l-a facut dupa ce s-a alaturat echipei a fost sa proiecteze cele doua modele de masini de curse cu motor. Gazlowe recunoaste ca afacerile ar putea avea de suferit fara colaborarea lui Pozzik cu Tinkers' Union, dar spune ca nimic nu intrece cursele."}},faq={{q="De ce are Pozzik nevoie sa mergi la Ratchet?",a="Gazlowe a spus acum cateva saptamani ca va trimite un prototip de regulator de combustibil, dar acesta nu a sosit. Pozzik iti cere sa mergi la Ratchet si sa-l intrebi despre el.",al={"de ce Ratchet","treaba lui Pozzik","obiectivul sponsorizarii Goblin"}},{q="Ce face Gazlowe pentru echipa de curse?",a="El cauta piese din toate colturile lumii pentru echipa si, odata, a venit chiar sa lucreze la unul dintre utilajele lor.",al={"implicarea lui gazlowe","sponsorul pistei de curse gazlowe","este gazlowe sponsor"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Load Lightening, oferita tot de Pozzik.",al={"misiune prealabila sponsorizarii goblin","ce misiune vine inaintea sponsorizarii goblin"}},{q="De ce se grabeste echipa goblin?",a="Pozzik spune ca gnomii ii ajung din urma.",al={"de ce sa grabim regulatorul de combustibil","intrecerea dintre goblin si gnome"}}},fp="18,266,15.419.0,18.361.1,42.143.0,41.106.0,23.49.0,34.43.0"}
P.entries["quest:1179"] = {n="The Brassbolts Brothers",s="Pilot Longbeard din Ironforge are nevoie de un curier care sa duca peste mare, pana in Kalimdor, o lada cu casti ranforsate pentru motoare de asediu. Prietenii sai, fratii Brassbolts, testeaza masini-racheta de mare viteza in Shimmering Flats si au nevoie urgent de protectii pentru cap pentru pilotii lor predispusi la accidente.",h="Pilot Longbeard din Ironforge are nevoie de un curier care sa duca peste mare, pana in Kalimdor, o lada cu...",kw={"brassbolts","ironforge","mirage raceway","pilot longbeard","masina-racheta","shimmering flats","thousand needles","wizzle brassbolts"},ang={["profession:Engineering"]="O misiune clasica de aprovizionare pentru inginerie, care imbina mestesugul piticilor in armuri grele cu experimentele gnomilor in propulsia de mare viteza.",["race:Dwarf"]="Doar armura robusta pentru Siege Engine pitic este destul de groasa ca sa reziste impactului frontal al unei rachete gnomice lansate la viteza maxima, pe intinderile sarate.",["race:Gnome"]="Goana dupa viteza pura a familiei Brassbolts ilustreaza ambitia clasica gnome, in care inovatia mecanica primeaza absolut in fata unor detalii neinsemnate precum franarea si longevitatea soferului."},sec={{t="O favoare de la mare distanta",b="In timp ce se afla langa aparatele sale de zbor din Ironforge, aviatorul pitic Pilot Longbeard a primit o cerere urgenta din Shimmering Flats, in sudul Kalimdorului. Prietenii sai, doi frati gnomi inventivi, cunoscuti drept Brassbolts, se stabilisera pe intinsele saline pentru a intrece masini experimentale. Longbeard este prins cu indatoririle militare si de pilotaj, asa ca nu poate duce el insusi proviziile."},{t="Siguranta la viteze mari",b="Masina-racheta a familiei Brassbolts s-a dovedit extraordinar de rapida - atat de rapida, incat pilotii de incercare tot se izbesc de pamant pe salina si sufera comotii grave. Longbeard procura o lada cu casti robuste pentru Dwarven Siege Engine, menite sa le protejeze craniile. Ducandu-le lada, le oferi gnomilor sprijinul necesar pentru a-i convinge pe pilotii reticenti sa se urce din nou la comenzile masinii lor de viteza volatile."}},faq={{q="Cine este Pilot Longbeard?",a="Pilot Longbeard este un aviator pitic din Ironforge. Cunoscut al fratilor Brassbolts, le asigura aprovizionarea din Eastern Kingdoms, procurand echipamente grele piticesti pe care acestia nu le pot fabrica cu usurinta in teren.",al={"pilot longbeard","cel care da misiunea","cine ofera aceasta misiune"}},{q="Cine sunt fratii Brassbolts?",a="Fratii Brassbolts, printre care si Wizzle Brassbolts, sunt ingineri gnome ambitiosi, care si-au stabilit un punct de lucru la Mirage Raceway, in Shimmering Flats. Isi petrec zilele proiectand si regland masini de curse cu rachete de ultima generatie, ca sa-i intreaca pe goblini.",al={"fratii brassbolts","wizzle brassbolts","frati gnomi"}},{q="Unde se afla Shimmering Flats?",a="Shimmering Flats este o intinsa campie sarata, arsa de soare, aflata in sudul Kalimdorului, dincolo de inaltii stalpi de canion din Thousand Needles. Intinderea sa neteda, lipsita de obstacole, o face un teren de incercare ideal pentru vehicule experimentale de mare viteza.",al={"locatia Shimmering Flats","unde trebuie livrat","unde este pista de curse"}},{q="De ce au nevoie gnomii de casti pentru Siege Engine?",a="Masina-racheta a familiei Brassbolts atinge viteze uriase, dar directia si stabilitatea lasa mult de dorit. Accidentele soferilor si comotiile au devenit atat de frecvente, incat niciun pilot de testare nu mai era dispus sa se urce la volan fara o protectie solida pentru cap, de sorginte dwarven.",al={"de ce casti","casti de protectie","accidente cu masini-racheta"}},{q="De ce nu le livreaza Longbeard el insusi?",a="Pilot Longbeard este legat de obligatiile si indatoririle sale militare din Ironforge. Deoarece lunga calatorie peste Great Sea pana in sudul Kalimdorului l-ar obliga sa-si abandoneze postul, el se bazeaza pe aventurierii aflati in trecere pentru a transporta lada grea.",al={"de ce nu Longbeard","indatoririle lui Longbeard"}},{q="Pot jucatorii din Horde sa indeplineasca aceasta sarcina?",a="Nu. Aceasta misiune incepe de la Pilot Longbeard in capitala Alliance, Ironforge, si este rezervata curierilor Alliance, desi Mirage Raceway in sine ii primeste pe membrii ambelor factiuni.",al={"este doar pentru alianta","varianta hoardei","factiune"}}},fp="23,296,21.426.0,23.411.0,23.242.0,32.258.0,30.242.0,44.260.0,43.238.0,37.181.0"}
P.entries["quest:118"] = {n="The Price of Shoes",s="Verner Osgood, fierarul din Lakeshire, si-a epuizat rezerva de fier reparand echipamentul garzii orasului, coplesite de probleme. Neavand metal cu care sa potcoveasca caii din zona, il trimite pe un curier prin Elwynn Forest sa ceara ajutorul lui Smith Argus din Goldshire.",h="Verner Osgood, fierarul din Lakeshire, si-a epuizat rezerva de fier reparand echipamentul garzii orasului...",kw={"elwynn","goldshire","potcoave","fier","lakeshire","redridge","smith argus","verner osgood"},ang={["faction:Alliance"]="Dependenta Lakeshire de Goldshire scoate in evidenta cat de intinse la limita sunt resursele logistice ale regatului sub regenta din Stormwind.",["profession:Blacksmithing"]="Cererea scoate in evidenta realitatile materiale dure ale faurariei de la frontiera, unde forja unui mestesugar trebuie sa dea intaietate supravietuirii soldatilor, nu gospodariilor obisnuite."},sec={{t="O frontiera impinsa la limita",b="Lakeshire se afla chiar in calea gnollilor, orcilor si murlocilor, dar Stormwind ofera prea putine intariri. Garnizoana locala trebuie sa lupte zi de zi pentru a impiedica orasul sa cada, iar luptele neincetate uzeaza rapid echipamentul. Verner Osgood isi petrece aproape fiecare ora de veghe reparand platoasele indoite, reascutind sabiile tocite si tinand garzile orasului imbracate in fier, consumandu-si astfel materiile prime."},{t="Linii de aprovizionare catre Elwynn",b="Cand o asezare de frontiera ramane complet fara fier, chiar si sarcinile obisnuite se opresc. Fara potcoave, mesagerii nu pot calari in schimburi rapide, iar animalele de povara nu pot transporta provizii pe cararile stancoase din Redridge. Verner trebuie sa-si inghita mandria si sa ceara ajutor din tinuturile centrale, trimitand calatori spre vest, pe drumul Three Corners, pana la Goldshire, unde Smith Argus are in continuare acces regulat la rezervele bogate de minereu ale domeniului regal."}},faq={{q="De ce a ramas Verner fara fier?",a="Garzile locale din Lakeshire sunt atacate neincetat de fauna ostila din Redridge, gnolli si orci Blackrock. Verner si-a folosit tot fierul pentru a le repara armurile si armele zdrobite, fara sa-i mai ramana nimic pentru nevoile civililor.",al={"de ce nu este fier","Verner a ramas fara metal","lipsa de fier din Lakeshire"}},{q="Cine este Smith Argus?",a="Smith Argus este fierarul din Goldshire, in Elwynn Forest. Fiind aproape de centrul aglomerat al regatului, atelierul sau are acces mult mai facil la lingouri si provizii decat orasele de frontiera precum Lakeshire.",al={"argus in goldshire","cine este argus","fierarul din goldshire"}},{q="De ce nu primeste Lakeshire provizii din Stormwind?",a="Conducatorii din Stormwind sunt prinsi in inertie politica, in vreme ce regele Varian Wrynn ramane disparut. Cum House of Nobles refuza sa furnizeze trupe si fonduri, orasele de la frontiera, precum Lakeshire, sunt lasate in mare parte sa se descurce singure, folosind orice comert regional pot sustine.",al={"de ce nu vine ajutor din Stormwind","Lakeshire, lasat de izbeliste","neglijenta Stormwind"}},{q="De ce sunt potcoavele atat de importante in Redridge?",a="Terenul stancos si necrutator din Redridge toceste repede copitele fiarelor fara potcoave. Fara acestea, curierii, carele cu provizii si caii de patrulare ajung schiopi, izoland Lakeshire de restul regatului.",al={"de ce sunt necesare potcoavele","de ce conteaza potcoavele"}},{q="Ce se intampla dupa ce ajungi la Smith Argus?",a="Argus primeste biletul lui Verner si iti da o livrare de potcoave pe care sa le duci inapoi la Lakeshire, deschizandu-ti calea spre alte sarcini care sa ajute la apararea asezarii asediate.",al={"urmatoarea misiune","ce urmeaza dupa Argus"}},{q="Unde se afla Smith Argus in Goldshire?",a="Poate fi gasit lucrand la forja in aer liber de langa Lion's Pride Inn din Goldshire, chiar langa drumul principal care strabate Elwynn Forest.",al={"unde este Argus","locatia lui Argus"}}},fx={["24418d93"]={q="De ce te trimite Verner in loc sa mearga el insusi sau sa trimita un gardian?",a="Verner este fierarul principal din Lakeshire si nu-si poate parasi forja cat timp apararea orasului este atat de solicitata. Redridge este deja asediat de gnolli si orci, asa ca fiecare strajer local este necesar pe metereze si de-a lungul podului. Cum lanturile locale de aprovizionare sunt complet suprasolicitate, doar aventurieri capabili, gata de drum precum tine, pot strabate tot Elwynn Forest.",al={"de ce sa ma trimita pe mine","de ce nu pleaca Verner","de ce sa nu trimita un gardian"}}},fp="18,261,32.437.0,22.435.0,26.246.0,19.213.0,48.266.0,43.216.0,40.167.0,42.127.0"}
P.entries["quest:1180"] = {n="Goblin Sponsorship",s="Gazlowe revine la problema care te-a adus aici: regulatorul de combustibil promis lui Pozzik n-a ajuns la Ratchet. Revilgaz din Booty Bay a spus ca-l va trimite, dar poate s-a ratacit pe drum. Gazlowe te trimite la Wharfmaster Lozgil de acolo, care poate verifica registrele marfurilor.",h="Gazlowe revine la problema care te-a adus aici: regulatorul de combustibil promis lui Pozzik n-a ajuns la...",kw={"booty bay","regulator de combustibil","gazlowe","sponsorizare goblin","mirage raceway","pozzik","ratchet","revilgaz","wharfmaster lozgil"},sec={{t="O piesa care n-a mai sosit",b="Gazlowe recunoaste ca i-a promis lui Pozzik un regulator nou de combustibil si ca inca nu l-a primit. Revilgaz din Booty Bay a spus ca il va trimite, dar poate ca a fost ratacit. Daca asa stau lucrurile, nu se prea poate face nimic, dar macar poti afla daca a plecat din Booty Bay. Wharfmaster Lozgil, aflat la extremitatea nord-vestica a docurilor din Booty Bay, poate cauta in registrele de marfa."},{t="Registrele capitanului portului",b="Lozgil verifica registrele pentru livrarile catre Ratchet. Cea mai recenta a fost un transport de cizme de la Drizzlik, iar in rest au fost doar materiale de constructie si unelte. Nu au existat piese pentru masini de curse."}},faq={{q="Ce parte lipseste?",a="Gazlowe i-a promis lui Pozzik un regulator nou pentru combustibil, dar Gazlowe nu l-a primit inca.",al={"piesa lui pozzik","de ce regulatorul de combustibil","livrarea lui pozzik"}},{q="Cine a spus ca va trimite regulatorul la Ratchet?",a="Revilgaz din Booty Bay a spus ca o va trimite la Gazlowe din Ratchet.",al={"cine trimite piesa","piesa lui revilgaz","cine are regulatorul de combustibil"}},{q="Cine tine registrele transporturilor in Booty Bay?",a="Wharfmaster Lozgil, care poate consulta registrele de marfa. Se afla la capatul nord-vestic indepartat al docurilor din Booty Bay.",al={"maestrul de marfa din booty bay","cine este wharfmaster lozgil","unde este lozgil"}},{q="Unde se situeaza acest pas in lant?",a="Aceasta urmeaza dupa prima misiune Goblin Sponsorship, in care Pozzik te-a trimis la Gazlowe, iar urmatorul pas este Goblin Sponsorship (3).",al={"lantul sponsorizarii goblin","progresul misiunilor","ce urmeaza inainte de aceasta"}}},fp="18,290,22.386.0,25.183.1,21.82.0,50.79.0,44.117.0,38.122.0"}
P.entries["quest:1181"] = {n="Goblin Sponsorship",s="Wharfmaster Lozgil nu te mai poate ajuta cu regulatorul de combustibil disparut si iti sugereaza sa-l intrebi chiar pe Baron Revilgaz. Il vei gasi pe Baron la hanul de peste port, in Booty Bay, la ultimul etaj.",h="Wharfmaster Lozgil nu te mai poate ajuta cu regulatorul de combustibil disparut si iti sugereaza sa-l intrebi...",kw={"baron revilgaz","booty bay","regulator de combustibil","sponsorizare goblin","mirage raceway","ratchet","wharfmaster lozgil"},sec={{t="O intrebare pentru Baron",b="Wharfmaster Lozgil iti spune ca nu te mai poate ajuta prea mult sa dai de urma transportului disparut, destinat lui Ratchet. Daca vrei sa afli mai multe, iti sugereaza sa mergi chiar la Baron, fiindca, daca cineva stie ce pune la cale Revilgaz, acela este Revilgaz. Te asteapta in taverna de peste port, la ultimul etaj."},{t="Raspunsul baronului",b="Baron Revilgaz intelege despre ce vorbesti, dar nu te poate ajuta. Cativa dintre oamenii lui au fost trimisi sa gaseasca planurile regulatorului de combustibil, dar s-au intors cu mainile goale."}},faq={{q="Unde il pot gasi pe Baron Revilgaz?",a="La taverna de peste port, in Booty Bay, la ultimul etaj.",al={"locatia lui Baron Revilgaz","unde se afla Revilgaz","gaseste-l pe Revilgaz in Booty Bay"}},{q="De ce te trimite Wharfmaster Lozgil la Revilgaz?",a="Lozgil nu te poate ajuta cu mult mai mult si spune ca, daca cineva stie de afacerile lui Revilgaz, acela e chiar Revilgaz.",al={"de ce sa vorbesti cu Revilgaz","Lozgil te trimite la Baron","de ce sa-l vezi pe Baron Revilgaz"}},{q="Ce transport incearca sa gaseasca?",a="Un nou regulator de combustibil care trebuia sa ajunga la Ratchet, pentru masinile de curse goblin de la Mirage Raceway.",al={"ce transport lipseste","ce cautam","marfa ratchet lipsa"}},{q="Unde se situeaza acest pas in lant?",a="Urmeaza dupa Goblin Sponsorship (2), discutia ta cu Wharfmaster Lozgil, iar urmatorul pas este Goblin Sponsorship (4).",al={"ce a fost inainte de goblin sponsorship 3","progresul lantului goblin sponsorship"}}},fp="18,208,16.299.0,18.163.1,32.63.0,49.110.0,36.101.0,38.114.0"}
P.entries["quest:1182"] = {n="Goblin Sponsorship",s="Baron Revilgaz iti spune ca tocatoarele Venture Company de la Lake Nazferiti, in nordul Stranglethorn, au un nou model de regulator de combustibil pe care Pozzik l-ar putea folosi. Foreman Cozzle s-a dovedit mai istet decat se astepta Baronul, asa ca Revilgaz te trimite sa gasesti planurile.",h="Baron Revilgaz iti spune ca tocatoarele Venture Company de la Lake Nazferiti, in nordul Stranglethorn, au un...",kw={"baron revilgaz","planuri","foreman cozzle","regulator de combustibil","goblin sponsorship","lake nazferiti","mirage raceway","pozzik","venture company"},ang={["class:Rogue"]="Un Rogue poate descuia lada cu schitele fara a avea nevoie de cheia maistrului."},sec={{t="Planurile de constructie ale maistrului",b="Baron Revilgaz explica faptul ca tocatoarele Venture Company de la Lake Nazferiti, in nordul Stranglethorn, sunt echipate cu un nou model de regulator de combustibil. Pozzik ar putea profita de el daca ar avea detaliile, dar Cozzle, maistrul de acolo, este mai istet decat credea Revilgaz. S-ar putea sa ai mai mult noroc. Revilgaz stie ca planurile sunt pastrate in casa lui Cozzle, aproape sigur sub cheie. Venture Company isi are baza in jurul lacului Lake Nazferiti, in coltul de nord-est al vaii. Cheia este la maistrul Cozzle, in cabana din varful turnului petrolier, iar lada cu planurile se afla in casuta de langa baza turnului. Revilgaz recunoaste ca echipa de gnome de acolo este destul de buna si spune ca echipa are nevoie de orice avantaj poate gasi."},{t="O copie pentru baron",b="Cu planurile in mana, Revilgaz vrea o copie pentru propriile insemnari, apoi te trimite la Pozzik, ca Pozzik sa nu creada ca unul dintre sponsorii sai l-a abandonat."}},faq={{q="De ce vrea Baron Revilgaz planurile regulatorului de combustibil?",a="Masinile de tocat ale Venture Company de la Lake Nazferiti au un nou model de regulator de combustibil, iar Revilgaz crede ca Pozzik ar putea profita de el daca ar avea detaliile.",al={"de ce sa furi schitele","de ce regulatorul de combustibil","motivul lui revilgaz"}},{q="Unde sunt pastrate planurile?",a="Intr-o cutie dintr-o casuta de la baza turnului petrolier, la baza Venture Company de la Lake Nazferiti, in nordul Stranglethorn.",al={"unde sunt schitele","locatia schitelor regulatorului de combustibil","casa lui Cozzle"}},{q="Cine detine cheia?",a="Foreman Cozzle il poarta si lucreaza in cabana din varful turnului petrolier.",al={"cheia lui Cozzle","unde este cheia","cum deschizi cufarul"}},{q="Unde se situeaza acest pas in lant?",a="Urmeaza dupa Goblin Sponsorship (3), in care Wharfmaster Lozgil te-a trimis la Baron. Pasul urmator este Goblin Sponsorship (5).",al={"ce urmeaza","ce misiune urmeaza","lantul de sponsorizare goblin"}}},fp="18,259,24.743.0,20.166.1,55.159.0,30.135.0,18.69.0,38.126.0"}
P.entries["quest:1183"] = {n="Goblin Sponsorship",s="Baron Revilgaz are gata proiectele Fuel Regulator si i le trimite lui Pozzik, in Shimmering Flats. Ii transmite salutari si adauga ca Pozzik nu trebuie sa ezite sa ceara ajutor daca va avea vreodata nevoie de ceva.",h="Baron Revilgaz are gata proiectele Fuel Regulator si i le trimite lui Pozzik, in Shimmering Flats.",kw={"baron revilgaz","scheme pentru regulatorul de combustibil","sponsorizare goblin","mirage raceway","pozzik","shimmering flats","thousand needles"},sec={{t="Salutari pentru Pozzik",b="Baron Revilgaz spune ca totul e pregatit. Ai asupra ta schitele pentru Pozzik, aflat in Shimmering Flats, insotite de salutari din partea Baronului si de un mesaj: daca Pozzik va avea vreodata nevoie de ceva, sa nu ezite sa ceara. Revilgaz spune ca va astepta vesti ca Pozzik a doborat recordul pistei."},{t="Imbunatatirea proiectului",b="Pozzik sperase ca regulatorul sa fie deja asamblat. Totusi, vede o ocazie de a imbunatati proiectul de la zero. Planuieste sa schiteze planuri imbunatatite, sa construiasca piesa si sa o instaleze curand."}},faq={{q="Cine te trimite cu planurile?",a="Baron Revilgaz te trimite din Booty Bay, cu salutari pentru Pozzik.",al={"cine ofera sponsorizarea goblina 5","cel care da misiunea","misiunea lui revilgaz"}},{q="Cine primeste planurile regulatorului de combustibil?",a="Pozzik, in Shimmering Flats.",al={"unde duc planurile","cine primeste schemele","locatia lui pozzik"}},{q="Ce spera sa auda Baron Revilgaz?",a="Spune ca va astepta vesti despre faptul ca Pozzik doboara recordul pistei.",al={"motivul lui revilgaz","baron revilgaz, sponsor"}},{q="Ce precede aceasta livrare?",a="Urmeaza dupa Goblin Sponsorship (4), in care ai recuperat planurile pentru Revilgaz. Urmatorul pas este The Eighteenth Pilot.",al={"misiunea anterioara","ce a dus la aceasta","lantul de sponsorizare al goblinilor"}}},fp="18,200,18.282.0,20.207.1,34.69.0,43.32.0,38.72.0,32.123.0"}
P.entries["quest:1184"] = {n="Parts of the Swarm"}
P.entries["quest:1186"] = {n="The Eighteenth Pilot",s="Pozzik va fi ocupat sa monteze noul regulator de combustibil in schitele masinilor de curse, dar iti sugereaza sa ajuti echipa si mai mult, vorbind cu Razzeric in Shimmering Flats. Razzeric este pilotul echipei, al optsprezecelea la rand, si ii place sa adauge modificari masinilor de curse.",h="Pozzik va fi ocupat sa monteze noul regulator de combustibil in schitele masinilor de curse, dar iti...",kw={"goblin","pilot","pozzik","cursa","razzeric","shimmering flats","thousand needles"},sec={{t="Intalneste pilotul",b="Pozzik spune ca regulatorul de combustibil il tine ocupat, dar poti ajuta echipa si mai mult vorbind cu Razzeric in Shimmering Flats. Razzeric este pilotul echipei, al optsprezecelea, de fapt, si ii place sa adauge mici modificari personale vehiculelor de curse. Pozzik adauga ca Razzeric e cam dus cu pluta, asa ca incearca sa nu pari prea surprins."},{t="Un pilot isi aminteste",b="Razzeric stie ca l-ai ajutat pe Pozzik si spune ca a fost candva ca tine, alergand prin zona gropii si ajutand la orice treaba pe care mecanicii il lasau sa o faca. Acum este pilotul de exceptie al echipei de curse a goblinilor."}},faq={{q="Cine este Razzeric?",a="Razzeric este un goblin, pilotul echipei de curse goblin de pe Shimmering Flats. Pozzik il numeste al optsprezecelea pilot al echipei.",al={"cine este eighteenth pilot","povestea lui razzeric","pilot goblin"}},{q="De ce te trimite Pozzik la Razzeric?",a="Pozzik este ocupat sa integreze noul regulator de combustibil in proiectele masinilor de curse si iti sugereaza sa ajuti echipa mai departe vorbind cu Razzeric.",al={"de ce sa vorbesc cu razzeric","pozzik eighteenth pilot"}},{q="Cum este Razzeric?",a="Pozzik spune ca lui Razzeric ii place sa aduca mici modificari proprii vehiculelor de curse si ca e putin sarit de pe fix.",al={"personalitatea lui razzeric","e razzeric nebun"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa Goblin Sponsorship (5), in care ai livrat Fuel Regulator Blueprints lui Pozzik.",al={"conditie prealabila eighteenth pilot","lantul de misiuni dinaintea lui razzeric"}}},fp="20,261,14.352.0,17.215.1,16.128.0,37.144.0,22.106.0,22.100.0"}
P.entries["quest:1187"] = {n="Razzeric's Tweaking",s="In Shimmering Flats, Razzeric adauga modificari personale vehiculelor de curse dupa ce Pozzik termina cu ele. Un amplificator de seaforium comandat de la Shreev din Gadgetzan se afla intr-un zeppelin despre care Razzeric a auzit ca s-a prabusit in Dustwallow Marsh, iar Razzeric vrea sa fie adus inapoi.",h="In Shimmering Flats, Razzeric adauga modificari personale vehiculelor de curse dupa ce Pozzik termina cu ele.",kw={"Dustwallow Marsh","Gadgetzan","Gizmorium","Pozzik","Razzeric","amplificator Seaforium","Shimmering Flats","Shreev","Thousand Needles"},sec={{t="Mai mult suc",b="Razzeric recunoaste ca Pozzik este un mecanic grozav, dar crede ca Pozzik se teme prea mult sa adauge putere de foc si sa se tina bine in timpul cursei. Dupa ce Pozzik termina un vehicul de curse, Razzeric isi petrece timpul facand modificari personale: slabeste comenzile, scoate sectiuni ale cadrului si adauga putere. A comandat un amplificator de seaforium de la Shreev, de la Gizmorium din Gadgetzan, dar, dupa cum povesteste Razzeric, zeppelinul care il transporta s-a prabusit in Dustwallow Marsh. Amplificatorul trebuie adus inapoi in Shimmering Flats, fiindca ar fi o rusine sa apari pe pista fara acel plus de putere."},{t="Prins de masina de curse",b="Razzeric se entuziasmeaza in legatura cu propulsorul: cincisprezece livre intregi de seaforium. Prins pe latura unui racer, ar trebui sa-l poarte pe Razzeric prin circuit cu o asemenea viteza, incat gnomii sa fie invinsi de doua ori."}},faq={{q="Cine este Razzeric?",a="Razzeric este un concurent de pe Shimmering Flats care face modificari personale concurentilor dupa ce Pozzik termina cu ei.",al={"Razzeric","cine ofera misiunea Razzeric's Tweaking","Razzeric in Shimmering Flats"}},{q="De unde a venit amplificatorul?",a="Razzeric a comandat-o de la Shreev, de la Gizmorium din Gadgetzan.",al={"de unde a venit amplificatorul","cine a creat amplificatorul Seaforium","Gadgetzan Gizmorium"}},{q="Unde se afla acum boosterul seaforium?",a="Razzeric spune ca zeppelinul care o transporta s-a prabusit in Dustwallow Marsh.",al={"unde se afla amplificatorul Seaforium","locatia amplificatorului","locatia zeppelinului prabusit"}},{q="De ce vrea Razzeric boosterul?",a="Razzeric vrea mai multa putere decat este dispus sa incarce Pozzik si crede ca ar fi o rusine sa concureze pe pista fara acel plus de zvac.",al={"de ce vrea seaforium","de ce are nevoie de amplificatorul seaforium"}},{q="Ce a fost inainte de acest pas?",a="Eighteenth Pilot a venit primul.",al={"misiunea anterioara","cerinta prealabila","ce duce la razzerics tweaking"}}},fp="19,263,10.560.0,21.199.1,16.113.0,32.57.0,35.67.0,35.133.0,27.32.0"}
P.entries["quest:1188"] = {n="Safety First",s="Razzeric a aflat ca Shreev a lasat siguranta pusa pe amplificatorul de seforiu. Aceasta limiteaza puterea pe care Razzeric o obtine de la amplificator, iar Razzeric ceruse sa fie scoasa. Esti trimis la Shreev in Gadgetzan, in Tanaris.",h="Razzeric a aflat ca Shreev a lasat siguranta pusa pe amplificatorul de seforiu.",kw={"gadgetzan gizmorium","razzeric","safety first","amplificator seaforium","shimmering flats","shreev","tanaris"},sec={{t="O masura de siguranta pe care n-o voia nimeni",b="Razzeric examineaza amplificatorul de seforiu si observa ca siguranta este inca activata. Aceasta limiteaza puterea pe care o poate furniza amplificatorul, iar Razzeric ii spusese lui Shreev ca trebuia dezactivata. Razzeric iti da amplificatorul si te trimite la sud de Shimmering Flats, in desertul din Tanaris, la Gizmorium-ul din Gadgetzan, ca sa-l rogi pe Shreev sa dezactiveze siguranta."},{t="Raspunsul lui Shreev",b="Gizmorium iti ofera servicii pentru toate nevoile tale legate de mesterit. Cand ii dai amplificatorul, Shreev neaga ca i-ar fi montat vreo siguranta. Potrivit lui Shreev, amplificatorul este aproape in intregime alcatuit din explozibil seaforium, deja modificat astfel incat, odata folosit, sa-si elibereze o parte mai mare din incarcatura. Shreev spune ca Razzeric nu se multumeste niciodata decat daca duce lucrurile pana la unsprezece."}},faq={{q="Cine te trimite la Gadgetzan?",a="Razzeric, pilotul Goblin, te trimite la Gadgetzan cu amplificatorul sau cu seaforium.",al={"emitatorul misiunii","cine incepe Safety First","misiunea lui Razzeric"}},{q="De ce este Razzeric nemultumit de amplificator?",a="Shreev a lasat siguranta activata. Aceasta limiteaza puterea pe care Razzeric o obtine de la propulsor, iar Razzeric ceruse sa fie dezactivata.",al={"de ce se plange Razzeric","problema cu amplificatorul","ce nu e in regula cu amplificatorul"}},{q="Unde poate fi gasit Shreev?",a="Shreev se afla in Gadgetzan, la Gizmorium, in desertul Tanaris, la sud de Shimmering Flats.",al={"locatia lui shreev","unde se afla shreev","locatia gizmorium din gadgetzan"}},{q="Ce obiect duci la Gadgetzan?",a="Porti amplificatorul de seaforium al lui Razzeric, pe care Razzeric ti-l da sa-l duci la Shreev.",al={"ce obiect","obiectul amplificator","ce trebuie sa-i aduci lui Shreev"}},{q="Ce urmeaza dupa aceasta livrare?",a="Lantul continua cu o a doua parte, numita tot Safety First.",al={"misiunea urmatoare","ce urmeaza dupa Safety First","continuarea misiunii Safety First"}}},fp="12,220,22.321.0,15.350.1,27.78.0,41.123.0,26.98.0,40.84.0,31.65.0"}
P.entries["quest:1189"] = {n="Safety First",s="Shreev a facut ce i-a cerut Razzeric cu amplificatorul de seaforium, iar tu duci amplificatorul modificat inapoi la Razzeric, in Shimmering Flats. Shreev te avertizeaza sa fii atent cand il declansezi, fiindca o singura greseala si Razzeric ajunge o pata de cenusa pe pista. Aceasta urmeaza primei misiuni Safety First.",h="Shreev a facut ce i-a cerut Razzeric cu amplificatorul de seaforium, iar tu duci amplificatorul modificat...",kw={"gadgetzan","pozzik","razzeric","safety first","seaforium booster","shimmering flats","shreev","thousand needles"},sec={{t="Un avertisment de la Shreev",b="Shreev iti da amplificatorul modificat, asa cum a cerut Razzeric. Shreev te avertizeaza ca Razzeric trebuie sa fie atent cand il declanseaza. O singura greseala si nu va mai intrece pe nimeni; va deveni o urma de arsura pe pista. Shreev adauga ca ar fi pacat si se intreaba daca al nouasprezecelea sofer s-ar fi descurcat bine."},{t="Nisip sub scaun",b="Inapoi in Shimmering Flats, Razzeric bombane despre Pozzik, care a pus o galeata cu nisip pe racer. Cum, intreaba Razzeric, ar putea sa atinga viteza maxima cu nisipul sub scaun?"},{t="Amplificatorul returnat",b="Razzeric este multumit de propulsorul modificat. Si-ar dori sa poata vedea fetele gnome-lor cand il declanseaza, desi se asteapta sa fie prea ocupat sa stabileasca un nou record de viteza."}},faq={{q="Cine trimite amplificatorul modificat inapoi in campie?",a="Shreev termina lucrul la amplificatorul de seaforium din Gadgetzan si ti-l da sa i-l duci inapoi lui Razzeric, pe Shimmering Flats.",al={"cine da Safety First 2","cine da misiunea lui Shreev","cine modifica amplificatorul"}},{q="Despre ce avertizeaza Shreev?",a="Shreev spune ca Razzeric ar trebui sa fie atent cand declanseaza amplificatorul. O singura greseala si nu va porni in cursa; va ramane o urma de arsura pe pista.",al={"este periculos amplificatorul","avertismentul lui shreev","riscurile amplificatorului"}},{q="De ce este Razzeric suparat pe vehiculul sau?",a="Pozzik a incarcat o galeata cu nisip in masina de curse, iar Razzeric intreaba cum poate atinge viteza maxima cu nisip sub scaun.",al={"de ce e razzeric suparat","galeata cu nisip a lui pozzik","plangerea lui razzeric"}}},fp="12,302,21.329.0,19.188.0,20.176.1,49.133.0,28.149.0,40.119.0"}
P.entries["quest:119"] = {n="Return to Verner",s="Duci cincizeci de potcoave proaspat faurite din Goldshire inapoi la Lakeshire. Smith Argus a terminat comanda, iar Verner Osgood te asteapta dincolo de granita, in Redridge.",h="Duci cincizeci de potcoave proaspat faurite din Goldshire inapoi la Lakeshire.",kw={"crate of horseshoes","elwynn forest","goldshire","lakeshire","redridge","smith argus","the price of shoes","verner osgood"},ang={["faction:Alliance"]="Ca membru al Alliance, ajuti la pastrarea legaturii dintre asezari indepartate precum Lakeshire si inima regatului, prin rutele de aprovizionare dintre Elwynn Forest si Redridge.",["profession:Blacksmithing"]="Ca fierar, stii ca mijloacele de transport de la granita au nevoie de provizii constante de potcoave, mai ales cand forjele locale sunt coplesite de razboi."},sec={{t="Un curier dincolo de granita",b="Smith Argus a faurit cincizeci de potcoave pentru Lakeshire, iar tu le duci spre est, din Goldshire. Redridge se confrunta cu lipsuri de provizii si atacuri ale gnollilor. Potcoavele de fier ajuta caii si animalele de povara sa lucreze pe drumurile sale montane accidentate."},{t="Biletul de pe lada",b="Verner Osgood rasufla usurat cand sosesc potcoavele, dar Smith Argus a prins o nota de plata de lada. Verner este enervat ca fierarul din Goldshire se asteapta sa fie platit. Redridge se confrunta cu primejdii urgente si nu e timp de cearta pe tema costului."}},faq={{q="Unde duc Crate of Horseshoes?",a="Du lada la Verner Osgood din Lakeshire, in Redridge Mountains, chiar la est de pod si de docurile de pe malul lacului.",al={"unde este verner","locatia predarii","cine primeste potcoavele"}},{q="Cine a trimis aceasta livrare inapoi la Redridge?",a="Smith Argus, fierarul din fata Lion's Pride Inn din Goldshire, trimite lada dupa ce termina de facut potcoavele.",al={"cine a oferit misiunea","smith argus","cel care ofera misiunea"}},{q="De ce se supara Verner cand primeste lada?",a="Smith Argus a atasat o factura care cere plata pentru toate cele cincizeci de potcoave, iar Verner este iritat. Se pare ca sperase sa primeasca o favoare gratis sau conditii mai usoare.",al={"de ce e Verner furios","biletul lui Argus","reactia lui Verner"}},{q="Ce misiuni devin disponibile dupa finalizarea acestei livrari?",a="Dupa aceasta livrare, Verner iti ofera de lucru impotriva amenintarilor locale: vaneaza gnollii din Redridge in 'A Baying of Gnolls' si adu 'Underbelly Scales'.",al={"urmatoarea misiune","misiuni ulterioare","ce se deblocheaza"}},{q="De ce are Lakeshire nevoie de provizii aduse din Goldshire?",a="Gnollii si orcii Blackrock asediaza Lakeshire, solicitand la maximum mesterii locali. Orasul are adesea nevoie de bunuri de zi cu zi, precum potcoave de fier in cantitati mari, din locuri mai linistite ca Goldshire.",al={"de ce pantofi din Elwynn","de ce sa importam potcoave","proviziile pentru Redridge"}},{q="Te insoteste Smith Argus inapoi la Redridge?",a="Nu. Smith Argus ramane la forja sa din Goldshire, in timp ce tu duci lada la Redridge.",al={"vine argus cu","insotitorul lui smith argus"}}},fx={a0846e84={q="De ce vrea Smith Argus ca aceasta lada sa-i fie livrata lui Verner?",a="Smith Argus indeplineste cererea urgenta a lui Verner Osgood pentru cincizeci de potcoave, dar nu din simpla bunatate. Le-a pus intr-o lada si a atasat o factura categorica, cerand plata pentru munca si materiale. Predandu-ti transportul, te asiguri ca Redridge primeste proviziile si ca Verner intelege ca lucrarile de fierarie din Goldshire nu sunt gratuite.",al={"de ce trimite Argus potcoave","motivul lui Smith Argus","potcoave Argus de ce Verner"}},f67540ab={q="De ce iti cere Smith Argus sa duci potcoavele in loc sa le livreze chiar el?",a="Argus este fierarul din Goldshire, legat de nicovala si forja sa, unde echipeaza calatorii si garzile locale. Sa care o lada grea cu cincizeci de potcoave de fier peste granita, prin trecatorile din Redridge, ii rapeste timp pentru munca si expune un mestesugar singuratic gnollilor si talharilor de pe drum. Esti un aventurier priceput, deja pornit spre est.",al={"de ce nu livreaza argus pantofii","de ce trebuie eu return to verner","de ce e trimis jucatorul in lakeshire"}}},fp="16,171,27.233.0,21.242.0,40.115.0,40.118.0,47.154.0,51.142.0,57.178.0,48.86.0"}
P.entries["quest:1190"] = {n="Keeping Pace",s="Pozzik este sigur ca fratii Brassbolts au descoperit un nou material de constructie. Masinile lor merg mai repede ca inainte, dar planurile si restul datelor din cursele lor nu s-au schimbat. Rizzle Brassbolts s-a concentrat aproape fara incetare asupra planurilor acestei descoperiri, iar Zamek poate crea o diversiune, ca sa le poti fura. Aceasta misiune urmeaza dupa News for Fizzle.",h="Pozzik este sigur ca fratii Brassbolts au descoperit un nou material de constructie.",kw={"brassbolts","diversiune","pozzik","masina de curse","rizzle brassbolts","scheme","shimmering flats","thousand needles","zamek"},sec={{t="Mai rapid decat o arata cifrele",b="Pozzik nu gaseste decat o singura explicatie pentru viteza cu care au ajuns sa mearga masinile fratilor Brassbolts: un material de constructie nou. Proiectele lor si tot ce s-a adunat din curse par la fel ca inainte. Se stie ca Rizzle Brassbolts a ramas aproape permanent concentrat asupra planurilor pentru aceasta descoperire."},{t="O diversiune din partea lui Zamek",b="Zamek poate crea o diversiune, iar cat timp aceasta dureaza, furi planurile lui Rizzle. Pozzik, de pe Shimmering Flats, le vrea."},{t="Pergamentul furat",b="Planurile se dovedesc a fi un sul cu notite si schite, mazgalite in graba, despre rafinarea unei materii prime."}},faq={{q="De ce vrea Pozzik planurile lui Rizzle?",a="Masinile fratilor Brassbolts merg mai repede, desi proiectele si datele lor au ramas neschimbate. Pozzik concluzioneaza ca au gasit un material de constructie nou si vrea planurile in care Rizzle a fost atat de absorbit.",al={"motivul lui pozzik","de ce a furat planurile brassbolts","motivul pentru keeping pace"}},{q="Cine ajuta sa-i distraga atentia lui Rizzle Brassbolts?",a="Zamek poate crea o diversiune, oferindu-ti ocazia sa furi planurile lui Rizzle.",al={"cine creeaza diversiunea","rolul lui zamek","cum sa-l distragi pe rizzle"}},{q="Pentru cine sunt furate planurile?",a="Pentru Pozzik, care se afla in Shimmering Flats din Thousand Needles.",al={"unde este keeping pace","locatia keeping pace"}},{q="Ce urmeaza inaintea acestui pas?",a="Urmeaza dupa News for Fizzle.",al={"conditia prealabila pentru Keeping Pace","ce misiune precede Keeping Pace"}},{q="Ce urmeaza dupa asigurarea planurilor?",a="Lantul continua cu Rizzle's Schematics.",al={"care este urmatoarea misiune","dupa Keeping Pace"}}},fp="12,355,27.304.0,22.126.0,17.108.1,36.196.0,37.76.0,29.63.0,28.27.0,38.45.0"}
P.entries["quest:1191"] = {n="Zamek's Distraction",s="Zamek poate crea diversiunea ceruta de Keeping Pace. Acest pas are loc in mijlocul acelei etape, iar Keeping Pace nu poate fi incheiata fara el.",h="Zamek poate crea diversiunea ceruta de Keeping Pace.",kw={"distragere","tinerea pasului","thousand needles","zamek"},sec={{t="O diversiune binevenita",b="In timp ce te ocupi de Keeping Pace, Zamek poate crea o diversiune. Cand se intampla asta, Rizzle isi paraseste coliba, iar planurile Indurium raman nesupravegheate."}},faq={{q="Cine ofera Zamek's Distraction?",a="Zamek, in Thousand Needles.",al={"cine incepe zameks distraction","cel care da misiunea lui zamek","de unde iau zameks distraction"}},{q="Ce legatura are aceasta cu Keeping Pace?",a="Se primeste in timpul Keeping Pace, iar acea etapa nu poate fi incheiata fara el.",al={"este necesar pentru Keeping Pace","Keeping Pace de la Zamek","legatura cu Keeping Pace"}},{q="Ce efect are diversiunea?",a="Rizzle isi paraseste coliba, iar planurile sale raman in urma.",al={"ce se intampla cand zamek distrage atentia","rizzle paraseste coliba"}},{q="Pot aventurierii din Alliance si Horde sa colaboreze cu Zamek?",a="Da. Este neutra si deschisa ambelor factiuni.",al={"este zamek neutru","zamek pentru Alliance sau Horde","cine poate face diversiunea lui zamek"}}},fp="19,158,18.153.0,30.27.0,37.98.0,27.53.0,56.43.0"}
P.entries["quest:1192"] = {n="Indurium Ore",s="Pozzik planuieste sa foloseasca indurium pentru a fabrica mai multe piese ale masinilor de curse, ceea ce necesita mult minereu brut. Minereul se gaseste la sapatura Uldaman din Badlands, peste mare, in Khaz Modan. Gnomii isi fac deja rost de propriul minereu, iar Pozzik vrea sa tina pasul cu ei.",h="Pozzik planuieste sa foloseasca indurium pentru a fabrica mai multe piese ale masinilor de curse, ceea ce...",kw={"badlands","indurium","minereu de indurium","pozzik","piloti de curse","thousand needles","uldaman"},sec={{t="Minereu din Uldaman",b="Pozzik cere patru bucati de minereu brut de indurium. Se gaseste la sapaturile din Uldaman, in Badlands, peste mare, in Khaz Modan. Gnomes isi procura deja propriile rezerve, asa ca Pozzik vrea si el o cantitate. Aceasta sarcina urmeaza dupa Rizzle's Schematics."}},faq={{q="De ce vrea Pozzik minereu de indurium?",a="Vrea sa foloseasca indurium pentru mai multe piese ale masinilor de curse, iar pentru asta este nevoie de mult minereu brut.",al={"la ce foloseste indurium","de ce indurium ore","scopul indurium al lui Pozzik"}},{q="Unde se gaseste minereul de indurium?",a="La situl de excavare Uldaman din Badlands, peste mare, in Khaz Modan.",al={"unde gasesc minereu de indurium","locatia induriumului","de unde obtin minereu de indurium"}},{q="De ce este important sa obtii minereul?",a="Gnomii pun deja mana pe propriul indurium, iar Pozzik vrea sa tina pasul cu ei.",al={"de ce sa te grabesti cu indurium","rivalitatea gnomilor pentru indurium"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa Rizzle's Schematics, care la randul ei urmeaza dupa Keeping Pace.",al={"cerinta prealabila pentru indurium ore","misiunea anterioara din seria indurium"}}},fp="12,280,16.242.0,34.99.0,32.65.0,34.97.0,22.66.0"}
P.entries["quest:1194"] = {n="Rizzle's Schematics",s="Planurile nesupravegheate ale lui Rizzle descriu rafinarea minereului de indurium. Notitele mazgalite indica sapatura Dwarves de la Uldaman, in Badlands, drept sursa minereului, iar multe dintre celelalte insemnari sunt despre rezistenta la caldura. O bucata de minereu brut sta pe planuri drept greutate pentru hartie, iar tu duci aceasta mostra la Pozzik, in Shimmering Flats. Aceasta misiune urmeaza dupa Keeping Pace.",h="Planurile nesupravegheate ale lui Rizzle descriu rafinarea minereului de indurium.",kw={"badlands","indurium","pozzik","rizzle","scheme","shimmering flats","uldaman"},sec={{t="Note despre Indurium",b="Schemele lui Rizzle descriu rafinarea minereului de indurium. Mazgaliturile lui Rizzle indica sapaturile dwarves din Uldaman, in Badlands, drept sursa minereului. Multe dintre celelalte insemnari privesc rezistenta lui la caldura. O bucata de minereu de indurium brut tine planurile pe loc, ca greutate pentru hartie, iar aceasta este mostra pe care o duci la Pozzik."},{t="Verdictul lui Pozzik",b="Pozzik gaseste induriumul interesant. Daca rezista la caldura in masura in care spui, asta ar putea explica cat de mult au progresat gnomii in ultima vreme. Mostra va fi nepretuita pentru teste, desi Pozzik va avea nevoie de mai mult ca sa fie de vreun folos real."}},faq={{q="De unde isi procura Rizzle minereul de indurium?",a="Insemnarile lui Rizzle indica sapatura dwarves de la Uldaman, in Badlands.",al={"de unde provine indurium","sursa minereului de indurium","locatia induriumului lui rizzle"}},{q="Ce spun notitele lui Rizzle despre indurium?",a="Notitele lui Rizzle descriu rafinarea minereului, iar multe dintre celelalte notite sunt despre rezistenta lui la caldura.",al={"la ce foloseste induriumul","de ce indurium","proprietatile induriumului"}},{q="Cine primeste mostra de indurium?",a="Duci mostra la Pozzik, pe Shimmering Flats.",al={"cui predau asta","cine vrea mostra de indurium","predare pentru pozzik"}},{q="De unde provine acest esantion?",a="Un bulgare de minereu brut de indurium tinea apasate planurile lui Rizzle, ca greutate pentru hartii.",al={"unde a fost gasita mostra","prespapierul lui rizzle"}}},fp="19,356,17.329.0,16.242.1,39.71.0,42.110.0,33.55.0,32.76.0"}
P.entries["quest:1195"] = {n="Flacara Sacra"}
P.entries["quest:1196"] = {n="Flacara Sacra"}
P.entries["quest:1197"] = {n="Flacara Sacra"}
P.entries["quest:1198"] = {n="In Search of Thaelrid",s="In Search of Thaelrid este o misiune de recunoastere a Alliance, trimisa din Darnassus in numele Argent Dawn. Dawnwatcher Shaedlass le cere aventurierilor sa patrunda in ruinele scufundate din Blackfathom Deeps pentru a gasi o iscoada disparuta, care a disparut in timp ce cerceta o alianta periculoasa intre naga si cultisti. Este una dintre primele ocazii de a intalni influenta Argent Dawn dincolo de obisnuita lor straja nordica.",h="In Search of Thaelrid este o misiune de recunoastere a Alliance, trimisa din Darnassus in numele Argent Dawn.",kw={"argent dawn","ashenvale","blackfathom deeps","darnassus","naga","shaedlass","thaelrid","twilight's hammer"},ang={["class:Paladin"]="Paladins de partea Argent Dawn privesc straja solitara a lui Thaelrid ca pe o datorie solemna de a apara lumea de umbra si coruperea care se raspandesc.",["faction:Alliance"]="Aceasta misiune marcheaza una dintre primele ocazii pentru aventurierii din Alliance de a-si castiga bunavointa si de a sluji alaturi de Argent Dawn.",["race:NightElf"]="Pangarirea stravechiului Templu al lui Elune din Blackfathom Deeps face ca ajutorul dat celor din Argent Dawn sa fie esential pentru recuperarea mostenirii sacre a night elves."},sec={{t="Ochii din Darnassus",b="Desi Argent Dawn este cunoscuta mai ales pentru ca tine piept Scourge in ruinele molipsite din Lordaeron, vigilenta sa se extinde in intreaga Kalimdor. Stabilita in Darnassus, Dawnwatcher Shaedlass aduna zvonuri si informatii despre amenintarile supranaturale care apar in lume. Cand au aparut relatari tulburatoare potrivit carora naga din adancuri si fanaticii apocalipsei din Twilight's Hammer incheiasera un pact in incaperile inundate din Blackfathom Deeps, de-a lungul tarmului Ashenvale, ordinul a recunoscut potentialul dezastruos al situatiei."},{t="Cercetasul disparut",b="Pentru a verifica veridicitatea zvonurilor despre coasta, Shaedlass l-a trimis pe Argent Guard Thaelrid sa se infiltreze in taina in cavernele subterane. Au trecut saptamani fara vesti, lasandu-l pe Strajerul Zorilor in intuneric, in timp ce ceilalti cercetasi ai sai erau implicati in misiuni separate. Temandu-se ca Thaelrid fie cazuse in lupta, fie fusese capturat de puterile intunecate salasluind sub valuri, el cere ajutorul calatorilor incercati, destul de curajosi sa patrunda in Blackfathom Deeps si sa-l aduca inapoi in viata."}},faq={{q="De ce este Argent Dawn interesata de Blackfathom Deeps?",a="Argent Dawn supravegheaza toate amenintarile existentiale si corupatoare de pe Azeroth, nu doar pe cei strigoi din Eastern Kingdoms. Posibilitatea ca naga stravechi sa colaboreze cu fanaticii cultisti ai Twilight's Hammer in Kalimdor reprezinta un rau destabilizator, care le cere atentia.",al={"de ce este Argent Dawn aici","Argent Dawn in Blackfathom","naga din Argent Dawn"}},{q="Cine este Dawnwatcher Shaedlass?",a="Dawnwatcher Shaedlass este un agent al Argent Dawn aflat in capitala Night Elf, Darnassus. Principala sa indatorire este sa adune informatii, sa identifice locurile unde ordinul trebuie sa intervina de urgenta si sa trimita investigatori pentru evaluarea crizelor regionale.",al={"cine este Shaedlass","cel care ofera misiunea, Shaedlass","rolul lui Dawnwatcher Shaedlass"}},{q="Cine este Argent Guard Thaelrid?",a="Argent Guard Thaelrid este un agent al Argent Dawn trimis sa cerceteze Blackfathom Deeps. Misiunea lui era sa determine adevarata forta si intentiile cultistilor si naga care salasluiesc in cavernele inundate.",al={"cine este thaelrid","povestea lui thaelrid","cercetasul disparut thaelrid"}},{q="Unde poate fi gasit Thaelrid?",a="Argent Guard Thaelrid a reusit sa se infiltreze in adancurile subterane ale Blackfathom Deeps, de-a lungul Zoram Strand, in Ashenvale, desi ramane izolat adanc in pesteri, asteptand intariri.",al={"locatia lui Thaelrid","unde se afla Thaelrid","gaseste-l pe Thaelrid in BFD"}},{q="Ce se intampla dupa ce il gasesti pe Thaelrid?",a="Dupa ce este gasit, Thaelrid dezvaluie adevarata natura perfida a ritualului desfasurat in ruine si ii trimite imediat pe aventurieri sa atace conducerea cultului, in misiunea Blackfathom Villainy.",al={"ce urmeaza","continuarea dupa Thaelrid","urmatoarea misiune dupa Thaelrid"}},{q="Pot jucatorii Horde sa accepte aceasta misiune?",a="Misiunea este oferita de Dawnwatcher Shaedlass in Darnassus si se adreseaza aventurierilor Alliance. Aventurierii Horde o pot accepta si ei daca ajung la el.",al={"horde in search of thaelrid","poate horde sa faca aceasta misiune","horde thaelrid"}}},fx={["4b9c6d96"]={q="De ce vrea Dawnwatcher Shaedlass sa-l gasesti pe Thaelrid?",a="Shaedlass strange informatii pentru Argent Dawn, ca sa urmareasca raul tot mai mare din Kalimdor. Cu cateva saptamani in urma, l-a trimis pe Argent Guard Thaelrid sa cerceteze zvonuri tulburatoare despre o alianta intre naga si Twilight's Hammer in Blackfathom Deeps. Cum nu a primit vesti de la el, se teme de ce e mai rau si trebuie sa afle atat ce s-a intamplat cu cercetasul, cat si daca planul sinistru care prinde radacini de-a lungul coastei din Ashenvale este real.",al={"de ce sa-l gasesc pe thaelrid","motivul lui shaedlass","de ce sa fiu trimis la blackfathom deeps"}},["3832a285"]={q="De ce trimite Shaedlass un aventurier in locul propriilor cercetasi?",a="Prezenta Argent Dawn in Darnassus este redusa, iar Shaedlass spune ca toti ceilalti cercetasi ai sai sunt prinsi cu propriile misiuni urgente prin tinuturi. Cum Thaelrid a disparut si nu mai are agenti disponibili, trebuie sa se bazeze pe aventurieri capabili si dornici sa patrunda in adancurile primejdioase in locul sau.",al={"de ce eu in In Search of Thaelrid","de ce nu trimite cercetasi Argent Dawn"}}},fp="21,424,17.537.0,17.468.0,55.291.0,29.259.0,29.229.0,28.208.0,36.219.1,36.155.0"}
P.entries["quest:1199"] = {n="Twilight Falls",s="Argent Guard Manados, aflat in Darnassus, le cere campionilor Alliance sa loveasca in cultistii Twilight's Hammer adunati in Blackfathom Deeps. Cultul intunecat s-a aliat cu naga asemanatori serpilor pentru a ocupa templul night elf scufundat de pe coasta Ashenvale. Adunand pandantivele cultistilor cazuti, aventurierii dau o lovitura planurilor lor marsave de a trezi rele stravechi.",h="Argent Guard Manados, aflat in Darnassus, le cere campionilor Alliance sa loveasca in cultistii Twilight's...",kw={"argent dawn","argent guard manados","ashenvale","blackfathom deeps","darnassus","manados","naga","old gods","twilight falls","twilight pendant","twilight's hammer"},ang={["class:Paladin"]="Ca aparatori ai Holy Light, aliati cu ordine precum Argent Dawn, paladinii considera venerarea depradata a Old God de catre Twilight's Hammer o abominatie ce trebuie curatata prin dreptate.",["class:Priest"]="Preotii percep cu usurinta pervertirea fantanii lunare din templu, odinioara sacra, si soaptele intunecate, care tulbura mintea si-i imping pe cultisti tot mai adanc in nebunie.",["faction:Alliance"]="Twilight's Hammer reprezinta un pericol tot mai mare chiar la sud de Darkshore, astfel ca purificarea Blackfathom Deeps este esentiala pentru securizarea nordului Kalimdor.",["race:NightElf"]="Pangarirea unui templu sacru si a unei fantani lunare de catre adepti perfizi ai Old God si naga este o ofensa directa la adresa lui Elune si a tinuturilor ancestrale din Ashenvale."},sec={{t="Un Sanctum profanat",b="Sub stancile aspre ale Zoram Strand din Ashenvale se afla ruinele Blackfathom Deeps. Odinioara un templu sacru al elfilor noptii, inchinat lui Elune si adapostind o puternica fantana lunara, a fost sfaramat si scufundat in adancuri in timpul Sundering. Astazi, apele sacre au devenit imputite si respingatoare, napadite de naga insetati de sange si cultisti fanatici care venereaza forte mult mai intunecate decat marea."},{t="Soaptele Old Gods",b="Twilight's Hammer este un cult apocaliptic dedicat Old Gods haotici, urmarind sa readuca la viata patronii lor primordiali si sa cufunde lumea in nebunie si ruina. Rapoartele care ajung in Darnassus confirma ca acesti smintiti s-au aliat cu naga care locuiesc in Blackfathom Deeps. In adancul salilor scufundate, ei savarsesc ritualuri blasfematoare, folosind apele intinate ale templului scufundat pentru a alimenta renasterea stapanilor lor intunecati."},{t="Veghea Argent Dawn",b="Stationat in Darnassus, Argent Guard Manados reprezinta vigilenta Argent Dawn impotriva tuturor plagilor care ameninta Azeroth. Dandu-si seama ca depravarile din Blackfathom Deeps ar putea dezlantui orori asupra tuturor raselor civilizate, ordinul le ofera recunoastere si ajutor eroilor dispusi sa coboare in labirintul inundat, sa-i nimiceasca pe cultisti si sa le smulga Twilight Pendants de la gat, drept dovada a infrangerii lor."}},faq={{q="Cine este Argent Guard Manados?",a="Argent Guard Manados este un emisar al Argent Dawn, stationat in Darnassus. Actionand ca ochii si urechile ordinului sau in Kalimdor, supravegheaza cultele malefice si fortele intunecate care ameninta tinutul si recruteaza aventurieri pentru a le nimici.",al={"Manados","cine ofera Twilight Falls","locatia lui Argent Guard Manados"}},{q="De ce este Argent Dawn ingrijorat de Blackfathom Deeps?",a="Desi Argent Dawn este cunoscuta mai ales pentru lupta impotriva Scourge in Lordaeron, carta sa prevede confruntarea oricarui rau existential si supranatural. Reaparitia venerarii Old God si alianta dintre adeptii cultului si naga in Kalimdor reprezinta o catastrofa globala daca nu este oprita.",al={"de ce Argent Dawn Darnassus","argent dawn blackfathom"}},{q="Ce este Twilight's Hammer?",a="Twilight's Hammer este un cult fanatic al apocalipsei care se inchina Old Gods - entitati haotice, primordiale, inchise de multa vreme sub pamant. Cultistii cred in grabirea unui sfarsit apocaliptic, in care stapanii lor intunecati se vor ridica din nou pentru a recladi lumea in teroare si nebunie.",al={"cultul Twilight's Hammer","cine sunt cei din Twilight's Hammer","Twilight's Hammer"}},{q="La ce erau folosite Twilight Pendants?",a="Twilight Pendants sunt talismane intunecate purtate de membrii Twilight's Hammer. Simbolizand loialitatea lor fata de entitatile haotice carora li se inchina, acestea sunt adunate de Argent Dawn ca dovada verificabila ca un cultist a fost ucis si neutralizat.",al={"Twilight Pendant lore","ce sunt Twilight Pendants"}},{q="Ce era Blackfathom Deeps initial?",a="Cu mult inainte de coruperea sa, Blackfathom Deeps era un templu magnific al elfilor noptii, inchinat zeitei lunii Elune. Era vestit pentru fantana lunii de o putere exceptionala, inainte ca Great Sundering sa despice pamantul si sa-i scufunde salile sub mare.",al={"istoria Blackfathom","istoria templului BFD","moonwell-ul Blackfathom"}},{q="De ce colaboreaza Twilight's Hammer cu naga?",a="Nu se cunosc pe deplin motivele aliantei lor, dar ambele parti sunt atrase de puterea intunecata care se agita in templul scufundat. In Blackfathom Deeps, cooperarea le permite adeptilor cultului sa ajunga in siguranta la vechile incaperi inundate, in timp ce naga profita de vrajile abjecte si ritualurile de sacrificiu ale cultului.",al={"cultisti naga din Alliance","naga din bfd si Alliance"}}},fp="14,384,17.393.0,24.443.0,28.423.0,28.243.0,57.285.0,30.278.0,41.246.0,38.262.0,52.303.0"}
P.entries["quest:12"] = {n="The People's Militia",s="La Sentinel Hill, Gryan Stoutmantle iti pune la incercare curajul pentru People's Militia. Tronul din Stormwind e distras, iar armata sa lipseste, asa ca voluntarii locali apara Westfall de Defias Brotherhood. Incepi prin a-i alunga pe proscrisi de pe campurile si din minele nordice.",h="La Sentinel Hill, Gryan Stoutmantle iti pune la incercare curajul pentru People's Militia.",kw={"defias smuggler","defias trapper","furlbrow","gryan stoutmantle","jangolode","molsen farm","militia poporului","sentinel hill","westfall"},ang={["class:Paladin"]="Ca paladin, ii protejezi pe cei lipsiti de aparare si ii pedepsesti pe nelegiuitii care ii prigonesc pe cei vulnerabili.",["faction:Alliance"]="Ca aventurier al Alliance, vezi ruptura din regat: nobilimea din Stormwind ramane in spatele zidurilor capitalei, in timp ce colonistii de rand apara Westfall de la ruina.",["race:Human"]="Ca human al regatului, vezi cum familiile muncitoare si generatiile de fermieri sufera din cauza atacurilor banditilor, in timp ce autoritatile regale inchid ochii."},sec={{t="Pretul pacii",b="Westfall asigura odinioara hrana pentru Stormwind, dar acum regiunea este napadita de haiduci, vagabonzi si hoti. Cum capitala nu trimite soldati regali sa patruleze tinutul, Gryan Stoutmantle a organizat People's Militia in Sentinel Hill, ca forta locala de aparare. El cere masuri hotarate pentru recucerirea Westfall. Oricine doreste sa poarte insemnul militiei trebuie sa dovedeasca faptul ca stie sa lupte si ca ii va apara pe colonistii nevinovati."},{t="Curatarea hambarului",b="Inainte sa le incredinteze recrutilor noi operatiuni mai ample, Stoutmantle ii trimite impotriva fortelor Defias de langa gospodariile din nord. Defias Trappers si Smugglers actioneaza pe fata langa Jangolode Mine, Molsen Farm si Furlbrow's Pumpkin Patch, jefuind provizii si atacand calatorii prin surprindere. Le poti intrerupe incursiunile alungandu-i, dovedindu-le astfel cercetasilor lui Stoutmantle ca ai curajul necesar pentru o lupta lunga impotriva nelegiuirilor."}},faq={{q="Ce este People's Militia?",a="People's Militia este o armata de voluntari organizata de Gryan Stoutmantle si cu baza la Sentinel Hill. Fermierii locali, veteranii si oamenii de rand i-au format randurile ca sa apere Westfall de Defias Brotherhood, in vreme ce armata regala din Stormwind a refuzat sau nu a reusit sa garnizoneze regiunea.",al={"militia poporului","cine este militia","ce este militia poporului"}},{q="De ce nu-si trimite Stormwind armata regala?",a="In lipsa regelui Varian Wrynn, casa nobiliara House of Nobles si conducerea consiliului din Stormwind si-au indreptat resursele regatului in alta parte. Teritorii rurale indepartate, precum Westfall, sunt lasate sa se descurce singure in fata bandelor de proscrisi tot mai numeroase.",al={"unde este armata","de ce nu sunt garzi in Westfall","garnizoana Stormwind"}},{q="Unde pot gasi Defias Trappers si Smugglers?",a="Capcanele si contrabandistii Defias actioneaza in nordul tinutului Westfall, mai ales in jurul Furlbrow's Pumpkin Farm, Molsen Farm si intrarii in Jangolode Mine.",al={"locatia vanatorului cu capcane","locatia contrabandistului","unde sunt vanatorii cu capcane"}},{q="Cine este Gryan Stoutmantle?",a="Gryan Stoutmantle este un veteran incercat, care conduce People's Militia la Sentinel Hill. El aduna voluntari pentru a-i apara pe colonistii din Westfall, a-i alunga pe Defias Brotherhood si a restabili ordinea in tinut.",al={"cine este Stoutmantle","povestea lui Gryan Stoutmantle","conducatorul militiei"}},{q="Duce aceasta misiune la mai multe sarcini pentru militie?",a="Da. Aceasta proba de inceput duce la indatoriri suplimentare pentru voluntarii care reusesc, acestia urcand in ranguri tot mai periculoase ale Defias Brotherhood de-a lungul campiilor din Westfall.",al={"face parte dintr-un lant","urmatoarea misiune","progresul militiei"}},{q="Ce se intampla la Furlbrow's Pumpkin Farm?",a="Defias Brotherhood i-a alungat pe Furlbrows de pe proprietatea lor si le-a preluat terenurile agricole. Haiduci si scotocitori jefuiesc acum campurile si terorizeaza drumurile nordice.",al={"ferma furlbrow","ce s-a intamplat cu furlbrows","ferma de dovleci"}}},fx={b0313ac5={q="De ce vrea Gryan Stoutmantle sa se faca acest lucru?",a="Gryan Stoutmantle conduce People's Militia cu un singur scop: sa apere Westfall si sa readuca pacea, alungand sindicatul criminal care-i napadeste terenurile agricole. Cete de proscrisi Defias jefuiesc gospodarii precum fermele Molsen si Furlbrow. Eliminandu-le capcanele si contrabandistii, Gryan vrea sa le respinga prezenta tot mai puternica si sa vada daca ai hotararea de a lupta pentru oamenii din Westfall.",al={"de ce sa omori capcani si contrabandisti","motivul lui Gryan Stoutmantle","scopul misiunii People's Militia"}},["1cf2b131"]={q="Cine sunt Defias Trappers si Smugglers?",a="Acestia sunt agenti de rand aflati la inceputul carierei, membri ai Defias Brotherhood, un sindicat nemilos de hoti si haiduci care i-a alungat pe fermieri de pe pamanturile lor. Capcanii si contrabandistii pandesc in jurul domeniilor confiscate, precum Molsen Farm si Jangolode Mine, asigurandu-si teritoriul si adunand bunuri ilicite pentru a sustine controlul de fier al Brotherhood asupra tinutului.",al={"capcanele Defias","contrabandistii Defias","cine sunt proscrisii Defias"}},b416da40={q="De ce are Gryan Stoutmantle nevoie de tine ca sa lupti impotriva Defias?",a="People's Militia este o forta de voluntari impinsa pana la limita si abandonata complet de armata regala din Stormwind. Gryan nu-si poate permite sa-si trimita cei cativa aparatori ramasi in lupte riscante, slabind astfel paza de pe Sentinel Hill. Se bazeaza pe voluntari si mercenari capabili, cerandu-ti sa-ti dovedesti valoarea si devotamentul inainte de a te primi oficial in randurile militiei.",al={"de ce nu se lupta militia cu ei","de ce eu, Gryan?","de ce sa recrutezi straini"}}},fp="20,267,18.396.0,24.414.0,29.278.0,43.238.0,47.152.0,25.216.0,49.167.0,45.179.0"}
P.entries["quest:120"] = {n="Messenger to Stormwind",s="Magistrate Solomon din Lakeshire are disperata nevoie de ajutor militar, caci gnollii si orcs Blackrock incercuiesc orasul. Neputand renunta la trupele garnizoanei, el trimite un aventurier sa duca 'The State of Lakeshire' direct la General Marcus Jonathan, in Stormwind City.",h="Magistrate Solomon din Lakeshire are disperata nevoie de ajutor militar, caci gnollii si orcs Blackrock...",kw={"generalul Marcus Jonathan","Lakeshire","Magistrate Solomon","Messenger to Stormwind","Redridge Mountains","intariri","armata Stormwind","starea din Lakeshire"},ang={["class:Paladin"]="A duce strigatele celor disperati la conducatori paralizati de politica de curte pune la incercare virtutile fundamentale ale datoriei, protectiei si actiunii drepte.",["faction:Alliance"]="Aceasta misiune dezvaluie tensiunea tot mai mare dintre capitala prospera si asezarile de granita neglijate, care lupta pentru supravietuire la marginile regatului.",["race:Human"]="Redridge este teritoriu ancestral al Stormwindului; sa-si vada semenii abandonati in spatele birocratiei doare orice patriot al regatului."},sec={{t="Un strigat peste munti",b="Lakeshire este in pragul colapsului. Haitele de Gnoll disputa fiecare drum, orcii Blackrock ataca din nord, iar garzile locale sunt suprasolicitate. Magistrate Solomon nu-si poate permite sa trimita oameni inarmati intr-o calatorie de mai multe zile pana la capitala, asa ca un calator independent trebuie sa duca apelul sau oficial pentru trupe regulate pana la portile orasului."},{t="Birocratia si High Seat",b="Predarea raportului magistratului il aduce pe aventurier fata in fata cu General Marcus Jonathan, comandantul apararii din Stormwind. Desi Jonathan respecta conducerea lui Solomon si recunoaste urgenta situatiei, protocolul armatei il impiedica sa mobilizeze trupele fara o porunca regala. Apararea lui Redridge va trebui sa astepte consultarea oficiala cu tanarul King Anduin si consiliul regentei."}},faq={{q="De ce are nevoie Magistrate Solomon de un mesager?",a="Lakeshire este asediat fara incetare de orci Blackrock si gnolli. Fiecare gardian local este necesar pentru a apara orasul si a tine podul, asa ca Solomon le incredinteaza aventurierilor aflati in trecere apelurile sale urgente pentru ajutor.",al={"de ce sa ma trimita","de ce un mesager","mesagerul lui Solomon"}},{q="Ce contine raportul 'The State of Lakeshire'?",a="Este o dare de seama oficiala asupra crizei care cuprinde Redridge Mountains; detaliaza cresterea numarului de inamici, pierderile si caderea iminenta a orasului daca nu sunt trimise trupe regulate din capitala.",al={"situatia din lakeshire","raportul lui solomon","ce spune scrisoarea"}},{q="Cine este General Marcus Jonathan?",a="General Marcus Jonathan este comandantul Stormwind City Guard si un lider de rang inalt in cadrul Stormwind Army. El supravegheaza portile orasului si raporteaza direct lui Highlord Bolvar Fordragon si coroanei.",al={"Marcus Jonathan","cine este generalul","generalul din Stormwind"}},{q="De ce nu trimite General Jonathan soldati imediat?",a="General Jonathan nu poate mobiliza armata din proprie autoritate. Trebuie sa prezinte raportul lui Solomon in fata regelui si a consiliului regentei pentru a obtine un mandat regal oficial, inainte ca trupele sa poata porni la drum.",al={"de ce nu sunt trupe","unde sunt intaririle","raspunsul lui Jonathan"}},{q="Este drumul dintre Lakeshire si Stormwind sigur?",a="Nu. Drumurile prin Redridge si spre Elwynn sunt bantuite de cete agresive de gnolli si de talhari Defias, ceea ce face calatoria periculoasa pentru mesagerii singuratici.",al={"drumul spre stormwind","calatorie in siguranta","drumul din redridge"}},{q="Ajunge Stormwind sa trimita ajutor?",a="Inertia politica si tulburarile din capitala intarzie orice raspuns militar real, lasand Lakeshire si magistratul sau sa se bazeze aproape in intregime pe mercenari si voluntari.",al={"sosesc intariri","ajutor pentru lakeshire"}}},fx={["3f8e995f"]={q="De ce trimite Magistrate Solomon un aventurier in locul unui gardian al orasului?",a="Lakeshire este intins la limita absoluta. Orasul se afla sub presiunea constanta a gnollilor si a orcs Blackrock care inainteaza dinspre dealurile din jur. Magistrate Solomon pur si simplu nu poate lua de pe liniile de lupta niciun aparator jurat sau paznic fara a lasa apararea asezarii grav compromisa. Incredintarea apelului catre Stormwind unui aventurier in putere ii permite fiecarei santinele locale sa ramana la postul ei.",al={"de ce ma trimite","de ce nu livreaza gardienii lacului","de ce un aventurier ca mesager"}}},fp="22,259,26.356.0,29.384.0,45.212.0,43.206.0,31.211.0,54.197.0,49.156.0,35.166.1"}
P.entries["quest:1200"] = {n="Blackfathom Villainy",s="Blackfathom Villainy este o sarcina a Alliance, data de Argent Guard Thaelrid in adancul templului subteran in ruina Blackfathom Deeps. Pentru a opri sacrificiile cumplite care hranesc o oroare straveche, eroii trebuie sa-l ucida pe conducatorul cultului, Twilight Lord Kelris, si sa duca dovada la Argent Dawn din Darnassus.",h="Blackfathom Villainy este o sarcina a Alliance, data de Argent Guard Thaelrid in adancul templului subteran...",kw={"aku'mai","argent dawn","blackfathom","darnassus","deeps","elune","kelris","moon well","selgorm","thaelrid","twilight's hammer"},ang={["class:Paladin"]="Sa raspunzi chemarii Argent Dawn si sa ucizi un cultist care sacrifica oameni nevinovati unor orori primordiale este insasi definitia razbunarii sfinte.",["class:Priest"]="Oprirea lui Kelris pune capat profanarii blasfematoare a apelor sfintite, odinioara venerate ca sfinte din devotiune fata de divinitate.",["faction:Alliance"]="Ajutand Argent Dawn impotriva lui Kelris, Alliance contribuie la apararea granitelor vulnerabile din Ashenvale impotriva infiltrarii insidioase a cultistilor.",["race:NightElf"]="Razbunarea profanarii unui templu stravechi al Elunei si purificarea Moon Well-ului otravit lovesc direct in inima mostenirii kaldorei."},sec={{t="Un sanctuar profanat",b="Pestera inundata cunoscuta acum drept Blackfathom Deeps a fost candva un templu subteran imaculat, inchinat lui Elune. Trecutul sau sacru s-a naruit cand coruptia unui Old God stravechi s-a strecurat prin stanca, pangarind Moon Well al templului si eliberandu-l pe Aku'mai, un slujitor lacom al acelei intunecimi primordiale. In urma acestei profanari, cultul Twilight's Hammer a incheiat o alianta necurata cu naga din tinut, transformand salile sfinte intr-o vizuina a crimelor ritualice."},{t="Ruga garzii cazute",b="Argent Guard Thaelrid a patruns in Blackfathom Deeps in numele ordinului sau, dar a fost grav ranit si si-a pierdut puterile. Prins printre dusmani, Thaelrid intelege ca nu-si poate duce singur misiunea la capat. Ii implora pe calatorii curajosi ai Alliance care ajung la el sa-l ucida pe Twilight Lord Kelris, cultistul sinistru care orchestreaza jertfirea nevinovatilor catre Aku'mai in schimbul puterii intunecate."},{t="Dreptate in Darnassus",b="Infatisarea capului retezat al lui Kelris inaintea lui Dawnwatcher Selgorm, la Craftsmen's Terrace din Darnassus, pune in sfarsit capat unei vanatori indelungate si tulburatoare. Argent Dawn se temuse ca Kelris murise sau se pierduse in umbra, avand in vedere ca se implica mereu ori de cate ori fortele intunecate se agitau in Kalimdor. Uciderea lui asigura o victorie esentiala impotriva planurilor cultului din Ashenvale."}},faq={{q="Cine este Argent Guard Thaelrid?",a="Thaelrid este un agent al Argent Dawn, trimis sa cerceteze umbra tot mai amenintatoare din Blackfathom Deeps. Grav ranit in adancuri, nu mai are puterea necesara si este nevoit sa recruteze aventurieri aflati in trecere pentru a-l opri pe Kelris.",al={"cine este thaelrid","povestea lui thaelrid","garda Argent"}},{q="De ce este vizat Twilight Lord Kelris?",a="Kelris este conducatorul cultistilor din Twilight's Hammer care locuiesc in Blackfathom Deeps. El i-a sacrificat in mod sistematic pe captivii nevinovati lui Aku'mai, o fiara abjecta legata de Old Gods, in schimbul unei puteri malefice.",al={"cine este Kelris","de ce sa-l ucizi pe Kelris","Twilight Lord Kelris"}},{q="Cine este Dawnwatcher Selgorm?",a="Dawnwatcher Selgorm este un reprezentant al Argent Dawn stationat pe Craftsmen's Terrace, in Darnassus. Supravegheaza eforturile ordinului de a impiedica raspandirea coruptiei in nordul Kalimdorului.",al={"Selgorm din Darnassus","cine este Selgorm","Argent Dawn din Darnassus"}},{q="Care este istoria lui Blackfathom Deeps?",a="Inainte de a deveni o ascunzatoare scufundata, plina de monstri si cultisti, pesterile adaposteau un mare templu night elven inchinat zeitei Elune. Acesta a cazut in ruina dupa ce rautatea unui Old God s-a revarsat de jos si a pangarit sacru Moon Well.",al={"istoria bfd","ce a fost blackfathom deeps","templul lui elune din bfd"}},{q="Cine este Aku'mai?",a="Aku'mai este o creatura monstruoasa, asemanatoare unei hydra, aflata in slujba unui Old God, care s-a tarat afara din apele intinate de sub Blackfathom Deeps. Twilight's Hammer venereaza creatura si ii hraneste pe prizonieri, pentru a obtine binecuvantari intunecate.",al={"ce este akumai","povestea lui aku'mai","bestia akumai"}},{q="De ce lucreaza impreuna Twilight's Hammer si naga?",a="Motivele pactului lor nu sunt pe deplin cunoscute, dar in Blackfathom Deeps s-au aliat pentru a ocupa terenul templului in ruina, in timp ce cultul ii aduce sacrificii lui Aku'mai.",al={"cultisti Naga din Alliance","de ce sunt Naga in BFD","Twilight's Hammer si Naga"}}},fx={["96533b2d"]={q="De ce vrea Argent Guard Thaelrid sa-l ucida pe Twilight Lord Kelris?",a="Thaelrid a descoperit ca Twilight Lord Kelris si cultistii sai sacrifica captivi nevinovati lui Aku'mai, un slujitor al unui Old God, in schimbul puterii intunecate. Ca agent al Argent Dawn, Thaelrid este hotarat sa opreasca asemenea fapte malefice si sa puna capat macelului ritualic ingrozitor din templul in ruina.",al={"motivul lui thaelrid","de ce vrea thaelrid sa-l omoare pe kelris","de ce sa-l ucizi pe kelris"}},["101c08a2"]={q="La ce foloseste Head of Kelris?",a="Capul este o dovada de netagaduit a mortii conducatorului cultului. Dawnwatcher Selgorm si Argent Dawn credeau ca Kelris era mort sau disparut, dupa ani de fapte ticaloase savarsite pe ascuns in Kalimdor. Aducerea capului sau la Selgorm, in Darnassus, confirma ca domnia sa a terorii si a sacrificiilor sangeroase a luat in sfarsit sfarsit.",al={"capul lui Kelris","de ce am nevoie de capul lui Kelris","ce sa faci cu capul lui Kelris"}},["5d00ba2b"]={q="De ce nu-l poate ucide Argent Guard Thaelrid pe Kelris insusi?",a="Thaelrid se afla adanc in ruinele inundate, ranit si complet istovit. Puterile l-au parasit si nu-si poate croi drum prin cultisti si naga, daramite sa-l doboare singur pe Kelris. Se bazeaza pe tine sa duci misiunea la bun sfarsit in locul sau.",al={"de ce nu se lupta thaelrid cu kelris","de ce are thaelrid nevoie de mine","poate thaelrid sa-l ucida pe kelris"}}},fp="20,322,19.464.0,23.408.0,20.360.1,29.222.0,43.224.0,27.195.0,41.223.0,15.214.0,56.170.0"}
P.entries["quest:1201"] = {n="Theramore Spies",s="Armistitiul dintre Horde si Alliance este fragil, cu incaierari si actiuni secrete de ambele parti. Nazeer Bloodpike din Brackenwall Village vrea ca infiltratorii Alliance de la est de sat sa fie vanati si ucisi.",h="Armistitiul dintre Horde si Alliance este fragil, cu incaierari si actiuni secrete de ambele parti.",kw={"brackenwall","dustwallow","infiltratori","nazeer bloodpike","spioni","theramore"},sec={{t="Spioni la est de sat",b="Infiltratori ai Alliance s-au stabilit la est de Brackenwall Village, supraveghind asezarea si transmitand Theramore informatii despre miscarile Horde. Nazeer Bloodpike, seful local al spionilor, nu va tolera asa ceva. Esti trimis sa-i gasesti si sa-i ucizi pe infiltratori, pentru ca superiorii lor sa afle ca spionii de acest fel nu sunt bineveniti."}},faq={{q="Cine ordona uciderea infiltratilor din Theramore?",a="Nazeer Bloodpike, maestrul local al spionilor din Brackenwall Village.",al={"cine ofera misiunea theramore spies","misiunea de spionaj nazeer bloodpike","cine incepe theramore spies"}},{q="Unde se ascund infiltratorii?",a="La est de Brackenwall Village, pe insule.",al={"locatia infiltratorilor din theramore","unde gasesc theramore spies","locatiile infiltratorilor dustwallow"}},{q="De ce spioneaza cercetasii Brackenwall Village?",a="Ei supravegheaza satul si transmit Theramore informatii despre miscarile Horde.",al={"de ce spioneaza Human din Brackenwall","motivul spionilor din Brackenwall Village"}},{q="Ce urmeaza dupa ce te ocupi de spioni?",a="Urmatorul pas din poveste este The Theramore Docks.",al={"continuarea theramore spies","ce misiune urmeaza dupa theramore spies"}}},fp="15,217,25.298.0,51.61.0,34.44.0,47.74.0,40.50.0"}
P.entries["quest:1202"] = {n="The Theramore Docks"}
P.entries["quest:1203"] = {n="Jarl Needs a Blade",s="\"Swamp Eye\" Jarl, din Dustwallow Marsh, are de facut niste taieri, dar nu spune ce. Jarl vrea o anumita lama, o spada cu doua taisuri din moonsteel, si nu vrea sa pierzi vremea.",h="\"Swamp Eye\" Jarl, din Dustwallow Marsh, are de facut niste taieri, dar nu spune ce.",kw={"Dustwallow Marsh","jarl","Moonsteel Broadsword","Swamp Eye Jarl","lama de lupta"},sec={{t="O anumita lama",b="\"Swamp Eye\" Jarl are ceva de taiat, dar nu poate spune ce anume. Jarl are nevoie de o anumita lama, pe care unii o numesc spada lata din otel lunar, iar Jarl o numeste lama de taiat. Ai putea gasi una in oras sau un fierar ar putea fauri una la comanda. Jarl te avertizeaza sa nu lasi lucrurile pe mai tarziu, fiindca ceea ce trebuie taiat nu va rezista la nesfarsit."}},faq={{q="Cine cere lama?",a="\"Swamp Eye\" Jarl, care se afla in Dustwallow Marsh.",al={"cine ofera jarl needs a blade","cine este jarl","swamp eye jarl"}},{q="Ce arma ii trebuie lui Jarl?",a="O spada lata din otel lunar, pe care Jarl o numeste lama de lovit.",al={"ce sabie vrea jarl","arma lui jarl","de ce lama are nevoie jarl"}},{q="De ce are Jarl atat de urgent nevoie de o lama?",a="Jarl are de taiat, nu poate spune ce va fi taiat si avertizeaza ca nu va tine la nesfarsit.",al={"de ce are jarl nevoie de o lama","ce taie jarl","scopul lui jarl"}},{q="Unde sugereaza Jarl sa fie cautata sabia?",a="Jarl spune ca s-ar putea sa gasesti unul in oras sau sa vorbesti cu un fierar care il poate face special.",al={"cum obtin sabia larga moonsteel pentru jarl","unde gasesc lama pentru jarl"}}},fp="18,164,15.319.0,28.51.0,30.55.0,39.94.0,42.86.0"}
P.entries["quest:1204"] = {n="Mudrock Soup and Bugs",s="In Theramore, Morgan Stern pregateste un fel de mancare numit Mudrock Soup and Bugs, care ar putea deveni urmatorul mare succes in hanurile din Stormwind City. Morgan Stern se indoieste ca acestia ar supravietui unei calatorii lungi prin Dustwallow Marsh si, prin urmare, iti cere sa aduni limbi de la broastele testoase Mudrock.",h="In Theramore, Morgan Stern pregateste un fel de mancare numit Mudrock Soup and Bugs, care ar putea deveni...",kw={"blue recluse","insecte","Dustwallow Marsh","limbi bifurcate","Morgan Stern","Mudrock","supa","Theramore"},sec={{t="Un fel de mancare in pregatire",b="Morgan Stern lucreaza la un fel de mancare numit Mudrock Soup and Bugs si inca are nevoie de ingredientele principale. O calatorie lunga prin Dustwallow Marsh e mai mult decat se asteapta Morgan Stern sa poata indura, asa ca ti se cere sa mergi la vanatoare. Mai intai, trebuie sa aduci limbile broastelor testoase Mudrock."},{t="Limbi bifurcate",b="Mudrocks hoinaresc pe coasta, mai ales in jurul golfului. Morgan Stern nu vrea limbi obisnuite. A ajuns la Morgan Stern vestea ca unii Mudrocks au limbi despicate si ca acestea au o aroma distincta, potrivita pentru felul de mancare."},{t="Spre masa",b="Morgan Stern va incerca diferite moduri de a gati limbile, cautand metoda care le scoate cel mai bine in evidenta gustul. Speranta este sa obtina un fel de mancare demn de a fi servit la Blue Recluse din Stormwind."}},faq={{q="Cine cere limbile de broasca testoasa?",a="Morgan Stern, in Theramore, care lucreaza la un fel de mancare numit Mudrock Soup and Bugs.",al={"cine incepe Mudrock Soup and Bugs","Morgan Stern Theramore"}},{q="Unde pot fi gasite testoasele Mudrock?",a="De-a lungul coastei din Dustwallow Marsh, mai ales in jurul golfului.",al={"locatia testoaselor Mudrock","unde sunt testoasele Mudrock"}},{q="De ce vrea Morgan Stern tocmai limbi bifurcate?",a="Morgan Stern a auzit ca au o aroma aparte si vrea ca acea aroma sa se regaseasca in mancare.",al={"de ce limbi despicate","motivul pentru limbile Mudrock despicate"}},{q="De ce nu aduna Morgan Stern ingredientele personal?",a="Morgan Stern nu crede ca ar supravietui unei calatorii lungi prin Dustwallow Marsh.",al={"de ce nu vaneaza morgan stern","morgan stern in mlastina"}},{q="Ce urmeaza dupa aceasta misiune?",a="Urmatorul pas se numeste ... and Bugs.",al={"urmatoarea misiune dupa supa Mudrock","continuarea misiunii cu supa Mudrock"}}},fp="21,279,20.265.0,14.216.0,16.178.1,37.82.0,39.59.0,55.87.0,56.84.0,28.37.0"}
P.entries["quest:1205"] = {n="Deadmire"}
P.entries["quest:1206"] = {n="Jarl Needs Eyes",s="\"Swamp Eye\" Jarl de la Swamplight Manor vrea 40 de ochi Darkmist neclociti, fiindca sucul din ochii Darkmist este fin si sarat. Paianjenii traiesc in Darkmist Cavern, la vest de conac.",h="\"Swamp Eye\" Jarl de la Swamplight Manor vrea 40 de ochi Darkmist neclociti, fiindca sucul din ochii Darkmist...",kw={"darkmist","darkmist cavern","dustwallow marsh","jarl","ochi de paianjen","jarl ochi de mlastina","swamplight manor"},sec={{t="Pofta de ochi de paianjen",b="Dupa Soothing Spices, Jarl trece la sucul de ochi, care este bun de baut. Majoritatea creaturilor au doar cate doi ochi, pe cand paianjenii au foarte multi, iar lui Jarl ii place sucul de ochi Darkmist. Paianjenii Darkmist traiesc in Darkmist Cavern, la vest de conac, iar Jarl se intreaba daca pestera le-a dat numele paianjenilor sau invers."},{t="Un ospat pentru Jarl",b="Jarl se bucura la vederea ochilor si spune ca sunt deliciosi. Jarl te sfatuieste sa-i pastrezi pentru final pe cei care se uita inapoi cand ii privesti, fiindca ii tin cuiva de urat in mlastina. Apoi Jarl ii saluta pe ochisorii cei mici, ii gusta si declara ca au gust de pui moale si sarat."}},faq={{q="Cine cere ochii paianjenilor?",a="\"Swamp Eye\" Jarl le cere, la Swamplight Manor din Dustwallow Marsh.",al={"cine da aceasta misiune","cel care da misiunea pentru jarl","swamp eye jarl"}},{q="De ce vrea Jarl ochi de paianjen?",a="Lui Jarl ii place sa bea suc de ochi si gaseste sucul de ochi Darkmist fin si sarat. Majoritatea vietatilor au doar doi ochi, in timp ce paianjenii au foarte multi.",al={"de ce ochi de paianjen","ce face Jarl cu ochii","suc de ochi"}},{q="Unde se afla paianjenii Darkmist?",a="Jarl plaseaza paianjenii Darkmist in Darkmist Cavern, la vest de Swamplight Manor.",al={"locatia darkmist cavern","unde sunt paianjenii darkmist","unde se gasesc ochii"}},{q="De cati ochi are nevoie Jarl?",a="Jarl vrea 40 de ochi Darkmist neexplodati.",al={"cate perechi de ochi","numarul de ochi"}},{q="Ce urmeaza inaintea acestui lucru?",a="Soothing Spices a fost primul.",al={"misiunea anterioara","conditie preliminara","ce duce la aceasta"}}},fp="15,173,23.343.0,16.276.1,29.72.0,31.147.0,31.85.0,29.37.0,23.27.0"}
P.entries["quest:121"] = {n="Messenger to Stormwind",s="Duci raspunsul lui General Marcus Jonathan din Stormwind la Lakeshire, unde orcii Blackrock si gnoll ameninta orasul. Capitala nu trimite soldati, lasand asezarea sa infrunte pericolul in timp ce conducatorii din Stormwind trag de timp.",h="Duci raspunsul lui General Marcus Jonathan din Stormwind la Lakeshire, unde orcii Blackrock si gnoll ameninta...",kw={"orci Blackrock","Bolvar","Lakeshire","Magistrate Solomon","Marcus Jonathan","Messenger to Stormwind","Redridge Mountains","Stormwind"},ang={["faction:Alliance"]="Ca membru al Alliance, vezi cum blocajul politic lasa teritoriile omenesti ale regatului expuse amenintarilor regionale.",["race:Human"]="Ca Human al regatului, duci aceasta corespondenta intre confortul aparat de straja din Stormwind City si granitele in ruina ale vecinilor din Elwynn."},sec={{t="Un mesaj catre Lakeshire",b="Dupa ce ai dus apelul disperat pentru intariri al lui Magistrate Solomon direct la General Marcus Jonathan, in Stormwind, esti trimis imediat inapoi pe drumul spre Redridge. Generalul nu poate angaja armata fara aprobare regala, asa ca te trimite inapoi cu o misiva preliminara in timp ce asteapta vesti din sala tronului. Pentru locuitorii greu incercati ai Lakeshire, fiecare zi fara garzile orasului isi aduce asezarea mai aproape de a cadea sub calcaiul Blackrock clan."},{t="Neliniste in regat",b="Magistrate Solomon nu vede nicio urma a batalioanelor promise, marsaluind spre est de-a lungul granitei Elwynn, in raspunsul lui Jonathan. Scrisoarea ofera proceduri evazive in loc de soldati, iar Solomon simte ca ceva nu e in regula la curtea regala. Regele Varian Wrynn a disparut, iar regenta este in impas. Orasele indepartate, precum Lakeshire, sunt lasate sa se apere singure."}},faq={{q="Ce contine raspunsul lui General Marcus Jonathan?",a="Scrisoarea lui General Marcus Jonathan spune ca nu poate trimite armata Stormwind fara autorizatie oficiala din partea regelui sau a curtii regale. El afirma ca problema a fost adusa in atentia coroanei, lasand Lakeshire sa astepte.",al={"ce scrie in scrisoare","raspuns general","scrisoarea lui Marcus Jonathan"}},{q="De ce nu poate Stormwind pur si simplu sa trimita soldati in Redridge?",a="In lipsa lui King Varian Wrynn, hotararile de guvernare le revin tanarului King Anduin, Lordului Regent Bolvar Fordragon si House of Nobles. Dezbinarea si tergiversarile din capitala il impiedica pe General Jonathan sa porneasca la lupta fara aprobarea regala.",al={"de ce nu ajuta Stormwind","de ce nu ajuta Stormwind Lakeshire","armata Stormwind in Redridge"}},{q="Cine este Magistrate Solomon?",a="Magistrate Solomon guverneaza Lakeshire si Redridge Mountains. El conduce asezarea si coordoneaza modesta ei aparare impotriva orcilor Blackrock, a gnoll si a banditilor locali.",al={"Magistrate Solomon","cine este Solomon","magistratul din Lakeshire"}},{q="Cine este General Marcus Jonathan?",a="General Marcus Jonathan comanda Stormwind City Guard si fortele armate permanente ale capitalei. Este stationat la Valley of Heroes, chiar inauntrul portilor principale ale Stormwind City.",al={"cine este Marcus Jonathan","generalul Jonathan","generalul din Stormwind"}},{q="Ce face Solomon dupa ce citeste scrisoarea?",a="Dupa ce citeste scrisoarea, Solomon cere ajutorul regiunilor invecinate si te trimite sa afli care este situatia in Westfall.",al={"ce se intampla in continuare","misiunea de dupa Messenger to Stormwind","incotro merg mai departe"}},{q="De ce spune Solomon 'ceva nu este in regula in regatul nostru'?",a="Solomon nu vede niciun sens militar in refuzarea sau intarzierea ajutorului pentru un oras de granita atacat. Intarzierea il avertizeaza ca liderii politici din Stormwind sunt manipulati sau paralizati din interior.",al={"ceva nu e in regula","de ce este ingrijorat Solomon","conspiratia din Stormwind"}}},fx={["53d96341"]={q="De ce te trimite General Marcus Jonathan inapoi la Lakeshire?",a="Magistrate Solomon a cerut de urgenta intariri militare din partea Stormwindului, pentru a respinge amenintarile gnollilor si orcilor care incercuiesc Lakeshire. General Jonathan a cerut ajutor tronului, dar nu poate trimite trupe regale fara aprobarea Coroanei. Te trimite inapoi cu raspunsul sau oficial, ca liderii din Lakeshire sa nu ramana in necunostinta de cauza in timp ce deliberarile regale bat pasul pe loc in capitala.",al={"de ce trimite marcus jonathan scrisoarea","raspunsul lui marcus jonathan din lakeshire","de ce trebuie sa se ocupe generalul jonathan de asta"}},["64d074bd"]={q="De ce iti incredinteaza General Jonathan aceasta scrisoare in loc s-o trimita printr-un curier regal?",a="Tu ai fost cel care a dus petitia originala a lui Solomon din Redridge in Valley of Heroes. Cum garnizoana orasului Stormwind este deja raspandita pentru a mentine ordinea si a pazi portile capitalei, generalul Jonathan considera mult mai practic sa trimita un aventurier capabil, care cunoaste drumul inapoi spre Lakeshire, decat sa-si desprinda unul dintre gardienii de serviciu.",al={"de ce ma trimite marcus jonathan","de ce nu trimite un mesager al garzii regale","de ce trebuie un aventurier sa livreze in lakeshire"}}},fp="22,222,23.388.0,21.344.1,46.208.0,51.229.0,26.175.0,31.180.0,51.115.1,57.192.0"}
P.entries["quest:1218"] = {n="Soothing Spices",s="\"Swamp Eye\" Jarl adora sa gateasca in stilul mlastinii si are nevoie de condiment calmant pentru o tocana. Jarl din Dustwallow Marsh iti cere sa aduci trei Soothing Spices.",h="\"Swamp Eye\" Jarl adora sa gateasca in stilul mlastinii si are nevoie de condiment calmant pentru o tocana.",kw={"Dustwallow Marsh","picioare de broasca","condimente calmante","tocana","Swamp Eye Jarl"},sec={{t="Condimente pentru oala",b="\"Swamp Eye\" Jarl indrageste bucatele gatite dupa obiceiul mlastinii, printre care se numara pulpele de broasca verde prajite. Se pregateste o tocanita, iar Jarl are nevoie de condimente pentru ea. Cine le aduce va primi o portie. Jarl vrea trei Soothing Spices si se intreaba daca iti place tocana."}},faq={{q="Cine doreste condimentele calmante?",a="\"Swamp Eye\" Jarl, care se afla in Dustwallow Marsh.",al={"cine ofera mirodenii calmante","cine da misiunea mirodenii calmante","mirodenii Swamp Eye Jarl"}},{q="Ce intentioneaza Swamp Eye Jarl sa gateasca folosind mirodeniile?",a="O tocanita. Jarl indrageste bucatele din mlastina, cum ar fi picioarele de broasca verde prajite, si planuieste sa imparta tocanita cu tine.",al={"ce prepara Jarl","ce tocana prepara Jarl","mancarea lui Jarl"}},{q="De cate condimente are nevoie Jarl?",a="Jarl cere trei Soothing Spices.",al={"cate mirodenii calmante","cantitatea de mirodenii calmante","cerinta de mirodenii calmante"}}},fp="15,147,17.268.0,30.51.0,56.107.0,31.36.0"}
P.entries["quest:1219"] = {n="The Orc Report",s="In timp ce scormonesti prin pamantul afanat din Dustwallow Marsh, dai peste mana taiata a unui orc, care strange un tub sculptat din os. Inauntru se afla un pergament patat de noroi, cu scris in limba Orc, care pare important. Este destinat unui locotenent din Theramore.",h="In timp ce scormonesti prin pamantul afanat din Dustwallow Marsh, dai peste mana taiata a unui orc, care...",kw={"tub din os","dustwallow marsh","pamant afanat","raport de la orc","locotenent din theramore"},sec={{t="O mana in pamant",b="In pamantul afanat se afla mana taiata a unui orc, strangand un tub sculptat in os. Inauntru se gaseste un pergament patat de pamant, scris in Orcish, ceea ce pare important. Trebuie sa i-l arati unui Lieutenant din Theramore."},{t="Verdictul locotenentului",b="Locotenentul recunoaste ca citeste greu Orcish, dar ia pergamentul drept raportul unui spion orc."}},faq={{q="Ce este ascuns in pamantul afanat?",a="Scotocind prin el, gasesti o mana de Orc retezata, care strange intr-o gheara un tub sculptat din os, cu un pergament patat de pamant inauntru.",al={"ce gasesti in pamantul afanat","obiect din pamantul afanat","mana de orc din dustwallow"}},{q="Cui trebuie sa-i fie inmanat pergamentul?",a="Un locotenent din Theramore.",al={"unde duc raportul","cine primeste raportul spionului","locatia locotenentului din theramore"}},{q="In ce limba este scris pergamentul?",a="Scrierea este in Orcish si pare importanta.",al={"limba pergamentului","pot citi pergamentul"}}},fp="14,236,18.220.0,24.96.1,33.122.0,29.23.0,42.48.0"}
P.entries["quest:122"] = {n="Underbelly Scales",s="Verner Osgood are nevoie de solzii de pe burta puilor de dragon negru, pentru a-si plati datoria comerciala fata de fierarul Smith Argus din Goldshire. Pentru a-i obtine, trebuie vanati puii de dragon care ratacesc prin stancariile de la sud de Lakeshire. Solzii achita contul lui Verner si ofera destula piele bruta pentru a confectiona o piesa de echipament.",h="Verner Osgood are nevoie de solzii de pe burta puilor de dragon negru, pentru a-si plati datoria comerciala...",kw={"pui de dragon negru","zborul dragonilor","Goldshire","Lakeshire","Redridge","Smith Argus","solzi de sub pantece","Verner Osgood"},ang={["faction:Alliance"]="Ameninarea tot mai mare a Black Dragonflight la sud de Lakeshire este o alta povara pentru garnizoana deja suprasolicitata, care se lupta sa apere Redridge.",["profession:Blacksmithing"]="Cererea lui Smith Argus arata cum reactivi rari, precum solzii de dragon, sunt folositi ca marfuri de troc foarte valoroase intre fierari atunci cand moneda obisnuita este putina.",["race:Human"]="Rutele comerciale dintre Elwynn si Redridge aprovizioneaza orase precum Lakeshire, insa mestesugarii de la frontiera trebuie adesea sa plateasca preturi piperate negustorilor din oras."},sec={{t="O datorie la granita",b="Administrarea unei forje la marginea orasului Lakeshire necesita provizii greu de gasit, iar Verner Osgood face deseori schimburi cu mestesugari de dincolo de Redridge Mountains. Dupa ce primeste o incarcatura de potcoave de la fierarul Smith Argus din Goldshire, Verner ramane fara bani obisnuiti. In schimb, Argus cere plata in solzi pretiosi de dragon: mai exact, solzii moi, foarte cautati, de pe pantecele puilor de dragon negru care isi fac cuibul in regiune. Fara ei, Verner risca sa trimita recuperatori din Elwynn Forest sa-si ia singuri ce li se datoreaza."},{t="Puii zborului negru",b="Prezenta puilor de dragon negru in Redridge Mountains este un semn alarmant pentru aparatorii locali. In timp ce gnolii si orcii se lupta pe fata pentru drumuri, puietul Black Dragonflight isi face cuibul pe piscurile inalte si strabate cerurile la sud de Lake Everstill. Solzii de pe pantecele acestor tineri pradatori sunt rezistenti, dar flexibili, ceea ce ii face componente cautate pentru armuri de catre armurieri, fierari si pielari din intregul regat, destul de indrazneti sa-i procure."}},faq={{q="De ce are nevoie Verner Osgood de solzi de dragon?",a="Verner ii datoreaza bani fierarului Smith Argus din Goldshire pentru un transport de potcoave. Argus a cerut, in locul monedelor obisnuite, plata in solzi de pe pantecele puilor de dragon negru. Verner are nevoie ca solzii sa-i fie livrati repede, inainte ca Argus sa trimita recuperatorii sa-si ceara datoria.",al={"de ce solzii de dragon","datoria lui Verner","solzii lui Argus"}},{q="Unde se gasesc puii de dragon negru in Redridge?",a="Puii de dragon negru ratacesc adesea printre stancile si vaile de la sud de Lakeshire. De obicei umbla liberi prin dealurile sudice, asa ca vanatorii trebuie sa patruleze pe poteci si creste pentru a-i zari in zbor.",al={"locatii pui de dragon","unde se gasesc puii de dragon","locatia puilor de dragon redridge"}},{q="Cine este Smith Argus?",a="Smith Argus este fierarul din Goldshire, in Elwynn Forest. El furnizeaza obiecte prelucrate si produse forjate asezarilor din imprejurimi, inclusiv potcoave pentru Verner Osgood din Redridge.",al={"argus din goldshire","cine este argus","smith argus"}},{q="De ce se afla pui de dragon negru in Redridge Mountains?",a="Black Dragonflight este prezenta in Burning Steppes si in varfurile din jurul Redridge. Puii lor vaneaza si se deplaseaza spre sud prin trecatorile montane, pana in poalele muntilor din Redridge.",al={"de ce sunt dragoni in Redridge","dragonii negri din Redridge","Zborul Negru din Redridge"}},{q="Ce au special solzii de pe pantece?",a="In timp ce solzii dorsali ai dragonilor sunt grosi si rigizi, cei de pe pantece sunt flexibili si maleabili, dar rezista bine la caldura si perforare. Astfel, sunt ideali pentru pielarie de specialitate, intariri croite pe masura si marfuri exotice.",al={"de ce solzii de pe burta","valoarea solzilor","calitatea pielii de dragon"}},{q="Duce achitarea acestei datorii la alte sarcini pentru Verner?",a="Aceasta sarcina face parte dintre cererile lui Verner Osgood, dupa ce ii aduci transportul de potcoave. In afara de aceasta insarcinare optionala de adunare, Verner ii indruma pe aventurieri sa combata amenintarea tot mai mare a gnollilor din Redridge, vanandu-le cercetasii si conducatorii.",al={"ce urmeaza","lantul de misiuni al lui Verner","continuarea lui Osgood"}}},fx={["43de1078"]={q="De ce iti cere Verner sa vanezi puii de dragon in loc sa o faca el insusi?",a="Verner Osgood este prins cu treburile grajdurilor si fierariei aglomerate din Lakeshire, in vreme ce garzile locale sunt ocupate pana peste cap sa apere zona de incursiunile gnollilor si orcilor din imprejurimi. Pentru a porni spre sud, pe dealuri, in cautarea puilor de dragon negru care dau tarcoale, e nevoie de aventurieri priceputi, capabili sa urmareasca fauna periculoasa si sa se descurce in salbaticie.",al={"de ce are nevoie Verner de mine","de ce nu poate Verner sa vaneze puii de dragon","de ce imi cere sa aduc solzi din Underbelly"}}},fp="17,309,15.533.0,25.469.0,42.260.0,52.222.0,19.198.0,50.209.0,37.247.0,55.246.0"}
P.entries["quest:1220"] = {n="Captain Vimes",s="Lieutenant Aden te trimite cu raportul despre orc pe care l-ai gasit la Captain Garran Vimes, care citeste limba orcilor mai bine decat majoritatea. Raportul trebuie sa includa si vestile despre spionii din Horde aflati langa Theramore.",h="Lieutenant Aden te trimite cu raportul despre orc pe care l-ai gasit la Captain Garran Vimes, care citeste...",kw={"captain vimes","dustwallow marsh","garran vimes","lieutenant aden","raport orc","raportul spionului","theramore","theramore isle"},sec={{t="Un raport pentru capitan",b="Lieutenant Aden crede ca raportul despre Orc pe care l-ai gasit ar trebui sa ajunga in mainile lui Captain Garran Vimes, care citeste limba orc mai bine decat majoritatea. Aden vrea si ca acestuia sa i se spuna ca spionii Horde pandesc in apropiere de Theramore. Il vei gasi pe Vimes la cazarma din partea nord-estica a Theramore Isle."}},faq={{q="Cine te trimite la Captain Vimes?",a="Lieutenant Aden, care vrea ca capitanul sa vada raportul despre orc pe care l-ai gasit.",al={"cine incepe Captain Vimes","de unde iau Captain Vimes"}},{q="Unde se afla Captain Garran Vimes?",a="La cazarma, pe latura nord-estica a Theramore Isle.",al={"unde se afla captain vimes","locatia lui captain vimes","cazarma lui vimes"}},{q="De ce trebuie sa vada Captain Vimes raportul?",a="Aden spune ca Vimes citeste limba orceasca mai bine decat majoritatea si ca ar trebui sa afle ca spionii Horde sunt aproape de Theramore.",al={"de ce captain vimes","de ce are nevoie vimes de raport"}}},fp="13,168,24.285.0,31.71.0,38.55.0,46.103.0"}
P.entries["quest:1221"] = {n="Blueleaf Tubers",s="Blueleaf Tubers este un contract de recuperare comandat de negustorul goblin Mebok Mizzyrix din Ratchet. Dorind sa profite de o delicatesa subterana rara, Mizzyrix ii echipeaza pe aventurieri cu popandai cu bot fin dresati, care sa localizeze si sa dezgroape tuberculii ingropati in desisurile spinoase din Razorfen Kraul.",h="Blueleaf Tubers este un contract de recuperare comandat de negustorul goblin Mebok Mizzyrix din Ratchet.",kw={"tuberculi blueleaf","baston de comanda","delicatesa","mebok mizzyrix","quillboar","ratchet","razorfen kraul","popandau snufflenose","the barrens"},ang={["faction:Alliance"]="Expeditiile Alliance care ajung in portul neutru Ratchet pot profita de contractul comercial al lui Mizzyrix pentru a-si justifica incursiunea pe un teritoriu ostil, invecinat cu tinuturile Horde.",["faction:Horde"]="Razboinicii Horde care apara Barrens de incursiunile quilboar pot castiga usor niste bani in plus trecand cartitele dresate ale lui Mizzyrix prin Kraul.",["profession:Cooking"]="Artasii culinari stiu ca tuberculii blueleaf sunt considerati una dintre cele mai rare delicatese din Azeroth, cautate de cumparatori de elita care le pretuiesc aroma distincta, pamantie.",["profession:Herbalism"]="Spre deosebire de flora obisnuita de la suprafata, tuberculii blueleaf cresc numai in subteran, printre radacinile de maracini din Razorfen, feriti de lumina soarelui."},sec={{t="O delicatesa subterana de pret",b="Tuberculii blueleaf sunt ravniti in toata lumea ca o delicatesa culinara rara si luxoasa. In ciuda valorii lor mari, recoltarea este de notorietate dificila, deoarece nu cresc pe campuri deschise sau prin dumbravi salbatice obisnuite. In schimb, se gasesc aproape numai adanc sub pamant, in sudul regiunii Barrens, impletiti printre radacinile labirintice din Razorfen Kraul."},{t="Ingeniozitatea lui Mizzyrix",b="Deoarece tuberculii raman complet ingropati si sunt aproape imposibil de observat pentru humanoizii obisnuiti, negustorul Mebok Mizzyrix din Ratchet a gasit o solutie neobisnuita. Dresand popandai snufflenose autohtoni - creaturi capabile sa adulmece un tubercul ingropat de la cincizeci de pasi - Mizzyrix a transformat daunatorii in unelte de cautare a hranei. El le da scotocitorilor un bat de comanda, o lada aerisita si un manual de instructiuni pentru a-i indruma pe micile creaturi prin tinutul quilboar."},{t="Recoltarea din maracini",b="Recuperarea tuberculilor presupune patrunderea pe teritoriul ostilei triburi Death's Head de quilboari. Culegatorii trebuie sa-si apere cartitele dresate de fiarele salbatice si de maracinii spinosi din Kraul, poruncindu-le rozatoarelor sa dezgroape bulbii ascunsi, apoi sa-i impacheteze pentru transportul inapoi la Ratchet, unde ii asteapta cumparatorii straini ai lui Mizzyrix, care platesc foarte bine."}},faq={{q="La ce se folosesc Blueleaf Tubers?",a="Sunt considerate delicatese culinare rare si foarte cautate in intreaga lume. Cumparatorii bogati platesc sume considerabile pentru tuberculi proaspeti, ceea ce-i transforma intr-o marfa comerciala profitabila pentru goblini precum Mebok Mizzyrix.",al={"la ce foloseste tuberculul Blueleaf","ce sunt tuberculii Blueleaf","de ce se aduna tuberculi Blueleaf"}},{q="Unde se gasesc Blueleaf Tubers?",a="Ele cresc ingropate in pamantul subteran si printre sistemele de radacini spinoase de sub sudul Barrens, mai exact in interiorul fortaretei quilboar din Razorfen Kraul.",al={"unde gasesc tuberculi blueleaf","locatia tuberculilor blueleaf","unde cresc"}},{q="De ce ai nevoie de un cartitor Snufflenose ca sa-i gasesti?",a="Tuberculii sunt ascunsi complet sub pamant si nu pot fi vazuti cu ochiul liber. Cartita cu bot adulmecator are un simt al mirosului ascutit, care-i permite sa detecteze tuberculii ingropati de la o distanta de pana la cincizeci de pasi si sa-i dezgroape.",al={"de ce sa folosim cartite","scopul cartitei Snufflenose","cum gasesc cartitele tuberculi"}},{q="Cine este Mebok Mizzyrix?",a="Mebok Mizzyrix este un negustor goblin intreprinzator, care isi desfasoara activitatea in orasul-port neutru Ratchet, din Barrens. Este specializat in dresarea faunei locale si in procurarea de marfuri exotice pentru comertul exterior.",al={"cine ofera misiunea pentru blueleaf tubers","povestea lui mebok mizzyrix","goblinul care ofera misiuni in ratchet"}},{q="Ce echipament iti pune la dispozitie Mizzyrix pentru treaba?",a="Mizzyrix le da aventurierilor o lada cu gauri, in care se afla o cartita dresata, un Snufflenose Command Stick folosit pentru a-i porunci animalului sa sape si un Snufflenose Owner's Manual care explica felul in care trebuie manevrata bestia.",al={"obiecte de misiune cu tuberi","bat de comanda pentru gopher","lada cu gauri"}},{q="De ce nu poate Mebok sa adune singur tuberculii?",a="Razorfen Kraul este puternic pazit de triburi agresive de quilboar, liane cu spini si pradatori subterani periculosi. Mizzyrix prefera sa-si riste mercenarii decat sa patrunda el insusi in tumulii primejdiosi.",al={"de ce nu-i obtine mebok","de ce angajeaza aventurieri"}}},fx={["8175ef8b"]={q="De ce vrea Mebok Mizzyrix Blueleaf Tubers?",a="Mebok Mizzyrix este manat de un scop simplu, specific goblinilor: profitul. Tuberculii blueleaf sunt o delicatesa extrem de rara in toata lumea, gasita doar adanc sub pamant, in Razorfen Kraul. Pentru ca adunatorii obisnuiti nu-i pot gasi cu usurinta, au un pret exceptional. Mebok intentioneaza sa vanda contactelor sale bogate tot ce-i aduci, pentru o gramada frumusica de bani, oferindu-ti o parte modesta din castiguri pentru ca ti-ai riscat viata si integritatea ca sa-i recuperezi.",al={"motivul lui Mebok Mizzyrix","de ce vrea Mebok tuberculi","de ce sa aduni tuberculi Blueleaf"}},e7d11e5c={q="La ce foloseste Crate With Holes?",a="Crate With Holes este un container special de transport, construit de Mebok pentru a adaposti un gopher cu botul sensibil dresat. Orificiile de aer il mentin in viata si ii permit sa respire in voie pana ajungi in adancurile din Razorfen Kraul, unde il poti elibera in siguranta ca sa adulmece tuberculii ingropati.",al={"la ce foloseste lada cu gauri","ce este lada cu gauri","de ce lada are gauri"}},["91901628"]={q="La ce foloseste Snufflenose Command Stick?",a="Bastonul de comanda este o unealta de antrenament conceputa de Mebok pentru a indruma cartita cu bot adulmecator. Folosirea lui ii indica fapturii sa-si concentreze nasul ascutit, sa scotoceasca podeaua pesterii din apropiere si sa dezgroape orice tuberculi blueleaf ascunsi pe care ii adulmeca ingropati prin preajma.",al={"scopul toiagului de comanda","ce face Snufflenose Command Stick","Snufflenose Command Stick"}},af9e7fb9={q="La ce foloseste Snufflenose Owner's Manual?",a="Manualul contine instructiunile scrise de Mebok despre cum sa manuiasca goferul, sa-l indrume cu bastonul de comanda si sa dezgroape cu succes tuberculii fara sa-si piarda animalul dresat in tunelurile quilboar.",al={"scopul manualului Snufflenose","la ce foloseste manualul proprietarului","manualul proprietarului lui Snufflenose"}}},fp="15,300,30.371.0,20.474.0,24.357.0,34.213.0,32.159.0,50.237.0,22.207.0,49.205.0,42.208.0"}
P.entries["quest:1222"] = {n="Stinky's Escape",s="\"Stinky\" Ignatz e in mlastina, unde Morgan Stern, bucatar din Theramore, l-a trimis sa adune frunze de bogbean. Creaturile l-au inconjurat, iar el iti cere sa-l ajuti si sa-i pazesti spatele in timp ce cauta o planta de bogbean. Dupa aceea, trebuie sa-l cauti pe Morgan Stern in Theramore.",h="\"Stinky\" Ignatz e in mlastina, unde Morgan Stern, bucatar din Theramore, l-a trimis sa adune frunze de...",kw={"paianjen pustnic albastru","bogbean","dustwallow marsh","morgan stern","stinky ignatz","theramore"},sec={{t="Incercuit",b="Ignatz rasufla usurat ca a intalnit pe cineva care nu-l vede drept o masa copioasa. Spune ca Morgan Stern, un bucatar, lucreaza la o reteta noua si l-a trimis sa adune frunze de bogbean, despre care Ignatz banuieste ca lui Stern i se par gustoase. In timp ce cauta planta, Ignatz a fost inconjurat si iti cere sa-l ajuti si sa-i pazesti spatele cat timp cauta."},{t="Un bucatar care asteapta",b="Morgan Stern din Theramore este ingrijorat: Ignatz a plecat spre mlastina cu ceva vreme in urma si inca nu s-a intors."},{t="Multumiri din partea bucatarului",b="Stern spune ca Ignatz a trecut pe acolo cu frunzele de bogbean si i-a povestit cum l-ai ajutat sa treaca peste necazuri. Drept multumire, Stern il va ruga pe un unchi sa-ti pregateasca un ospat data viitoare cand vei vizita Blue Recluse din Stormwind."}},faq={{q="Cine este \"Stinky\" Ignatz?",a="\"Stinky\" Ignatz a fost trimis in mlastina de bucatarul Morgan Stern ca sa adune frunze de bogbean.",al={"stinky ignatz","cine este stinky","ignatz dustwallow"}},{q="De ce are Ignatz necazuri?",a="In timp ce cauta o planta de bogbean, creaturile din jur l-au inconjurat.",al={"de ce este Stinky prins","Ignatz ratacit","de ce este Stinky in Dustwallow"}},{q="La ce folosesc frunzele de bogbean?",a="Morgan Stern lucreaza la o reteta noua si l-a trimis pe Ignatz dupa frunze. Ignatz banuieste ca Stern le gaseste gustoase.",al={"frunze de bogbean","ce sunt bogbeans","planta bogbean"}},{q="Cine este Morgan Stern?",a="Morgan Stern este bucatar in Theramore si lucreaza la o reteta noua.",al={"morgan stern theramore","cine este morgan stern","bucatarul morgan stern"}}},fp="15,285,10.324.0,14.101.0,20.204.1,23.90.0,25.90.0,28.110.0,20.67.0"}
P.entries["quest:123"] = {n="The Collector",s="Un mesaj interceptat de la jefuitorii gnoll din Elwynn Forest dezvaluie cand pleaca transporturile de aur din minele parasite. Este adresat unei persoane numite 'The Collector' si indica o operatiune organizata in apropierea garnizoanei din Stormwind.",h="Un mesaj interceptat de la jefuitorii gnoll din Elwynn Forest dezvaluie cand pleaca transporturile de aur din...",kw={"Brackwell Pumpkin Patch","Elwynn Forest","orarul ridicarii aurului","Goldshire","vanatoare de oameni","Marshal Dughan","mine","colectionarul"},ang={["class:Rogue"]="Ca rogue, poti citi programul interceptat si urmari contrabanda prin retelele criminale din tinuturile salbatice ale Elwynn.",["faction:Alliance"]="Fiecare uncie de aur scoasa prin contrabanda din Elwynn priveaza Coroana de venituri fiscale si materii prime, in timp ce regatul se straduieste sa-si apere granitele.",["profession:Mining"]="Ca miner, stii ca minele inchise din Elwynn inca adapostesc cupru si metale pretioase. Cineva exploateaza ilegal aceste filoane, in timp ce minerii cinstiti stau acasa de frica."},sec={{t="O urma de hartie in ghearele Gnoll-ilor",b="Haitele de gnoll Riverpaw din vestul regiunii Elwynn Forest poarta cu ele mai mult decat blanuri si arme rudimentare. Printre ele se afla un pergament numit Gold Pickup Schedule, care noteaza datele si orele la care este colectat aurul din minele locale. Biletul interceptat indruma fiecare transport catre un supraveghetor identificat doar drept 'The Collector'."},{t="Vesti tulburatoare pentru Goldshire",b="Marshal Dughan afla vestea la Lion's Pride Inn si intelege ca aurul continua sa fie extras si transportat. Minele oficiale din Elwynn sunt inchise de luni intregi din cauza atacurilor gnoll, a infestatiilor kobold si a banditilor hoinari. Gnoll care poarta programe de transport indica existenta unei retele criminale organizate, care fura bogatiile regatului."},{t="Cu ochii pe peticul Brackwell",b="Programul il plaseaza pe presupusul Collector langa Brackwell Pumpkin Patch, in estul Elwynn Forest. Marshal Dughan a auzit soapte despre nume, dar nu are dovezi clare despre cine conduce reteaua sau unde ajunge aurul. Mesajul ofera garnizoanei primul indiciu solid in urmarirea celui care coordoneaza transporturile."}},faq={{q="Ce este programul de colectare a aurului?",a="Programul ridicarii aurului este o nota interceptata, purtata de gnolli in Elwynn Forest. Ea enumera datele si orele la care aurul extras din mine trebuie predat unei persoane numite 'The Collector.'",al={"programul de ridicare","nota colectorului","programul aurului din Elwynn"}},{q="Cine este 'The Collector'?",a="'The Collector' este o figura criminala despre care se crede ca se afla langa Brackwell Pumpkin Patch, in estul Elwynn Forest, unde coordoneaza un comert ilegal cu aur.",al={"identitatea colectionarului","cine este colectionarul","colectionarul Brackwell"}},{q="De ce este Marshal Dughan socat de program?",a="Marshal Dughan este socat, deoarece aurul continua sa fie extras si transportat, desi minele oficiale sunt inchise de luni intregi. Atacurile gnoll-ilor, invaziile Kobold si banditii ratacitori au dus la inchiderea lor, asa ca programul dezvaluie o operatiune secreta care fura de la coroana.",al={"de ce este Dughan surprins","reactia lui Dughan","minele din Elwynn sunt inchise"}},{q="De ce au gnollii biletul acesta?",a="Gnoll-ii Riverpaw din vestul Elwynn par sa transporte programul ca mesageri, paznici sau complici in contrabanda cu aur, ducand ordine despre locurile de ridicare.",al={"aurul gnollilor","de ce lasa gnollii pontajul","implicarea gnollilor"}},{q="Incotro duce aceasta investigatie?",a="Predarea programului lui Marshal Dughan duce la Manhunt, care te trimite sa-l gasesti si sa-l elimini pe Collector de langa Brackwell Pumpkin Patch.",al={"continuarea misiunii Collector","misiunea de vanatoare de oameni","dupa Collector"}},{q="Unde se afla Brackwell Pumpkin Patch?",a="Brackwell Pumpkin Patch se afla in estul Elwynn Forest, la nord de rau si la est de viile Maclure si Stonefield.",al={"locatia brackwell","unde este brackwell","pumpkin patch elwynn"}}},fp="13,230,35.293.0,29.336.0,27.318.1,33.177.0,23.146.0,46.268.0,29.159.0,40.141.0,45.127.0"}
P.entries["quest:1238"] = {n="The Lost Report",s="Scormonind prin pamantul afanat din Dustwallow Marsh, gasesti o mana retezata de Orc, care strange un tub sculptat in os, cu un pergament patat de pamant inauntru. Este un raport scris de un Orc care a spionat Theramore timp de saptamani si care ii este destinat lui Nazeer Bloodpike, seful spionilor Orc din Brackenwall Village.",h="Scormonind prin pamantul afanat din Dustwallow Marsh, gasesti o mana retezata de Orc, care strange un tub...",kw={"brackenwall village","dustwallow marsh","pamant afanat","nazeer bloodpike","raport de spionaj","raportul pierdut","theramore"},sec={{t="O mana in pamant",b="In pamantul afanat se afla mana taiata a unui orc, strangand un tub sculptat din os. Pergamentul din interior este un raport al unui orc care a spionat Theramore timp de mai multe saptamani. Dupa ce-l citesti, intelegi ca trebuie sa ajunga la Nazeer Bloodpike, spionul-sef al orcilor din Brackenwall Village."},{t="Vesti de la spymaster",b="Nazeer Bloodpike spune ca autoarea era Marg Nighteye, o agenta postata in afara Theramore, pentru a supraveghea orasul. Acesta este ultimul raport al lui Marg si poate chiar ultimul ei mesaj: dupa cele spuse de tine, Bloodpike se teme ca Marg si-a gasit sfarsitul in mlastina."}},faq={{q="Unde se gaseste raportul?",a="Se afla in pamantul afanat din Dustwallow Marsh, tinut in mana taiata a unui orc.",al={"unde este raportul","locatia raportului pierdut","cum incep misiunea raportului pierdut"}},{q="Despre ce este raportul?",a="Un orc a scris-o dupa ce a spionat Theramore timp de cateva saptamani.",al={"ce contine raportul","ce spune raportul spionului","continutul pergamentului"}},{q="Cine primeste raportul?",a="Spionul-sef al orcilor, Nazeer Bloodpike, la Brackenwall Village.",al={"cui trebuie sa predau raportul","unde predau raportul pierdut","unde duc raportul spionului"}}},fp="15,308,18.276.0,23.232.1,26.77.0,25.51.0,20.62.0"}
P.entries["quest:1239"] = {n="The Severed Head",s="Sapaturile intense scot la iveala capul unui Orc, taiat grosolan de la gat. Trebuie dus la Nazeer Bloodpike din Brackenwall Village.",h="Sapaturile intense scot la iveala capul unui Orc, taiat grosolan de la gat.",kw={"brackenwall village","cap de orc sfidator","dustwallow marsh","pamant afanat","marg nighteye","nazeer bloodpike","cap taiat"},sec={{t="O descoperire sumbra",b="Sapand cu putere in pamantul afanat, scoti la iveala capul unui orc, al unui mascul, zdrentuit acolo unde a fost taiat de la gat. Buzele sunt trase intr-un ranjet, iar ochii intunecati privesc sfidator. Trebuie sa-l duci la Nazeer Bloodpike, in Brackenwall Village."},{t="Nazeer cerceteaza mai atent",b="Nazeer Bloodpike recunoaste imediat capul ca fiind al lui Marg Nighteye si spune ca se temea ca Marg ar fi murit. Studiind rana zdrentuita de la gat, Nazeer se intreaba daca taietura a fost facuta cu o arma sau daca vreun animal l-a ucis pe agent. E o enigma care trebuie dezlegata, iar Nazeer vrea sa afle daca Alliance s-a aflat in spatele mortii lui Marg."}},faq={{q="Unde trebuie sa duci capul retezat?",a="Lui Nazeer Bloodpike din Brackenwall Village.",al={"unde predau capul retezat","predarea capului retezat","cine ia capul"}},{q="Cum arata capul?",a="Al unui Orc, de sex masculin, zdrentuit acolo unde a fost taiat de la gat, cu buzele schimonosite intr-un ranjet si ochi intunecati care privesc sfidator.",al={"ce se afla in pamantul afanat","cap de orc sfidator","descrierea capului taiat"}},{q="Ce urmeaza dupa capul taiat?",a="Urmatorul pas este The Troll Witchdoctor.",al={"urmatoarea misiune dupa capul taiat","continuarea misiunii cu capul taiat"}}},fp="16,155,11.236.0,19.306.1,36.43.0,29.119.0,34.39.0"}
P.entries["quest:124"] = {n="A Baying of Gnolls",s="Verner Osgood, grajdarul din Lakeshire, isi vede afacerea amenintata de gnolli care ataca din sud, coborand de pe colinele din Redridge. Deja pus la incercare de incursiunile orcilor Blackrock, le cere calatorilor sa-i alunge pe brutii si mistici care ii ameninta animalele.",h="Verner Osgood, grajdarul din Lakeshire, isi vede afacerea amenintata de gnolli care ataca din sud, coborand...",kw={"gnolli","cai","Lakeshire","bruta din Redridge","Redridge Mountains","mistic din Redridge","grajduri","Verner Osgood"},ang={["class:Hunter"]="Fiarele salbatice si haitele furioase din Redridge au devenit indraznete in lipsa vanatorilor organizati, transformandu-se intr-o amenintare imprevizibila pentru animalele domestice si calatori.",["faction:Alliance"]="Fiecare comunitate mica din regatul sudic resimte neglijenta Stormwind, obligandu-i pe negustori modesti precum Verner sa angajeze ajutoare pe cont propriu pentru a-si proteja liniile esentiale de aprovizionare."},sec={{t="Cai pe creasta",b="Administrarea unui grajd in Lakeshire a devenit tot mai periculoasa. Orcii Blackrock stapanesc inaltimile regiunii, iar cete de gnolli cutreiera crestele din jur. Pentru Verner Osgood, situatia a ajuns la limita atunci cand cetele agresive de gnolli jefuitori s-au apropiat de granitele nordice ale padocurilor sale, pradand orice cal care se apropia prea mult de povarnisuri."},{t="O amenintare coordonata",b="Nu sunt simpli necrofagi raspanditi prin zona. Haitele care actioneaza chiar la nord de oras imbina forta bruta salbatica cu vrajitoria primitiva, folosind brute rezistente pentru a-si coplesi prada, alaturi de mistici care manuiesc magia neimblanzita. Rarirea randurilor lor ofera o scurta usurare asezarii, dar devine repede limpede ca agresivitatea lor este provocata de o putere mai mare, care pandeste sus, in dealuri."}},faq={{q="De ce are Verner Osgood nevoie de ajutor cu gnollii?",a="Gnollii din crestele nordice au inceput sa patrunda pe pasunile lui Verner si sa fure caii care se indeparteaza de tarcuri. Intre aceasta amenintare si invazia orcilor Blackrock, nu-si poate apara herghelia fara ajutor din afara.",al={"problema lui Verner","de ce vrea Verner sa omoare gnolli","gnolli la grajdurile din Lakeshire"}},{q="Unde se afla gnollii acestia?",a="Brutele si mistici Redridge pandesc pe crestele inalte si pe dealurile de la poalele muntilor, chiar la nord si est de Lakeshire, cu vedere spre oras si drumul catre Everstill Bridge.",al={"unde sunt brute din Redridge","locatia misticului din Redridge","gnolii de la nord de grajduri"}},{q="De ce sunt gnollii o problema pe langa orcii Blackrock?",a="In timp ce Blackrock clan este principala forta militara care ameninta Redridge, haitele locale de gnolli profita de distragere. Cu aparatorii din Lakeshire rasfirati si cu Stormwind trimitand intariri minime, pradatorii din zona s-au extins nestingheriti pana la marginea satului.",al={"orci si gnolli in Redridge","de ce sunt atat gnolli, cat si orci"}},{q="Ce urmeaza dupa ce te ocupi de acesti gnolli?",a="Dupa ce numarul brutelor si al misticilor scade, Verner observa ca urletele din dealuri continua, semn ca exista o amenintare mai ampla din partea unei conduceri care trebuie infruntata in inaltimile din jur.",al={"continuarea misiunii Baying of Gnolls","ce urmeaza dupa Baying of Gnolls"}},{q="De ce sunt misticii deosebit de periculosi?",a="Misticii din Redridge practica o magie rudimentara a naturii si a elementelor, intorcand impotriva intrusilor incantatii nestatornice si salbatice. Prezenta lor printre brute sugereaza o structura de clan organizata, nu o adunatura de pradatori salbatici solitari.",al={"lore despre mistici din Redridge","samanilor gnolli din Redridge"}},{q="Trimite Stormwind soldati sa protejeze grajdurile din Lakeshire?",a="Nu. Curtea regala din Stormwind a lasat regiunea Redridge in mare masura sa se apere singura, in mijlocul framantarilor politice si al lipsei de trupe. Astfel, Magistrate Solomon si cetateni precum Verner Osgood sunt nevoiti sa recruteze aventurieri ratacitori.",al={"gardienii din Stormwind in Redridge","de ce nu-l ajuta niciun gardian pe Verner"}}},fx={["114f5694"]={q="Cine sunt gnolii care ameninta caii lui Verner?",a="Esti trimis impotriva salbaticilor si misticilor din Redridge care pandesc pe dealurile aflate chiar la nord de grajdurile lui Verner Osgood. Acesti oameni-hiena salbatici locuiesc pe crestele ce domina Lakeshire si profita de preocuparile localnicilor pentru a fura animale nepazite si a teroriza gospodariile din zona.",al={"gnolii din Redridge","brutii si misticii din Redridge","ce gnoli ataca Lakeshire"}}},fp="18,257,19.373.0,20.393.1,45.234.0,31.178.0,53.285.0,43.190.1,39.225.0,61.215.0"}
P.entries["quest:1240"] = {n="The Troll Witchdoctor",s="Nazeer Bloodpike vrea sa afle ce s-a intamplat in jurul mortii lui Marg Nighteye si spune ca doar magia vrajitoreasca a celor din Troll poate dezvalui adevarul. Duci capul lui Marg la Kin'weelay, in Grom'gol Base Camp din Stranglethorn Vale.",h="Nazeer Bloodpike vrea sa afle ce s-a intamplat in jurul mortii lui Marg Nighteye si spune ca doar magia...",kw={"vraci-vindecator Darkspear","cap de Orc razvratit","grom'gol base camp","kin'weelay","marg nighteye","nazeer bloodpike","stranglethorn vale"},sec={{t="Magia vrajitoreasca a celor din Troll",b="Dupa ce capul retezat a fost gasit, Nazeer Bloodpike insista ca trebuie aflate imprejurarile mortii lui Marg si ca numai magia vrajitoreasca a trollilor le poate dezvalui. Capul lui Marg trebuie dus la Kin'weelay, in Stranglethorn Vale, la Grom'gol Base Camp. Printre trollii Darkspear, niciun witchdoctor nu este mai puternic decat Kin'weelay, iar Nazeer crede ca, daca poate cineva, Kin'weelay ii poate atinge spiritul lui Marg."},{t="Vorbe la Grom'gol",b="Kin'weelay simte un spirit manios in jurul tau cand sosesti. Privind capul, witch doctor-ul vede ca spiritul orcului e legat de aceasta lume si fierbe de furie din cauza unei datorii neindeplinite, asa ca propune sa stea de vorba cu el."}},faq={{q="De ce trebuie dusa capul lui Marg Nighteye in Stranglethorn Vale?",a="Nazeer Bloodpike spune ca singura modalitate de a afla ce s-a intamplat la moartea lui Marg este magia vrajitoreasca a trollilor, iar Kin'weelay se afla la Grom'gol Base Camp.",al={"de ce sa mergi in stranglethorn","de ce grom'gol","de ce kin'weelay"}},{q="Cine este Kin'weelay?",a="Cel mai puternic witchdoctor dintre trollii Darkspear se afla la Grom'gol Base Camp, in Stranglethorn Vale.",al={"cine este witchdoctor","witchdoctor kin'weelay"}},{q="Ce urmeaza dupa acest pas?",a="Urmatorul pas este Marg Speaks.",al={"care este urmatoarea misiune","dupa Troll Witchdoctor"}}},fp="21,206,25.377.0,17.225.1,61.141.0,18.104.0,27.29.0"}
P.entries["quest:1241"] = {n="The Missing Diplomat",s="In Stormwind, incepe o ancheta urgenta dupa ce un diplomat nu ajunge la Theramore Isle. Bishop DeLavey suspecteaza o tradare din partea Defias si trimite agenti de incredere la Jorgen, un contact discret din Valley of Heroes.",h="In Stormwind, incepe o ancheta urgenta dupa ce un diplomat nu ajunge la Theramore Isle.",kw={"defias","delavey","jaina","jorgen","diplomat disparut","stormwind","theramore","valley of heroes"},ang={["class:Priest"]="Bishop DeLavey foloseste legaturile bisericii pentru a investiga discret crimele de stat, atunci cand canalele regale obisnuite ar putea fi compromise.",["class:Rogue"]="Jorgen este un contact de multa vreme, iar profilul sau discret ajuta la urmarirea emisarilor disparuti prin reteaua de spionaj subterana, ascunsa sub strazile impecabile ale Stormwindului.",["faction:Alliance"]="Disparitia diplomatului regal pune in pericol negocierile delicate dintre Stormwind si avanpostul lui Lady Jaina Proudmoore din Theramore.",["race:Human"]="Ameninarea Defias Brotherhood depaseste granitele Westfall si ajunge pana in capitala, punand in pericol stabilitatea regatului Human."},sec={{t="O disparitie in umbre",b="Un diplomat de rang inalt a navigat din Eastern Kingdoms pentru a o intalni pe Lady Jaina Proudmoore in Theramore Isle, in cadrul unor discutii delicate, dar nu a ajuns niciodata la destinatie. Anchetatorii regali cauta indicii in Stormwind. Disparitia este tinuta secreta pentru a preveni panica si a impiedica conspiratorii sa afle ca este supravegheata curtea."},{t="Cercetari discrete",b="Bishop DeLavey crede ca Defias Brotherhood l-a rapit pe diplomat, dar nu se bazeaza doar pe garda regelui. Apeleaza la contacte discrete si il cauta pe Jorgen, un vechi cunoscut care pescuieste ferit de priviri in Valley of Heroes, chiar dincolo de portile orasului."},{t="Un informator reticent",b="Jorgen pastreaza o atitudine ursuza si un post modest langa apele orasului, dar isi respecta vechile obligatii fata de DeLavey. El avertizeaza ca urmarirea traseului diplomatului implica riscuri mortale. Oricine se implica in ancheta trebuie sa pastreze tacerea."}},faq={{q="Cine este diplomatul disparut?",a="Church of the Light si tronul din Stormwind protejeaza identitatea diplomatului, referindu-se la acesta doar drept un diplomat important trimis peste Great Sea, in Theramore.",al={"identitatea diplomatului disparut","cine a disparut","cine a pierit fara urma","identitatea diplomatului"}},{q="De ce calatorea diplomatul spre Theramore?",a="Diplomatul a fost trimis sa se intalneasca cu Lady Jaina Proudmoore pentru discutii cruciale despre securitatea si starea Alliance dintre Eastern Kingdoms si Kalimdor.",al={"de ce Theramore","scopul diplomatului","ce facea diplomatul"}},{q="De cine il banuieste Bishop DeLavey?",a="Bishop DeLavey banuieste ca Defias Brotherhood l-a rapit pe diplomat, desi metodele si complicii lor din oras raman necunoscuti.",al={"cine l-a rapit pe diplomat","suspectul delavey"}},{q="Cine este Jorgen?",a="Jorgen este agent si vechi cunoscut personal al lui Bishop DeLavey; pescuieste in Valley of Heroes din Stormwind, chiar in interiorul portilor orasului.",al={"unde este jorgen","identitatea lui jorgen","cine este pescarul"}},{q="De ce este tinuta aceasta chestiune secreta fata de public?",a="Autoritatile tin lucrurile ascunse deoarece dezvaluirea faptului ca un emisar vital a fost rapit chiar sub nasul tronului ar putea provoca haos si i-ar avertiza pe conspiratori ca agentii regali ii vaneaza.",al={"de ce secretul","de ce sa pastrezi secret","de ce sa nu spui orasului"}},{q="Unde duce aceasta investigatie?",a="Jorgen indreapta ancheta spre lumea interlopa si retelele ascunse din Stormwind, pentru a descoperi locul unde a fost interceptat diplomatul.",al={"ce se intampla mai departe","unde merg dupa jorgen"}}},fx={["02dad4d3"]={q="De ce are Bishop DeLavey nevoie de un aventurier in locul garzii regale?",a="Agentii regelui scotocesc deja prin Stormwind, dar Bishop DeLavey prefera sa-si urmeze propriile piste discrete, in afara supravegherii oficiale a coroanei. Incredintand treaba unui curier particular, poate apela la contacte independente precum Jorgen fara sa atraga atentia publicului larg sau sa-i alerteze pe conspiratorii din oras.",al={"de ce eu pentru missing diplomat","de ce nu garzile orasului pentru missing diplomat","de ce eu, bishop delavey"}}},fp="20,211,26.306.0,17.272.0,21.223.1,28.162.0,44.158.0,32.134.0,14.144.0,46.194.0,35.125.0"}
P.entries["quest:1242"] = {n="The Missing Diplomat",s="Jorgen trimite agenti de incredere prin Stormwind cu un bilet sigilat pentru Elling Trias. Mesajul duce cautarile diplomatului disparut din Valley of Heroes pana la Trias' Cheese din Trade District.",h="Jorgen trimite agenti de incredere prin Stormwind cu un bilet sigilat pentru Elling Trias.",kw={"Elling Trias","Jorgen","diplomat disparut","bilet sigilat","Stormwind","Trade District","branza Trias"},ang={["class:Rogue"]="Ca rogue, poti banui ca Trias' Cheese este mai mult decat un magazin de lactate. Proprietarul sau pastreaza legaturi discrete mult dincolo de Trade District.",["faction:Alliance"]="Ca membru al Alliance, poti vedea cum cautarea discreta a emisarului disparut dezvaluie vulnerabilitati subtile in conducerea Stormwind."},sec={{t="O livrare discreta",b="Dupa primele cercetari privind disparitia diplomatului, Jorgen le cere agentilor de incredere sa pastreze tacerea si sa duca un bilet sigilat prin oras. Acesta este destinat magazinului Trias' Cheese din Trade District al Stormwind, nu unei cazarmi sau unui birou de magistrat. Predarea ocoleste canalele obisnuite ale garzilor, pe masura ce ingrijorarea cu privire la diplomatul disparut ajunge dincolo de palat."},{t="In spatele pravaliai",b="Elling Trias este un negustor de branza vesel, harnic si respectat la Trias' Cheese. Trecutul sau alaturi de Jorgen si propriile sale contacte depasesc cu mult limitele pravaliei. Odata ce biletul lui Jorgen a fost livrat, cautarea diplomatului disparut trece in tacere in mainile lui Trias."}},faq={{q="Cine este Elling Trias?",a="Elling Trias este un negustor respectat care conduce Trias' Cheese in Trade District din Stormwind. El are un trecut comun cu Jorgen si contacte pe care le poate folosi in chestiuni delicate.",al={"cine este trias","vanzator de branza","identitatea lui elling trias"}},{q="De ce imi spune Jorgen sa pastrez tacerea?",a="Jorgen cere tacere fiindca disparitia diplomatului este o chestiune de stat. Vestea ar putea starni panica sau l-ar putea alerta pe cel care a organizat rapirea, dezvaluind ca a inceput o ancheta.",al={"de ce tacere","avertismentul lui Jorgen","tine-ti gura inchisa"}},{q="Unde pot gasi Trias' Cheese?",a="Trias' Cheese se afla in Trade District din Stormwind City, de-a lungul bulevardelor principale, printre negustori si mesteri.",al={"locatia lui Trias","locatia magazinului de branza","unde este Elling Trias"}},{q="Ce contine biletul sigilat adresat lui Elling?",a="Biletul sigilat al lui Jorgen il informeaza pe Elling Trias despre diplomatul disparut si ii cere sa-si foloseasca relatiile si urechile din lumea subterana pentru a gasi urme pe care autoritatile obisnuite nu le pot depista.",al={"continutul biletului","ce scrie in bilet","bilet sigilat pentru Elling"}},{q="Cine este diplomatul disparut mentionat in misiune?",a="Curtea regala pazeste identitatea diplomatului in aceasta etapa. Secretul si ingrijorarea sugereaza ca este vorba despre cineva de o imensa importanta politica pentru Kingdom of Stormwind.",al={"cine lipseste","cine este diplomatul","identitatea persoanei disparute"}},{q="De ce ar folosi investigatia un negustor de branza in locul garzii orasului?",a="Garda orasului este constransa de protocol, jurisdictie si legaturi politice. Elling Trias poate ajunge la zvonurile de pe strazi si la contacte discrete, dincolo de raza de actiune a soldatilor.",al={"de ce un negustor de branza","de ce Trias, nu garzile","garzile sau Trias"}}},fx={c433039c={q="De ce vrea Jorgen ca aceasta scrisoare sa fie livrata lui Elling Trias?",a="Jorgen stie ca gasirea diplomatului disparut este o misiune delicata si secreta, cu mult peste puterile unui simplu agent de teren. Elling Trias poate parea un vanzator de branza obisnuit din Trade District, dar are legaturi subterane si informatii esentiale pentru cercetare. Jorgen trebuie sa-i transmita descoperirile in siguranta, fara sa dea de banuit celor care supravegheaza locul.",al={"de ce sa-i trimiti un bilet lui elling trias","motivul lui jorgen in cazul diplomatului disparut","de ce sa predai biletul sigilat"}}},fp="20,208,19.354.0,20.259.1,20.174.0,38.190.0,31.106.0,37.179.0,51.165.0,73.156.0"}
P.entries["quest:1243"] = {n="The Missing Diplomat",s="Elling Trias te trimite spre sud sa cauti vesti despre diplomatul disparut. Indiciile din Stormwind duc spre Duskwood si Watcher Backus, un contact din apropierea Darkshire care ar putea sti ceva despre activitatea Defias.",h="Elling Trias te trimite spre sud sa cauti vesti despre diplomatul disparut.",kw={"darkshire","defias","duskwood","elling trias","jorgen","missing diplomat","night watch","watcher backus"},ang={["class:Rogue"]="Ca rogue, vezi cum Elling Trias isi desfasoara activitatea printr-o retea. El se bazeaza pe soldati de infanterie independenti pentru a aduna informatii, pastrandu-si in acelasi timp mainile curate.",["faction:Alliance"]="Ca erou Alliance, ajuti la cercetarea unei disparitii care priveste interesele regale din Stormwind. Cautarea ii reuneste pe spionii regali, infractorii independenti si militiile regionale."},sec={{t="Pasi prin intuneric",b="Dupa o discutie frustranta cu Jorgen, negustorul de branza Elling Trias apeleaza la cercul sau mai larg de informatori. Ca sa-si pastreze banii, te trimite pe tine sa faci cercetarile pe teren, in loc sa angajeze agenti. Ducand o scrisoare sigilata peste granita, in Duskwood, te expui primejdiilor calatoriei printre bestii si Undead."},{t="O ureche prietenoasa in Night Watch",b="Watcher Backus slujeste in Night Watch si patruleaza pe drumul de apropiere dinspre nord catre Darkshire. Trias are incredere in el ca va raporta miscarile ilicite prin Duskwood, in ciuda primejdiilor de pe drumuri. Arata-i lui Backus scrisoarea sigilata, iar el iti poate impartasi registrele garzii si zvonuri locale despre operatiunile Defias Brotherhood din sud."}},faq={{q="De ce ma trimite Elling Trias in Duskwood?",a="Elling Trias urmareste piste despre diplomatul disparut si activitatile suspecte ale Defias Brotherhood. Pentru a-si folosi contactele fara sa cheltuiasca bani pe agenti, te trimite sa-l intrebi pe Watcher Backus ce se intampla in Duskwood.",al={"de ce sa mergi in Duskwood","treaba lui Trias in Duskwood","de ce Darkshire"}},{q="Unde il pot gasi pe Watcher Backus?",a="Watcher Backus patruleaza drumul de pamant din nord, chiar in afara Darkshire, in Duskwood, de-a lungul drumului spre Redridge si Elwynn Forest.",al={"locatia lui Watcher Backus","unde se afla Backus","gaseste-l pe Backus"}},{q="Cine este Watcher Backus?",a="Watcher Backus este un soldat din militia civila a Darkshire, Night Watch. Il cunoaste personal pe Elling Trias si ii impartaseste ce observa despre calatorii suspecti si miscarile infractorilor.",al={"povestea lui backus","cine este backus"}},{q="Ce contine biletul sigilat primit de Backus?",a="Nota sigilata a lui Elling Trias ii cere lui Watcher Backus informatii despre aparitiile sau deplasarile celor din Defias Brotherhood prin Duskwood.",al={"continutul notei sigilate","ce scrie in nota","Sealed Note to Watcher Backus"}},{q="Ce legatura are Duskwood cu Defias Brotherhood?",a="Defias Brotherhood isi are centrul in Westfall si se ascunde sub Deadmines. Celulele, curierii si ascunzatorile sale ajung si in provinciile sudice ale oamenilor, inclusiv la marginile umbrite din Duskwood.",al={"defias in Duskwood","sunt defias in Duskwood"}},{q="De ce se plange Trias de Jorgen?",a="Jorgen a refuzat sa vorbeasca cu Trias sau a negociat dur in timpul anchetei. Trias s-a enervat atat de tare, incat l-a blestemat pe Jorgen sa ajunga in Twisting Nether, apoi a cautat alti informatori pe teren.",al={"cine este jorgen","trias si jorgen"}}},fx={["8b2965b1"]={q="De ce vrea Elling Trias ca aceasta sarcina sa fie indeplinita?",a="Elling Trias poate parea un umil maestru al branzeturilor fine, dar are o retea vasta de contacte si a acceptat sa cerceteze disparitia diplomatului disparut. Orice indiciu al implicarii Defias Brotherhood ar putea duce la dezlegarea cazului, asa ca te trimite pe urmele pistei din Duskwood, in timp ce isi pune la lucru propriile surse din oras.",al={"de ce ii pasa lui Trias","motivul lui Trias","motivul lui Elling Trias"}},c3fdc8e2={q="De ce te pune Elling Trias sa faci treaba in loc sa o faca el insusi?",a="Trias nu-si ascunde pragmatismul: trimiterea unui aventurier il scuteste de cheltuieli insemnate si ii lasa timp sa lucreze cu contactele sale discrete din Stormwind City. Un negustor cunoscut, ratacind prin mohoratul Duskwood, ar atrage atentia degeaba, pe cand un investigator calator poate vorbi discret cu garzi locale precum Watcher Backus fara sa alerteze privirile Defias.",al={"de ce sa ma trimita pe mine","de ce are Trias nevoie de mine","de ce nu se duce el insusi"}}},fp="20,185,21.300.0,33.316.0,43.217.0,32.131.0,22.179.0,43.142.0,58.201.0,37.189.0"}
P.entries["quest:1244"] = {n="The Missing Diplomat",s="In Duskwood, cautarea diplomatului disparut din Stormwind urmeaza o pista de la Watcher Backus catre documente Defias de la Addle's Stead.",h="In Duskwood, cautarea diplomatului disparut din Stormwind urmeaza o pista de la Watcher Backus catre...",kw={"Addle's Stead","Defias Docket","Duskwood","caseta pentru picior","Night Watch","diplomatul disparut","Watcher Backus"},ang={["class:Rogue"]="Ca rogue, trebuie sa te descurci prin retelele criminale si sa deosebesti informatiile autentice de diversiunea Defias.",["faction:Alliance"]="Disparitia emisarului regatului pune in pericol securitatea Stormwind. Intrigile Defias merg mult dincolo de talhariile marunte de pe drumurile din Westfall."},sec={{t="O pista in bezna",b="Watcher Backus din Night Watch duce cercetarile pana in Duskwood. El spune ca, in urma cu cateva saptamani, un grup neobisnuit de mare de banditi Defias a venit la Addle's Stead. De obicei, banditii isi vad de treaba de cealalta parte a granitei, in Westfall, asa ca adunarea lor in padurile intunecate este o miscare iesita din comun. Acum cauti ferma abandonata, in cautarea documentelor pe care le-au lasat in urma."},{t="Defias Docket",b="La ferma cotropita, gasesti o cutie de voiaj incuiata, in care se afla un Defias Docket. Documentele confirma implicarea fratiei, dar Watcher Backus te avertizeaza sa fii precaut. Este posibil ca Defias sa le fi falsificat pentru a-i induce in eroare pe anchetatori."}},faq={{q="Unde se afla Addle's Stead?",a="Addle's Stead se afla in vestul regiunii Duskwood, chiar la sud de drumul principal dinspre Westfall. Agenti ostili Defias ocupa ferma darapanata.",al={"locatia fermei Addle","unde se afla Addle's Stead","gaseste Addle's Stead"}},{q="Ce este Defias Docket?",a="Defias Docket este o colectie de documente cu aspect oficial, aflata intr-o lada pentru picioare la Addle's Stead. Aceasta descrie cateva dintre operatiunile clandestine recente ale Brotherhood-ului din regiune.",al={"defias docket","ce este registrul","documentul adunarii din stead"}},{q="Cine este Watcher Backus?",a="Watcher Backus este membru al Night Watch, stationat in Duskwood. Contactele sale din oras si supravegherea amenintarilor de la granita il ajuta sa urmareasca deplasarile neobisnuite ale Defias de-a lungul granitei cu Westfall.",al={"watcher backus","cine este backus","backus duskwood"}},{q="De ce opereaza Defias in Duskwood?",a="Agentii Defias patrund pe furis in vestul Duskwood, desi cetatea lor se afla peste granita, in Westfall. Addle's Stead este un punct de oprire izolat, departe de patrulele din Stormwind.",al={"de ce se afla Defias in Duskwood","Defias la Addle's Stead"}},{q="Se poate avea incredere in continutul Defias Docket?",a="Watcher Backus avertizeaza ca Defias ar fi putut lasa indicii false pentru a-i abate pe anchetatori de la urma lor. Dosarul pare autentic, dar continutul sau ar putea fi o diversiune.",al={"este registrul autentic","falsificarea registrului","este o copie"}},{q="Cine i-a indrumat initial pe anchetatori catre Watcher Backus?",a="Watcher Backus spune ca Elling Trias, negustor de branza si informator clandestin din Stormwind, a indrumat investigatia catre Night Watch din Duskwood.",al={"cine m-a trimis la Backus","legatura cu Trias"}}},fx={["860270d2"]={q="De ce te trimite Watcher Backus la Addle's Stead?",a="Watcher Backus considera orice prezenta Defias in Duskwood o amenintare iminenta la adresa hotarelor din Darkshire, chiar si cand membrii sai pastreaza tacerea. Cu cateva saptamani in urma, o adunare neobisnuita a agentilor lor la Addle's Stead a atras atentia Night Watch. Backus a banuit ca acolo s-a petrecut ceva important, ceea ce face din acel loc pista cea mai promitatoare in ancheta ta asupra miscarilor clandestine ale fratiei.",al={"de ce vrea backus sa se faca asta","motivul lui watcher backus","de ce sa investighez addle's stead"}}},fp="20,126,19.362.0,17.231.1,31.135.0,26.168.0,22.186.0,41.189.0,49.171.0,59.154.0"}
P.entries["quest:1245"] = {n="The Missing Diplomat",s="Duci Defias Docket recuperat inapoi la Stormwind, in timp ce cautarea unui diplomat disparut devine tot mai periculoasa.",h="Duci Defias Docket recuperat inapoi la Stormwind, in timp ce cautarea unui diplomat disparut devine tot mai...",kw={"Defias Docket","Duskwood","Elling Trias","pumn","diplomat disparut","Stormwind","Watcher Backus"},ang={["class:Rogue"]="Elling Trias arata cum mestesugul unui rogue poate inlocui pumnalele cu retele de informatori. Ca rogue, vezi cum un maestru al spionilor descifreaza codurile Defias in razboaiele din umbra ale coroanei.",["faction:Alliance"]="Ca membru al Alliance, vezi cat de mult s-a erodat securitatea Stormwindului de la Third War incoace, in timp ce planurile Defias ameninta regatul din interior."},sec={{t="Prea grea pentru Night Watch",b="In Duskwood, Watcher Backus nu vrea sa aiba de-a face cu Defias Docket pe care l-ai recuperat. Documentele descriu planuri prea elaborate pentru a fi simple jafuri sau o diversiune. Temandu-se de pedeapsa regala si neincrezator fata de superiorii sai din Night Watch, Backus iti cere sa pastrezi tacerea in privinta implicarii lui. Documentele indica intrigi destul de primejdioase incat sa puna capat carierelor sau vietilor, asa ca le duci la Stormwind."},{t="Negotul adevarat al unui negustor de branza",b="Inapoi in Trade District din Stormwind, maestrul negustor de branzeturi Elling Trias renunta la prefacatoria de pravalias cand te intorci. El studiaza documentul in calitate de coordonator intr-o retea de informatii secrete a regatului. Hartiile descriu planurile minutioase ale Defias Brotherhood si dezvaluie un nume de cod sumbru: 'Fist'. Diplomatul disparut a fost tinta unei retele bine organizate si bine conectate, cu influenta adanca in interiorul regatului."}},faq={{q="Ce este Defias Docket?",a="Defias Docket este o colectie de documente sensibile recuperate de tine in Duskwood, care prezinta planurile Defias Brotherhood. Complexitatea lor ii inspaimanta pe paznicii locali si ii ofera maestrului Trias piste noi in cautarea diplomatului disparut.",al={"Defias Docket","ce sunt documentele","continutul dosarului"}},{q="De ce ii este atat de teama lui Watcher Backus sa pastreze dosarul?",a="Watcher Backus se teme ca dosarul contine informatii care depasesc autoritatea unui paznic de noapte din Duskwood. Isi face griji ca, daca superiorii sai sau autoritatile Stormwindului afla ca a manuit ori a ascuns asemenea informatii, ar putea fi spanzurat pentru tradare.",al={"de ce se teme backus","teama lui watcher backus"}},{q="De ce sa duci documentele proprietarului unui magazin de branzeturi din Stormwind?",a="Elling Trias se da drept negustor de branza, dar este un maestru al spionajului din Stormwind si o figura-cheie in reteaua clandestina de informatii a regatului. Cunostintele si legaturile sale il ajuta sa descifreze planurile Defias.",al={"de ce elling trias","de ce trias si branza"}},{q="Cine este 'Fist', mentionat in registru?",a="Elling Trias recunoaste in registru termenul 'Fist' ca nume de cod pentru cineva implicat in coordonarea de catre Defias Brotherhood a complotului de rapire.",al={"cine este Fist","Fist, defias","nume de cod Fist"}},{q="Incotro duce aceasta investigatie?",a="Detaliile din registru ii permit lui Trias sa urmareasca mai departe conspiratorii. Te trimite sa interoghezi contactele si sa-l cauti pe 'Fist' pentru a afla unde a fost dus diplomatul.",al={"urmatorul pas","ce urmeaza dupa registru","unde merg mai departe"}},{q="Ce legatura are asta cu regele Varian Wrynn?",a="Registrul nu-l mentioneaza pe regele Varian Wrynn. Cauti un diplomat al carui nume nu este dezvaluit si care nu a ajuns niciodata in Theramore, iar lectura documentelor de catre Trias nu ii dezvaluie identitatea.",al={"este Varian diplomatul","legatura cu regele Varian"}}},fx={["74ee0470"]={q="De ce are Watcher Backus nevoie de tine in loc sa ia el insusi condica?",a="Watcher Backus este ingrozit de ceea ce scrie in Defias Docket. Ca membru al Night Watch, are datoria sa raporteze chestiunile de stat superiorilor sai, dar stie ca pastrarea unor documente despre o conspiratie tradatoare in afara canalelor oficiale l-ar putea costa viata. Daca superiorii sai afla ca a avut aceste informatii si le-a ascuns, se teme ca va fi spanzurat. Tu esti un investigator independent care lucreaza deja cu Trias, ceea ce ii permite lui Backus sa se spele pe maini de intriga mortala, asigurandu-se totodata ca documentele ajung la cineva in stare sa le descifreze.",al={"de ce eu","de ce nu livreaza backus dosarul","de ce ma trimiti la trias"}}},fp="20,114,29.375.0,27.406.1,26.238.0,51.235.0,56.198.0,38.139.0,40.153.0,49.190.1"}
P.entries["quest:1246"] = {n="The Missing Diplomat",s="In Old Town, o pista din cazul diplomatului disparut duce la un bataus de strada. Elling Trias te trimite sa-l gasesti pe Dashel Stonefist si sa obtii raspunsuri despre documentele suspecte. Ancheta ajunge pe strazile rau famate din Stormwind.",h="In Old Town, o pista din cazul diplomatului disparut duce la un bataus de strada.",kw={"dashel stonefist","elling trias","pumn","diplomat disparut","orasul vechi","stormwind"},ang={["class:Rogue"]="Ca rogue, te simti ca acasa in Old Town, printre informatori precum Trias si batausi pusi sa impuna legea precum Stonefist.",["faction:Alliance"]="Ca membru al Alliance, stii ca dezvaluirea conspiratiei din spatele diplomatului disparut este importanta pentru stabilitatea Alliance si pentru regatul aflat in centrul ei.",["race:Human"]="Ca Human din Stormwind, vezi dovezi ingrijoratoare ca derbedeii de pe strazi ajuta la inalta tradare impotriva conducerii regatului."},sec={{t="O pista in Old Town",b="Elling Trias isi aminteste un nume legat de notitele codificate si de piste: Dashel Stonefist, cunoscut ca Fist. Este un bataus de strada dur, foarte departe de nobilii din jurul Cathedral Square. Stonefist sta mai mult prin ulitele inghesuite din Old Town. Gasirea lui muta cautarile din salile impunatoare ale Stormwind Keep in cercurile criminale ale orasului."},{t="Convingere cu pumnul",b="Elling Trias avertizeaza ca Dashel Stonefist nu va vorbi deschis cu straini curiosi, mai ales cand e vorba de tradare si rapiri. Daca intrebarile nu dau roade, spune Trias, va trebui sa vorbeasca forta. Stonefist considera ulitele domeniul sau si nu suporta ca strainii sa scormoneasca prin treburi care l-ar putea lasa fara mijloace de trai sau l-ar putea costa capul."}},faq={{q="Cine este Dashel Stonefist?",a="Dashel Stonefist este un bataus notoriu care frecventeaza aleile centrale din Old Town din Stormwind. Trias il leaga de documentele compromitatoare gasite in timpul cautarii diplomatului disparut.",al={"dashel stonefist","cine este fist","dashel"}},{q="Unde pot gasi Dashel Stonefist?",a="Dashel Stonefist zaboveste afara, pe aleile din apropierea centrului cartierului Old Town, departe de strazile sale principale.",al={"locatia lui Dashel Stonefist","unde este Dashel","unde este Stonefist"}},{q="De ce ma trimite Elling Trias pe urmele lui?",a="Trias asociaza numele lui Dashel cu documente despre disparitia trimisului regelui. Dashel poate cunoaste nume, locuri sau ordine legate de cei care au organizat rapirea.",al={"de ce sa te lupti cu Dashel","motivul lui Trias"}},{q="Va coopera Dashel de bunavoie?",a="Nu. Stonefist este ostil strainilor care se amesteca in treburile sale. Trias se asteapta sa se impotriveasca si te sfatuieste sa folosesti o arma sau pumnii pentru a-l face sa vorbeasca.",al={"dashel vorbeste","stonefist prietenos"}},{q="Ce se intampla dupa ce il gasesti pe Dashel?",a="Infruntarea lui Dashel duce la o incaierare. Dupa ce este potolit, iti ofera indicii despre reteaua din spatele rapirii diplomatului si iti dezvaluie alti conspiratori din regat.",al={"diplomatul disparut, urmatorul pas","ce urmeaza dupa Dashel"}},{q="Cine este diplomatul disparut mentionat in misiune?",a="Autoritatile din Stormwind vorbesc doar despre un diplomat neidentificat, disparut in timp ce calatorea spre Theramore pentru a se intalni cu Jaina Proudmoore. Identitatea trimisului ramane un secret bine pazit in aceasta etapa a anchetei.",al={"cine este diplomatul disparut","care diplomat"}}},fx={["8d360f6b"]={q="De ce te trimite Elling Trias in locul garzilor orasului?",a="Elling isi desfasoara activitatea prin secrete, zvonuri si legaturi politice delicate, nu prin autoritate fatisa. Disparitia unui diplomat de rang inalt este o chestiune exploziva, iar implicarea garzii orasului Stormwind ar starni panica publica si i-ar alerta pe conspiratori ca cineva le-a dat de urma. Trias are nevoie de un anchetator independent, capabil sa se strecoare in liniste pe aleile dosnice din Old Town, sa puna intrebari periculoase si sa-i faca pe unii sa-si inghita dintii, fara sa atraga mana grea - si atentia zgomotoasa - a legii.",al={"de ce sa ma trimiti pe mine","de ce nu garzile din Stormwind","de ce nu gardienii orasului"}}},fp="20,224,18.321.0,22.325.1,24.187.0,34.104.0,41.157.0,32.155.0,34.173.1,51.213.2"}
P.entries["quest:1247"] = {n="The Missing Diplomat",s="Dashel Stonefist a marturisit in Old Town, iar tu ii duci avertismentul lui Elling Trias. Huliganul dezvaluie un plan de rapire de rezerva si un contact din Menethil Harbor.",h="Dashel Stonefist a marturisit in Old Town, iar tu ii duci avertismentul lui Elling Trias.",kw={"Addle's Stead","Dashel Stonefist","Elling Trias","Menethil","diplomatul disparut","Slim","Stormwind"},ang={["class:Rogue"]="Ca rogue, stii cat de usor se pot intersecta infractiunile stradale si secretele statului, de la batausii din spatele aleilor ai lui Dashel pana la activitatea discreta de spionaj a lui Trias.",["faction:Alliance"]="Ca membru al Alliance, stii ca disparitia trimisului afecteaza stabilitatea Alliance, iar sabotajul ameninta conducerea din Stormwind.",["race:Human"]="Ca Human, vezi cum se desfasoara o conspiratie in granitele Stormwindului, in timp ce regele-copil sta pe tron."},sec={{t="O crapatura in zid",b="Dashel Stonefist cedeaza cand se teme pentru sanatatea lui. Intr-o alee din Old Town, recunoaste ca primul plan al conspiratorilor de a comite o rapire a esuat, naruindu-i rolul in complot. Pentru a da vina pe altii, iti povesteste despre o intalnire secreta de acum cateva saptamani, la Addle's Stead din Duskwood. Numeste si o pista pentru planul lor de rezerva: o persoana din interiorul Menethil Harbor, cunoscuta doar ca Slim."},{t="Raport catre Fromager",b="Elling Trias strange secrete pentru Coroana de dupa tejgheaua pravaliei Trias' Cheese din Trade District. In timp ce il interogai pe Dashel, Trias a studiat mesajele capturate despre complot. Marturisirea corespunde dezvaluirilor din ele: conspiratorii au vizat un diplomat al carui nume nu a fost dezvaluit, prima ambuscada a esuat, iar un plan de rezerva a fost pus in miscare prin Wetlands. Odata aflat numele lui Slim, cautarile se indreapta spre nord, din Stormwind catre mlastini."}},faq={{q="Cine este Dashel Stonefist?",a="Dashel Stonefist este un intermediar si un om de forta in Old Town din Stormwind. Avand legaturi cu lumea subterana Defias, a ajutat la punerea in aplicare a primului plan de capturare a solului Stormwind, apoi a oferit informatii cand a fost confruntat.",al={"dashel stonefist","cine este dashel","stonefist din stormwind"}},{q="De ce este Elling Trias implicat in aceasta ancheta?",a="Elling Trias culege secrete pentru Stormwind, dand impresia ca este un maestru al branzeturilor fine. Magazinul sau din Trade District ii permite sa coordoneze anchete discrete, in afara razei de actiune a garzii orasului.",al={"de ce Elling Trias","vanzatorul de branza e spion","informatiile lui Trias"}},{q="Ce s-a intamplat la Addle's Stead?",a="Conspiratorii s-au intalnit cu cateva saptamani in urma la Addle's Stead, o ferma abandonata din vestul Duskwood, pentru a-si planui rapirile, dupa ce prima tentativa le-a fost dejucata.",al={"intalnire la Addle's Stead","Addle's Stead","intalnire in Westfall"}},{q="Cine este diplomatul pe care incercau sa-l rapeasca?",a="Documentele conspiratorilor si golanii de pe strazi le identifica tinta doar ca pe un diplomat fara nume, aflat in drum spre Theramore. Identitatea emisarului este pastrata cu mare grija in acest punct al investigatiei.",al={"cine este diplomatul disparut","cine a fost rapit","identitatea diplomatului"}},{q="Cine este Slim?",a="Slim este numele pe care il da Dashel Stonefist pentru contactul care se ocupa de planul de rezerva din Menethil Harbor, Wetlands. Contactul reprezinta a doua ruta a conspiratorilor pentru transportul oamenilor si proviziilor.",al={"cine este Slim","Slim Menethil","persoana de contact Menethil"}},{q="Unde duce urma dupa aceasta?",a="Pista duce spre nord, la Menethil Harbor din Wetlands, unde se spune ca se afla Slim. Elling Trias confirma informatiile lui Dashel.",al={"urmatorul pas in Missing Diplomat","unde merg dupa dashel","ce urmeaza"}}},fx={a7b1abaf={q="De ce vorbeste Dashel Stonefist acum?",a="Dashel vorbeste doar fiindca tocmai l-ai batut pana s-a supus. Dandu-si seama ca derbedeii lui nu-l puteau apara de tine, se grabeste sa-si salveze pielea, dezvaluind putinul pe care il stie despre planul de rezerva al conspiratiei si incercand sa-ti abata atentia de la el.",al={"de ce vorbeste Dashel","motivul lui Dashel Stonefist","de ce a marturisit Dashel"}}},fp="20,159,19.362.0,25.420.1,24.204.0,51.178.0,31.154.0,47.196.2,12.204.0,37.127.0"}
P.entries["quest:1248"] = {n="The Missing Diplomat",s="Missing Diplomat este o misiune de investigatie ce urmareste rapirea unui trimis anonim din Stormwind. Urmand indiciile dintr-un registru interceptat, agentii calatoresc la Menethil Harbor, in Wetlands, pentru a se consulta cu un contact retras si a-l gasi pe un suspect pe nume Slim.",h="Missing Diplomat este o misiune de investigatie ce urmareste rapirea unui trimis anonim din Stormwind.",kw={"dosar","Menethil Harbor","Mikhail","Slim","Stormwind","The Missing Diplomat","Trias","Wetlands"},ang={["class:Rogue"]="Descifrarea dosarelor secrete, gasirea vechilor contacte iesite la pensie si interogarea discreta a suspectilor in taverne aglomerate tin de tehnicile operatiunilor sub acoperire.",["faction:Alliance"]="Investigarea rapirii diplomatului priveste direct chestiuni de securitate la nivel inalt din Stormwind si raza de actiune a conspiratorilor din teritoriile Alliance."},sec={{t="O urma spre Wetlands",b="Ancheta privind rapirea unui diplomat duce dincolo de portile Stormwind, spre docurile invaluite in ceata din Menethil Harbor, in Wetlands. Un document interceptat confirma ca un diplomat a fost vizat si rapit, dar lasa lacune esentiale: nici identitatea reala a diplomatului, nici destinatia finala a conspiratorilor nu sunt precizate in actele recuperate. Pentru a rupe tacerea, anchetatorii trebuie sa cerceteze multimea schimbatoare din port si afacerile clandestine."},{t="Legaturi discrete in Menethil",b="Pentru a relua pista in Menethil, agentii sunt trimisi la Mikhail, fost asociat al lui Elling Trias, care s-a retras din Stormwind cu cativa ani in urma si se ocupa acum de tejgheaua tavernei locale. Mikhail este legatura esentiala pentru a-l gasi pe cel cunoscut doar drept Slim, care ar putea sti unde a fost dus prizonierul sau cine a pus la cale rapirea. Intr-o taverna aglomerata, discretia este esentiala - simpla rostire a numelui Trias e suficienta pentru a indemna pe toata lumea sa taca imediat, inainte ca conspiratorii sa observe cercetarile."}},faq={{q="Cine este Mikhail?",a="Mikhail este un fost asociat al lui Elling Trias, care a parasit Stormwind cu mai multi ani in urma pentru a se retrage in Menethil Harbor, unde lucreaza acum ca barman. Trias ii indruma pe anchetatori catre el, considerandu-l un contact de incredere care poate ajuta la identificarea unui suspect pe nume Slim.",al={"cine este mikhail","mikhail din wetlands","barman din menethil"}},{q="Cine este Slim si de ce il cauta?",a="Slim este o persoana din Menethil Harbor despre care se crede ca detine informatii esentiale despre diplomatul rapit. Mikhail este contactat anume pentru a-l urmari pe Slim si a afla ce stie.",al={"cine este Slim","gaseste-l pe Slim","diplomatul disparut Slim"}},{q="Cine este diplomatul rapit?",a="Identitatea diplomatului este pastrata cu mare grija si ramane necunoscuta chiar si anchetatorilor. Documentul interceptat descrie o rapire, dar omite atat identitatea reala a diplomatului, cat si planurile ulterioare ale conspiratorilor dupa capturare.",al={"cine a fost rapit","identitatea diplomatului rapit","cine este diplomatul disparut"}},{q="De ce duce urma la Menethil Harbor?",a="Menethil Harbor este un important oras-port situat pe coasta din Wetlands. Investigatorii sunt indrumati acolo deoarece Mikhail, fostul contact al lui Trias, lucreaza ca barman in oras, iar pistele esentiale despre rapire duc prin port.",al={"unde este Menethil Harbor","de ce Wetlands","de ce sa mergi in Menethil"}},{q="Ce dezvaluie dosarul despre complot?",a="Dosarul este un document interceptat care descrie rapirea diplomatului. Desi confirma rapirea, are lacune evidente: nu precizeaza unde a fost dus prizonierul si nici ce intentioneaza rapitorii sa faca in continuare.",al={"ce dosar","dosarul lui Trias","ce spune dosarul"}},{q="Ce rol are Trias in aceasta misiune?",a="Elling Trias este contactul din Stormwind care coordoneaza investigatia. El trimite agenti la Mikhail fiindca Mikhail era un vechi asociat care promisese sa-l ajute pe Trias doar pe baza cuvantului sau, fara sa atraga atentia publicului.",al={"cine ne-a trimis la Mikhail","legatura cu Trias","de ce il mentioneaza pe Trias"}}},fp="20,269,23.454.0,29.468.1,15.250.0,45.197.0,30.232.0,43.237.0,43.215.0,44.214.0"}
P.entries["quest:1249"] = {n="The Missing Diplomat",s="Missing Diplomat este o investigatie ampla asupra disparitiei unui emisar important din Stormwind, urmarind indicii obscure din capitala pana in porturi indepartate. In Menethil Harbor, ancheta se intersecteaza cu personaje din lumea interlopa si cu vechi agenti legati de reteaua de informatii a Stormwind.",h="Missing Diplomat este o investigatie ampla asupra disparitiei unui emisar important din Stormwind, urmarind...",kw={"elling trias","menethil harbor","missing diplomat","slim","stormwind","the missing diplomat","wetlands"},ang={["class:Rogue"]="Agentii si coordonatorii clandestini precum Elling Trias se bazeaza pe investigatii discrete si contacte de strada pentru a-i gasi pe cei care scapa printre fisuri.",["faction:Alliance"]="Ancheta privind disparitia diplomatului atrage aventurieri Alliance in lumea interlopa din umbra, care leaga cercurile politice din Stormwind de docurile din Wetlands."},sec={{t="Curenti ascunsi in Menethil Harbor",b="Cautarea trimisului disparut al Stormwind ii conduce pe investigatori mult spre nord de capitala, in portul umed Menethil Harbor. Dincolo de docurile aglomerate si tavernele batute de vreme ale orasului se afla o retea subterana de negustori dubiosi si curieri clandestini, care isi desfasoara activitatea chiar sub nasul garzii locale. Urmarirea indiciilor prin acest nod de coasta presupune sa tratezi direct cu indivizi care cunosc latura intunecata a teritoriului Alliance."},{t="Un Rogue cunoscut",b="Capturarea lui Slim aduce un progres neasteptat in cautare, luandu-i prin surprindere pe informatorii locali, care nu stiau ca era implicat direct in aceasta afacere. Desi capturarea ofera raspunsuri esentiale, ea trezeste si amintiri in randul agentilor pensionati care isi duc traiul in Wetlands si care trebuie sa cantareasca daca sa ajute Coroana, riscand sa fie atrasi din nou in lumea interlopa plina de intrigi din Stormwind."}},faq={{q="Cine este Slim?",a="Slim este un contact dubios din Menethil Harbor, prins in timpul anchetei privind disparitia diplomatului, spre surprinderea contactelor locale, care nu se asteptau ca el sa fie implicat.",al={"cine este Slim","diplomatul disparut Slim","Slim prins"}},{q="Cine este Elling?",a="Elling Trias este o figura influenta care isi desfasoara activitatea din Stormwind City si mentine o retea clandestina de fosti rogue si informatori pe tot cuprinsul tinuturilor Alliance.",al={"elling trias","cine este elling","elling din stormwind"}},{q="Unde are loc aceasta etapa a investigatiei?",a="Aceasta etapa a investigatiei are loc in Menethil Harbor, un oras-port din Wetlands care leaga regatul Ironforge de tarmuri indepartate si de rutele comerciale ale Stormwind.",al={"unde se intampla","diplomat disparut din Menethil Harbor","diplomat din Wetlands"}},{q="Despre ce este lantul de misiuni Missing Diplomat?",a="Missing Diplomat este o investigatie asupra disparitiei unui emisar important din Stormwind, care urmareste agenti clandestini, conspiratori si contacte din lumea interlopa, in intregul regat si dincolo de hotarele lui.",al={"ce este missing diplomat","misiunea missing diplomat","cine lipseste"}},{q="De ce te avertizeaza contactul sa nu-i mentionezi asta lui Elling?",a="Contactul din Menethil Harbor a lucrat in trecut cu Elling Trias in cercurile subterane din Stormwind si evita sa-i dea de inteles lui Elling ca ii lipseste viata de odinioara, ca nu cumva acesta sa-l cheme inapoi in capitala.",al={"de ce este mentionat Elling","branza Trias","legatura cu Elling Trias"}},{q="Ce s-a intamplat cu ancheta din Menethil Harbor?",a="Dupa ce urmele duc la Menethil Harbor, portul din Wetlands, anchetatorul il infrunta si il prinde pe Slim, confirmand suspiciunile localnicilor despre activitati subterane ilegale in oras.",al={"ce s-a intamplat in Menethil Harbor","pista din Menethil","slim prins"}}},fp="20,289,32.416.0,16.383.1,12.174.0,14.161.0,53.170.0,47.197.0,60.197.0,56.180.0"}
P.entries["quest:125"] = {n="The Lost Tools",s="Cu Lakeshire amenintat de fortele ostile, intretinerea si apararea orasului depind in intregime de munca localnicilor. Uneltele esentiale ale Foreman Oslow, trimise din Goldshire, s-au pierdut cand focul catapultelor Blackrock i-a scufundat barca de transport in Lake Everstill. Recuperarea cufarului scufundat de pe fundul lacului este esentiala pentru reconstruirea podului distrus al orasului.",h="Cu Lakeshire amenintat de fortele ostile, intretinerea si apararea orasului depind in intregime de munca...",kw={"catapulta","foreman oslow","goldshire","lake everstill","lakeshire","murloc","redridge","thresher","trusa de unelte"},ang={["faction:Alliance"]="Lakeshire este bastionul estic al Alliance in fata amenintarii Blackrock clan; este esential sa le asiguri echipamentul constructorilor civili pentru a mentine frontiera din Kingdom of Stormwind.",["profession:Blacksmithing"]="Este greu sa se confectioneze unelte de calitate in conditii de asediu, asa ca recuperarea uneltelor specializate de fierarie si constructii din Goldshire este esentiala pentru oras."},sec={{t="O livrare care a luat-o razna",b="Legatura vitala dintre Lakeshire si Elwynn Forest a fost intrerupta de distrugerea Marelui Pod. Cand un transport de inlocuire cu unelte de zidarie si tamplarie a fost trimis pe uscat din Goldshire, nu a putut ajunge direct in oras. Echipajul a mutat proviziile intr-o barca cu vasle pentru a traversa Lake Everstill, insa ambarcatiunea a fost lovita direct de o catapulta a orcilor Blackrock. Barca a fost facuta tandari, iar trusa grea de scule a lui Oslow, intarita cu fier, s-a dus drept la fundul lacului."},{t="Pericolele adancurilor",b="Recuperarea trusei de scule este mult mai primejdioasa decat o scufundare obisnuita. Apele din Lake Everstill sunt infestate cu triburi agresive de murloci care pandesc in apele putin adanci, in timp ce threshers pradatori vaneaza in adancurile tulburi. In ciuda pericolului, recuperarea uneltelor este necesara pentru ca Foreman Oslow sa poata relua reparatiile podului si sa impiedice Lakeshire sa ajunga de tot in ruina."}},faq={{q="De ce au fost trimise uneltele cu barca de la bun inceput?",a="Drumul principal spre Lakeshire traverseaza un pod de piatra peste Lake Everstill, dar orcii Blackrock au aruncat in aer o portiune mare. Cum carutele cu provizii venite din Goldshire nu mai puteau trece, echipajul a trebuit sa descarce uneltele si sa incerce sa le transporte peste apa.",al={"de ce barca","cum s-au scufundat uneltele","de ce transport pe lac"}},{q="Cum s-a scufundat barca?",a="In timp ce traversa lacul, barca de transport a fost atacata de orcii Blackrock, care au lovit-o direct cu un proiectil de catapulta lansat din inaltimile din jur, scufundand pe loc barca si incarcatura sa.",al={"cine a distrus barca","cum a fost lovita"}},{q="Cine este Foreman Oslow?",a="Foreman Oslow este principalul constructor si supraveghetor al orasului Lakeshire. Raspunde de lucrarile publice si intretinerea civila a orasului, iar cea mai urgenta sarcina este reconstructia podului distrus.",al={"foreman oslow","rolul lui oslow"}},{q="Ce pericole se afla in Lake Everstill?",a="Lacul este populat de triburi ostile de murloci, care patruleaza pe langa tarmuri si ruine, precum si de fiorosii talhari carnivori de lac, care vaneaza in ape deschise si in adancuri.",al={"ce se afla in lac","monstrii din lac","pericolul din Lake Everstill"}},{q="De ce are Lakeshire atat de mare nevoie de aceste unelte?",a="Lakeshire este practic sub asediu, izolata de intariri imediate si de transporturile regulate. Fara unelte grele, Oslow nu poate reconstrui podul sau repara apararile necesare pentru a respinge orcii si gnollii atacatori.",al={"de ce sunt importante uneltele","unelte pentru repararea podului"}},{q="Unde duce misiunea mai departe?",a="Dupa ce-si recupereaza trusa de scule, Foreman Oslow ii tocmieste pe aventurieri sa adune materialele brute necesare repararii podului Great Bridge, in misiunea urmatoare, The Everstill Bridge.",al={"urmatoarea misiune","ce urmeaza dupa uneltele pierdute"}}},fx={fed346ea={q="La ce se foloseste Oslow's Toolbox?",a="Oslow's Toolbox contine uneltele grele de fier necesare pentru refacerea infrastructurii ruinate din Lakeshire. Cu orcs Blackrock asediind orasul si aruncand in aer marele pod, constructiile si reparatiile s-au oprit cu totul. Oslow nu poate repara podul sau intari apararea orasului fara echipamentul sau specializat, iar Lakeshire ramane vulnerabil si izolat pana cand trusa este recuperata de pe fundul lacului.",al={"cutia de unelte a lui oslow","la ce foloseste cutia de unelte","uneltele lui foreman oslow"}},b04d784a={q="De ce ii cere Foreman Oslow ajutorul unui aventurier in locul garzii orasului?",a="Lakeshire este impins la limita absoluta, aflandu-se sub asediu. Putinii garzi ai orasului si magistratii ramasi sunt tinuti pe loc in apararea perimetrului impotriva orcilor Blackrock, a gnollilor si a focului de catapulta. Oslow este constructor, nu luptator sau scufundator, iar Lake Everstill este plin de murloci agresivi si threshers monstruosi. Are nevoie de un calator capabil, dispus sa infrunte apele ostile in timp ce aparatorii din Lakeshire tin linia.",al={"de ce eu sa caut uneltele","de ce nu le ia oslow singur","de ce sa nu trimitem garzile din lakeshire"}}},fp="14,350,20.485.0,19.373.0,51.268.0,22.202.0,21.191.0,35.178.0,45.220.0,31.182.1"}
P.entries["quest:1250"] = {n="Diplomatul disparut"}
P.entries["quest:1251"] = {n="The Black Shield",s="Shady Rest Inn a ars pana la temelii, iar unul dintre putinele lucruri care au ramas in picioare este un cos de fum darapanat. Un scut innegrit de flacari este prins de caramizile lui. Trebuie sa i-l arati lui Krog din Brackenwall Village.",h="Shady Rest Inn a ars pana la temelii, iar unul dintre putinele lucruri care au ramas in picioare este un cos...",kw={"scut negru","scut de fier innegrit","brackenwall village","dustwallow marsh","krog","shady rest inn"},sec={{t="Un scut pe cos",b="Flacarile au mistuit Shady Rest Inn si a mai ramas putin din ea. Pe cosul de fum in ruina este prins un scut de fier innegrit de foc, care poate fi desprins din caramida. Trebuie dus la Krog, in Brackenwall Village, iar acesta te va intreba daca poate fi considerat o dovada din ramasitele hanului."},{t="Ce parere are Krog despre asta",b="Krog admite ca oamenii au gusturi ciudate in materie de decoratiuni, dar se indoieste ca cineva ar agata un scut simplu de fier deasupra caminului. Krog banuieste ca cine a incendiat hanul l-a lasat acolo, poate ca avertisment sau amenintare."}},faq={{q="Unde se gaseste scutul negru?",a="Este fixat de hornul cladirii arse a Shady Rest Inn, una dintre putinele ramasite ale constructiei.",al={"locatia black shield","unde se afla scutul","scutul de la Shady Rest Inn"}},{q="Cine primeste scutul?",a="Trebuie sa i-l duci lui Krog, la Brackenwall Village.",al={"cine vrea black shield","unde predau scutul","locatia lui krog"}},{q="Poate fi luat scutul din cos?",a="Da, se poate desprinde din caramizile cosului de fum.",al={"pot scoate scutul","scoate scutul de pe horn"}}},fp="16,209,23.289.0,21.211.1,32.97.0,20.56.0,41.53.0"}
P.entries["quest:1252"] = {n="Lieutenant Paval Reethe",s="Ceva straluceste sub daramaturi: o insigna purtand insemnul Theramore, o ancora aurie pe email alb, cu numele Lieutenant Paval Reethe gravat sub ancora. Captain Garran Vimes din Theramore este cel caruia trebuie sa i-o duci.",h="Ceva straluceste sub daramaturi: o insigna purtand insemnul Theramore, o ancora aurie pe email alb, cu numele...",kw={"Dustwallow Marsh","Garran Vimes","Paval Reethe","Shady Rest Inn","insigna garzii din Theramore"},sec={{t="O sclipire printre daramaturi",b="Ceva sclipeste sub daramaturi. Dupa ce indepartezi cenusa si molozul, descoperi o insigna cu emblema Theramore si numele Lieutenant Paval Reethe gravat dedesubt. Captain Garran Vimes din Theramore ar trebui s-o vada si te va intreba ce ai gasit in ruinele Shady Rest Inn."},{t="Raspunsul capitanului",b="Vimes spune ca primirea insignelor unui gardian nu e niciodata de bun augur. Unii gardieni cad in lupta, iar Vimes trebuie sa le duca vestea familiilor indoliate. Despre altii nu afla nimeni niciodata ce li s-a intamplat, iar uneori adevarul e si mai ingrozitor."}},faq={{q="Unde se gaseste insigna?",a="Zace sub daramaturi, acoperit de cenusa si resturi. Captain Garran Vimes te va intreba ce ai gasit in ruinele Shady Rest Inn.",al={"locatia insignei","unde gasesti insigna lui Reethe","insigna de la Shady Rest Inn"}},{q="Al cui nume apare pe insigna?",a="Numele gravat sub ancora este Lieutenant Paval Reethe.",al={"cine este paval reethe","numele de pe insigna","cine a pierdut insigna"}},{q="Cine primeste insigna?",a="Ar trebui sa o vada Captain Garran Vimes, din Theramore.",al={"cui trebuie sa-i dau insigna","unde predau insigna","locatia lui Captain Garran Vimes"}},{q="Cum arata insigna?",a="O ancora aurie pe email alb, insemnul lui Theramore.",al={"simbolul theramore","aspectul insignei garzii","cum arata insigna"}}},fp="23,231,21.283.0,19.235.1,25.129.0,27.64.0,19.57.0,30.64.0"}
P.entries["quest:1253"] = {n="The Black Shield",s="Un scut de fier, innegrit de foc, este prins de hornul darapanat al Shady Rest Inn, mistuit de flacari. Captain Garran Vimes din Theramore asteapta dovezi de la locul hanului.",h="Un scut de fier, innegrit de foc, este prins de hornul darapanat al Shady Rest Inn, mistuit de flacari.",kw={"scut negru","cos","dustwallow marsh","garran vimes","scut de fier","shady rest inn","theramore"},sec={{t="Un scut pe cos",b="Shady Rest Inn a ars, iar unul dintre putinele lucruri ramase in picioare este un cos de fum darapanat. Un scut de fier innegrit de foc este prins de caramida si poate fi desprins. Captain Garran Vimes, din Theramore, vrea dovezi de la locul hanului."},{t="Verdictul capitanului",b="Vimes spune ca nu este expert in fabricarea armelor si armurilor, ci doar in folosirea lor. In ochii capitanului, scutul pare cat se poate de obisnuit, in afara stricaciunilor lasate de foc."}},faq={{q="Unde se afla scutul negru?",a="Prins de caramida cosului de fum in ruina, printre putinele parti ale Shady Rest Inn mistuite de foc care mai sunt in picioare.",al={"unde se afla scutul","locatia black shield","gaseste black shield"}},{q="Cine vrea dovezi de la Shady Rest Inn?",a="Captain Garran Vimes din Theramore, care asteapta dovezi din ruinele hanului.",al={"cine vrea scutul","investigatorul de la shady rest","cine este garran vimes"}}},fp="16,176,23.234.0,21.178.1,34.109.0,43.86.0"}
P.entries["quest:1258"] = {n="... and Bugs",s="Morgan Stern din Theramore lucreaza la o reteta care ar putea deveni urmatoarea moda culinara din Stormwind. Cu limbile Mudrock deja procurate, urmatorul ingredient al preparatului sunt picioarele cu carapace ale unui crab urias, si doar cele impecabile, fara zgarieturi, sunt bune.",h="Morgan Stern din Theramore lucreaza la o reteta care ar putea deveni urmatoarea moda culinara din Stormwind.",kw={"picioare de crawler","dustwallow marsh","morgan stern","mudrock soup and bugs","picior de crawler impecabil","stormwind","theramore","swamp of sorrows"},sec={{t="Picioare fara nicio zgarietura",b="Morgan Stern vrea ca invelisul clestelui de crab sa fie o parte esentiala a aspectului preparatului, asa ca fiecare cleste trebuie sa fie intact si fara zgarieturi. Un crab adult poate avea doar unul sau doi astfel de clesti, iar cercetarea necesita foarte multi. Muckshells din Dustwallow Marsh nu sunt buni. Doar crabii din indepartatul Swamp of Sorrows vor fi potriviti, asa ca te asteapta o calatorie."}},faq={{q="Cine este Morgan Stern?",a="Morgan Stern lucreaza in Theramore la o reteta noua, care ar putea deveni urmatoarea manie culinara din Stormwind.",al={"cine este morgan stern","morgan stern theramore","cine da misiunile cu insecte"}},{q="De unde provin picioarele de crab?",a="Nu din Dustwallow Marsh, unde Muckshells nu sunt potriviti pentru felul de mancare. Morgan Stern indica Swamp of Sorrows, departe de aici, unde gasesti crabi buni.",al={"unde gasesc picioare de crawler","unde sunt spiny rock crawlerii","locatia picioarelor de crawler"}},{q="De ce trebuie ca picioarele de crab sa fie intacte?",a="Carapacea este esentiala pentru felul in care este prezentat felul de mancare, asa ca Morgan Stern vrea picioare fara cicatrice.",al={"de ce sunt necesare picioare de crawler fara cusur","de ce picioare fara cicatrici","prezentarea piciorului de crawler"}},{q="Ce misiune preceda aceasta?",a="Urmeaza dupa Mudrock Soup and Bugs, prima parte a muncii depuse pentru noua reteta a lui Morgan Stern.",al={"misiunea anterioara si insectele","conditie prealabila pentru mudrock soup and bugs"}}},fp="12,255,22.357.0,20.104.0,33.152.0,41.103.0,29.99.0"}
P.entries["quest:1259"] = {n="Lieutenant Paval Reethe",s="Captain Garran Vimes nu recunoaste numele Lieutenant Paval Reethe si te trimite la Adjutant Tesoran din Theramore, care se ocupa de registrele garzii din Theramore.",h="Captain Garran Vimes nu recunoaste numele Lieutenant Paval Reethe si te trimite la Adjutant Tesoran din...",kw={"Adjutant Tesoran","Captain Garran Vimes","Dustwallow Marsh","Paval Reethe","Theramore"},sec={{t="Cine este Reethe?",b="Captain Garran Vimes nu-si aminteste numele Lieutenant Paval Reethe. Adjutant Tesoran tine registrele garzii din Theramore, atat pentru oameni, cat si pentru echipament, iar Vimes se asteapta ca o cercetare a registrelor sa arate cine este Reethe."}},faq={{q="Cine te trimite sa afli despre Reethe?",a="Captain Garran Vimes, care nu recunoaste numele Lieutenant Paval Reethe.",al={"cine incepe Lieutenant Paval Reethe","cel care ofera misiunea Reethe","cine ofera misiunea Reethe"}},{q="Cine pastreaza registrele garzii din Theramore?",a="Adjutant Tesoran din Theramore le pastreaza, tinand evidenta oamenilor garzii si a echipamentului acesteia.",al={"unde este Adjutant Tesoran","pastratorul registrelor din Theramore","cine are registrele garzii"}},{q="Ce iti poate spune Adjutant Tesoran?",a="Vimes se asteapta ca volumele lui Tesoran sa arate cine este Reethe.",al={"ce stie tesoran","cartile lui tesoran"}}},fp="23,173,14.240.0,39.78.0,40.88.0,35.52.0"}
P.entries["quest:126"] = {n="Howling in the Hills",s="Howling in the Hills este o recompensa oferita de Alliance de catre Verner Osgood din Lakeshire, pentru vanarea lui Yowler, fiorosul alfa care-i conduce pe gnollii din Redridge. Cu armata din Stormwind prea ocupata de lupta impotriva orcilor Blackrock ca sa apere granitele locale, Lakeshire se bazeaza pe aventurierii aflati in trecere pentru a zdrobi conducerea haitei de gnolli.",h="Howling in the Hills este o recompensa oferita de Alliance de catre Verner Osgood din Lakeshire, pentru...",kw={"blackrock","gnolli","lakeshire","labuta","redridge","armata din stormwind","verner osgood","yowler"},ang={["class:Hunter"]="Urmarirea unui alfa dominant precum Yowler pana la barlogul sau din munti cere un ochi ager pentru semnele teritoriale si comportamentul haitei.",["class:Warrior"]="A-l infrunta pe Yowler inseamna sa te confrunti cu un adversar care isi stapaneste haita brutala doar prin dominatie fizica, cerand o confruntare directa de forta bruta.",["faction:Alliance"]="Faptul ca Lakeshire se bazeaza pe mercenari in loc de soldati regali dezvaluie presiunea administrativa uriasa care slabeste in prezent regatul Stormwind."},sec={{t="Vocea din inaltimi",b="Chiar si dupa ce a starpit gnollii mai slabi care jefuiau drumurile din jurul lui Lakeshire, chematurile lor amenintatoare continua sa rasune peste culmile din Redridge. Verner Osgood, potcovarul harnic din Lakeshire, intelege ca uciderea cercetasilor si a necrofagilor nu va opri niciodata valul atata vreme cat conducatorul haitei este in viata. Deasupra gloatei se ridica Yowler, un gnoll urias si neobisnuit de viclean, ale carui chematuri indruma haita peste dealuri. Verner le cere aventurierilor sa vaneze fiara si sa-i taie laba, pentru ca urletele sa amuteasca o data pentru totdeauna."},{t="Un oras abandonat de armata",b="Contractul scoate in evidenta realitatea sumbra de la granitele estice ale regatului Stormwind. Cu regele disparut, Varian Wrynn, si disputele privind regenta care paralizeaza conducerea suprema, soldatii regali se concentreaza aproape exclusiv asupra clanurilor de orci Blackrock inradacinate in nord. Asezarile obisnuite precum Lakeshire raman complet lipsite de aparare impotriva amenintarilor bastinase, precum gnollii, silindu-i pe localnici ca Verner Osgood sa puna singuri recompense, pentru a-si impiedica locuintele sa fie cotropite."}},faq={{q="Cine este Yowler?",a="Yowler este liderul feroce al gnollilor din Redridge, care dau tarcoale dealurilor din afara Lakeshire. Verner Osgood remarca faptul ca Yowler este mult mai puternic si mai periculos decat un corcitura obisnuita, fiind alfa care uneste haita si o indruma impotriva calatorilor si a gospodariilor locale.",al={"Yowler","cine este seful gnollilor","povestea lui Yowler","Yowler gnoll"}},{q="De ce ofera Verner Osgood aceasta recompensa in locul garzii orasului?",a="Conducerea oficiala din Lakeshire si militia locala sunt complet depasite de invazia orcilor Blackrock. Verner Osgood, un artizan local si maestru de grajduri a carui existenta depinde de siguranta drumurilor, se ofera adesea sa angajeze mercenari ratacitori pentru a elimina pericolele locale imediate.",al={"de ce Verner","de ce nu Magistrate Solomon","de ce angajeaza Osgood"}},{q="Unde sunt soldatii din Stormwind care ar trebui sa apere Lakeshire?",a="Fortele permanente ale Stormwind sunt angajate in alta parte. Prezenta armatei in Redridge este legata de supravegherea si tinerea in frau a orcs din Blackrock clan de mai sus, din munti, lasandu-i pe oraseni fara niciun sprijin impotriva animalelor salbatice din zona, a murlocilor si a gnollilor.",al={"unde este armata","de ce nu sunt garzi Stormwind","armata Stormwind in Lakeshire"}},{q="Ce se intampla cu gnolii din Redridge dupa ce moare Yowler?",a="Uciderea lui Yowler dezorganizeaza conducerea haitei gnoll si impiedica raidurile coordonate asupra granitelor orasului. Totusi, gnollii raman o pacoste persistenta prin tinuturile inalte si stancoase din Redridge.",al={"au plecat gnolii","ce se intampla dupa ce moare Yowler"}},{q="Ce misiuni preliminare duc la acest contract?",a="Lantul de misiuni incepe cand Verner Osgood te trimite sa faci treburi pentru a procura echipament pentru cai in 'The Price of Shoes' si 'Return to Verner'. Dupa ce te ocupi de solzii din subteran si raresti haita in 'A Baying of Gnolls', Verner iti incredinteaza vanatoarea directa a lui Yowler.",al={"cerinte preliminare pentru misiunea Yowler","deblocheaza Howling in the Hills","lantul misiunilor pentru Howling in the Hills"}},{q="De ce are nevoie Verner de laba lui Yowler drept dovada?",a="Recompensele pentru bestii periculoase necesita dovezi materiale incontestabile inainte de plata. Aducerea inapoi a labei taiate a lui Yowler le dovedeste lui Verner si locuitorilor nelinistiti din Lakeshire ca bestia terifianta, al carei ecou rasuna prin dealuri, a fost intr-adevar rapusa.",al={"de ce laba lui yowler","dovada cu laba lui yowler"}}},fx={f0418674={q="De ce vrea Verner Osgood ca Yowler sa fie ucis?",a="Verner aude cum gnollii urla in timp ce dau tarcoale crestelor de deasupra Lakeshire, zi si noapte. Cum armata Stormwind este cu totul ocupata sa lupte impotriva orcilor Blackrock, localnici precum Verner raman fara aparare in fata pradatorilor hoinari. El crede ca uciderea lui Yowler, ferocele conducator al haitei, va zdrobi moralul gnollilor si va imprastia fiarele inainte sa coboare asupra orasului.",al={"motivul lui Verner Osgood","de ce sa-l ucizi pe Yowler","motivul lui Verner pentru Howling in the Hills"}}},fp="20,327,24.551.0,28.490.0,14.268.0,67.294.0,68.259.0,56.213.0,50.271.0,43.255.0"}
P.entries["quest:1260"] = {n="Morgan Stern",s="Angus Stern de la Blue Recluse din Stormwind pregateste un nou meniu cu preparate rustice, de inspiratie mlastinoasa. Angus are un nepot, pe Morgan, pe care l-a trimis la Theramore sa adune retete de la localnici, si vrea sa afle ce a descoperit Morgan pana acum.",h="Angus Stern de la Blue Recluse din Stormwind pregateste un nou meniu cu preparate rustice, de inspiratie...",kw={"angus stern","mlastina","blue recluse","dustwallow marsh","morgan stern","stormwind","theramore"},sec={{t="Un meniu de mlastina",b="Angus Stern crede ca clientilor de la Blue Recluse le va placea un meniu cu preparate rustice in stil bayou. Pentru a-l alcatui, Angus si-a trimis nepotul, Morgan, la Theramore, un oras de langa Dustwallow Marsh, ca sa adune retetele localnicilor. Drumul este prea lung pentru ca Angus sa-l faca, asa ca are nevoie de un calator tanar ca tine, care sa mearga si sa vorbeasca cu Morgan."},{t="Ce are de spus Morgan",b="Cand il gasesti pe Morgan Stern in Theramore, afli ca cercetarea retetelor a scos la iveala cateva piste, dar e nevoie de ajutor pentru a le urmari. Ajutorul trebuie sa fie cineva dispus sa se ude la picioare."}},faq={{q="Cine este Morgan Stern?",a="Morgan Stern este nepotul lui Angus Stern de la Blue Recluse. Morgan a fost trimis la Theramore sa adune retete de la localnici.",al={"cine este morgan stern","povestea lui morgan stern","nepotul lui angus stern"}},{q="De ce vrea Angus Stern sa ajunga la Morgan?",a="Angus pregateste un meniu nou cu mancaruri rustice de inspiratie mlastinoasa pentru Blue Recluse si vrea sa afle ce a descoperit Morgan pana acum.",al={"de ce sa trimiti la Theramore","meniul Blue Recluse","misiunea lui angus stern"}},{q="Unde poate fi gasit Morgan Stern?",a="Morgan se afla in Theramore, orasul de langa Dustwallow Marsh.",al={"unde este Morgan Stern","locatia lui Morgan Stern","locatia bucatarului din Theramore"}}},fp="12,248,12.334.0,22.195.1,20.126.0,42.135.0,32.57.0"}
P.entries["quest:1261"] = {n="Marg Speaks"}
P.entries["quest:1262"] = {n="Report to Zor",s="Nazeer Bloodpike considera ciudat ca soldatii de rand purtau pandantivul cu bijuterii furat de Marg. Spunand ca e o podoaba nobiliara, Nazeer te trimite cu el in Orgrimmar, la Zor Lonetree, un bun cunoscator al politicii Alliance.",h="Nazeer Bloodpike considera ciudat ca soldatii de rand purtau pandantivul cu bijuterii furat de Marg.",kw={"Brackenwall Village","pandantiv cu bijuterii","Marg Speaks","Nazeer Bloodpike","Orgrimmar","Report to Zor","Stormwind","Zor Lonetree"},sec={{t="Un pandantiv de nobil",b="Nazeer Bloodpike gaseste ciudat ca niste soldati de rand sa aiba un pandantiv ca acesta. Proprietarul lui s-ar putea sa fi fost deghizat, sau soldatii l-ar fi putut fura chiar ei. Oricum ar fi, Nazeer crede ca pandantivul apartine unui nobil, iar ca misterul sa se dezlege trebuie gasit adevaratul proprietar. Zor Lonetree din Orgrimmar stie multe despre politica Alliance si poate spune daca pandantivul apartine nobilimii din Stormwind."},{t="Verdictul lui Zor",b="Zor Lonetree admira maiestria deosebita cu care a fost facut pandantivul. Orcs nu ar avea ce face cu o asemenea bijuterie, spune Zor, dar multi humans ar avea. Zor il va pune sa fie studiat si spera ca misterele lui sa fie dezvaluite in timp."}},faq={{q="De ce este dus pandantivul la Orgrimmar?",a="Nazeer Bloodpike considera ca este un pandantiv de nobil. Zor Lonetree din Orgrimmar stie multe despre politica Alliance si poate spune daca acesta are o istorie printre nobilii din Stormwind.",al={"de ce sa trimiti pandantivul la orgrimmar","de ce sa mergi la orgrimmar","de ce sa-l vezi pe zor lonetree"}},{q="Cine a avut anterior pandantivul cu bijuterii?",a="Marg a furat obiectul de la soldatii unei tabere Alliance de langa Theramore. Nazeer considera ciudat ca niste soldati de rand il aveau si se intreaba daca proprietarul era deghizat sau daca soldatii l-au furat.",al={"cine avea pandantivul","de unde provenea pandantivul"}},{q="Ce a precedat aceasta misiune?",a="Urmeaza dupa Marg Speaks, in care Marg a povestit ca a furat pandantiva de la soldatii aflati in tabara de langa Theramore.",al={"misiune anterioara","ce misiune vine inainte"}},{q="Unde este Zor Lonetree?",a="Zor Lonetree se afla in Orgrimmar.",al={"locatia lui zor lonetree","unde este zor lonetree"}}},fp="13,227,17.410.0,13.218.1,44.177.0,39.189.0,28.100.0,22.29.0"}
P.entries["quest:1264"] = {n="Diplomatul disparut"}
P.entries["quest:1265"] = {n="Diplomatul disparut",s="Elling te-a trimis sa-l gasesti pe soldatul Hendel, iar un ofiter local spune ca cautarea suna ingrijoratoare. Hendel era stationat la primul turn din afara Theramore, unde ti se cere sa cauti semne ale lui.",h="Elling te-a trimis sa-l gasesti pe soldatul Hendel, iar un ofiter local spune ca cautarea suna ingrijoratoare.",kw={"elling","Hendel","ofiter","privat Hendel","punct de santinela","theramore","turn"},sec={{t="La Turn",b="Ofiterul il cunoaste pe Hendel si spune ca era stationat la Sentry Point, primul turn din afara Theramore. Ofiterul isi face griji ca Elling te-a trimis primul acolo, deoarece afacerea ta poate fi tulburatoare si cere sa i se spuna ce poti impartasi. Ofiterul are datoria de a proteja terenurile, asa ca orice tulburare conteaza pentru paza locala."}},faq={{q="Cine este soldatul Hendel?",a="Soldatul Hendel este omul pe care Elling te-a trimis sa-l gasesti. Un ofiter local spune ca Hendel era stationat la primul turn din afara Theramore.",al={"parghie privata","parghie cine","povestirea de fundal a parghiei"}},{q="Unde ar trebui sa-l caut pe Hendel?",a="Cautati semne ale soldatului Hendel la Sentry Point, primul turn din afara Theramore.",al={"locatie Hendel","unde Hendel","punct de santinela Hendel"}},{q="Cine m-a trimis sa-l gasesc pe Hendel?",a="Elling te-a trimis sa-l gasesti pe soldatul Hendel.",al={"cine m-a trimis","elling Hendel","Hendel search"}},{q="De ce este ingrijorat ofiterul?",a="Ofiterul crede ca Elling nu te-ar fi trimis mai intai acolo decat daca afacerea ta era tulburatoare si vrea sa stie ce poti impartasi pentru a proteja pamanturile.",al={"de ce ingrijorat","ofiter ingrijorat","ce e tulburator"}}},fp="20,202,12.327.0,22.130.0,31.84.0,27.39.0,29.156.0"}
P.entries["quest:1268"] = {n="Suspicious Hoofprints",s="Urme de copite se intind departe de Shady Rest Inn, al carei cadru gol inca fumega. Cateva urme se vad limpede, in vreme ce altele aproape s-au pierdut in pamantul moale al mlastinii. Krog din Brackenwall Village este cel caruia trebuie sa i le raportezi.",h="Urme de copite se intind departe de Shady Rest Inn, al carei cadru gol inca fumega.",kw={"brackenwall village","centaur","dustwallow marsh","urme","kagoro","krog","quilboar","shady rest inn","suspicious hoofprints"},sec={{t="Urme in noroi",b="Shady Rest Inn nu mai e decat un schelet, inca fumegand, iar urme de copite se indeparteaza de el. Unele urme se vad usor, altele abia se deslusesc in pamantul moale. Krog, din Brackenwall Village, ar trebui sa afle despre ele."},{t="Raspunsul lui Krog",b="Krog admite ca quilboar ar fi putut s-o faca, sau chiar centaurii, fiindca ambele grupuri sunt numeroase in Barrens, iar fapta nu ar fi greu de crezut din partea lor. Krog adauga ca hanul nu a fost doar incendiat: proprietarul si-a pierdut si o femeie, precum si un catel, amandoi ucisi. Krog il va trimite pe Kagoro sa afle incotro duc urmele."}},faq={{q="Unde sunt urmele de copite?",a="Urmele duc departe de Shady Rest Inn, a carui structura goala inca fumega, peste pamantul moale al mlastinii.",al={"locatia urmelor de copite","unde sunt urmele","urme la Shady Rest Inn"}},{q="Cine ar trebui sa afle despre urmele copitelor?",a="Krog, din Brackenwall Village, este cel caruia trebuie sa i le raportezi.",al={"cui ii spun","locatia lui Krog","unde raportez urmele de copite"}},{q="Cate urme sunt?",a="Cateva se vad clar, iar randurile urmatoare sunt aproape imposibil de distins in noroi.",al={"cate urme de copita","cate urme"}}},fp="21,229,17.236.0,12.326.1,25.100.0,37.59.0,26.84.0"}
P.entries["quest:1269"] = {n="Lieutenant Paval Reethe",s="Sub daramaturi se afla o insigna cu insemnul Theramore, o ancora aurie pe email alb, cu numele Lieutenant Paval Reethe gravat sub ancora. Du insigna la Krog din Brackenwall Village.",h="Sub daramaturi se afla o insigna cu insemnul Theramore, o ancora aurie pe email alb, cu numele Lieutenant...",kw={"insigna","brackenwall","krog","ogron","paval","reethe","theramore"},sec={{t="O sclipire printre daramaturi",b="Ceva straluceste sub daramaturi. Dupa ce stergi cenusa si molozul, descoperi o insigna cu emblema lui Theramore si numele Lieutenant Paval Reethe gravat dedesubt. Krog din Brackenwall Village o asteapta si te va intreba daca ai vreun indiciu despre ce s-a intamplat la Shady Rest Inn."},{t="Ce stie Krog",b="Krog il cunoaste pe acest Human, Paval Reethe, si il considera jalnic. Potrivit lui Krog, Reethe si-a abandonat camarazii de arme si acum se ascunde prin padure. Krog l-a trimis pe Ogron sa-l gaseasca, fiindca altii il suspecteaza pe Reethe ca fura provizii. Krog crede ca l-au vazut pe Ogron indreptandu-se spre sud-est."}},faq={{q="Ce scrie pe insigna?",a="Insemnul lui Theramore: o ancora aurie pe email alb, cu numele Lieutenant Paval Reethe gravat dedesubt.",al={"ce scrie pe insigna","insemnele de pe insigna garzii din Theramore","cui ii apartine insigna"}},{q="Cine primeste insigna?",a="Krog, din Brackenwall Village, este cel care ar trebui sa-l vada.",al={"cui ii duc insigna","unde ajunge insigna lui reethe","predarea insignei"}},{q="Unde a fost gasita insigna?",a="Sub daramaturi, acoperit de cenusa si moloz. Krog intreaba daca ai aflat ceva despre ce s-a intamplat cu Shady Rest Inn.",al={"locatia insignei","unde a fost gasita insigna lui reethe"}}},fp="23,212,21.276.0,15.285.1,21.116.0,19.51.0,26.104.0"}
P.entries["quest:127"] = {n="Selling Fish",s="Dockmaster Baren administreaza cheiul aglomerat din Lakeshire, dar procurarea marfii proaspete pentru negot a devenit dificila. El le plateste calatorilor sa aduca pesti-soare patati, o delicatesa locala din Lake Everstill, tot mai greu de prins din cauza murlocilor care se apropie.",h="Dockmaster Baren administreaza cheiul aglomerat din Lakeshire, dar procurarea marfii proaspete pentru negot a...",kw={"Dockmaster Baren","Lake Everstill","Lakeshire","murloc","Redridge","Selling Fish","pestele soare patat"},ang={["faction:Alliance"]="Intrucat Kingdom of Stormwind ofera putin ajutor militar pentru Redridge, chiar si aprovizionarea locala cu hrana depinde de calatorii independenti ai Alliance care dau o mana de ajutor.",["profession:Cooking"]="Faima Lakeshire pentru delicatesele de apa dulce, precum pestele-soare patat, face din apele locale un punct de atractie de durata pentru bucatarii aspiranti."},sec={{t="Un element de baza din Lake Everstill",b="Lake Everstill este renumit in tinuturile din jur pentru pestii-soare patati, o captura delicata, mereu cautata de orasenii si negustorii aflati in trecere. Totusi, chiar daca apele lacului sunt bogate in peste, proviziile orasului se imputineaza adesea. Cu Lakeshire solicitat la maximum de diverse amenintari locale, pana si negotul de baza are nevoie de ajutorul aventurierilor independenti."},{t="Necazuri in ape mici",b="In mod normal, pescarii din zona nu ar avea nicio problema sa indeplineasca ordinele lui Dockmaster Baren. Insa triburile tot mai agresive de murloci din apele putin adanci si de pe maluri i-au alungat pe localnici de langa apa. Calatorii care vor sa indeplineasca cererea lui Baren trebuie fie sa-si arunce singuri unditele, pazindu-si spatele, fie sa ia captura direct de la murlocii care scormonesc prin tarmuri."}},faq={{q="Cine este Dockmaster Baren?",a="Dockmaster Baren supravegheaza docurile si traficul ambarcatiunilor de pe Lake Everstill, in Lakeshire. El gestioneaza comertul acvatic al orasului si se bazeaza pe calatori priceputi ca sa-l ajute sa procure peste proaspat si sa indeparteze amenintarile din preajma apei.",al={"baren","cine este maestrul docurilor","Dockmaster Baren"}},{q="De ce sunt atat de cautati pestii-soare patati?",a="Lake Everstill este renumit pentru pestii soare patati, o delicatesa indragita si un produs comercial important pentru Lakeshire. Rezervele lui Dockmaster Baren sunt pe sfarsite, deoarece pescarii obisnuiti din oras nu pot pescui in siguranta cat timp lacul este infestat cu dusmani.",al={"de ce sunfish","povestea despre spotted sunfish","de ce vrea Lakeshire peste"}},{q="Cum ajunge pestele-soare la murloci?",a="Triburile murloc de-a lungul Lake Everstill cauta in mod activ hrana si vaneaza in apele putin adanci. Cand ucid pescarii din zona sau ii alunga, strang pestii pentru propriile tabere, iar proviziile lor devin o prada usoara pentru aventurierii care prefera sa lupte in loc sa arunce undita.",al={"peste murloc","de ce lasa murlocii peste","murlocii fura peste"}},{q="Unde se pot gasi pestii-soare patati?",a="Pestii-soare patati traiesc in apele lacului Lake Everstill din Redridge Mountains. Pot fi pescuiti direct cu o undita sau jefuiti de la murlocii care salasluiesc pe malurile si in apele putin adanci ale lacului.",al={"unde se gasesc","locul pestilor din Lake Everstill","cum obtii un peste-soare patat"}},{q="Cum se leaga aceasta misiune de Murloc Poachers?",a="Dockmaster Baren ofera ambele sarcini in acelasi timp. Murlocii dau tarcoale lacului si ii jefuiesc resursele, asa ca alungarea braconierilor se imbina in mod firesc cu recuperarea pestilor-soare patati pe care i-au scos din apa.",al={"legatura dintre braconierii de murloci","alta misiune a lui Baren","misiunile maestrului de doc"}},{q="Este necesar sa pescuiesti pentru a-l ajuta pe Dockmaster Baren?",a="Nu, nu ai nevoie de echipament sau abilitate de pescuit. Desi pescuitul este o modalitate pasnica de a strange pesti-soare patati, Dockmaster Baren sugereaza fara ocolisuri sa-i iei cu forta de la triburile de murloci care vaneaza in lac.",al={"am nevoie de pescuit","pot face asta fara undita","pescuitul este necesar"}}},fx={["2b5f9eab"]={q="De ce are Dockmaster Baren nevoie de mai multi Spotted Sunfish?",a="Lake Everstill este renumit pentru pestii soare patati, care sustin comertul regulat si pofta de mancare ce-l tin ocupat pe Dockmaster Baren la docurile din Lakeshire. Cum stocul sau local a ajuns periculos de scazut, are nevoie de un lot proaspat de zece bucati pentru a satisface cererea si a-si mentine schimburile.",al={"de ce vrea baren peste","motivul lui Dockmaster Baren","de ce misiunea Selling Fish"}},d0647bad={q="La ce se foloseste Spotted Sunfish?",a="Spotted Sunfish sunt pesti de apa dulce originari din Lake Everstill, apreciati in tot Redridge pentru gustul lor. Sunt o sursa locala de hrana de baza si o marfa valoroasa pentru comertul din Lakeshire, cautati de calatori si localnici deopotriva.",al={"ce sunt pestii-soare patati","povestea pestilor-soare patati","la ce se folosesc pestii-soare patati"}}},fp="12,269,26.402.0,23.397.0,24.218.0,44.251.0,39.261.0,35.199.0,45.218.0,45.198.0"}
P.entries["quest:1270"] = {n="Stinky's Escape",s="\"Stinky\" Ignatz e inconjurat de creaturi de mlastina si nu a gasit bogbean-ul dupa care venise. Mebok Mizzyrix, un goblin din Ratchet, are nevoie de frunze de bogbean pentru a prepara o potiune, iar Ignatz iti cere sa-l scoti din incurcatura si sa-l pazesti cat timp cauta. Dupa aceea, Mebok Mizzyrix poate fi gasit in Ratchet.",h="\"Stinky\" Ignatz e inconjurat de creaturi de mlastina si nu a gasit bogbean-ul dupa care venise.",kw={"bogbean","dustwallow marsh","escortare","Mebok Mizzyrix","ratchet","Stinky Ignatz"},sec={{t="Inconjurati in mlastina",b="Ignatz rasufla usurat sa intalneasca pe cineva care nu vrea sa-l manance. Spune ca Mebok Mizzyrix, un goblin din Ratchet, are nevoie de frunze de bogbean pentru a prepara o potiune sau ceva de genul acesta. Ignatz sustine ca nu-l intereseaza motivul, fiindca plata era buna si cunoaste mlastina. A fost inconjurat inainte sa gaseasca planta si iti cere sa-l ajuti sa iasa din incurcatura si sa-l pazesti cat timp o cauta."},{t="Vesti de la Mebok",b="Mebok spune ca Ignatz a adus ierburile si a povestit cum l-ai scos din incurcatura. Un prieten al lui Stinky, declara Mebok, este un prieten al lui Mebok. Ignatz i-a cerut lui Mebok sa-ti dea ceva daca va intalniti vreodata, chiar inainte sa porneasca din nou spre sud, catre mlastina."}},faq={{q="Cine este \"Stinky\" Ignatz?",a="\"Stinky\" Ignatz cauta frunze de bogbean in mlastina pentru Mebok Mizzyrix. Spune ca stie locul, dar a fost inconjurat de fapturi inainte sa gaseasca planta.",al={"cine este stinky","stinky ignatz","cine este insotitorul"}},{q="De ce aduna Ignatz frunze de bobina de mlastina?",a="Goblinul Mebok Mizzyrix, din Ratchet, are nevoie de ele pentru o potiune. Ignatz spune ca nu-l intereseaza de ce, fiindca plata a fost buna.",al={"de ce bogbean","la ce foloseste bogbean","bogbean pentru mebok"}},{q="Cine este Mebok Mizzyrix?",a="Mebok Mizzyrix este un goblin din Ratchet care vrea frunze de bogbean pentru a prepara o potiune.",al={"mebok","cine este mebok mizzyrix","goblin din ratchet"}},{q="Cu cine ar trebui sa vorbesti dupa aceea?",a="Dupa ce-l insotesti pe Ignatz, gaseste-l pe Mebok Mizzyrix in Ratchet.",al={"unde merge stinky","unde predau Stinky's Escape"}}},fp="15,299,23.362.0,15.256.1,23.166.0,39.125.0,22.82.0,34.60.0"}
P.entries["quest:1271"] = {n="Feast at the Blue Recluse",s="Munca ta pentru Morgan Stern in Dustwallow Marsh se incheie cu ... and Bugs si te aduce inapoi la Angus Stern, la Blue Recluse.",h="Munca ta pentru Morgan Stern in Dustwallow Marsh se incheie cu ...",kw={"angus stern","dustwallow marsh","feast at the blue recluse","stern family","the blue recluse","morgan stern"},sec={{t="Inapoi la Blue Recluse",b="Angus Stern este unchiul lui Morgan Stern, pe care l-ai ajutat cu cercetarea unei retete in Dustwallow Marsh. Acum, drumul te duce inapoi la Angus, la Blue Recluse."},{t="Ce a auzit Angus",b="Angus a aflat de la nepotul sau ca l-ai ajutat cu cercetarile si ca ai scos un asociat de-al lui dintr-o incurcatura. Cei din familia Stern au grija de prietenii lor, iar o petrecere in cinstea ta sta sa inceapa."}},faq={{q="Cine este Angus Stern?",a="Angus Stern este unchiul lui Morgan Stern, care aduna retete in Theramore, si are legatura cu Blue Recluse.",al={"angus stern","gazda de la Blue Recluse","cine da ospatul"}},{q="Ce legatura are Angus Stern cu Morgan Stern?",a="Angus este unchiul lui Morgan. Angus l-a trimis pe Morgan la Theramore ca sa adune retete pentru noul meniu cu specific de mlastina de la Blue Recluse.",al={"relatia dintre angus si morgan","familia stern","angus este nepotul lui morgan"}},{q="Ce misiune preceda aceasta?",a="Urmeaza dupa ... and Bugs, ultima parte a muncii pe care ai facut-o pentru Morgan Stern in Theramore.",al={"misiune anterioara","ce vine inainte de feast"}}},fp="25,124,24.155.0,20.209.1,19.113.0,45.119.0,29.84.0"}
P.entries["quest:1273"] = {n="Questioning Reethe",s="Ogron, pe care Krog l-a trimis sa-l urmareasca pe Human-ul Reethe, l-a gasit in cele din urma, dupa o cautare indelungata, si spune ca s-a ascuns bine pentru un Human. Ogron se teme ca atata timp petrecut in mlastina l-ar fi putut innebuni pe Reethe si te roaga sa-l insotesti ca sa afle raspunsuri de la el. Apoi, drumul duce inapoi la Krog, in Brackenwall Village.",h="Ogron, pe care Krog l-a trimis sa-l urmareasca pe Human-ul Reethe, l-a gasit in cele din urma, dupa o cautare...",kw={"brackenwall","dustwallow","interogatoriu","krog","marsh","ogron","reethe"},sec={{t="Cautarea lui Ogron",b="Dupa o lunga cautare, Ogron l-a gasit pe Reethe, care, dupa socoteala lui Ogron, s-a ascuns bine pentru un human. Ogron se teme ca atatea zile petrecute in mlastina l-ar fi putut innebuni pe Reethe si vrea sa fii alaturi de el pentru a obtine raspunsuri. Apoi, Krog te asteapta la Brackenwall Village."},{t="Inapoi la Krog",b="Krog se bucura ca Reethe a plecat din mlastina si-i dispretuieste pe humans, spunand ca sunt prea firavi ca sa-si revina chiar si dupa o rana usoara de sageata. Krog concluzioneaza ca pista aceasta nu duce nicaieri si ca trebuie cautat in alta parte."}},faq={{q="Cine l-a gasit pe Reethe?",a="Ogron l-a gasit pe Reethe dupa o lunga cautare si vrea sa te alaturi lui pentru a obtine raspunsuri de la acesta.",al={"cine ofera Questioning Reethe","cine da misiunea Questioning Reethe","Ogron Reethe"}},{q="De ce vrea Ogron companie?",a="Ogron se teme ca Reethe ar fi innebunit dupa atata vreme petrecuta in mlastina.",al={"de ce sa-l ajuti pe ogron","e reethe nebun","de ce sa te confrunti cu reethe"}},{q="La cine raportezi apoi?",a="Krog, la Brackenwall Village.",al={"unde predau questioning reethe","cu cine vorbesc dupa reethe","predare reethe"}}},fp="18,310,14.266.0,14.230.1,17.84.0,28.71.0,31.29.0"}
P.entries["quest:1274"] = {n="The Missing Diplomat",s="O cerere discreta din Stormwind te conduce la Bishop DeLavey, in Stormwind Keep. Church si coroana au nevoie de ajutor intr-o chestiune prea periculoasa pentru canalele publice.",h="O cerere discreta din Stormwind te conduce la Bishop DeLavey, in Stormwind Keep.",kw={"Bishop DeLavey","diplomat","investigatie","Stormwind Keep","The Missing Diplomat","Thomas"},ang={["faction:Alliance"]="Gasirea diplomatului disparut este importanta pentru integritatea si apararea Alliance. Ancheta poate scoate la iveala amenintari din insasi curtea Stormwindului.",["race:Human"]="Ca Human din Stormwind, te confrunti cu o problema care tine de stabilitatea patriei tale, intr-o perioada fragila de regenta."},sec={{t="O chemare tacuta",b="In timp ce strabati Stormwind, Thomas, un baiat de altar, se apropie cu o rugaminte rostita in soapta. Bishop DeLavey, un cleric respectat al Church of the Holy Light, are nevoie de ajutorul unui strain la Stormwind Keep. El spune ca problema este delicata si urgenta. Trebuie sa pastrezi discretia, ca sa nu se panicheze oamenii."},{t="Soapte in fortareata",b="La Stormwind Keep, Bishop DeLavey iti spune de ce trebuie pastrata taina: un demnitar de rang inalt al regatului a disparut in circumstante misterioase. Se pregatesc tulburari interne, iar regele Varian Wrynn este disparut. Orice semn de tradare in randurile cele mai inalte ale regatului ar putea ameninta pacea sa fragila."}},faq={{q="Cine este Thomas?",a="Thomas este baiat de altar la Cathedral of Light si face comisioane pentru Bishop DeLavey. El cauta pe strazile din Stormwind aventurieri capabili si ii indruma spre fortareata cand treburile Bisericii sau ale statului cer ajutor discret.",al={"cine este Thomas","Thomas din Stormwind","cel care ofera misiunea Thomas"}},{q="Cine este Bishop DeLavey?",a="Bishop DeLavey este un cleric cu rang inalt al Church of the Holy Light din Stormwind Keep. Colaboreaza cu curtea regala in chestiuni discrete de securitate si anchete delicate pe care garzile orasului nu le pot investiga deschis.",al={"cine este bishop delavey","delavey","bishop delavey"}},{q="De ce este aceasta chestiune tratata in secret?",a="Stormwindul este deja nelinistit: regele Varian Wrynn a disparut, iar Defias Brotherhood pune la cale o rebeliune in tot Westfallul. Vestea disparitiei unui alt diplomat sau demnitar cunoscut ar putea raspandi panica ori dezvalui slabiciunile curtii.",al={"de ce discret","de ce secretomanie","de ce secret"}},{q="Unde duce aceasta investigatie?",a="Cercetarea incepe cu Bishop DeLavey in Stormwind Keep. Ea continua prin Stormwind si teritoriile Human din jur, apoi ajunge in tinuturi periculoase de peste mare.",al={"unde merge diplomatul disparut","urmatoarea locatie a diplomatului disparut"}},{q="Cine este diplomatul disparut?",a="Bishop DeLavey pastreaza secretul identitatii diplomatului la inceputul anchetei. Dezvaluirea acesteia ar putea periclita investigatia si pune in primejdie oficialul disparut si regatul.",al={"cine este diplomatul","identitatea diplomatului disparut"}}},fx={["46e2b0bf"]={q="De ce vrea Thomas sa-l vezi pe Bishop DeLavey?",a="Young Thomas actioneaza la ordinul direct al Bishop DeLavey. DeLavey l-a insarcinat sa cerceteze discret prin Stormwind in cautarea unor aventurieri capabili sa se ocupe de o chestiune delicata si stringenta pentru regat. Thomas nu are niciun interes personal, in afara de a-l sluji cu sarguinta pe episcop si de a se asigura ca ajungi la fortareata fara sa dai alarma.",al={"de ce te trimite Thomas","motivul lui Thomas in cazul diplomatului disparut","de ce sa-l vezi pe Bishop DeLavey"}},["227c4a3f"]={q="De ce recruteaza Bishop DeLavey aventurieri in locul garzii orasului?",a="Misiunea priveste o chestiune de maxima importanta, care trebuie sa ramana strict confidentiala. Mobilizarea garzii orasului Stormwind sau atragerea atentiei oficiale a armatei risca sa raspandeasca informatii sensibile prin tot orasul. Cerandu-i lui Thomas sa abordeze discret aventurieri independenti precum tine, episcopul isi poate continua cercetarile in liniste, fara sa alerteze potentialii dusmani sau sa nelinisteasca publicul.",al={"de ce nu garda orasului","de ce recruteaza aventurieri Missing Diplomat","de ce are nevoie de tine Bishop DeLavey"}}},fp="20,154,15.290.0,20.306.1,14.221.0,22.207.0,37.236.0,35.165.0,28.177.0"}
P.entries["quest:1275"] = {n="Researching the Corruption",s="Gershala Nightwhisper din Auberdine cauta trunchiuri cerebrale corupte de la creaturile care infesteaza Blackfathom Deeps. Tulburat de zvonurile ca blood elves practica magia demonica de dincolo de mare, spera sa studieze degradarea fiziologica a nagalor si satirilor, pentru a prevedea - si poate impiedica - o alta mutatie elfica catastrofala.",h="Gershala Nightwhisper din Auberdine cauta trunchiuri cerebrale corupte de la creaturile care infesteaza...",kw={"ashenvale","auberdine","blackfathom deeps","blood elves","tulpina cerebrala corupta","corruption abroad","gershala nightwhisper","naga","satyr"},ang={["class:Druid"]="Druizii simt o aversiune innascuta fata de satiri, a caror coruptie fel pangareste visul natural si deformeaza insusi pamantul.",["class:Mage"]="Ancheta sumbra a lui Gershala este o amintire brutala a costurilor fizice si spirituale ale dependentei nechibzuite si necontrolate de magie.",["faction:Alliance"]="Alliance urmareste cu prudenta rapoartele despre alunecarea blood elf in artele intunecate de peste mare, temandu-se de aparitia unei noi amenintari demonice.",["race:NightElf"]="Pentru night elves, aceasta cercetare atinge cea mai dureroasa rana a istoriei lor: degradarea catastrofala a rudelor lor, transformate in satiri si naga care napastuiesc Kalimdor."},sec={{t="Un avertisment din istorie",b="Pentru elfii noptii din Kalimdor, pieirea rudelor lor stravechi este o amintire vie, intiparita in monstri. Cu zece mii de ani in urma, Highborne au cedat atractiei energiilor demonice, transformandu-se in satiri cu coarne sau scufundandu-se in adancuri ca naga serpentine. Faptul ca elfii sangerii isi schimba numele si imbratiseaza magia neagra nu i se pare lui Gershala Nightwhisper o curiozitate indepartata, ci o istorie condamnata sa se repete."},{t="In adancuri",b="Blackfathom Deeps este locul ideal pentru cercetarile lugubre ale lui Gershala. Ascunse sub Zoram Strand, in Ashenvale, ruinele templului subteran sunt pline de adepti satiri ai cultului si naga incolaciti. Trimitand un aventurier sa recolteze trunchiuri cerebrale de la ambele monstruozitati, el spera sa disece legatura biologica dintre dependenta de magia arcana, coruptia demonica si transformarile catastrofale ale trupului."},{t="Un leac disperat",b="Desi metodele lui Gershala sunt inspaimantator de anatomice, intentia declarata este una preventiva. El crede ca descifrarea mutatiilor fiziologice exacte pe care le au in comun satirii si naga ar putea oferi cunostintele necesare pentru a-i salva pe elfii sangelui de la damnarea deplina. Ramane o intrebare deschisa daca vreo cercetare desfasurata in darkshore poate intr-adevar sa-i influenteze pe elfii disperati din Quel'Thalas."}},faq={{q="De ce ii pasa lui Gershala Nightwhisper de elfii sangelui?",a="Gershala se teme ca apropierea elfilor de sange de puterile demonice va da nastere unei alte rase de monstri schimonositi, care sa ameninte Azeroth, asa cum trufia elfilor din trecut a dat nastere satirilor si nagelor.",al={"de ce sa-i ajute pe elfii de sange","legatura dintre Gershala si elfi de sange","elfii de sange din Auberdine"}},{q="Unde aduni tulpinile cerebrale corupte?",a="Acestea sunt adunate de la satirii si naga care locuiesc in Blackfathom Deeps, un complex antic de temple ingropat de-a lungul Zoram Strand, pe coasta de nord-vest a Ashenvale.",al={"unde se gasesc tulpinile cerebrale","locatia tulpinii cerebrale","prada tulpina cerebrala corupta"}},{q="De ce isi doreste in mod special mostre de la satiri si naga?",a="Atat satirii, cat si naga s-au ivit din elfi transformati de forte nefiresti - satirii prin intelegeri cu demonii, iar naga in urma Separarii. Gershala vrea sa le compare mutatiile cerebrale pentru a intelege cum se degradeaza fiziologia elfilor sub influenta puterii intunecate.",al={"de ce satyri si naga","legatura dintre satyri si naga"}},{q="Cine te indruma spre aceasta sarcina?",a="Poti fi indrumat catre Gershala Nightwhisper din Auberdine printr-o misiune introductiva care serveste drept indiciu, 'The Corruption Abroad', desi el iti va oferi si direct aceasta investigatie.",al={"misiune premergatoare","legatura cu Corruption Abroad"}},{q="Ce planuieste Gershala sa faca cu specimenele?",a="El intentioneaza sa studieze corelatiile fiziologice dintre cele doua forme de coruptie, in speranta ca rezultatele ar putea impiedica alunecarea elfilor sangelui spre o monstruozitate si mai cumplita.",al={"studiul trunchiului cerebral","scopul cercetarii lui gershala"}},{q="Este Auberdine amenintata direct de Blackfathom Deeps?",a="Desi Blackfathom Deeps se afla chiar dincolo de granita sudica, in Ashenvale, Night Elves din Auberdine supravegheaza intreaga regiune de coasta, cautand semne ale raspandirii coruptiei demonice si Twilight.",al={"de ce ii pasa lui Auberdine","amenintarea Blackfathom Deeps din Darkshore"}}},fx={["57dc4e51"]={q="Impotriva cui esti trimis in Blackfathom Deeps?",a="Gershala te trimite impotriva satirilor si naga care locuiesc in Blackfathom Deeps, pe coasta din Ashenvale. Ambele specii au fost candva Night Elves, inainte de a suferi transformari magice hidoase: satirii au fost deformati de coruptia demonica in timpul War of the Ancients, iar naga au fost mutati de vechi puteri intunecate sub mare. Acum, ambele factiuni locuiesc in ruinele templului scufundat.",al={"ce inamici trebuie infruntati pentru Researching the Corruption","cu cine ma lupt in Blackfathom Deeps","tinte pentru Researching the Corruption"}}},fp="26,328,22.436.0,14.404.0,16.379.1,58.190.0,46.171.0,53.260.0,27.175.0,49.187.0,54.194.0"}
P.entries["quest:1276"] = {n="The Black Shield",s="Krog isi aminteste acum de unde vine numele Mosarn: de la un fierar foarte apreciat din Thunder Bluff, a carui armura i-a fost daruita candva lui Krog de Earthen Ring. Krog spera ca Mosarn ii va putea spune mai multe despre scutul de fier innegrit, fiindca Reethe nu i-a oferit nicio informatie folositoare. Mosarn poate fi gasit in Thunder Bluff.",h="Krog isi aminteste acum de unde vine numele Mosarn: de la un fierar foarte apreciat din Thunder Bluff, a...",kw={"scut de fier innegrit","fierar","dustwallow","cercul pamantului","krog","mosarn","reethe","thunder bluff"},sec={{t="Numele unui fierar",b="Krog isi aminteste unde a mai auzit numele Mosarn: este vorba de un fierar foarte respectat din Thunder Bluff. Candva, Earthen Ring i-a multumit lui Krog oferindu-i o armura facuta de Mosarn, iar Krog o lauda. Spune ca Mosarn a faurit si scutul si poate sa-i dea mai multe informatii. Krog recunoaste ca indiciul e firav, dar Reethe n-a oferit nimic folositor, asa ca asta e tot ce are. Scutul de fier innegrit trebuie dus la Mosarn, care se afla in Thunder Bluff."},{t="Cuvantul lui Mosarn",b="Mosarn este de acord ca scutul este o piesa faurita de el, dar nu poate spune mare lucru in plus. A facut atat de multe scuturi si seturi de armura, incat nu si le poate aminti pe toate."}},faq={{q="Cine este Mosarn?",a="Mosarn este un fierar foarte apreciat in Thunder Bluff, care a faurit un set de armura pe care Earthen Ring i l-a daruit lui Krog.",al={"cine este mosarn","unde este mosarn","mosarn thunder bluff"}},{q="De ce sa duci scutul la Mosarn?",a="Krog spune ca Mosarn a facut scutul si ar putea sa-ti dea mai multe detalii. Krog numeste aceasta pista slaba, dar, cum nu s-a aflat nimic util de la Reethe, este singura pe care o au.",al={"de ce sa-i arat scutul lui mosarn","indiciul scutului innegrit","ce stie mosarn"}},{q="De unde il cunoaste Krog pe Mosarn?",a="Earthen Ring i-a dat lui Krog un set de armura confectionat de Mosarn, drept multumire.",al={"legatura dintre krog si mosarn","de unde il cunoaste krog pe fierar"}}},fp="16,300,14.436.0,13.161.1,14.112.0,30.163.0,26.71.0"}
P.entries["quest:128"] = {n="Blackrock Bounty",s="Blackrock Bounty este un contract de aparare emis de Guard Howe in Lakeshire, in numele lui Magistrate Solomon. Cum Stormwind nu trimite intariri, orasul plateste aventurieri independenti sa starpeasca Blackrock Champions de elita, care se strang in muntii nordici. Uciderea acestor comandanti de unitati de lupta urmareste sa perturbe atacul coordonat al clanului de orci asupra Redridge.",h="Blackrock Bounty este un contract de aparare emis de Guard Howe in Lakeshire, in numele lui Magistrate...",kw={"blackrock","bounty","burning steppes","campion","guard howe","lakeshire","magistrate solomon","redridge","stormwind"},ang={["class:Warrior"]="Blackrock Champions sunt batausi veterani, incercati si puternic blindati, care pun la incercare disciplina si rezistenta unui razboinic in lupta corp la corp.",["faction:Alliance"]="Lakeshire este scutul estic al Stormwindului; daca orcii Blackrock strapung aceste tabere montane, tinuturile agricole centrale ale Alliance vor fi direct expuse invaziei.",["race:Human"]="Blackrock clan a distrus vechiul Kingdom of Stormwind in First War. Pentru aparatorii umani, oprirea intoarcerii lor spre sud este o necesitate amara, ancestrala."},sec={{t="Mentinerea liniei suveranului",b="Redridge se afla de multa vreme sub conducerea suverana a Kingdom of Stormwind, dar Blackrock clan nu respecta granitele oamenilor. Venind in valuri prin trecatorile montane care duc din Burning Steppes, orcii au intemeiat tabere puternic fortificate in toata partea de nord a Redridge. In lipsa regelui Varian Wrynn si cu regenta din Stormwind retinand soldatii regali, conducatori locali precum Magistrate Solomon au fost nevoiti sa ofere recompense din vistieria tot mai saracita a orasului pentru a proteja Lakeshire."},{t="Tintirea campionilor",b="Guard Howe ii considera pe Blackrock Champions coloana vertebrala a avangardei invadatoare. In calitate de conducatori de echipa si veterani incercati in lupta din cadrul bandelor lor de razboi, acesti campioni coordoneaza miscarile trupelor si imping inainte fortele inferioare de grunt. Punand pret pe capetele lor, aparatorii din Lakeshire spera sa distruga conducerea tactica a clanului si sa opreasca o ofensiva de amploare spre sud, inainte ca perimetrul exterior al localitatii sa se prabuseasca."}},faq={{q="De ce ofera Guard Howe recompense in loc sa trimita garda orasului?",a="Garnizoana locala din Lakeshire este suprasolicitata pana la limita. Intre patrularea zonei Lake Everstill, paza podurilor si respingerea gnollilor si a jefuitorilor orci, garzile nu pot detasa o forta suficient de numeroasa pentru a ataca direct taberele de razboi fortificate ale orcilor fara a lasa orasul fara aparare.",al={"de ce sunt oferite recompense","unde este garda orasului","recompensa lui guard howe"}},{q="Unde se afla Blackrock Champions?",a="Sunt stationati in intinsele tabere Blackrock din nordul Redridge Mountains, chiar la vest de drumul principal care urca spre Burning Steppes.",al={"unde sunt campionii","locatia campionului","tabara campionilor din Blackrock"}},{q="De ce invadeaza orcii Blackrock Redridge?",a="Aflata in nord, in Blackrock Mountain, Blackrock clan considera dealurile din imprejurimi un teritoriu strategic de cucerit si pradat. Cu apararea Stormwind slabita si rasfirata, cauta sa alunge asezarile umane si sa stapaneasca trecatorile montane.",al={"de ce Blackrock in Redridge","de ce ataca orcii Lakeshire","invazia Blackrock"}},{q="De ce nu trimite Stormwind soldati regali sa-i alunge?",a="Regele Varian Wrynn a disparut, iar curtea regala, sub conducerea regentului Bolvar Fordragon si a Lady Prestor, sustine ca armatele regatului nu pot fi trimise in ajutor. Lakeshire a cerut in repetate randuri sprijin capitalei, dar a fost refuzata si lasata sa angajeze mercenari aflati in trecere.",al={"de ce nu exista armata Stormwind","unde este ajutorul Stormwind","intaririle Magistrate Solomon"}},{q="Ce rol au campionii in cadrul Blackrock clan?",a="Campionii actioneaza ca lideri tactici de prima linie. Fiecare echipa de lupta Blackrock se bazeaza pe un campion care sa-i coordoneze atacurile, sa impuna o disciplina brutala si sa conduca asalturile in teritoriul Alliance.",al={"ce sunt campionii blackrock","rangul de campion","unitatea de conducere blackrock"}},{q="Cine a autorizat acest contract pentru recompensa?",a="Magistrate Solomon, conducatorul civic al Lakeshire, a autorizat recompensa si i-a incredintat lui Guard Howe recrutarea unor luptatori capabili sa duca la bun sfarsit starpirea.",al={"cine plateste recompensa","cine vrea morti campionii","recompensa lui magistrate solomon"}}},fx={ae8dcd14={q="De ce vrea Guard Howe ca Blackrock Champions sa fie ucisi?",a="Blackrock clan a invadat pe fata teritoriul suveran al Stormwindului, amenintand Lakeshire si tinuturile Redridge Mountains din jur. Guard Howe actioneaza la ordinele directe ale Magistrate Solomon pentru a apara oraselul. Tintind campionii - comandantii incercati in lupta care conduc tabara - orasul incearca sa destrame lantul de comanda al invadatorilor, inainte ca un asalt total sa copleseasca apararea firava a tinutului Redridge.",al={"de ce sa ucidem campionii blackrock","motivul lui guard howe","de ce vrea howe sa-i omoare"}}},fp="16,386,26.506.0,23.435.0,70.285.0,42.157.0,45.266.0,60.261.0,55.181.0,36.153.0"}
P.entries["quest:1282"] = {n="They Call Him Smiling Jim",s="Guard Byron il compatimeste pe un barbat pe nume Smiling Jim si lasa sa se inteleaga ca nu a fost intotdeauna asa cum este acum. Byron prefera sa nu vorbeasca despre asta si te trimite la Captain Garran Vimes din Theramore.",h="Guard Byron il compatimeste pe un barbat pe nume Smiling Jim si lasa sa se inteleaga ca nu a fost intotdeauna...",kw={"captain garran vimes","dustwallow marsh","guard byron","james hyal","shady rest inn","smiling jim","theramore"},sec={{t="O poveste trista",b="Byron il compatimeste pe Jim si spune ca lucrurile nu au fost mereu asa pentru el: Jim a tinut candva un han in mlastina, unul minunat. Byron prefera sa nu intre in detalii. Oricine doreste cu adevarat sa afle povestea este trimis sa-l intrebe pe Captain Garran Vimes din Theramore."},{t="Relatarea lui Vimes",b="Vimes ii spune pe nume: James Hyal. Hyal a deschis un han la marginea lui Barrens, gandindu-l ca popas placut pentru calatori, iar o vreme afacerea a mers bine. Apoi Theramore si-a pierdut controlul asupra drumurilor din mlastina, iar ogrii au pus stapanire pe zona. Incapatanat cum era, Hyal n-a vrut sa renunte la visul sau pentru siguranta oferita de zidurile Theramore, iar focul a mistuit Shady Rest Inn. Vimes spune ca investigatia a avut prea putin succes pana acum si sugereaza sa cercetezi ruinele, in cautarea cuiva care sa vrea sa ajute."}},faq={{q="Cine este Smiling Jim?",a="Guard Byron ii compatimeste si spune ca nu a fost mereu asa. Byron isi aminteste ca Jim avea candva un han in mlastina, si unul minunat.",al={"cine este Jim","identitatea lui Smiling Jim","cine este barbatul zambitor"}},{q="De ce te trimite Guard Byron la Captain Vimes?",a="Byron ar prefera sa nu vorbeasca despre trecutul lui Jim si te indruma spre capitanul Garran Vimes.",al={"de ce sa vorbesti cu Vimes","misiunea lui Byron","motivul garzii Byron"}},{q="Unde il gasesc pe Captain Garran Vimes?",a="Captain Garran Vimes se afla in Theramore.",al={"cine este captain vimes","captain vimes dustwallow"}}},fp="25,194,11.246.0,15.479.1,19.146.0,47.90.0,37.37.0"}
P.entries["quest:1284"] = {n="Suspicious Hoofprints",s="Urmele de copite se indeparteaza de ramasitele fumegande ale Shady Rest Inn. Unele se vad usor, in timp ce altele aproape ca s-au pierdut in noroiul moale al mlastinii. Trebuie sa le raportezi lui Captain Garran Vimes din Theramore.",h="Urmele de copite se indeparteaza de ramasitele fumegande ale Shady Rest Inn.",kw={"barrens","captain garran vimes","centaur","dustwallow marsh","falgran hastil","urme de copite","shady rest inn","theramore"},sec={{t="Urme in noroi",b="Siruri de urme pornesc de la Shady Rest Inn, ale carei ruine inca fumega. Cateva dintre ele se vad limpede, in timp ce sirurile mai indepartate sunt aproape invizibile in noroiul moale al mlastinii. Capitanul Garran Vimes, din Theramore, ar trebui sa afle despre ele."},{t="Ce parere are Vimes despre asta",b="Vimes remarca faptul ca se inregistreaza multa activitate a centaurilor pe meleagurile de langa Dustwallow Marsh. Scurte incursiuni in Barrens au scos la iveala taberele si asezarile lor raspandite prin zona. Vimes il va trimite pe Falgran Hastil, unul dintre cercetasi, sa afle incotro duc urmele."}},faq={{q="Unde se gasesc urmele de copite?",a="Urmele lor se indeparteaza de Shady Rest Inn, care inca fumega, traversand noroiul moale al mlastinii.",al={"unde sunt urmele","locatia urmelor de copita","urme la Shady Rest Inn"}},{q="Cine primeste raportul despre urme?",a="Capitanul Garran Vimes, in Theramore.",al={"cui ii spun despre urmele copitelor","cine primeste raportul despre urmele copitelor","garran vimes urme de copite"}},{q="Cat de usor pot fi urmarite urmele?",a="Cateva sunt clare, dar mult mai multe randuri sunt aproape invizibile in noroi.",al={"sunt urmele greu de vazut","urme slabe in mlastina"}}},fp="21,208,17.246.0,22.272.1,31.91.0,41.35.0,34.68.0"}
P.entries["quest:1285"] = {n="Daelin's Men",s="Adjutant Tesoran l-a gasit pe Lieutenant Paval Reethe in registrele garzii. Acestea consemneaza inrolarea sa in marina militara din Kul Tiras la varsta de saisprezece ani, serviciul remarcabil si avansarile in grad, precum si incadrarea in garda din Theramore, printre recruti care au traversat marea alaturi de Lady Proudmoore. Ultima inregistrare il declara pe Reethe disparut, iar Captain Garran Vimes trebuie instiintat.",h="Adjutant Tesoran l-a gasit pe Lieutenant Paval Reethe in registrele garzii.",kw={"adjutant tesoran","daelin's men","dezertori","dustwallow marsh","garran vimes","kul tiras","paval reethe","theramore"},sec={{t="Ce spun registrele",b="Captain Garran Vimes te-a trimis la Adjutant Tesoran, care a cercetat registrele si l-a gasit pe Lieutenant Paval Reethe. Reethe s-a inrolat in marina Kul Tiras la varsta de saisprezece ani, iar serviciul remarcabil i-a adus promovari. Mai tarziu, Reethe s-a alaturat garzii din Theramore, la fel ca majoritatea recrutilor care au traversat marea alaturi de Lady Proudmoore. In registru, Reethe apare in cele din urma ca disparut. Vestea trebuie dusa la Vimes, in Theramore."},{t="Reactia capitanului",b="Vimes ia \"disparut\" drept cuvantul bland pe care Tesoran il foloseste pentru tradator. Vimes e convins ca Reethe este unul dintre prostii a caror loialitate fata de Admiral Daelin e atat de oarba, incat ii face sa tradeze, si vede o ironie amara in asta, fiindca dezertorii o acuza pe Theramore ca a tradat Alliance."}},faq={{q="Cine este Adjutant Tesoran?",a="Adjutant Tesoran a cautat informatii despre Lieutenant Paval Reethe in registrele garzii si a citit cu voce tare ce scrie acolo.",al={"tesoran","cine ii da oamenii lui daelin"}},{q="Ce spun documentele despre Paval Reethe?",a="Reethe s-a inrolat in infanteria marina Kul Tiras la saisprezece ani, a fost avansat datorita serviciului sau remarcabil, iar mai tarziu s-a alaturat garzii din Theramore, printre recruti care au traversat marea impreuna cu Lady Proudmoore. Registrul se incheie mentionandu-l pe Reethe ca disparut.",al={"povestea lui reethe","dosarul lui reethe","istoria lui paval reethe"}},{q="Cine primeste vestea despre Reethe?",a="Capitanul Garran Vimes, in Theramore.",al={"de ce sa te intorci la vimes","garran vimes reethe"}}},fp="12,352,20.404.0,22.272.1,24.116.0,43.244.0,31.35.0"}
P.entries["quest:1286"] = {n="The Deserters",s="Capitanul Garran Vimes spune ca dezertorii s-au stabilit intr-un turn pe care Theramore il abandonase. Turnul se afla la Lost Point, la sud-est de han. Un barbat pe nume Jacken ii conduce pe dezertori, iar Vimes vrea sa afle de la el informatii despre Reethe.",h="Capitanul Garran Vimes spune ca dezertorii s-au stabilit intr-un turn pe care Theramore il abandonase.",kw={"balos jacken","capitanul garran vimes","dezertori","dustwallow marsh","lost point","reethe","turn de veghe"},sec={{t="Un turn cucerit",b="Vimes recunoaste ca a fost greu sa reziste in mlastina, desi hotararea oamenilor sai a mentinut in picioare mai multe turnuri de straja defensive. Rapoartele cercetasilor spun ca dezertorii s-au instalat intr-un turn abandonat din Lost Point, la sud-est de han. Un barbat pe nume Jacken ii conduce. Vimes iti cere sa afli ce informatii va da Jacken despre Reethe si te avertizeaza ca s-ar putea sa nu le ofere usor."}},faq={{q="Cine te trimite sa te ocupi de dezertori?",a="Captain Garran Vimes, ale carui rapoarte de cercetare spun ca dezertorii s-au stabilit intr-unul dintre turnurile abandonate de Theramore.",al={"cine incepe misiunea The Deserters","cine ofera misiunea The Deserters"}},{q="Unde se ascund dezertorii?",a="La Lost Point, la sud-est de han, intr-un turn parasit din Dustwallow Marsh.",al={"locatia dezertorilor","unde se afla Lost Point"}},{q="Cine ii conduce pe dezertorii de la Lost Point?",a="Un barbat pe nume Jacken, sau Balos Jacken, ii conduce. Vimes avertizeaza ca Jacken s-ar putea sa nu ofere usor informatii.",al={"cine este Balos Jacken","liderul dezertorilor"}},{q="Ce vrea Captain Vimes de la Balos Jacken?",a="Informatii despre Reethe, de la Jacken si dezertori.",al={"de ce sa-l gasesti pe jacken","ce vrea vimes"}}},fp="13,248,13.415.0,41.115.0,31.90.0,38.109.0,47.56.0"}
P.entries["quest:1287"] = {n="The Deserters",s="Intrebat despre Reethe, Balos Jacken, conducatorul dezertorilor din Lost Point, il numeste las si spune ca dezertorii l-au alungat din tabara lor. Apoi, Jacken iti cere sa uiti ca te-ai intalnit vreodata cu ei. Captain Garran Vimes din Theramore este cel caruia trebuie sa-i vorbesti despre Reethe.",h="Intrebat despre Reethe, Balos Jacken, conducatorul dezertorilor din Lost Point, il numeste las si spune ca...",kw={"balos jacken","brackenwall village","caldwell","dezertori","garran vimes","lost point","reethe","theramore"},sec={{t="Aruncat afara",b="Jacken spune ca dezertorii l-au alungat pe Reethe pentru ca prada in repetate randuri proviziile ogre-ilor din Brackenwall Village. Potrivit lui Jacken, dezertorii sunt prea putini ca sa se impotriveasca acelor ogre, iar Reethe a intrecut masura de prea multe ori, asa ca banda l-a lasat sa se descurce singur. In schimbul raspunsului, Jacken iti cere sa uiti intalnirea."},{t="Inapoi in Theramore",b="Vimes spune ca Lieutenant Caldwell va fi trimis impotriva dezertorilor din Lost Point si ca i se va cere sa-l gaseasca si pe Reethe. Vimes considera ca mlastina nu este nici atat de intinsa, nici atat de greu de strabatut incat Caldwell sa nu-l poata gasi pe Reethe."}},faq={{q="De ce a fost Reethe alungat din tabara dezertorilor?",a="Jacken spune ca Reethe tot prada proviziile ogreilor din Brackenwall Village. Dezertorii sunt prea putini ca sa li se impotriveasca, asa ca l-au lasat pe Reethe sa se descurce singur.",al={"de ce l-au exilat dezertorii pe Reethe","Reethe din Brackenwall Village","de ce l-a alungat Balos pe Reethe"}},{q="Cine este Balos Jacken?",a="Jacken ii conduce pe dezertorii din Lost Point. Intrebat despre Reethe, il numeste las.",al={"cine este balos jacken","balos jacken - poveste","balos jacken dustwallow"}},{q="Cine vrea sa afle despre Reethe?",a="Captain Garran Vimes din Theramore, desi Jacken spera ca vei uita ca i-ai intalnit vreodata pe dezertori.",al={"unde sa-i predai pe dezertori","cine doreste informatii despre reethe"}}},fp="13,260,10.335.0,17.214.1,47.162.0,20.81.0,31.106.0"}
P.entries["quest:1288"] = {n="Vimes's Report",s="Captain Garran Vimes considera ca munca ta este cea mai buna pe care a vazut-o la un amator. Lady Jaina Proudmoore i-a cerut lui Vimes sa o tina la curent cu o situatie delicata, iar Vimes iti da raportul ca sa i-l duci in Theramore.",h="Captain Garran Vimes considera ca munca ta este cea mai buna pe care a vazut-o la un amator.",kw={"dustwallow","garran vimes","jaina proudmoore","raport","theramore","vimes"},sec={{t="Un raport pentru Lady Proudmoore",b="Lady Proudmoore i-a cerut lui Captain Vimes sa o tina la curent cu o situatie delicata, iar Vimes nu a mai vorbit cu ea de ceva vreme. Vimes intentiona sa-i predea raportul mai tarziu, dar acum considera ca e mai potrivit sa discuti tu cu ea despre asta, fiindca s-ar putea sa ai raspunsuri mai bune la intrebarile ei decat ar avea Vimes."}},faq={{q="Cine iti da raportul pe care sa i-l duci lui Jaina Proudmoore?",a="Captain Garran Vimes iti da raportul lui Vimes, pe care sa-l duci la Lady Jaina Proudmoore, in Theramore.",al={"cine incepe vimes's report","cine da raportul","cine a scris raportul lui vimes"}},{q="De ce te trimite Captain Vimes in loc sa mearga el insusi?",a="Vimes nu a mai vorbit de ceva vreme cu Lady Proudmoore si considera ca ar fi mai potrivit sa mergi tu in locul sau. Vimes crede ca ai putea avea raspunsuri mai bune la intrebarile ei.",al={"de ce ma trimite","de ce nu-l livreaza Vimes","de ce raportul pentru Jaina"}},{q="Unde trebuie dus raportul?",a="Lui Lady Jaina Proudmoore, in Theramore.",al={"unde predau raportul lui Vimes","unde este Jaina Proudmoore","destinatia raportului"}}},fp="14,221,28.313.0,53.93.0,57.166.0,33.38.0"}
P.entries["quest:1289"] = {n="Vimes's Report",s="Lady Jaina Proudmoore a citit raportul lui Captain Garran Vimes si iti multumeste pentru ajutorul dat anchetei. Iti cere sa te intorci la Vimes si sa-l ajuti sa elucideze misterul.",h="Lady Jaina Proudmoore a citit raportul lui Captain Garran Vimes si iti multumeste pentru ajutorul dat...",kw={"captain garran vimes","dustwallow marsh","ancheta","lady jaina proudmoore","theramore","raportul lui Vimes"},sec={{t="Inapoi la capitan",b="Potrivit raportului lui Captain Vimes, Lady Proudmoore considera ca ai fost de mare ajutor in ancheta lui si iti multumeste. Are mai putine griji stiind ca problema se afla pe maini atat de capabile. Iti cere sa te intorci la Captain Vimes, in Theramore, si sa-l ajuti sa dezlege misterul."}},faq={{q="Cine te trimite inapoi la Captain Vimes?",a="Lady Jaina Proudmoore, dupa ce citeste raportul lui Vimes in Theramore.",al={"cine ofera raportul lui Vimes","Jaina, cea care ofera misiunea","cine ma trimite la Vimes"}},{q="Ce parere are Lady Jaina despre raport?",a="Ea spune ca ai fost de mare ajutor investigatiei si iti multumeste. Stiind ca problema este pe maini bune, se poate odihni mai linistita.",al={"reactia lui Jaina","ce spune Jaina despre raportul lui Vimes"}},{q="Unde il gasesti pe Captain Garran Vimes?",a="Captain Garran Vimes se afla in Theramore.",al={"unde este Captain Vimes","locatia lui Captain Vimes","unde predau raportul lui Vimes"}}},fp="14,188,19.309.0,36.69.0,41.140.0,39.37.0"}
P.entries["quest:129"] = {n="A Free Lunch",s="A Free Lunch este o sarcina a Alliance care porneste din Lakeshire, unde Darcy, bucatareasa hanului, ii cere unui aventurier sa duca o masa pregatita la gardianul Parker. Parker patruleaza pe drumul primejdios din sud, care duce spre Duskwood, tinand caile de acces spre Lakeshire libere de gnolli ostili si orci Blackrock.",h="A Free Lunch este o sarcina a Alliance care porneste din Lakeshire, unde Darcy, bucatareasa hanului, ii cere...",kw={"blackrock orcs","darcy","darkshire","free lunch","gnolls","paznicul parker","lakeshire","parker's lunch","redridge mountains"},ang={["faction:Alliance"]="Livrarea mancarii lui Darcy scoate in evidenta presiunea la care sunt supusi oamenii de rand si strajerii de la posturile de pe linia frontului din asezarile indepartate ale Alliance, lasate in mare masura sa se descurce singure.",["profession:Cooking"]="O portie calda si bine pregatita, luata pe teren, este adesea singurul lucru care-l tine in viata pe un santinel izolat, pazind o rascruce ostila."},sec={{t="O masa pentru drum",b="Viata de zi cu zi in Redridge este plina de tensiune, dar Darcy, o localnica din Lakeshire, incearca sa-i sprijine in felul ei pe cei care apara orasul. Dupa ce a pregatit o masa zdravana pentru Guard Parker, isi da seama ca nu o poate duce personal. Salbaticia de dincolo de portile orasului e plina de gnolli Redridge agresivi si cete de orci ratacitoare, asa ca deplasarea in afara perimetrului orasului este mult prea periculoasa pentru un civil fara armura. In schimb, se bazeaza pe calatorii aflati in trecere ca sa duca ratia pe drum, spre Darkshire."},{t="Paza granitei",b="Guard Parker este stationat pe drumul de la sud de Lakeshire si vegheaza asupra rutei care leaga Redridge de Duskwood. Garda din Redridge este rasfirata periculos de mult, iar armata din Stormwind nu reuseste sa trimita intariri suficiente impotriva haitelor de gnolli din Redridge, tot mai numeroase, si a Blackrock clan, inradacinat in munti. Veghea solitara intr-un tinut atat de ostil ii sleieste de puteri pe paznici precum Parker, asa ca gesturile simple de grija din partea civililor si mancarea calda sunt un sprijin esential pentru moralul trupelor."}},faq={{q="Unde il putem gasi pe Guard Parker?",a="Guard Parker patruleaza drumul de pamant spre sud, care duce din Lakeshire spre granita cu Duskwood si orasul Darkshire.",al={"locatia gardianului Parker","unde este Parker","gaseste-l pe gardianul Parker"}},{q="De ce nu livreaza Darcy pranzul chiar ea?",a="Darcy este un civil obisnuit si considera ca imprejurimile din Lakeshire sunt mult prea primejdioase pentru a le strabate singura. Gnoll ostili si orci Blackrock pandesc chiar de-a lungul drumurilor, la marginea orasului.",al={"de ce nu poate merge darcy","darcy in redridge"}},{q="Cu ce amenintari se confrunta Guard Parker?",a="Parker trebuie sa apere drumul sudic impotriva haitelor de gnoll care bantuie prin Redridge Mountains, precum si a grupurilor razboinice de orci Blackrock, agresive.",al={"dusmanii lui parker","amenintarile din redridge"}},{q="Ce se intampla dupa ce Guard Parker isi primeste pranzul?",a="Cand primeste masa lui Darcy, Parker este recunoscator si, in cele din urma, il trimite pe aventurier sa mai indeplineasca treburi casnice intre garzi si orasenii locului, incepand cu o vizita la herbalistul local.",al={"urmatoarea misiune dupa pranzul gratuit","continuarea misiunii lui parker"}},{q="De ce se chinuie garzile din Stormwind sa mentina Redridge in siguranta?",a="Cu regele Varian Wrynn disparut si conducerea politica a regatului preocupata de situatia din Stormwind City, asezari indepartate precum Lakeshire au primit putin sau deloc ajutor militar, lasandu-i pe garzile locale sa se descurce in mare parte singure.",al={"de ce nu este aparata Lakeshire","neglijenta Stormwind fata de Redridge"}},{q="Care este recompensa promisa de Darcy?",a="In schimbul transportarii mesei lui Parker prin tinuturile salbatice si primejdioase, Darcy promite sa pregateasca si sa-i serveasca un pranz gratuit curierului la intoarcerea in oras.",al={"ce este pranzul gratuit","recompensa lui darcy"}}},fx={a6c03f8c={q="De ce vrea Darcy ca Parker sa primeasca acest pranz?",a="Darcy are o inima buna si are grija de aparatorii orasului. Gardianul Parker este stationat departe, pe drumul spre Duskwood, unde se confrunta fara sprijin cu amenintarea constanta a gnollilor si orcilor Blackrock. Stiind cat de istovitoare si singuratica poate fi datoria de patrulare in vremurile acestea primejdioase, Darcy i-a pregatit o masa proaspata, ca sa-i dea putere si sa-i arate ca Lakeshire ii apreciaza serviciul.",al={"motivul pranzului lui darcy","de ce ii trimite pranzul lui parker","de ce ii pasa lui darcy de parker"}}},fp="12,287,19.526.0,19.536.0,32.125.0,44.188.0,42.147.0,47.208.1,58.230.0,32.159.0"}
P.entries["quest:13"] = {n="The People's Militia",s="In tot Westfall, The People's Militia se confrunta cu o amenintare tot mai mare din partea celor din Defias. Voluntarii lui Gryan Stoutmantle se lupta acum cu hoti care au trecut de la talharirea drumurilor la jefuirea Moonbrook si Gold Coast Quarry, iar Militia cere represalii mai aspre.",h="In tot Westfall, The People's Militia se confrunta cu o amenintare tot mai mare din partea celor din Defias.",kw={"alexston farmstead","jefuitor defias","pradator defias","gold coast quarry","gryan stoutmantle","moonbrook","militia poporului","sentinel hill","westfall"},ang={["class:Paladin"]="Ca paladin, il auzi pe Gryan Stoutmantle cerand Light sa curete Westfall de coruptia criminala. Aceasta campanie este pentru tine o misiune directa de dreptate.",["faction:Alliance"]="Ca luptator din Alliance, vezi prapastia amara dintre zidurile confortabile ale Stormwind City si tinuturile de frontiera infometate, lasate cu totul sa se descurce singure.",["race:Human"]="Ca Human, te confrunti cu lupta tragica impotriva fostilor pietrari si vecini care s-au intors cu violenta impotriva propriului popor."},sec={{t="Violenta in crestere",b="Atacurile Defias au depasit stadiul unor simple jafuri marunte pe drumuri si au devenit o amenintare mai ampla. Defias Looters si Pillagers, care arunca foc, au napadit centrele economice din Westfall. Ocupa Moonbrook, devasteaza Alexston Farmstead si au preluat controlul asupra Gold Coast Quarry. Gryan Stoutmantle vede primejdia: daca banditii pastreaza aceste locuri, recucerirea Westfall ar putea deveni imposibila fara o armata regala oficiala."},{t="Filozofia militiei",b="Stormwind nu i-a trimis lui Gryan Stoutmantle nici soldati, nici provizii, asa ca el face apel la Holy Light si la hotararea fermierilor ramasi in Westfall. Razboiul de uzura al People's Militia depinde de voluntarii care duc lupta in fortaretele Defias. Alungarea jefuitorilor va lipsi Brotherhood de resurse si le va arata locuitorilor inspaimantati ca aparatorii inca lupta pentru pacea si prosperitatea din Westfall."}},faq={{q="Ce este People's Militia?",a="Gryan Stoutmantle a organizat People's Militia ca forta armata de voluntari pentru apararea lui Westfall. Randurile sale sunt alcatuite in mare parte din fermieri stramutati din Westfall si calatori care ii sustin. S-a format pentru a se impotrivi lui Defias Brotherhood, dupa ce curtea regala din Stormwind a refuzat sa trimita garzi ale orasului.",al={"militia oamenilor","cine este militia","militia din Westfall"}},{q="Cine este Gryan Stoutmantle?",a="Gryan Stoutmantle este un comandant Human veteran care conduce apararea din Westfall din reduta aflata deasupra Sentinel Hill. Devotat Light-ului si tinutului sau natal, el coordoneaza rezistenta disperata a People's Militia impotriva celor care au pus stapanire pe regiune.",al={"Gryan","cine este Stoutmantle","povestea lui Stoutmantle"}},{q="De ce jefuiesc Defias ferme si cariere?",a="Defias Brotherhood vrea sa paralizeze aprovizionarea cu hrana a Westfall si sa puna mana pe materii prime. Punand stapanire pe Gold Coast Quarry, controleaza piatra si mineralele; capturarea Moonbrook si a fermelor ii alunga pe oamenii cinstiti si le ofera baze pentru activitatile lor criminale.",al={"de ce jefuiesc Defias","Defias in Moonbrook","de ce sunt jefuitori la cariera"}},{q="De ce nu a trimis Stormwind soldati in Westfall?",a="Stormwind nu a trimis soldati deoarece regele Varian Wrynn a disparut in mod misterios, lasandu-l pe baiatul-rege Anduin pe tron, sub regenta lui Highlord Bolvar Fordragon. Nobilimea din House of Nobles este puternic blocata de dispute, solicitand resursele coroanei si lasand tinuturi marginase precum Westfall pe seama aparatorilor locali.",al={"unde sunt garzile din Stormwind","de ce nu vine ajutor din Stormwind","regele Varian si Westfall"}},{q="Unde se gasesc jefuitorii si pradatorii Defias?",a="Defias Pillagers si Looters se aduna in jurul asezarilor capturate din sudul si vestul Westfallului. Ii gasesti in orasul abandonat Moonbrook, la Gold Coast Quarry de-a lungul falezelor vestice si la ruinele Alexston Farmstead.",al={"locatia jefuitorilor","unde sunt talharii","locatiile Defias"}}},fx={["3f9873c1"]={q="De ce vrea Gryan Stoutmantle ca Defias Pillagers si Looters sa fie ucisi?",a="Jefuitorii si pradatorii Defias ataca in mod activ gospodariile si resursele vitale ramase in Westfall, inclusiv Moonbrook, Gold Coast Quarry si Alexston Farmstead. Gryan Stoutmantle nu va permite hotilor sa-i lipseasca pe localnici de putina pace si de mijloacele de trai care le-au mai ramas. Doborandu-le grupurile de jefuitori, spera sa le stavileasca elanul, sa-i protejeze pe colonistii supravietuitori si sa transmita un mesaj limpede: faradelegea si coruptia vor fi intampinate cu forta.",al={"de ce sa omor pradatorii Defias","motivul lui Gryan Stoutmantle","de ce vrea Gryan sa-i omoare pe pradatori"}},["599e05d4"]={q="Cine sunt jefuitorii si pradatorii Defias vizati in aceasta sarcina?",a="Acestia sunt jefuitorii si vrajitorii de rand ai Defias Brotherhood, trimisi sa lase Westfall fara nimic. In timp ce hotii de buzunare obisnuiti cutreiera campurile deschise, acesti talhari si pradatori lovesc direct asezari precum Moonbrook si Gold Coast Quarry. Inarmati cu arme si magie de foc distrugatoare, aduna provizii, jefuiesc proprietati abandonate si alunga cu violenta orice colonist care incearca sa le stea in cale.",al={"cine sunt jefuitorii Defias","cine sunt talharii Defias","tinte Defias in Westfall"}},["7d97eb03"]={q="De ce are Gryan Stoutmantle nevoie de ajutorul tau, in loc sa se bazeze pe Militie?",a="People's Militia este impinsa pana la limita rezistentei. Cum Stormwind refuza sa ofere sprijin militar, Sentinel Hill nu are decat o mana de voluntari, fermieri si veterani iesiti la pensie pentru a pazi drumul si a-si apara dealul fortificat. Nu isi poate lipsi garnizoana de soldati pentru a lansa contraofensive ample in intreaga regiune, fara sa-si lase baza fara aparare. Aventurieri capabili ca tine ofera forta de atac de care Militia duce cumplit de mult lipsa.",al={"de ce are nevoie gryan de mine","de ce sa nu folosesti militia","de ce sa folosesti aventurieri"}}},fp="20,253,19.409.0,24.388.0,29.282.0,25.223.0,46.263.0,47.317.0,45.231.0"}
P.entries["quest:130"] = {n="Visit the Herbalist",s="Dupa ce ii aduci mancarea la avanpostul indepartat, gardianul Parker iti cere o favoare inainte sa te intorci la hanul din Lakeshire. Dorind sa-si marturiseasca sentimentele fata de Darcy, te trimite la herbalistul local sa cumperi flori. Parker insista sa nu-i spui herbalistului cine le-a comandat sau cui ii sunt destinate.",h="Dupa ce ii aduci mancarea la avanpostul indepartat, gardianul Parker iti cere o favoare inainte sa te intorci...",kw={"narcise","darcy","flori","guard parker","lakeshire","martie jainrose","redridge","vizita la herbalist"},ang={["faction:Alliance"]="Chiar si in mijlocul amenintarii constante a haitelor de gnolli si a orcilor Blackrock care patrund in Redridge, intre aparatorii din Lakeshire infloresc povesti de dragoste marunte, intre oameni de rand.",["profession:Herbalism"]="Vizita la Martie Jainrose le face cunostinta culegatorilor cu principalul negustor de plante medicinale si alchimie din Lakeshire, aflat la marginea vestica a orasului."},sec={{t="O cerere secreta a unui gardian",b="Stationat de-a lungul drumului pustiu de la sud de Lakeshire, Guard Parker isi petrece straja urmarind orcii Blackrock si gnolii. Cand ii aduci o masa calda de la Darcy, de la Lakeshire Inn, el profita de ocazie ca sa-i intoarca bunatatea. In loc sa te lase pur si simplu sa pleci, iti cere sa treci pe la bacania cu plante din capatul vestic al orasului si sa-i cumperi un buchet de flori."},{t="Barfele orasului si curtarea secreta",b="Viata intr-un orasel precum Lakeshire nu prea lasa loc secretelor, ceea ce explica de ce Parker te avertizeaza explicit sa nu-i dezvalui herbalistei Martie Jainrose de la cine sunt florile sau cui ii sunt destinate. Cand ajungi la pravalia ei, Martie nu se poate abtine sa te tachineze, presupunand ca ti-ai gasit repede o iubita in oras. Intr-o regiune napadita de incursiuni ale orcilor si banditi, chiar si un modest gest romantic este o distragere binevenita."}},faq={{q="Cine te trimite sa-l vizitezi pe fitoterapeut?",a="Guard Parker iti da aceasta sarcina. Este stationat pentru a pazi drumul din sud care duce spre Redridge Mountains, chiar la nord de granita cu Duskwood.",al={"cine da aceasta misiune","cel care da misiunea","gardianul Parker"}},{q="Cine este herbalistul din Lakeshire?",a="Martie Jainrose este herborista si florareasa locala din Lakeshire. Magazinul ei se afla la capatul de vest al orasului.",al={"cine este Martie Jainrose","unde se afla herbalistul","herbalistul din lakeshire"}},{q="De ce vrea Guard Parker flori?",a="Parker vrea sa-i trimita flori lui Darcy, chelnerita de la Lakeshire Inn care i-a adus un pranz gratuit, ca gest de interes romantic si recunostinta.",al={"de ce sa cumperi flori","pentru cine sunt florile","motivul lui Parker"}},{q="De ce vrea Parker ca achizitia sa ramana secreta?",a="Lakeshire este un orasel unit, unde vestile se raspandesc repede. Parker este timid cand vine vorba de a o curta pe Darcy si vrea sa evite barfele lui Martie Jainrose si ale celorlalti localnici.",al={"de ce sa pastrezi secretul","de ce sa ascunzi pentru cine sunt florile","nu-i spune lui Martie"}},{q="Ce se intampla dupa ce vorbesti cu Martie Jainrose?",a="Martie pregateste un buchet de narcise, ceea ce da startul sarcinii de a duce florile direct la Darcy, la Lakeshire Inn.",al={"ce urmeaza","Delivering Daffodils","dupa herbalist"}},{q="Unde se incadreaza in lantul de misiuni?",a="Aceasta misiune face legatura dintre 'A Free Lunch', in care ii duci pranzul lui Guard Parker, si 'Delivering Daffodils', in care duci florile inapoi la Darcy.",al={"lant de misiuni","conditie prealabila","lantul misiunii pranz gratuit"}}},fx={["07240ec3"]={q="De ce iti cere Guard Parker sa mergi la ierbar in loc sa mearga el insusi?",a="Parker este de serviciu, pazind drumurile din Redridge, si nu-si poate parasi pur si simplu postul ca sa faca treburi personale prin oras. Mai important, il stanjeneste profund ceea ce simte pentru Darcy. Vrea in mod expres ca gestul romantic sa ramana secret fata de Martie Jainrose si de toti ceilalti din Lakeshire, lucru imposibil daca l-ar vedea cumparand singur flori.",al={"de ce are parker nevoie de mine","de ce nu poate parker sa culeaga singur florile","de ce mi se cere sa vizitez un herbalist"}}},fp="19,303,24.413.0,31.449.0,37.153.0,34.116.0,35.148.0,46.173.0,46.127.1,39.158.1"}
P.entries["quest:1302"] = {n="James Hyal",s="\"James Hyal\" este o misiune Alliance despre un colonist uman care a navigat spre Kalimdor alaturi de expeditia lui Lady Jaina Proudmoore. Dupa ce a plecat sa deschida un han la granita, familia sa din Eastern Kingdoms a pierdut legatura cu el si cauta vesti despre soarta lui in arhivele administrative din Theramore.",h="\"James Hyal\" este o misiune Alliance despre un colonist uman care a navigat spre Kalimdor alaturi de...",kw={"functionar Lendry","bucatar","hangiul","Jaina Proudmoore","James Hyal","Kalimdor","Theramore"},ang={["faction:Alliance"]="James a navigat spre vest alaturi de Lady Jaina Proudmoore in timpul Third War, reflectand legaturile personale care unesc multe familii din Alliance de-a lungul Great Sea, cu Theramore Isle.",["profession:Cooking"]="Cunoscut in tinutul natal ca bucatar exceptional de talentat, James a plecat in Kalimdor pentru a-si castiga traiul administrand un han si hranind calatorii."},sec={{t="Dincolo de Great Sea",b="In timpul Third War, nenumarate suflete si-au parasit casele stramosesti din Eastern Kingdoms pentru a o urma pe Lady Jaina Proudmoore peste Great Sea. Printre ele se numara James Hyal, amintit cu drag de rudele sale ca un bucatar talentat. Dupa ce luptele s-au domolit si Theramore Isle a fost intemeiata, James a ales sa-si castige traiul pe continentul accidentat Kalimdor, deschizandu-si propriul han pentru a-i gazdui pe calatori si pe ceilalti colonisti."},{t="In cautarea unui frate",b="In Eastern Kingdoms, fratele lui James a inceput sa se ingrijoreze dupa ce n-a mai primit nicio veste de peste mare. In speranta ca James este doar coplesit de cerintele administrarii unui han aglomerat de la marginea drumului, le cere calatorilor sa-l gaseasca. Primul pas pentru a-l descoperi duce in Theramore, unde functionarul Lendry tine evidentele locale si urmareste membrii expeditiilor plecati in salbaticie."}},faq={{q="Cine este James Hyal?",a="James Hyal este un colonist uman si un bucatar talentat care a traversat Great Sea cu flota lui Lady Jaina Proudmoore. In cautarea unui nou mijloc de trai in Kalimdor dupa incheierea luptelor, a pornit sa deschida un han pe continent.",al={"cine este james hyal","povestea lui james hyal","cine este james"}},{q="Unde il pot gasi pe James Hyal?",a="James a pornit sa infiinteze un han undeva pe continentul Kalimdor, dupa ce a sosit cu expeditia lui Lady Proudmoore. Familia lui nu a mai primit vesti de la el de ceva vreme, insa Clerk Lendry din Theramore Isle tine registrele si s-ar putea sa-i cunoasca locul exact.",al={"unde este James Hyal","gaseste-l pe James Hyal","locatia lui James Hyal"}},{q="Cine este Clerk Lendry?",a="Clerk Lendry este un functionar al Alliance stationat in Theramore Isle, care se ocupa de administratia locala si de solicitarile cetatenilor. Calatorii care ii cauta pe colonisti precum James Hyal sunt indrumati la Lendry pentru a verifica registrele din Theramore.",al={"cine este functionarul Lendry","locatia functionarului Lendry","functionar din Theramore"}},{q="De ce a calatorit James in Kalimdor?",a="James a navigat cu flota Lady Jaina Proudmoore in timpul Third War, ca parte a exodului oamenilor din Eastern Kingdoms. Dupa ce marile conflicte s-au incheiat, a ales sa ramana si sa construiasca un han pentru calatori si colonisti.",al={"de ce a mers james in kalimdor","expeditia lui james hyal"}},{q="Cine il cauta pe James Hyal?",a="Solicitarea vine de la fratele lui James din Eastern Kingdoms, care nu a mai primit vesti de la el de ceva vreme. Stiindu-l pe James un bucatar priceput, fratele sau presupune ca este doar ocupat cu deschiderea noului han.",al={"cine da misiunea lui James Hyal","cine este fratele lui James"}},{q="Este James Hyal in pericol?",a="Fratele sau crede ca este doar ocupat sa-si conduca noua afacere, presupunand ca pacea de pe continent i-a permis sa prospere. Totusi, familia sa nu a mai primit vesti directe de la el de ceva vreme.",al={"este james hyal in siguranta","ce i s-a intamplat lui james hyal"}}},fp="10,300,20.416.0,22.438.0,18.233.0,28.252.0,20.226.0,33.225.0,30.217.0,28.210.0"}
P.entries["quest:131"] = {n="Delivering Daffodils",s="Delivering Daffodils incheie o mica treaba domestica intre postul de garda si piata orasului Lakeshire. Dupa ce aduci pranzul lui Guard Parker si ridici un buchet de la Martie Jainrose, herbalista, ii dai florile lui Darcy, la Lakeshire Inn, si nimeresti direct in mijlocul unei rivalitati locale stanjenitoare.",h="Delivering Daffodils incheie o mica treaba domestica intre postul de garda si piata orasului Lakeshire.",kw={"daffodil bouquet","darcy","delivering daffodils","gardian parker","lakeshire","martie jainrose","redridge","sauteed sunfish"},ang={["faction:Alliance"]="Ajutorul dat garzii orasului si hangiului din Lakeshire mentine moralul civililor, in timp ce orasul se lupta cu incursiunile Blackrock si ale gnolilor.",["profession:Cooking"]="Darcy te rasplateste pentru livrare cu peste-soare sotat, bine condimentat, oferind un exemplu de mancare simpla, gatita acasa, de pe malul lacului din Redridge.",["profession:Herbalism"]="Sarcina se bazeaza pe cunostintele botanice ale lui Martie Jainrose si pe ochiul ei pentru florile proaspete de pe malul lacului, dezvaluind latura pasnica a culesului de plante."},sec={{t="O insarcinare parfumata",b="Ceea ce incepe ca o simpla favoare, aceea de a-i duce o masa calda lui Guard Parker, se transforma intr-un gest romantic delicat. Recunoscator pentru pranz, Parker iti cere sa iei flori de la Martie Jainrose, ca surpriza pentru Darcy, bucatareasa care i-a pregatit mancarea. Martie aranjeaza un buchet proaspat din florile ei preferate, narcise, fara sa stie cine urmeaza sa le primeasca."},{t="Rivalitati intre asezari",b="Dupa ce buchetul ajunge inapoi la Lakeshire Inn, incantarea initiala a lui Darcy se transforma repede in suspiciune. Recunoscand narcisele drept florile preferate ale lui Martie, Darcy banuieste imediat ca Parker a avut de-a face cu o femeie pe care o considera o vulpe geloasa. Desi se teme ca Martie ar fi otravit florile din rautate daca ar fi stiut cine le primeste, Darcy te scapa de orice vina si iti da, drept rasplata pentru osteneala, o portie fierbinte de peste-soare sotat."}},faq={{q="Cine este Darcy?",a="Darcy lucreaza la Lakeshire Inn, in Redridge Mountains, unde pregateste mancare pentru localnici si garzile orasului. Ea este bucatareasa care i-a trimis pranzul lui Guard Parker, iar acesta i-a raspuns trimitandu-i un buchet de flori, drept multumire.",al={"darcy","cine este darcy in Lakeshire","bucatareasa din Lakeshire darcy"}},{q="Cine este Martie Jainrose?",a="Martie Jainrose este fitoterapeuta si pasionata de flori din Lakeshire. Guard Parker te trimite la ea sa cumperi un buchet frumos, iar Martie alcatuieste cu placere un buchet de narcise, mentionand ca acestea sunt chiar florile ei preferate.",al={"Martie Jainrose","herbalista din Lakeshire","cine a dat florile"}},{q="De ce este Darcy suparata din cauza narciselor?",a="Darcy recunoaste pe loc narcisele ca fiind florile preferate ale lui Martie. O considera pe Martie o rivala geloasa si se teme ca aceasta ar fi otravit tulpinile daca ar fi stiut ca buchetul era pentru Darcy.",al={"de ce este Darcy furioasa","cearta dintre Darcy si Martie","de ce au fost otravite florile"}},{q="A otravit Martie buchetul, de fapt?",a="Nu. Martie nu stia ca florile erau pentru Darcy, deoarece Parker doar a rugat-o sa-i pregateasca un buchet, iar Martie si-a ales fara sa se gandeasca florile preferate pentru acesta.",al={"sunt narcisele otravite","este buchetul otravit"}},{q="Ce misiuni duc la aceasta livrare?",a="Seria incepe cu 'A Free Lunch', in care duci masa lui Darcy la Guard Parker. Apoi Parker iti da misiunea 'Visit the Herbalist', ca sa cumperi un cadou de la Martie Jainrose, iar aceasta se incheie cu 'Delivering Daffodils'.",al={"lantul de misiuni","cerinte preliminare pentru daffodils","lantul Delivering Daffodils"}},{q="Ce recompensa primesti pentru livrarea florilor?",a="Darcy iti multumeste cu un pachet consistent de pesti soare caliti, niste cupru si experienta, precum si cu reputatie in regatul Stormwind.",al={"recompensa misiunii","recompensele pentru daffodils"}}},fx={["12ade65f"]={q="De ce vrea Martie Jainrose sa-i duci narcise lui Darcy?",a="Martie Jainrose a ales narcisele pur si simplu pentru ca sunt florile ei preferate, fara sa stie pentru cine le dorea Parker. Gardianul Parker ti-a cerut sa aduci un buchet pentru a rasplati bunatatea lui Darcy, iar Martie a aranjat cu bucurie florile ei preferate. Ceea ce ea considera un aranjament minunat, Darcy percepe imediat ca pe o insulta din partea unei rivale sentimentale meschine.",al={"de ce narcise","motivul lui Martie Jainrose","de ce sa trimiti narcise"}}},fp="20,322,17.358.0,14.430.1,13.214.0,23.223.0,39.196.1,39.173.1,37.203.0,50.136.0"}
P.entries["quest:1319"] = {n="The Black Shield",s="Captain Garran Vimes regreta ca nu te poate ajuta prea mult cu Blackened Iron Shield, dar stie cine se poate descurca mai bine: Caz Twosprocket, unul dintre cei mai buni fierari din zona, care ingrijeste forja din fieraria Theramore.",h="Captain Garran Vimes regreta ca nu te poate ajuta prea mult cu Blackened Iron Shield, dar stie cine se poate...",kw={"scut de fier innegrit","captain garran vimes","caz twosprocket","dustwallow marsh","the black shield","theramore"},sec={{t="Un fierar care poate spune",b="Vimes isi cere scuze ca nu poate ajuta prea mult cu scutul, dar numeste pe cineva care poate. Trebuie sa-l duci la Caz Twosprocket, unul dintre cei mai buni fierari, care se ocupa de forja din fieraria Theramore. Poate ca Caz iti va putea spune ceva despre el."},{t="Parerea fierarului",b="Caz cerceteaza fierul si il numeste o piesa interesanta. Nu este opera lui Caz si, cu siguranta, nu este opera vreunui fierar pe care Caz sa-l cunoasca de partea aceasta a apei."}},faq={{q="Cine te trimite sa examinezi scutul?",a="Captain Garran Vimes din Theramore, caruia ii pare rau ca nu te poate ajuta prea mult si te indruma catre cineva mai priceput.",al={"cine ofera the black shield","cel care incepe misiunea black shield","cine incepe the black shield"}},{q="Cine este Caz Twosprocket?",a="Un fierar care intretine forja din atelierul de fierarie din Theramore. Vimes il considera unul dintre cei mai buni.",al={"caz twosprocket","cine este fierarul din theramore"}},{q="Ce scut ii este aratat lui Caz?",a="Scutul de fier innegrit.",al={"scut de fier innegrit","ce scut sa-i arat lui caz"}}},fp="16,207,19.248.0,19.161.1,36.110.0,23.88.0,28.26.0"}
P.entries["quest:132"] = {n="The Defias Brotherhood",s="In Westfall, The Defias Brotherhood construieste o retea care depaseste simplul banditism. Wiley the Black transmite vesti despre legaturile sale cu gnolli, kobolds si goblini. Gryan Stoutmantle are nevoie de aceste informatii pentru a masura amploarea conspiratiei care sufoca Westfall.",h="In Westfall, The Defias Brotherhood construieste o retea care depaseste simplul banditism.",kw={"Defias Brotherhood","gnolli","goblini","Gryan Stoutmantle","kobolzi","Sentinel Hill","Westfall","Wiley the Black","biletul lui Wiley"},ang={["class:Rogue"]="Ca Rogue, poti vedea cum Wiley the Black paseste pe linia subtire dintre proscris si informator util si cum legaturile cu lumea interlopa transmit informatii militare in vreme de razboi.",["faction:Alliance"]="Pentru Alliance, cooperarea dintre proscrisii human, gnolli si goblini arata cat de grava este lipsa de securitate de la granitele vestice ale Stormwindului.",["race:Human"]="Ca human, stii ca biletul confirma ca banditii care jefuiesc gospodariile familiilor din Westfall si Redridge desfasoara o campanie deliberata si coordonata."},sec={{t="Un mesaj periculos",b="Wiley the Black spune ca dezvaluirea a ceea ce stie despre Defias l-ar putea costa viata. Pe la marginile Redridge si Westfall, a prins zvonuri despre o operatiune mult mai ampla decat jafurile de drumul mare. Biletul sau sigilat descrie felul in care Brotherhood a coordonat grupuri care, de obicei, sunt ostile unele fata de altele, raspandite prin tinut."},{t="Alliances neasteptate",b="Wiley avertizeaza ca Defias a creat in jurul sau o retea alarmanta. Banditii cu masti rosii au recrutat haite de gnoll, sapatori kobold si ingineri goblin, in loc sa actioneze singuri. Impreuna, forta lor brutala, munca de excavare si ingeniozitatea mecanica indica o operatiune mult peste asteptarile initiale ale People's Militia."},{t="Dependenta nelinistitoare a lui Stoutmantle",b="Gryan Stoutmantle nu-l prea simpatizeaza pe Wiley si deplange deschis faptul ca nu l-a lasat pe rogue sa putrezeasca atunci cand a avut ocazia. Totusi, Westfall nu-si poate permite orgolii. Cum Stormwind ignora apelurile pentru ajutor militar, People's Militia trebuie sa foloseasca informatiile utile oriunde le poate gasi."}},faq={{q="Despre ce este Wiley's Note?",a="Biletul lui Wiley the Black avertizeaza ca Defias Brotherhood se coordoneaza cu gnoll-i, kobolzi si ingineri goblin. El le spune celor din People's Militia ca proscrisii pregatesc o operatiune mult mai ampla decat simple talharii.",al={"nota lui Wiley","ce scrie in nota","nota lui Wiley the Black"}},{q="Cine este Wiley the Black?",a="Wiley the Black este un contact dubios, stationat la Lakeshire, in Redridge. Gryan Stoutmantle il considera un ticalos de neuitat, dar Wiley are legaturi intinse in lumea interlopa si informatii esentiale despre activitatea Defias.",al={"cine este Wiley","Wiley the Black lore","Wiley Lakeshire"}},{q="De ce s-ar alia Defias cu gnollii si koboldii?",a="Defias foloseste creaturi locale pentru a controla teritoriul si a asigura forta de munca ieftina. Gnollii actioneaza ca luptatori brutali de harta care sa-i distraga pe aparatori, koboldii sapa tuneluri in minele regiunii, iar tehnicienii goblin contribuie cu utilaje grele si unelte de demolare.",al={"de ce folosesc Defias gnolli","kobolzii si aliatii Defias","aliatii Defias"}},{q="De ce nu-l place Gryan Stoutmantle pe Wiley?",a="Gryan Stoutmantle este un fost soldat disciplinat, care il considera pe Wiley un simplu hot de buzunare si infractor. Regreta ca l-a scutit pe Wiley de inchisoare, desi urechea lui pentru zvonurile lumii interlope este de nepretuit.",al={"stoutmantle si wiley","de ce il uraste pe wiley"}},{q="Cum se incadreaza acest mesaj in ancheta militiei?",a="Mesajul lui Wiley duce ancheta militiei de la recunoasterea locala spre conspiratia mai ampla a Defias. Primirea raspunsului il indeamna pe Stoutmantle sa cerceteze conducerea conspiratiei si locurile sale de adunare.",al={"etapa din lantul defias","ce misiune este aceasta"}},{q="De ce nu se ocupa Stormwind de aceasta amenintare?",a="In lipsa regelui Varian Wrynn, House of Nobles din Stormwind refuza sa deturneze soldati regali sau fonduri pentru a apara Westfall. People's Militia a lui Stoutmantle, pestrita si slab organizata, este lasata sa apere regiunea.",al={"ajutor din Stormwind pentru Westfall","unde sunt gardienii"}}},fx={["3bfb9fad"]={q="De ce te trimite Wiley the Black la Gryan Stoutmantle?",a="Wiley stie ca Defias Brotherhood pune la cale ceva catastrofal, dupa ce a adunat zvonuri potrivit carora ar colabora cu gnolli, kobolzi si goblini. Stie prea bine ca detinerea unor asemenea secrete periculoase ii pune propria viata in joc. Punandu-si cunostintele intr-un mesaj sigilat pentru Gryan Stoutmantle, Wiley lasa sarcina de a actiona in seama People's Militia, contribuind la zadarnicirea conspiratiei, dar ramanand in afara liniei de foc.",al={"de ce ajuta Wiley","motivul lui Wiley the Black","de ce trimite biletul lui Wiley"}},["6813809b"]={q="De ce se bazeaza Wiley pe tine in loc sa duca el insusi biletul?",a="Wiley este un nelegiuit din lumea interlopa care isi pastreaza profilul discret la hanul din Lakeshire, departe de privirile vigilente atat ale autoritatilor, cat si ale celor din Defias. O calatorie pe jos prin tinut ostil pana in Westfall l-ar pune in mare primejdie, iar trecutul sau cu Gryan Stoutmantle il face detestat, nu binevenit. Tu esti un curier priceput, care se poate strecura prin salbaticie fara sa fie observat si poate duce avertismentul direct la Sentinel Hill.",al={"de ce are Wiley nevoie de tine","de ce nu poate Wiley merge in Westfall","de ce eu, biletul lui Wiley"}}},fp="22,250,20.328.0,18.328.0,29.283.0,27.217.0,23.229.0,50.238.0,41.187.0,61.203.0,41.193.0"}
P.entries["quest:1320"] = {n="The Black Shield",s="Caz Twosprocket cerceteaza scutul negru din misterul Shady Rest Inn si aproape ca nu observa un ultim detaliu. Caz te trimite la Captain Garran Vimes din Theramore cu ceea ce ati gasit.",h="Caz Twosprocket cerceteaza scutul negru din misterul Shady Rest Inn si aproape ca nu observa un ultim detaliu.",kw={"scut negru","caz twosprocket","dustwallow marsh","garran vimes","shady rest inn","tauren","theramore"},sec={{t="O curea arsa complet",b="Examinand scutul negru, Caz Twosprocket aproape ca nu observa un ultim detaliu: cureaua de piele de pe spate a ars, dar pare sa fi fost facuta pentru o persoana masiva. Caz banuieste ca era un Tauren. Asta e tot ce poate spune Caz, iar tu esti trimis la capitanul Garran Vimes din Theramore cu vestea si cu scuzele lui Caz ca nu a putut fi de mai mult ajutor."},{t="Ce parere are Vimes despre asta",b="Vimes considera ca indiciul nu prea ajuta, dar spune ca va tine minte. Speranta este ca si celelalte piese ale misterului sa se potriveasca si sa arate mai limpede ce s-a intamplat."}},faq={{q="Ce descopera Caz Twosprocket despre scut?",a="Cureaua de piele de pe spate a ars, dar pare sa fi fost facuta pentru o persoana masiva. Caz banuieste ca era un Tauren.",al={"descoperirile lui caz","indicii despre scut","indiciu despre scutul negru"}},{q="Cine ar trebui sa afle ce a descoperit Caz?",a="Capitanul Garran Vimes din Theramore.",al={"cui ii spun despre scut","predau Black Shield","unde raportez despre scut"}}},fp="16,181,19.350.0,22.165.1,52.122.0,31.34.0"}
P.entries["quest:1321"] = {n="The Black Shield",s="Krog se uita la Blackened Iron Shield si nu vede nimic neobisnuit. Krog sugereaza ca fierarul Do'gol sa-l examineze, desi nu prea are sperante, si te trimite la Brackenwall Village.",h="Krog se uita la Blackened Iron Shield si nu vede nimic neobisnuit.",kw={"scut negru","scut din fier innegrit","brackenwall village","do'gol","dustwallow marsh","krog"},sec={{t="O a doua opinie",b="Krog nu vede nimic neobisnuit la scut. Fierarul Do'gol ar putea sa-ti spuna mai multe despre el, spune Krog, dar te avertizeaza sa nu ai prea mari asteptari. Do'gol se afla in Brackenwall Village."},{t="Raspunsul lui Do'gol",b="Do'gol spune ca este un scut bun, rezistent si greu. Totusi, Do'gol nu are nevoie de el, fiindca faureste scuturi, nu le cumpara, si spune ca ar trebui sa stii asta."}},faq={{q="Cine te trimite la Do'gol cu scutul?",a="Krog, care a cercetat Blackened Iron Shield si nu a gasit nimic neobisnuit la el.",al={"cine da misiunea black shield","unde incep misiunea black shield","cel care ofera misiunea black shield"}},{q="Unde poate fi gasit Do'gol?",a="Do'gol este fierarul din Brackenwall Village.",al={"locatia lui dogol","unde este dogol","gaseste-l pe dogol"}},{q="De ce te trimite Krog la Do'gol?",a="Krog spera ca fierarul va putea spune mai multe despre scut, desi nu se asteapta sa obtina prea multe informatii.",al={"de ce sa-l vizitez pe Dogol","de ce sa-i arat scutul fierarului"}}},fp="16,193,16.183.0,15.155.1,40.83.0,26.48.0,33.105.0"}
P.entries["quest:1322"] = {n="The Black Shield"}
P.entries["quest:1323"] = {n="The Black Shield",s="Do'gol a frecat scutul pana cand a putut distinge ceea ce pare sa scrie Mosarn, un nume care nu-i spune nimic. Krog din Brackenwall Village cunoaste multa lume, asa ca Do'gol te trimite acolo sa intrebi.",h="Do'gol a frecat scutul pana cand a putut distinge ceea ce pare sa scrie Mosarn, un nume care nu-i spune nimic.",kw={"acid","scut negru","brackenwall village","do'gol","dustwallow marsh","krog","mosarn"},sec={{t="Un nume pe margine",b="Do'gol a turnat cam prea mult acid, dar o frecare usoara scoate la iveala o inscriptie greu de citit, care pare sa spuna Mosarn. Numele nu-i spune nimic lui Do'gol. Krog din Brackenwall Village cunoaste multa lume, asa ca Do'gol te trimite sa vorbesti cu Krog."},{t="Raspunsul lui Krog",b="Krog spune ca numele Mosarn ii este familiar, dar nu reuseste sa-si aminteasca de unde; spera sa-i revina mai tarziu in minte. Krog adauga ca probabil nu conteaza, fiindca scuturile apar de prin tot felul de locuri si nu inseamna nimic."}},faq={{q="Cine este Do'gol?",a="Cel din Brackenwall Village care a curatat scutul cu acid pentru a-i putea citi inscriptia.",al={"dogol","cine da scutul negru"}},{q="Ce nume este scris pe scut?",a="Do'gol crede ca scrisul spune Mosarn, desi e greu de citit, si nu a auzit niciodata de cineva cu acest nume.",al={"ce nume este pe scut","cine este mosarn","numele inscriptionat pe scut"}},{q="De ce sa vorbesti cu Krog despre scut?",a="Do'gol nu stie cine este Mosarn, dar spune ca Krog cunoaste multi oameni.",al={"de ce sa vorbesti cu krog","cine este krog"}},{q="Unde se afla Krog?",a="Krog se afla in Brackenwall Village.",al={"locatia lui krog","unde il gasesc pe krog"}}},fp="16,196,17.249.0,13.204.1,14.94.0,27.111.0,34.68.0,22.31.0"}
P.entries["quest:133"] = {n="Ghoulish Effigy",s="In adancul salbaticiei intunecate din Duskwood, excentricul pustnic Abercrombie sustine ca locuinta sa izolata este asediata de mortii care umbla. Pentru a-si apara casa, le cere aventurierilor aflati in trecere sa adune coaste de ghoul pentru a construi o sperietoare bizara.",h="In adancul salbaticiei intunecate din Duskwood, excentricul pustnic Abercrombie sustine ca locuinta sa...",kw={"Abercrombie","Bone Chewers","Darkshire","Duskwood","efigie","mancatori de carne","coasta de ghoul","pustnic"},ang={["class:Paladin"]="Vanarea celor din Flesh Eaters si Bone Chewers curata pamantul din Duskwood de molima, chiar daca predarea ramasitelor lor unui pustnic pare de-a dreptul tulburatoare.",["class:Priest"]="Sa ajuti un pustnic inspaimantat, ramas izolat printre spirite intunecate, este o fapta nobila, desi asamblarea unor efigii din ramasite adunate iti pune stomacul la incercare.",["faction:Alliance"]="Night Watch se straduieste sa protejeze drumurile, lasandu-i pe locuitorii izolati ai padurii, precum Abercrombie, sa se bazeze pe calatorii din Alliance aflati in trecere pentru a se apara de mortii nelinistiti."},sec={{t="Necazurile unui pustnic",b="Abercrombie locuieste mult dincolo de granitele pazite ale Darkshire, izolat printre copacii umbriti din Duskwood. Aici, ghouluri ratacitoare precum Flesh Eaters si Bone Chewers umbla nestingherite. Sustinand ca niste cadavre hamesite i-au daramat recent zidurile, pustnicul inspaimantat le cere coastele acestor orori pentru a fauri un mijloc de descurajare, sperand ca o efigie infioratoare ii va tine la distanta pe mortii infometati."},{t="O aparare bizara",b="Desi bunul-simt ar putea indemna pe oricine sa fuga spre siguranta Night Watch sau sa-si intareasca baraca de lemn, Abercrombie insista asupra unor metode macabre. El crede ca un chip cioplit din ramasitele unui ghul ii va speria pe ceilalti morti veniti la scotocit. Desi ridicarea unei sperietori din strigoi macelariti pare nelinistitoare, calatorii din Duskwood ii dau adesea crezare pustnicului excentric pentru a castiga niste bani bineveniti."}},faq={{q="Unde locuieste Abercrombie?",a="Abercrombie locuieste intr-o coliba izolata din vestul Duskwood, chiar la nord-est de Raven Hill Cemetery si departe de protectia oferita de Darkshire.",al={"locatia lui Abercrombie","unde este coliba lui Abercrombie","coliba pustnicului din Duskwood"}},{q="De ce are nevoie Abercrombie de coaste de ghoul?",a="Abercrombie sustine ca haite de ghuli ii bat in peretii colibei. Intentioneaza sa foloseasca oasele pentru a confectiona o efigie hidoasa de sperietoare, ca sa alunge strigoii care cauta hoituri.",al={"scopul coastelor de ghoul","de ce coaste de ghoul","la ce foloseste efigia"}},{q="Ce creaturi lasa Ghoul Rib?",a="Coastele pot fi adunate de la orice strigoi din zona care ratacesc pe drumurile si prin cimitirele din Duskwood, mai exact Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones si Plague Spreaders.",al={"de unde iei coaste","ce lasa ghoul-ii","ce ghoul lasa coaste"}},{q="Chiar alunga ghoul-ii construirea unei sperietori de ciori undead?",a="Undead rareori dau semne de frica, ceea ce face ca planul lui Abercrombie sa para indoielnic vanatorilor de monstri cu experienta. Totusi, pustnicul insista asupra proiectului sau straniu, iar in astfel de paduri napastuite putini refuza un angajator care plateste.",al={"functioneaza efigiile asupra ghouls","logica sperietorii pentru ghoul"}},{q="De ce nu se muta pur si simplu Abercrombie in Darkshire?",a="Abercrombie alege sa traiasca izolat, departe de Night Watch si de conducerea orasului. In ciuda primejdiilor vadite din salbaticia Duskwood, prefera sa-si gospodareasca singur coliba, aparandu-se in felul sau neobisnuit.",al={"de ce locuieste in padure","de ce nu se muta Abercrombie","siguranta in Darkshire"}},{q="Ce urmeaza dupa strangerea coastelor?",a="Dupa ce primeste coastele de ghoul, Abercrombie gaseste inca o dilema bizara de rezolvat, trimitand aventurieri si mai adanc in salbaticie sa se ocupe de ogres locali care i-au furat bunurile.",al={"urmatoarea misiune","ce urmeaza dupa efigia macabra"}}},fx={d0d16021={q="La ce se folosesc Ghoul Ribs?",a="Abercrombie pretinde ca are nevoie de coastele unor ghouli din zona pentru a fauri o efigie macabra, o sperietoare de strigoi, pe care s-o aseze in fata colibei sale izolate. Locuind mult dincolo de siguranta Darkshire, el sustine ca aratarea groteasca va alunga ororile mancatoare de carne care ii pandesc zidurile.",al={"la ce folosesc coastele de ghoul","folosirea coastelor de ghoul","de ce sa aduni coaste de ghoul"}},["0ad10362"]={q="De ce are nevoie Abercrombie sa aduni coastele?",a="Abercrombie este un pustnic excentric si firav, izolat in padure, care nu are nicio simpatie pentru Darkshire sau pentru Night Watch. Ingrozit de ghoul-ii care-i izbesc in peretii cocioabei, nu are forta razboinica necesara pentru a infrunta singur ororile putrede, asa ca depinde de aventurierii trecatori dispusi sa infrunte primejdiile din Duskwood pentru bani.",al={"de ce mi se cere mie","de ce nu se ocupa Abercrombie de asta","de ce sa nu-i ceri ajutorul lui Night Watch"}},cd024384={q="De ce cutreiera ghoulii prin Duskwood?",a="Umbra care se apropia si a inghitit regiunea, cufundand-o intr-un amurg vesnic, i-a tulburat si pe mortii de acolo. Strigoii nelinistiti, de la Bone Chewers lacomi la ghouli mancatori de carne, se ridica acum prin intuneric si prin cimitire, ratacesc prin padurile in descompunere si prada fara incetare orice suflet viu destul de nesabuit incat sa iasa din asezarile fortificate.",al={"de ce sunt ghuli aici","ghuli din Duskwood","de unde provin ghulii"}}},fp="15,258,17.392.0,17.409.0,28.140.0,37.170.0,36.186.0,56.197.0,53.208.0,41.182.0"}
P.entries["quest:1338"] = {n="Stormpike's Order",s="In Loch Modan, Mountaineer Stormpike comanda un scut de la Furen Longbeard. Armurierul lucreaza mult mai la sud, in Stormwind City, asa ca Stormpike ii cere unui calator sa-i duca acolo comanda.",h="In Loch Modan, Mountaineer Stormpike comanda un scut de la Furen Longbeard.",kw={"armurier","districtul dwarven","furen longbeard","ironforge","loch modan","scut","stormpike","stormwind"},ang={["faction:Alliance"]="In calitate de calator din Alliance, poti vedea legaturile comerciale si culturale dintre fortaretele piticesti din Khaz Modan si Stormwind, unite de Deeprun Tram.",["profession:Blacksmithing"]="Ca fierar, poti lua aminte la Furen Longbeard, un mester exceptional in armuri, recunoscut chiar si dincolo de hotarele regatelor, in timp ce calatoresti prin Stormwind.",["race:Dwarf"]="Fiind un dwarf, vezi cat de departe poate ajunge reputatia unui clan. Stormpike's Order ridica si intrebarea de ce un maestru armurier ar alege piatra human in locul celei din Ironforge."},sec={{t="Un scut care merita calatoria",b="Mountaineer Stormpike vrea un scut nou si are incredere doar in Furen Longbeard ca sa-l faureasca. Munteanul este dispus sa plateasca bine pentru a-i incredinta comanda fierarului, desi Loch Modan si Stormwind City sunt departe unul de celalalt."},{t="De la Ironforge la Dwarven District",b="Stormpike se intreaba de ce Furen lucreaza atat de departe de Ironforge si Great Forge, unde isi au casa multi Dwarf. Banuieste ca oamenii din Stormwind ii platesc fierarului o avere regeasca. Cand ordinul ajunge la Furen, la nicovala lui, armurierul se mandreste ca a primit vesti de la prestigiosul clan Stormpike si se grabeste sa pregateasca faurirea scutului."}},faq={{q="Cine este Mountaineer Stormpike?",a="Mountaineer Stormpike este un santinela al Alliance, stationat in Loch Modan. Apartine clanului Stormpike, mandru si influent, si slujeste alaturi de mountaineers Dwarf care protejeaza trecatorile si vaile muntoase.",al={"Mountaineer Stormpike","cine ofera misiunea","cel care da misiunea"}},{q="Cine este Furen Longbeard?",a="Furen Longbeard este un iscusit faurar de armuri dwarven, care locuieste in Stormwind City's Dwarven District. Reputatia sa pentru faurirea unor scuturi si armuri de calitate superioara ajunge pana la nord, in Khaz Modan.",al={"furen longbeard","cine este furen","armurierul"}},{q="De ce locuieste Furen in Stormwind in loc de Ironforge?",a="Furen Longbeard lucreaza in Dwarven District din Stormwind, unde le ofera servicii nobililor oameni, gardienilor orasului si aventurierilor aflati in trecere. Mountaineer Stormpike se intreaba de ce un dwarf maestru ar parasi Ironforge, dar Furen probabil castiga bani frumosi in moneda oamenilor.",al={"de ce este Furen in Stormwind","de ce este in districtul piticilor","Furen pleaca din Ironforge"}},{q="Ce rol are Deeprun Tram in livrarea acestui ordin?",a="Calatorii care poarta misiva lui Stormpike merg de obicei spre vest din Loch Modan catre Ironforge, apoi iau Deeprun Tram pe sub pamant pana in Stormwind City's Dwarven District, unde se afla forja lui Furen.",al={"calatorie spre Stormwind","cum ajung in Stormwind","Deeprun Tram"}},{q="Ce misiune preceda aceasta?",a="Inainte sa-ti incredinteze livrarea catre Stormwind, Mountaineer Stormpike iti pune la incercare curajul si seriozitatea in Loch Modan, prin 'Mountaineer Stormpike's Task'.",al={"cerinte preliminare","misiunea precedenta","Mountaineer Stormpike's Task"}},{q="Forjeaza Furen Longbeard scutul pe loc?",a="Cand primeste scrisoarea si recunoaste prestigiul numelui Stormpike, Furen Longbeard accepta comanda si promite sa inceapa sa faureasca scutul inainte de sfarsitul zilei.",al={"ce urmeaza","misiune urmatoare","reactia lui Furen"}}},fx={["317873dc"]={q="De ce vrea Mountaineer Stormpike ca acest lucru sa fie facut?",a="Mountaineer Stormpike are nevoie de un scut nou si tine mestesugul lui Furen Longbeard intr-o stima cu totul deosebita, considerand ca priceperea armurierului nu are egal. Desi il nedumereste faptul ca un mester pitic de asemenea calibru locuieste atat de departe, printre oamenii din Stormwind, in loc sa stea langa Ironforge, Stormpike nu se multumeste cu o aparare inferioara si insista sa primeasca un scut faurit chiar de mana lui Furen.",al={"de ce are stormpike nevoie de un scut","motivul lui mountaineer stormpike","de ce sa iau o comanda de la furen"}},["02c191af"]={q="De ce te roaga Mountaineer Stormpike pe tine in loc sa mearga el insusi?",a="Ca Mountaineer activ, stationat in trecatorile inalte din Loch Modan, Stormpike nu-si poate abandona pur si simplu postul de paza al frontierelor piticilor pentru a calatori spre sud, in tinuturile oamenilor. Trimiterea unei insarcinari in Dwarven District din Stormwind presupune o calatorie lunga, asa ca apeleaza la aventurieri aflati in trecere, care au timp la dispozitie si sunt dispusi sa-i duca mesajul pentru o plata cinstita.",al={"de ce sa trimit un aventurier la Furen","de ce nu poate Stormpike sa livreze ordinul","de ce eu pentru ordinul lui Stormpike"}}},fp="17,185,26.228.0,38.337.0,29.210.0,23.184.0,54.258.0,57.195.0,29.160.0,50.191.0"}
P.entries["quest:134"] = {n="Ogre Thieves",s="Abercrombie, pustnicul excentric care locuieste in vestul Duskwood, le cere calatorilor sa se aventureze in fortareata ogre din Vul'Gol Ogre Mound. El sustine ca ogrii l-au atacat in timp ce cauta hrana si au fugit cu o lada plina de ierburi si unelte de neinlocuit.",h="Abercrombie, pustnicul excentric care locuieste in vestul Duskwood, le cere calatorilor sa se aventureze in...",kw={"abercrombie","lada","duskwood","pustnic","ogru","vul'gol"},ang={["class:Paladin"]="Bucuria nerabdatoare si tainica a lui Abercrombie la recuperarea lazilor sale ar trebui sa-i puna in garda pe toti slujitorii Holy Light, ca sa nu-l ajute orbeste pe pustnicul retras.",["class:Warlock"]="Warlock familiarizati cu artele interzise vor recunoaste fara greutate ca Abercrombie a scapat porumbelul din gura despre vrajitoria neagra, nu despre o simpla pasiune botanica.",["profession:Herbalism"]="Desi Abercrombie sustine ca lada lui contine doar ierburi, un fitoterapeut s-ar putea intreba ce flora bizara trebuie recuperata cu atata disperare dintr-o movila de ogri."},sec={{t="Bunurile pierdute ale unui pustnic",b="Retras de-a lungul drumurilor umede din vestul Duskwood, batranul pustnic Abercrombie spune ca a fost atacat in timp ce aduna provizii in salbaticie. Potrivit lui, niste brute din movila capcaunilor din sud l-au alungat, silindu-l sa abandoneze o lada solida de lemn, plina cu ierburi pretioase si instrumente delicate."},{t="Amenintarea Vul'Gol",b="Vul'Gol Ogre Mound, aflat in sudul lui Duskwood, este un adapost fortificat al capcaunilor ostili, care ii hartuiesc pe calatorii neatenti. Cufarul se afla chiar langa intrarea in musuroiul lor ca o pestera, provocandu-i pe straini sa treaca pe langa uriasele care rag si magii care tes vraji, ca sa-l duca inapoi pustnicului."},{t="O scapare de vorbe",b="Dupa ce isi recupereaza marfurile pierdute, purtarea excentrica a lui Abercrombie se transforma intr-o exaltare maniacala. Aproape ca striga laude la adresa lui 'Nec...' inainte sa se opreasca brusc si sa-i multumeasca in schimb aventurierului, nerabdator sa se inchida in casa si sa-si foloseasca proviziile recuperate in intuneric."}},faq={{q="Cine este Abercrombie?",a="Abercrombie este un pustnic excentric si singuratic, care locuieste intr-o coliba darapanata din vestul Duskwood. Desi se poarta ca si cum ar fi plapand, neajutorat si ar avea nevoie de ajutor, agitatia si cererile sale ciudate sugereaza motive mai intunecate si tulburatoare.",al={"povestea lui Abercrombie","cine mi-a dat aceasta misiune","cine este pustnicul"}},{q="Unde au dus ogres lada lui Abercrombie?",a="Lada a fost dusa la Vul'Gol Ogre Mound, in sudul Duskwood. Zace la vedere, pe pamant, chiar in fata gurii pesterii ogre.",al={"unde este lada","locatia lazii","lada din Vul'gol"}},{q="De ce sunt ogri in Duskwood?",a="Capcaunii din clanul Vul'Gol si-au croit un punct de sprijin in dealurile accidentate din sudul Duskwood. Agresivi si oportunisti, ataca in mod regulat trecatorii, ii iau prin surprindere pe calatorii singuratici si aduna prada furata in jurul culcusului lor.",al={"capcanii din duskwood","originea capcanilor din vul'gol","de ce sunt capcani aici"}},{q="Ce se afla de fapt in lada?",a="Abercrombie sustine ca lada contine ierburi rare si unelte speciale de recoltare, pe care le-a abandonat in timpul atacului, si este nespus de incantat sa le aiba inapoi.",al={"ce a pierdut abercrombie","continutul lazii"}},{q="Ce era cat pe ce sa spuna Abercrombie cand a primit lada?",a="Dupa ce isi primeste lada inapoi, Abercrombie incepe sa-i multumeasca altcuiva, dar se opreste brusc si ii multumeste aventurierului in schimb, apoi se arata incantat de serile care il asteapta.",al={"multumeste-i nec","ce spunea Abercrombie","replica lui Abercrombie"}},{q="Are aceasta misiune vreo legatura cu alte treburi de la movila capcaunilor?",a="Adventurer-ii care calatoresc la Vul'Gol Ogre Mound s-ar putea sa adune si monocli de ogre pentru Viktori Prism'Antras.",al={"misiuni de la movila ogrelor","misiuni in apropiere de vulgol"}}},fx={["7ac39a32"]={q="De ce isi vrea Abercrombie lada inapoi?",a="Abercrombie sustine ca se afla departe de coliba sa, cautand provizii, cand a fost prins intr-o ambuscada de ogri si silit sa-si abandoneze colectia de ierburi rare si uneltele delicate. Pentru un pustnic singuratic care traieste la marginea cimitirului, este aproape imposibil sa-si inlocuiasca singur asemenea provizii. Totusi, tulburarea lui intensa si usurarea disperata cand acestea ii sunt inapoiate sugereaza ca le foloseste intr-un scop mult mai sinistru decat simpla indeletnicire cu plantele.",al={"de ce sa recuperez lada","motivul lui abercrombie pentru lada","de ce vrea lada"}},["1d020e8a"]={q="Cine sunt ogrii care tin lada?",a="Hotii fac parte din ogrii Vul'Gol, proscrisi brutali care si-au sapat un barlog respingator in stancile din sudul Duskwood. Cunoscand obiceiul lor de a jefui calatori pe potecile intunecate, au dat peste Abercrombie in timp ce acesta se afla departe de locurile pe care le frecventa, l-au alungat pe batranul pustnic si i-au tarat incarcatura inapoi in asezarea lor, alaturi de alte prazi.",al={"cine a luat lada","ogrii din Vul'Gol","lada ogreilor din Duskwood"}},["504b8e87"]={q="De ce te roaga Abercrombie pe tine, si nu pe Night Watch?",a="Abercrombie este un pustnic firav si retras, lipsit atat de puterea de a infrunta o tabara de brute masive, cat si de orice bunavointa din partea celor din Darkshire. Orasenii suspiciosi si membrii Night Watch, care au deja prea multe pe cap, pastreaza distanta fata de coliba sa, pazind doar drumurile principale si marginile orasului. Neputand conta pe autoritatile locale, pustnicul depinde de aventurierii aflati in trecere, dispusi sa infrunte primejdiile din Vul'Gol Ogre Mound.",al={"de ce eu","de ce nu Night Watch","de ce are nevoie Abercrombie de ajutor"}}},fp="12,265,21.316.0,18.273.0,20.291.1,19.227.0,45.140.0,32.226.0,34.152.1,57.189.1,57.106.0"}
P.entries["quest:135"] = {n="The Defias Brotherhood",s="In Westfall, necazurile Defias Brotherhood ajung pana la Stormwind. Gryan Stoutmantle te trimite sa-i predai lui Master Mathias Shaw Wiley's Note, banuind o legatura intre Defias si vechea Stonemasons Guild.",h="In Westfall, necazurile Defias Brotherhood ajung pana la Stormwind.",kw={"fratie","defias","gryan stoutmantle","mathias shaw","old town","si:7","zidari","westfall","biletul lui wiley"},ang={["class:Rogue"]="La sediul SI:7, il intalnesti pe Mathias Shaw, marele maestru al celor din clasa Rogue si al spionilor din Stormwind. Munca lui leaga tulburarile locale din Westfall de operatiuni clandestine mai ample.",["faction:Alliance"]="In calitate de membru al Alliance, vezi fisuri in principalul regat al Alliance. Unele amenintari vin din partea cetatenilor tradati, nu a strainilor monstruosi.",["race:Human"]="Ca Human din Stormwind, vezi cum tinutul fara lege de la marginea Westfall se intalneste cu scandalurile politice amare si nerezolvate care au urmat reconstruirii capitalei tale."},sec={{t="O scapare de vorbe",b="O mentiune despre Stonemasons in comunicarile lui Wiley atrage atentia lui Gryan Stoutmantle. Constructorii au refacut Stormwind City dupa First War, dar de multa vreme se crede ca ghilda s-a risipit sau a fost desfiintata. Daca Defias Brotherhood are legaturi cu ei, insurgenta rurala din Westfall este mai mult decat o banda dezorganizata de banditi."},{t="Secretele din Old Town",b="Din Sentinel Hill, Gryan Stoutmantle nu-si poate confirma banuielile. Te trimite la maestrul Mathias Shaw, seful serviciului secret al Stormwind, SI:7. Shaw isi desfasoara activitatea din cazarma din Old Town, adunand zvonuri si secrete din intregul regat. S-ar putea sa poata descifra originile Defias Brotherhood."},{t="Umbra deasupra coroanei",b="Wiley's Note ii aduce lui Master Mathias Shaw o veste ingrijoratoare: rebeliunea din Westfall este mai profunda si are ramificatii politice mai complicate decat intelege Gryan Stoutmantle. Shaw aminteste de propriul trecut tumultuos al Stormwind."}},faq={{q="De ce te trimite Gryan Stoutmantle in Stormwind?",a="O mentiune despre Stonemasons din Wiley's Note il face pe Gryan Stoutmantle sa banuiasca intrigi politice in spatele banditismului. Te trimite la Master Mathias Shaw sa confirmi legatura.",al={"de ce sa mergi la Stormwind","de ce misiunea din Stormwind","treaba lui Stoutmantle in Stormwind"}},{q="Cine este Mathias Shaw?",a="Maestrul Mathias Shaw conduce SI:7, ramura secreta de informatii si spionaj din Stormwind. Isi desfasoara activitatea din cazarma din Old Town.",al={"cine este shaw","rolul lui mathias shaw","liderul si7"}},{q="Unde il gasesc pe Mathias Shaw?",a="Il gasesti pe Master Mathias Shaw la etajul al doilea al sediului SI:7, in cazarma din Old Town, Stormwind City.",al={"unde este Shaw","locatia lui Shaw","gaseste-l pe Mathias Shaw"}},{q="Ce legatura exista intre Defias si zidari?",a="Stonemasons Guild a reconstruit Stormwind dupa distrugerea sa din First War. Gryan Stoutmantle banuieste ca mentiunea facuta de Wiley despre breasla o leaga de Defias, iar Mathias Shaw poate confirma sau infirma aceasta legatura.",al={"zidari Defias","sunt zidari Defias","legatura cu zidarii"}},{q="Ce este Wiley's Note?",a="Wiley's Note vine de la Wiley the Black, un ticalos cu care Gryan Stoutmantle a mai avut de-a face. Mesajul avertizeaza ca cei din Defias comploteaza impreuna cu gnolli, kobolds si goblini, iar mentiunea lui Wiley despre Stonemasons ar putea lega Defias Brotherhood de fosta breasla.",al={"biletul lui Wiley","ce este biletul","bilet pentru Shaw"}},{q="Stie Highlord Bolvar sau regele-copil despre asta?",a="Treburile secrete ale statului trec prin Mathias Shaw si SI:7 inainte sa ajunga la Highlord Bolvar Fordragon si la tron. Shaw spune ca situatia ar putea fi mai complicata decat isi da seama Stoutmantle.",al={"stie regele","stie bolvar","ce stie guvernul din stormwind"}}},fx={f764ce01={q="De ce te trimite Gryan Stoutmantle in locul unui soldat din People's Militia?",a="People's Militia abia mai rezista, aparand Sentinel Hill si fermele rasfirate din Westfall. Gryan Stoutmantle nu-si poate permite sa retraga de pe front aparatori pregatiti de lupta pentru a duce mesaje inapoi in capitala. In plus, esti un strain care a descifrat deja indiciile lui Wiley, ceea ce te face un curier de incredere, capabil sa duca intrebari sensibile direct la seful spionilor din Stormwind.",al={"de ce sa ma trimita pe mine","de ce nu militia","de ce are nevoie Stoutmantle de tine"}}},fp="22,207,20.332.0,16.314.0,25.215.1,49.179.0,20.125.0,29.118.0,62.212.1,21.255.0,53.181.0"}
P.entries["quest:1358"] = {n="Sample for Helbrim"}
P.entries["quest:1359"] = {n="Livrarea lui Zinge"}
P.entries["quest:136"] = {n="Captain Sanders' Hidden Treasure",s="O harta vechi si uzata pe pergament da startul aventurii Captain Sanders' Hidden Treasure de-a lungul coastei Westfall. Cautarea incepe cu o explorare a tarmului in incercarea de a gasi cufarul personal al regretatului capitan, apoi se indreapta spre prada sa ascunsa in intreaga regiune.",h="O harta vechi si uzata pe pergament da startul aventurii Captain Sanders' Hidden Treasure de-a lungul coastei...",kw={"captain sanders","cufar","comoara ascunsa","ancora ruginita","naufragiu","harta comorii","coasta Westfall"},ang={["class:Rogue"]="Ca Rogue, cunosti valoarea urmaririi hartii unui marinar mort de-a lungul unui tarm fara lege. O vanatoare de comori piratereasca li se potriveste ticalosilor si corsarilor.",["faction:Alliance"]="Ca aventurier Alliance, recuperarea unei averi de pe coasta din Westfall, plina de epave, este o mica victorie in mijlocul tulburarilor de la frontiera regatului, unde Murloc de coasta ameninta tarmul."},sec={{t="Ultima dorinta a unui marinar",b="Epavele si spiritele nelinistite ale marinarilor inecati definesc coasta vestica a Westfall. Captain Sanders, un vechi lup de mare, si-a gasit acolo moartea in ape. A lasat indicatii criptice pentru ca averea castigata cu greu sa nu fie inghitita de Great Sea sau luata de cotropitori. Un aventurier hotarat ii poate reface drumul."},{t="Ancora ruginita",b="Primul indiciu duce la o ancora ruginita, singuratica, in valurile de pe coasta vestica a lui Westfall. Langa o epava, pe jumatate ingropat in nisip, se afla vechiul cufar de campanie al lui Captain Sanders, batut de valuri. Inauntru se gasesc apa sarata, nisip si un crab miscator care strange urmatoarea piesa din puzzle-ul lui Sanders."}},faq={{q="Cine a fost Captain Sanders?",a="Captain Sanders a fost un batran capitan de corabie, iar harta lui spune ca zace intr-un mormant acvatic. A lasat harta si o serie de indicii care duc la prada ascunsa.",al={"povestea capitanului Sanders","cine este Sanders","trecutul lui Sanders"}},{q="Unde se afla lada de voiaj?",a="Lada de voiaj este pe jumatate ingropata in nisipul de pe coasta vestica din Westfall, langa o ancora ruginita, singuratica, pe tarm.",al={"locatia cufarului","unde se afla ancora ruginita","gaseste cufarul lui Sanders"}},{q="Contine lada de voiaj comoara capitanului?",a="Harta te indruma spre un cufar de calatorie si urmatorul indiciu dintr-o vanatoare de comori mai ampla.",al={"este vreo comoara in cufar","ce se afla in lada de voiaj","unde se afla aurul"}},{q="Cate indicii sunt in vanatoarea de comori a capitanului Sanders?",a="Vanatoarea are patru etape de-a lungul coastei si prin tinuturile rurale din Westfall, incepand cu harta si incheindu-se la adevaratul cufar cu comori al lui Captain Sanders, aflat pe o insula in largul coastei.",al={"cat dureaza misiunea lui Sanders","cate parti sunt","lantul de misiuni al lui Sanders"}},{q="De ce si-a ingropat Captain Sanders comoara in Westfall?",a="Harta lui Captain Sanders nu spune de ce a ales Westfall. Spune ca se astepta sa-si gaseasca sfarsitul in ape si ca voia ca oricine ii urma indiciile sa-i gaseasca comoara, cu indicii raspandite de-a lungul coastei si pe falezele de deasupra ei.",al={"de ce sa ascunzi comoara","de ce coasta Westfall"}},{q="Pot jucatorii din Horde sa urmeze aceasta harta a comorii?",a="Da. Harta si indiciile lui Captain Sanders sunt neutre, asa ca orice aventurier care ajunge pe coasta din Westfall ii poate urma urma.",al={"poate Hoarda sa faca asta","misiunea lui sanders pentru Hoarda","comoara neutra fata de factiuni"}}},fx={["1a1a7b8a"]={q="De ce a lasat Captain Sanders aceasta harta cu comori?",a="Capitanul Sanders stia ca-l astepta un mormant in adancul apelor si nu voia ca bogatiile stranse de el sa putrezeasca uitate pe fundul marii. A lasat un sir criptic de indicii pentru oricine ar fi avut istetimea si curajul sa-i descopere pergamentul. Punandu-i pe calatorii ambitiosi sa-si caute vechea lada, se asigura ca numele si mostenirea sa dainuie mult dupa moarte.",al={"de ce harta lui sanders","motivul lui sanders pentru harta comorii","de ce a lasat harta comorii"}}},fp="32,243,23.319.0,16.278.1,24.149.0,32.122.0,51.80.1,53.170.0,54.217.0,43.117.0"}
P.entries["quest:1361"] = {n="Regthar Deathgate"}
P.entries["quest:1362"] = {n="Kolkarul Desolacei"}
P.entries["quest:1365"] = {n="Khan Dez'hepah",s="Dupa The Kolkar of Desolace, Felgur Twocuts te trimite impotriva liderului Kolkar, Khan Dez'hepah. Numeroase clanuri de centauri se lupta intre ele in Desolace, iar Felgur vrea sa-i destabilizeze pe Kolkar inainte ca aceste clanuri sa se uneasca.",h="Dupa The Kolkar of Desolace, Felgur Twocuts te trimite impotriva liderului Kolkar, Khan Dez'hepah.",kw={"centaur","Desolace","Dez'hepah","Felgur Twocuts","Khan Dez'hepah","Kolkar","satul Kolkar"},sec={{t="Clanuri dezbinate",b="Kolkar sunt doar unul dintre clanurile de centauri din Desolace. Multi ratacesc prin campiile aride, luptand si murind de mana unora dintre ceilalti. Felgur Twocuts nu se sinchiseste, fiindca centaurii sunt puternici si brutali, iar un popor centaur unit ar fi un dusman de temut pentru Horde. Trebuie sa se ocupe de ei inainte sa se intample asta."},{t="Conducatorul Kolkar",b="Prima miscare a lui Felgur este sa-i perturbe pe Kolkar ucigandu-le liderul, pe Khan Dez'hepah. Kolkar Village se afla la nord-est de locul unde sta Felgur, iar acesta vrea sa-i fie adus inapoi capul khanului."}},faq={{q="De ce vrea Felgur Twocuts ca Khan Dez'hepah sa moara?",a="Felgur se teme ca clanurile centaurilor s-ar putea uni impotriva Horde. Uciderea lui Khan Dez'hepah are menirea de a destabiliza mai intai Kolkar clan.",al={"de ce sa-l omori pe Dezhepah","scopul lui Khan Dezhepah","motivul pentru care il omori pe Dezhepah"}},{q="Unde se afla Khan Dez'hepah?",a="In Kolkar Village, la nord-est de Felgur Twocuts, in Desolace.",al={"locatia lui khan dezhepah","unde este dezhepah","locatia kolkar village"}},{q="Ce vrea Felgur sa-i fie adus inapoi?",a="Capul lui Khan Dez'hepah, adus lui Felgur Twocuts.",al={"dovada khan dezhepah","ce sa-i duci lui felgur"}},{q="Ce preceda Khan Dez'hepah?",a="Kolkar of Desolace. Dupa aceasta, Felgur Twocuts te trimite impotriva conducatorului Kolkar, Khan Dez'hepah.",al={"misiunea anterioara Dez'hepah","cerinta prealabila pentru Khan Dez'hepah"}}},fp="14,214,13.309.0,17.190.0,49.132.0,32.63.0,35.54.0,33.101.0"}
P.entries["quest:1366"] = {n="Centaur Bounty",s="Dupa Khan Dez'hepah, Felgur Twocuts spune ca acum trebuie varsat sangele clanurilor de centaur inspaimantate. Vanati centaur din orice clan in Desolace si aduceti-i lui Felgur cincisprezece dintre urechile lor.",h="Dupa Khan Dez'hepah, Felgur Twocuts spune ca acum trebuie varsat sangele clanurilor de centaur inspaimantate.",kw={"centaur","recompensa pentru centauri","urechi de centaur","desolace","felgur twocuts","khan dez'hepah"},sec={{t="E timpul sa-i facem sa sangereze",b="Felgur Twocuts spune ca acum, dupa ce clanurile centaurilor au fost inspaimantate, a venit vremea sa le sangereze. Oriunde ai calatori prin Desolace, vaneaza centauri. Lui Felgur nu-i pasa ce clan vanezi, ci doar sa aduni urechi, cincisprezece la numar. Rarirea randurilor lor le va slabi hotararea si va pune capat oricaror ganduri de expansiune."},{t="Verdictul lui Felgur",b="Cand te intorci, Felgur spune ca centaurul trebuie sa-ti stie deja numele si sa-l respecte si sa se teama de el. Stiu si sub ce steag lupti: cel al Horde."}},faq={{q="Cine a ordonat aceasta recompensa pentru centaur?",a="Felgur Twocuts, in Desolace. Trebuie sa-i aduci lui Felgur cincisprezece urechi de centaur.",al={"cine da recompensa pentru centauri","cel care da misiunea privind recompensa pentru centauri"}},{q="Ce clanuri de centauri trebuie vanate?",a="Oricare dintre ei. Lui Felgur nu-i pasa ce clan vanezi, ci doar sa aduni urechi.",al={"ce centaur trebuie sa ucid","ce clan trebuie sa vizez pentru recompensa pe centauri"}},{q="De ce vrea Felgur atatea urechi de centaur?",a="Pentru a slabi numarul centaurilor. Mai putini centauri inseamna o vointa mai slaba si inabusa orice gand de expansiune.",al={"de ce sa ucizi centauri in desolace","motivul recompensei pentru centauri"}},{q="Ce a precedat aceasta recompensa?",a="Urmeaza dupa Khan Dez'hepah. Felgur spune ca clanurile centaurilor au fost inspaimantate, iar acum a venit vremea sa le varsati sangele.",al={"cerinta prealabila pentru recompensa pe centauri","misiunea anterioara pentru recompensa pe centauri"}}},fp="14,165,18.314.0,16.151.1,38.83.0,38.81.0,42.111.0,29.108.0"}
P.entries["quest:1367"] = {n="Magram Alliance",s="Gurda Wildmane propune sa intoarca ura clanurilor centaurilor impotriva lor: sa te imprietenesti cu un clan si sa-l folosesti pentru a afla cum pot fi invinsi toti. Daca te aliezi cu Magram, trebuie sa-i ucizi pe dusmanii lor, Gelkis, apoi sa vorbesti cu purtatorul de cuvant Magram, Warug, la marginea Magram Village, in sud-estul Desolace.",h="Gurda Wildmane propune sa intoarca ura clanurilor centaurilor impotriva lor: sa te imprietenesti cu un clan...",kw={"centaur","desolace","gelkis","gurda wildmane","magram","magram village","warug"},sec={{t="Ura ca arma",b="Planul Gurdei Wildmane este sa exploateze ura reciproca dintre centauri. Un singur clan este ales ca aliat, iar ceea ce te invata acesta iti arata cum sa invingi toate clanurile. Alege Magram si ii vei dobori pe Gelkis, dusmanii lor, castigandu-ti respectul printre cei din Magram."},{t="Purtatorul de cuvant",b="Dupa ce ai castigat suficient respect, Warug, purtatorul de cuvant Magram, te asteapta la marginea localitatii Magram Village, in sud-estul Desolace. Inainte de asta, nu are nimic sa-ti spuna. Magram nu vorbesc cu cei slabi, ci ii ucid, asa ca te trimite sa-ti dovedesti puterea infruntand numerosi Gelkis."},{t="Judecata lui Warug",b="Warug iti spune ca Gelkis plang cand iti aud numele, temandu-se de tine si urandu-te asa cum ii urasc pe Magram. Poate ca, admite el, esti la fel de puternic ca Magram. Va vedea."}},faq={{q="Cine propune o alianta cu Magram?",a="Gurda Wildmane vrea sa intoarca ura dintre clanurile centaurilor impotriva lor, aliindu-se cu un clan si afland de la acesta cum sa-i invinga pe toti.",al={"cine ofera magram alliance","magram, cel care da misiuni","gurda wildmane, cel care da misiuni"}},{q="Cum castigi respectul celor din Magram?",a="Ucigandu-le dusmanii, Gelkis.",al={"cum sa devii prietenos cu magram","reputatia magram","fa-i pe magram prietenosi"}},{q="Unde este Warug?",a="La marginea Magram Village, in sud-estul zonei Desolace. El este purtatorul de cuvant al Magram.",al={"unde este warug","gaseste-l pe warug","locatia lui warug"}},{q="De ce refuza Warug sa vorbeasca la inceput?",a="Spune ca Magram nu stau de vorba cu cei slabi, ci ii omoara. Mai intai dovedeste-ti puterea ucigand multi Gelkis.",al={"de ce nu vrea warug sa vorbeasca","warug furios","dialogul lui warug"}}},fp="15,310,18.256.0,13.301.0,16.176.1,41.142.0,42.34.0,15.86.0,40.110.0"}
P.entries["quest:1368"] = {n="Gelkis Alliance",s="Gurda Wildmane propune sa intoarca ura clanurilor centaur impotriva lor: sa se alieze cu un clan si sa afle astfel cum pot fi infrante toate. Alegand tabara Gelkis, trebuie sa-i ucizi cel mai mare dusman, pe Magram, apoi sa te intalnesti cu Uthek the Wise, un shaman al Gelkis, la marginea Gelkis Village, in sud-vestul Desolace.",h="Gurda Wildmane propune sa intoarca ura clanurilor centaur impotriva lor: sa se alieze cu un clan si sa afle...",kw={"centaur","desolace","gelkis","gelkis village","gurda wildmane","magram","uthek the wise"},sec={{t="Ura ca arma",b="Planul Gurdei Wildmane este sa exploateze ura reciproca dintre centauri. Un singur clan este ales ca aliat, iar ceea ce te invata acesta iti arata cum sa invingi toate clanurile. Alege Gelkis si ii vei ucide pe Magram, cei pe care Gelkis ii urasc cel mai mult, castigandu-le respectul."},{t="Shamanul",b="Dupa ce le-ai castigat respectul, urmeaza sa te intalnesti cu Uthek the Wise, shaman al Gelkis, la marginea Gelkis Village, in sud-vestul Desolace. Pana atunci, nu te primesc acolo: Uthek spune ca pasesti pe pamantul Gelkis, iar prietenia trebuie dovedita prin uciderea centaurilor Magram. Revino dupa ce sangele Magram a imbibat pamantul."},{t="Cuvantul lui Uthek",b="Uthek spune ca pamantul arata cati Magram ai ucis si ca asta e bine. Uthek are mai mult de lucru pentru un prieten al celor din Gelkis."}},faq={{q="Cine propune o alianta cu Gelkis?",a="Gurda Wildmane vrea sa intoarca ura dintre clanurile centaurilor impotriva lor, aliindu-se cu un clan si afland de la acesta cum sa-i invinga pe toti.",al={"cine ofera alianta gelkis","cel care da misiunea alianta gelkis"}},{q="Cum castigi bunavointa celor din Gelkis?",a="Ucigandu-i pe Magram, pe care Gelkis ii urasc cel mai mult.",al={"cum sa devii prietenos cu Gelkis","reputatie Gelkis"}},{q="Cu cine vorbesti dintre Gelkis?",a="Uthek the Wise, un shaman Gelkis, la marginea satului Gelkis Village din sud-vestul Desolace.",al={"unde se afla Uthek","locatia lui Uthek the Wise"}},{q="Ce ii cere Uthek inainte sa te primeasca?",a="Uthek spune ca nu esti binevenit pe pamantul Gelkis pana nu-ti dovedesti prietenia ucigand centauri Magram.",al={"de ce ma respinge uthek","gelkis village ostil"}}},fp="15,321,18.248.0,10.326.0,12.141.1,41.142.0,40.49.0,37.90.0,45.100.0"}
P.entries["quest:1369"] = {n="Broken Tears",s="Warug spune ca Gelkis cred in mod prostesc ca mama centaurilor, Theradras, ii protejeaza. Te trimite in pestera din satul lor ca sa distrugi cristalele pe care le ascund acolo, lacrimile lui Theradras, si sa-i aduci trei dintre bucatile sfaramate.",h="Warug spune ca Gelkis cred in mod prostesc ca mama centaurilor, Theradras, ii protejeaza.",kw={"broken tears","centaur","desolace","gelkis","magram","theradras","warug"},sec={{t="Cristale in pestera",b="Warug ii dispretuieste pe Gelkis pentru ca se incred in Theradras, mama centaurilor, ca sa-i apere. Pentru el, nimeni nu-i apara pe centauri, iar Magram, fiind cei mai puternici, nu au nevoie de protectie. Te trimite in pestera din Gelkis Village, unde acestia pastreaza o comoara de cristale numite lacrimile lui Theradras. Sfarama-le si adu-i lui Warug trei bucati sparte. Iti va incredinta aceasta sarcina doar daca nu esti dusman al Magram."},{t="Laudarosenia lui Warug",b="Warug este incantat: acum ca lacrimile au fost sfaramate, Gelkis vor intelege ca Theradras nu-i poate ajuta, iar nicio lacrima de-a ei nu va cadea cand Magram ii vor zdrobi. El declara ca Magram vor domni si te numeste intelept pentru ca te-ai aliat cu cei mai puternici."}},faq={{q="Cine este Warug?",a="Un centaur Magram din Magram Village, in Desolace. Iti cere sa distrugi lacrimile lui Theradras din pestera Gelkis.",al={"Warug","cine ofera Broken Tears","cel care ofera misiunea Broken Tears"}},{q="Ce sunt lacrimile lui Theradras?",a="Cristale pe care Gelkis le aduna intr-o pestera din satul lor.",al={"lacrimile lui theradras","povestea Broken Tears","cristale gelkis"}},{q="De ce vrea Warug ca lacrimile sa fie distruse?",a="Cei din Gelkis cred ca Theradras, mama centaurilor, ii protejeaza. Warug ii numeste prosti, spune ca cei din Magram nu au nevoie de protectie si vrea sa le arate celor din Gelkis ca se insala.",al={"de ce sa distrug lacrimile","motivul Magram","de ce sa sparg cristalele"}},{q="Unde se gasesc cristalele?",a="In pestera din Gelkis village. Warug vrea sa-i fie aduse inapoi trei fragmente sparte.",al={"unde sunt broken tears","locatia pesterii gelkis","unde sunt lacrimile"}}},fp="12,237,20.411.0,13.235.1,13.113.0,32.53.0,40.168.0,29.87.0"}
P.entries["quest:1370"] = {n="Stealing Supplies",s="Uthek the Wise spune ca hrana din carne le da putere celor din Gelkis, iar cei din Magram pastreaza provizii suplimentare pentru a putea lupta mai mult intre vanatori. Esti trimis sa jefuiesti satul Magram din est si sa aduci sase saci de carne uscata.",h="Uthek the Wise spune ca hrana din carne le da putere celor din Gelkis, iar cei din Magram pastreaza provizii...",kw={"centaur","Desolace","Gelkis","Magram","carne","provizii","Uthek"},sec={{t="Carne si putere",b="Intre razboaie, Gelkis vaneaza, fiindca hrana inseamna putere, iar cei cu burta plina lupta mai bine decat cei infometati. Uthek the Wise spune ca Magram pastreaza provizii de rezerva ca sa le ajunga intre vanatoare. Ataca-le satul din est, ia acele provizii, iar puterea lor va slabi. Sunt necesare sase saci de carne uscata rudimentar, pe care sa-i duci la Uthek, in Gelkis Village."}},faq={{q="Cine te trimite sa iei aceste provizii?",a="Uthek the Wise din Gelkis, in Desolace.",al={"cel care ofera misiunea","cine da misiunea Stealing Supplies","Uthek the Wise"}},{q="De ce vrea Uthek sa fie luata carnea celor din Magram?",a="Pentru Gelkis, carnea inseamna putere. Magram pastreaza provizii ca sa poata continua lupta intre vanatori, iar Uthek spune ca daca le-ai lua, i-ai slabi.",al={"de ce sa furi carne","mancarea din magram","motivul raidului pentru carne"}},{q="Unde sunt pastrate proviziile Magram?",a="In satul Magram, spre est.",al={"unde se afla Magram Village","unde sunt proviziile","locatia Magram"}},{q="De cata carne are nevoie Uthek?",a="Sase saci cu carne uscata grosolan, pe care Uthek the Wise ii colecteaza la Gelkis Village.",al={"cata carne","ce sa-i aduc lui Uthek"}}},fp="17,226,17.353.0,37.42.0,42.140.0,35.35.0,30.84.0"}
P.entries["quest:1371"] = {n="Gizmo for Warug",s="Warug, din Magram Village, isi aminteste de un Gnome care a venit candva in Desolace cu o caruta plina de lucruri ciudate. A pastrat un omulet din lemn din caruta pana l-a rupt, iar acum vrea unul nou: o tinta de antrenament avansata.",h="Warug, din Magram Village, isi aminteste de un Gnome care a venit candva in Desolace cu o caruta plina de...",kw={"centaur","desolace","gnome","magram","manechin de antrenament","warug"},sec={{t="Caruta Gnome",b="Cu mult timp in urma, un mic gnome a venit in Desolace cu cai si o caruta. In caruta se aflau lucruri ciudate: unele ardeau in culori diferite, altele se miscau desi nu erau vii. Warug l-a ucis pe gnome, dar mai intai acesta l-a facut sa rada. Warug a pastrat lucrul lui preferat din caruta: un om din lemn care ii facea cu mana pana cand l-a lovit si l-a rupt. Acum vrea unul nou, o tinta de antrenament avansata, si se asteapta s-o primeasca de la oricine nu este dusmanul celor din Magram."}},faq={{q="Cine este Warug?",a="Warug este un centaur Magram din Magram Village. Se asteapta ca cei cu care are de-a face sa ramana in gratiile clanului Magram.",al={"warug","cine ofera gizmo for warug"}},{q="Ce vrea Warug?",a="Un manechin de antrenament avansat, care sa inlocuiasca omul de lemn din caruta gnome-ului, pe care l-a stricat.",al={"de ce obiect are nevoie warug","obiectul-mecanism al lui warug"}},{q="De ce vrea Warug o tinta de antrenament?",a="Cu mult timp in urma, a ucis un gnome care venise in Desolace cu o caruta plina de lucruri ciudate si caraghioase. Gnome-ul l-a facut sa rada, iar Warug prefera o figurina de lemn infatisand un human, care ii facea semn cu mana pana cand a lovit-o si a rupt-o. Vrea una noua.",al={"de ce vrea warug o tinta de antrenament","motivul pentru tinta de antrenament a lui warug"}},{q="Ce preceda acest lucru in povestea Magram?",a="Urmeaza dupa Broken Tears, mai devreme in relatia ta cu Magram.",al={"lantul Gizmo for Warug","ce misiune precede Gizmo for Warug"}}},fp="15,215,16.457.0,13.121.0,21.90.0,35.231.0,43.66.0"}
P.entries["quest:1373"] = {n="Ongeku",s="Uthek the Wise din Gelkis spune ca mai ai multe de dovedit si ca deocamdata Gelkis se vor ocupa singuri de Magram. Pamantul i-a soptit lui Uthek despre draenethyst, iar tu esti trimis departe, in Swamp of Sorrows, dupa un fragment aflat la cel pierdut, Ongeku.",h="Uthek the Wise din Gelkis spune ca mai ai multe de dovedit si ca deocamdata Gelkis se vor ocupa singuri de...",kw={"desolace","draenethyst","gelkis","cel pierdut","magram","ongeku","swamp of sorrows","uthek the wise"},sec={{t="Un cristal de departe",b="Dupa Stealing Supplies, Uthek the Wise iti spune ca urmatoarea sarcina te asteapta departe. Cei care asculta aud multe secrete in pamant, iar unul dintre secretele aflate de Uthek priveste un cristal rosu numit draenethyst, sosit de curand pe aceste meleaguri dintr-un loc cu munti zburatori si demoni conducatori. O aschie din el va intari magia, spune Uthek. Cel pierdut, Ongeku, are o aschie in Swamp of Sorrows, in Eastern Kingdoms. Cand te intorci, Uthek va cauta dovezi ca Gelkis te mai pot numi prieten."}},faq={{q="Cine este Uthek the Wise?",a="Un centaur Gelkis din Gelkis Village, in Desolace, care spune ca pamantul isi sopteste secretele celor care-l asculta.",al={"uthek","batranul Gelkis","cel care ofera misiunea centaurilor"}},{q="Ce este draenethyst?",a="Un cristal rosu pe care Uthek il numeste nou pe pamantul nostru. Uthek spune ca provine dintr-un tinut al muntilor zburatori, stapanit de demoni.",al={"fragment de draenethyst","cristal rosu","ce este draenethyst"}},{q="Cine este Ongeku?",a="Un Lost One care tine un fragment de draenethyst in centrul Swamp of Sorrows, in Eastern Kingdoms.",al={"unde este ongeku","locatia lui ongeku","gaseste-l pe ongeku"}},{q="De ce vrea Uthek un fragment de draenethyst?",a="Uthek spune ca un fragment va intari magia.",al={"de ce sa obtii draenethyst","magia lui uthek"}},{q="Ce a fost inainte de asta?",a="Stealing Supplies, pe care ti l-a dat Uthek mai devreme.",al={"misiune precedenta","cerinta prealabila"}}},fp="6,274,23.525.0,22.107.0,20.119.0,14.101.0,40.46.0,22.48.0"}
P.entries["quest:1374"] = {n="Khan Jehn",s="Dupa ce-l urmezi pe Ongeku, Uthek the Wise iti spune ca pamantul arata ca Magram slabesc si ca a sosit ceasul sa le ucizi Khanul. Uthek vrea sa duci capul lui Khan Jehn la Gelkis Village.",h="Dupa ce-l urmezi pe Ongeku, Uthek the Wise iti spune ca pamantul arata ca Magram slabesc si ca a sosit ceasul...",kw={"centaur","desolace","gelkis","gelkis village","capul lui jehn","khan jehn","magram","uthek the wise"},sec={{t="Hanul Magram",b="Uthek the Wise din Gelkis Village spune ca pamantul ii vorbeste lui Uthek si ii dezvaluie ca Magram slabesc. Uthek il numeste pe Khan-ul lor, Jehn, drept tinta care trebuie doborata si iti cere capul lui Magram Khan. Uthek se asteapta sa fii in continuare prieten cu Gelkis cand te intorci."}},faq={{q="Cine este Khan Jehn?",a="Khanul centaurilor Magram.",al={"Khan Jehn","cine este Jehn","liderul Magram"}},{q="De ce vrea Uthek the Wise ca Khan Jehn sa moara?",a="Uthek spune ca pamantul ii da de inteles ca Magram slabesc, asa ca acum e momentul sa le omori Khan-ul.",al={"de ce sa-l ucizi pe jehn","motivul lui uthek","de ce sa-l ucizi pe khanul magram"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa Ongeku.",al={"ce precede Khan Jehn","ordinea seriei","misiunea anterioara"}},{q="Unde se afla Uthek the Wise?",a="In Gelkis Village, in Desolace.",al={"locatia lui uthek","unde este uthek"}}},fp="9,194,15.282.0,17.31.0,44.91.0,22.22.0,24.30.0"}
P.entries["quest:1375"] = {n="Khan Shaka",s="Warug din Magram, multumit de ajutorul tau dupa Gizmo for Warug, vrea acum capul lui Khan Shaka, Khan of the Gelkis. Vrea sa se uite la el si sa rada de dusmanul sau.",h="Warug din Magram, multumit de ajutorul tau dupa Gizmo for Warug, vrea acum capul lui Khan Shaka, Khan of the...",kw={"centaur","Desolace","Gelkis","capul lui Khan Shaka","Khan Shaka","Magram","Warug"},sec={{t="Un khan rival",b="In Magram Village, Warug iti spune ca i-ai ajutat pe Magram si ca te place. Acum vrea sa-l ucizi pe Khan Shaka, Khan of the Gelkis, si sa-i aduci capul. Spune ca vrea sa se holbeze la el si sa rada de el. Se asteapta sa ramai in relatii bune cu Magram."}},faq={{q="Cine este Khan Shaka?",a="Khan of the Gelkis, conducatorul clanului de centauri din Desolace, al carui cap il doreste Warug din Magram.",al={"povestea lui khan shaka","cine este shaka","centaurul shaka"}},{q="De ce il vrea Warug mort pe Khan Shaka?",a="Vrea capul lui Shaka ca sa se uite la el si sa rada de el.",al={"de ce sa-l ucizi pe shaka","razbunarea lui Warug impotriva lui shaka"}},{q="Unde este Warug?",a="In Magram Village, in Desolace.",al={"locatia lui khan shaka","unde se afla warug"}},{q="Ce a dus la asta?",a="Gizmo for Warug, dupa care Warug spune ca te place fiindca i-ai ajutat pe Magram.",al={"conditii prealabile pentru khan shaka","misiunea anterioara pentru shaka"}}},fp="10,172,12.273.0,18.86.0,36.61.0,15.30.0,20.76.0"}
P.entries["quest:138"] = {n="Captain Sanders' Hidden Treasure",s="In Westfall, Captain Sanders' Hidden Treasure te trimite spre interiorul tinutului dupa un indiciu gasit pe tarm. Poteca duce spre est, de la coasta catre un butoi de langa ruine de piatra.",h="In Westfall, Captain Sanders' Hidden Treasure te trimite spre interiorul tinutului dupa un indiciu gasit pe...",kw={"butoi spart","captain sanders","cos de fum","pirat","comoara lui sanders","vanatoare de comori","westfall"},ang={["class:Rogue"]="Ca Rogue, poti folosi furisarea si siretenia pentru a descifra cifrurile piratilor si a cauta prada uitata in ruine abandonate.",["faction:Alliance"]="Ca un calator din Alliance, poti urma traseul lui Sanders de-a lungul coastei fara lege din Westfall si pe drumurile neingrijite din interior, in timp ce militia locala se lupta cu proscrisii organizati."},sec={{t="Un sir de enigme din interiorul tinutului",b="Captain Sanders te trimite spre interior dupa ce este descifrat primul cifru. Indiciul te indeparteaza de tarm si te indreapta spre falezele stancoase, catre drumurile principale din Westfall."},{t="Ruine de-a lungul drumului",b="Un cos vechi de fum, printre ruinele de pe marginea drumului, marcheaza urmatoarea oprire. Un butoi abandonat din apropiere ascunde un alt mesaj, iar gospodaria in ruina ii ofera lui Sanders un reper pentru traseu."}},faq={{q="Cine a fost Captain Sanders?",a="Captain Sanders a fost un capitan pirat care naviga de-a lungul coastelor din Westfall. A imprastiat indicii si ghicitori prin regiune pentru oricine ii cauta bogatiile ascunse.",al={"povestea capitanului sanders","cine este sanders","piratul sanders"}},{q="Unde te trimite acest indiciu?",a="Indiciul te trimite spre est, venind de la marea din vest, pe deasupra stancilor si catre drum. Langa un cos vechi de piatra, printre ruine, un butoi spart ascunde urmatoarea piesa a puzzle-ului.",al={"unde merg","locatia indiciului","locatia hornului"}},{q="De ce si-a ascuns Sanders comoara in bucati?",a="Sanders a impartit indicatiile in mai multe ghicitori pentru a-i impiedica pe rivali si pe autoritati sa-i gaseasca averea ascunsa. Numai un cautator perseverent si descurcaret poate urma pista pana la ascunzatoarea finala.",al={"de ce indicii","de ce vanatoarea de comori"}},{q="Este periculos sa urmezi vanatoarea de comori?",a="Indiciile in sine sunt pergamente si recipiente vechi, dar drumurile si campurile din Westfall ascund pericole. Fiare ratacitoare, gnoll panditori si membri ostili ai Defias Brotherhood ii ameninta pe calatorii din apropierea gospodariilor parasite.",al={"este sigur","pericole in Westfall"}},{q="De ce fel de ruine este ascuns butoiul?",a="Butoiul se afla langa cosul de piatra darapanat al unei cladiri in ruina, aproape de drum. In ultimii ani de tulburari, multe gospodarii din Westfall au fost abandonate sau demolate.",al={"ruinele cosului","care cladire"}},{q="Dezvaluie aceasta misiune locul comorii?",a="Nu. Acest pas dezvaluie un alt indiciu. Sanders a raspandit mai multe etape prin regiune, inainte ca premiul propriu-zis sa poata fi gasit.",al={"este acesta cufarul final","primesc prada acum"}}},fp="32,170,25.157.0,20.170.0,24.159.0,30.174.0,44.197.0,41.227.0,45.174.0,43.123.0"}
P.entries["quest:1380"] = {n="Khan Hratha",s="Uthek the Wise isi aminteste cum i-ai ajutat pe Gelkis impotriva Magram, iar acum iti cere sa-i ataci pe Maraudine, ucigandu-l pe conducatorul clanului lor, Khan Hratha. Hratha are o bucata dintr-o cheie, iar Uthek vrea sa i-o aduci.",h="Uthek the Wise isi aminteste cum i-ai ajutat pe Gelkis impotriva Magram, iar acum iti cere sa-i ataci pe...",kw={"centaur","desolace","gelkis village","khan hratha","maraudine","maraudine war horn","uthek the wise","valley of spears"},sec={{t="Infruntandu-i pe Maraudine",b="Uthek the Wise spune ca Gelkis au acum nevoie de ajutor impotriva Maraudine. Maraudine War Horn se afla pe o stanca inalta din Valley of Spears, iar sunetul lui e folosit pentru a-l chema pe Khan Hratha. Totusi, cornul e inutil fara mustiucul unui corn de razboi, care e rar si se afla doar la centauri Maraudine de incredere. Cand rasuna cornul, sosesc mai multi centauri, iar Hratha vine ultimul."},{t="O bucata dintr-o cheie",b="Khan Hratha detine o bucata dintr-o cheie, iar Uthek vrea sa o duci la Gelkis Village."},{t="La intoarcerea ta",b="La intoarcerea ta, Uthek jubila ca Hratha e mort si ca Maraudine sunt condamnati. Jura ca Gelkis isi vor aminti de tine cand vor stapani acest tinut si ca spiritele pamantului iti vor canta numele pentru totdeauna."}},faq={{q="Cine te trimite sa te lupti cu Khan Hratha?",a="Uthek the Wise, din Gelkis Village, in Desolace, le cere acest lucru celor care i-au ajutat pe Gelkis.",al={"cine ofera khan hratha","cine da misiunea khan hratha","de unde il gasesc pe khan hratha"}},{q="Cum este atras Khan Hratha in lupta?",a="Uthek te indruma catre Maraudine War Horn din Valley of Spears, care trebuie sa fie sunat. Centaur raspund la chemare, iar Hratha vine dupa ei.",al={"locatia lui Khan Hratha","unde este Khan Hratha","gaseste-l pe Khan Hratha"}},{q="Cum sufli in Maraudine War Horn?",a="Cornul nu poate fi folosit fara o piesa de gura pentru corn de razboi, iar doar centaurii Maraudine de incredere au asemenea piese, si arareori.",al={"mustiuc de corn de razboi","cum folosesc Maraudine War Horn","sufla in Maraudine War Horn"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Khan Jehn. Uthek iti aminteste ca i-ai ajutat pe cei din Gelkis impotriva celor din Magram.",al={"conditii prealabile pentru Khan Hratha","ce misiune trebuie facuta inainte de Khan Hratha","lantul de misiuni Khan Hratha"}},{q="Ce tine Khan Hratha?",a="Khan Hratha are o bucata de cheie, pe care Uthek iti cere s-o aduci la el in Gelkis Village.",al={"obiect khan hratha","fragment de cheie maraudine","ce lasa hratha"}}},fp="11,223,25.369.0,16.81.0,14.204.1,35.91.0,40.131.0,39.105.0,23.86.0,27.91.0"}
P.entries["quest:1381"] = {n="Khan Hratha",s="Warug anunta moartea lui Khan dintre Gelkis si spune ca urmatorii sunt Maraudine. Warug te trimite dupa conducatorul lor, Hratha, si vrea bucata de cheie pe care acesta o poarta.",h="Warug anunta moartea lui Khan dintre Gelkis si spune ca urmatorii sunt Maraudine.",kw={"desolace","fragment de cheie","khan hratha","magram","maraudine","valley of spears","corn de razboi","warug"},sec={{t="Un corn pe promontoriu",b="Warug vrea ca Hratha, khanul Maraudine, sa moara. Un corn de pe o stanca din Valley of Spears il provoaca, dar nu va suna fara mustuc, iar acesta poate fi obtinut ucigand centauri Maraudine. Dupa ce cornul rasuna, centaurii Maraudine se aduna la turn, iar Hratha se arata in cele din urma."},{t="O bucata dintr-o cheie",b="Hratha detine o parte a unei chei, iar Warug vrea sa i-o aduci lui Warug in Magram Village. Warug asteapta sa-ti dovedesti ca esti un aliat al Magram."},{t="Stapanii Centaur",b="Dupa moartea lui Hratha, Warug proclama ca Magram sunt cei mai puternici dintre centauri, destinati sa-si zdrobeasca rivalii si sa conduca Desolace. Warug spune ca vei fi tinut minte si crutat cand restul vor fi calcati in picioare."}},faq={{q="Cine te trimite sa-l invingi pe Khan Hratha?",a="Warug, la Magram Village din Desolace, dupa moartea Gelkis Khan.",al={"cine ii da misiunea lui khan hratha","khan hratha, cel care da misiunea"}},{q="Cum ajungi la Khan Hratha?",a="Warug spune ca pentru a-l infrunta pe Hratha trebuie sa suni din corn pe povarnisul din Valley of Spears. Cornului ii trebuie un mustiuc, care poate fi obtinut omorand centauri Maraudine; apoi centaurii se aduna la turn inainte ca Hratha sa apara.",al={"cum sa-l invoci pe hratha","gaseste-l pe khan hratha","sufla in corn in Valley of Spears"}},{q="Unde apare Khan Hratha?",a="Hratha apare la turnul din Valley of Spears dupa ce se sufla in corn si sunt doborati centaurii Maraudine care se aduna acolo.",al={"locatia lui khan hratha","unde se afla hratha"}},{q="Ce tine Khan Hratha?",a="Hratha are o parte dintr-o cheie, iar Warug iti cere sa-i duci acea bucata.",al={"ce lasa hratha","fragmentul de cheie Maraudine"}}},fp="11,169,19.295.0,16.141.0,22.197.1,36.68.0,29.215.0,30.137.0,27.76.0"}
P.entries["quest:1382"] = {n="Strange Alliance",s="Capitanul Pentigast vede un noroc in faptul ca clanurile de centauri din Desolace se lupta intre ele, fiindca unite n-ar putea fi oprite. Gelkis sunt prinsi intr-un razboi crunt cu Magram, asa ca Pentigast te trimite la Uthek the Wise, in sud-vestul Desolace, sa cauti o alianta.",h="Capitanul Pentigast vede un noroc in faptul ca clanurile de centauri din Desolace se lupta intre ele, fiindca...",kw={"centaur","desolace","gelkis","magram","pentigast","strange alliance","uthek"},sec={{t="Clanuri dezbinate",b="Captain Pentigast considera un noroc faptul ca clanurile centaurilor se razboiesc intre ele, caci unite, nu ar putea fi oprite. Pentigast vrea sa profite de acest avantaj. Gelkis si Magram sunt prinse intr-un razboi crunt, asa ca un atac asupra Magram ar putea castiga bunavointa Gelkis."},{t="In cautarea lui Uthek",b="Uthek the Wise poate fi gasita acolo unde incep taberele Gelkis, in sud-vestul regiunii Desolace, iar prin intermediul ei s-ar putea incheia o alianta. La inceput te alunga, spunandu-ti sa pleci si sa te intorci dupa ce ai ucis multi Magram."},{t="Raspunsul lui Uthek",b="Dupa ce ai doborat destui Magram, Uthek spune ca Gelkis iti soptesc acum numele si isi exprima aprobarea. Este dispusa sa discute despre ce poti oferi clanului si ce iti poate oferi acesta."}},faq={{q="Cine te trimite sa iei legatura cu Gelkis?",a="Captain Pentigast, care spera ca se va putea incheia o alianta cu clanul Gelkis.",al={"cine da Strange Alliance","cel care ofera misiunea Strange Alliance","cine incepe Strange Alliance"}},{q="Unde se afla Uthek the Wise?",a="Unde incep taberele Gelkis, in sud-vestul tinutului Desolace.",al={"locatia lui uthek","gaseste-l pe uthek the wise","unde este uthek"}},{q="De ce nu vorbeste Uthek the Wise cu nou-venitii imediat?",a="Iti spune sa pleci si sa te intorci dupa ce omori multi Magram.",al={"de ce este uthek ostil","uthek nu vrea sa vorbeasca","cum sa vorbesti cu uthek"}},{q="De ce vrea Alliance un pact cu Gelkis?",a="Captain Pentigast isi da seama ca, daca clanurile de centauri s-ar uni, n-ar putea fi oprite, asa ca disputele lor sunt o binecuvantare. Gelkis sunt in razboi cu Magram, asa ca un atac asupra Magram ar putea castiga prietenia celor din Gelkis.",al={"de ce sa te aliezi cu gelkis","motivul aliantei cu centaurii","de ce clanul gelkis"}}},fp="16,272,13.266.0,13.223.0,14.185.1,36.76.0,32.59.0,57.63.0,50.210.0"}
P.entries["quest:1384"] = {n="Raid on the Kolkar",s="Dupa Strange Alliance, Uthek the Wise te trimite impotriva centaurilor Kolkar din nord-est. Omoara-i, ia-le amuletele si adu-i lui Uthek zece dintre ele.",h="Dupa Strange Alliance, Uthek the Wise te trimite impotriva centaurilor Kolkar din nord-est.",kw={"centaur","talismane rudimentare","desolace","gelkis","kolkar","uthek"},sec={{t="Dispret fata de magia Kolkar",b="Uthek isi bate joc de centaurii Kolkar pentru ca isi cred magia puternica; dupa parerea lui Uthek, nu stiu nimic despre magie. Mergi spre nord-est, ii omori pe Kolkar si le iei amuletele. Uthek vrea zece Crude Charms pe care sa le arunce in foc, razand in timp ce ard."},{t="Verdictul lui Uthek",b="Uthek lauda fapta, spunand ca a fost un lucru bun pentru Gelkis. Kolkar sunt slabi si sortiti pieirii, spune Uthek, iar magia lor nu-i va salva. Dupa ce ti-au vazut isprava, se vor teme si mai mult, iar frica ii slabeste. Pe pamanturile Gelkis, cei slabi mor repede."}},faq={{q="Cine este Uthek the Wise?",a="Uthek the Wise te asteapta in Gelkis Village, in Desolace. Uthek vrea talismanele Kolkar.",al={"cine ofera Raid on the Kolkar","Uthek","povestea lui Uthek the Wise"}},{q="Unde se afla Kolkar?",a="Spre nord-est, potrivit lui Uthek.",al={"unde sa gasesti kolkar","locatia kolkar in desolace"}},{q="Ce sunt talismanele rudimentare?",a="Talismane luate de la Kolkar. Uthek vrea zece dintre ele, ca sa le arunce in foc si sa rada.",al={"amuleta rudimentara","amuleta kolkar"}},{q="Cum se incadreaza aceasta in lantul de misiuni Gelkis?",a="Urmeaza dupa Strange Alliance.",al={"lantul gelkis","ce urmeaza inainte de Raid on the Kolkar"}}},fp="18,169,25.252.0,15.253.1,22.84.0,29.37.0,26.85.0,40.28.0"}
P.entries["quest:1385"] = {n="Brutal Politics",s="Captain Pentigast crede ca oricare clan centaur care va castiga razboaiele din Desolace se va revarsa asupra fortaretelor Alliance si le va ameninta. Pentru a afla cum sa-i invinga, Pentigast vrea o alianta cu un clan: lupta impotriva Gelkis, castiga increderea celor din Magram si vorbeste cu Warug.",h="Captain Pentigast crede ca oricare clan centaur care va castiga razboaiele din Desolace se va revarsa asupra...",kw={"brutal politics","centaur","desolace","gelkis","magram","pentigast","warug"},sec={{t="Un taram aflat in razboi",b="Razboiul face ravagii in Desolace, centaurii luptand impotriva centaurilor, iar Alliance crede ca invingatorii isi vor revarsa fortele asupra fortaretelor sale. Acest lucru nu poate fi ingaduit. Pentru a afla cum pot invinge centaurii, spune Captain Pentigast, Alliance are nevoie de unul dintre clanuri ca aliat."},{t="Magram",b="Magram se lupta cu Gelkis, asa ca un atac asupra Gelkis i-ar putea face pe Magram sa ia in calcul o alianta. Castiga-le bunavointa, apoi mergi la Warug, in satul Magram, in sud-estul regiunii Desolace. Warug te avertizeaza ca, pentru a fi prieten cu Magram, trebuie sa-i ucizi pe Gelkis."}},faq={{q="De ce doreste Alliance o alianta cu un clan centaur?",a="Captain Pentigast crede ca tribul care va invinge in razboaiele centaurilor se va napusti asupra fortaretelor Alliance si le va ameninta. Pentru a afla cum ii poate invinge, Alliance are nevoie de unul dintre clanuri ca aliat.",al={"de ce sa ne aliem cu Magram","planul lui pentigast","motivul aliantei cu centaurii"}},{q="Cum castigi bunavointa celor din Magram?",a="Magram sunt in razboi cu Gelkis, iar lupta impotriva celor din Gelkis i-ar putea face sa ia in considerare o alianta. Warug spune ca, pentru a fi prietenul celor din Magram, trebuie sa-i ucizi pe Gelkis.",al={"cum obtin reputatie cu magram","cum devin prietenos cu magram","uciderea celor din gelkis"}},{q="Unde este Warug?",a="In satul Magram, in sud-estul regiunii Desolace.",al={"locatia lui warug","unde este warug","contactul Magram"}}},fp="15,260,13.260.0,10.247.0,59.183.0,40.166.0,15.47.0"}
P.entries["quest:1386"] = {n="Assault on the Kolkar",s="Dupa Brutal Politics, Warug din Magram Village vrea sa dovedesti ca poti ucide Kolkar asa cum o fac cei din Magram. Indreapta-te spre nord si ucide centauri, cercetasi si batausi Kolkar.",h="Dupa Brutal Politics, Warug din Magram Village vrea sa dovedesti ca poti ucide Kolkar asa cum o fac cei din...",kw={"brutal politics","centaur","desolace","kolkar","magram","magram village","warug"},sec={{t="Radem si ucidem",b="Warug isi bate joc de Kolkar, care se cred puternici, in timp ce Magram rad de ei pe cand ii omoara. Warug vrea sa dovedesti ca poti ucide Kolkar la fel ca Magram, asa ca mergi spre nord: trebuie sa dobori doisprezece centauri Kolkar, doisprezece cercetasi si sase zdrobitori."},{t="Aprobarea lui Warug",b="Cand te intorci, Warug spune ca acum Kolkar se tem de tine. Warug spera ca ai ras in timp ce-i omorai, fiindca rasul in timp ce ucizi ii arata dusmanului propria slabiciune."}},faq={{q="Cine te trimite sa ataci Kolkar?",a="Warug, din Magram, in Magram Village, in Desolace.",al={"cine ofera misiunea assault on the kolkar","cel care ofera misiunea assault on the kolkar","unde se ia misiunea assault on the kolkar"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza dupa Brutal Politics.",al={"misiunea anterioara","cerinta pentru Assault on the Kolkar","cerinta preliminara pentru Assault on the Kolkar"}},{q="Unde se afla Kolkar?",a="Warug iti spune sa mergi spre nord pentru a-i gasi.",al={"locatia kolkar","unde sunt centaurii kolkar","unde gasesc kolkar"}},{q="De ce vrea Warug ca Kolkar sa fie ucisi?",a="Warug isi bate joc de Kolkar fiindca se cred puternici si vrea sa-i arati ca-i poti ucide asa cum fac Magram.",al={"de ce sa omori kolkar","rivalitatea dintre magram si kolkar","de ce il uraste warug pe kolkar"}}},fp="21,163,20.253.0,16.165.1,35.52.0,27.27.0,29.43.0,38.112.0"}
P.entries["quest:1387"] = {n="Centaur Bounty",s="Corporal Melkins din Nijel's Point spune ca toate clanurile centaur din Desolace au o trasatura comuna, cruzimea, si ca nu va fi pace cat timp centaurii raman. Melkins iti cere sa-i vanezi prin tinut si sa aduci cincisprezece urechi.",h="Corporal Melkins din Nijel's Point spune ca toate clanurile centaur din Desolace au o trasatura comuna...",kw={"alliance","recompensa","centaur","ureche de centaur","corporal melkins","desolace","urechi","nijel's point"},sec={{t="Un lucru in comun",b="La Nijel's Point, Corporal Melkins descrie o rasa de centauri impartita in numeroase clanuri, fiecare cu un lider si propriile planuri, dar toate la fel de crude. Pacea, spune Melkins, va veni numai daca centaurii sunt indepartati."},{t="Urechi pentru Alliance",b="Ratacind prin Desolace, vanezi centaur si le iei urechile. Melkins vrea foarte multe, cincisprezece in total, si numeste aceasta munca un serviciu pentru Alliance, care apropie sfarsitul razboiului."}},faq={{q="Cine ofera recompensa pentru centaur?",a="Corporal Melkins, stationat la Nijel's Point, in Desolace.",al={"misiunea de vanatoare de centauri","cine ofera vanatoarea de centauri","vanatoarea lui Melkins"}},{q="De ce vrea Corporal Melkins sa fie ucis centaurul?",a="Melkins spune ca clanurile se deosebesc prin conducatori si scopuri, dar sunt toate crude, si ca pacea este imposibila cat timp centaurii raman aici.",al={"de ce ucizi centaur","motivul lui melkins","de ce urechi de centaur"}},{q="Ce iti cere Corporal Melkins sa aduci?",a="Cincisprezece urechi de centaur, luate de la centaur pe care ii vanezi in timp ce ratacesti prin Desolace.",al={"ce trebuie colectat","obiecte pentru recompensa de centaur","trofeu pentru recompensa de centaur"}},{q="Ce clanuri de centauri trebuie vanate?",a="Melkins nu numeste niciun clan anume, spunand ca toate clanurile sunt la fel de crude, si iti cere doar sa vanezi centauri in Desolace.",al={"care centauri","clanul centaurilor vizat","ce clan trebuie vanat pentru urechi"}}},fp="14,230,19.211.0,21.180.0,37.57.0,50.123.0,44.75.0,38.114.0"}
P.entries["quest:1389"] = {n="Draenethyst Crystals",s="Magtoor, din Harborage, cere sase cristale draenethyst, sacre pentru poporul lui Magtoor si furate de Lost Ones din Fallow Sanctuary. Fara ele, oamenii lui Magtoor se tem ca si ei isi vor pierde calea.",h="Magtoor, din Harborage, cere sase cristale draenethyst, sacre pentru poporul lui Magtoor si furate de Lost...",kw={"draenethyst","fallow sanctuary","harborage","lost ones","magtoor","swamp of sorrows"},sec={{t="Lost Ones",b="Lost Ones din Fallow Sanctuary seamana cu oamenii lui Magtoor, dar greutatile calatoriei spre Azeroth i-au innebunit. Odinioara frati, acum traiesc in Sanctuary, la est, si ii rapesc sau ii ucid pe toti cei care se apropie. Au furat si ceva sacru: cristale draenethyst."},{t="Fara cristale",b="Oamenii lui Magtoor nu au puterea sa intre in Fallow Sanctuary si sa recupereze draenethyst-ul dintre colibe si focurile de tabara. Fara cristale, se tem ca si ei s-ar putea rataci. Magtoor iti cere sa aduci inapoi sase."}},faq={{q="Cine cere cristalele draenethyst?",a="Magtoor, care se afla in Harborage.",al={"cine ofera Draenethyst Crystals","misiunea lui Magtoor","cine doreste draenethyst"}},{q="De ce sunt cristalele draenethyst importante pentru Magtoor?",a="Sunt sacre pentru poporul lui Magtoor. Fara ele, Magtoor se teme ca si ei isi vor pierde calea.",al={"la ce folosesc cristalele draenethyst","ce fac cristalele draenethyst","scopul draenethyst"}},{q="Cine a luat cristalele?",a="lost ones din Fallow Sanctuary, la est. Odinioara, erau fratii lui Magtoor, pana cand greutatile calatoriei spre Azeroth i-au facut sa-si piarda mintile.",al={"cine a furat Draenethyst","cine are cristalele","dusmanii din Fallow Sanctuary"}},{q="Unde pot fi gasite cristalele?",a="Printre colibele si focurile de tabara din Fallow Sanctuary, aflat la est.",al={"locatia cristalelor draenethyst","unde sunt cristalele draenethyst","gaseste draenethyst"}},{q="De ce nu-si pot recupera singuri oamenii lui Magtoor obiectele?",a="Nu au puterea sa intre in Sanctuary si sa ia cristalele inapoi.",al={"de ce nu lupta magtoor","de ce sa-l ajut pe magtoor"}}},fp="20,206,13.294.0,20.233.0,43.39.0,54.93.0,22.145.0,32.77.0,52.80.0"}
P.entries["quest:139"] = {n="Captain Sanders' Hidden Treasure",s="Un butoi spart de pe tarmul vestic al Westfallului ascunde indiciul pentru Captain Sanders' Hidden Treasure. Acesta te trimite spre nord, catre un ulcior vechi de langa o moara de vant de pe coasta, inca un pas pe urmele piratului raposat si spre bogatiile sale ascunse.",h="Un butoi spart de pe tarmul vestic al Westfallului ascunde indiciul pentru Captain Sanders' Hidden Treasure.",kw={"stanci","butoi spart","capitanul sanders","comoara ascunsa","ulcior vechi","indiciu de pirat","westfall","moara de vant"},ang={["class:Rogue"]="Ca Rogue, urmarirea traseului unui ticalos, marcat de mesaje ascunse si semne camuflate de-a lungul povarnisurilor, ti s-ar putea parea cunoscuta.",["faction:Alliance"]="In timp ce Westfall este napadit de foamete si de proscrisii Defias, prada pierduta a piratilor lui Sanders iti ofera un castig neasteptat."},sec={{t="Firimiturile lasate de un pirat",b="Captain Sanders si-a raspandit indicatiile de-a lungul tarmului vestic din Westfall. Fiecare indiciu duce doar la urmatorul recipient, niciodata direct la comoara. Trebuie sa urmezi traseul de la un butoi, cufar sau ulcior la altul, traversand povarnisurile, pentru a ajunge la prada sa."},{t="Spre nord, catre stanci",b="Din butoiul spart, pergamentul indica nordul, spre falezele de la mare. Langa o moara de vant izolata de pe stanci, un ulcior abandonat ascunde urmatorul indiciu. Murloc si cautatorii Defias de prada umbla pe coasta din Westfall, asa ca drumul spre nord este primejdios."}},faq={{q="Ce este Captain Sanders' Hidden Treasure?",a="Captain Sanders era un corsar care si-a ascuns bogatiile de-a lungul coastei din Westfall. In loc sa lase o harta, a scris ghicitori si le-a ascuns in butoaie, cufere si carafe prin tinut.",al={"comoara lui sanders","despre ce este aceasta misiune","cine este sanders"}},{q="Unde duce acest al treilea indiciu?",a="Pergamentul arata drept spre nord, de la butoiul spart catre falezele oceanului. Langa o moara de vant singuratica, un ulcior vechi ascunde urmatorul indiciu.",al={"incotro sa merg","locatia ulciorului","unde este moara de vant"}},{q="De ce si-a ascuns Sanders indicatiile in mai multe bucati?",a="Sanders si-a impartit indicatiile pentru a-si proteja comoara de echipajul razvratit si de marauderii rivali. Gasirea unui singur indiciu nu ar dezvalui intregul traseu.",al={"de ce indicii","de ce nu o harta completa"}},{q="Pot jucatorii Horde parcurge acest traseu?",a="Da. Orice aventurier poate interactiona cu indiciile si obiectele legate de ascunzatoarea lui Captain Sanders, desi Westfall se afla adanc in teritoriul Alliance.",al={"este doar pentru Alianta","comoara lui Sanders pentru hoarda"}},{q="Indiciul acesta dezvaluie direct locatia cufarului?",a="Nu. Ulciorul de langa moara de vant de pe coasta ascunde un alt indiciu care duce la cufarul lui Sanders, fiind astfel penultimul pas al cautarii.",al={"este comoara in ulcior","pasul final"}},{q="Ce pericole pandesc de-a lungul potecii spre moara de vant?",a="Gnoll-ii Riverpaw, murlocii de coasta si banditii Defias aflati in pribegie pandesc pe falezele si plajele din vestul Westfall. Un mars direct spre nord poate fi primejdios.",al={"pericole pe stanci","ce inamici sunt acolo"}}},fx={["03354d32"]={q="De ce este indiciul ascuns intr-un butoi spart?",a="Butoiul in sine nu are vointa proprie si nici interese personale - este doar un punct de predare inert, lasat pe coasta din Westfall. Captain Sanders si-a ascuns intentionat ghicitorile in resturi de lemn aduse de valuri si in moloz neinsemnat, pentru ca jefuitorii de ocazie si ticalosii rivali sa nu poata descifra intregul drum spre cufarul sau.",al={"de ce butoiul spart","de ce e biletul intr-un butoi","butoiul spart al lui Sanders"}}},fp="32,217,27.256.0,23.244.0,41.170.0,32.128.0,46.154.0,38.140.0,41.130.0,48.147.0"}
P.entries["quest:1392"] = {n="Noboru the Cudgel",s="De luni intregi, Noboru i-a chinuit pe Draenei din Harborage. Buzduganul lui Noboru este un simbol al cruzimii pe care Lost Ones le-au aratat-o, iar ti se cere sa-l duci conducatorului din Harborage.",h="De luni intregi, Noboru i-a chinuit pe Draenei din Harborage.",kw={"buzdugan","Draenei","Harborage","Lost Ones","Magtoor","Noboru","Swamp of Sorrows"},sec={{t="Un simbol al brutalitatii",b="Noboru i-a chinuit luni intregi pe Draenei din Harborage. Ghioaga a ajuns sa reprezinte cruzimea pe care Lost Ones le-au aratat-o. Cu ea in mana, o duci la liderul din Harborage."},{t="Bun venit din partea lui Magtoor",b="Magtoor intreaba daca arma inseamna ca Noboru a murit si spune ca acolo e o zi de bucurie. Noboru si banda lui i-au terorizat pe Draenei, ratacind prin mlastini si ucigandu-i pe toti cei care le ieseau in cale. Noboru le ameninta insasi supravietuirea, iar ei nu aveau puterea sa-l infrunte."}},faq={{q="Cine este Noboru?",a="Unul dintre Lost Ones, care ii chinuie de luni intregi pe Draenei din Harborage.",al={"cine este noboru","povestea lui noboru","noboru, tipul cu maciuca"}},{q="De ce vrea Harborage maciuca lui Noboru?",a="Ghioaga simbolizeaza cruzimea pe care Lost Ones au abatut-o asupra Draenei din Harborage.",al={"de ce predau ghioaga","scopul ghioagei lui Noboru","de ce duc ghioaga la Magtoor"}},{q="Cine primeste ghioaga?",a="Magtoor, care conduce Harborage.",al={"cine este magtoor","unde ajunge ghioaga"}},{q="Unde se afla Harborage?",a="In Swamp of Sorrows, unde traiesc Draenei din Harborage.",al={"unde se afla harborage","locatia harborage"}}},fp="17,203,21.194.0,17.274.1,14.75.0,44.93.0,24.33.0,31.65.0"}
P.entries["quest:1393"] = {n="Galen's Escape",s="Galen Goodward se afla in Fallow Sanctuary si implora sa fie salvat de creaturile de acolo, promitand o comoara mare oricui il va scoate. Aceasta il asteapta intr-o caseta de valori incuiata, in tabara lui de la nord de Stonard.",h="Galen Goodward se afla in Fallow Sanctuary si implora sa fie salvat de creaturile de acolo, promitand o...",kw={"rasina neagra","fallow sanctuary","galen goodward","galen's escape","stonard","lada de valori","swamp of sorrows"},sec={{t="Un apel pentru salvare",b="Galen Goodward striga ca fapturile din jurul lui urmeaza sa-l manance. Oricui il scoate din primejdie ii promite o comoara nepretuita. Aceasta se afla in tabara lui, in mlastina de la nord de Stonard, inchisa intr-o lada ferecata care poate fi deschisa doar printr-un truc cunoscut numai de Galen. Daca il ajuti sa scape, te va invata si pe tine."},{t="La lada de valori",b="In tabara, gasesti gaura cheii de la lada incuiata umpluta cu rasina neagra, asa ca nu o poti deschide pe acolo. Dar Galen ti-a vorbit despre un zavor ascuns pe fundul lazii. O cautare rapida il da la iveala, iar cand il rasucesti, lada se deschide."}},faq={{q="Cine este Galen Goodward?",a="O persoana tinuta captiva in Fallow Sanctuary, care se teme ca vietatile de acolo o vor manca si care ofera o comoara grozava oricui o ajuta sa evadeze.",al={"cine este galen","povestea lui galen goodward","tipul care a scapat de galen"}},{q="Unde se afla tabara lui Galen?",a="In mlastina de la nord de Stonard, in Swamp of Sorrows.",al={"unde este tabara lui galen","locatia cufarului lui galen","unde este cufarul"}},{q="De ce nu poate fi deschisa caseta de valori in mod obisnuit?",a="Comoara lui Galen este incuiata intr-o caseta de valori care se deschide doar printr-un truc stiut numai de Galen, pe care il va invata pe oricine il ajuta sa evadeze.",al={"cum sa deschizi cufarul incuiat","cheia cufarului lui galen"}}},fp="14,206,17.322.0,16.227.1,22.146.0,30.55.0,51.149.0"}
P.entries["quest:1394"] = {n="Final Passage",s="Parqual Fintallas iti spune ca ai trecut aceasta incercare si pe cele de dinainte. Esti trimis inapoi la Dorn Plainstalker, in Thousand Needles, care va simti schimbarea din tine si va vedea daca ai devenit mai puternic la minte, la trup si la spirit, indeajuns incat eforturile tale sa fie rasplatite cu o onoare.",h="Parqual Fintallas iti spune ca ai trecut aceasta incercare si pe cele de dinainte.",kw={"dorn plainstalker","pasajul final","freewind post","parqual fintallas","incercarea credintei","test of lore","thousand needles","weathered nook"},ang={["faction:Horde"]="Aceasta serie de incercari este destinata lui Horde si se incheie cu Dorn Plainstalker."},sec={{t="Inapoi la Weathered Nook",b="Acesta este ultimul pas al Test of Faith, lantul de incercari inceput de Dorn Plainstalker. Dorn te asteapta in Weathered Nook, intr-o pestera la care se ajunge pe o rampa, la nord de Freewind Post. Parqual Fintallas te indeamna sa ramai fidel echilibrului pe care l-ai dovedit de-a lungul acestor incercari."},{t="Bun venit din partea lui Dorn",b="Dorn remarca faptul ca ai lipsit mult timp de la casa lui si ca au trecut multe luni de cand primul tau salt te-a pornit pe aceasta cale. Te gaseste mai puternic si mai luminat decat inainte, lucru care-l bucura, si spune ca meriti sa fii onorat pentru ca i-ai dus incercarile pana la capat."}},faq={{q="Cine te trimite sa faci acest ultim pas?",a="Parqual Fintallas, care iti spune ca ai trecut testul lui, precum si testele dinaintea acestuia.",al={"cel care ofera misiunea","cine incepe Final Passage","Parqual Fintallas"}},{q="Unde merg mai departe?",a="Inapoi la Dorn Plainstalker, in Thousand Needles. Te asteapta in Weathered Nook, intr-o pestera la care se ajunge pe o rampa, la nord de Freewind Post.",al={"unde se afla dorn","unde predau","locatia lui dorn plainstalker","locatia lui weathered nook"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Test of Lore, o incercare anterioara din acelasi lant.",al={"misiunea precedenta","cerinta preliminara","ce duce la trecerea finala"}},{q="Care a fost primul pas al acestei calatorii?",a="Test of Faith, oferita de Dorn Plainstalker in Weathered Nook. Acesta este ultimul pas din acest lant.",al={"prima misiune","de unde a inceput","lantul Test of Faith"}},{q="De ce te trimite Parqual inapoi la Dorn?",a="Parqual spune ca Dorn va observa schimbarea din tine si va considera ca mintea, trupul si spiritul tau sunt suficient de puternice pentru a merita onoare.",al={"de ce Dorn","motivul lui Parqual"}}},fp="13,279,26.276.0,14.279.1,33.88.0,19.131.0,23.60.0,45.102.0,39.116.0"}
P.entries["quest:1396"] = {n="Encroaching Wildlife",s="Watcher Biggs se indrepta spre coasta de est cu o caravana cand au atacat lost ones. Doar Biggs a supravietuit, iar acum creaturi salbatice dau tarcoale taberei. Biggs iti cere ajutorul ca sa o aperi. Aceasta continua misiunea Help Watcher Biggs.",h="Watcher Biggs se indrepta spre coasta de est cu o caravana cand au atacat lost ones.",kw={"convoi","lost ones","sawtooth crocolisk","sorrow spinner","provizii","jaguar de mlastina","swamp of sorrows","watcher biggs"},sec={{t="O tabara sub supraveghere",b="Caravana lui Watcher Biggs se indrepta spre coasta de est, dar nu a mai ajuns la destinatie. Lost Ones au atacat, au ucis garzile si au distrus proviziile, iar Biggs a fost singurul supravietuitor. Biggs a jurat sa protejeze proviziile ramase, insa creaturi salbatice dau tarcoale taberei. Biggs vrea sa-l ajuti sa o apere."},{t="Creaturile din apropiere",b="Biggs numeste trei feluri de creaturi care ameninta tabara: crocolisks cu dinti ca fierastraul, inca tineri, sorrow spinners si jaguari de mlastina. Trebuie ucisi opt crocolisks, zece spinners si zece jaguari."}},faq={{q="Incotro se indrepta caravana lui Watcher Biggs?",a="Spre coasta de est, dar caravana nu si-a atins niciodata destinatia.",al={"incotro se indrepta biggs","destinatia caravanei","traseul caravanei lui biggs"}},{q="Cine a atacat caravana lui Watcher Biggs?",a="Lost Ones. Au ucis garzile si au distrus proviziile; numai Biggs a supravietuit.",al={"cine l-a atacat pe biggs","cine a distrus caravana","ambuscada caravanei"}},{q="Ce bestii ameninta tabara?",a="Puii de crocodil sawtooth, sorrow spinnerii si jaguarii de mlastina pandesc in apropiere.",al={"ce bestii inainteaza","ce animale il ataca pe Biggs","bestii din mlastina"}},{q="De ce ramane Watcher Biggs in tabara?",a="Biggs a jurat sa protejeze proviziile ramase din convoi.",al={"de ce ramane biggs","de ce nu fuge","proviziile lui biggs"}}},fp="20,227,18.303.0,20.185.0,44.61.0,37.85.0,30.75.0,42.69.0"}
P.entries["quest:1398"] = {n="Driftwood",s="Dupa The Lost Caravan, Watcher Biggs mai are de reparat o caruta inainte sa ajunga la Nethergarde. Biggs are nevoie de lemn rezistent si uscat si te trimite spre est, pe coasta, sa cauti lemn adus de ape si uscat la soare.",h="Dupa The Lost Caravan, Watcher Biggs mai are de reparat o caruta inainte sa ajunga la Nethergarde.",kw={"lemn plutitor","Nethergarde","lemn plutitor uscat la soare","Swamp of Sorrows","caruta","Watcher Biggs"},sec={{t="Lemn pentru caruta",b="Watcher Biggs spune ca ti se cuvin multe multumiri si iti cere din nou ajutorul. Daca Biggs vrea vreodata sa ajunga in Nethergarde, caruta trebuie reparata, iar pentru asta e nevoie de lemn tare si uscat. Lemnul copacilor din mlastina e spongios si incurcat si nu va fi bun."},{t="Driftwood de pe coasta",b="Biggs te trimite spre est, catre coasta, sa cauti lemn plutitor uscat de soare. Trebuie sa-i aduci lui Biggs opt bucati in Swamp of Sorrows."}},faq={{q="De ce are nevoie Watcher Biggs de lemn?",a="Caruta trebuie reparata daca Biggs vrea sa ajunga vreodata la Nethergarde, iar lemnul copacilor din mlastina este prea moale si incurcat.",al={"motivul lemnelor plutitoare","de ce are biggs nevoie de lemne plutitoare","de ce lemne plutitoare"}},{q="Unde te trimite Watcher Biggs sa iei lemnul?",a="Spre est, catre coasta, in cautarea lemnului adus de ape si uscat de soare.",al={"locatia lemnelor plutitoare","unde gasesti lemne plutitoare","unde se afla lemnul"}},{q="Ce a fost inainte de asta?",a="The Lost Caravan vine prima, iar apoi Biggs cere ajutor suplimentar.",al={"misiunea precedenta driftwood","ce duce la driftwood","ce misiune vine inainte de driftwood"}},{q="De cata lemne aduse de apa este nevoie?",a="Opt bucati de lemn plutitor uscat la soare.",al={"cantitatea de lemn plutitor","cat lemn plutitor"}},{q="Ce urmeaza dupa strangerea lemnului adus de apa?",a="Deliver the Shipment urmeaza.",al={"continuarea lui driftwood","ce urmeaza dupa driftwood","urmatoarea misiune driftwood"}}},fp="9,196,18.244.0,24.152.0,33.121.0,47.66.0,22.64.0,29.35.0,41.29.0"}
P.entries["quest:14"] = {n="The People's Militia",s="Aceasta sarcina marcheaza punctul culminant al campaniei lui Gryan Stoutmantle de a curata drumurile si fermele din Westfall de Defias Brotherhood. Vanand banditii incercati, inradacinati in sudul Dagger Hills, voluntarii isi dovedesc devotamentul si sunt primiti cu drepturi depline in People's Militia din Sentinel Hill.",h="Aceasta sarcina marcheaza punctul culminant al campaniei lui Gryan Stoutmantle de a curata drumurile si...",kw={"dagger hills","defias highwayman","defias knuckleduster","defias pathstalker","gryan stoutmantle","people's militia","sentinel hill","westfall"},ang={["class:Paladin"]="Stoutmantle invoca binecuvantarea Light asupra celor primiti, reflectand idealurile sacre ale dreptatii si apararii celor lipsiti de aparare impotriva talharilor pradatori.",["faction:Alliance"]="Incapacitatea lui Stormwind de a proteja Westfall ii sileste pe oamenii de rand ai Alliance sa-si verse propriul sange pentru a mentine ordinea in tinutul natal.",["race:Human"]="Pentru oamenii din Stormwind, aceasta misiune inseamna sa le tina piept in numele compatriotilor uitati, ale caror mijloace de trai au fost abandonate de elita politica a capitalei."},sec={{t="Curatarea Dagger Hills",b="Tinuturile agricole din nordul Westfall au avut mult de suferit din pricina Defias Brotherhood, dar proscrisii care au scapat de primele raiduri ale lui Stoutmantle s-au retras spre sud, printre crestele stancoase din Dagger Hills. Folosindu-se de terenul accidentat, talharii de drumul mare, iscoadele si batausii Defias au continuat sa atace gospodariile rurale si sa intercepteze calatorii. Pentru a le zdrobi controlul asupra jumatatii sudice a regiunii, People's Militia trimite recruti incercati in dealuri, ca sa desfiinteze direct aceste bande de prazi."},{t="Cruciada lui Stoutmantle",b="Gryan Stoutmantle a infiintat People's Militia dupa ce s-a intors acasa din luptele impotriva Scourge in Lordaeron, doar ca sa descopere ca garnizoana regala din Stormwind abandonase Westfall cu totul. In fata unui sindicat criminal necontrolat si a fermierilor infometati, alungati de pe pamanturile lor, el a organizat voluntari locali pentru a pune mana pe arme. Indeplinirea completa a acestui ultim nivel de patrulare le aduce aventurierilor primirea oficiala in militie, cu binecuvantarea lui Stoutmantle in Light, pe masura ce lupta impotriva Fratiei se inaspreste."}},faq={{q="Unde se afla Dagger Hills?",a="Dagger Hills se afla in sudul Westfallului, la sud-vest de Sentinel Hill. Crestele accidentate si intrarile in mine parasite de acolo le servesc luptatorilor mai puternici din Defias Brotherhood drept baza de operatiuni si reduta.",al={"locatia Dagger Hills","unde gasesti Dagger Hills","unde sunt talharii de drumul mare"}},{q="De ce lupta People's Militia singura impotriva Defias?",a="Cu regele Varian Wrynn disparut si resursele insuficiente, House of Nobles din Stormwind refuza sa trimita armata regala sa apere Westfall rural. Gryan Stoutmantle si fermierii din zona n-au avut de ales decat sa-si formeze propria forta de voluntari pentru a-si apara casele.",al={"de ce nu sunt garzi din Stormwind","unde este armata din Stormwind","de ce este Westfall parasit"}},{q="Ce se obtine prin indeplinirea acestei sarcini?",a="Eliminarea talharilor de drumul mare, a pandarilor de poteci si a batausilor pune capat stapanirii Defias asupra drumurilor din sudul Westfall si iti aduce primirea oficiala in People's Militia, sub comanda lui Gryan Stoutmantle.",al={"finalizarea misiunii People's Militia","inductia in militie","ce primesc daca o duc la bun sfarsit"}},{q="Cine este Gryan Stoutmantle?",a="Gryan Stoutmantle este un soldat veteran care a luptat in timpul third war in Lordaeron. La intoarcerea in Westfall, dupa ce a vazut ca Kingdom of Stormwind si-a abandonat taranimea, a infiintat People's Militia la Sentinel Hill pentru a lupta impotriva Defias.",al={"trecutul lui Gryan","cine este Stoutmantle","conducatorul din Sentinel Hill"}},{q="Ce fel de Defias se ascund in Dagger Hills?",a="Dagger Hills adapostesc talhari de drumul mare Defias cu experienta, Pathstalker letali si Knuckleduster brutali, care pun la cale raiduri impotriva sudului Westfall si pazesc fortaretele mai bine ascunse ale Brotherhood-ului.",al={"inamici Defias in sudul regiunii Westfall","cine sunt Pathstalker si Knuckleduster","cine se afla in Dagger Hills"}},{q="Cum se leaga aceasta de Lordaeron?",a="Gryan Stoutmantle mentioneaza ca s-a intors de curand din 'tinuturile corupte din Lordaeron', unde Alliance a luptat impotriva Scourge. Supravietuirea in acel teatru sumbru i-a dat hotararea de a organiza apararea din Westfall dupa ce autoritatile locale au esuat.",al={"stoutmantle in lordaeron","pamanturile corupte din lordaeron","istoria razboiului lui gryan"}}},fx={["12e61ece"]={q="De ce vrea Gryan Stoutmantle ca acesti Defias sa fie ucisi?",a="Jefuitorii Defias au patruns adanc in sudul Westfall, pradand ferme si evitand patrulele militiei. Cercetasii lui Gryan i-au urmarit pana la Dagger Hills, unde se aduna pentru a pune la cale urmatorul atac. Daca nu sunt starpiti si invinsi acum, gospodariile ramase in sud vor ajunge cu totul sub stapanirea lor.",al={"de ce sa ucizi Defias din Dagger Hills","motivul lui Gryan","de ce ii vrea Gryan morti"}}},fp="20,306,24.514.0,21.516.0,27.203.0,54.268.0,39.204.0,25.272.0,45.198.0,35.250.0"}
P.entries["quest:140"] = {n="Captain Sanders' Hidden Treasure",s="Un indiciu imbibat in whiskey porneste vanatoarea dupa Captain Sanders' Hidden Treasure spre vest, de pe tarmul din Westfall. Traseul duce peste Great Sea, departe de necazurile continentului, pana la o insula indepartata.",h="Un indiciu imbibat in whiskey porneste vanatoarea dupa Captain Sanders' Hidden Treasure spre vest, de pe...",kw={"captain sanders","indiciul final","comoara ascunsa","insula","cufar incuiat","ulcior vechi","vanatoare de comori","westfall"},ang={["class:Rogue"]="Urmarirea unui ticalos de-a lungul plajelor pustii si pana in largul marii ii vine firesc unui rogue care pretuieste contrabanda piratilor.",["race:Human"]="Ca human care apara Westfall de banditii Defias si gnolli, poate ca te bucura o pauza de la patrularea fermelor, cat timp cauti ascunzatoarea uitata a unui pirat din partea locului."},sec={{t="Urmele unui marinar",b="Captain Sanders a raspandit indicii de-a lungul coastei din Westfall, pentru orice aventurier destul de indraznet sa le urmeze. Ultimul pergament a fost scos din ramasitele ulciorului sau preferat de whiskey si indica directia finala. Cuvintele capitanului sunt clare: mergi spre vest, pana la marginea apei, apoi inoata in larg, printre valuri."},{t="Insulita pustie",b="Mici stanci se ridica din Great Sea, in largul coastei din Westfall. Inotand drept spre vest, ajungi la insulita izolata unde Captain Sanders si-a ascuns prada. Acolo te asteapta un cufar incuiat, cu balamalele ruginite de stropii sarati ai marii. Cei destul de staruitori il pot forta si pot incheia traseul bucanierului."}},faq={{q="Unde duce indiciul final?",a="Biletul din Old Jug te trimite spre vest, pe tarmul din Westfall, apoi in larg. Cufarul te asteapta pe o insula mica.",al={"unde e cufarul","locatia comorii lui Sanders","destinatia indiciului final"}},{q="Cine a fost Captain Sanders?",a="Captain Sanders era un corsar care naviga de-a lungul Westfall. A lasat in urma un sir de indicii presarate cu ghicitori de-a lungul tarmului, care duceau la un cufar de pe o insula indepartata, in loc sa-si pastreze prada intr-o banca sau intr-o fortareata.",al={"cine este capitanul Sanders","povestea lui Sanders","trecutul capitanului Sanders"}},{q="De ce miroase a whisky ultimul indiciu?",a="Instructiunile finale au fost ascunse in carafa de whisky aruncata a lui Captain Sanders, langa coasta. Umezeala si bautura au facut cerneala sa se intinda cu timpul, dar indicatiile raman lizibile.",al={"bilet despre whisky","indiciu de pe ulciorul vechi"}},{q="Cati pasi are aceasta vanatoare de comori?",a="Vanatoarea are patru etape. Incepe cu o harta batuta de valuri pe coasta, apoi duce la un cufar pentru voiaj, un butoi si o carafa de whisky, inainte de a se incheia la cufarul de pe insula.",al={"cat dureaza lantul de misiuni al lui sanders","etapele misiunii lui sanders","lantul de misiuni al capitanului sanders"}},{q="Este periculos sa ajungi pe insula?",a="Principala provocare este inotul indelungat pana la Great Sea. Apele de coasta din Westfall adapostesc adesea murloci agresivi si bestii marine, iar pe insulita se afla locul unde Sanders si-a tinut proviziile ascunse.",al={"inoata pana la cufarul lui sanders","pericolul de pe insula","murlocii de langa cufar"}},{q="In ce stare se afla cufarul cu comoara?",a="Aerul marin si valurile care se sparg au macinat cufarul. Balamalele sunt foarte ruginite, dar o parghie il poate forta sa se deschida, pentru a ajunge la bunurile din interior.",al={"starea cufarului","este incuiat cufarul","cufar ruginit"}}},fp="32,189,16.289.0,16.295.1,31.123.0,24.212.0,44.180.0,41.169.0,33.176.0,36.139.0"}
P.entries["quest:141"] = {n="The Defias Brotherhood",s="Mathias Shaw trimite un raport confidential din Stormwind catre Gryan Stoutmantle, la Sentinel Hill. Shaw a investigat fosta Stonemasons Guild pentru a-l ajuta pe Stoutmantle sa descopere originile Defias Brotherhood.",h="Mathias Shaw trimite un raport confidential din Stormwind catre Gryan Stoutmantle, la Sentinel Hill.",kw={"defias","sentinel hill","shaw","zidari","stormwind","stoutmantle","vancleef","westfall"},ang={["class:Rogue"]="Ca rogue, vezi cum disputele dintre fostii mestesugari din Stormwind pot tulbura asezari indepartate.",["faction:Alliance"]="Pentru Alliance, rascoala Stonemasons scoate la iveala fisuri adanci in regat. Muncitorii care au reconstruit meterezele de piatra din Stormwind ameninta acum sa le darame.",["race:Human"]="Ca Human din Stormwind, aceasta dezvaluire te priveste indeaproape. Zidurile caselor voastre si Catedrala insasi au fost ridicate de aceiasi oameni care jefuiesc acum tinuturile rurale din Westfall."},sec={{t="Constructor devenit bandit",b="De luni intregi, Gryan Stoutmantle si People's Militia se confrunta cu o rascoala aparent fara chip, in tot Westfall. Talharii, hotii si ucigasii ataca de pe drumuri si din tinuturile rurale. Maestrul Mathias Shaw din SI:7 studiaza Wiley's Note si pune cap la cap adevarul. Breasla arhitectilor si zidarilor care au reconstruit zidurile albe ale Stormwindului nu s-a desfiintat niciodata. Conducatorul lor, Edwin VanCleef, i-a dus in subteran."},{t="Amaraciune si tradare",b="Dupa ce First War a transformat Stormwind in ruine fumegande, Stonemasons' Guild condusa de VanCleef a inceput sa restaureze capitala regatului. Munca lor a transformat din nou Stormwind intr-o bijuterie a omenirii. Cand lucrarile s-au incheiat, a izbucnit o disputa amara privind plata. VanCleef si artizanii sai erau nemultumiti de felul in care fusesera tratati de coroana si de House of Nobles. Au luat pumnalele si bandanele rosii, abandonand mestesugul civic pentru o rebeliune violenta impotriva tronului."},{t="Neincrederea lui Stoutmantle",b="Raportul lui Shaw ajunge la Sentinel Hill, iar Gryan Stoutmantle se lupta sa-i accepte continutul. Si-l aminteste pe VanCleef ca pe un artizan harnic si talentat, nu ca pe un criminal care se ascunde in umbrele tinutului rural. Munca lui VanCleef a oferit adapost miilor de cetateni intorsi acasa. Comandantul militiei cere dovezi concrete inainte de a accepta pe deplin acuzatia alarmanta ca arhitectul-sef al Stormwind orchestreaza ruinarea Westfall-ului."}},faq={{q="Ce este Shaw's Report?",a="Raportul confidential al lui Mathias Shaw contine concluziile sale despre fosta Stonemasons Guild si despre Defias. Il duci la Gryan Stoutmantle.",al={"raportul lui Shaw","documentul lui Mathias Shaw","raportul pentru Stoutmantle"}},{q="Cine este Edwin VanCleef?",a="Edwin VanCleef conducea Stonemasons Guild, care a reconstruit Stormwind. Raportul lui Shaw cerceteaza istoria ulterioara a breslei.",al={"identitatea lui VanCleef","cine este Edwin VanCleef","povestea lui Edwin VanCleef"}},{q="De ce este Gryan Stoutmantle sceptic in privinta raportului?",a="Gryan Stoutmantle gaseste greu de inghitit acuzatiile lui Shaw si cere dovezi concrete inainte de a le accepta pe deplin. Detaliile ies la iveala cand citeste raportul.",al={"de ce nu crede Gryan","reactia lui Stoutmantle","de ce are Gryan nevoie de dovezi"}},{q="De ce s-au intors masonii impotriva Stormwind?",a="Zidarii au reconstruit Stormwind, apoi au ajuns intr-o disputa amara din cauza compensatiilor. Erau nemultumiti de felul in care fusesera tratati de coroana si de House of Nobles.",al={"de ce sunt furiosi defias","disputa zidarilor","motivul lui vancleef"}},{q="Ce rol are SI:7 in aceasta misiune?",a="Mathias Shaw din SI:7 cerceteaza posibile legaturi intre fosta breasla si proscrisi, apoi ii trimite descoperirile lui Stoutmantle.",al={"de ce Mathias Shaw","implicarea SI:7","breasla hotilor din Stormwind"}},{q="Incotro duce aceasta investigatie?",a="Predai raportul, apoi il ajuti pe Stoutmantle sa caute noi dovezi in ancheta aflata in curs despre Defias.",al={"ce urmeaza","urmatoarea misiune Defias","dupa raportul lui Shaw"}}},fx={b90c31ae={q="De ce vrea Master Mathias Shaw ca acest raport sa fie livrat?",a="Mathias Shaw ii trimite descoperirile sale lui Gryan Stoutmantle, pentru ca People's Militia sa poata continua investigatiile asupra Defias. Raportul confidential se bazeaza pe cercetarile lui Shaw despre fosta Stonemasons Guild.",al={"de ce sa trimiti raportul","motivul lui shaw","de ce ii trimite shaw raportul lui gryan"}},d51cfbac={q="De ce se bazeaza Mathias Shaw pe tine ca sa duci raportul?",a="Ai ajuns in Stormwind la recomandarea directa a lui Gryan Stoutmantle si ti-ai dovedit deja valoarea pe teren. In loc sa-si puna in pericol curierii oficiali SI:7 sau garzile orasului, cand infiltratorii Defias ar putea fi cu ochii pe ei, Shaw are incredere in tine sa duci direct la People's Militia descoperirile sale confidentiale.",al={"de ce sa nu trimita gardieni","de ce sa foloseasca un aventurier","de ce eu, Shaw"}}},fp="22,212,23.416.1,23.458.1,23.423.1,22.141.0,22.118.0,49.167.0,47.167.0,39.129.0,40.106.1"}
P.entries["quest:1418"] = {n="Neeka Bloodscar",s="Helgrum the Swift te trimite din Stonard la avanpostul Kargath din Badlands, ca sa vorbesti cu sefa cercetasilor de acolo, Neeka Bloodscar. Legatura dintre Stonard si Kargath este adesea intrerupta.",h="Helgrum the Swift te trimite din Stonard la avanpostul Kargath din Badlands, ca sa vorbesti cu sefa...",kw={"badlands","cercetas-sef","helgrum the swift","kargath","loch modan","neeka bloodscar","stonard","swamp of sorrows"},sec={{t="O linie taiata",b="Badlands este un tinut aspru, aflat in apropiere de Loch Modan, tinut de Alliance. Din acest motiv, legatura dintre Stonard si Kargath este deseori intrerupta. Helgrum iti cere sa-ti dovedesti valoarea calatorind in Badlands si vorbind cu Neeka Bloodscar, cercetasul-sef de acolo. Apoi, raportul lui Neeka trebuie trimis inapoi lui Helgrum."},{t="Raspunsul lui Neeka",b="Neeka iti spune ca un curier a fost trimis spre Stonard cu doar trei zile in urma. Daca Stonard nu a primit nimic de la Neeka, inseamna ca acel curier a dat gres. Neeka spera ca urmatorul va fi mai priceput sau mai norocos."}},faq={{q="Unde te trimite Helgrum the Swift?",a="Din Stonard, la avanpostul Kargath din Badlands, pentru a vorbi cu Neeka Bloodscar.",al={"unde ma duc","locatia lui Neeka Bloodscar","unde se afla Neeka"}},{q="De ce s-a intrerupt comunicarea dintre Stonard si Kargath?",a="Badlands este un tinut aspru, aflat aproape de Loch Modan, pe care il detine Alliance, iar legaturile dintre Stonard si Kargath sunt adesea intrerupte.",al={"de ce s-au intrerupt comunicatiile","probleme de comunicatie in badlands","de ce stonard catre kargath"}},{q="Cine este Neeka Bloodscar?",a="Neeka Bloodscar este sefa cercetasilor avanpostului din Kargath, aflat in Badlands.",al={"cine este neeka","rolul lui neeka","povestea lui neeka bloodscar"}},{q="Ce urmeaza dupa ce vorbesti cu Neeka Bloodscar?",a="Report to Helgrum urmeaza.",al={"ce urmeaza","misiune de continuare","dupa Neeka Bloodscar"}}},fp="15,170,10.325.0,14.199.1,38.86.0,57.128.0,23.73.0,47.26.0"}
P.entries["quest:1419"] = {n="Coyote Thieves",s="In avanpostul Kargath, Neeka Bloodscar vrea sa vanezi coiotii de stanca din Badlands, fiare rezistente care au indraznit sa se furiseze in Kargath si sa-i fure hrana. Neeka iti cere treizeci de mandibule.",h="In avanpostul Kargath, Neeka Bloodscar vrea sa vanezi coiotii de stanca din Badlands, fiare rezistente care...",kw={"badlands","coyote thieves","coyote de pe stanci","oase de maxilar","Kargath","Neeka Bloodscar"},sec={{t="Hotii din Kargath",b="Neeka Bloodscar te intreaba daca ai petrecut multe zile in Badlands, daca i-ai simtit arsita si ai intalnit bestiile campiilor sale prafuite. Coiotii de stanca sunt o rasa rezistenta si s-au strecurat in Kargath ca sa fure provizii din avanpost. Neeka vrea sa-i vanezi si sa-i aduci inapoi cu falcile lor. Adu destule, iar Neeka s-ar putea sa creada ca cunosti Badlands."}},faq={{q="De ce vrea Neeka Bloodscar oasele maxilarului de coyote?",a="Crag coyotes s-au strecurat in Kargath si au furat provizii de hrana. Neeka vrea sa-i vanezi si sa-i aduci falcile drept dovada ca te descurci in Badlands.",al={"de ce maxilare de coiot","motivul lui Neeka Bloodscar","de ce sa colectezi maxilare"}},{q="Unde fac necazuri coiotii?",a="Coiotii Crag ratacesc prin campiile prafuite din Badlands si au patruns in avanpostul din Kargath ca sa fure hrana.",al={"locatia coiotilor","unde gasesc crag coyotes","unde sunt coiotii"}},{q="Cate maxilare vrea Neeka Bloodscar?",a="Treizeci de mandibule de coiot, duse la Neeka Bloodscar in Kargath.",al={"cate mandibule","numarul mandibulelor de coiot"}},{q="Cine este Neeka Bloodscar?",a="Neeka Bloodscar se afla la avanpostul Kargath din Badlands, unde Neeka ofera aceasta vanatoare.",al={"cine este neeka","neeka bloodscar"}}},fp="14,206,18.339.0,46.154.0,38.116.0,44.62.0,23.94.0"}
P.entries["quest:142"] = {n="The Defias Brotherhood",s="Gryan Stoutmantle te trimite dupa un curier evaziv Defias, sperand sa afle cum isi dirijeaza fortele Fratia.",h="Gryan Stoutmantle te trimite dupa un curier evaziv Defias, sperand sa afle cum isi dirijeaza fortele Fratia.",kw={"defias","jangolode","mesager","moonbrook","cariera","saldean","stoutmantle","la vest"},ang={["class:Rogue"]="Ca rogue, poti vedea cum iscusitii cercetasi si hotii de buzunare coordoneaza o vasta retea din umbra, chiar sub nasul militiei.",["faction:Alliance"]="Fara sprijinul garnizoanei regale din Stormwind, People's Militia se ocupa singura de informatiile din Westfall, urmarind curierii de-a lungul drumurilor de pamant pustii.",["race:Human"]="Ca human, poti urmari mesajele pana la Edwin VanCleef si poti vedea urmarile amare si persistente ale conflictelor politice si de munca din Stormwind."},sec={{t="Interceptarea curierului",b="Cercetasii lui Gryan Stoutmantle au vazut un Curier Defias greu de prins, calatorind intre Moonbrook, Gold Coast Quarry si Jangolode Mine. Spre deosebire de batausii care stapanesc tinuturile rurale, acest curier duce ordine scrise prin regiune. Stoutmantle vrea sa-l captureze sau sa-l ucida, pentru ca People's Militia sa-i poata citi geanta si sa afle unde isi trimite Brotherhood fortele."},{t="O urma de cerneala",b="Mesajul recuperat confirma ca Edwin VanCleef, legendarul fost lider al Stonemasons Guild, conduce personal revolta celor din Defias. Confirma ca el comanda celulele locale, dar nu dezvaluie unde si-a stabilit baza secreta."},{t="O intorsatura norocoasa",b="Mesajul confirma ca VanCleef este la conducere, iar People's Militia are parte de o sansa nesperata. Un bandit disperat este prins in timp ce incearca sa fure caruta fermierului Saldean si accepta sa-si tradeze camarazii in schimbul vietii. Cu dovada scrisa in mana, Stoutmantle isi indreapta atentia spre tradator, sperand ca acesta il va putea conduce pe un insotitor in inima ascunzatorii Defias."}},faq={{q="Unde calatoreste mesagerul Defias?",a="Defias Messenger isi incepe patrula in Moonbrook, in fata fierariei. Merge spre nord, pana la Gold Coast Quarry si Jangolode Mine, intra in ambele exploatari subterane, apoi isi reface drumul pana la Moonbrook.",al={"traseul mesagerului","unde este mesagerul Defias","gaseste mesagerul"}},{q="Ce dezvaluie mesajul interceptat?",a="Stoutmantle spera ca ordinele curierului vor dezvalui structura de comanda a Brotherhood si vor ajuta la gasirea ascunzatorii sale. Continutul mesajului devine cunoscut dupa ce acesta este recuperat.",al={"ce scria in mesaj","textul mesajului misterios","biletul lui vancleef"}},{q="Cine este Gryan Stoutmantle?",a="Gryan Stoutmantle conduce People's Militia de la cartierul ei general din Sentinel Hill. Avand prea putini strajeri regali din Stormwind, el organizeaza voluntari si aventurieri pentru a apara Westfall de jefuitorii Defias.",al={"rolul lui stoutmantle","cine ofera aceasta misiune"}},{q="De ce viziteaza mesagerul minele?",a="Fratia a pus stapanire pe bogatiile minerale ale Westfall, folosind Jangolode Mine si Gold Coast Quarry pentru resurse brute, adapost si locuri de pregatire. Mesagerul duce vesti intre aceste operatiuni si conducerea Brotherhood.",al={"de ce Gold Coast Quarry","de ce Jangolode Mine"}},{q="Dezvaluie prinderea mesagerului ascunzatoarea Defias?",a="Stoutmantle intentioneaza sa foloseasca ordinele interceptate pentru a continua cautarea ascunzatorii. Afli urmatoarea pista cand te intorci la el.",al={"am gasit ascunzatoarea","unde este ascunzatoarea"}},{q="Cine este Edwin VanCleef?",a="Edwin VanCleef a fost Maestrul Zidar al Stonemasons Guild, care a reconstruit Stormwind. Ancheta lui Stoutmantle cerceteaza posibila legatura dintre VanCleef si Brotherhood.",al={"cine este VanCleef","conducatorul Defias"}}},fx={["885172ef"]={q="De ce vrea Gryan Stoutmantle sa se faca acest lucru?",a="Gryan Stoutmantle si People's Militia duc o campanie disperata pentru a recuceri Westfall de la Defias Brotherhood. Desi militia stie ca hotii actioneaza in fermele si minele din intreaga provincie, inca nu stie unde se afla ascunzatoarea principala a fratiei. Interceptarea acestui mesager este cea mai buna pista a lui Stoutmantle pentru a le descoperi fortareata si a lovi direct in conducerea lor.",al={"motivul lui gryan stoutmantle","de ce sa interceptezi mesagerul","de ce sa prinzi mesagerul defias"}},fc5d2b39={q="Cine este mesagerul Defias?",a="Curierul este un agent Defias insarcinat sa duca mesaje intre principalele fortarete ale fratiei din Westfall: orasul ocupat Moonbrook, Gold Coast Quarry si Jangolode Mine. Fiindca coordoneaza miscarile dintre aceste avanposturi dispersate, capturarea lui sau confiscarea ordinelor sale le ofera celor din People's Militia o ocazie rara de a vedea structura de comanda a conspiratorilor.",al={"mesager Defias","cine este mesagerul","mesagerul vizat"}},a4c1678d={q="De ce are nevoie Gryan Stoutmantle de ajutorul tau pentru aceasta sarcina?",a="People's Militia este impinsa la limita, mentinand un perimetru defensiv subtire in jurul Sentinel Hill si aparand fermierii refugiati de banditii si gnollii dezlantuiti. Stormwind a refuzat sa trimita intariri sau trupe regale in Westfall, lasandu-l pe Stoutmantle fara soldatii de rezerva necesari pentru a urmari curierii pe teritoriul ostil.",al={"de ce sa ma trimiti pe mine","de ce nu se ocupa Gryan","de ce are nevoie militia de tine"}}},fp="22,116,24.376.0,14.251.1,17.347.1,39.213.0,41.173.1,25.204.0,40.235.0,54.134.0,22.171.1"}
P.entries["quest:1420"] = {n="Report to Helgrum",s="Neeka Bloodscar a scris un raport nou pentru Helgrum the Swift din Stonard si te roaga sa i-l duci. Aceasta urmeaza dupa vizita la Neeka, in Kargath.",h="Neeka Bloodscar a scris un raport nou pentru Helgrum the Swift din Stonard si te roaga sa i-l duci.",kw={"badlands","helgrum the swift","informatii pentru horde","neeka bloodscar","curier","raport","stonard"},sec={{t="Un raport pentru Stonard",b="Neeka Bloodscar a scris un raport nou pentru Helgrum, in Stonard, si ti-l inmaneaza. Neeka adauga ca oricine se considera un outrunner nu trebuie sa-si piarda drumul si nici sa cada in mainile dusmanului."},{t="Helgrum citeste raportul",b="Citind raportul lui Neeka, Helgrum isi da seama ca Alliance are propriile probleme. Helgrum crede si ca Horde si Alliance s-ar putea dovedi a avea cativa dusmani comuni."}},faq={{q="Cine te trimite cu raportul?",a="Neeka Bloodscar, care a scris un raport nou pentru Helgrum.",al={"cine ofera Report to Helgrum","cel care da misiunea Report to Helgrum","cine incepe aceasta misiune"}},{q="Unde trebuie livrat raportul?",a="Pentru Helgrum the Swift, in Stonard.",al={"unde predau report to helgrum","locatia helgrum","unde este helgrum"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa pasul anterior, in care Helgrum te-a trimis sa vorbesti cu Neeka Bloodscar in Kargath.",al={"misiunea precedenta","conditie prealabila pentru Report to Helgrum","ce misiune trebuie facuta mai intai"}}},fp="17,153,20.185.0,24.162.1,30.60.0,43.32.0,23.95.0"}
P.entries["quest:1421"] = {n="The Lost Caravan",s="Dupa Encroaching Wildlife, Watcher Biggs mai are o treaba pentru tine. Desi fusese ametit in timpul atacului Lost Ones asupra caravanei, Biggs a vazut totusi cum era dusa o caruta la Fallow Sanctuary, satul Lost Ones din nord. In ea se afla un cufar cu reactivi valorosi, iar Biggs vrea sa-i aduci inapoi.",h="Dupa Encroaching Wildlife, Watcher Biggs mai are o treaba pentru tine.",kw={"dark portal","fallow sanctuary","lost ones","nethergarde keep","swamp of sorrows","watcher biggs","reagenti pentru vrajitori"},sec={{t="Caruta furata",b="Biggs a fost lasat fara cunostinta in timpul atacului, dar a zarit unul dintre vagoanele caravanei fiind tarat spre Fallow Sanctuary, satul Lost Ones din nord. In acel vagon se afla un cufar cu reactivi pretuiti de vrajitorii din Nethergarde Keep pentru studiile lor. Biggs vrea ca cufarul sa fie gasit, iar continutul lui sa-i fie adus."},{t="Vesti de la Biggs",b="Intorcandu-te cu reagentii, il gasesti pe Biggs multumit, fiindca vrajitorii din Nethergarde isi pot continua acum treaba. Biggs nu stie in ce consta aceasta, doar ca are legatura cu Dark Portal, aflat in Blasted Lands, si ca este foarte importanta pentru siguranta Alliance."}},faq={{q="Cine este Watcher Biggs?",a="Watcher Biggs a pierdut o caruta din convoi in fata celor din Lost Ones si vrea sa fie recuperati reactivii pe care ii transporta.",al={"watcher biggs","cine da caravanei pierdute"}},{q="Unde au dus Lost Ones lada carutei?",a="Biggs a vazut caruta dusa la Fallow Sanctuary, satul Lost Ones din nord, cu lada la bord.",al={"locatia lazilor caravanei","unde este fallow sanctuary","unde sunt reagentii"}},{q="De ce sunt importanti reactivii?",a="Vrajitorii din Nethergarde Keep se bazeaza pe ele pentru studiile lor.",al={"de ce conteaza reactivii","scopul reactivilor din nethergarde"}},{q="Ce urmeaza dupa recuperarea cufarului?",a="Driftwood urmeaza dupa ce Biggs obtine reactivii.",al={"urmatoarea misiune dupa lost caravan","lantul lost caravan"}}},fp="16,303,16.322.0,15.274.1,21.103.0,47.116.0,31.65.0,38.46.0"}
P.entries["quest:1422"] = {n="Threat From the Sea",s="Dupa Lack of Surplus, Tok'Kar incepe sa lucreze la arma ta si iti spune sa vorbesti cu Katar in Swamp of Sorrows. Katar a spus ca patrulele de pe plaja ar putea folosi ajutor.",h="Dupa Lack of Surplus, Tok'Kar incepe sa lucreze la arma ta si iti spune sa vorbesti cu Katar in Swamp of...",kw={"plaja","katar","patrula","tarm","swamp of sorrows","threat from the sea","tok'kar"},sec={{t="O vorba cu Katar",b="In timp ce lucrezi la arma ta, Tok'Kar iti sugereaza sa vorbesti cu Katar, care a spus ca patrulele de-a lungul plajei ar avea nevoie de ajutor. Tok'Kar imparte tabara cu niste betivi, dar ar prefera sa-ti pastrezi mintea agera si armele pregatite, in loc sa li te alaturi."},{t="Peste vuietul marii",b="Katar iti cere un moment de tacere. Deasupra vuietului infundat al marii, se mai aud bolboroselile scarboase ale oamenilor-peste."}},faq={{q="De ce te trimite Tok'Kar la Katar?",a="Tok'Kar este ocupat cu arma ta si prefera sa-ti pastrezi mintea si bratele pregatite, in loc sa te imbeti cu lichelele din tabara.",al={"de ce sa vorbesti cu katar","motivul pentru tok'kar","de ce sa-l vizitezi pe katar"}},{q="Cu ce are Katar nevoie de ajutor?",a="Katar a spus ca patrulele de-a lungul plajei ar avea nevoie de ajutor, iar asta este ceea ce cauta Katar.",al={"problema lui katar","ce vrea katar","patrula lui katar"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza Lack of Surplus, dupa care Tok'Kar incepe sa-ti faca arma.",al={"misiunea anterioara","conditii prealabile","lantul Threat From the Sea"}}},fp="19,176,17.260.0,24.126.1,35.133.0,37.105.0,27.75.0"}
P.entries["quest:1423"] = {n="The Lost Supplies",s="Un butoias mic si trainic, cu imbinarile sigilate cu ceara galbena, intepatoare. O stampila de pe baza lui poarta numele Quartermaster Lungertz si Nethergarde Keep, iar acolo ii este locul.",h="Un butoias mic si trainic, cu imbinarile sigilate cu ceara galbena, intepatoare.",kw={"butoi","darkshire","provizii pierdute","nethergarde keep","quartermaster lungertz","swamp of sorrows"},sec={{t="Un butoi stantat",b="Ceara galbena si intepatoare sigileaza rosturile acestui butoi compact si zdravan. Dedesubt, o stampila poarta inscriptia Quartermaster Lungertz, Nethergarde Keep, deci butoiul ii este destinat intendentului de acolo."},{t="Vesti de la quartermaster",b="Quartermaster Lungertz iti multumeste. Proviziile se pierd pe tot drumul de la Darkshire la Nethergarde si e bine sa vezi ca unele au fost recuperate."}},faq={{q="Cine trebuie sa primeasca proviziile pierdute?",a="Butoiul este destinat lui Quartermaster Lungertz de la Nethergarde Keep.",al={"cine primeste butoiul","destinatarul proviziilor pierdute","unde trebuie dus butoiul"}},{q="Cum iti dai seama cui ii apartine butoiul?",a="Pe fundul butoiului se afla o stampila cu numele Quartermaster Lungertz si Nethergarde Keep.",al={"marcajele butoiului","cum se citeste butoiul","stampila quartermaster lungertz"}},{q="Cum arata butoiul?",a="Este un butoi mic si solid, cu ceara galbena, intepatoare, de-a lungul imbinarilor.",al={"butoi cu provizii pierdute","descrierea butoiului"}}},fp="17,169,16.185.0,27.134.1,42.68.0,37.90.0,31.69.0"}
P.entries["quest:1424"] = {n="Pool of Tears",s="In Stonard, Fel'zerul iti cere sa cauti artefacte Atal'ai in jurul Pool of Tears. Warchief i-a trimis oamenii lui Fel'zerul sa cerceteze evenimentele ciudate de la Temple of Atal'Hakkar, iar ei au ajuns si l-au gasit scufundat.",h="In Stonard, Fel'zerul iti cere sa cauti artefacte Atal'ai in jurul Pool of Tears.",kw={"artefacte","Atal'ai","Fel'zerul","dragoni verzi","Pool of Tears","Stonard","Swamp of Sorrows","Temple of Atal'Hakkar","Warchief"},sec={{t="Sunken Temple",b="Trollii Atal'ai sunt vrajitori intunecati, un trib renumit pentru magia interzisa. Cand grupul lui Fel'zerul a ajuns la Temple of Atal'Hakkar, membrii sai au fost uimiti sa-l gaseasca scufundat. Acum dragonii verzi vegheaza asupra locului si se numesc protectorii Azeroth."},{t="Piese ale unui puzzle",b="Fel'zerul vrea sa afle ce s-a intamplat si iti cere sa cutreieri zona din jurul Pool of Tears, adunand artefacte Atal'ai, cu ajutorul carora puzzle-ul ar putea incepe sa se limpezeasca. Nimeni nu stie ce ritualuri intunecate se practicau in templu; se stie doar ca erau folosite forte magice uriase. Fel'zerul spera ca vrajile Atal'ai s-ar putea dovedi utile pentru Horde si vrea sa inteleaga ce sperau troll sa obtina si ce a mers atat de ingrozitor de rau."}},faq={{q="Cine este Fel'zerul?",a="Fel'zerul se afla in Stonard si este unul dintre cei pe care Warchief i-a trimis sa cerceteze intamplarile neobisnuite de la Temple of Atal'Hakkar.",al={"fel'zerul","felzerul","cine da Pool of Tears"}},{q="De ce este Horde interesata de trollii Atal'ai?",a="Fel'zerul subliniaza ca acolo au fost folosite forte magice uriase si crede ca vrajile Atal'ai s-ar putea dovedi folositoare pentru Horde.",al={"de ce vrea horde atal'ai","magia atal'ai si horde"}},{q="Unde se afla artefactele Atal'ai?",a="Se afla pe fundul Pool of Tears, langa templu.",al={"locatia artefactului Atal'ai","unde gasesc artefacte","artefactele din Pool of Tears"}},{q="Cine pazeste acum templul scufundat?",a="Dragonii verzi vegheaza asupra locului si se considera protectorii lui Azeroth.",al={"de ce sunt dragonii verzi aici","dragonii verzi de la templul atal'hakkar","dragonii verzi din swamp of sorrows"}},{q="Ce urmeaza dupa predarea artefactelor?",a="Atal'ai Exile urmeaza.",al={"urmatoarea misiune dupa Pool of Tears","continuarea lui Pool of Tears","ce urmeaza dupa Pool of Tears"}}},fp="13,217,17.253.0,18.423.0,17.114.0,50.126.0,40.58.0,33.77.0,50.26.0"}
P.entries["quest:1425"] = {n="Deliver the Shipment",s="Dupa Driftwood, Watcher Biggs mai are o ultima treaba pentru tine, cat timp caruta e reparata. Biggs a strans proviziile esentiale salvate din atacurile ogre si vrea sa le duci la Quartermaster Lungertz, la Nethergarde Keep.",h="Dupa Driftwood, Watcher Biggs mai are o ultima treaba pentru tine, cat timp caruta e reparata.",kw={"cristale azoran","blasted lands","portalul intunecat","nethergarde keep","quartermaster lungertz","transport","swamp of sorrows","watcher biggs"},sec={{t="O ultima livrare pentru Biggs",b="In timp ce Biggs repara caruta, proviziile esentiale recuperate dupa atacurile ogres sunt impachetate pentru a le duce la Nethergarde Keep. Fortareata se afla pe dealurile nordice din Blasted Lands si vegheaza asupra Dark Portal. Biggs iti arata drumul: urmeaza soseaua spre est, indreapta-te spre sud in Blasted Lands, acolo unde se bifurca, apoi fa la stanga la urmatoarea rascruce. Te avertizeaza sa fii cu bagare de seama."},{t="La Nethergarde",b="Quartermaster Lungertz este surprins sa primeasca un pachet de la caravana lui Biggs, deoarece fortareata ii daduse disparuti si pe cei din caravana, si pe Biggs. Lungertz iti multumeste si spera ca proviziile contin Azoran Crystals, un reactiv de care este mare nevoie si care se gaseste tot mai rar in fortareata."}},faq={{q="Cine trimite transportul la Nethergarde?",a="Watcher Biggs, care ramane sa repare caruta, a strans provizii esentiale salvate din urma atacurilor ogres.",al={"cine da misiunea Deliver the Shipment","cine ofera misiunea Deliver the Shipment","livrarea pentru Watcher Biggs"}},{q="Unde trebuie dus acest transport?",a="Se duce la Quartermaster Lungertz din Nethergarde Keep, in dealurile nordice din Blasted Lands.",al={"unde se afla Nethergarde Keep","cum ajung la Nethergarde","locatia Quartermaster Lungertz"}},{q="Ce se intampla chiar inaintea acestei livrari?",a="Urmeaza Driftwood.",al={"cerinte pentru Deliver the Shipment","ce misiune preceda Deliver the Shipment"}},{q="Ce drum duce din mlastina la fortareata?",a="Urmeaza drumul spre est, apoi coteste spre sud in Blasted Lands, acolo unde drumul se bifurca, si ia-o la stanga la urmatoarea bifurcatie.",al={"indicatii catre nethergarde keep","drumul spre blasted lands"}},{q="Ce supravegheaza Nethergarde Keep?",a="Vegheaza asupra Dark Portal.",al={"scopul lui Nethergarde Keep","de ce se afla Nethergarde in Blasted Lands"}}},fp="20,232,25.377.0,14.263.1,38.99.0,36.92.0,41.21.0,44.117.0,39.36.0"}
P.entries["quest:1426"] = {n="Threat From the Sea",s="Dupa ce Tok'Kar iti cere sa vorbesti cu Katar, acesta isi arata limpede ura fata de mare. Lui Katar ii face o oarecare placere sa priveasca cum oamenii-peste mor de mana oricui face voia Horde, iar Katar te intreaba cati poti ucide si daca ai vrea sa-ti incerci puterile impotriva celor mai puternici dintre ei.",h="Dupa ce Tok'Kar iti cere sa vorbesti cu Katar, acesta isi arata limpede ura fata de mare.",kw={"katar","devorator de mlastina","improscator de cerneala de mlastina","murloc de mlastina","murloc","swamp of sorrows","threat from the sea"},sec={{t="O ranchiuna impotriva marii",b="Katar nu indrageste nici marea, nici vreo creatura care iese din ea si o numeste o stapana puternica, dar oarba, nemiloasa si brutala. Uciderea sutelor de oameni-peste l-ar incanta pe Katar, daca ar fi cu putinta, iar sa-i vada cazand in mainile celor care slujesc Horde ii aduce o oarecare satisfactie. Katar, aflat in Swamp of Sorrows, iti cere sa ucizi murlocii de mlastina, scuipatorii de cerneala de mlastina si devoratorii de carne de mlastina."},{t="Verdictul lui Katar",b="La intoarcerea ta, Katar spune ca marea poate parea vasta si neinduplecata, dar propriile sale odrasle poarta acum semnul tau insangerat. Oamenii-peste cunosc acum durerea si trebuie sa-si refaca randurile, lucru pe care Katar il gaseste imbucurator; Katar va zambi de fiecare data cand unul e redus la tacere. Katar te invita sa te intorci si sa ucizi mai multi."}},faq={{q="De ce vrea Katar ca murlocii sa fie distrusi?",a="Katar nu are nicio dragoste pentru mare sau pentru ce iese din ea si ar fi bucuros sa vada sute de oameni-peste ucisi. Ii face o oarecare placere sa-i priveasca murind de mana celor care fac voia Horde.",al={"de ce sa omori murlocs","katar murlocs","de ce uraste marea"}},{q="Unde are loc aceasta vanatoare?",a="In Swamp of Sorrows, printre murloci de mlastina, scuipatori de cerneala de mlastina si devoratori de carne de mlastina.",al={"unde sunt murlocii din mlastina","locatia Threat From the Sea"}},{q="Cine da aceasta misiune de vanatoare?",a="Katar, cu care Tok'Kar ti-a spus sa vorbesti in Swamp of Sorrows.",al={"cine ofera Threat From the Sea","cel care da misiunea Threat From the Sea"}},{q="Ce a precedat aceasta vanatoare?",a="Urmeaza dupa prima Threat From the Sea, in care Tok'Kar te-a trimis sa vorbesti cu Katar.",al={"cerinte preliminare pentru Threat From the Sea","misiunea anterioara Threat From the Sea"}}},fp="19,288,24.401.0,15.279.1,42.185.0,32.85.0,20.67.0,28.88.0"}
P.entries["quest:1427"] = {n="Threat From the Sea",s="Dupa ce ai lucrat pentru Katar, ti se spune sa-l vezi inca o data pe Tok'Kar inainte sa te odihnesti. Katar crede ca Tok'Kar a terminat cateva arme cat ai fost plecat si ca una iti va fi oferita drept multumire pentru ajutor.",h="Dupa ce ai lucrat pentru Katar, ti se spune sa-l vezi inca o data pe Tok'Kar inainte sa te odihnesti.",kw={"katar","murloc","carne de sawtooth","swamp of sorrows","threat from the sea","tok'kar"},sec={{t="Inapoi la Tok'Kar",b="Katar crede ca Tok'Kar a mai faurit cateva arme cat timp ai lipsit si ca Tok'Kar iti va oferi una pentru ajutorul tau. Katar adauga ca ar fi bine sa-i incerci puterea pe oamenii-peste cand esti gata, dar numai ca sa-i faci o bucurie lui Katar."},{t="Multumirile lui Tok'Kar",b="Tok'Kar se bucura sa te vada inapoi si spune ca au fost faurite mai multe arme pentru razboiul impotriva murlocilor. Drept multumire ca ai adus carne proaspata de sawtooth si i-ai adus un zambet lui Katar, iti da una dintre ele."}},faq={{q="Cine te trimite sa vorbesti cu Tok'Kar?",a="Katar o face, spunandu-ti sa-l vezi din nou pe Tok'Kar inainte sa te odihnesti in Swamp of Sorrows.",al={"cine da aceasta misiune","de unde iau threat from the sea","cine incepe aceasta"}},{q="De ce ofera Tok'Kar o arma?",a="Katar crede ca Tok'Kar a terminat cateva arme cat timp ai fost plecat si ca una iti va fi oferita drept multumire pentru ajutor.",al={"de ce da Tok'kar o arma","ce a creat Tok'kar","motivul recompensei lui Tok'kar"}},{q="Ce urmeaza dupa ce vorbesti cu Tok'Kar?",a="Continued Threat continua.",al={"care este urmatoarea misiune","unde merg dupa aceasta","ce urmeaza dupa Threat From the Sea"}}},fp="19,199,15.236.0,16.208.1,36.89.0,33.127.0,44.25.0"}
P.entries["quest:1428"] = {n="Continued Threat",s="Katar se bucura ca ura ta fata de oamenii-peste creste odata cu a lui si te trimite sa vanezi mai multi pe plaja din Swamp of Sorrows.",h="Katar se bucura ca ura ta fata de oamenii-peste creste odata cu a lui si te trimite sa vanezi mai multi pe...",kw={"continued threat","oameni-pesti","katar","marsh flesheater","marsh inkspewer","marsh oracle","murlocs","swamp of sorrows"},sec={{t="Mai multe de-a lungul plajei",b="Katar iti spune sa cauti mai multi oameni-peste de-a lungul plajei si sa te intorci cand te-ai saturat de lupta. Sunt cautati marsh inkspewers, marsh flesheaters si marsh oracles. Katar nu va simti nicio placere pana cand marea si fiecare dintre odraslele ei nu vor fi reduse la tacere, cu atat mai putin oamenii-peste dezgustatori."}},faq={{q="Cine ofera aceasta misiune?",a="Katar, in Swamp of Sorrows.",al={"cine incepe Continued Threat","cel care da misiunea Continued Threat","Katar din Swamp of Sorrows"}},{q="Ce creaturi trebuie vanate?",a="Katar vrea marsh inkspewers, marsh flesheaters si marsh oracles de-a lungul plajei.",al={"ce trebuie ucis","tinte pentru continued threat","care murloci"}},{q="De ce vrea Katar sa rareasca murlocii?",a="Katar nu va avea tihna pana cand marea si odraslele ei nu vor fi reduse la tacere, mai ales oamenii-peste.",al={"de ce sa omori murloci","motivul lui katar","de ce uraste oamenii-peste"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza dupa misiunea anterioara Threat From the Sea, dupa care Tok'Kar ti-a oferit o arma.",al={"continued threat cerinte","misiunea anterioara continued threat"}}},fp="16,160,20.310.0,21.31.0,33.82.0,39.95.0,27.86.0"}
P.entries["quest:1429"] = {n="The Atal'ai Exile",s="Cat timp erai la Pool of Tears, unul dintre cercetasii lui Fel'zerul a adus un pergament scris cu sange pe piele uscata. Fel'zerul impacheteaza acum artefactele pe care le-ai adunat si te trimite departe spre nord, in Hinterlands, sa gasesti un preot Atal'ai exilat.",h="Cat timp erai la Pool of Tears, unul dintre cercetasii lui Fel'zerul a adus un pergament scris cu sange pe...",kw={"atal'ai exile","fel'zerul","hakkar","hinterlands","jammal'an","pool of tears","shadra'alor","swamp of sorrows","witherbark"},sec={{t="O sentinta scrisa cu sange",b="Pergamentul descrie o hotarare judecatoreasca impotriva unui preot al Atal'ai, o soarta mai rea decat moartea in randul propriului sau popor. A fost exilat sa traiasca printre trollii Witherbark, departe, in nordul Hinterlands. Fel'zerul va impacheta artefactele si te trimite sa-l gasesti pe exilat, sa-i descoperi adevarata intrebuintare si sa te intorci."},{t="Cuvintele exilatului",b="Dupa ce i se arata legatura, exilatul identifica artefactele drept unelte de invocare ale Atal'ai. El remarca faptul ca discipolii Camerei Sangelui sunt condusi de Jammal'an the Prophet catre soarta aleasa de ei si se intreaba daca Hakkar s-a intors in templu."}},faq={{q="Cine te trimite sa-l gasesti pe Atal'ai Exile?",a="Fel'zerul din Stonard, care strange artefactele adunate de tine si te trimite spre nord, in Hinterlands.",al={"cine ofera Atal'ai Exile","cine da misiunea Atal'ai Exile","cine incepe misiunea"}},{q="Unde se afla Atal'ai Exile?",a="In Hinterlands, traind alaturi de trollii Witherbark, la templul din Shadra'Alor.",al={"unde se afla exilatul","locatia lui atal'ai exile","unde gasesti atal'ai exile"}},{q="Ce sentinta a fost data asupra preotului?",a="Un pergament cu cerneala din sange pe piele uscata condamna preotul la o soarta mai rea decat moartea printre Atal'ai: exilul printre troll-ii Witherbark din Hinterlands.",al={"de ce a fost exilat","care a fost sentinta","povestea din trecut despre atal'ai exile"}},{q="Ce duci la exilat?",a="Un manunchi de artefacte Atal'ai adunate de la Pool of Tears, a caror adevarata utilizare vrea sa o afle Fel'zerul de la exilat.",al={"ce pachet trebuie sa aduci","care sunt artefactele","scopul artefactelor Atal'ai"}},{q="Ce urmeaza imediat inaintea acestei calatorii?",a="Urmeaza dupa Pool of Tears, unde Fel'zerul ti-a cerut sa aduni artefacte Atal'ai.",al={"misiunea anterioara","conditie prealabila","ce duce la Atal'ai Exile"}}},fp="17,242,19.310.0,17.256.1,40.100.0,35.83.0,39.158.0,35.116.0,40.75.0"}
P.entries["quest:143"] = {n="Messenger to Westfall",s="Messenger to Westfall este o misiune a Alliance, care duce un apel urgent al lui Magistrate Solomon din Redridge, prin Elwynn, pana in Westfall. Conducerea din Lakeshire, abandonata cu totul de armata din Stormwind, cauta ajutor reciproc din partea People's Militia, nou infiintata de Gryan Stoutmantle.",h="Messenger to Westfall este o misiune a Alliance, care duce un apel urgent al lui Magistrate Solomon din...",kw={"gryan stoutmantle","lakeshire","magistrate solomon","militia poporului","redridge mountains","sentinel hill","solomons plea","westfall"},ang={["faction:Alliance"]="Acest mesaj evidentiaza prabusirea completa a apararii centrale din Kingdom of Stormwind, fortand orasele de la granita sa negocieze pacte private de aparare mutuala.",["race:Human"]="Mesajul arata greutatile comune ale colonistilor human din Redridge si Westfall, care trebuie sa se bazeze pe voluntari si mercenari in timp ce capitala sta nepasatoare."},sec={{t="Un apel disperat",b="Magistrate Solomon gaseste Lakeshire intr-o situatie disperata. Redridge Mountains sunt asediate de orci Blackrock si gnolli, insa Stormwind Army nu a sosit in numar mare. Dandu-si seama ca Lakeshire nu poate supravietui doar cu garzile orasului si trupele neregulate, Solomon scrie o cerere oficiala de ajutor. Cum rezervele regale regulate nu se vad nicaieri, isi indreapta privirea spre vest, dupa ce a auzit ca dincolo de Elwynn Forest se formeaza un grup de aparare al cetatenilor."},{t="Intinzandu-ne peste hotare",b="Destinatarul scrisorii este Gryan Stoutmantle, un comandant veteran care a inceput sa adune luptatori voluntari sub stindardul People's Militia. Trimitand un curier direct de-a curmezisul regatului, Solomon spera ca voluntarii organizati din Westfall vor putea trimite soldati pentru a intari granitele din Lakeshire pana cand armatele Coroanei se vor mobiliza in cele din urma. Insa, dupa cum descopera curand mesagerii, Westfall este prins in propriile lupte catastrofale impotriva Defias Brotherhood."}},faq={{q="De ce ii cere Magistrate Solomon ajutor lui Westfall?",a="Stormwind nu a trimis intaririle militare de care Lakeshire are atata nevoie impotriva orcilor si gnoll-ilor. Dupa ce a auzit zvonuri despre o forta armata de cetateni care se aduna in Westfall, Solomon spera ca Gryan Stoutmantle va putea trimite soldati sa intareasca Redridge.",al={"de ce westfall","rugamintea lui solomon","de ce sa-l intrebi pe gryan"}},{q="Cine este Gryan Stoutmantle?",a="Gryan Stoutmantle este un soldat veteran stationat la Sentinel Hill, in Westfall. In lipsa autoritatii si protectiei Coroanei, el a organizat si conduce People's Militia pentru a apara gospodariile locale de banditi si de Defias Brotherhood.",al={"cine este gryan","stoutmantle rolul","cine conduce westfall"}},{q="Unde duce aceasta calatorie a curierului?",a="Mesajul trebuie dus de la primaria din Lakeshire spre vest, traversand Redridge si Elwynn Forest, pana la Sentinel Hill, in centrul Westfall.",al={"unde trebuie sa predau","unde se afla Stoutmantle","din Redridge in Westfall"}},{q="De ce nu a venit Stormwind Army sa elibereze Lakeshire?",a="Magistrate Solomon observa ca se petrece ceva ciudat cu armata, deoarece trupele promise nu au sosit. Regele lipseste, iar Highlord Bolvar Fordragon conduce ca regent; rezervele asteptate nu mai vin, lasand teritoriile indepartate sa se descurce singure.",al={"de ce nu exista armata Stormwind","unde sunt garzile regale","armata Stormwind lipseste"}},{q="Poate Westfall sa trimita intr-adevar trupe in Redridge?",a="Nu. Cand ajungi la Sentinel Hill, descoperi ca Westfall abia mai rezista in fata Defias Brotherhood. People's Militia nu are soldati de prisos si se lupta sa-si apere propriile granite.",al={"ajuta Westfall","va veni militia","poate ajuta Gryan"}},{q="Ce urmeaza dupa predarea scrisorii?",a="Gryan Stoutmantle primeste mesajul si redacteaza imediat un raspuns in care explica situatia disperata din Westfall, apoi te trimite inapoi cu un raspuns pentru Magistrate Solomon.",al={"ce urmeaza","misiunea urmatoare","dupa Messenger to Westfall"}}},fx={dcf2b619={q="De ce trimite Magistrate Solomon un aventurier in locul propriilor garzi?",a="Garda locala din Lakeshire este solicitata peste orice limita. Gnollii, murlocii si orcii Blackrock ameninta toate granitele, gata sa copleseasca orasul in orice clipa. Solomon nu poate lipsi nici macar un singur gardian pentru lunga calatorie prin Elwynn Forest pana in Westfall, asa ca trebuie sa se bazeze pe calatori capabili ca tine, care sa duca apelurile sale disperate dupa ajutor.",al={"de ce sa ma trimiti","de ce are nevoie Solomon de un aventurier","de ce sa nu trimita un gardian in Westfall"}}},fp="21,278,18.449.0,23.482.0,51.252.0,25.241.0,37.156.0,49.265.0,52.211.1,39.184.1"}
P.entries["quest:1430"] = {n="Fresh Meat",s="In Swamp of Sorrows, Dar spune ca exista o cerere mare pentru carnea de crab in randul clientilor din Orgrimmar, mai ales pentru cea a crabului monstruos. Dar iti cere sa aduci inapoi cateva dintre picioarele lor de pe coasta.",h="In Swamp of Sorrows, Dar spune ca exista o cerere mare pentru carnea de crab in randul clientilor din...",kw={"picioare de taratoare","dar","carne proaspata","taratoare monstruoasa","orgrimmar","swamp of sorrows"},sec={{t="Crawler Legs pentru Orgrimmar",b="Clientii lui Dar au gusturi pentru carnea suculenta de crawler, mai ales cea a crawlerilor monstruosi. Dar promite ca o calatorie pana la coasta va merita osteneala daca ii aduci cateva dintre picioarele lor, pentru a fi trimise la Orgrimmar. Coasta se afla la est de aici, unde creaturile se napustesc pe plaje si intra in valuri. O bute de vin te asteapta daca reusesti, iar Dar vrea sa guste marfa inainte sa fie expediata."},{t="Provizii gustoase pentru drum",b="Dar este incantat de picioare, imaginandu-si cum s-ar gati la foc deschis. Dar te indeamna sa iei cu tine o mostra gatita in calatorii si jura ca este cu adevarat delicioasa."}},faq={{q="Cine vrea carne de taratoare in Swamp of Sorrows?",a="Dar, ai carui clienti din Orgrimmar au mare nevoie de acest lucru.",al={"cine da carne proaspata","misiunea lui Dar","cine este Dar"}},{q="Unde se afla crawlerii monstruosi?",a="Pe coasta din est, forfotind peste plaje si intrand in valuri.",al={"locatia crawler","unde sunt crawlerele","monstrous crawler de pe tarm"}},{q="De ce are Dar nevoie de aceste picioare anume?",a="Clientilor lui Dar le place carnea de crawler, mai ales cea a crawlerilor monstruosi, iar picioarele trebuie trimise inapoi la Orgrimmar.",al={"de ce carne de crawler","la ce foloseste carnea","carne de crawler din Orgrimmar"}}},fp="10,198,26.401.0,20.174.1,47.60.0,41.71.0,38.130.0"}
P.entries["quest:1431"] = {n="Alliance Relations"}
P.entries["quest:1432"] = {n="Alliance Relations"}
P.entries["quest:1437"] = {n="Vahlarriel's Search",s="Vahlarriel Demonslayer a venit in Desolace pentru a afla ce s-a intamplat cu doi nobili disparuti din House Malem, o familie de negustori Darnassian. Tatal lor se teme de ce-i mai rau, iar ultimul mesaj despre cei doi ii plaseaza in Stonetalon Mountains cu cateva saptamani in urma. Vahlarriel iti cere sa le gasesti caruta.",h="Vahlarriel Demonslayer a venit in Desolace pentru a afla ce s-a intamplat cu doi nobili disparuti din House...",kw={"cufar","dalinda","darnassus","desolace","malem","stonetalon","tyranis","vahlarriel"},sec={{t="Doi nobili disparuti",b="Vahlarriel Demonslayer ii cauta pe Tyranis si Dalinda Malem, al caror tata se teme de ce e mai rau si i-a cerut lui Vahlarriel sa faca tot ce-i sta in putinta pentru a-i gasi. Cautarea abia a inceput, iar Vahlarriel spera ca nu ii va tine mult in Desolace. Ultima data, cei doi au fost vazuti traversand Stonetalon Mountains cu cateva saptamani in urma. Vahlarriel iti cere sa le gasesti caruta in Desolace si sa te intorci numaidecat cand o gasesti. Acolo se afla ramasitele ei carbonizate, iar printre ele este un cufar."},{t="Printre daramaturi",b="Scotocind prin epava, iti dai seama ca asupra carutei s-au folosit atat vraji, cat si arme. Lupta pare sa fi fost scurta si inegala, fara sange si fara cadavre lasate in urma. Oricine a facut asta a actionat eficient si rapid."}},faq={{q="Pe cine cauta Vahlarriel?",a="Tyranis si Dalinda Malem, doi nobili din Casa Malem, o familie de negustori Darnassian.",al={"cine lipseste","cine sunt nobilii","copiii disparuti ai Casei Malem"}},{q="Unde au fost auziti ultima data fratii?",a="Ultima data s-a raportat ca traversasera Stonetalon Mountains cu cateva saptamani inainte ca Vahlarriel sa-ti vorbeasca.",al={"ultima oara cand au fost vazuti fratii Malem","unde s-au dus","traseul carutei"}},{q="De ce cauta Vahlarriel?",a="Tatal lor se teme de ce e mai rau, iar Vahlarriel a primit sarcina de a face tot ce-i sta in putinta pentru a-i gasi pe copiii disparuti.",al={"cine a angajat-o pe vahlarriel","cine vrea sa fie gasiti fratii"}},{q="Ce vrea Vahlarriel sa gasesti?",a="Caruta lui Tyranis si Dalinda Malem din Desolace. Daca o gasesti, Vahlarriel iti cere sa vii numaidecat.",al={"cum incepe cautarea lui vahlarriel","care este primul pas"}}},fp="19,290,18.474.0,18.217.1,30.83.0,40.100.0,28.122.0,38.104.0"}
P.entries["quest:1438"] = {n="Vahlarriel's Search",s="Dupa a doua parte a lui Vahlarriel's Search, Vahlarriel Demonslayer te trimite sa-i cauti pe Dalinda si Tyranis Malem, incepand cu fortareata. Vestea ajunge la superiorii lui Vahlarriel din Darnassus, care sunt ingrijorati de motivele lui Tyranis si vor, mai presus de orice, ca Dalinda sa fie adusa acasa teafara.",h="Dupa a doua parte a lui Vahlarriel's Search, Vahlarriel Demonslayer te trimite sa-i cauti pe Dalinda si...",kw={"burning blade","dalinda","darnassus","demonslayer","desolace","malem","thunder axe fortress","tyranis","vahlarriel"},sec={{t="O cautare la fortareata",b="Vahlarriel Demonslayer vrea sa-i cauti atat pe Dalinda, cat si pe Tyranis, incepand cu fortareata, si sa te intorci cu vestile aflate. Vahlarriel ii va contacta imediat pe superiorii din Darnassus. Apoi iti spune ceva in particular: se intreaba de ce a venit Tyranis in Desolace, dar cel mai mult ii pasa ca Dalinda sa ajunga acasa in siguranta. In privinta lui Tyranis, vrea mai intai sa-i afle intentiile, inainte sa se intoarca acasa."},{t="Marturia unui captiv",b="Dalinda, aflata in cladirea mare din fata intrarii, spune ca Burning Blade au prins-o pe ea si pe Tyranis si i-au adus aici; crede ca urmeaza sa fie sacrificata stapanilor lor demoni. Spune ca totul a fost o greseala de la bun inceput. Tyranis tanjea dupa cunoasterea arcana, impotriva dorintelor poporului sau, si a pornit la drum in ciuda avertismentelor despre demonii de aici. Se teme de ceea ce i s-a intamplat."}},faq={{q="Unde se afla Dalinda Malem?",a="In zona Thunder Axe Fortress din Desolace, in cladirea mare cu fata spre intrare.",al={"dalinda malem locatie","unde o gasesti pe dalinda","gaseste dalinda desolace"}},{q="Cine te trimite sa-i cauti pe Dalinda si Tyranis?",a="Vahlarriel Demonslayer iti cere sa-i gasesti pe amandoi, daca poti, incepand de la fortareata, in timp ce Vahlarriel isi informeaza superiorii din Darnassus.",al={"cine ofera vahlarriel's search","cel care da misiunea lui vahlarriel","misiunea vahlarriel demonslayer"}},{q="De ce ii pasa mai mult lui Darnassus de Dalinda decat de Tyranis?",a="Superiorii lui Vahlarriel se indoiesc de motivele lui Tyranis pentru a veni in Desolace si pun mai presus de orice intoarcerea in siguranta a lui Dalinda.",al={"de ce este suspectat tyranis","motivele lui tyranis","de ce sa o prioritizezi pe dalinda"}},{q="Ce a avut loc inaintea acestei parti a cautarii?",a="Urmeaza a doua parte din Vahlarriel's Search.",al={"misiunea anterioara","misiune premergatoare pentru Vahlarriel","lantul de cautare Vahlarriel"}}},fp="19,280,24.374.0,19.390.1,23.92.0,46.132.0,56.118.0,41.50.0"}
P.entries["quest:1439"] = {n="Search for Tyranis",s="Dalinda Malem iti spune ca orcii i-au macelarit pe toti gardienii si servitorii inainte de a o aduce aici pe ea si pe Tyranis. Tyranis a incercat sa vorbeasca cu ei, iar ea nu poate pleca pana nu afla ce s-a intamplat cu fratele ei. Iti cere sa-l gasesti si sa te intorci dupa ce-i afli soarta.",h="Dalinda Malem iti spune ca orcii i-au macelarit pe toti gardienii si servitorii inainte de a o aduce aici pe...",kw={"burning blade","dalinda","desolace","malem","pandantiv","thunder axe fortress","tyranis","vahlarriel"},sec={{t="Un frate rapit",b="Dalinda iti spune ca orcii i-au ucis toti paznicii si servitorii inainte de a o tarai pe ea si pe Tyranis in acest loc. Se astepta sa moara pe loc, dar orcii aveau, in mod clar, alte planuri. Tyranis a incercat sa discute cu ei, poate sperand ca vastele sale cunostinte arcane ii vor impresiona, desi ea nu stie de ce. Nu va evada pana nu va afla ce soarta a avut el, asa ca te roaga sa-l gasesti si sa te intorci dupa ce il gasesti. Se afla intr-o cladire din stanga intrarii in fortareata."},{t="Teama Dalindei",b="Dalinda se teme ca Tyranis, daca i se va permite, va cauta secretele Burning Blade si va deveni unul dintre ei. Puterea l-a atras dintotdeauna, asa cum atrage pe oricine sedus de magie. Pentru poporul ei, chiar si studiul unor astfel de lucruri este o crima grava, iar ea se indoieste ca si-ar putea privi familia in ochi spunandu-i ca spiritul lui s-a jucat cu acel pericol."},{t="Ce afla Dalinda",b="Cand te intorci, Dalinda spune ca a fost ingrozitor, dar necesar. Daca mana ta nu ar fi facut-o, ar fi facut-o oamenii ei. Isi cere iertare daca multumirile ei suna lipsite de sinceritate. Cunoscandu-i soarta, este gata sa fuga si iti va accepta ajutorul daca mai esti dispus sa i-l oferi."}},faq={{q="Cine este Tyranis Malem?",a="Fratele Dalindei. A vorbit cu rapitorii lor, poate sperand sa-i impresioneze cu cunostintele sale arcane, iar ea spune ca puterea magiei l-a atras dintotdeauna.",al={"cine este tyranis","trecutul lui tyranis","tyranis malem"}},{q="De ce refuza Dalinda sa plece deocamdata?",a="Ea nu va pleca pana nu afla ce s-a intamplat cu fratele ei. Iti cere sa-l gasesti si sa te intorci dupa ea cand ii vei cunoaste soarta.",al={"de ce nu pleaca dalinda","de ce ramane dalinda","de ce asteapta sa evadeze"}},{q="Ce s-a intamplat cu garzile si servitorii?",a="Orcs i-au ucis pe toti, apoi i-au luat pe Dalinda si Tyranis vii, se pare ca aveau alte planuri.",al={"ce s-a intamplat cu paznicii lor","cine a fost ucis","paznici si servitori"}},{q="Unde este Tyranis?",a="La Thunder Axe Fortress din Desolace, in cladirea din stanga, imediat dupa intrare.",al={"unde se afla tyranis","locatia lui tyranis"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza dupa a treia parte din Vahlarriel's Search, in care Vahlarriel ti-a cerut sa o gasesti pe Dalinda.",al={"ce misiune preceda aceasta","progresul misiunilor","lantul de misiuni al lui Vahlarriel"}}},fp="18,276,15.446.0,14.312.0,19.257.1,21.152.0,37.139.0,41.93.0,17.78.0,27.92.0"}
P.entries["quest:144"] = {n="Messenger to Westfall",s="O scrisoare din Westfall ii aduce lui Magistrate Solomon un raspuns categoric in Lakeshire. Ii ceruse soldati lui Gryan Stoutmantle pentru apararea Redridge, dar Westfall a fost lasat sa-si infrunte singur problemele.",h="O scrisoare din Westfall ii aduce lui Magistrate Solomon un raspuns categoric in Lakeshire.",kw={"Gryan Stoutmantle","Lakeshire","Magistrate Solomon","Messenger to Westfall","militia poporului","Redridge","Sentinel Hill","Westfall"},ang={["faction:Alliance"]="Aceasta corespondenta arata ruptura dintre conducatorii din Stormwind Keep si provinciile indepartate. Westfall si Redridge sunt lasate sa se descurce singure.",["race:Human"]="Ca turist Human, vezi cat de izolate sunt orasele de provincie. Oamenii de rand si veteranii isi varsa sangele aparand tinuturi pe care nobilii din Stormwind refuza sa le protejeze."},sec={{t="Un apel de ajutor peste frontiere schimbatoare",b="Magistrate Solomon se confrunta cu probleme tot mai mari in Redridge Mountains, fara garnizoana regala din Stormwind. El cauta ajutor la frontiera sudica si ii scrie lui Gryan Stoutmantle, comandantul People's Militia din Westfall. Solomon spera ca voluntarii de la Sentinel Hill pot trimite luptatori pentru a intari apararea din Lakeshire. Nu stie cat de greu o duc tinuturile din campia vestica."},{t="Un refuz amar",b="Gryan Stoutmantle refuza, desi raspunsul il apasa greu. Westfall lupta impotriva Defias Brotherhood si a gnollilor jefuitori, fiindca House of Nobles si coroana au abandonat hambarul regatului. People's Militia a fost infiintata pentru ca oamenii sa poata supravietui. Randurile ei pierd oameni de isprava in fiecare zi, iar Stoutmantle nu poate trimite nici macar un luptator in Redridge."},{t="Regatul care se destrama",b="Cand duci raspunsul lui Stoutmantle inapoi in Lakeshire, Solomon vede ca si tinuturile de frontiera sunt neglijate la fel. Magistratii locali si militiile cetatenesti sunt lasati sa se apere singuri, in timp ce Stormwind Army nu li se alatura. Solomon isi indreapta atentia spre sud, catre Darkshire din Duskwood, in speranta ca va gasi ajutor acolo."}},faq={{q="De ce i-a cerut Magistrate Solomon ajutorul lui Westfall?",a="Magistrate Solomon a cerut ajutor deoarece Lakeshire se confrunta cu amenintari tot mai mari, fara armata din Stormwind. El stia ca Gryan Stoutmantle organizase People's Militia pentru a apara Westfall si spera ca aceasta va putea trimite soldati in Redridge.",al={"de ce sa intrebi in Westfall","scrisoarea lui Solomon catre Stoutmantle","de ce militia Westfall"}},{q="De ce refuza Gryan Stoutmantle sa trimita ajutor?",a="Westfall lupta deja cu Defias Brotherhood si se apara de gnollii jefuitori. Stoutmantle spune ca Militia exista fiindca Stormwind a abandonat Westfall, iar acum nu mai are luptatori de trimis.",al={"de ce spune Stoutmantle nu","militia refuza Lakeshire","raspunsul lui Stoutmantle"}},{q="Unde se afla Stormwind Army in timpul acestor crize?",a="Nimeni dintre cei care apar in scrisori nu stie de ce Stormwind Army este plecata. Solomon si Stoutmantle nu pot decat sa se intrebe ce o impiedica sa apere provinciile de la margine.",al={"de ce nu ajuta Stormwind","unde este armata","dezertarea din Stormwind"}},{q="Ce se intampla dupa ce inapoiati scrisoarea lui Stoutmantle lui Solomon?",a="Dupa ce afla ca Westfall nu-l poate ajuta, Magistrate Solomon se indreapta spre Duskwood. Te trimite mai departe la Darkshire, in speranta ca Night Watch, aflata sub comanda lui Mayor Ello Ebonlocke, ii va putea oferi ajutor.",al={"urmatoarea misiune dupa Messenger to Westfall","ce face Solomon in continuare"}},{q="Ce este People's Militia?",a="People's Militia este o forta de voluntari organizata de Gryan Stoutmantle si stabilita la Sentinel Hill. Fermierii, veteranii si localnicii apara Westfall de proscrisi si gnolli fara ajutorul trupelor coroanei.",al={"cine sunt militienii","militia din Westfall"}},{q="Cine este Gryan Stoutmantle?",a="Gryan Stoutmantle este un veteran care conduce apararea din Westfall. Din turnul de la Sentinel Hill, el aduna voluntari si coordoneaza lupta impotriva Defias Brotherhood.",al={"povestea lui Gryan Stoutmantle","cine este Stoutmantle"}}},fx={["84b4f9a5"]={q="De ce te trimite Gryan Stoutmantle in locul propriei sale militii?",a="People's Militia este intinsa pana la limita in apararea fermelor din Westfall impotriva Defias Brotherhood si a gnollilor care dau iama prin tinut. Stoutmantle nu poate trimite nici macar un luptator in lunga calatorie spre est, prin Elwynn Forest, pana la Redridge. Deoarece ai sosit purtand de la bun inceput solicitarea lui Magistrate Solomon, actionezi deja ca mesager al Redridge si esti persoana cea mai potrivita pentru a duce raspunsul sumbru inapoi.",al={"de ce ma trimite","de ce nu trimite un curier al militiei","de ce are nevoie Gryan de un mesager"}}},fp="21,189,32.385.0,16.367.0,30.323.1,49.224.0,46.202.0,48.149.0,61.161.1,29.201.0,25.177.0"}
P.entries["quest:1440"] = {n="Return to Vahlarriel"}
P.entries["quest:1442"] = {n="Seeking the Kor Gem"}
P.entries["quest:1444"] = {n="Return to Fel'Zerul",s="Un Atal'ai exilat din Hinterlands a cercetat artefactele aduse la el si le considera inofensive. Are temeri mai sumbre legate de Jammal'an the Prophet, iar Fel'zerul din Stonard trebuie sa le afle.",h="Un Atal'ai exilat din Hinterlands a cercetat artefactele aduse la el si le considera inofensive.",kw={"atal'ai exile","fel'zerul","hinterlands","jammal'an","stonard","ritual de invocare","temple of atal'hakkar"},sec={{t="Vesti de la un exilat",b="Atal'ai Exile il considera odinioara pe Jammal'an the Prophet un mare preot demn de incredere. Dar credinta neclintita a profetului in profetie ar putea condamna Atal'ai, daca nu a facut-o deja. Pentru ca a vorbit, exilatul a fost declarat necredincios si alungat din Temple of Atal'Hakkar. Artefactele pe care le-ai adus nu sunt periculoase. Ceea ce il inspaimanta pe exilat este posibilitatea ca Jammal'an sa fi gasit vraja potrivita pentru talismanul ritualului de invocare, ceea ce ar pune lumea in mare primejdie. Fel'zerul, din Stonard, asteapta sa afle ce ai descoperit."}},faq={{q="Unde trebuie sa merg ca sa vorbesc cu Fel'zerul?",a="Fel'zerul se afla in Stonard.",al={"locatia lui Fel'zerul","unde se afla Fel'zerul","preda Return to Fel'Zerul"}},{q="De ce a fost exilat Atal'ai Exile?",a="Exilatul a vorbit despre credinta neclintita a lui Jammal'an the Prophet in profetia sa, care, crede el, va distruge Atal'ai. Pentru ca si-a exprimat ingrijorarea, a fost numit necredincios si alungat din Temple of Atal'Hakkar.",al={"de ce a fost alungat atal'ai exile","de ce este exile in hinterlands","povestea din spatele atal'ai exile"}},{q="Sunt periculoase artefactele aduse exilatului?",a="Exilatul spune ca nu sunt periculosi. Grija este ritualul de invocare si daca Jammal'an a gasit descantecul potrivit pentru talisman.",al={"sunt artefactele daunatoare","pericolul artefactelor fetis"}}},fp="19,203,19.525.0,40.24.0,35.228.0,49.137.0"}
P.entries["quest:1447"] = {n="The Missing Diplomat",s="In Stormwind, cautarea diplomatului disparut te aduce fata in fata cu Dashel Stonefist in Old Town. Ai nevoie de raspunsuri de la un om care ar prefera sa le pastreze pentru sine.",h="In Stormwind, cautarea diplomatului disparut te aduce fata in fata cu Dashel Stonefist in Old Town.",kw={"incaierare","conspiratie","dashel","diplomat disparut","orasul vechi","stonefist","stormwind","huligani"},ang={["class:Rogue"]="Ca Rogue, te ocupi de brute precum Dashel Stonefist atunci cand smulgi informatii de strada de la informatori.",["faction:Alliance"]="Fiecare indiciu despre disparitia diplomatului este esential pentru a descoperi tradarea din interior care ameninta stabilitatea conducerii Alliance.",["race:Human"]="Ca Human, vezi cum batausii din Stormwind ingreuneaza cautarea diplomatului disparut, amenintand securitatea regatului."},sec={{t="O discutie prietenoasa in Old Town",b="In Old Town, cautarea diplomatului disparut te poarta printre hoti de buzunare si intermediari dubiosi, dincolo de ochii vigilenti ai Cathedral. Dashel Stonefist este un localnic cu legaturi in factiunile criminale din Stormwind si stie cate ceva despre rapire. Nu are de gand sa le impartaseasca ce stie anchetatorilor care pun intrebari delicate."},{t="Bataie pe alee",b="Dashel Stonefist refuza sa coopereze cand te apropii de el. Golanii sai fideli din Old Town il sustin in incercarea de a te dobori si de a opri ancheta. Dupa ce-l pui la pamant pe Dashel impreuna cu oamenii lui, isi schimba atitudinea si-ti deschide calea spre urmatorul indiciu despre conspiratie."}},faq={{q="Cine este Dashel Stonefist?",a="Dashel Stonefist este un contact local dubios din Old Town, cu legaturi cu lumea interlopa criminala din Stormwind. Stie mai multe decat lasa sa se inteleaga despre miscarile ilegale prin oras.",al={"dashel stonefist","cine este stonefist","dashel"}},{q="De ce trebuie sa ma lupt cu Dashel in loc sa vorbesc pur si simplu cu el?",a="Dashel nu are niciun interes sa coopereze cu anchetatorii. Cand il intrebi despre diplomatul disparut, presupune ca te poate intimida cu usurinta si isi cheama batausii ca sa te reduca la tacere. Numai o bataie zdravana il convinge sa vorbeasca.",al={"de ce sa te lupti cu Dashel","pot vorbi cu Stonefist","de ce sa-l bati pe Dashel"}},{q="Trebuie sa-l ucid pe Dashel Stonefist?",a="Nu. Trebuie sa-l infrangi pe Dashel, nu sa-l ucizi. Cand sanatatea lui scade suficient de mult, se preda, isi recheama oamenii si accepta sa raspunda la intrebarile tale.",al={"sa-l ucid pe Dashel","Stonefist e in viata","Dashel a murit"}},{q="Unde se desfasoara aceasta lupta?",a="Lupta are loc in aer liber, in Old Town, langa aleile din spatele tavernei Pig and Whistle si salile locale de antrenament, pe unde isi petrece de obicei timpul Dashel Stonefist.",al={"locatia lui Stonefist","unde se afla Dashel","bataia din Old Town"}},{q="Ce se intampla dupa ce il invingi pe Dashel?",a="Dupa ce il invingi pe Dashel, acesta isi cere scuze si e de acord sa-ti spuna ce stie despre conspiratie. El indreapta ancheta spre urmatoarea veriga, aflata in afara capitalei.",al={"ce urmeaza dupa dashel","stonefist urmatoarea misiune","urmatorul pas in lantul diplomatului"}},{q="Despre ce este, de fapt, lantul de misiuni 'The Missing Diplomat'?",a="Cautarea unui ambasador disparut dezvaluie o retea de inselaciuni in jurul rapirii diplomatului si al personajelor misterioase din spatele ei.",al={"diplomat disparut - poveste","cine este diplomatul","regele disparut"}}},fx={c22a58c4={q="Cu cine te lupti in aceasta confruntare?",a="Te lupti cu Dashel Stonefist si cu doi dintre batausii sai zdraveni din Old Town. Dashel isi desfasoara activitatea pe aleile rau famate din Old Town, inconjurat de golani locali care-i fac treburile murdare si intimideaza pe oricine se amesteca in chestiuni care nu-l privesc. In loc sa raspunda la intrebari despre legaturile sale ilegale, Dashel isi cheama prietenii sa te bata pana taci, ca sa nu mai pleci niciodata din oras.",al={"cu cine ma lupt in misiunea diplomatului disparut","cine ataca alaturi de dashel","tinta misiunii diplomatului disparut 8"}},["15b1a9ee"]={q="De ce te ataca Dashel Stonefist?",a="Dashel nu vrea ca nimeni sa puna intrebari despre diplomatul disparut sau despre propriile lui legaturi dubioase. Actionand din umbra cartierului Old Town, el supravietuieste prin secretomanie, intimidare si forta bruta. Cand il presezi pentru raspunsuri, te considera un curios nedorit si o tinta usoara, asteptandu-se ca golanii lui sa te reduca la tacere definitiv inainte ca implicarea sa in comploturi mai intunecate sa iasa la iveala.",al={"de ce se lupta dashel stonefist cu tine","de ce ataca dashel","motivul lui dashel stonefist"}}},fp="20,175,27.326.0,18.260.1,24.171.0,61.224.0,35.163.0,33.166.0,34.164.1,50.124.2"}
P.entries["quest:145"] = {n="Messenger to Darkshire",s="Messenger to Darkshire este o misiune diplomatica urgenta, trimisa de Magistrate Solomon din Lakeshire lui Lord Ello Ebonlocke in Duskwood. Disperat sa obtina intariri militare impotriva orcilor Blackrock si a gnollilor care ameninta Redridge, Solomon cere ajutor asezarii vecine. Curierul trebuie sa infrunte drumurile umbrite din Duskwood pentru a-i inmana primarului din Darkshire rugamintea oficiala a lui Solomon.",h="Messenger to Darkshire este o misiune diplomatica urgenta, trimisa de Magistrate Solomon din Lakeshire lui...",kw={"darkshire","duskwood","ebonlocke","lakeshire","mesager","night watch","redridge","solomon"},ang={["faction:Alliance"]="Scrisorile disperate ale lui Solomon scot in evidenta cat de dezbinate si neglijate au ajuns asezarile indepartate ale Alliance, in timp ce curtea regala din Stormwind ramane paralizata.",["race:Human"]="Misiunea ilustreaza soarta comuna a asezarilor umane din sud, fiecare fiind nevoita sa se bazeze pe militii locale neregulate dupa ce regatul si-a retras patrulele armatei regulate."},sec={{t="Un apel disperat dupa ajutor",b="Cum palatul regal din Stormwind ii ignora rugamintile, iar Westfall, vecina sa, este prinsa in propria rascoala, Magistrate Solomon isi indreapta privirea spre sud, catre Duskwood. Redridge se confrunta cu un asediu tot mai intens al clanurilor de orci Blackrock si al haitelor agresive de gnolli, iar garzile locale din Lakeshire sunt impinse la limita. Disperat, Solomon ii scrie o scrisoare direct primarului Ello Ebonlocke, sperand sa inchirieze sau sa imprumute faimoasa Night Watch din Darkshire pentru a intari perimetrul orasului."},{t="Drumul spre intuneric",b="Pentru a duce scrisoarea lui Solomon, trebuie sa treci spre sud, in Duskwood, o regiune impadurita, invaluita intr-o bezna supranaturala. Solomon le recomanda curierilor sa ramana strict pe drumuri, caci salbaticia dintre Lakeshire si Darkshire a devenit renumita pentru primejdiile ei. Ajungand la Town Hall din Darkshire, vei inmana scrisoarea Lordului Ebonlocke, insa daca Duskwood mai are forte de trimis este o cu totul alta intrebare."}},faq={{q="De ce cere Lakeshire ajutorul lui Darkshire?",a="Stormwind a refuzat ajutorul militar oficial, lasand orase precum Lakeshire sa se apere singure impotriva unor amenintari coplesitoare, precum orcii Blackrock. Magistrate Solomon incearca sa apeleze la fiecare aliat Alliance din apropiere, in speranta ca Night Watch, militia civica din Darkshire, va putea trimite luptatori instruiti.",al={"de ce sa intrebi in Duskwood","de ce Darkshire","apelul lui Solomon catre Darkshire"}},{q="Cine este Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke este primarul din Darkshire si conducatorul civil de frunte al tinutului Duskwood. El administreaza orasul din primarie si coordoneaza treburile obstesti impreuna cu Commander Althea Ebonlocke, comandanta Night Watch.",al={"ello ebonlocke","cine este ebonlocke","primarul din darkshire"}},{q="Ce este Night Watch?",a="Night Watch este militia civila independenta din Darkshire, infiintata pentru a patrula perimetrul si a lupta impotriva strigoilor, bestiilor si umbrelor care se strecoara prin Duskwood in lipsa trupelor de garnizoana din Stormwind.",al={"Night Watch din Duskwood","cine sunt cei din Night Watch"}},{q="De ce ma avertizeaza Solomon sa raman pe drumuri?",a="Salbaticia din Duskwood este plina de orori strigoi, paianjeni si fiare salbatice. Cei care se abat de la drumul pietruit si intra in tufisuri sunt expusi pradatorilor agresivi si ambuscadelor.",al={"avertisment pe drumurile din Duskwood","ramai pe drumuri in Duskwood"}},{q="Unde a inceput acest sir de misiuni?",a="Aceasta misiune face parte din seria de scrisori disperate a lui Magistrate Solomon. Urmeaza rugamintea pe care i-a trimis-o anterior lui Gryan Stoutmantle in Westfall, continuandu-i efortul neobosit de a recruta ajutoare pentru Lakeshire.",al={"misiunea anterioara","ordinea misiunii mesagerului"}},{q="Chiar are Darkshire destui gardieni de rezerva?",a="Duskwood se confrunta cu propria criza existentiala, asediat de mortii inviati, worgen razvratiti si monstruozitati panditoare. Night Watch abia are destui luptatori pentru a apara Darkshire, astfel ca implorarea lui Solomon este o speranta amara si aproape zadarnica.",al={"va ajuta darkshire","trimite ebonlocke garzi"}}},fx={["532260e8"]={q="De ce trimite Magistrate Solomon un aventurier in locul propriilor garzi?",a="Garda locala din Lakeshire este la capatul puterilor, incercand sa-i tina la distanta de oras pe orcii Blackrock si gnollii din Redridge. Magistrate Solomon nu-si poate lipsi nici macar un strajer de la perimetru pentru primejdiosul drum spre sud, prin Duskwood. Cum Stormwindul ii ignora apelurile pentru trupe regale, trebuie sa se bizuie pe calatori de incredere ca tine, care sa-i duca cererile urgente oraselor vecine.",al={"de ce ma trimiti in Darkshire","de ce nu trimite Solomon un gardian","de ce mi-a fost dat Messenger to Darkshire"}}},fp="22,397,24.474.0,23.424.0,43.299.0,27.230.0,24.213.0,46.185.0,31.203.0,45.237.0"}
P.entries["quest:1450"] = {n="Gryphon Master Talonaxe",s="Falstad Wildhammer nu vrea sa spuna cine zbura odinioara alaturi de un vechi prieten din Explorers' League si te trimite sa-l intrebi pe maestrul de grifoni. Gryphon Master Talonaxe te asteapta in Aerie Peak Aviary.",h="Falstad Wildhammer nu vrea sa spuna cine zbura odinioara alaturi de un vechi prieten din Explorers' League si...",kw={"aerie peak","voliera","brohann caskbelly","breasla exploratorilor","falstad wildhammer","gryphon master talonaxe","rhapsody shindigger","uldaman"},sec={{t="Trimis departe",b="Falstad Wildhammer nu are rabdare cu cineva trimis in numele unui vechi membru al Explorers' League. Falstad nu stie cu cine zbura odinioara acel prieten, iar repartizarile de zbor sunt treaba gryphon master-ului. Gryphon Master Talonaxe se afla in Aerie Peak Aviary, iar daca zabovesti pe langa Falstad, iti va da de lucru pe bune."},{t="Ce isi aminteste Talonaxe",b="Talonaxe isi aminteste ca a trimis un calaret pe gryphon sa-l ajute pe Brohann Caskbelly si a avut dintotdeauna o slabiciune pentru Explorers' League, fiindca tatal lui Talonaxe a ajutat prima echipa de excavare care a descoperit Uldaman. Calaretul era Rhapsody Shindigger, pe care Talonaxe il considera cel mai bun la vremea aceea."}},faq={{q="De ce te trimite Falstad Wildhammer la Talonaxe?",a="Falstad nu stie cu cine a zburat prietenul din Explorers' League si te indruma catre maestrul de grifoni, care se ocupa de repartizarea zborurilor.",al={"de ce sa-l vad pe Talonaxe","de ce il trimite Falstad departe","cine este Talonaxe"}},{q="Unde se afla Gryphon Master Talonaxe?",a="Gryphon Master Talonaxe se afla in Aerie Peak Aviary.",al={"unde se afla Talonaxe","locatia lui Talonaxe","voliera din Aerie Peak"}}},fp="23,196,9.344.0,23.283.1,49.141.0,41.56.0"}
P.entries["quest:1451"] = {n="Rhapsody Shindigger",s="Gryphon Master Talonaxe iti povesteste despre Rhapsody Shindigger, candva cel mai bun zburator din voliera, care s-a atasat atat de mult de bautura, incat a trebuit sa fie concediat. Talonaxe a auzit ca Rhapsody are acum o tabara de fabricat bere la est de voliera, in Hinterlands.",h="Gryphon Master Talonaxe iti povesteste despre Rhapsody Shindigger, candva cel mai bun zburator din voliera...",kw={"aerie peak","voliera","brohann","gryphon master talonaxe","hinterlands","rhapsody shindigger"},sec={{t="Un zburator doborat",b="Talonaxe subliniaza ca tuturor Dwarves de la voliera le place o bere buna, dar Rhapsody s-a apucat de bautura asa cum se avanta un gryphon spre cer. Nimeni nu putea zbura ca Rhapsody, ceea ce, dupa parerea lui Talonaxe, era o mare pacoste. Primele semne de necaz au aparut cand Rhapsody s-a intors impleticindu-se din calatoria cu Brohann, iar lucrurile au luat-o repede la vale. In cele din urma, Rhapsody a trebuit sa fie concediat. Ultimele vesti spun ca acum exista o tabara de berari la est de Aerie Peak."}},faq={{q="Cine te trimite sa-l cauti pe Rhapsody Shindigger?",a="Gryphon Master Talonaxe de la voliera din Aerie Peak te indruma catre Rhapsody.",al={"cine il intalneste pe Rhapsody Shindigger","cine ofera misiunea lui Rhapsody","unde incepe misiunea lui Rhapsody"}},{q="De ce a fost concediat Rhapsody Shindigger din voliera?",a="Rhapsody s-a apucat de bautura asa cum un gryphon se avanta spre cer. Primele semne de necaz au aparut cand s-a intors clatinandu-se dintr-un zbor cu Brohann; lucrurile au mers repede din rau in mai rau, iar Talonaxe a fost nevoit sa renunte la Rhapsody.",al={"de ce a fost concediat Rhapsody","ce s-a intamplat cu Rhapsody","povestea lui Rhapsody Shindigger"}},{q="Unde este Rhapsody acum?",a="Talonaxe a auzit ca Rhapsody tine acum o tabara de bere la est de voliera, in Hinterlands.",al={"unde este Rhapsody Shindigger","locatia taberei lui Rhapsody","cum il gasesc pe Rhapsody"}}},fp="19,249,14.431.0,42.72.0,51.211.0,22.94.0"}
P.entries["quest:1452"] = {n="Rhapsody's Kalimdor Kocktail",s="Rhapsody Shindigger, care se afla in Hinterlands, va vorbi despre ce s-a intamplat in mlastina doar daca primeste ceva tare de baut. Pentru un Kalimdor Kocktail sunt nevoie de pipote de Roc din Tanaris si de ficati de Groddoc si Ironfur din Feralas.",h="Rhapsody Shindigger, care se afla in Hinterlands, va vorbi despre ce s-a intamplat in mlastina doar daca...",kw={"brohann","feralas","ficat de groddoc","ficat de ironfur","kalimdor kocktail","rhapsody shindigger","pipota de roc","tanaris"},sec={{t="O bautura tare",b="Rhapsody il intampina cu un sughit pe mesagerul lui Brohann. Cei doi au avut parte de o aventura pe cinste, iar povestea celor intamplate in mlastina, unde lucrurile au fost urate, va iesi la iveala doar cu ceva tare de baut. Rhapsody are in minte o reteta, Kalimdor Kocktail, si promite sa-ti povesteasca totul dupa ce va fi preparata."},{t="Ingrediente din Kalimdor",b="Kocktailul are nevoie de trei pipote de Roc din Tanaris, trei ficati de Groddoc din Feralas si trei ficati de Ironfur, tot din Feralas. Nici cel mai bun malt al lui Rhapsody nu e suficient de tare ca sa faca fata amintirii acelui zbor fatidic peste mlastina."}},faq={{q="Ce vrea Rhapsody pentru Kalimdor Kocktail?",a="Trei maruntaie de Roc, trei ficati de Groddoc si trei ficati de Ironfur. Rhapsody vrea o bautura tare inainte sa vorbeasca despre ce s-a intamplat in mlastina.",al={"de ce kocktail","de ce pipote de roc","de ce ficati"}},{q="De unde provin ingredientele?",a="Maruntaiele de Roc provin din Tanaris. Ficatul de Groddoc si Ironfur provine din Feralas.",al={"unde gasesti pipote","locatia ingredientelor pentru cocktail","unde sunt groddocs"}},{q="Cine te-a trimis la Rhapsody Shindigger?",a="Brohann, pe care Rhapsody il numeste nebun, te-a trimis. Inainte de asta, Gryphon Master Talonaxe ti-a spus unde putea fi gasit Rhapsody.",al={"cine m-a trimis la rhapsody","misiunea anterioara","brohan"}}},fp="28,231,13.324.0,25.237.0,50.144.0,35.85.0,36.128.0"}
P.entries["quest:1454"] = {n="The Karnitol Shipwreck",s="Kreldig Ungor iti vorbeste despre Karnitol, un Mage care este un fel de nobil din Stormwind. Gigantii marini i-au atacat corabia in apele din nord-vestul regiunii Desolace, iar el a lasat in urma un cufar valoros si s-a teleportat. Cufarul si continutul sau trebuie gasite.",h="Kreldig Ungor iti vorbeste despre Karnitol, un Mage care este un fel de nobil din Stormwind.",kw={"desolace","ethel rethor","karnitol","kreldig ungor","reclaimers","giganti marini","naufragiu","stormwind"},sec={{t="Fuga unui nobil",b="Dupa Reclaimers' Business in Desolace, Kreldig Ungor iti vorbeste despre o prima treaba de rezolvat. Este vorba despre Karnitol, un mage care e un fel de nobil in Stormwind. Uriasii marii au atacat corabia lui Karnitol in apele din nord-vestul regiunii Desolace. Karnitol si servitorii sai au incercat sa duca la tarm unul dintre cuferele sale mai scumpe, dar uriasii s-au napustit asupra lor, iar el a abandonat cufarul si s-a teleportat in afara locului impreuna cu servitorii sai. Cufarul si continutul sau trebuie gasite, apoi returnate lui Karnitol in Stormwind. Se afla de-a lungul coastei nordice, in zona Ethel Rethor."},{t="Ce arata cufarul",b="Cufarul nu prezinta urme de apa, dar capacul a fost fortat, iar urmele de arsura de pe margini arata ca toate capcanele magice care il pazeau s-au declansat cu mult timp in urma."}},faq={{q="Cine este Karnitol?",a="Un mage care pare a fi un nobil din Stormwind. Sea giants i-au atacat corabia in apele din nord-vestul Desolace.",al={"karnitol","cine este karnitol","cine vrea cufarul"}},{q="Ce s-a intamplat cu nava lui Karnitol?",a="Gigantii marini au atacat-o in apele din nord-vestul Desolace. Karnitol si servitorii sai au incercat sa duca la tarm un cufar de mare valoare, dar gigantii au navalit asupra lor, asa ca a lasat cufarul in urma si s-a teleportat de acolo impreuna cu servitorii sai.",al={"povestea naufragiului","de ce s-a scufundat corabia","atacul uriasului marin"}},{q="Cine cauta lada?",a="Kreldig Ungor, care spune ca Karnitol vrea ca lada si continutul ei sa fie gasite si aduse inapoi la el in Stormwind.",al={"cine da misiunea","rolul lui kreldig ungor"}},{q="Unde se afla cufarul?",a="Pe coasta de nord a Desolace, in zona Ethel Rethor.",al={"locatia cufarului lui karnitol","unde este cufarul lui karnitol","cufar din ethel rethor"}}},fp="22,250,16.559.0,20.160.1,16.110.0,33.211.0,29.105.0,25.70.0"}
P.entries["quest:1455"] = {n="The Karnitol Shipwreck",s="Cufarul mage-ului Karnitol a fost fortat si este complet gol. Zgarieturile lungi si adanci de pe laterale si de pe capac sugereaza ca nu a fost nici om, nici urias, iar tu te intorci la Kreldig Ungor, la Nijel's Point.",h="Cufarul mage-ului Karnitol a fost fortat si este complet gol.",kw={"desolace","karnitol","lada lui karnitol","kreldig ungor","nijel's point","epava"},sec={{t="Un cufar gol",b="Cercetezi ce a fortat deschiderea cufarului. Pe laterale si pe capac se intind zgarieturi lungi si adanci. Ele indica faptul ca faptasul nu era nici om, nici urias, iar urmele nu par sa fi fost lasate de un pumnal sau de o sabie. Cufarul este complet gol. Neavand altceva de facut, il inchizi si te pregatesti sa pleci, stiind ca Kreldig Ungor va fi dezamagit."}},faq={{q="Ce se afla in cufarul lui Karnitol?",a="Nimic. Cufarul este complet gol.",al={"ce se afla in cufarul lui Karnitol","este cufarul lui Karnitol gol","continutul cufarului"}},{q="Ce a lasat urmele de pe cufar?",a="Laturi si partea de sus sunt brazdate de zgarieturi lungi si adanci. Acestea sugereaza ca nu le-a facut nici un om, nici un urias si nu par a fi opera unui pumnal sau a unei sabii.",al={"ce a deschis cufarul","cine a luat incarcatura","urme de gheare pe cufar"}},{q="Cui raportezi?",a="Kreldig Ungor, la Nijel's Point in Desolace.",al={"cui predau acest obiect","unde este kreldig ungor","unde merg mai departe"}},{q="Ce a fost inainte de asta?",a="Cautarea cufarului lui Karnitol, pe care Kreldig Ungor ti-a cerut-o.",al={"misiune precedenta","lantul misiunilor cu naufragiul lui Karnitol"}}},fp="22,218,14.340.0,32.39.0,33.158.0,21.44.0,22.66.0"}
P.entries["quest:1456"] = {n="The Karnitol Shipwreck"}
P.entries["quest:1457"] = {n="The Karnitol Shipwreck"}
P.entries["quest:1458"] = {n="Reagents for Reclaimers Inc.",s="Kreldig Ungor aduna reactivi pentru Mage-ul gnome Leftwitch, care locuieste in Kharanos, iar Reclaimers nu au destui oameni. Inainte sa poata incepe restul listei, vrea gheare si coarne de la satirii Hatefury din est.",h="Kreldig Ungor aduna reactivi pentru Mage-ul gnome Leftwitch, care locuieste in Kharanos, iar Reclaimers nu au...",kw={"desolace","hatefury","kharanos","kreldig ungor","leftwitch","recuperatori","roetten","sargeron","satyr"},sec={{t="Lista lui Leftwitch",b="Dupa Reclaimers' Business in Desolace, Kreldig Ungor are o alta treaba pe cap: sa adune reactivi pentru Leftwitch, mage-ul gnome care locuieste in Kharanos. Roetten crede ca-i un castig usor, fiindca Reclaimers sunt deja plecati in Desolace, iar Kreldig spune ca nu-i pasa ca echipa duce lipsa de oameni."},{t="Coarne si gheare",b="Primele lucruri de pe lista n-ar trebui sa fie prea greu de obtinut. Kreldig vrea sa duci zece gheare si zece coarne luate de la satirii Hatefury din est, care se gasesc in ruinele Sargeron, chiar la est de Nijel's Point. Dupa ce le primeste, poate incepe restul listei."}},faq={{q="Cine solicita acesti reactivi?",a="Kreldig Ungor le aduna pentru un mage gnome numit Leftwitch, care locuieste in Kharanos. Roetten crede ca e un castig usor, fiindca Reclaimers sunt deja in Desolace.",al={"cine este Leftwitch","cel care da misiunea Reagents for Reclaimers Inc","cine vrea reactivii"}},{q="Unde se afla satyrii Hatefury?",a="Hatefury satyrs se gasesc in ruinele din Sargeron, la est de Nijel's Point.",al={"locatia satirilor Hatefury","unde gasesc ghearele Hatefury","locatia coarnelor Hatefury"}},{q="Ce vrea Kreldig de la satyri?",a="Zece gheare Hatefury si zece coarne Hatefury. Cu ele, el si tu puteti trece la urmatoarele obiecte de pe lista lui Leftwitch.",al={"ce trebuie sa adun","reactivi pentru obiectele Reclaimers Inc","componente satyr necesare"}},{q="Ce crede Kreldig despre satyri?",a="Le spune creaturi josnice. A auzit ca sunt legate intr-un fel de night elves, desi se indoieste de asta. In opinia lui, povestea a pornit de la singurul elf care le-a adus in razboi cu cativa ani in urma, iar de atunci lumea a devenit mai primejdioasa si mai infricosatoare.",al={"povestea satirului Kreldig","sunt satirii Night Elves"}}},fp="28,226,16.302.0,15.247.0,33.171.0,38.82.0,39.124.0,37.271.0"}
P.entries["quest:1459"] = {n="Reagents for Reclaimers Inc.",s="Urmatoarele pe lista lui Leftwitch pentru Kreldig Ungor sunt veninul scorpashilor si pieile de kodo batran. Kreldig nu-ti poate spune unde sa le gasesti, fiindca nu cunoaste bine Desolace.",h="Urmatoarele pe lista lui Leftwitch pentru Kreldig Ungor sunt veninul scorpashilor si pieile de kodo batran.",kw={"piele de kodo batran","desolace","ironforge","kreldig ungor","leftwitch","reclaimers inc","venin Scorpashi"},sec={{t="Urmatoarele obiecte",b="Dupa prima parte a listei lui Leftwitch, Kreldig Ungor trece la urmatoarele articole. Par destul de simple, dar instructiunile sunt precise. Mage vrea venin de la scorpashi, oricare dintre ei este bun, si piei de kodo, dar numai de la kodo batrani. Kodo muribunzi si stravechi nu sunt de folos. Kreldig vrea sapte fiole de venin si trei piei. Mages, mediteaza Kreldig, cer lucruri ciudate."},{t="Pamant necunoscut",b="Kreldig nu stie unde umbla kodo si scorpashi. Abia cunoaste zona si nu a avut timp sa o exploreze."}},faq={{q="Cine solicita acesti reactivi?",a="Leftwitch, un Mage, a carui lista este parcursa de Kreldig Ungor.",al={"cine vrea reactivii","cine este leftwitch","seful lui kreldig"}},{q="De ce are Kreldig nevoie de ajutor pentru a gasi aceste creaturi?",a="Kreldig cunoaste prea putin Desolace si nu a avut timp sa-l exploreze, asa ca nu poate spune pe unde umbla kodo si scorpashi.",al={"de ce nu-i poate obtine Kreldig","cunostintele lui Kreldig despre teritoriu"}},{q="Se pot folosi pieile oricarui kodo?",a="Nu. Indrumarile lui Leftwitch cer doar kodo batrani; cei muribunzi si cei stravechi nu se pun.",al={"vreo piele de kodo","piele de kodo stravechi","piele de kodo pe moarte"}},{q="Ce sunt scorpashi?",a="Sunt scorpionii intalniti peste tot in Desolace. Leftwitch spune ca veninul oricaruia dintre ei este bun.",al={"venin de scorpashi","unde se gasesc scorpashi"}},{q="Pe unde umbla kodo batrani?",a="Turme intregi merg pe carari, mai ales in sud si vest, iar multe ajung langa Kodo Graveyard.",al={"locatia kodo imbatraniti","unde se afla kodo imbatraniti"}}},fp="28,175,14.378.0,17.123.0,33.63.0,51.117.0,32.88.0,23.96.0,28.104.0"}
P.entries["quest:146"] = {n="Messenger to Darkshire",s="Messenger to Darkshire incheie corespondenta diplomatica disperata dintre Lakeshire si Darkshire. Apelul lui Magistrate Solomon pentru intariri militare este respins categoric de Lord Ello Ebonlocke, dezvaluind adevarul amar ca ambele orase au fost lasate de Stormwind sa-si infrunte singure soarta.",h="Messenger to Darkshire incheie corespondenta diplomatica disperata dintre Lakeshire si Darkshire.",kw={"darkshire","ebonlocke","lakeshire","mesager","night watch","solomon","stormwind"},ang={["faction:Alliance"]="Aceasta nota dezvaluie fisurile adanci care sfasie regatul sudic, in timp ce asezarile Alliance de la margine se trezesc abandonate si lipsite de aparare.",["race:Human"]="Pentru calatorii oameni, corespondenta este o ilustrare sumbra a izolarii tot mai mari a oraselor regatului, in timp ce curtea regala intoarce privirea."},sec={{t="O cerere disperata, respinsa",b="Confruntat cu asaltul orcilor Blackrock si al gnollilor, Magistrate Solomon din Redridge spera ca fostul sau tovaras din Duskwood ii va putea trimite soldati. Dar reactia lui Lord Ello Ebonlocke se apropie de indignare. Darkshire abia rezista atacurilor mortilor vii, bestiilor flamande si magiei blestemate care o impresoara din toate partile. Ebonlocke spune fara menajamente ca Night Watch exista doar fiindca Stormwind a abandonat Duskwood mai intai. Daca Darkshire ar ramane fara aparatori, asezarea ar cadea inainte ca patrula sa treaca de marginea padurii."},{t="Un tipar de abandon",b="Cand Solomon citeste raspunsul lui Ebonlocke, cruda realitate a regatului devine limpede. Stormwind Army s-a retras din Westfall, a lasat Darkshire sa se descurce singur, iar acum a ignorat cererile de ajutor ale orasului Lakeshire. Solomon este silit sa se confrunte cu ceea ce conducatorii locali din tot regatul au inceput sa sopteasca: nu e vorba de o simpla neglijenta birocratica sau de incompetenta, ci de o tradare despre care se banuieste ca isi are culcusul chiar in inima Stormwind."}},faq={{q="De ce nu-l trimite Lord Ebonlocke pe Night Watch sa o ajute pe Lakeshire?",a="Darkshire este asediat din toate partile de strigoi, fiare si vrajitorii blestemate. Night Watch este o militie locala neregulata, creata tocmai fiindca Stormwind si-a retras garnizoanele. Daca Ebonlocke si-ar trimite garzile in Redridge, Darkshire ar fi invadat inainte ca trupele sa ajunga macar la marginea padurii.",al={"de ce refuza Ebonlocke","de ce nu vine Night Watch in ajutorul Lakeshire","Darkshire refuza sa ajute"}},{q="Ce intelege Magistrate Solomon dupa ce citeste raspunsul?",a="Solomon isi da seama ca situatia disperata din Lakeshire face parte dintr-o criza care cuprinde intregul regat. Cum armata s-a retras din Westfall, iar Darkshire a ramas complet fara garda, Solomon banuieste o tradare activa in randul conducerii din Stormwind, nu o simpla neglijenta.",al={"reactia lui solomon","ce isi da seama solomon"}},{q="Cine a intemeiat Night Watch?",a="Night Watch a fost infiintata de cetatenii si conducatorii incercati de greutati din Duskwood, sub indrumarea lui Lord Ello Ebonlocke, dupa ce fortele oficiale din Stormwind au lasat tinutul in voia intunericului si a putreziciunii.",al={"originile Night Watch","cine a creat Night Watch"}},{q="Unde se duce Solomon de aici pentru a cere ajutor?",a="Cu Darkshire refuzand sa ajute si Westfall cotropit de Defias Brotherhood, Lakeshire a ramas complet singur. Solomon este nevoit sa cerceteze mai indeaproape curtea palatului din Stormwind, ca sa afle de ce coroana refuza sa-si apere teritoriile indepartate.",al={"ce face Solomon in continuare","cine altcineva poate ajuta in Lakeshire"}},{q="S-a retras oficial Stormwind din Duskwood si Westfall?",a="Da. Pe masura ce magia neagra corupea Duskwood si izbucneau tulburari in Westfall, fortele regulate din Stormwind s-au retras, lasand orasele de frontiera sa-si infiinteze militii locale precum Night Watch si People's Militia, pentru a supravietui.",al={"de ce a plecat Stormwind","orasele abandonate de Stormwind"}},{q="Ce relatie exista intre Solomon si Ebonlocke?",a="Sunt colegi si magistrati de lunga durata, care guverneaza orasele de frontiera ale regatului. Solomon s-a bazat pe aceasta relatie personala cand le-a cerut trupe, dar gravitatea extrema a primejdiilor din Duskwood a facut imposibila indeplinirea cererii.",al={"sunt Solomon si Ebonlocke prieteni","relatia dintre Solomon si Ello"}}},fx={ec08915e={q="De ce te trimite Lord Ebonlocke sa duci scrisoarea in loc sa-si trimita propriii gardieni?",a="Lordul Ebonlocke nu poate lipsi nici macar un membru al Night Watch. Darkshire este asediat de intuneric si orori abominabile, iar fiecare sabie este de neinlocuit pentru a impiedica orasul sa fie coplesit. Pentru ca ai sosit din Lakeshire in calitate de curier al lui Magistrate Solomon, trimiterea ta inapoi cu raspunsul acestuia nu lipseste Darkshire de niciunul dintre pretiosii sai aparatori.",al={"de ce ma trimite","de ce nu trimite Night Watch","de ce folosesc un aventurier"}}},fp="22,292,26.542.0,24.418.1,64.301.0,63.257.0,27.189.0,44.245.0,59.213.0,51.234.0"}
