P.entries["quest:1465"] = {n="Vahlarriel's Search",s="Continuand cautarea carutei familiei Malems, gasesti un pandantiv si o dara de urme care se indreapta spre sud. Departe, se ridica fum de la o fortareata mare. Vahlarriel Demonslayer, de la Nijel's Point, ar trebui sa vada pandantivul si sa afle despre indiciul ca familia Malems ar putea fi in viata.",h="Continuand cautarea carutei familiei Malems, gasesti un pandantiv si o dara de urme care se indreapta spre...",kw={"burning blade","demonslayer","desolace","fortareata","malem","nijel's point","pandantiv","vahlarriel"},sec={{t="Semne de viata",b="Cautand mai departe in caruta, gasesti un pandantiv, iar dincolo de el, urme care duc spre sud. In departare, se ridica fum de la o fortareata mare. Provine de la un foc intretinut, nu de la cladiri in flacari, iar instinctul iti spune ca, daca Malems mai sunt in viata, au fost dusi intr-acolo."},{t="Cuvant pentru Vahlarriel",b="Vahlarriel Demonslayer de la Nijel's Point ar trebui sa vada pandantivul Malem si sa afle despre urmele care duc spre sud."},{t="Ce spun localnicii",b="Vahlarriel este furioasa din cauza intregii situatii. Cei doi Malems fusesera avertizati cat de periculoasa este Desolace, iar acum amandoi au disparut sau, mai rau. Dupa ce aude de urmele care duc spre fortul din apropiere, Vahlarriel spune ca aceasta este cea mai buna pista. Potrivit localnicilor, fortareata este invadata de Burning Blade, orci care s-au pus in slujba fortelor demonice. Nu reprezinta majoritatea Hordei, dar sunt malefici, iar oricine este prins spionandu-i va fi ucis pe loc."}},faq={{q="Ce ai gasit in caruta?",a="O pandantiva si urme care duc spre sud. In departare, se ridica fum de la o fortareata mare.",al={"ce se afla in cufar","indicii despre caruta","pandantivul lui malem"}},{q="Unde duc urmele?",a="Spre sud, catre o fortareata mare. Fumul de deasupra ei provine de la un foc intretinut, nu de la cladiri in flacari, ceea ce sugereaza ca Malems, daca mai sunt in viata, au fost dusi in acea directie.",al={"incotro duc urmele pasilor","unde se afla fortul","directia urmelor"}},{q="Unde se afla Vahlarriel Demonslayer?",a="Vahlarriel Demonslayer se afla la Nijel's Point, in Desolace. Acolo trebuie duse pandantivul si vestile despre urme.",al={"locatia lui Vahlarriel","unde predau pandantivul Malem","locul unde se afla Vahlarriel Demonslayer"}}},fp="19,264,13.261.0,19.118.0,19.448.1,31.99.0,25.174.0,40.108.0"}
P.entries["quest:1466"] = {n="Reagents for Reclaimers Inc.",s="Kreldig Ungor are ultimul dintre obiectele dorite de Leftwitch si recunoaste ca nu e deloc placut si ca va dura mai mult decat celelalte. Totul provine de la demoni: creiere, aripi si fiole cu sange.",h="Kreldig Ungor are ultimul dintre obiectele dorite de Leftwitch si recunoaste ca nu e deloc placut si ca va...",kw={"desolace","sange de doomwarder","creier de felhound","kreldig ungor","leftwitch","mannoroc coven","aripa din Nether","reclaimers inc"},sec={{t="Ultimul de pe lista",b="Kreldig avertizeaza ca ultimul set e o treaba sinistra si se aduna mai greu decat oricare dintre cele de pana acum. Leftwitch vrea trei feluri de componente, cate zece din fiecare. Creierele provin de la felhounds: devoratori de mana, vanatori de mage sau vanatori de ley. Aripile provin de la fecioarele, surorile sau vrajitoarele din Nether. Sangele provine de la capeteniile sau lorzii doomwarder. Kreldig spune ca ar intelege daca ai renunta la aceasta sarcina."},{t="Demoni in Desolace",b="Kreldig nici nu-si daduse seama ca acesti demoni se aflau in Desolace. Din ce a citit, Desolace a apartinut in mare parte centaurilor dupa plecarea night elves, cu ani in urma, iar el se intreaba cum si de ce s-au stabilit demonii aici. Acestia traiesc langa Mannoroc Coven, in sudul regiunii Desolace, dincolo de Kodo Graveyard."}},faq={{q="Cine cere aceste parti demonice?",a="Kreldig Ungor transmite lista lui Leftwitch, iar aceste parti de demon sunt ultimele elemente de pe ea.",al={"cine ti-a dat aceasta misiune","cine vrea partile de demon","cine este Kreldig Ungor"}},{q="Ce creaturi detin obiectele necesare?",a="Creierele de felhound provin de la devoratori de mana, vanatori de magi si vanatori de ley. Aripile provin de la fecioarele, surorile si vrajitoarele Nether. Sangele provine de la capitanii si lorzii doomwarder.",al={"ce lasa creiere de felhound","unde gasesc aripi din Nether","care doomwarders au sange"}},{q="Unde pot fi gasiti acesti demoni?",a="Se aduna langa Mannoroc Coven, la capatul sudic al Desolace, dincolo de Kodo Graveyard.",al={"locatia demonilor","unde este Mannoroc Coven","pe unde cutreiera demonii"}},{q="De ce i se par surprinzatori demonii lui Kreldig?",a="Citise ca centaurii stapaneau Desolace dupa plecarea night elves, cu multi ani in urma, asa ca prezenta demonilor il nedumereste.",al={"de ce sunt demoni in desolace","povestea centaur din desolace"}}},fp="28,188,20.389.0,18.291.0,36.92.0,39.177.0,32.92.0,44.116.0"}
P.entries["quest:1467"] = {n="Reagents for Reclaimers Inc.",s="Kreldig Ungor iti da pachetul lui Leftwitch si te trimite inapoi la Ironforge. Roetten Stonehammer este cel cu care trebuie sa vorbesti despre plata, iar Kreldig promite sa vorbeasca de bine despre tine cand se intoarce acasa.",h="Kreldig Ungor iti da pachetul lui Leftwitch si te trimite inapoi la Ironforge.",kw={"desolace","ironforge","kreldig ungor","pachetul lui leftwitch","reagenti pentru reclaimers inc","roetten stonehammer"},sec={{t="Plata in Ironforge",b="Kreldig spune ca plata ta te asteapta in Ironforge, chiar la Roetten Stonehammer. Roetten se va bucura sa scape de pachetul lui Leftwitch, iar daca i-l predai ar trebui sa primesti ce ti se cuvine. Kreldig se asteapta sa mai ramana putin in Desolace si, odata ajuns acasa, tot intentioneaza sa vorbeasca frumos despre tine."},{t="Multumirile lui Roetten",b="Roetten Stonehammer primeste cu bucurie pachetul lui Leftwitch din Desolace si iti multumeste pentru munca si rapiditatea cu care ai indeplinit-o. Plata ta e pregatita, iar Roetten remarca faptul ca o saptamana grea de munca e intotdeauna bine rasplatita de Reclaimers Inc."}},faq={{q="Cine te trimite inapoi la Ironforge?",a="Kreldig Ungor te trimite inapoi la Ironforge cu pachetul lui Leftwitch dupa ce aduni reactivii.",al={"cel care da misiunea","cine ofera misiunea","cine incepe aceasta misiune"}},{q="Unde trebuie sa ajunga pachetul lui Leftwitch?",a="Ajunge la Roetten Stonehammer in Ironforge.",al={"unde duc pachetul","destinatia pachetului","cine primeste pachetul"}},{q="De ce duci pachetul la Roetten?",a="Kreldig spune ca plata vine chiar de la Roetten, asa ca pachetul trebuie dus la el in Ironforge.",al={"de ce sa duc pachetul","de ce sa-l vizitez pe Roetten"}},{q="A mai ramas Kreldig Ungor in Desolace?",a="Nu pentru mult timp, potrivit lui Kreldig, care tot intentioneaza sa vorbeasca frumos despre tine cand se va intoarce acasa.",al={"pleaca kreldig din desolace","unde se indreapta kreldig"}}},fp="28,189,20.296.0,16.225.1,32.99.0,42.44.0,40.90.0,39.95.0"}
P.entries["quest:1469"] = {n="Rhapsody's Tale",s="Dupa ce Rhapsody Shindigger primeste Kalimdor Kocktail, isi spune in sfarsit povestea zborului alaturi de Brohann Caskbelly. Iti da un Atal'ai Tablet Fragment si iti cere sa-l duci la Brohann, in Stormwind.",h="Dupa ce Rhapsody Shindigger primeste Kalimdor Kocktail, isi spune in sfarsit povestea zborului alaturi de...",kw={"atal'ai","brohann","caskbelly","fragment","Hinterlands","rhapsody","shindigger","stormwind","tablite"},sec={{t="Un fragment pentru Brohann",b="Dupa ce cocktailul isi face efectul, Rhapsody Shindigger incepe in sfarsit sa vorbeasca. Inainte de zbor a baut un butoi intreg de bere tare, iar Brohann l-a urmat pe cer. Ce a pastrat din acea aventura este o amintire troll, un Atal'ai Tablet Fragment, si vrea sa-l duci la Brohann Caskbelly in Stormwind."},{t="Unde s-a incheiat zborul",b="Rhapsody n-a vazut niciun templu din aer. Apoi, putin prea cherchelit, a cazut din sa si s-a prabusit in apa. A fost tras la fund si s-a trezit printre trolls infricosatori, apoi a inotat repede afara, luand cu el un suvenir. Asadar, templul lui Brohann se afla totusi acolo jos."}},faq={{q="Cine primeste Atal'ai Tablet Fragment?",a="Rhapsody cere ca acesta sa fie dus la Brohann Caskbelly in Stormwind.",al={"cui dau fragmentul","locatia lui Brohann","unde trebuie dusa tablita"}},{q="Ce isi aminteste Rhapsody despre zborul alaturi de Brohann?",a="Rhapsody a baut un butoi intreg de bere neagra inainte de zbor, apoi a zburat iute prin cer, cu Brohann in urma lui.",al={"de ce a zburat rhapsody","brohann si rhapsody"}},{q="Ce a fost inainte de acest pas?",a="Rhapsody's Kalimdor Kocktail a venit prima. Rhapsody nu voia sa-si spuna povestea pana cand bautura nu era preparata.",al={"misiunea precedenta","conditie pentru Rhapsody's Tale"}}},fp="15,209,22.278.0,22.259.1,41.67.0,55.112.0,27.105.0"}
P.entries["quest:147"] = {n="Manhunt",s="Marshal Dughan te trimite dupa un intermediar Defias numit Collector, in Elwynn Forest. Collector isi desfasoara activitatea din Brackwell Pumpkin Patch, ocupat de intrusi, si trimite aurul furat din minele padurii in vistieria Brotherhood.",h="Marshal Dughan te trimite dupa un intermediar Defias numit Collector, in Elwynn Forest.",kw={"brackwell pumpkin patch","colectionar","defias","goldshire","vanatoare de oameni","marshal dughan","inel","stonemasons guild"},ang={["class:Rogue"]="Ca Rogue, poti vedea cum activitatea clandestina a lui Collector reflecta extinderea retelei de talhari de drumul mare si hoti de buzunare care prinde radacini in Elwynn Forest.",["faction:Alliance"]="Ca membru Alliance, ajuti la protejarea resurselor locale ale Stormwind. Oprirea lui Collector intrerupe un flux ilegal de aur al regatului, destinat finantarii rebeliunii de langa capitala.",["race:Human"]="Ca human, s-ar putea sa simti greutatea recuperarii inelului zidarului. Acesta aminteste de disputele amare dintre muncitori, care au dezbinat regatul dupa reconstruirea Stormwind."},sec={{t="Dreptate in lanul de dovleci",b="Marshal Dughan te trimite la Brackwell Pumpkin Patch dupa ce se descopera ca gnoll-ii din Elwynn poarta un program pentru ridicarea aurului. Banditii Defias si gnoll-ii au ocupat gospodaria candva linistita. Collector se ascunde printre vrejurile napadite, sustrage minereu din minele regatului si organizeaza transporturi pentru rascoala in crestere."},{t="Sigiliul unui mestesugar",b="Dupa ce Collector este ucis, ii recuperezi inelul si i-l predai lui Marshal Dughan. Marshal este nedumerit: veriga poarta insemnul vechii Stonemasons Guild din Stormwind, nu blazonul unui infractor de rand. Inelul sugereaza ca talharii care sufoca Elwynn Forest sunt mai mult decat niste oportunisti. Unii au fost mestesugari care s-au umplut de amaraciune si au devenit proscrisi dupa ce Stormwind a fost reconstruit."}},faq={{q="Unde il pot gasi pe Collector?",a="The Collector se ascunde la Brackwell Pumpkin Patch, in sud-estul Elwynn Forest, imediat la est de Maclure Vineyards si la nord de hotarul raului.",al={"locatia colectionarului","unde este colectionarul","locul colectionarului"}},{q="De ce fura Collector aur din minele din Elwynn?",a="Collector aduna minereu de contrabanda si taxe de santaj din minele Fargodeep si Jasperlode, infestate de kobold, pentru a finanta operatiunile clandestine ale Defias Brotherhood in tot regatul.",al={"de ce fura aur","minele Defias","ce face colectorul"}},{q="Ce semnificatie are inelul Collector?",a="Inelul apartine vechii Stonemasons Guild, ai carei mesteri au reconstruit Stormwind City dupa First War. Marshal Dughan nu poate explica de ce un hot marunt care lucreaza cu Defias poarta un inel al unei ghilde de mestesugari si spera ca intr-o zi va primi raspuns la aceasta intrebare.",al={"povestea inelului colectionarului","inelul zidarului","ce inseamna inelul"}},{q="Isi da seama Marshal Dughan cine se afla in spatele Brotherhood?",a="Nu imediat. Marshal Dughan recunoaste insemnul mestesugarului de pe inel, dar nu poate explica de ce un hot de rand poarta un sigiliu al breslei mestesugarilor. Conspiratia mai ampla ramane o intrebare fara raspuns in Goldshire.",al={"stie Dughan","reactia lui Dughan","Marshal Dughan si Stonemasons"}},{q="Cine te trimite in aceasta vanatoare?",a="Marshal Dughan, comandantul garnizoanei de la Lion's Pride Inn din Goldshire, iti incredinteaza aceasta sarcina dupa ce recuperezi programul livrarilor Defias.",al={"cine da misiunea vanatoarea de oameni","cine ofera misiunea vanatoarea de oameni","misiunea lui marshal dughan"}},{q="Ce s-a intamplat cu familia Brackwell?",a="Brackwell Pumpkin Patch este in ruina, abandonat de proprietari si ocupat de Rogue Defias, banditi si gnoll Riverpaw care inainteaza prin padurile din sud-est.",al={"povestea lui Brackwell","cine detine plantatia de dovleci","ferma lui Brackwell"}}},fx={["1901992d"]={q="De ce vrea Marshal Dughan sa-l opreasca pe Collector?",a="Aurul jefuit din minele Elwynn este proprietatea regatului Stormwind. Deturnand sistematic aceasta bogatie, Collector jefuieste in mod activ regatul si finanteaza operatiuni ilicite. Marshal Dughan nu poate ingadui hotilor sa prade nestingheriti resursele Coroanei, mai ales cand monedele furate sugereaza existenta unei conspiratii organizate in spatele banditismului local.",al={"de ce sa-l omoram pe Colector","motivul lui Marshal Dughan pentru vanatoarea de oameni","de ce ii pasa lui Dughan de Colector"}},["535c4316"]={q="Cine este Collector si de ce se afla in lanul de dovleci?",a="Collector este un agent care lucreaza cu hotii Defias pentru a aduna si transporta aurul obtinut ilegal din minele din Elwynn. Foloseste abandonatul Brackwell Pumpkin Patch drept ascunzatoare retrasa si asteapta transporturile conform programului de ridicare, inainte de a scoate pe furis bogatiile regatului din padure.",al={"cine este colectionarul","de ce se afla colectionarul la Brackwell Pumpkin Patch","tinta vanatorii de oameni"}},e23a6feb={q="De ce trimite Marshal Dughan un aventurier in locul garzilor din Stormwind?",a="Stormwind City Guard si garnizoana din Goldshire sunt raspandite pana la limita in Elwynn Forest, coplesite de incursiunile gnollilor, de infestarea minelor cu koboldi si de banditii Defias care misuna pretutindeni. Dughan pur si simplu nu are soldati de rezerva pe care sa-i trimita intr-o vanatoare de oameni la o plantatie izolata de dovleci, asa ca trebuie sa se bazeze pe aventurieri capabili si de incredere.",al={"de ce are nevoie dughan de mine","de ce sa trimita aventurieri la vanatoarea de oameni","de ce nu-i omoara garzile pe colector"}}},fp="7,224,28.325.0,17.371.1,31.145.0,55.184.0,49.271.1,61.207.1,30.143.0,38.176.0"}
